static int guards_state = -1;
static int guards_on(void) { if (guards_state < 0) { const char *e = getenv("LLMS_DS4_GUARDS"); guards_state = e && *e && *e != '0'; } return guards_state; }
void llms_guard_fail(const char *what) {
    if (!guards_on()) return;
    const char *dn = getenv("DS4_METAL_DENSE_SOURCE"), *mi = getenv("DS4_METAL_DSV4_MISC_SOURCE"), *mo = getenv("DS4_METAL_MOE_SOURCE"), *hc = getenv("DS4_METAL_DSV4_HC_SOURCE");
    fprintf(stderr, "llms GUARDS FATAL: %s -- sources: dense %s | misc %s | moe %s | hc %s. A switch that is set cannot run as set; exiting 3 "
                    "(LLMS_DS4_GUARDS=0 runs on with it off)\n", what, dn ? dn : "(built-in)", mi ? mi : "(built-in)", mo ? mo : "(built-in)", hc ? hc : "(built-in)");
    fflush(stderr); exit(3);
}
int llms_strict_after(int printed, const char *what) { llms_guard_fail(what); return printed; }
static struct { const char *key; const char *kind; int hit; } srckey_hits[128]; static int srckey_hit_count; static volatile int srckey_lock; static uint64_t srckey_calls;
static const char *srckey_kind(const char *src) {
    static const char *const nm[6] = {"DS4_METAL_DENSE_SOURCE", "DS4_METAL_DSV4_MISC_SOURCE", "DS4_METAL_MOE_SOURCE", "DS4_METAL_DSV4_HC_SOURCE", "DS4_METAL_NORM_SOURCE", "DS4_METAL_DSV41_SOURCE"};
    static const char *const sh[6] = {"dense", "misc", "moe", "hc", "norm", "dsv41"};
    if (!src) return "unset";
    for (int i = 0; i < 6; i++) { const char *v = getenv(nm[i]); if (v && !strcmp(v, src)) return sh[i]; }
    return "other";
}
static void report_srckeys(void) {
    fprintf(stderr, "llms source-name decisions (features keyed on a source FILE NAME):");
    for (int i = 0; i < srckey_hit_count; i++) fprintf(stderr, " %s@%s=%s", srckey_hits[i].key, srckey_hits[i].kind, srckey_hits[i].hit ? "yes" : "NO");
    fprintf(stderr, " (%llu calls)\n", (unsigned long long)srckey_calls);
}
const char *llms_srckey(const char *src, const char *key) {
    const char *r = src ? strstr(src, key) : NULL;
    if (!guards_on()) return r;
    __atomic_fetch_add(&srckey_calls, 1, __ATOMIC_RELAXED); const char *kind = srckey_kind(src);
    while (__atomic_exchange_n(&srckey_lock, 1, __ATOMIC_ACQUIRE)) { }
    int i = 0; for (; i < srckey_hit_count; i++) if (!strcmp(srckey_hits[i].key, key) && srckey_hits[i].kind == kind) break;
    if (i == srckey_hit_count && srckey_hit_count < 128) { srckey_hits[i].key = key; srckey_hits[i].kind = kind; srckey_hits[i].hit = r != NULL; if (!srckey_hit_count++) atexit(report_srckeys); }
    __atomic_store_n(&srckey_lock, 0, __ATOMIC_RELEASE);
    return r;
}
