    for (int i = 0; i < dup_name_count; i++) if (!strcmp(dup_names[i], name)) {   /* llms DUP_KERNELS */
        int seen = 0; for (int k = 0; k < dup_pipeline_count; k++) seen |= dup_pipelines[k] == pso;
        if (!seen && dup_pipeline_count < 64) { dup_pipeline_group[dup_pipeline_count] = dup_name_group[i]; dup_pipelines[dup_pipeline_count++] = pso; }   /* llms DUPG */
    }
    for (int i = 0; i < skip_name_count; i++) if (!strcmp(skip_names[i], name)) {
        for (int k = 0; k < skip_pipeline_count; k++) if (skip_pipelines[k] == pso) return;
        if (skip_pipeline_count < 64) { skip_pipeline_group[skip_pipeline_count] = skip_name_group[i]; skip_pipelines[skip_pipeline_count++] = pso; }   /* llms SKIPG */
