        if (substream_count) { fprintf(stderr, "llms: substreams %d (the batch encoder with %d compute substreams; the verify attention's q / kv / indexer chains on streams 1-3, joined by progress tags)\n", substream_count, substream_count);
            atexit_b(^{ fprintf(stderr, "llms substreams: %llu encoders, %llu setSubstream, %llu signals, %llu waits, %llu waits skipped (tag signalled on an earlier encoder of the same generation), %llu FALLBACKS (tag not signalled in this generation: the encoder was closed instead -- a plumbing error if nonzero)\n",
                                (unsigned long long)substream_encoders, (unsigned long long)substream_sets, (unsigned long long)substream_signals, (unsigned long long)substream_waits, (unsigned long long)substream_waits_skipped, (unsigned long long)substream_fallbacks); }); } }
