        if (dsp_ss_state) { fprintf(stderr, "llms: dsp ss (the drafter step's paired chains on 2 compute substreams, joined by progress tags)\n");
            atexit_b(^{ fprintf(stderr, "llms dsp ss: %llu drafter cones; substream encoders %llu, setSubstream %llu, signals %llu, waits %llu, skipped %llu, FALLBACKS %llu\n",
                                (unsigned long long)dsp_ss_cones, (unsigned long long)substream_encoders, (unsigned long long)substream_sets, (unsigned long long)substream_signals,
                                (unsigned long long)substream_waits, (unsigned long long)substream_waits_skipped, (unsigned long long)substream_fallbacks); }); } }
