/* llms VSS (apply_vss.py): the verify's FFN -- the router chain and the shared expert -- on two compute substreams; off unless LLMS_DS4_VSS is set */
static int vss_state = -1; static uint64_t vss_cones;   /* llms SP_BCTX: vss_mode moved */
static int vss_on(void) {
    if (vss_state < 0) { const char *e = getenv("LLMS_DS4_VSS"); vss_state = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? 3 : 2;
        if (vss_state) { fprintf(stderr, vss_state == 3 ? "llms: vss -- CANARY: the verify FFN's shared expert skips its down projection\n" : "llms: vss (the verify FFN's router chain and shared expert on 2 compute substreams, joined before the routed call)\n");
            atexit_b(^{ fprintf(stderr, "llms vss: %llu verify FFN cones; substream encoders %llu, setSubstream %llu, signals %llu, waits %llu, skipped %llu, FALLBACKS %llu\n",
                                (unsigned long long)vss_cones, (unsigned long long)substream_encoders, (unsigned long long)substream_sets, (unsigned long long)substream_signals,
                                (unsigned long long)substream_waits, (unsigned long long)substream_waits_skipped, (unsigned long long)substream_fallbacks); }); } }
    return vss_state;
}
int ds4_gpu_llms_vss_on(void) { return vss_on() > 0 && !llms_alt_off("vss") ? vss_on() : 0; }   /* 2 on, 3 canary; ALT vss */
static uint64_t vss_late_joins;   /* llms SP_BCTX: vss_late_tag moved */   /* llms VSS3: set by ds4.c, consumed (joined) just before the ED path's doorbell wait */
void ds4_gpu_llms_vss_late(unsigned tag) { vss_late_tag = tag; }
unsigned ds4_gpu_llms_vss_late_pending(void) { return vss_late_tag; }
void ds4_gpu_llms_vss_want(int w) {   /* the verify FFN's cone: closing the open encoder makes the factory create the right kind next */
    if (vss_on() <= 0) return;
