    else { substream_current = 0u; if (g_batch_enc) ds4_gpu_close_batch_encoder(); substreams_wanted = 0; vss_mode = 0; }   /* the close is the full join */
}
static int substreams_n(void) { return vss_mode ? 2 : dsp_ss_mode ? dsp_ss_on() : substreams_on(); }   /* llms DSP_SS: the count the open cone uses; llms VSS: 2 inside the verify FFN's cone */
int ds4_gpu_llms_dsp_ss_on(void) { return dsp_ss_on() > 0; }
void ds4_gpu_llms_dsp_ss_want(int w) {   /* llms DSP_SS: the drafter's cone; closing the open encoder makes the factory create the right kind next */
    if (dsp_ss_on() <= 0) return;
