    else { substream_current = 0u; if (g_batch_enc) ds4_gpu_close_batch_encoder(); substreams_wanted = 0; dsp_ss_mode = 0; }   /* the close is the full join */
}
static void start_ane_preload(void);   /* llms ANE_PRELOAD: defined beside the ANE init, called from ds4_gpu_init's end */
static void start_ane_t12_bg(void);   /* llms ANE_T12_BG: defined beside start_ane_preload, called from ds4_gpu_init's end */
static void start_q4l_prefetch(void);   /* llms Q4L_PREFETCH: defined beside start_ane_t12_bg, called from ds4_gpu_init's end */
static void start_q4l_early(void);   /* llms Q4L_RESIDENCY: defined after load_dense4_table, called from ds4_gpu_init's end */
static void load_dense4_table(void);   /* llms Q4L_RESIDENCY: forward declaration for start_q4l_early's caller */
static void bind_rows_bytes(id<MTLComputeCommandEncoder> enc, const void *p, NSUInteger bytes, NSUInteger index);   /* llms ROWS_CAP4: defined beside the v41 rows binder */
static inline int prepare_dispatch(id<MTLComputeCommandEncoder> e) {   /* llms BARSWZ (apply_barswz.py): the per-dispatch modes, run by the swizzled dispatch methods (install_dispatch_hooks installs them while a mode is on); 0 = skip */
    if (skip_kernels_on && skip_this_dispatch()) { skipped_dispatches++; return 0; }   /* llms SKIP_KERNELS: no barrier, no dispatch */
    if (gpu_noop_count > 0) { gpu_noop_skips++; return 0; }
    if (concurrent_encoder && e == g_batch_enc) {
        if (conc_skip_first == 1) { conc_skip_first = 2; conc_barriers_skipped++; }   /* only the op's FIRST dispatch goes without */
        else { [e memoryBarrierWithScope:MTLBarrierScopeBuffers]; conc_barriers++; }
    }
    if (substreams_active && e == g_batch_enc && substream_current != substream_set) { ((void(*)(id, SEL, unsigned))objc_msgSend)(e, sel_registerName("setSubstream:"), substream_current); substream_set = substream_current; substream_sets++; }   /* llms SUBSTREAMS */
    return 1;
}
/* llms SP_BCTX: moved to struct sp_bctx */ /* g_batch_has_work */
void ds4_gpu_llms_ss(int s) { substream_current = (substreams_n() > 0 && s > 0 && s < substreams_n()) ? (unsigned)s : 0u; }   /* llms DSP_SS: substreams_n */   /* llms SUBSTREAMS: the stream of the next dispatches */
void ds4_gpu_llms_ss_want(int w) { substreams_wanted = w; if (!w) substream_current = 0u; else if (substreams_n() > 0 && g_batch_enc && !substreams_active) ds4_gpu_close_batch_encoder(); }   /* llms SUBSTREAMS v6: the cone begins -- a plain encoder still open is closed so the factory creates the substream kind (gates 3-4: 0 substream encoders, the encoder was already open); the cone ends -- the next encoder is plain */
void ds4_gpu_llms_ss_signal(unsigned tag) {   /* on the current stream, after its last dispatch */
    if (!substreams_active || !g_batch_enc) return;
    if (substream_current != substream_set) { ((void(*)(id, SEL, unsigned))objc_msgSend)(g_batch_enc, sel_registerName("setSubstream:"), substream_current); substream_set = substream_current; substream_sets++; }
    ((void(*)(id, SEL, unsigned))objc_msgSend)(g_batch_enc, sel_registerName("signalProgress:"), tag); substream_tag_generation[tag & 511u] = substream_generation; substream_tag_serial[tag & 511u] = substream_encoder_serial; substream_signals++;
