    if (substream_tag_serial[tag & 511u] < substream_encoder_serial) { substream_waits_skipped++; return; }   /* signalled on an earlier encoder of this generation: the boundary joined */
    if (substream_current != substream_set) { ((void(*)(id, SEL, unsigned))objc_msgSend)(g_batch_enc, sel_registerName("setSubstream:"), substream_current); substream_set = substream_current; substream_sets++; }
    ((void(*)(id, SEL, unsigned))objc_msgSend)(g_batch_enc, sel_registerName("waitForProgress:"), tag); substream_waits++;
