/* ---- Encoder timeline diagnostic (DS4_METAL_ENCODER_TIMELINE=<file>) ----
 * Gives every batch dispatch group its own compute pass with stage-boundary
 * GPU timestamps, so one decode token can be read as a per-kernel GPU
 * timeline (durations and the gaps between them) without ending command
 * buffers. Pass boundaries add a little serialization, so absolute numbers
 * are an upper bound; the anatomy is what this exists for. Off by default. */
#define DS4_TIMELINE_NAME_MAX 256   /* llms TL_NAMES (apply_tl_names.py): was 80 -- the attention output encoder's joined names were cut at its body */
#define DS4_TIMELINE_SAMPLES_PER_BUFFER 4096
typedef struct {
    uintptr_t caller;
    uint32_t n_dispatch;
    uint32_t tg[3];
    uint32_t tpt[3];
    char kernel[DS4_TIMELINE_NAME_MAX];
    uint32_t phase, pos, rows; uint64_t inv;   /* llms TL_PHASE (apply_tl_phase.py) */
    uintptr_t enc;   /* apply_tl_bind.py: the encoder this record samples, so the hooks label their own record */
    uint32_t tlp_sb, tlp_slot; uint64_t tlp_gen; int tlp;   /* llms TL_POOL: the pool buffer, sample index and ring position of this record */
} ds4_timeline_rec;
static int timeline_sample_wanted, timeline_sample_current;   /* llms TL_CBONLY 3: sample only the doorbell wait dispatches (DS4_METAL_TIMELINE_SAMPLE_DBWAIT) */
static int timeline_cb_only(void) {   /* llms TL_CBONLY (apply_tl_cbonly.py) */
    static int v = -1; if (v < 0) { const char *e = getenv("DS4_METAL_TIMELINE_CB_ONLY"); v = e && *e && *e != '0';
        if (v) fprintf(stderr, "llms: timeline cb-only (plain encoders, no per-encoder samples; P lines tag the command buffers by step, B lines carry their GPU spans)\n"); } return v; }
uint32_t timeline_phase, timeline_position, timeline_rows; uint64_t timeline_phase_changes;   /* llms TL_PHASE: the owner's phase / position / rows at encoder creation */
static volatile uint32_t prefill_since_quiesce;   /* llms Z9 JIT2: a prefill phase was entered since the last quiesce */
void ds4_gpu_llms_tl_phase(uint32_t phase, uint32_t pos, uint32_t rows) { if (phase == 2u || phase == 3u) prefill_since_quiesce = 1u; if (phase != timeline_phase) timeline_phase_changes++; timeline_phase = phase; timeline_position = pos; timeline_rows = rows; }
uint32_t ds4_gpu_llms_tl_phase_get(uint32_t *pos, uint32_t *rows) { if (pos) *pos = timeline_position; if (rows) *rows = timeline_rows; return timeline_phase; }
static int has_kernel(const char *name);   /* llms KR8: defined below */
static int kr8_state = -1; static uint64_t kr8_mv_calls, kr8_ao_calls;   /* llms KR8 (apply_kr8.py) */
static uint32_t kr8_rows_max(void) {   /* llms KR8: the most rows a VERIFY matvec / attention output takes in one k-row pass (8 with the switch, else 4) */
    if (kr8_state < 0) {
        const char *e = getenv("LLMS_DS4_KR8"); kr8_state = e && *e && *e != '0';
        if (kr8_state) {
            char kn[64];
            kr8_state = atoi(e) >= 2 ? 2 : 1;   /* llms KR8 v2: 1 = the dense matvecs + the attention output, 2 = + the HC rows */
            for (int k = 5; kr8_state && k <= 8; k++) {
                const char *fm[12] = { "kernel_llms_q4l_mv_k%d_r4_b", "kernel_llms_q4l_mv_k%d_r4_f", "kernel_llms_q4l_mv_kg%d", "kernel_llms_q4l_mv_k%d_r4_bxh",
                    "kernel_llms_q4l_mv_k%d_r4_fxh", "kernel_llms_q4l_mv_k%d_r4_bxh_rsg4", "kernel_llms_q4l_mv_k%d_r4_bxh_rsg8", "kernel_llms_q4l_mv_k%d_r4_fxh_rsg4",
                    "kernel_llms_q4l_mv_k%d_r4_fxh_rsg8", "kernel_llms_q4l_mv_kgxh%d", "kernel_llms_q4l_mv_k%d_r4_bxh", "kernel_llms_q4l_mv_k%d_r4_fxh" };
                const int saved = kr8_state; kr8_state = saved;
                for (int i = 0; kr8_state && i < 12; i++) { snprintf(kn, sizeof kn, fm[i], k);
                    if (!has_kernel(kn)) { fprintf(stderr, "llms: LLMS_DS4_KR8 ignored -- the dense source lacks %s\n", kn); kr8_state = 0; } }
            }
            if (kr8_state) { fprintf(stderr, "llms: kr8 v2 level %d (5..8-row verify matvecs and attention outputs in one pass on the TUNED k5..k8 bodies -- half x, RSG, grouped half heads%s; ALT kr8 / kr8hx / kr8hc)\n", kr8_state, kr8_state >= 2 ? ", + the HC rows" : "");
                             atexit_b(^{ fprintf(stderr, "llms kr8: %llu matvecs and %llu attention outputs at 5..8 rows in one pass\n", (unsigned long long)kr8_mv_calls, (unsigned long long)kr8_ao_calls); }); }
        }
    }
    return (kr8_state && timeline_phase == 1u && !llms_alt_off("kr8")) ? 8u : 4u;
}
uint32_t ds4_gpu_llms_kr8_rows(void) { return kr8_rows_max() >= 8u && kr8_state >= 2 && !llms_alt_off("kr8hc") ? 8u : 4u; }   /* llms KR8B / KR8 v2: the HC sites only at level 2 */
static const char *kr8_f16k_name(uint32_t rows, int isbf16) {   /* llms KR8C: the k-row bf16 / f16 body for 5..8 verify rows, or NULL (off, or not in the source) */
    static int have[2][9]; static int tried[2][9];
    static const char *nb[9] = { 0, 0, 0, 0, 0, "kernel_llms_bf16_mv_k5_r2", "kernel_llms_bf16_mv_k6_r2", "kernel_llms_bf16_mv_k7_r2", "kernel_llms_bf16_mv_k8_r2" };
    static const char *nf[9] = { 0, 0, 0, 0, 0, "kernel_llms_f16_mv_k5_r2", "kernel_llms_f16_mv_k6_r2", "kernel_llms_f16_mv_k7_r2", "kernel_llms_f16_mv_k8_r2" };
    if (rows < 5u || rows > 8u || kr8_rows_max() < rows || llms_alt_off("kr8rt")) return NULL;
    const int b = isbf16 ? 1 : 0; const char *n = b ? nb[rows] : nf[rows];
    if (!tried[b][rows]) { tried[b][rows] = 1; have[b][rows] = has_kernel(n); if (!have[b][rows]) fprintf(stderr, "llms kr8c: %s not in the dense source -- the old kernel stays\n", n); }
    return have[b][rows] ? n : NULL;
}
static int kr8_hx_name(const char *name) {   /* llms KR8 v2: a k5..k8 dense kernel name in a verify with KR8 on -> the 2..4-row half-x / RSG rewrites apply */
    return !strncmp(name, "kernel_llms_q4l_mv_k", 20) && name[20] >= '5' && name[20] <= '8' && name[21] == '_' && kr8_rows_max() >= (uint32_t)(name[20] - '0') && !llms_alt_off("kr8hx");
}

@interface DS4TimelineBatch : NSObject {
@public
    NSMutableArray<id<MTLCounterSampleBuffer>> *samples;
    ds4_timeline_rec *recs;
    uint32_t count;
    uint32_t cap;
    uint64_t seq;
    __unsafe_unretained id<MTLCommandBuffer> cb;   /* llms TL_ATTACH: the command buffer this batch samples */
}
@end
@implementation DS4TimelineBatch
- (void)dealloc { free(recs); }
@end

static BOOL g_timeline_enabled;
static FILE *g_timeline_file;
static pthread_mutex_t g_timeline_mutex = PTHREAD_MUTEX_INITIALIZER;
static DS4TimelineBatch *g_timeline_batch;
static uint64_t g_timeline_seq;
static NSMutableDictionary<NSNumber *, NSString *> *g_timeline_pso_names;
static id<MTLCounterSet> g_timeline_counter_set;
/* llms TL_POOL (apply_tlp.py): at most 32 counter sample buffers can be live (csb_probe.m); one per batch failed after ~32 batches in flight. 24 buffers allocated once, a ring of encoder slots shared by all batches. Adopted; the switch removed 10-27 (a failed buffer still turns the pool off). */
#define TIMELINE_POOL_BUFFERS 24u
#define TIMELINE_POOL_SAMPLES_PER_BUFFER (DS4_TIMELINE_SAMPLES_PER_BUFFER / 2u)
#define TIMELINE_POOL_SLOTS (TIMELINE_POOL_BUFFERS * TIMELINE_POOL_SAMPLES_PER_BUFFER)
static id<MTLCounterSampleBuffer> timeline_pool_buffers[TIMELINE_POOL_BUFFERS]; static int timeline_pool_state = -1; static uint64_t timeline_pool_next, timeline_pool_stale;
static int timeline_pool_on(void) {
    if (timeline_pool_state < 0) {
        timeline_pool_state = 1;
        {
            for (uint32_t i = 0; i < TIMELINE_POOL_BUFFERS; i++) {
                MTLCounterSampleBufferDescriptor *d = [MTLCounterSampleBufferDescriptor new];
                d.counterSet = g_timeline_counter_set; d.storageMode = MTLStorageModeShared; d.sampleCount = DS4_TIMELINE_SAMPLES_PER_BUFFER;
                NSError *error = nil; timeline_pool_buffers[i] = [g_device newCounterSampleBufferWithDescriptor:d error:&error];
                if (!timeline_pool_buffers[i]) { fprintf(stderr, "llms tl pool: buffer %u failed: %s -- pool off\n", i, [[error localizedDescription] UTF8String]); timeline_pool_state = 0; break; }
            }
            if (timeline_pool_state) { fprintf(stderr, "llms: tl pool (%u counter sample buffers, %u encoder slots in a ring)\n", TIMELINE_POOL_BUFFERS, TIMELINE_POOL_SLOTS);
                atexit_b(^{ fprintf(stderr, "llms tl pool: %llu slots taken, %llu records stale at resolve\n", (unsigned long long)timeline_pool_next, (unsigned long long)timeline_pool_stale); }); }
        }
    }
    return timeline_pool_state;
}
static BOOL g_timeline_encoder_hooked;

static void ds4_gpu_timeline_note_pso_name(id pso, NSString *name) {
    { static int pipe_info_state = -1; if (pipe_info_state < 0) { const char *e = getenv("LLMS_DS4_PIPE_INFO"); pipe_info_state = e && *e && *e != '0'; }   /* llms PIPE_INFO (apply_ds4_pipe_info.py) */
      if (pipe_info_state && pso && name) { id<MTLComputePipelineState> p_ = (id<MTLComputePipelineState>)pso;
          fprintf(stderr, "llms pipe: %s max_threads %lu width %lu static_tg_mem %lu\n", [name UTF8String], (unsigned long)[p_ maxTotalThreadsPerThreadgroup],
                  (unsigned long)[p_ threadExecutionWidth], (unsigned long)[p_ staticThreadgroupMemoryLength]); } }
    if (!g_timeline_enabled || !pso || !name) return;
    pthread_mutex_lock(&g_timeline_mutex);
    if (!g_timeline_pso_names) g_timeline_pso_names = [NSMutableDictionary dictionary];
    g_timeline_pso_names[@((uintptr_t)pso)] = name;
    pthread_mutex_unlock(&g_timeline_mutex);
}

@interface NSObject (DS4TimelineSwizzle)
- (id)ds4_tl_newComputePipelineStateWithFunction:(id<MTLFunction>)fn
                                            error:(NSError * __autoreleasing *)error NS_RETURNS_RETAINED;
- (id)ds4_tl_newComputePipelineStateWithDescriptor:(MTLComputePipelineDescriptor *)descriptor
                                            options:(MTLPipelineOption)options
                                         reflection:(MTLAutoreleasedComputePipelineReflection *)reflection
                                              error:(NSError * __autoreleasing *)error NS_RETURNS_RETAINED;
- (void)ds4_tl_setComputePipelineState:(id<MTLComputePipelineState>)pso;
- (void)ds4_tl_dispatchThreadgroups:(MTLSize)tg threadsPerThreadgroup:(MTLSize)tpt;
- (void)ds4_tl_dispatchThreads:(MTLSize)threads threadsPerThreadgroup:(MTLSize)tpt;
@end

/* apply_tl_bind.py: the record of THIS encoder (the newest whose enc matches, scanning back up to 64); NULL when none matches (21:0x: no fallback) */
static ds4_timeline_rec *ds4_gpu_timeline_rec_for(id self_enc) {
    DS4TimelineBatch *b = g_timeline_batch;
    if (!b || b->count == 0) return NULL;
    const uintptr_t key = (uintptr_t)self_enc; const uint32_t n = b->count;
    for (uint32_t i = 0; i < 64u && i < n; i++) { ds4_timeline_rec *r = &b->recs[n - 1u - i]; if (r->enc == key) return r; }
    return NULL;   /* an encoder without a record of its own (keepbusy's, or one made outside the timeline) labels nothing: its dispatches were never sampled */
}

@implementation NSObject (DS4TimelineSwizzle)
- (id)ds4_tl_newComputePipelineStateWithFunction:(id<MTLFunction>)fn
                                            error:(NSError * __autoreleasing *)error {
    id pso = [self ds4_tl_newComputePipelineStateWithFunction:fn error:error];
    ds4_gpu_timeline_note_pso_name(pso, [fn name]);
    return pso;
}
- (id)ds4_tl_newComputePipelineStateWithDescriptor:(MTLComputePipelineDescriptor *)descriptor
                                            options:(MTLPipelineOption)options
                                         reflection:(MTLAutoreleasedComputePipelineReflection *)reflection
                                              error:(NSError * __autoreleasing *)error {
    id pso = [self ds4_tl_newComputePipelineStateWithDescriptor:descriptor
                                                        options:options
                                                     reflection:reflection
                                                          error:error];
    ds4_gpu_timeline_note_pso_name(pso, [[descriptor computeFunction] name]);
    return pso;
}
char timeline_shape_tag[40];   /* llms TL_SHAPES: the pending shape tag for the next named record */
static uint64_t sp_tiles_only_k(void) { static long long v = -1; if (v < 0) { const char *e = getenv("LLMS_DS4_SP_TILES_ONLYK"); v = e && *e ? atoll(e) : 0; if (v) fprintf(stderr, "llms: sp tiles onlyk %lld (the lift applies to in_dim == %lld only)\n", v, v); } return (uint64_t)v; }   /* llms SP_TILES_ONLYK (apply_sp_tiles_onlyk.py) */
static int timeline_shapes_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("LLMS_DS4_TL_SHAPES"); on = e && *e && *e != '0'; if (on) fprintf(stderr, "llms: tl shapes (the dense Q4 GEMM passes tagged @K_R_C in the encoder timeline)\n"); } return on; }
- (void)ds4_tl_setComputePipelineState:(id<MTLComputePipelineState>)pso {
    [self ds4_tl_setComputePipelineState:pso];
    ds4_timeline_rec *rec = ds4_gpu_timeline_rec_for(self);   /* apply_tl_bind.py */
    if (!rec) return;
    NSString *name = nil;
    pthread_mutex_lock(&g_timeline_mutex);
    if (g_timeline_pso_names) name = g_timeline_pso_names[@((uintptr_t)pso)];
    pthread_mutex_unlock(&g_timeline_mutex);
    const char *cname = name ? [name UTF8String] : "?";
    const char *shape_tag_now = timeline_shape_tag[0] ? timeline_shape_tag : "";   /* llms TL_SHAPES (apply_tl_shapes.py): the q4g site's shape tag, consumed once */
    if (rec->kernel[0] == '\0') {
        snprintf(rec->kernel, sizeof(rec->kernel), "%s%s", cname, shape_tag_now); timeline_shape_tag[0] = 0;
    } else {   /* llms TL_NAMES: skip only an EXACT component already held (the substring test hid k2_r4_f inside k2_r4_fxh); a name that does not fit ends '+...' */
