/* llms STARTUP_LOG (apply_startup_log.py): ms since the image loaded at each startup step, once per label; off unless set */
static uint64_t startup_t0;
__attribute__((constructor)) static void startup_constructor(void) { startup_t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); }
void ds4_gpu_llms_startup_mark(const char *label) {
    static int on = -1; if (on < 0) { const char *e = getenv("LLMS_DS4_STARTUP_LOG"); on = e && *e && *e != '0'; }
    if (!on || !label) return;
    static const char *seen[96]; static int nseen; static pthread_mutex_t label_seen_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&label_seen_mutex); for (int i = 0; i < nseen; i++) if (seen[i] == label) { pthread_mutex_unlock(&label_seen_mutex); return; }
    if (nseen < 96) seen[nseen++] = label; pthread_mutex_unlock(&label_seen_mutex);
    fprintf(stderr, "llms startup: %8.1f ms %s (%s thread)\n", (double)(clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - startup_t0) * 1e-6, label, pthread_main_np() ? "main" : "other");
}
/* llms PIPE_CENSUS (apply_pipe_census.py): creation times of pipelines and functions; off unless LLMS_DS4_PIPE_CENSUS */
static double pipeline_creation_ms, function_creation_ms, creation_ms_by_phase[4]; static uint64_t pipelines_created, functions_created, creations_by_phase[4];
static pthread_mutex_t pipeline_census_mutex = PTHREAD_MUTEX_INITIALIZER;
static uint32_t pipeline_census_phase(void);
double ds4_gpu_llms_pipe_ms(void) { pthread_mutex_lock(&pipeline_census_mutex); const double v = pipeline_creation_ms + function_creation_ms; pthread_mutex_unlock(&pipeline_census_mutex); return v; }
static double monotonic_ms(void) { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec * 1e3 + ts.tv_nsec / 1e6; }
static void note_pipeline_creation(int is_fn, double ms, NSString *name) {
    const uint32_t ph = pipeline_census_phase() & 3u;
    pthread_mutex_lock(&pipeline_census_mutex);
    if (is_fn) { function_creation_ms += ms; functions_created++; } else { pipeline_creation_ms += ms; pipelines_created++; }
    creation_ms_by_phase[ph] += ms; creations_by_phase[ph]++;
    pthread_mutex_unlock(&pipeline_census_mutex);
    if (ms > 5.0) fprintf(stderr, "llms pipe slow: %s %s %.1f ms phase %u\n", is_fn ? "function" : "pipeline", name ? [name UTF8String] : "?", ms, ph);
}
/* llms CFLAGS (apply_cflags.py): ISA_ARCHIVE / TG_CENSUS names / TGMULT, on the PIPE_CENSUS creation swizzles */
static id<MTLBinaryArchive> pipeline_archive; static uint32_t pipeline_archive_count, pipeline_archive_failures; static int promise_threadgroup_multiple;
static NSMutableDictionary<NSNumber *, NSString *> *pipeline_names; static os_unfair_lock pipeline_names_lock = OS_UNFAIR_LOCK_INIT;
static NSDictionary<NSString *, NSNumber *> *census_clean_pipelines, *census_fixed_pipelines;   /* llms CFLAGS2: from a tg_census.txt -- clean: every row a multiple of 32; fixed: one size */
static NSDictionary<NSString *, NSNumber *> *read_threadgroup_census(const char *path, int want_fixed) {
    NSString *t = [NSString stringWithContentsOfFile:[NSString stringWithUTF8String:path] encoding:NSUTF8StringEncoding error:nil]; if (!t) return nil;
    NSMutableDictionary *ok = [NSMutableDictionary new], *bad = [NSMutableDictionary new];
    for (NSString *l in [t componentsSeparatedByString:@"\n"]) {
        NSArray<NSString *> *f = [l componentsSeparatedByString:@" "]; if (f.count < 6) continue;
        const long mn = f[2].integerValue, mx = f[3].integerValue, b = f[4].integerValue, be = f[5].integerValue; NSString *n = f[0];
        const int good = want_fixed ? (mn == mx && mx > 0) : (b == 0 && be == 0 && (mn & 31) == 0 && (mx & 31) == 0);
        if (!good || bad[n] || (ok[n] && want_fixed && [ok[n] longValue] != mx)) { bad[n] = @1; [ok removeObjectForKey:n]; continue; }
        ok[n] = @(mx);
    }
    return ok;
}
static MTLComputePipelineDescriptor *pipeline_promises_descriptor(id<MTLFunction> fn, MTLComputePipelineDescriptor *d) {   /* the per-pipeline promises, or nil when none applies */
    NSString *n = fn ? fn.name : d.computeFunction.name; const int mul = promise_threadgroup_multiple == 1 || (census_clean_pipelines && census_clean_pipelines[n]);
    NSNumber *mt = census_fixed_pipelines ? census_fixed_pipelines[n] : nil;
    if (!mul && !mt) return nil;
    MTLComputePipelineDescriptor *o = d ? [d copy] : [MTLComputePipelineDescriptor new]; if (!d) o.computeFunction = fn;
    if (mul) o.threadGroupSizeIsMultipleOfThreadExecutionWidth = YES;
    if (mt) o.maxTotalThreadsPerThreadgroup = (NSUInteger)mt.unsignedIntegerValue;
    return o;
}
static void capture_pipeline(id p, id<MTLFunction> fn, MTLComputePipelineDescriptor *d) {
    if (!p) return;
    id<MTLFunction> f = fn ? fn : d.computeFunction;
    note_skip_pipeline((__bridge const void *)p, f.name ? f.name.UTF8String : NULL);   /* llms SKIP_KERNELS */
    if (pipeline_names) { os_unfair_lock_lock(&pipeline_names_lock); pipeline_names[@((uintptr_t)(__bridge void *)p)] = f.name ?: @"?"; os_unfair_lock_unlock(&pipeline_names_lock); }
