        MTLComputePipelineDescriptor *dd = d;
        if (!dd) { dd = [MTLComputePipelineDescriptor new]; dd.computeFunction = fn; dd.threadGroupSizeIsMultipleOfThreadExecutionWidth = promise_threadgroup_multiple ? YES : NO; }
        NSError *e = nil; os_unfair_lock_lock(&pipeline_names_lock);
        if ([pipeline_archive addComputePipelineFunctionsWithDescriptor:dd error:&e]) pipeline_archive_count++;
        else if (!pipeline_archive_failures++) fprintf(stderr, "llms isa archive: add failed for %s: %s\n", f.name.UTF8String, e ? e.localizedDescription.UTF8String : "?");
        os_unfair_lock_unlock(&pipeline_names_lock);
