}
@interface NSObject (LLMSPipeCensus)
- (id)llms_pc_newComputePipelineStateWithFunction:(id<MTLFunction>)fn error:(NSError * __autoreleasing *)error NS_RETURNS_RETAINED;
- (id)llms_pc_newComputePipelineStateWithDescriptor:(MTLComputePipelineDescriptor *)d options:(MTLPipelineOption)o reflection:(MTLAutoreleasedComputePipelineReflection *)r error:(NSError * __autoreleasing *)error NS_RETURNS_RETAINED;
- (id)llms_pc_newFunctionWithName:(NSString *)name NS_RETURNS_RETAINED;
- (id)llms_pc_newFunctionWithName:(NSString *)name constantValues:(MTLFunctionConstantValues *)cv error:(NSError * __autoreleasing *)error NS_RETURNS_RETAINED;
@end
@implementation NSObject (LLMSPipeCensus)
- (id)llms_pc_newComputePipelineStateWithFunction:(id<MTLFunction>)fn error:(NSError * __autoreleasing *)error {
    const double t0 = monotonic_ms(); id p;
    MTLComputePipelineDescriptor *cd = (promise_threadgroup_multiple || census_fixed_pipelines) ? pipeline_promises_descriptor(fn, nil) : nil;   /* llms CFLAGS2: per-pipeline promises (the swizzled name reaches the original) */
    if (cd) p = [self llms_pc_newComputePipelineStateWithDescriptor:cd options:MTLPipelineOptionNone reflection:nil error:error];
    else p = [self llms_pc_newComputePipelineStateWithFunction:fn error:error];
    note_pipeline_creation(0, monotonic_ms() - t0, [fn name]); capture_pipeline(p, fn, cd); return p; }
- (id)llms_pc_newComputePipelineStateWithDescriptor:(MTLComputePipelineDescriptor *)d options:(MTLPipelineOption)o reflection:(MTLAutoreleasedComputePipelineReflection *)r error:(NSError * __autoreleasing *)error {
    const double t0 = monotonic_ms();
    if ((promise_threadgroup_multiple || census_fixed_pipelines) && d) { MTLComputePipelineDescriptor *cd = pipeline_promises_descriptor(nil, d); if (cd) d = cd; }   /* llms CFLAGS2 */
    id p = [self llms_pc_newComputePipelineStateWithDescriptor:d options:o reflection:r error:error]; note_pipeline_creation(0, monotonic_ms() - t0, [[d computeFunction] name]); capture_pipeline(p, nil, d); return p; }
- (id)llms_pc_newFunctionWithName:(NSString *)name {
    const double t0 = monotonic_ms(); id f = [self llms_pc_newFunctionWithName:name]; note_pipeline_creation(1, monotonic_ms() - t0, name); return f; }
- (id)llms_pc_newFunctionWithName:(NSString *)name constantValues:(MTLFunctionConstantValues *)cv error:(NSError * __autoreleasing *)error {
    const double t0 = monotonic_ms(); id f = [self llms_pc_newFunctionWithName:name constantValues:cv error:error]; note_pipeline_creation(1, monotonic_ms() - t0, name); return f; }
@end
static void ds4_gpu_timeline_swizzle(Class cls, SEL orig, SEL repl) {
    Method m_orig = class_getInstanceMethod(cls, orig);
    Method m_repl = class_getInstanceMethod(cls, repl);
    if (!m_orig || !m_repl) {
        fprintf(stderr, "ds4: timeline hook missing for %s\n", sel_getName(orig));
        return;
    }
    if (class_addMethod(cls, orig, method_getImplementation(m_repl),
                        method_getTypeEncoding(m_orig))) {
        class_replaceMethod(cls, repl, method_getImplementation(m_orig),
                            method_getTypeEncoding(m_orig));
    } else {
        method_exchangeImplementations(m_orig, m_repl);
    }
}

/* Called once the device exists: opens the log and hooks pipeline creation so
 * every pipeline made afterwards has a kernel name. */
static void ds4_gpu_timeline_probe(id<MTLDevice> device) {
    static int probed;
    if (probed) return;
    probed = 1;
    const char *path = getenv("DS4_METAL_ENCODER_TIMELINE");
    if (!path || !path[0] || !device) return;
    g_timeline_file = fopen(path, "a");
    if (!g_timeline_file) {
        fprintf(stderr, "ds4: cannot open encoder timeline %s\n", path);
        return;
    }
    for (id<MTLCounterSet> cs in [device counterSets]) {
        if ([[cs name] isEqualToString:MTLCommonCounterSetTimestamp]) g_timeline_counter_set = cs;
    }
    if (!g_timeline_counter_set ||
        ![device supportsCounterSampling:MTLCounterSamplingPointAtStageBoundary]) {
        fprintf(stderr, "ds4: encoder timeline unsupported on this device\n");
        fclose(g_timeline_file);
        g_timeline_file = NULL;
        return;
    }
    g_timeline_enabled = YES;
    Class dev_cls = object_getClass(device);
    ds4_gpu_timeline_swizzle(dev_cls,
        @selector(newComputePipelineStateWithFunction:error:),
        @selector(ds4_tl_newComputePipelineStateWithFunction:error:));
    ds4_gpu_timeline_swizzle(dev_cls,
        @selector(newComputePipelineStateWithDescriptor:options:reflection:error:),
        @selector(ds4_tl_newComputePipelineStateWithDescriptor:options:reflection:error:));
    fprintf(g_timeline_file, "# ds4 encoder timeline; slide=0x%llx pid=%d\n",
            (unsigned long long)_dyld_get_image_vmaddr_slide(0), (int)getpid());
    fprintf(g_timeline_file, "# B <seq> <n_encoders> <gpu_start_ns> <gpu_end_ns>\n");
    fprintf(g_timeline_file, "# E <seq> <idx> <start_ns> <end_ns> <dur_us> <gap_us> <caller_unslid> <n_dispatch> <tg> <tpt> <kernel>\n");
    fflush(g_timeline_file);
    fprintf(stderr, "ds4: encoder timeline -> %s\n", path);
}

/* llms TG_CLAMP (apply_tg_clamp.py): LLMS_DS4_TG_CLAMP=1 clamps every dispatch to the bound pipeline's maxTotalThreadsPerThreadgroup -- a shader-validation aid (instrumented pipelines allow 704); off unless set. */
static __thread __unsafe_unretained id<MTLComputePipelineState> current_pipeline;
static uint64_t threadgroups_seen, threadgroups_clamped;
static int threadgroup_clamp_on;   /* llms CFLAGS: TG_CLAMP's clamping, apart from the hook (the census hooks without clamping) */
typedef struct { const void *pso; uint64_t n, bad, bad_edge; uint32_t mint, maxt; } tg_census_entry;   /* llms CFLAGS TG_CENSUS */
static tg_census_entry tg_census_entries[4096]; static int tg_census_count; static os_unfair_lock tg_census_lock = OS_UNFAIR_LOCK_INIT;
static void note_tg_census(MTLSize t, MTLSize grid, int threads) {   /* threads: dispatchThreads (grid in threads; the edge groups are partial) */
    if (tg_census_count <= 0) return;
    const void *p = (__bridge const void *)current_pipeline; const uint32_t n = (uint32_t)(t.width * t.height * t.depth);
    int edge_bad = 0;
    if (threads) { const NSUInteger ew = t.width && grid.width % t.width ? grid.width % t.width : t.width, eh = t.height && grid.height % t.height ? grid.height % t.height : t.height,
                                     ed = t.depth && grid.depth % t.depth ? grid.depth % t.depth : t.depth;
                   edge_bad = ((ew * t.height * t.depth) | (t.width * eh * t.depth) | (t.width * t.height * ed) | (ew * eh * ed)) & 31u ? 1 : 0; }
    os_unfair_lock_lock(&tg_census_lock);
    uint32_t h = (uint32_t)((((uintptr_t)p) >> 4) * 2654435761u) & 4095u, k = 0;
    while (tg_census_entries[h].pso && tg_census_entries[h].pso != p && k++ < 4096u) h = (h + 1u) & 4095u;
    tg_census_entry *e = &tg_census_entries[h];
    if (!e->pso) { e->pso = p; e->mint = n; }
    if (e->pso == p) { e->n++; if (n > e->maxt) e->maxt = n; if (n < e->mint) e->mint = n; if (n & 31u) e->bad++; if (edge_bad) e->bad_edge++; }
    os_unfair_lock_unlock(&tg_census_lock);
}
static void arm_tg_census(const char *path) {
    static char out[1024]; snprintf(out, sizeof out, "%s", path);
    fprintf(stderr, "llms: TG_CENSUS -- every dispatch's threadgroup recorded per pipeline (no clamping) -> %s at exit\n", out);
    atexit_b(^{
        FILE *f = fopen(out, "w"); uint64_t n = 0, bad = 0, bade = 0; uint32_t np = 0, maxt = 0;
        for (uint32_t i = 0; i < 4096u; i++) { const tg_census_entry *e = &tg_census_entries[i]; if (!e->pso) continue;
            NSString *nm = pipeline_names ? pipeline_names[@((uintptr_t)e->pso)] : nil;
            np++; n += e->n; bad += e->bad; bade += e->bad_edge; if (e->maxt > maxt) maxt = e->maxt;
            if (f) fprintf(f, "%s %llu %u %u %llu %llu\n", nm ? nm.UTF8String : "?", (unsigned long long)e->n, e->mint, e->maxt, (unsigned long long)e->bad, (unsigned long long)e->bad_edge); }
        if (f) fclose(f);
        fprintf(stderr, "llms tg census: %u pipelines, %llu dispatches, largest threadgroup %u, %llu dispatches with a threadgroup not a multiple of 32, %llu dispatchThreads with a partial edge group not a multiple of 32 -> %s (name dispatches min max bad bad_edge)\n",
                np, (unsigned long long)n, maxt, (unsigned long long)bad, (unsigned long long)bade, out); });
}
static MTLSize fit_threadgroup(MTLSize s) {
    __atomic_fetch_add(&threadgroups_seen, 1, __ATOMIC_RELAXED);
    if (!threadgroup_clamp_on) return s;   /* llms CFLAGS: hooked for the census only */
    id<MTLComputePipelineState> p = current_pipeline; if (!p) return s;
    const NSUInteger mx = p.maxTotalThreadsPerThreadgroup;
    if (s.width * s.height * s.depth <= mx) return s;
    __atomic_fetch_add(&threadgroups_clamped, 1, __ATOMIC_RELAXED);
    { static char seen[32][64]; static int warned_label_count; static pthread_mutex_t warned_label_mutex = PTHREAD_MUTEX_INITIALIZER; NSString *nm = nil; if (g_timeline_pso_names) { pthread_mutex_lock(&g_timeline_mutex); nm = g_timeline_pso_names[@((uintptr_t)p)]; pthread_mutex_unlock(&g_timeline_mutex); }   /* names exist with DS4_METAL_ENCODER_TIMELINE set */
      char pb[40]; snprintf(pb, sizeof pb, "(pso %p)", (__bridge void *)p); const char *lb = nm ? nm.UTF8String : pb;   /* name every clamped pipeline once: its outputs are suspect, and so is any OOB report downstream of it */
      pthread_mutex_lock(&warned_label_mutex); int k = 0; for (; k < warned_label_count; k++) if (!strncmp(seen[k], lb, 63)) break;
      if (k == warned_label_count && warned_label_count < 32) { snprintf(seen[warned_label_count++], 64, "%s", lb); fprintf(stderr, "llms tg clamp: %s %lux%lux%lu -> max %lu\n", lb, (unsigned long)s.width, (unsigned long)s.height, (unsigned long)s.depth, (unsigned long)mx); }
      pthread_mutex_unlock(&warned_label_mutex); }
    while (s.width * s.height * s.depth > mx && s.width > 1) s.width = (s.width + 1) / 2;
    while (s.width * s.height * s.depth > mx && s.height > 1) s.height = (s.height + 1) / 2;
    while (s.width * s.height * s.depth > mx && s.depth > 1) s.depth = (s.depth + 1) / 2;
    return s;
}
/* llms DEP_DUMP (apply_dep_dump.py, 2026-10-22 17:0x): LLMS_DS4_DEP_DUMP=<path> -- one line per dispatch: phase / pos / rows, kernel, grid, and every buffer binding the kernel declares (reflection: slot, access) with the range bound there (buffer, offset, length; precise when the offset came through llms_dep_off) and the buffer's NoCopy (mapped weights) flag. An offline script builds the step's dispatch DAG. Diagnostic only; off unless the variable is set. */
static int g_llms_dep = 0; static FILE *g_llms_dep_f;

static unsigned long long g_llms_dep_lines, g_llms_dep_precise, g_llms_dep_conserv;
typedef struct { const void *buf; uint64_t off, len; int precise; uint64_t generation, cpuBase, wholeLength; } llms_dep_slot;
@interface LLMSDepResource : NSObject
@property(nonatomic, strong) id<MTLBuffer> buffer;
@property MTLResourceUsage usage;
@end
@implementation LLMSDepResource
@end
@interface LLMSDepEncoderState : NSObject { @public llms_dep_slot slots[64]; id<MTLComputePipelineState> pipeline;
    NSMutableDictionary<NSValue *, LLMSDepResource *> *declared; int unknown; uint64_t encoderID, commandID, queueID; }
@end
@implementation LLMSDepEncoderState
@end
static char llms_dep_encoder_key;
static LLMSDepEncoderState *llms_dep_state(id encoder) {
    LLMSDepEncoderState *state = objc_getAssociatedObject(encoder, &llms_dep_encoder_key);
    if (!state) {
        state = [LLMSDepEncoderState new];
        objc_setAssociatedObject(encoder, &llms_dep_encoder_key, state, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    return state;
}
typedef struct { const void *pso; char name[96]; int n, complete; unsigned char slot[32], acc[32]; } llms_dep_pso; static llms_dep_pso g_llms_dep_psos[4096]; static int g_llms_dep_npso;
static const void *g_llms_dep_nocopy[65536];
static unsigned llms_dep_h(const void *p) { uint64_t x = (uint64_t)(uintptr_t)p; x ^= x >> 17; x *= 0x9E3779B97F4A7C15ull; return (unsigned)(x >> 40) & 65535u; }
static void llms_dep_nocopy_add(const void *p) {
    if (!g_llms_dep_f) return;
    flockfile(g_llms_dep_f);
    unsigned h = llms_dep_h(p);
    for (int k = 0; k < 64; k++) {
        unsigned i = (h + (unsigned)k) & 65535u;
        if (!g_llms_dep_nocopy[i] || g_llms_dep_nocopy[i] == p) { g_llms_dep_nocopy[i] = p; break; }
    }
    funlockfile(g_llms_dep_f);
}
static int llms_dep_nocopy_has(const void *p) { unsigned h = llms_dep_h(p); for (int k = 0; k < 64; k++) { unsigned i = (h + (unsigned)k) & 65535u; if (!g_llms_dep_nocopy[i]) return 0; if (g_llms_dep_nocopy[i] == p) return 1; } return 0; }
static llms_dep_pso *llms_dep_find(const void *pso) { for (int i = g_llms_dep_npso - 1; i >= 0; i--) if (g_llms_dep_psos[i].pso == pso) return &g_llms_dep_psos[i]; return NULL; }
static void llms_dep_note_pso(id pso, NSString *name, MTLComputePipelineReflection *refl) {
    if (!pso || !g_llms_dep_f) return;
    llms_dep_pso record = {0}; record.pso = (__bridge const void *)pso;
    record.complete = refl != nil;
    snprintf(record.name, sizeof record.name, "%s", name ? name.UTF8String : "?");
    if (refl) for (id<MTLBinding> binding in refl.bindings) {
        if (binding.type == MTLBindingTypeThreadgroupMemory) continue;   /* dynamic threadgroup memory is no device dependency (apply_dep_tgfix.py) */
        if (binding.type != MTLBindingTypeBuffer || binding.index >= 64 || record.n >= 32) {
            record.complete = 0; continue;
        }
        record.slot[record.n] = (unsigned char)binding.index;
        record.acc[record.n++] = (unsigned char)binding.access;
    }
    flockfile(g_llms_dep_f);
    if (g_llms_dep_npso < 4096) { g_llms_dep_psos[g_llms_dep_npso] = record; g_llms_dep_npso++; }
    funlockfile(g_llms_dep_f);
}
/* Known virtual backing only. Distinct CPU mappings can still alias physically. */
static char llms_alias_generation_key;
static uint64_t llms_alias_next_generation;
static llms_dep_slot llms_alias_slot(id<MTLBuffer> buffer) {
    llms_dep_slot slot={0};
    if (!buffer) return slot;
    /* Recursive FILE lock: bind callers and emit callers share this identity owner. */
    flockfile(g_llms_dep_f);
    NSNumber *generation=objc_getAssociatedObject(buffer,&llms_alias_generation_key);
    if (!generation) {
        generation=@(++llms_alias_next_generation);
        objc_setAssociatedObject(buffer,&llms_alias_generation_key,generation,OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    slot.buf=(__bridge const void *)buffer;
    slot.generation=generation.unsignedLongLongValue;
    slot.cpuBase=(uint64_t)(uintptr_t)buffer.contents;
    slot.wholeLength=buffer.length;
    funlockfile(g_llms_dep_f);
    return slot;
}

static void llms_dep_bind(id encoder, id<MTLBuffer> b, NSUInteger off, NSUInteger idx) {
    if (!g_llms_dep || idx >= 64) return;
    llms_dep_slot *s = &llms_dep_state(encoder)->slots[idx]; *s = llms_alias_slot(b); s->off = off;
    if (!b) { s->len = 0; s->precise = 1; }
    else { s->len = b.length > off ? b.length - off : 0; s->precise = 0; }
}
/* DEP_DUMP only: declarations are conservative, not decoded GPU pointers. */
#include <mach/mach_time.h>
static char llms_order_identity_key, llms_order_commit_key;
static uint64_t llms_order_next_identity, llms_order_sequence;
static uint64_t llms_order_done_notifications;

/* Caller owns the FILE lock. IDs follow object lifetime, not pointer reuse. */
static uint64_t llms_order_id(id object) {
    if (!object) return 0;
    NSNumber *number = objc_getAssociatedObject(object, &llms_order_identity_key);
    if (!number) {
        number = @(++llms_order_next_identity);
        objc_setAssociatedObject(object, &llms_order_identity_key, number, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    return number.unsignedLongLongValue;
}
static void llms_order_row(const char *kind, uint64_t queue, uint64_t cb, uint64_t enc, uint64_t event, uint64_t value) {
    fprintf(g_llms_dep_f,"O3 %llu %llu %s %llu %llu %llu %llu %llu\n",
            (unsigned long long)++llms_order_sequence,(unsigned long long)mach_absolute_time(),kind,
            (unsigned long long)queue,(unsigned long long)cb,(unsigned long long)enc,
            (unsigned long long)event,(unsigned long long)value);
}
static void llms_order_note(const char *kind, id<MTLCommandBuffer> cb, id event, uint64_t value) {
    if (!g_llms_dep || !g_llms_dep_f) return;
    flockfile(g_llms_dep_f);
    llms_order_row(kind,llms_order_id(cb.commandQueue),llms_order_id(cb),0,llms_order_id(event),value);
    funlockfile(g_llms_dep_f);
}
static void llms_order_bind(id<MTLComputeCommandEncoder> enc, id<MTLCommandBuffer> cb) {
    if (!g_llms_dep || !g_llms_dep_f || !enc) return;
    flockfile(g_llms_dep_f);
    LLMSDepEncoderState *state=llms_dep_state(enc);
    uint64_t cbid=llms_order_id(cb),qid=llms_order_id(cb.commandQueue);
    if (!state->encoderID) {
        state->encoderID=++llms_order_next_identity; /* one ID per encoding interval: Metal reuses encoder objects */state->commandID=cbid;state->queueID=qid;
        llms_order_row("ENC_BEGIN",qid,cbid,state->encoderID,0,(uint64_t)enc.dispatchType);
    } else if (state->commandID!=cbid || state->queueID!=qid) {
        state->unknown=1;
        llms_order_row("OWNER_MISMATCH",qid,cbid,state->encoderID,0,0);
    }
    funlockfile(g_llms_dep_f);
}
static void llms_order_end(id encoder) {
    if (!g_llms_dep || !g_llms_dep_f) return;
    flockfile(g_llms_dep_f);
    LLMSDepEncoderState *state=llms_dep_state(encoder);
    llms_order_row("ENC_END_CALL",state->queueID,state->commandID,state->encoderID,0,0);
    funlockfile(g_llms_dep_f);
}
static void llms_order_event(id<MTLCommandBuffer> cb, id<MTLEvent> event, uint64_t value, int signal) {
    llms_order_note(signal?"SIGNAL_CALL":"WAIT_CALL",cb,event,value);
    if (signal) [cb encodeSignalEvent:event value:value];
    else [cb encodeWaitForEvent:event value:value];
    llms_order_note(signal?"SIGNAL_RETURN":"WAIT_RETURN",cb,event,value);
}
static void llms_order_host(id<MTLSharedEvent> event, uint64_t value) {
    llms_order_note("HOST_SET_CALL",nil,event,value);
    event.signaledValue=value;
    llms_order_note("HOST_SET_RETURN",nil,event,value);
}
static int llms_fc_armed; static double llms_fc_sec;   /* llms VSPLIT3 : the first command-buffer commit after the verify armed it (CLOCK_MONOTONIC s) */
static volatile int llms_vg_on; static double llms_vg_busy, llms_vg_first, llms_vg_last; static int llms_vg_n;   /* llms VSPLIT4: the verify's command buffers' own GPU time */
static double llms_vg_each[64]; static int llms_vg_seq;   /* llms VSPLIT5: each buffer's GPU ms in commit order (the first 64) */
void ds4_gpu_llms_fc_arm(void) { llms_fc_armed = 1; llms_fc_sec = 0.0; llms_vg_on = 1; llms_vg_busy = 0.0; llms_vg_first = 0.0; llms_vg_last = 0.0; llms_vg_n = 0; llms_vg_seq = 0; for (int i = 0; i < 64; i++) llms_vg_each[i] = -1.0; }
int ds4_gpu_llms_vg_each(double *out, int cap) { int n = llms_vg_seq < cap ? llms_vg_seq : cap; for (int i = 0; i < n; i++) out[i] = llms_vg_each[i]; return n; }   /* llms VSPLIT5 */
void ds4_gpu_llms_vg_read(double *busy_ms, double *span_ms, int *n) { llms_vg_on = 0; *busy_ms = llms_vg_busy * 1e3; *span_ms = (llms_vg_last - llms_vg_first) * 1e3; *n = llms_vg_n; }
double ds4_gpu_llms_fc_sec(void) { return llms_fc_sec; }
static void llms_order_commit(id<MTLCommandBuffer> cb) {
    if (g_llms_dep && g_llms_dep_f && cb) {
        flockfile(g_llms_dep_f);
        BOOL first=!objc_getAssociatedObject(cb,&llms_order_commit_key);
        if (first) objc_setAssociatedObject(cb,&llms_order_commit_key,@YES,OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        funlockfile(g_llms_dep_f);
        if (first) {
            [cb addScheduledHandler:^(id<MTLCommandBuffer> buffer){llms_order_note("CB_SCHEDULED_NOTIFY",buffer,nil,(uint64_t)buffer.status);}];
            [cb addCompletedHandler:^(id<MTLCommandBuffer> buffer){
                llms_order_note("CB_DONE_NOTIFY",buffer,nil,(uint64_t)buffer.status);
                __atomic_fetch_add(&llms_order_done_notifications,1,__ATOMIC_RELEASE);
            }];
        }
    }
    const int vg_k = llms_vg_on ? llms_vg_seq++ : -1;   /* llms VSPLIT5: this buffer's commit index */
    if (llms_vg_on) [cb addCompletedHandler:^(id<MTLCommandBuffer> b) { if (!llms_vg_on) return; const double s0 = b.GPUStartTime, e0 = b.GPUEndTime; if (s0 <= 0.0 || e0 < s0) return; if (vg_k >= 0 && vg_k < 64) llms_vg_each[vg_k] = (e0 - s0) * 1e3;   /* llms VSPLIT4 / 5 */
        @synchronized ([NSNull null]) { llms_vg_busy += e0 - s0; if (llms_vg_first == 0.0 || s0 < llms_vg_first) llms_vg_first = s0; if (e0 > llms_vg_last) llms_vg_last = e0; llms_vg_n++; } }];
    if (llms_fc_armed) { struct timespec fts; clock_gettime(CLOCK_MONOTONIC, &fts); llms_fc_sec = (double)fts.tv_sec + (double)fts.tv_nsec * 1.0e-9; llms_fc_armed = 0; }   /* llms VSPLIT3 */
    llms_order_note("COMMIT_CALL",cb,nil,0);
    [cb commit];
    llms_order_note("COMMIT_RETURN",cb,nil,0);
}

static void llms_dep_use(id encoder, id<MTLResource> resource, MTLResourceUsage usage) {
    if (!g_llms_dep) return;
    LLMSDepEncoderState *state = llms_dep_state(encoder);
    const MTLResourceUsage known = MTLResourceUsageRead | MTLResourceUsageWrite | MTLResourceUsageSample;
    if (!resource || ![resource conformsToProtocol:@protocol(MTLBuffer)] ||
        !(usage & known) || (usage & ~known)) { state->unknown = 1; return; }
    if (!state->declared) state->declared = [NSMutableDictionary new];
    NSValue *key = [NSValue valueWithPointer:(__bridge const void *)resource];
    LLMSDepResource *entry = state->declared[key];
    if (!entry) {
        entry = [LLMSDepResource new]; entry.buffer = (id<MTLBuffer>)resource;
        state->declared[key] = entry;
    }
    entry.usage |= usage;
}

static void llms_dep_print_slot(NSUInteger index, llms_dep_slot slot, unsigned access) {
    fprintf(g_llms_dep_f, " %lu:%p:%llu:%llu:%u:%d:%d:%llu:%llu:%llu", (unsigned long)index, slot.buf,
            (unsigned long long)slot.off, (unsigned long long)slot.len, access,
            slot.precise, slot.buf ? llms_dep_nocopy_has(slot.buf) : 0, (unsigned long long)slot.generation, (unsigned long long)slot.cpuBase, (unsigned long long)slot.wholeLength);
    if (slot.precise) g_llms_dep_precise++; else g_llms_dep_conserv++;
}

static void llms_dep_emit(id encoder, int kind, MTLSize size,
                          id<MTLBuffer> indirect, NSUInteger offset) {
    if (!g_llms_dep || !g_llms_dep_f) return;
    LLMSDepEncoderState *state = llms_dep_state(encoder);
    flockfile(g_llms_dep_f); /* Also protects reflection/NoCopy publication. */
    llms_dep_pso *r = llms_dep_find((__bridge const void *)state->pipeline);
    const uint64_t argument_bytes = sizeof(MTLDispatchThreadgroupsIndirectArguments);
    int local = r && r->complete && !state->unknown && state->encoderID && state->commandID && state->queueID;
    if (substreams_active) { local=0; llms_order_row("SUBSTREAM_UNMODELED",state->queueID,state->commandID,state->encoderID,0,substream_current); }
    if (kind == 2 && (!indirect || offset % 4 || offset > indirect.length ||
                     argument_bytes > indirect.length - offset)) local = 0;
    char grid[96];
    if (kind == 2) snprintf(grid, sizeof grid, "?");
    else snprintf(grid, sizeof grid, "%lux%lux%lu", (unsigned long)size.width,
                  (unsigned long)size.height, (unsigned long)size.depth);
    NSUInteger count = (r ? r->n : 0) + state->declared.count + (kind == 2);
    fprintf(g_llms_dep_f, "D4 %llu %llu %llu %llu %llu %u %u %u %s %d %s %lu %d",
            (unsigned long long)++llms_order_sequence,(unsigned long long)mach_absolute_time(),
            (unsigned long long)state->queueID,(unsigned long long)state->commandID,(unsigned long long)state->encoderID,
            (unsigned)timeline_phase,
            (unsigned)timeline_position, (unsigned)timeline_rows, r ? r->name : "?", kind,
            grid, (unsigned long)count, local);
    if (r) for (int i = 0; i < r->n; i++)
        llms_dep_print_slot(r->slot[i], state->slots[r->slot[i]], r->acc[i]);
    if (kind == 2) {
        llms_dep_slot arg = llms_alias_slot(indirect); arg.off=offset; arg.len=argument_bytes; arg.precise=1;
        llms_dep_print_slot(64, arg, 0);
    }
    NSUInteger slot = 65;
    for (LLMSDepResource *entry in state->declared.objectEnumerator) {
        const BOOL writes = (entry.usage & MTLResourceUsageWrite) != 0;
        const BOOL reads = (entry.usage & (MTLResourceUsageRead | MTLResourceUsageSample)) != 0;
        llms_dep_slot resource = llms_alias_slot(entry.buffer); resource.len=entry.buffer.length;
        llms_dep_print_slot(slot++, resource, writes ? (reads ? 2 : 1) : 0);
    }
    fputc('\n', g_llms_dep_f); g_llms_dep_lines++;
    funlockfile(g_llms_dep_f);
}

static void llms_dep_flush(id encoder, int kind, MTLSize size) {
    llms_dep_emit(encoder, kind, size, nil, 0);
}

@implementation NSObject (LLMSDep)
- (void)llms_dep_indirect:(id<MTLBuffer>)buffer indirectBufferOffset:(NSUInteger)offset
      threadsPerThreadgroup:(MTLSize)threads {
    llms_dep_emit(self, 2, MTLSizeMake(0, 0, 0), buffer, offset);
    [self llms_dep_indirect:buffer indirectBufferOffset:offset threadsPerThreadgroup:threads];
}
- (void)llms_dep_useResource:(id<MTLResource>)resource usage:(MTLResourceUsage)usage {
    llms_dep_use(self, resource, usage);
    [self llms_dep_useResource:resource usage:usage];
}
- (void)llms_dep_useResources:(const id<MTLResource> [])resources count:(NSUInteger)count usage:(MTLResourceUsage)usage {
    if (g_llms_dep) for (NSUInteger i = 0; i < count; i++) llms_dep_use(self, resources[i], usage);
    [self llms_dep_useResources:resources count:count usage:usage];
}
- (void)llms_dep_useHeap:(id<MTLHeap>)heap {
    if (g_llms_dep) llms_dep_state(self)->unknown = 1;
    [self llms_dep_useHeap:heap];
}
- (void)llms_dep_useHeaps:(const id<MTLHeap> [])heaps count:(NSUInteger)count {
    if (g_llms_dep && count) llms_dep_state(self)->unknown = 1;
    [self llms_dep_useHeaps:heaps count:count];
}

- (void)llms_dep_setBytes:(const void *)bytes length:(NSUInteger)length atIndex:(NSUInteger)index {
    llms_dep_bind(self, nil, 0, index);
    [self llms_dep_setBytes:bytes length:length atIndex:index];
}
- (void)llms_dep_endEncoding {
    llms_order_end(self);
    [self llms_dep_endEncoding];
    objc_setAssociatedObject(self, &llms_dep_encoder_key, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
}
- (void)llms_dep_setBuffer:(id<MTLBuffer>)b offset:(NSUInteger)off atIndex:(NSUInteger)i { llms_dep_bind(self, b, off, i); [self llms_dep_setBuffer:b offset:off atIndex:i]; }   /* the allocation suffix [off, buffer.length): a tensor allocation is its own buffer; no thread-local guess (apply_dep_conservative.py item 3) */
- (id)newLlmsDepPSO:(id<MTLFunction>)fn error:(NSError **)err { MTLComputePipelineReflection *refl = nil; id pso = [(id<MTLDevice>)self newComputePipelineStateWithFunction:fn options:MTLPipelineOptionBindingInfo reflection:&refl error:err]; llms_dep_note_pso(pso, fn.name, refl); return pso; }
- (id)newLlmsDepPSOd:(MTLComputePipelineDescriptor *)d options:(MTLPipelineOption)opt reflection:(MTLAutoreleasedComputePipelineReflection *)rp error:(NSError **)err { MTLComputePipelineReflection *refl = nil; id pso = [self newLlmsDepPSOd:d options:(opt | MTLPipelineOptionBindingInfo) reflection:&refl error:err]; llms_dep_note_pso(pso, d.computeFunction.name, refl); if (rp) *rp = refl; return pso; }
- (id)newLlmsDepNoCopy:(void *)p length:(NSUInteger)len options:(MTLResourceOptions)o deallocator:(void (^)(void *, NSUInteger))dealloc { id b = [self newLlmsDepNoCopy:p length:len options:o deallocator:dealloc]; if (b) llms_dep_nocopy_add((__bridge const void *)b); return b; }
@end
static void llms_dep_report(void) { if (g_llms_dep_f) fflush(g_llms_dep_f); fprintf(stderr, "llms dep dump: %llu dispatch lines, %llu precise bindings, %llu conservative (rest of buffer), %d pipelines named\n", g_llms_dep_lines, g_llms_dep_precise, g_llms_dep_conserv, g_llms_dep_npso); }
#include <execinfo.h>
static void llms_dep_segv(int sig) { void *bt[64]; int n = backtrace(bt, 64); fprintf(stderr, "llms dep dump: signal %d, backtrace:\n", sig); backtrace_symbols_fd(bt, n, 2); if (g_llms_dep_f) fflush(g_llms_dep_f); _exit(128 + sig); }   /* 19:1x: the 19:03 run died with rc -11 and an empty dump */
/* 19:4x: the replacement selectors are in the ARC new family (newLlmsDep...) -- a +0-family name autoreleased the +1 PSO / buffer and the caller's release freed it (SIGSEGV in setComputePipelineState:, dep_dump 19:47) */
static void llms_dep_init(id<MTLDevice> dev) {
    const char *d = getenv("LLMS_DS4_DEP_DUMP"); if (!d || !*d || !dev) return;
    g_llms_dep_f = fopen(d, "w"); if (!g_llms_dep_f) { fprintf(stderr, "llms dep dump: cannot open %s\n", d); return; }
    setvbuf(g_llms_dep_f, NULL, _IOFBF, 1 << 20); g_llms_dep = 1; atexit(llms_dep_report); signal(SIGSEGV, llms_dep_segv); signal(SIGBUS, llms_dep_segv);
    Class dc = object_getClass(dev);
    ds4_gpu_timeline_swizzle(dc, @selector(newComputePipelineStateWithFunction:error:), @selector(newLlmsDepPSO:error:));
    ds4_gpu_timeline_swizzle(dc, @selector(newComputePipelineStateWithDescriptor:options:reflection:error:), @selector(newLlmsDepPSOd:options:reflection:error:));
    ds4_gpu_timeline_swizzle(dc, @selector(newBufferWithBytesNoCopy:length:options:deallocator:), @selector(newLlmsDepNoCopy:length:options:deallocator:));
    fprintf(stderr, "llms: dep dump -> %s (every dispatch's declared buffer bindings with their bound ranges; the device's pipeline and NoCopy creation hooked)\n", d);
}
/* llms MEM_CENSUS (11-02, apply_mem_census.py): every device buffer counted by bytes and caller, printed at exit with the device's currentAllocatedSize and the task's phys_footprint -- a measurement switch, off unless LLMS_DS4_MEM_CENSUS=1 */
typedef struct { uintptr_t caller; uint64_t n, bytes; int nocopy; } llms_memc_row;
static llms_memc_row llms_memc[1024]; static int llms_memc_n, g_llms_memc; static uint64_t llms_memc_lost, llms_memc_len_bytes, llms_memc_nc_bytes;
static pthread_mutex_t llms_memc_mu = PTHREAD_MUTEX_INITIALIZER; static id<MTLDevice> llms_memc_dev;
static void llms_memc_note(uintptr_t caller, uint64_t bytes, int nocopy) {
    pthread_mutex_lock(&llms_memc_mu);
    if (nocopy) llms_memc_nc_bytes += bytes; else llms_memc_len_bytes += bytes;
    int i = 0; for (; i < llms_memc_n; i++) if (llms_memc[i].caller == caller && llms_memc[i].nocopy == nocopy) { llms_memc[i].n++; llms_memc[i].bytes += bytes; break; }
    if (i == llms_memc_n) { if (llms_memc_n < 1024) { llms_memc[i].caller = caller; llms_memc[i].n = 1; llms_memc[i].bytes = bytes; llms_memc[i].nocopy = nocopy; llms_memc_n++; } else llms_memc_lost++; }
    pthread_mutex_unlock(&llms_memc_mu);
}
@interface NSObject (LLMSMemCensus)
- (id)newLlmsMemLen:(NSUInteger)len options:(MTLResourceOptions)o;
- (id)newLlmsMemNoCopy:(void *)p length:(NSUInteger)len options:(MTLResourceOptions)o deallocator:(void (^)(void *, NSUInteger))dealloc;
@end
@implementation NSObject (LLMSMemCensus)
- (id)newLlmsMemLen:(NSUInteger)len options:(MTLResourceOptions)o { id b = [self newLlmsMemLen:len options:o]; if (b) llms_memc_note((uintptr_t)__builtin_return_address(0), (uint64_t)len, 0); return b; }
- (id)newLlmsMemNoCopy:(void *)p length:(NSUInteger)len options:(MTLResourceOptions)o deallocator:(void (^)(void *, NSUInteger))dealloc {
    id b = [self newLlmsMemNoCopy:p length:len options:o deallocator:dealloc]; if (b) llms_memc_note((uintptr_t)__builtin_return_address(0), (uint64_t)len, 1); return b; }
@end
static void llms_memc_report(void) {
    task_vm_info_data_t vi; mach_msg_type_number_t cnt = TASK_VM_INFO_COUNT; const int ok = task_info(mach_task_self(), TASK_VM_INFO, (task_info_t)&vi, &cnt) == KERN_SUCCESS;
    const uintptr_t slide = (uintptr_t)_dyld_get_image_vmaddr_slide(0);
    fprintf(stderr, "llms mem census: %d callers (%llu lost); newBufferWithLength %.3f GiB, NoCopy wraps %.3f GiB; device currentAllocatedSize %.3f GiB; "
            "phys_footprint %.3f GiB, internal %.3f, compressed %.3f\n", llms_memc_n, (unsigned long long)llms_memc_lost, llms_memc_len_bytes / 1073741824.0,
            llms_memc_nc_bytes / 1073741824.0, llms_memc_dev ? (double)[llms_memc_dev currentAllocatedSize] / 1073741824.0 : -1.0,
            ok ? vi.phys_footprint / 1073741824.0 : -1.0, ok ? vi.internal / 1073741824.0 : -1.0, ok ? vi.compressed / 1073741824.0 : -1.0);
    static int idx[1024]; for (int i = 0; i < llms_memc_n; i++) idx[i] = i;
    for (int i = 0; i < llms_memc_n; i++) for (int j = i + 1; j < llms_memc_n; j++) if (llms_memc[idx[j]].bytes > llms_memc[idx[i]].bytes) { const int t = idx[i]; idx[i] = idx[j]; idx[j] = t; }
    for (int k = 0; k < llms_memc_n && k < 40; k++) { const llms_memc_row *r = &llms_memc[idx[k]];
        fprintf(stderr, "llms mem census: %10.3f MiB %6llu x %s caller unslid 0x%llx\n", r->bytes / 1048576.0, (unsigned long long)r->n, r->nocopy ? "nocopy" : "length",
                (unsigned long long)(r->caller - slide)); }
}
static void llms_mem_census_init(id<MTLDevice> dev) {
    const char *e = getenv("LLMS_DS4_MEM_CENSUS"); if (!e || !*e || *e == '0' || !dev) return;
    if (g_llms_dep) { fprintf(stderr, "llms mem census: off -- DEP_DUMP already hooks NoCopy creation\n"); return; }
    g_llms_memc = 1; llms_memc_dev = dev; Class dc = object_getClass(dev);
    ds4_gpu_timeline_swizzle(dc, @selector(newBufferWithLength:options:), @selector(newLlmsMemLen:options:));
    ds4_gpu_timeline_swizzle(dc, @selector(newBufferWithBytesNoCopy:length:options:deallocator:), @selector(newLlmsMemNoCopy:length:options:deallocator:));
    atexit(llms_memc_report);
    fprintf(stderr, "llms: mem census (every device buffer counted by bytes and caller; printed at exit -- a measurement switch)\n");
}
@implementation NSObject (LLMSTGClamp)
- (void)llms_tgc_setComputePipelineState:(id<MTLComputePipelineState>)pso { current_pipeline = pso; if (g_llms_dep) llms_dep_state(self)->pipeline = pso; bound_pipeline = (__bridge const void *)pso; [self llms_tgc_setComputePipelineState:pso]; }   /* llms SKIP_KERNELS */
- (void)llms_tgc_dispatchThreadgroups:(MTLSize)tg threadsPerThreadgroup:(MTLSize)tpt { if (!prepare_dispatch((id<MTLComputeCommandEncoder>)self)) return; note_tg_census(tpt, tg, 0); llms_dep_flush(self, 0, tg); [self llms_tgc_dispatchThreadgroups:tg threadsPerThreadgroup:fit_threadgroup(tpt)];
    if (dup_this_dispatch()) { if ([(id<MTLComputeCommandEncoder>)self dispatchType] == MTLDispatchTypeConcurrent) [(id<MTLComputeCommandEncoder>)self memoryBarrierWithScope:MTLBarrierScopeBuffers];
                          [self llms_tgc_dispatchThreadgroups:tg threadsPerThreadgroup:fit_threadgroup(tpt)]; dup_dispatches++; } }   /* llms DUP_KERNELS */
- (void)llms_tgc_dispatchThreads:(MTLSize)th threadsPerThreadgroup:(MTLSize)tpt { if (!prepare_dispatch((id<MTLComputeCommandEncoder>)self)) return; note_tg_census(tpt, th, 1); llms_dep_flush(self, 1, th); [self llms_tgc_dispatchThreads:th threadsPerThreadgroup:fit_threadgroup(tpt)];
