/* llms DENSE_XQ (apply_xq.py): a FIDELITY DIAL, NOT the model -- every TWO-ROW f32 -> f16 x copy (kernel_llms_f32_to_f16_rows with cv[2] == 2) fake-quantized to N two's-complement planes per 32-group with the routed experts' quantizer (sc = max|x| / (2^(N-1) - 1), rint): the KL the bit-serial dense body would pay. Other row counts pass through as the shipped conversion; the hx producers stand down while it is set. Off unless LLMS_DS4_DENSE_XQ=3..8. */
static int dense_xq_env(void) { static int v = -1; if (v < 0) { const char *e = getenv("LLMS_DS4_DENSE_XQ"); v = e && *e ? atoi(e) : 0; if (v < 3 || v > 8) v = 0; } return v; }
static id<MTLComputePipelineState> dense_xq_pipe; static int dense_xq_built;
static id<MTLComputePipelineState> dense_xq_pipeline(void) {
    if (dense_xq_built || !dense_xq_env() || !g_device) return dense_xq_pipe;
    dense_xq_built = 1; const int v = dense_xq_env();
    NSString *src = [NSString stringWithFormat:@"#include <metal_stdlib>\nusing namespace metal;\n"
        "kernel void llms_f32_to_f16_rows_xq(device const float4 * src [[buffer(0)]], device half4 * dst [[buffer(1)]], constant uint * cv [[buffer(2)]],\n"
        "                                    uint gid [[thread_position_in_grid]]) {\n"
        "    const uint n4 = cv[0], rs4 = cv[1], rows = cv[2]; const bool live = gid < n4 * rows;\n"
        "    const uint r = live ? gid / n4 : 0u, i = live ? gid - r * n4 : 0u;\n"
        "    const float4 v = live ? clamp(src[r * rs4 + i], -65504.0f, 65504.0f) : float4(0.0f);\n"
        "    float a = max(max(fabs(v.x), fabs(v.y)), max(fabs(v.z), fabs(v.w)));\n"
        "    a = max(a, simd_shuffle_xor(a, (ushort)1)); a = max(a, simd_shuffle_xor(a, (ushort)2)); a = max(a, simd_shuffle_xor(a, (ushort)4));\n"
        "    const float qmax = %d.0f; const float sc = a > 0.0f ? a / qmax : 1.0f;\n"
        "    if (live) dst[r * n4 + i] = rows == 2u ? half4(rint(v / sc) * sc) : half4(v);\n"
        "}\n", (1 << (v - 1)) - 1];
    NSError *err = nil; id<MTLLibrary> lib = [g_device newLibraryWithSource:src options:nil error:&err];
    id<MTLFunction> fn = lib ? [lib newFunctionWithName:@"llms_f32_to_f16_rows_xq"] : nil;
    dense_xq_pipe = fn ? [g_device newComputePipelineStateWithFunction:fn error:&err] : nil;
    if (!dense_xq_pipe) { fprintf(stderr, "llms dense xq: kernel build failed (%s) -- REFUSING to run a dial that is not in force\n", err ? err.localizedDescription.UTF8String : "?"); abort(); }
    fprintf(stderr, "llms: dense xq %d planes per 32-group on every two-row x copy (FIDELITY DIAL, not the model; the hx producers off)\n", v);
    return dense_xq_pipe;
}
