static int hx_producer_on(void) {   /* llms HX_PRODUCER (apply_hxprod.py): LLMS_DS4_HX_PRODUCER=1; ALT hxprod */

    if (dense_xq_env()) return 0;   /* llms DENSE_XQ: every two-row consumer converts through the (quantizing) copy */
    if (swr_env_active()) return 0;   /* llms DENSE_SWR: the two-row consumers read f32 x; a half copy would have no reader */
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_HX_PRODUCER"); on = e && *e && *e != '0';
        if (on) { fprintf(stderr, "llms: hx producer (swiglu writes the half copy of its output; the next half-x matvec skips its conversion; ALT hxprod)\n");
                  atexit_b(^{ fprintf(stderr, "llms hx producer: %llu half copies written, %llu used by the next matvec, %llu dropped\n",
                                      (unsigned long long)hxp_made, (unsigned long long)hxp_used, (unsigned long long)hxp_dropped); }); } }
    return on;
}
