static void report_gateup_side(void) {
    fprintf(stderr, "llms bs6c: %llu batched gate/up calls (%llu single pairs, %llu two-row, %llu three/four-row entries), %llu translated layer calls, "
            "%llu tables translated, %llu side-file reads, %llu IQ2_XXS-sized notes rejected by the size class\n",
            (unsigned long long)gateup_side_calls, (unsigned long long)gateup_side_single_pairs, (unsigned long long)gateup_side_two_row_entries, (unsigned long long)gateup_side_four_row_entries,
            (unsigned long long)gateup_side_translated_calls, (unsigned long long)gateup_side_tables_translated, (unsigned long long)gateup_side_reads, (unsigned long long)gateup_side_rejected_notes);
