static int bs64_side_format;   /* llms BS64 (apply_bs64_gen.py): the side file is the G64 code (1,400 B rows) */
static int gateup_side_on(void) {
    if (gateup_side_state > -2) return gateup_side_state;
    gateup_side_state = 0;
    const char *e = getenv("LLMS_DS4_GATEUP_BS64"), *src = getenv("DS4_METAL_MOE_SOURCE");
    if (!e || !*e || !strcmp(e, "0")) return 0;
    if (!(src && llms_srckey(src, "bs6c") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_GATEUP_BS64 ignored: DS4_METAL_MOE_SOURCE does not name a *bs6c* source\n"), LLMS_G_NAME); return 0; }
    const int fd = open(e, O_RDONLY | O_CLOEXEC);
    if (fd < 0) { fprintf(stderr, "llms: LLMS_DS4_GATEUP_BS64 ignored: cannot open %s\n", e); return 0; }
    unsigned char h[56]; uint32_t u32[5]; uint64_t u64[4];
    if (pread(fd, h, sizeof h, 0) != (ssize_t)sizeof h || (memcmp(h, "BS6C", 4) != 0 && memcmp(h, "BS64", 4) != 0)) { fprintf(stderr, "llms: LLMS_DS4_GATEUP_BS64 ignored: %s is not a BS6C / BS64 file\n", e); close(fd); return 0; }
    bs64_side_format = memcmp(h, "BS64", 4) == 0;   /* llms BS64 */
    memcpy(u32, h + 4, sizeof u32); memcpy(u64, h + 24, sizeof u64);   /* version, layers, experts, rows, cols | matrix, expert, layer bytes, data offset */
    if (u32[0] != 1u || u32[1] != 40u || u32[2] != 384u || u32[3] != 2304u || u32[4] != 5120u || u64[0] != 2304ull * (bs64_side_format ? 1400ull : 1520ull) ||   /* llms BS64 */ u64[1] != 2ull * u64[0] ||
        u64[2] != 384ull * u64[1] || u64[3] != 16384ull) { fprintf(stderr, "llms: LLMS_DS4_GATEUP_BS64 ignored: unexpected header in %s\n", e); close(fd); return 0; }
    const int gateup_partial_env = getenv("LLMS_DS4_GATEUP_BS64_PARTIAL") != NULL;   /* apply_bs6c_partial.py */
    if (gateup_partial_env) fprintf(stderr, "llms: bs6c PARTIAL -- the completeness check is skipped: missing layers read as zero weights (a plumbing test, NOT the model)\n");
    for (uint32_t L = 0; L < 40u && !gateup_partial_env; L++) {   /* a layer never encoded is a hole of zeros: check its first and its last record */
        unsigned char a[64], b[64]; int nz = 0;
        if (pread(fd, a, 64, (off_t)(u64[3] + L * u64[2])) != 64 || pread(fd, b, 64, (off_t)(u64[3] + (L + 1ull) * u64[2] - 64ull)) != 64) nz = -1;
        else { for (int i = 0; i < 64; i++) nz |= a[i] | b[i]; }
        if (nz <= 0) { fprintf(stderr, "llms: LLMS_DS4_GATEUP_BS64 ignored: layer %u of %s is missing (zeros or short)\n", L, e); close(fd); return 0; }
    }
    (void)fcntl(fd, F_NOCACHE, 1); (void)fcntl(fd, F_RDAHEAD, 0);
    gateup_side_fd = fd; gateup_side_matrix_bytes = u64[0]; gateup_side_layer_bytes = u64[2]; gateup_side_data_offset = u64[3];
    gateup_side_eight_planes = getenv("LLMS_DS4_GATEUP_BS64_P8") != NULL;
    gateup_side_state = getenv("LLMS_DS4_GATEUP_BS64_CANARY") != NULL ? -1 : 1;
    fprintf(stderr, "llms: bs6c (the batched decode's routed gate/up from %s: plain 2-bit %s codes, bit-serial over %d activation planes%s; prefill and one-token calls keep IQ2_XXS)\n",
            e, bs64_side_format ? "G64/4 (512 super-blocks)" : "G32/4", gateup_side_eight_planes ? 8 : 6, gateup_side_state < 0 ? " -- CANARY: the code planes swapped" : "");
    atexit(report_gateup_side);
    return gateup_side_state;
}
/* llms BSMX (apply_bsmx.py): mixed two-plane / one-plane 32-row gate / up tiles -- LLMS_DS4_GATEUP_MIX names the mask file; the payload in LLMS_DS4_GATEUP_BS64 must be the COMPACT file make_bsmx_file.py wrote from the same two-plane input. Off unless set. */
static int gateup_mix_state = -2; static id<MTLBuffer> gateup_mix_mask; static uint32_t gateup_mix_layer; static uint64_t gateup_mix_calls;
static int gateup_mix_on(void) {
    if (gateup_mix_state > -2) return gateup_mix_state;
    gateup_mix_state = 0;
    const char *e = getenv("LLMS_DS4_GATEUP_MIX"), *src = getenv("DS4_METAL_MOE_SOURCE");
    if (!e || !*e || !strcmp(e, "0")) return 0;
    if (!(src && llms_srckey(src, "_bsmx") != NULL)) { fprintf(stderr, "llms: LLMS_DS4_GATEUP_MIX refused: DS4_METAL_MOE_SOURCE does not name a *_bsmx source\n"); exit(2); }
    if (gateup_side_on() <= 0 || !bs64_side_format) { fprintf(stderr, "llms: LLMS_DS4_GATEUP_MIX refused: it needs the BS64 side file on\n"); exit(2); }
    FILE *fp = fopen(e, "rb"); const size_t want = 16u + 40u * 384u * 16u; unsigned char *buf = malloc(want); size_t got = fp ? fread(buf, 1, want, fp) : 0; if (fp) fclose(fp);
    uint32_t h[3]; if (got == want) memcpy(h, buf + 4, sizeof h);
    if (got != want || memcmp(buf, "BSMK", 4) != 0 || h[0] != 1u || h[1] != 40u || h[2] != 384u) { fprintf(stderr, "llms: LLMS_DS4_GATEUP_MIX refused: %s is not a BSMK mask file\n", e); exit(2); }
    gateup_mix_mask = [g_device newBufferWithBytes:buf length:want options:MTLResourceStorageModeShared]; free(buf);
    if (!gateup_mix_mask) { fprintf(stderr, "llms: LLMS_DS4_GATEUP_MIX: mask buffer allocation failed\n"); exit(2); }
    gateup_mix_state = 1;
