    if (!(src && llms_srckey(src, "_g32d") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_DOWN_G32 ignored: DS4_METAL_MOE_SOURCE does not name a *_g32d* source\n"), LLMS_G_NAME); return 0; }
    const int fd = open(e, O_RDONLY | O_CLOEXEC);
    if (fd < 0) { fprintf(stderr, "llms: LLMS_DS4_DOWN_G32 ignored: cannot open %s\n", e); return 0; }
