        unsigned char a[64], b[64]; int nz = 0;
        if (pread(fd, a, 64, (off_t)(u64[2] + L * u64[1])) != 64 || pread(fd, b, 64, (off_t)(u64[2] + (L + 1ull) * u64[1] - 64ull)) != 64) nz = -1;
        else { for (int i = 0; i < 64; i++) nz |= a[i] | b[i]; }
