static id<MTLComputePipelineState> doorbell_pipeline; static id<MTLBuffer> doorbell_flag_buffer, doorbell_status_buffer; static volatile uint32_t *doorbell_flag; static int doorbell_state = -1;
uint32_t ds4_gpu_llms_db_polls(void) { return doorbell_status_buffer ? ((const volatile uint32_t *)[doorbell_status_buffer contents])[1] : 0u; }   /* llms VSPLIT6: the GPU's doorbell polls so far (wraps at 2^32) */
