    for (uint32_t k = 0; k < 65536u; k++) { if (!r[k]) continue; const uint32_t p = r[k] - 1u, l = doorbell_hist_layer[k] < 64u ? doorbell_hist_layer[k] : 63u; n++; tot += p; if (p > 1000u) big3 += p; if (p > 10000u) big4 += p;
        int b = 0; while (b < 32 && (1u << b) <= p) b++; lg[b]++; if (doorbell_hist_counts[l] < 4096u) v[l][doorbell_hist_counts[l]++] = p; }
    fprintf(stderr, "llms doorbell hist: %llu waits, %llu polls (%.1f us at 0.327 us per poll), mean %.1f polls; polls in waits > 1,000: %.1f %%, > 10,000: %.1f %%\n", (unsigned long long)n, (unsigned long long)tot,
            (double)tot * 0.327, n ? (double)tot / (double)n : 0.0, tot ? 100.0 * (double)big3 / (double)tot : 0.0, tot ? 100.0 * (double)big4 / (double)tot : 0.0);
    fprintf(stderr, "llms doorbell hist log2 (bin b: 2^(b-1) <= polls < 2^b; bin 0 = 0 polls):"); for (int b = 0; b <= 32; b++) if (lg[b]) fprintf(stderr, " %d:%llu", b, (unsigned long long)lg[b]); fprintf(stderr, "\n");
