static void topk_descending(const float *s, uint32_t n, uint32_t k, int32_t *out) {   /* descending, first index wins ties (topk_desc) */
    for (uint32_t i = 0; i < k; i++) out[i] = -1;
    for (uint32_t e = 0; e < n; e++) {
        const float v = s[e]; uint32_t pos = k;
        while (pos > 0 && (out[pos - 1] < 0 || v > s[out[pos - 1]])) pos--;
        if (pos >= k) continue;
        for (uint32_t j = k - 1; j > pos; j--) out[j] = out[j - 1];
        out[pos] = (int32_t)e;
    }
}
