static void report_keepbusy_thermal(void) {
    fprintf(stderr, "llms kb thermal: %llu touches gated, %llu open, last zone share %.2f, %llu samples\n", (unsigned long long)keepbusy_gated,
            (unsigned long long)keepbusy_open, (double)thermal_zone, (unsigned long long)thermal_samples);
