#include <mach/mach.h>
static void report_thread_cpu(void) {   /* llms THREAD_CPU (apply_thread_cpu.py) */
    thread_act_array_t th = NULL; mach_msg_type_number_t n = 0;
    if (task_threads(mach_task_self(), &th, &n) != KERN_SUCCESS) return;
    double us[256], ss[256]; char nm[256][64]; unsigned k = 0; double tot = 0.0;
    for (mach_msg_type_number_t i = 0; i < n && k < 256; i++) {
        thread_basic_info_data_t bi; mach_msg_type_number_t c1 = THREAD_BASIC_INFO_COUNT;
        thread_extended_info_data_t xi; mach_msg_type_number_t c2 = THREAD_EXTENDED_INFO_COUNT;
        if (thread_info(th[i], THREAD_BASIC_INFO, (thread_info_t)&bi, &c1) != KERN_SUCCESS) continue;
        nm[k][0] = 0; if (thread_info(th[i], THREAD_EXTENDED_INFO, (thread_info_t)&xi, &c2) == KERN_SUCCESS) { strncpy(nm[k], xi.pth_name, 63); nm[k][63] = 0; }
        us[k] = bi.user_time.seconds + bi.user_time.microseconds * 1e-6; ss[k] = bi.system_time.seconds + bi.system_time.microseconds * 1e-6; tot += us[k] + ss[k]; k++;
    }
    for (mach_msg_type_number_t i = 0; i < n; i++) mach_port_deallocate(mach_task_self(), th[i]);
    vm_deallocate(mach_task_self(), (vm_address_t)th, n * sizeof(thread_act_t));
    unsigned ord[256]; for (unsigned i = 0; i < k; i++) ord[i] = i;
    for (unsigned i = 0; i < k; i++) for (unsigned j = i + 1; j < k; j++) if (us[ord[j]] + ss[ord[j]] > us[ord[i]] + ss[ord[i]]) { unsigned x = ord[i]; ord[i] = ord[j]; ord[j] = x; }
    fprintf(stderr, "llms thread cpu: %u threads, %.2f s CPU in total (user + system); the busiest:\n", k, tot);
    for (unsigned i = 0; i < k && i < 12; i++) fprintf(stderr, "llms thread cpu:   %-24s user %8.3f s  system %7.3f s\n", nm[ord[i]][0] ? nm[ord[i]] : "(unnamed)", us[ord[i]], ss[ord[i]]);
}
__attribute__((constructor)) static void arm_thread_cpu(void) { const char *e = getenv("LLMS_DS4_THREAD_CPU"); if (e && *e && *e != '0') { pthread_setname_np("main"); atexit(report_thread_cpu); } }
static void *thermal_thread(void *arg) { pthread_setname_np("llms.kbt");   /* llms THREAD_CPU */
    (void)arg;
    void *h = dlopen("/usr/lib/libIOReport.dylib", RTLD_NOW);
    if (!h) { fprintf(stderr, "llms: kb thermal -- libIOReport not loadable; the gate stays open\n"); return NULL; }
    CFDictionaryRef (*copy_ch)(CFStringRef, CFStringRef, uint64_t, uint64_t, uint64_t) = dlsym(h, "IOReportCopyChannelsInGroup");
    void *(*create_sub)(void *, CFMutableDictionaryRef, CFMutableDictionaryRef *, uint64_t, CFTypeRef) = dlsym(h, "IOReportCreateSubscription");
    CFDictionaryRef (*samples)(void *, CFMutableDictionaryRef, CFTypeRef) = dlsym(h, "IOReportCreateSamples");
    CFDictionaryRef (*delta_of)(CFDictionaryRef, CFDictionaryRef, CFTypeRef) = dlsym(h, "IOReportCreateSamplesDelta");
    CFStringRef (*ch_sub)(CFDictionaryRef) = dlsym(h, "IOReportChannelGetSubGroup");
    CFStringRef (*ch_name)(CFDictionaryRef) = dlsym(h, "IOReportChannelGetChannelName");
    int (*ch_fmt)(CFDictionaryRef) = dlsym(h, "IOReportChannelGetFormat");
    int32_t (*st_count)(CFDictionaryRef) = dlsym(h, "IOReportStateGetCount");
    CFStringRef (*st_name)(CFDictionaryRef, int32_t) = dlsym(h, "IOReportStateGetNameForIndex");
    int64_t (*st_res)(CFDictionaryRef, int32_t) = dlsym(h, "IOReportStateGetResidency");
    if (!copy_ch || !create_sub || !samples || !delta_of || !ch_sub || !ch_name || !ch_fmt || !st_count || !st_name || !st_res) {
        fprintf(stderr, "llms: kb thermal -- an IOReport symbol is missing; the gate stays open\n"); return NULL; }
    CFDictionaryRef ch = copy_ch(CFSTR("GPU Stats"), NULL, 0, 0, 0);
    if (!ch) { fprintf(stderr, "llms: kb thermal -- no 'GPU Stats' channels; the gate stays open\n"); return NULL; }
    CFMutableDictionaryRef want = CFDictionaryCreateMutableCopy(NULL, 0, ch), subbed = NULL; CFRelease(ch);
    void *sub = create_sub(NULL, want, &subbed, 0, NULL);
    if (!sub) { fprintf(stderr, "llms: kb thermal -- IOReportCreateSubscription failed; the gate stays open\n"); return NULL; }
    CFDictionaryRef prev = samples(sub, subbed, NULL);
    for (;;) {
        sleep(1);
