            id<MTLFunction> fn = lib ? [lib newFunctionWithName:@"llms_kb"] : nil;
            keepbusy_pipeline = fn ? [g_device newComputePipelineStateWithFunction:fn error:&err] : nil;
            keepbusy_queue = [g_device newCommandQueue];
            keepbusy_buffer = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
            if (keepbusy_pipeline && keepbusy_queue && keepbusy_buffer) { keepbusy_iterations = atoi(e); atexit(report_keepbusy); fprintf(stderr, "llms: keepbusy on (%d multiply-adds per filler dispatch, second queue)\n", keepbusy_iterations); }
