        gpu_ledger_entry *full_copy = NULL;   /* llms LEDGER_DUMP_FULL: copy once, at the fill, under the lock */
        if (ledger_dump_full_state == 1 && gpu_ledger_count == GPU_LEDGER_MAX) { ledger_dump_full_state = 2; full_copy = malloc((size_t)GPU_LEDGER_MAX * sizeof(gpu_ledger_entry));
                                                                                if (full_copy) memcpy(full_copy, gpu_ledger, (size_t)GPU_LEDGER_MAX * sizeof(gpu_ledger_entry)); }
        os_unfair_lock_unlock(&gpu_ledger_lock);
