            char p[1024]; snprintf(p, sizeof p, "%s.full", gpu_ledger_dump_path); FILE *f = fopen(p, "w");
            if (f) { for (uint32_t i = 0; i < GPU_LEDGER_MAX; i++) { const gpu_ledger_entry *e = &full_copy[i];
                         fprintf(f, "B %u %u %u %.6f %.6f %.6f %d %u %d\n", e->tag >> 16, (e->tag >> 8) & 0xFFu, e->tag & 0xFFu, e->commit, e->start, e->end, e->unit, e->step, e->ugrp); }
                     fclose(f); fprintf(stderr, "llms ledger dump full: %u buffers -> %s\n", (unsigned)GPU_LEDGER_MAX, p); }
