}
static volatile int decode_cycle_now;   /* set by ds4.c around each speculative decode cycle (ds4_gpu_llms_decode_cycle); MAINWFE reads it -- renamed from the bridge's decode flag (S1 10-26) */
static volatile double decode_cycle_end_ms;   /* llms KWIDLE: the last decode cycle's end (ds4_gpu_now_ms) */
void ds4_gpu_llms_decode_cycle(int on) { decode_cycle_now = on; if (!on) decode_cycle_end_ms = ds4_gpu_now_ms(); }


/* llms CLOCK_KEEP (apply_clock_keep.py, 10-29 03:5x): a thread that wakes every P us while the engine waits for the GPU, so the P-cluster's clock is up when the waiting thread resumes host work (policy_bench_keeper.c: the call after an 8-ms sleep 414-557 -> 106 us with a usleep(50) waker). LLMS_DS4_CLOCK_KEEP=P[,1] (',1': prefill only). Off unless set. The thread only sleeps and counts. */
static volatile uint64_t ck_activity; static uint64_t ck_wakes, ck_idle_slices, ck_decode_slices; static int ck_period_us, ck_pf_only;
static void *ck_thread_main(void *arg) {
    (void)arg; pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0);
    uint64_t seen = ck_activity; double last_change = ds4_gpu_now_ms();
    for (;;) {
        const uint64_t a = ck_activity; const double t = ds4_gpu_now_ms();
        if (a != seen) { seen = a; last_change = t; }
        if (t - last_change > 100.0) { usleep(5000); ck_idle_slices++; continue; }   /* no engine wait for 100 ms: the engine is idle */
        if (ck_pf_only && decode_cycle_now) { usleep(2000); ck_decode_slices++; continue; }
        usleep((useconds_t)ck_period_us); ck_wakes++;
    }
    return NULL;
}
static void ck_start(void) {
    static int started; if (started) return; started = 1;
    const char *e = getenv("LLMS_DS4_CLOCK_KEEP"); if (!e || !*e || *e == '0') return;
    ck_period_us = atoi(e); if (ck_period_us < 10) ck_period_us = 10; if (ck_period_us > 5000) ck_period_us = 5000;
    const char *c = strchr(e, ','); ck_pf_only = c && atoi(c + 1) == 1;
    pthread_t th; pthread_attr_t at; pthread_attr_init(&at); pthread_attr_setdetachstate(&at, PTHREAD_CREATE_DETACHED);
    const int rc = pthread_create(&th, &at, ck_thread_main, NULL); pthread_attr_destroy(&at);
    fprintf(stderr, "llms: clock keep %d us%s (a waker thread while the engine waits for the GPU; rc %d)\n", ck_period_us, ck_pf_only ? ", prefill only" : "", rc);
    atexit_b(^{ fprintf(stderr, "llms clock keep: %llu wakes, %llu idle slices, %llu decode slices\n", (unsigned long long)ck_wakes, (unsigned long long)ck_idle_slices, (unsigned long long)ck_decode_slices); });
}

/* llms MAINWFE (apply_mainwfe.py): the decode cycle's owned batches end with a one-thread post; the main thread waits in WFE on it */
static int mainwfe_state = -1; static id<MTLBuffer> mainwfe_box; static id<MTLComputePipelineState> mainwfe_ps; static uint32_t mainwfe_seq;   /* llms SP_BCTX: mainwfe_want moved */
/* llms SP_BCTX: mainwfe_prev moved */ static uint64_t mainwfe_posts, mainwfe_waits, mainwfe_wakeups, mainwfe_fallbacks, mainwfe_skipped, mainwfe_deferred_errors, mainwfe_hist[6];
static double mainwfe_wait_ms, mainwfe_saved_ms;
/* llms SP_BCTX (b2): mainwfe_want_cb moved to struct sp_bctx */

static int mainwfe_pf_state = -1; static uint64_t mainwfe_pf_waits; static double mainwfe_pf_saved_ms;   /* llms MAINWFE_PF (apply_mainwfe_pf.py): outside decode cycles too */
static int mainwfe_pf_on(void) {
    if (mainwfe_pf_state >= 0) return mainwfe_pf_state;
    const char *e = getenv("LLMS_DS4_MAINWFE_PF"); mainwfe_pf_state = e && *e && *e != '0';
    if (mainwfe_pf_state) { fprintf(stderr, "llms: mainwfe pf (the post and the WFE wait outside decode cycles too: the prefill's per-layer waits)\n");
        atexit_b(^{ fprintf(stderr, "llms mainwfe pf: %llu waits outside decode cycles; post -> plain-wait return %.4f ms per such wait (check mode only)\n",
                            (unsigned long long)mainwfe_pf_waits, mainwfe_pf_waits ? mainwfe_pf_saved_ms / (double)mainwfe_pf_waits : 0.0); }); }
    return mainwfe_pf_state;
}
static int mainwfe_on(void) {
    if (mainwfe_state >= 0) return mainwfe_state;
    const char *e = getenv("LLMS_DS4_MAINWFE"); mainwfe_state = 0;
    if (e && *e && *e != '0' && g_device) {
        NSError *err = nil;
        id<MTLLibrary> lib = [g_device newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\nkernel void llms_mainwfe_post(device atomic_uint *box [[buffer(0)]], constant uint &v [[buffer(1)]], uint t [[thread_index_in_threadgroup]]) { if (t == 0) atomic_store_explicit(&box[0], v, memory_order_relaxed); }\n" options:nil error:&err];
        id<MTLFunction> fn = lib ? [lib newFunctionWithName:@"llms_mainwfe_post"] : nil;
        mainwfe_ps = fn ? [g_device newComputePipelineStateWithFunction:fn error:&err] : nil;
        mainwfe_box = [g_device newBufferWithLength:16384 options:MTLResourceStorageModeShared];
        if (mainwfe_ps && mainwfe_box) { memset(mainwfe_box.contents, 0, 16384); mainwfe_state = strcmp(e, "check") ? 1 : 2; }
        fprintf(stderr, mainwfe_state == 2 ? "llms: mainwfe CHECK (the post, the WFE wait, then the plain wait: the time the live mode would save per wait)\n"
                      : mainwfe_state ? "llms: mainwfe (the decode cycle's owned batches end with a post; the main thread waits in WFE on it, not in waitUntilCompleted)\n" : "llms: mainwfe -- setup failed; off\n");
        if (mainwfe_state) atexit_b(^{ const double n = mainwfe_waits ? (double)mainwfe_waits : 1.0;
            fprintf(stderr, "llms mainwfe: %llu posts, %llu waits (%.3f ms each in WFE, %.1f wake-ups each), %llu fallbacks, %llu batches not posted (substream / timeline encoder), %llu deferred errors; "
                            "post -> plain-wait return %.4f ms per wait [<25us %llu, <50 %llu, <100 %llu, <200 %llu, <400 %llu, more %llu]%s\n",
                    (unsigned long long)mainwfe_posts, (unsigned long long)mainwfe_waits, mainwfe_wait_ms / n, (double)mainwfe_wakeups / n, (unsigned long long)mainwfe_fallbacks,
                    (unsigned long long)mainwfe_skipped, (unsigned long long)mainwfe_deferred_errors, mainwfe_saved_ms / n, (unsigned long long)mainwfe_hist[0], (unsigned long long)mainwfe_hist[1],
                    (unsigned long long)mainwfe_hist[2], (unsigned long long)mainwfe_hist[3], (unsigned long long)mainwfe_hist[4], (unsigned long long)mainwfe_hist[5], mainwfe_state == 2 ? " (check)" : ""); });
    }
    return mainwfe_state;
}
static int doorbell_on(void);
static void note_wait_wake(id<MTLCommandBuffer> cb, double wait0) {
    if (gpu_ledger_on <= 0) return;
    const double now = uptime_s(), e = cb.GPUEndTime;
    if (e > 0.0) { ledger_wake_ms += (now - (e > wait0 ? e : wait0)) * 1e3; ledger_wakes++; }
}
static int compare_ledger_start(const void *a, const void *b) { const double x = ((const gpu_ledger_entry *)a)->start, y = ((const gpu_ledger_entry *)b)->start; return x < y ? -1 : x > y; }
static void report_gpu_ledger(void) {
    if (!gpu_ledger) return;
    os_unfair_lock_lock(&gpu_ledger_lock);
    qsort(gpu_ledger, gpu_ledger_count, sizeof(gpu_ledger_entry), compare_ledger_start);
    double busy = 0.0, sched = 0.0, starved = 0.0, overlap = 0.0, prev_end = 0.0, first = 0.0; uint32_t bad = 0, n = 0;
    double hs[5] = {0, 0, 0, 0, 0}; uint32_t hn[5] = {0, 0, 0, 0, 0};   /* starved gaps: < 0.5, 0.5-2, 2-5, 5-20, >= 20 ms */
    for (uint32_t i = 0; i < gpu_ledger_count; i++) {
        const gpu_ledger_entry *e = &gpu_ledger[i];
        if (!(e->start > 0.0 && e->end >= e->start) || e->start + 1e-3 < e->commit) { bad++; continue; }
        if (!n++) first = e->start;
        busy += e->end - e->start;
        if (prev_end > 0.0) {
            if (e->start < prev_end) overlap += (e->end < prev_end ? e->end : prev_end) - e->start;
            else if (e->commit <= prev_end) sched += e->start - prev_end;
            else { const double g = e->commit - prev_end; const int b = g < 0.5e-3 ? 0 : g < 2e-3 ? 1 : g < 5e-3 ? 2 : g < 20e-3 ? 3 : 4;
                   hs[b] += g; hn[b]++; starved += g; sched += e->start - e->commit; }
        }
        if (e->end > prev_end) prev_end = e->end;
    }
    fprintf(stderr, "llms gpu ledger: buffers %u bad %u dropped %llu busy %.1f ms sched-idle %.1f ms starved %.1f ms overlap %.1f ms span %.1f ms wake %.1f ms over %llu waits\n",
            n, bad, (unsigned long long)gpu_ledger_dropped, busy * 1e3, sched * 1e3, starved * 1e3, overlap * 1e3, (prev_end - first) * 1e3,
            ledger_wake_ms, (unsigned long long)ledger_wakes);
    fprintf(stderr, "llms gpu starved gaps: lt0.5ms %u %.1f ms | 0.5-2ms %u %.1f ms | 2-5ms %u %.1f ms | 5-20ms %u %.1f ms | ge20ms %u %.1f ms\n",
            hn[0], hs[0] * 1e3, hn[1], hs[1] * 1e3, hn[2], hs[2] * 1e3, hn[3], hs[3] * 1e3, hn[4], hs[4] * 1e3);
    if (gpu_ledger_dump_path) {   /* llms LEDGER_TAGS: per-layer table (whole run) and the dump */
        double lb[64] = {0}, ls[64] = {0}; uint32_t ln[64] = {0}; double pe = 0.0;
        for (uint32_t i = 0; i < gpu_ledger_count; i++) {
            const gpu_ledger_entry *e = &gpu_ledger[i]; const uint32_t layer = e->tag & 0xFFu, kind = e->tag >> 16;
            if (!(e->start > 0.0 && e->end >= e->start)) continue;
            if (layer < 64 && kind < 2) { lb[layer] += e->end - e->start; ln[layer]++; if (pe > 0.0 && e->commit > pe) ls[layer] += e->commit - pe; }
            if (e->end > pe) pe = e->end;
        }
        fprintf(stderr, "llms gpu ledger by layer (whole run; busy ms, starved-before ms, buffers):");
        for (int l = 0; l < 64; l++) if (ln[l]) fprintf(stderr, " L%d %.0f/%.0f/%u", l, lb[l] * 1e3, ls[l] * 1e3, ln[l]);
        fprintf(stderr, "\n");
        FILE *f = fopen(gpu_ledger_dump_path, "w");
        if (f) {
            for (uint32_t i = 0; i < gpu_ledger_count; i++) { const gpu_ledger_entry *e = &gpu_ledger[i];
                fprintf(f, "B %u %u %u %.6f %.6f %.6f %d %u %d\n", e->tag >> 16, (e->tag >> 8) & 0xFFu, e->tag & 0xFFu, e->commit, e->start, e->end, e->unit, e->step, e->ugrp); }   /* llms ALT2D: unit step group */
            for (uint32_t i = 0; i < ticket_ledger_count; i++) { const ticket_ledger_entry *t = &ticket_ledger[i];
                fprintf(f, "T %u %.6f %.6f %llu %llu %.6f %.6f\n", t->layer, t->issue, t->end, (unsigned long long)t->bytes, (unsigned long long)t->reads, t->w0, t->w1); }
            fclose(f); fprintf(stderr, "llms gpu ledger dump: %u buffers, %u tickets -> %s\n", gpu_ledger_count, ticket_ledger_count, gpu_ledger_dump_path);
        }
    }
    os_unfair_lock_unlock(&gpu_ledger_lock);
}
static void report_ops(void) { fprintf(stderr, "llms ops: %llu encoder calls, %llu owned commits (commit+wait), %llu all commits\n", (unsigned long long)ops_counted, (unsigned long long)commits_counted, (unsigned long long)all_commits); fprintf(stderr, "llms time: gpu-wait %.1f ms, pread %.1f ms, pread %.3f GB, load-wait %.1f ms\n", command_wait_ms, g_stream_expert_cache_pread_ms, (double)g_stream_expert_cache_read_bytes / 1e9, load_wait_total()); report_gpu_ledger(); fprintf(stderr, "llms cache: hits %llu misses %llu\n", (unsigned long long)g_stream_expert_cache_hits, (unsigned long long)g_stream_expert_cache_misses); }
static id<MTLComputeCommandEncoder> ds4_gpu_compute_encoder(id<MTLCommandBuffer> cb) {
    if (!ops_counted++ && getenv("LLMS_DS4_COUNT_OPS")) atexit(report_ops);
    if (g_batch_cb && cb == g_batch_cb) {
        g_batch_has_work = YES;
        if (g_timeline_enabled && (!g_timeline_batch || g_timeline_batch->cb != cb)) ds4_gpu_timeline_attach(cb);   /* llms TL_ATTACH: a batch cb made without an attach gets its own batch */
        if (g_timeline_enabled && g_timeline_batch) {
            /* Diagnostic: one timestamped pass per dispatch group. A
             * concurrent section keeps its single encoder. */
            if (g_batch_enc && !g_batch_encoder_concurrent && (!timeline_cb_only() || timeline_sample_wanted != timeline_sample_current)) {   /* llms TL_CBONLY 2: the live encoder structure kept; 3: split around the sampled wait */
                [g_batch_enc endEncoding];
                g_batch_enc = nil;
            }
            if (!g_batch_enc) {
                g_batch_enc = ds4_gpu_timeline_new_encoder(
                        cb, g_batch_encoder_concurrent,
                        (uintptr_t)__builtin_return_address(0));
            }
            if (g_batch_enc) return install_dispatch_hooks(g_batch_enc, cb);
        }
        if (!g_batch_enc) {
            if (conc_state < 0) { const char *e = getenv("LLMS_DS4_CONC"); conc_state = e && *e && *e != '0';   /* llms CONC */
                                   if (conc_state) { fprintf(stderr, "llms: conc (concurrent batch encoder, a barrier before every dispatch unless dropped)\n");
                                       atexit_b(^{ fprintf(stderr, "llms conc: %llu encoders, %llu barriers, %llu dropped\n", (unsigned long long)conc_encoders,
                                                   (unsigned long long)conc_barriers, (unsigned long long)conc_barriers_skipped); }); } }
            const int concurrent_auto = conc_state > 0 && !g_batch_encoder_concurrent && !g_timeline_enabled && !ds4_gpu_llms_alt_off("conc");
            if (substreams_n() > 0 && substreams_wanted && !g_batch_encoder_concurrent && !concurrent_auto && !g_timeline_enabled) {   /* llms DSP_SS: substreams_n */   /* llms SUBSTREAMS: only while the attention cone wants it (v4) */
                g_batch_enc = ((id(*)(id, SEL, NSUInteger, unsigned))objc_msgSend)(cb, sel_registerName("computeCommandEncoderWithDispatchType:substreamCount:"), (NSUInteger)MTLDispatchTypeSerial, (unsigned)substreams_n());
                substream_set = 0u; substream_encoders++; substreams_active = 1; substream_encoder_serial++;
            } else { substreams_active = 0;
            g_batch_enc = (g_batch_encoder_concurrent || concurrent_auto)
                ? [cb computeCommandEncoderWithDispatchType:MTLDispatchTypeConcurrent]
                : [cb computeCommandEncoder];
            concurrent_encoder = concurrent_auto; if (concurrent_auto) conc_encoders++; }
        }
        return install_dispatch_hooks(g_batch_enc, cb);
    }
    return install_dispatch_hooks([cb computeCommandEncoder], cb);
}

static void ds4_gpu_end_compute_encoder(id<MTLCommandBuffer> cb, id<MTLComputeCommandEncoder> enc) {
    if (!enc) return;
    if (g_batch_cb && cb == g_batch_cb && enc == g_batch_enc) return;
    [enc endEncoding];
}

static void ds4_gpu_close_batch_encoder(void) {
    if (!g_batch_enc) return;
    [g_batch_enc endEncoding];
    g_batch_enc = nil;
    concurrent_encoder = 0;   /* llms CONC */
}

static double g_gpu_busy_accum;
static uint64_t g_gpu_busy_cbs;

/* A failed command buffer can leave a cross-threadgroup arrival counter at an
 * arbitrary partial value.  Drop cached ownership instead of CPU-resetting
 * buffers that another in-flight command buffer might still reference; bound
 * resources remain retained by their command buffers/transient list. */
static void ds4_gpu_invalidate_completion_counters(void) {
    [g_dsv4_completion_cache removeAllObjects];
    g_dsv4_hc_producer_last_mix_buffer = nil;
    g_dsv4_hc_producer_last_mix_offset = 0;
    g_dsv4_hc_producer_last_completion = nil;
}

static int ds4_gpu_wait_command_buffer(id<MTLCommandBuffer> cb, const char *label) {
    ck_activity++;   /* llms CLOCK_KEEP */
    { const double wait_start = ds4_gpu_now_ms();   /* llms: the wait time (command_wait_ms); SPIN_WAIT culled 10-24 (cull_spin_wait.py: retired for harm) */
      [cb waitUntilCompleted];
      doorbell_fatal_check("after a command buffer wait");   /* llms DOORBELL */
      command_wait_ms += ds4_gpu_now_ms() - wait_start; }
    if (cached_getenv("DS4_METAL_CB_TIMES")) {
        static double prev_gpu_end;
        static uint64_t n_printed;
        static long cb_times_max = -1; if (cb_times_max < 0) { const char *e = getenv("LLMS_DS4_CB_TIMES_MAX"); cb_times_max = e && atol(e) > 0 ? atol(e) : 400; }   /* llms CB_TIMES_MAX */
        if ((long)n_printed < cb_times_max) {
            n_printed++;
            fprintf(stderr,
                    "ds4: cb %s: driver %.0f us, queue-wait %.0f us, gpu %.0f us, gap-from-prev-gpu-end %.0f us\n",
                    label,
                    (cb.kernelEndTime - cb.kernelStartTime) * 1e6,
                    (cb.GPUStartTime - cb.kernelEndTime) * 1e6,
                    (cb.GPUEndTime - cb.GPUStartTime) * 1e6,
                    prev_gpu_end ? (cb.GPUStartTime - prev_gpu_end) * 1e6 : 0.0);
        }
        prev_gpu_end = cb.GPUEndTime;
    }
    if (getenv("DS4_METAL_GPU_BUSY_PROFILE")) {
        const double busy = cb.GPUEndTime - cb.GPUStartTime;
        if (busy > 0) g_gpu_busy_accum += busy;
        if ((++g_gpu_busy_cbs % 64u) == 0u) {
            fprintf(stderr, "ds4: gpu busy accum %.1f ms over %llu cbs\n",
                    g_gpu_busy_accum * 1000.0,
                    (unsigned long long)g_gpu_busy_cbs);
        }
    }
    if (cb.status == MTLCommandBufferStatusError) {
        expert_server_abort = 1;   /* llms CB_LAZYABORT: the main thread saw the failure -- release the expert server (a no-op unless a buffer failed) */
        fprintf(stderr, "ds4: Metal %s failed: %s\n",
                label, [[cb.error localizedDescription] UTF8String]);
        ds4_gpu_invalidate_completion_counters();
        return 0;
    }
    return 1;
}

static id<MTLCommandBuffer> ds4_gpu_new_command_buffer(void) {
    static int initialized;
    static int use_unretained;
    if (!initialized) {
        use_unretained = getenv("DS4_METAL_UNRETAINED_COMMAND_BUFFERS") != NULL;
        initialized = 1;
    }
    id<MTLCommandBuffer> command_buffer_made = use_unretained ? [g_queue commandBufferWithUnretainedReferences] : [g_queue commandBuffer];
    {   /* llms CB_LABEL: engine buffers labelled 'ds4' so a Metal System Trace separates them from keepbusy's */
        static int command_buffer_label_state = -1; if (command_buffer_label_state < 0) { const char *e = getenv("LLMS_DS4_CB_LABEL"); command_buffer_label_state = e && *e && *e != '0'; if (command_buffer_label_state) fprintf(stderr, "llms: cb label (engine command buffers 'ds4', keepbusy's 'llms_kb')\n"); }
        if (command_buffer_label_state && command_buffer_made) command_buffer_made.label = @"ds4";
    }

    static int cb_nohandler_state = -1;   /* llms CB_NOHANDLER (2026-10-24 13:3x): a MEASUREMENT switch -- LLMS_DS4_CB_NOHANDLER=1 skips the EDF_ABORT completed handler on steps whose ALT 'cbh' is on (with LLMS_DS4_ALTW cbh:r50, half the steps): does a per-buffer handler cost GPU time at the 44 boundaries? */
    if (cb_nohandler_state < 0) { const char *e = getenv("LLMS_DS4_CB_NOHANDLER"); cb_nohandler_state = e && *e && *e != '0';
                                  if (cb_nohandler_state) fprintf(stderr, "llms: cb nohandler (the EDF_ABORT completed handler skipped on ALT 'cbh'-on steps; a MEASUREMENT switch)\n"); }
    if (command_buffer_made && !(cb_nohandler_state > 0 && !llms_alt_off("cbh")) && !cb_lazyabort_on()) [command_buffer_made addCompletedHandler:^(id<MTLCommandBuffer> d) { if (d.status == MTLCommandBufferStatusError) expert_server_abort = 1; }];   /* llms EDF_ABORT */
    return command_buffer_made;
}

static uint64_t ds4_gpu_exact_view_cache_limit_bytes(void) {
    static int initialized;
    static uint64_t limit_bytes;
    if (initialized) return limit_bytes;

    const uint64_t mib = 1024ull * 1024ull;
    const uint64_t gib = 1024ull * mib;
    limit_bytes = 64ull * gib;

    const char *gib_env = getenv("DS4_METAL_EXACT_VIEW_CACHE_GIB");
    if (gib_env && gib_env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(gib_env, &end, 10);
        if (end != gib_env && *end == '\0') {
            limit_bytes = v > UINT64_MAX / gib ? UINT64_MAX : (uint64_t)v * gib;
        }
    }

    const char *mib_env = getenv("DS4_METAL_EXACT_VIEW_CACHE_MIB");
    if (mib_env && mib_env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(mib_env, &end, 10);
        if (end != mib_env && *end == '\0') {
            limit_bytes = v > UINT64_MAX / mib ? UINT64_MAX : (uint64_t)v * mib;
        }
    }

    initialized = 1;
    return limit_bytes;
}

static void ds4_gpu_model_buffer_cache_note_insert(uint64_t bytes) {
    if (g_model_buffer_cache_bytes > UINT64_MAX - bytes) {
        g_model_buffer_cache_bytes = UINT64_MAX;
    } else {
        g_model_buffer_cache_bytes += bytes;
    }

    const uint64_t limit = ds4_gpu_exact_view_cache_limit_bytes();
    if (limit != 0 && g_model_buffer_cache_bytes > limit) {
        g_model_buffer_cache_over_limit = 1;
    }
}

static void ds4_gpu_model_buffer_cache_clear(const char *reason) {
    if (!g_model_buffer_cache) {
        g_model_buffer_cache_bytes = 0;
        g_model_buffer_cache_over_limit = 0;
        return;
    }

    const NSUInteger entries = [g_model_buffer_cache count];
    if (entries != 0) {
        if (getenv("DS4_METAL_EXACT_VIEW_CACHE_PROFILE") != NULL) {
            fprintf(stderr,
                    "ds4: Metal exact model view cache evict reason=%s entries=%lu bytes=%.2f GiB limit=%.2f GiB\n",
                    reason ? reason : "unknown",
                    (unsigned long)entries,
                    ds4_gpu_gib(g_model_buffer_cache_bytes),
                    ds4_gpu_gib(ds4_gpu_exact_view_cache_limit_bytes()));
        }
        [g_model_buffer_cache removeAllObjects];
        g_model_buffer_cache_evictions++;
    }
    g_model_buffer_cache_bytes = 0;
    g_model_buffer_cache_over_limit = 0;
}

static void ds4_gpu_model_buffer_cache_maybe_evict(const char *reason) {
    if (g_model_buffer_cache_over_limit) {
        ds4_gpu_model_buffer_cache_clear(reason);
    }
}

static uint64_t ds4_gpu_stream_expert_cache_next_cb_seq(void) {
    if (g_stream_expert_cache_cb_seq == UINT64_MAX) {
        /*
         * A real wrap would require an astronomical number of command buffers.
         * Resetting the epoch space is still safer than letting zero become a
         * valid in-flight marker.
         */
        g_stream_expert_cache_cb_seq = 0;
        g_stream_expert_cache_done_seq = 0;
        g_stream_expert_cache_batch_seq = 0;
        g_stream_expert_cache_owned_seq = 0;
        g_stream_expert_cache_pending_max_seq = 0;
        for (uint32_t layer = 0; layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER; layer++) {
            for (uint32_t expert = 0; expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT; expert++) {
                g_stream_expert_cache[layer][expert].inflight_seq = 0;
            }
        }
    }
    return ++g_stream_expert_cache_cb_seq;
}

static void ds4_gpu_stream_expert_cache_note_batch_created(void) {
    g_stream_expert_cache_batch_seq =
        ds4_gpu_stream_expert_cache_next_cb_seq();
    if (!sp_bcur->sp_live_lo) sp_bcur->sp_live_lo = g_stream_expert_cache_batch_seq; sp_bcur->sp_live_hi = g_stream_expert_cache_batch_seq;   /* llms SP_BATON b3 */
}

static void ds4_gpu_stream_expert_cache_note_batch_committed(void) {
    if (g_stream_expert_cache_batch_seq > g_stream_expert_cache_pending_max_seq) {
        g_stream_expert_cache_pending_max_seq = g_stream_expert_cache_batch_seq;
    }
    g_stream_expert_cache_batch_seq = 0;
}

static void ds4_gpu_stream_expert_cache_note_owned_created(void) {
    g_stream_expert_cache_owned_seq =
        ds4_gpu_stream_expert_cache_next_cb_seq();
    if (!sp_bcur->sp_live_lo) sp_bcur->sp_live_lo = g_stream_expert_cache_owned_seq; sp_bcur->sp_live_hi = g_stream_expert_cache_owned_seq;   /* llms SP_BATON b3 */
}

static void ds4_gpu_stream_expert_cache_note_pending_completed(void) {
    if (g_stream_expert_cache_pending_max_seq > g_stream_expert_cache_done_seq) {
        g_stream_expert_cache_done_seq = g_stream_expert_cache_pending_max_seq;
    }
    g_stream_expert_cache_pending_max_seq = 0;
}

static void ds4_gpu_stream_expert_cache_note_owned_completed(void) {
    if (g_stream_expert_cache_owned_seq > g_stream_expert_cache_done_seq) {
        g_stream_expert_cache_done_seq = g_stream_expert_cache_owned_seq;
    }
    g_stream_expert_cache_owned_seq = 0;
    if (!g_pending_cbs || [g_pending_cbs count] == 0) { sp_bcur->sp_live_lo = g_stream_expert_cache_batch_seq; sp_bcur->sp_live_hi = g_stream_expert_cache_batch_seq; }   /* llms SP_BATON b3: only the open batch (if any) stays live */
}

/* llms PFU_PRECISE (apply_plag_precise.py): the PFU guard waits only for the ticket of the layer a call prepares; an * entry whose PFU read is still landing (entry_read_ticket above the settled ticket) is never an eviction victim. LLMS_DS4_PFU_PRECISE=1. */
static uint64_t entry_read_ticket[DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER][DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
static uint64_t prefill_prefetch_ticket_of_layer[DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER];
static uint64_t landing_victims_skipped, landing_settles, prefill_prefetch_precise_waits; static double prefill_prefetch_precise_wait_ms; static uint32_t prefill_prefetch_cap_override;
static uint64_t tickets_settled_count(void);
static int prefill_prefetch_waits_precise(void) {
    static int c = -1;
    if (c < 0) { const char *e = getenv("LLMS_DS4_PFU_PRECISE"); c = e && *e && *e != '0';
                 if (c) { fprintf(stderr, "llms: pfu precise (the PFU guard waits for the prepared layer's ticket only; landing entries are never evicted)\n");
                          atexit_b(^{ fprintf(stderr, "llms pfu precise: %llu guard waits (%.1f ms), %llu victims skipped while their read landed, %llu full settles\n",
                                             (unsigned long long)prefill_prefetch_precise_waits, prefill_prefetch_precise_wait_ms, (unsigned long long)landing_victims_skipped, (unsigned long long)landing_settles); }); } }
    return c;
}
static int expert_read_busy(uint32_t layer, uint32_t expert) {
    if (!prefill_prefetch_waits_precise() || layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER || expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) return 0;
    const uint64_t k = entry_read_ticket[layer][expert]; if (k == 0 || k <= tickets_settled_count()) return 0;
    landing_victims_skipped++; return 1;
}
static int ds4_gpu_stream_expert_cache_entry_inflight(
        const ds4_gpu_stream_expert_cache_entry *e) {
    if (e && e->valid && sp_bctx_baton && e->inflight_seq) {   /* llms SP_BATON b3: inside either context's unfinished range */
        const uint64_t q = e->inflight_seq;
        if ((sp_bctx0.sp_live_lo && q >= sp_bctx0.sp_live_lo && q <= sp_bctx0.sp_live_hi) || (sp_bctx1.sp_live_lo && q >= sp_bctx1.sp_live_lo && q <= sp_bctx1.sp_live_hi)) return 1;
    }
    return e && e->valid && e->inflight_seq > g_stream_expert_cache_done_seq;
}

static int ds4_gpu_stream_expert_cache_mark_inflight(
        ds4_gpu_stream_expert_cache_entry *e) {
    if (!e || !e->valid) return 0;
    const uint64_t seq = g_stream_expert_cache_batch_seq ?
                         g_stream_expert_cache_batch_seq :
                         g_stream_expert_cache_owned_seq;
    if (seq == 0) return 0;
    e->inflight_seq = seq;
    return 1;
}

static int ds4_gpu_stream_expert_cache_mark_entries_inflight(
        ds4_gpu_stream_expert_cache_entry * const *entries,
        uint32_t n_entries,
        uint32_t active_mask) {
    if (!entries || n_entries == 0) return 0;
    for (uint32_t i = 0; i < n_entries; i++) {
        if (active_mask != 0 && (active_mask & (1u << i)) == 0) continue;
        if (!ds4_gpu_stream_expert_cache_mark_inflight(entries[i])) return 0;
    }
    return 1;
}

static int ds4_gpu_stream_expert_cache_wait_inflight(const char *label);

static int quiesce_install_state = -1; static void quiesce_gpu_policy(void);   /* llms Z9 D1 (defined with the Z9 kernel) */
static int quiesce_deferred;   /* llms Z9 QUIESCE ORDER (apply_z9_quiesce_order.py): set by finish_command_buffer while its CURRENT buffer is in flight */
static int ds4_gpu_wait_pending_command_buffers(const char *label) {
    int ok = 1;
    for (id<MTLCommandBuffer> pending in g_pending_cbs) {
        if (!ds4_gpu_wait_command_buffer(pending, label)) ok = 0;
    }
    [g_pending_cbs removeAllObjects];
    ds4_gpu_stream_expert_cache_note_pending_completed();
    if (quiesce_install_state != 0 && !quiesce_deferred) quiesce_gpu_policy();   /* llms Z9 QUIESCE ORDER: not while finish's current buffer runs */   /* -1: unread */   /* llms Z9 D1: no command buffer in flight */
    if (!ok) ds4_gpu_invalidate_zero_prefix_prefill_block_maps();
    return ok;
}

/* llms SP_BCTX (b3): g_batch_cb_created_ms moved to struct sp_bctx */
static double ds4_gpu_now_ms(void);
static void ds4_gpu_queue_keepalive_start(void);
static void ds4_gpu_queue_keepalive_stop_thread(void);
#include <mach-o/dyld.h>   /* llms SYNC_SITES */
static int sync_sites_state = -1; static void *sync_site_caller[64], *sync_site_caller2[64]; static const char *sync_site_label[64]; static uint64_t sync_site_count[64]; static int sync_sites_known;
static void report_sync_sites(void) {
    fprintf(stderr, "llms sync sites (waited commits by label and caller; main image slide 0x%lx):\n", (unsigned long)_dyld_get_image_vmaddr_slide(0));
    for (int r = 0; r < 20; r++) { int b = -1; for (int i = 0; i < sync_sites_known; i++) if (sync_site_count[i] && (b < 0 || sync_site_count[i] > sync_site_count[b])) b = i;
        if (b < 0) break; fprintf(stderr, "  %8llu  %-24s caller %p  caller2 %p\n", (unsigned long long)sync_site_count[b], sync_site_label[b] ? sync_site_label[b] : "-", sync_site_caller[b], sync_site_caller2[b]); sync_site_count[b] = 0; }
}
static void note_sync_site(const char *label, void *ra, void *ra2) {
    if (sync_sites_state < 0) { sync_sites_state = getenv("LLMS_DS4_SYNC_SITES") != NULL; if (sync_sites_state) atexit(report_sync_sites); }
    if (!sync_sites_state) return;
    for (int i = 0; i < sync_sites_known; i++) if (sync_site_caller[i] == ra && sync_site_caller2[i] == ra2 && sync_site_label[i] == label) { sync_site_count[i]++; return; }
    if (sync_sites_known < 64) { sync_site_caller[sync_sites_known] = ra; sync_site_caller2[sync_sites_known] = ra2; sync_site_label[sync_sites_known] = label; sync_site_count[sync_sites_known++] = 1; }
}
static void (*sp_baton_release_fn)(void), (*sp_baton_acquire_fn)(void);   /* llms SP_BATON b2: set by ds4.c in pair mode (stage C) */
static int mainwfe_finish(id<MTLCommandBuffer> cb, uint32_t want, const char *label) {   /* llms MAINWFE */
    ck_activity++;   /* llms CLOCK_KEEP */
    if (mainwfe_prev) { id<MTLCommandBuffer> p = mainwfe_prev; mainwfe_prev = nil;   /* the previous posted batch: completed long ago; its status now */
        if (!ds4_gpu_wait_command_buffer(p, "mainwfe deferred")) { mainwfe_deferred_errors++; expert_server_abort = 1; fprintf(stderr, "llms mainwfe: a DEFERRED batch FAILED -- its results were already consumed\n"); }
    }
    if (!want) return ds4_gpu_wait_command_buffer(cb, label);
    volatile uint32_t *box = (volatile uint32_t *)mainwfe_box.contents;
    const double w0 = ds4_gpu_now_ms(); uint64_t it = 0; int got = 0;
    for (;;) {
        uint32_t v; __asm__ volatile("ldaxr %w0, [%1]" : "=r"(v) : "r"(box) : "memory");
        if (v == want) { got = 1; break; }
        if (sp_baton_release_fn && cb.status >= MTLCommandBufferStatusCompleted) { got = 1; break; }   /* llms SP_BATON b2: complete already (the other call may have posted later) */
        if ((++it & 63u) == 0u) { if (cb.status >= MTLCommandBufferStatusCompleted) break; if (ds4_gpu_now_ms() - w0 > 2000.0) break; }
        __asm__ volatile("wfe" ::: "memory");
    }
    __asm__ volatile("clrex" ::: "memory");
    const double w1 = ds4_gpu_now_ms(); command_wait_ms += w1 - w0; mainwfe_wait_ms += w1 - w0; mainwfe_waits++; mainwfe_wakeups += it;
    const int mw_pf = !decode_cycle_now; if (mw_pf) mainwfe_pf_waits++;   /* llms MAINWFE_PF */
    if (!got) { mainwfe_fallbacks++; return ds4_gpu_wait_command_buffer(cb, label); }
    if (mainwfe_state == 2) { const int r = ds4_gpu_wait_command_buffer(cb, label); const double d = ds4_gpu_now_ms() - w1; mainwfe_saved_ms += d; if (mw_pf) mainwfe_pf_saved_ms += d;
                              mainwfe_hist[d < 0.025 ? 0 : d < 0.05 ? 1 : d < 0.1 ? 2 : d < 0.2 ? 3 : d < 0.4 ? 4 : 5]++; return r; }
    doorbell_fatal_check("after a mainwfe post");
    mainwfe_prev = cb;   /* its status is read at the next finish */
    return 1;
}
void ds4_gpu_llms_set_baton(void (*rel)(void), void (*acq)(void)) { sp_baton_release_fn = rel; sp_baton_acquire_fn = acq; }
void ds4_gpu_llms_baton_window(int on) { sp_bcur->sp_baton_window = on; }   /* llms SP_BATON b4 */
void ds4_gpu_llms_bctx_select(int k) {   /* llms SP_BATON b3: the backend context of the call that holds the baton */
    sp_bcur = k ? &sp_bctx1 : &sp_bctx0;
    if (k) { sp_bctx_baton = 1; if (!g_pending_cbs) g_pending_cbs = [NSMutableArray array]; }   /* the macro names sp_bcur's member: select first */
}
static int ds4_gpu_finish_command_buffer(id<MTLCommandBuffer> cb, int owned, const char *label) {
    if (owned) note_sync_site(label, __builtin_return_address(0), __builtin_frame_address(1) ? __builtin_return_address(1) : NULL);   /* llms SYNC_SITES */
    if (!owned) return 1;
    commits_counted++;   /* llms COUNT_OPS: owned command buffers = commit + full wait */

    const double t_commit = ds4_gpu_now_ms();
    const uint32_t mw_want = mainwfe_want; mainwfe_want = 0;   /* llms MAINWFE: end_commands posted this batch's end */
    track_command_buffer(cb); llms_order_commit(cb); all_commits++;
    if (sp_baton_release_fn && sp_baton_acquire_fn && sp_bcur->sp_baton_window) {   /* llms SP_BATON b2 (+ b4: only inside the policy point's window): the pure wait without the baton -- the call's own buffers only, no shared state */
        NSArray<id<MTLCommandBuffer>> *own = g_pending_cbs ? [g_pending_cbs copy] : nil;
        sp_baton_release_fn();
        for (id<MTLCommandBuffer> p in own) [p waitUntilCompleted];
        [cb waitUntilCompleted];
        sp_baton_acquire_fn();
    }
    quiesce_deferred = 1;   /* llms Z9 QUIESCE ORDER: the older buffers' wait must not quiesce while cb runs */
    int ok = ds4_gpu_wait_pending_command_buffers(label);
    quiesce_deferred = 0;
    if (!mainwfe_finish(cb, mw_want, label)) {   /* llms MAINWFE: the post's WFE wait when end_commands posted this batch; else the plain wait */
        ok = 0;
        ds4_gpu_invalidate_zero_prefix_prefill_block_maps();
    }
    if (quiesce_install_state != 0) quiesce_gpu_policy();   /* llms Z9 QUIESCE ORDER: now nothing is in flight */
    if (cached_getenv("DS4_METAL_CB_TIMES")) {
        const double t_done = ds4_gpu_now_ms();
        struct timespec ts_mono;
        clock_gettime(CLOCK_MONOTONIC, &ts_mono);
        const double mono_ms = (double)ts_mono.tv_sec * 1e3 + (double)ts_mono.tv_nsec / 1e6;
        fprintf(stderr, "ds4: cb '%s': mono %.1f ms: ", label ? label : "?", mono_ms);
        fprintf(stderr, "encode %.1f ms, commit->done %.1f ms, gpu span %.1f ms, gpu start +%.1f ms, caller 0x%llx\n",
                t_commit - g_batch_cb_created_ms, t_done - t_commit,
                (cb.GPUEndTime - cb.GPUStartTime) * 1e3,
                cb.GPUStartTime * 1e3 - (mono_ms - (t_done - t_commit)),
                (unsigned long long)((uintptr_t)__builtin_return_address(0) - (uintptr_t)_dyld_get_image_vmaddr_slide(0)));
        if (t_done - t_commit > 100.0 && (cb.GPUEndTime - cb.GPUStartTime) * 1e3 < 10.0) {
            void *frames[12];
            const int n = backtrace(frames, 12);
            fprintf(stderr, "ds4: cb stall backtrace:");
            for (int i = 1; i < n; i++)
                fprintf(stderr, " 0x%llx", (unsigned long long)((uintptr_t)frames[i] - (uintptr_t)_dyld_get_image_vmaddr_slide(0)));
            fprintf(stderr, "\n");
        }
    }
    ds4_gpu_stream_expert_cache_note_owned_completed();
    if (cached_getenv("DS4_METAL_CB_TIMES")) {
        uint64_t bytes = 0;
        for (id<MTLBuffer> b in g_transient_buffers) bytes += [b length];
        fprintf(stderr, "ds4: transient buffers this batch: %lu (%.1f MiB)\n",
                (unsigned long)[g_transient_buffers count], bytes / 1048576.0);
    }
    [g_transient_buffers removeAllObjects];
    ds4_gpu_model_buffer_cache_maybe_evict(label);
    return ok;
}

static int ds4_gpu_device_name_contains(const char *needle);
/* llms M3PATHS (apply_m3paths.py): upstream's 15 M3-only paths, per site, on any device -- LLMS_DS4_M3_PATHS = a hex mask of sites; ALT m3p<K> */
static int llms_m3_mask = -1; static uint64_t llms_m3_true[16];
static int llms_m3_site(int site) {
    if (ds4_gpu_device_name_contains("M3")) return 1;
    if (llms_m3_mask < 0) { const char *e = getenv("LLMS_DS4_M3_PATHS"); llms_m3_mask = e && *e ? (int)strtol(e, NULL, 16) : 0;
        if (llms_m3_mask) { fprintf(stderr, "llms: m3 paths mask 0x%x (upstream's M3-only paths on this device)\n", (unsigned)llms_m3_mask);
            atexit_b(^{ fprintf(stderr, "llms m3 paths:"); for (int q = 0; q < 16; q++) if (llms_m3_true[q]) fprintf(stderr, " site %d true %llu", q, (unsigned long long)llms_m3_true[q]); fprintf(stderr, "\n"); }); } }
    if (site < 0 || site > 15 || !((llms_m3_mask >> site) & 1)) return 0;
    { char nm[8]; snprintf(nm, sizeof nm, "m3p%d", site); if (llms_alt_off(nm)) return 0; }
    llms_m3_true[site]++; return 1;
}

static int ds4_gpu_use_m5_private_scratch(void) {
    static int initialized;
    static int enabled;
    if (!initialized) {
        enabled = ds4_gpu_device_name_contains("M5");
        initialized = 1;
    }
    return enabled;
}

static int ds4_gpu_scratch_needs_cpu_access(const char *label) {
    if (!label) return 0;
    return strstr(label, "mask") != NULL ||
           strcmp(label, "ds4_attention_output_group_ids") == 0;
}

static MTLResourceOptions ds4_gpu_model_resource_options(void) {
    MTLResourceOptions options = MTLResourceStorageModeShared;
    if (getenv("DS4_METAL_MODEL_UNTRACKED") != NULL) {
        options |= MTLResourceHazardTrackingModeUntracked;
    }
    return options;
}

static int ds4_gpu_ensure_scratch_buffer(
        id<MTLBuffer> __strong *buffer,
        NSUInteger    *capacity,
        NSUInteger     bytes,
        const char    *label) {
    if (*buffer && *capacity >= bytes) return 1;
    if (bytes == 0) bytes = 1;
    if (bytes > NSUIntegerMax) return 0;

    MTLResourceOptions options = MTLResourceStorageModeShared;
    if (ds4_gpu_use_m5_private_scratch() &&
        !ds4_gpu_scratch_needs_cpu_access(label)) {
        /*
         * M5 scratch buffers that only flow between Metal kernels do not need
         * CPU-visible shared storage. This reduces shared-memory traffic and
         * residency pressure for the long prefill scratch pools without
         * changing the public buffer lifetime model. Keep default hazard
         * tracking because the graph reuses these buffers across dependent
         * compute encoders.
         */
        options = MTLResourceStorageModePrivate;
    }

    *buffer = [g_device newBufferWithLength:bytes options:options];
    if (!*buffer && options != MTLResourceStorageModeShared) {
        *buffer = [g_device newBufferWithLength:bytes options:MTLResourceStorageModeShared];
    }
    if (!*buffer) {
        fprintf(stderr, "ds4: failed to allocate Metal scratch buffer %s (%llu bytes)\n",
                label, (unsigned long long)bytes);
        *capacity = 0;
        return 0;
    }
    (*buffer).label = [NSString stringWithUTF8String:label];
    *capacity = bytes;
    return 1;
}

static int ds4_gpu_ensure_zero_attention_mask(NSUInteger bytes) {
    const NSUInteger capacity = 8192u * sizeof(uint16_t);
    if (bytes > capacity) return 0;
    if (g_flash_attn_zero_mask_buffer &&
        g_flash_attn_zero_mask_bytes >= capacity) {
        return 1;
    }
    if (!ds4_gpu_ensure_scratch_buffer(&g_flash_attn_zero_mask_buffer,
                                         &g_flash_attn_zero_mask_bytes,
                                         capacity,
                                         "ds4_flash_attn_zero_mask")) {
        return 0;
    }
    void *contents = [g_flash_attn_zero_mask_buffer contents];
    if (!contents) return 0;
    memset(contents, 0, g_flash_attn_zero_mask_bytes);
    return 1;
}

static uint64_t round_up_u64(uint64_t v, uint64_t align) {
    return (v + align - 1) & ~(align - 1);
}

static uint64_t ds4_gpu_effective_model_max_tensor_bytes(uint64_t map_size, uint64_t max_tensor_bytes) {
    if (max_tensor_bytes != 0) return max_tensor_bytes;
    return map_size < DS4_METAL_FALLBACK_MAX_TENSOR_BYTES ?
           map_size : DS4_METAL_FALLBACK_MAX_TENSOR_BYTES;
}

static id<MTLComputePipelineState> ds4_gpu_get_pipeline_or_die(const char *function_name);
static int ds4_gpu_warm_model_views(void);
static int q4l_view_only(uint64_t start, uint64_t bytes);   /* llms Q4L_UNLOCK */
static double ds4_gpu_gib(uint64_t bytes);

static double ds4_gpu_now_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000.0 + ts.tv_nsec / 1000000.0;
}

static int ds4_gpu_moe_selected_hotlist_cmp(const void *a, const void *b) {
    const ds4_gpu_moe_selected_hotlist_entry *ea = a;
    const ds4_gpu_moe_selected_hotlist_entry *eb = b;
    if (ea->hits < eb->hits) return 1;
    if (ea->hits > eb->hits) return -1;
    if (ea->layer != eb->layer) return ea->layer < eb->layer ? -1 : 1;
    if (ea->expert != eb->expert) return ea->expert < eb->expert ? -1 : 1;
    return 0;
}

static int ds4_gpu_moe_selected_hotlist_merge_requested(void) {
    return getenv("DS4_MOE_RECORD_SELECTED_HOTLIST_MERGE") != NULL &&
           getenv("DS4_MOE_RECORD_SELECTED_HOTLIST_FRESH") == NULL;
}

static int ds4_gpu_moe_selected_hotlist_load_existing(const char *path) {
    if (!path || !path[0] || !ds4_gpu_moe_selected_hotlist_merge_requested()) {
        return 1;
    }

    FILE *fp = fopen(path, "rb");
    if (!fp) {
        if (errno == ENOENT) return 1;
        fprintf(stderr, "ds4: failed to open selected hotlist merge file %s\n", path);
        return 0;
    }

    char line[256];
    uint64_t lineno = 0;
    uint64_t loaded_entries = 0;
    uint64_t loaded_hits = 0;
    uint64_t header_records = UINT64_MAX;
    uint64_t header_selections = UINT64_MAX;
    while (fgets(line, sizeof(line), fp)) {
        lineno++;
        char *p = line;
        while (*p && isspace((unsigned char)*p)) p++;
        if (*p == '\0') continue;
        if (*p == '#') {
            unsigned long long value = 0;
            if (sscanf(p, "# layer_records %llu", &value) == 1) {
                header_records = (uint64_t)value;
            } else if (sscanf(p, "# selections %llu", &value) == 1) {
                header_selections = (uint64_t)value;
            }
            continue;
        }

        errno = 0;
        char *end = NULL;
        unsigned long layer = strtoul(p, &end, 10);
        if (end == p || errno != 0) goto bad_line;
        p = end;
        while (*p && isspace((unsigned char)*p)) p++;

        errno = 0;
        unsigned long expert = strtoul(p, &end, 10);
        if (end == p || errno != 0) goto bad_line;
        p = end;
        while (*p && isspace((unsigned char)*p)) p++;

        errno = 0;
        unsigned long long hits = strtoull(p, &end, 10);
        if (end == p || errno != 0) goto bad_line;
        if (layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER &&
            expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT &&
            hits != 0) {
            uint64_t *dst = &g_moe_selected_hotlist_counts[layer][expert];
            if (*dst > UINT64_MAX - (uint64_t)hits) {
                *dst = UINT64_MAX;
            } else {
                *dst += (uint64_t)hits;
            }
            loaded_entries++;
            if (loaded_hits > UINT64_MAX - (uint64_t)hits) {
                loaded_hits = UINT64_MAX;
            } else {
                loaded_hits += (uint64_t)hits;
            }
        }
        continue;

bad_line:
        fprintf(stderr,
                "ds4: invalid selected hotlist merge line %" PRIu64 " in %s\n",
                lineno,
                path);
        fclose(fp);
        return 0;
    }
    if (ferror(fp)) {
        fprintf(stderr, "ds4: failed to read selected hotlist merge file %s\n", path);
        fclose(fp);
        return 0;
    }
    fclose(fp);

    g_moe_selected_hotlist_records =
        header_records != UINT64_MAX ? header_records : loaded_hits / 6u;
    g_moe_selected_hotlist_selections =
        header_selections != UINT64_MAX ? header_selections : loaded_hits;
    fprintf(stderr,
            "ds4: merged selected-id hotlist %s "
            "(%" PRIu64 " entries, %" PRIu64 " hits)\n",
            path,
            loaded_entries,
            loaded_hits);
    return 1;
}

static void ds4_gpu_moe_selected_hotlist_close(void) {
    const char *path = getenv("DS4_MOE_RECORD_SELECTED_HOTLIST");
    if (!g_moe_selected_hotlist_initialized || !path || !path[0]) return;

    const size_t cap =
        (size_t)DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER *
        DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
    ds4_gpu_moe_selected_hotlist_entry *entries =
        malloc(cap * sizeof(entries[0]));
    if (!entries) {
        fprintf(stderr, "ds4: failed to allocate selected hotlist entries\n");
        return;
    }

    size_t n = 0;
    for (uint32_t layer = 0;
         layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER;
         layer++) {
        for (uint32_t expert = 0;
             expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
             expert++) {
            const uint64_t hits =
                g_moe_selected_hotlist_counts[layer][expert];
            if (hits == 0) continue;
            entries[n++] = (ds4_gpu_moe_selected_hotlist_entry) {
                .layer = layer,
                .expert = expert,
                .hits = hits,
            };
        }
    }
    qsort(entries, n, sizeof(entries[0]), ds4_gpu_moe_selected_hotlist_cmp);

    FILE *fp = fopen(path, "wb");
    if (!fp) {
        fprintf(stderr, "ds4: failed to open selected hotlist file %s\n", path);
        free(entries);
        return;
    }
    fprintf(fp,
            "# ds4 selected-id hotlist v1\n"
            "# layer_records %" PRIu64 "\n"
            "# selections %" PRIu64 "\n"
            "# columns: layer expert hits weight\n",
            g_moe_selected_hotlist_records,
            g_moe_selected_hotlist_selections);
    for (size_t i = 0; i < n; i++) {
        fprintf(fp,
                "%u %u %" PRIu64 " 0\n",
                entries[i].layer,
                entries[i].expert,
                entries[i].hits);
    }
    free(entries);

    if (fclose(fp) != 0) {
        fprintf(stderr, "ds4: failed to close selected hotlist file %s\n", path);
    } else {
        fprintf(stderr,
                "ds4: wrote selected-id hotlist to %s "
                "(%" PRIu64 " layer records, %" PRIu64 " selections)\n",
                path,
                g_moe_selected_hotlist_records,
                g_moe_selected_hotlist_selections);
    }
}

static int ds4_gpu_moe_selected_hotlist_record(
        uint32_t       layer,
        const int32_t *selected_ids,
        uint32_t       n_selected,
        uint32_t       n_total_expert) {
    const char *path = getenv("DS4_MOE_RECORD_SELECTED_HOTLIST");
    if (!path || !path[0]) return 1;
    if (!selected_ids ||
        n_selected == 0 ||
        n_selected > DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED) {
        return 0;
    }
    if (!g_moe_selected_hotlist_initialized) {
        g_moe_selected_hotlist_initialized = 1;
        if (!ds4_gpu_moe_selected_hotlist_load_existing(path)) return 0;
        atexit(ds4_gpu_moe_selected_hotlist_close);
    }
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) return 1;

    g_moe_selected_hotlist_records++;
    for (uint32_t i = 0; i < n_selected; i++) {
        if (selected_ids[i] < 0) continue;
        const uint32_t expert = (uint32_t)selected_ids[i];
        if (expert >= n_total_expert ||
            expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
            continue;
        }
        g_moe_selected_hotlist_counts[layer][expert]++;
        g_moe_selected_hotlist_selections++;
    }
    return 1;
}

static void ds4_gpu_moe_selected_trace_record_close(void) {
    if (g_moe_selected_trace_record_fp) {
        const char *path = getenv("DS4_MOE_RECORD_SELECTED_IDS");
        fclose(g_moe_selected_trace_record_fp);
        g_moe_selected_trace_record_fp = NULL;
        fprintf(stderr,
                "ds4: recorded %" PRIu64 " routed-MoE selected-id entries to %s\n",
                g_moe_selected_trace_record_count,
                path && path[0] ? path : "(unknown)");
    }
}

static int ds4_gpu_moe_selected_trace_record(
        const int32_t selected_ids[6],
        uint32_t      n_selected) {
    const char *path = getenv("DS4_MOE_RECORD_SELECTED_IDS");
    if (!path || !path[0]) return 1;
    if (n_selected != 6) {
        fprintf(stderr, "ds4: selected-id recording expects exactly 6 selected experts\n");
        return 0;
    }

    if (!g_moe_selected_trace_record_initialized) {
        g_moe_selected_trace_record_initialized = 1;
        g_moe_selected_trace_record_fp = fopen(path, "wb");
        if (!g_moe_selected_trace_record_fp) {
            fprintf(stderr, "ds4: failed to open selected-id record file %s\n", path);
            return 0;
        }
        setvbuf(g_moe_selected_trace_record_fp, NULL, _IOFBF, 1u << 20);
        atexit(ds4_gpu_moe_selected_trace_record_close);
    }

    if (fwrite(selected_ids, sizeof(selected_ids[0]), n_selected, g_moe_selected_trace_record_fp) != n_selected) {
        fprintf(stderr, "ds4: failed to write selected-id record file %s\n", path);
        return 0;
    }
    if (fflush(g_moe_selected_trace_record_fp) != 0) {
        fprintf(stderr, "ds4: failed to flush selected-id record file %s\n", path);
        return 0;
    }
    g_moe_selected_trace_record_count++;
    return 1;
}

static int ds4_gpu_moe_selected_trace_replay(
        int32_t  selected_ids[6],
        uint32_t n_selected) {
    const char *path = getenv("DS4_MOE_REPLAY_SELECTED_IDS");
    if (!path || !path[0]) return 0;
    if (n_selected != 6) {
        fprintf(stderr, "ds4: selected-id replay expects exactly 6 selected experts\n");
        return -1;
    }

    if (!g_moe_selected_trace_replay_initialized) {
        g_moe_selected_trace_replay_initialized = 1;
        FILE *fp = fopen(path, "rb");
        if (!fp) {
            fprintf(stderr, "ds4: failed to open selected-id replay file %s\n", path);
            return -1;
        }
        if (fseeko(fp, 0, SEEK_END) != 0) {
            fprintf(stderr, "ds4: failed to seek selected-id replay file %s\n", path);
            fclose(fp);
            return -1;
        }
        const off_t end = ftello(fp);
        if (end < 0) {
            fprintf(stderr, "ds4: failed to size selected-id replay file %s\n", path);
            fclose(fp);
            return -1;
        }
        if (fseeko(fp, 0, SEEK_SET) != 0) {
            fprintf(stderr, "ds4: failed to rewind selected-id replay file %s\n", path);
            fclose(fp);
            return -1;
        }

        const uint64_t bytes = (uint64_t)end;
        const uint64_t entry_bytes = (uint64_t)n_selected * sizeof(selected_ids[0]);
        if (bytes == 0 || (bytes % entry_bytes) != 0) {
            fprintf(stderr,
                    "ds4: selected-id replay file %s has invalid size %" PRIu64 "\n",
                    path,
                    bytes);
            fclose(fp);
            return -1;
        }
        if (bytes > SIZE_MAX) {
            fprintf(stderr, "ds4: selected-id replay file %s is too large\n", path);
            fclose(fp);
            return -1;
        }
        g_moe_selected_trace_replay_count = bytes / entry_bytes;
        g_moe_selected_trace_replay_ids = malloc((size_t)bytes);
        if (!g_moe_selected_trace_replay_ids) {
            fprintf(stderr, "ds4: failed to allocate selected-id replay buffer\n");
            fclose(fp);
            return -1;
        }
        if (fread(g_moe_selected_trace_replay_ids, 1, (size_t)bytes, fp) != (size_t)bytes) {
            fprintf(stderr, "ds4: failed to read selected-id replay file %s\n", path);
            fclose(fp);
            free(g_moe_selected_trace_replay_ids);
            g_moe_selected_trace_replay_ids = NULL;
            return -1;
        }
        fclose(fp);
        fprintf(stderr,
                "ds4: loaded %" PRIu64 " routed-MoE selected-id entries from %s\n",
                g_moe_selected_trace_replay_count,
                path);
    }

    if (g_moe_selected_trace_replay_pos >= g_moe_selected_trace_replay_count) {
        fprintf(stderr,
                "ds4: selected-id replay exhausted after %" PRIu64 " entries\n",
                g_moe_selected_trace_replay_pos);
        return -1;
    }
    memcpy(selected_ids,
           g_moe_selected_trace_replay_ids + g_moe_selected_trace_replay_pos * n_selected,
           (size_t)n_selected * sizeof(selected_ids[0]));
    g_moe_selected_trace_replay_pos++;
    return 1;
}

static int ds4_gpu_progress_enabled(void) {
    return ds4_log_is_tty(stderr);
}

static void ds4_gpu_progress_begin(const char *what) {
    if (!ds4_gpu_progress_enabled()) return;
    fprintf(stderr, "ds4: %s...", what);
    fflush(stderr);
}

static void ds4_gpu_progress_done(void) {
    if (!ds4_gpu_progress_enabled()) return;
    fputs(" done\n", stderr);
    fflush(stderr);
}

static void ds4_gpu_progress_failed(void) {
    if (!ds4_gpu_progress_enabled()) return;
    fputs(" failed\n", stderr);
    fflush(stderr);
}

static void ds4_gpu_model_views_clear(void) {
    for (uint32_t i = 0; i < g_model_view_count; i++) {
        g_model_views[i].buffer = nil;
        g_model_views[i].model_map = NULL;
        g_model_views[i].model_size = 0;
        g_model_views[i].model_offset = 0;
        g_model_views[i].bytes = 0;
    }
    g_model_view_count = 0;
}

static void ds4_gpu_model_views_remove_map(const void *model_map) {
    uint32_t kept = 0;
    for (uint32_t i = 0; i < g_model_view_count; i++) {
        if (g_model_views[i].model_map != model_map)
            g_model_views[kept++] = g_model_views[i];
    }
    for (uint32_t i = kept; i < g_model_view_count; i++)
        g_model_views[i] = (ds4_gpu_model_view){0};
    g_model_view_count = kept;
}

static void ds4_gpu_model_residency_clear(void) {
#if TARGET_OS_OSX
    if (@available(macOS 15.0, *)) {
        if (g_model_residency_set) {
            if (g_model_residency_added_to_queue &&
                g_queue &&
                [g_queue respondsToSelector:@selector(removeResidencySet:)]) {
                [g_queue removeResidencySet:g_model_residency_set];
            }
            [g_model_residency_set endResidency];
            [g_model_residency_set removeAllAllocations];
            g_model_residency_set = nil;
        }
    }
#endif
    g_model_residency_count = 0;
    g_model_residency_added_to_queue = 0;
}

/* TP sharding keeps only this rank's expert ranges warm,
 * so whole-view residency requests (which would page in the full file)
 * must be skipped; pages fault in lazily through the same view buffers,
 * exactly like ssd-streaming mode. */
static int g_model_residency_skipped;

void ds4_gpu_model_residency_skip(int skip) {
    g_model_residency_skipped = skip;
}

static int ds4_gpu_model_residency_request_views(void) {
    if (g_model_view_count == 0 ||
        g_ssd_streaming_mode ||
        g_model_residency_skipped ||
        getenv("DS4_METAL_NO_RESIDENCY") != NULL) {
        return 1;
    }

#if TARGET_OS_OSX
    if (@available(macOS 15.0, *)) {
        /*
         * Register all model views as one residency set before inference. This
         * is a GPU residency/budgeting hint, not a request to fault the whole
         * 80+ GB file into memory. Its purpose is to make the driver see the
         * complete set of large shared allocations during setup instead of
         * discovering them lazily from the first measured graph command, where
         * VM validation and residency accounting would look like model compute.
         */
        MTLResidencySetDescriptor *desc = [[MTLResidencySetDescriptor alloc] init];
        desc.label = @"ds4_model";
        desc.initialCapacity = g_model_view_count;

        NSError *error = nil;
        g_model_residency_set = [g_device newResidencySetWithDescriptor:desc error:&error];
        if (!g_model_residency_set) {
            fprintf(stderr, "ds4: Metal model residency set creation failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            return 0;
        }

        for (uint32_t i = 0; i < g_model_view_count; i++) {
            [g_model_residency_set addAllocation:g_model_views[i].buffer];
        }
        [g_model_residency_set commit];
        [g_model_residency_set requestResidency];
        if (getenv("DS4_METAL_DISABLE_QUEUE_RESIDENCY_SET") == NULL &&
            g_queue &&
            [g_queue respondsToSelector:@selector(addResidencySet:)]) {
            [g_queue addResidencySet:g_model_residency_set];
            g_model_residency_added_to_queue = 1;
        }
        g_model_residency_count = g_model_view_count;
    }
#endif

    return 1;
}

static int ds4_gpu_add_model_view_range(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    map_offset,
        uint64_t    map_size,
        uint64_t    max_tensor_bytes,
        bool        use_default_view_cap,
        uint64_t   *mapped_model_size_out) {
    const uint64_t page = (uint64_t)getpagesize();
    const uintptr_t model_addr = (uintptr_t)model_map;

    if ((model_addr & (uintptr_t)(page - 1)) != 0) {
        fprintf(stderr, "ds4: Metal model mmap base is not page aligned\n");
        return 0;
    }
    if (map_offset > model_size || map_size > model_size - map_offset) {
        fprintf(stderr, "ds4: Metal model mapped range is outside the GGUF mapping\n");
        return 0;
    }
    const uint64_t page_model_offset = map_offset & ~(page - 1);
    const uint64_t leading = map_offset - page_model_offset;
    if (map_size > UINT64_MAX - leading ||
        leading + map_size > UINT64_MAX - (page - 1))
    {
        fprintf(stderr, "ds4: Metal model mapped range overflows page alignment\n");
        return 0;
    }
    const uint64_t mapped_model_size = round_up_u64(leading + map_size, page);
    uint64_t max_buffer = (uint64_t)[g_device maxBufferLength];
    max_buffer &= ~(page - 1);

    /*
     * Wrap only the tensor-data part of the GGUF file. Metadata is parsed by the
     * CPU and is never dereferenced by kernels, so exposing it to Metal only
     * grows the residency set and the VM range the driver must validate.
     *
     * Metal buffers have a device-specific maximum length, and this model is
     * larger than that maximum on the target machines. Creating one no-copy
     * buffer per tensor would avoid the length limit, but it would also move a
     * lot of VM-object creation and residency bookkeeping into graph setup. The
     * stable shape here is a tiny number of page-aligned views created once.
     *
     * Adjacent views intentionally overlap by more than the largest tensor, plus
     * one page for alignment. That invariant guarantees every tensor lies wholly
     * inside at least one view, so hot paths pass one buffer and one inner byte
     * offset. We never split a weight tensor across command encoders.
     */
    if (max_tensor_bytes > map_size) {
        fprintf(stderr, "ds4: Metal model max tensor span is larger than a mapped tensor span\n");
        return 0;
    }
    if (max_tensor_bytes > UINT64_MAX - (page - 1)) {
        fprintf(stderr, "ds4: Metal model max tensor span overflows page alignment\n");
        return 0;
    }
    const uint64_t max_tensor_rounded = round_up_u64(max_tensor_bytes, page);
    if (max_tensor_rounded > UINT64_MAX - page) {
        fprintf(stderr, "ds4: Metal model view overlap overflows page slack\n");
        return 0;
    }
    const uint64_t overlap = max_tensor_rounded + page;
    if (max_buffer == 0 || max_buffer <= overlap) {
        fprintf(stderr,
                "ds4: Metal maxBufferLength is too small for DS4 model views "
                "(max tensor %.2f GiB, max buffer %.2f GiB)\n",
                ds4_gpu_gib(max_tensor_bytes),
                ds4_gpu_gib(max_buffer));
        return 0;
    }

    uint64_t view_limit = max_buffer;
    const char *view_limit_env = getenv("DS4_METAL_MODEL_VIEW_MAX_GIB");
    if (view_limit_env && view_limit_env[0]) {
        char *end = NULL;
        unsigned long long gib = strtoull(view_limit_env, &end, 10);
        if (end != view_limit_env && gib > 0) {
            uint64_t env_limit = gib * 1024ull * 1024ull * 1024ull;
            env_limit &= ~(page - 1);
            if (env_limit > 0) view_limit = env_limit;
        }
    } else if (use_default_view_cap && mapped_model_size > max_buffer) {
        /*
         * Very large no-copy buffers can make Metal's VM validation dominate
         * startup or the first graph command on multi-hundred-GiB slices. Keep
         * ordinary contiguous model mappings unchanged, but let distributed
         * span maps use smaller overlapping views when a range already has to
         * be split.
         */
        const uint64_t default_limit = 128ull * 1024ull * 1024ull * 1024ull;
        if (view_limit > default_limit) view_limit = default_limit;
    }
    if (view_limit > max_buffer) view_limit = max_buffer;
    view_limit &= ~(page - 1);
    if (view_limit == 0 || view_limit <= overlap) {
        fprintf(stderr,
                "ds4: Metal model view cap is too small for DS4 model views "
                "(cap %.2f GiB, max tensor %.2f GiB)\n",
                ds4_gpu_gib(view_limit),
                ds4_gpu_gib(max_tensor_bytes));
        return 0;
    }

    const uint64_t step = view_limit - overlap;
    uint64_t off = 0;
    while (off < mapped_model_size) {
        if (g_model_view_count == DS4_METAL_MAX_MODEL_VIEWS) {
            fprintf(stderr, "ds4: Metal model needs more mapped views than expected\n");
            return 0;
        }

        uint64_t view_bytes = mapped_model_size - off;
        if (view_bytes > view_limit) view_bytes = view_limit;

        id<MTLBuffer> buffer = [g_device newBufferWithBytesNoCopy:(void *)(model_addr + page_model_offset + off)
                                                           length:(NSUInteger)view_bytes
                                                          options:ds4_gpu_model_resource_options()
                                                      deallocator:nil];
        if (!buffer) {
            fprintf(stderr,
                    "ds4: Metal could not wrap mmaped model view at %.2f GiB, size %.2f GiB\n",
                    (double)(page_model_offset + off) / (1024.0 * 1024.0 * 1024.0),
                    (double)view_bytes / (1024.0 * 1024.0 * 1024.0));
            return 0;
        }
        buffer.label = [NSString stringWithFormat:@"ds4_model_view_%u", g_model_view_count];

        g_model_views[g_model_view_count].buffer = buffer;
        g_model_views[g_model_view_count].model_map = model_map;
        g_model_views[g_model_view_count].model_size = model_size;
        g_model_views[g_model_view_count].model_offset = page_model_offset + off;
        g_model_views[g_model_view_count].bytes = view_bytes;
        g_model_view_count++;

        g_model_wrap_count++;
        g_model_wrap_bytes += view_bytes;
        if (view_bytes > g_model_wrap_max_bytes) g_model_wrap_max_bytes = view_bytes;

        if (off + view_bytes >= mapped_model_size) break;
        off += step;
    }

    if (mapped_model_size_out) *mapped_model_size_out += mapped_model_size;
    return 1;
}

static int ds4_gpu_finish_model_views(
        double t0,
        uint64_t mapped_model_size,
        uint64_t display_offset) {
    const double t_mapped = ds4_gpu_now_ms();
    const int request_residency =
        !g_ssd_streaming_mode &&
        getenv("DS4_METAL_NO_RESIDENCY") == NULL;
    if (request_residency) ds4_gpu_progress_begin("requesting Metal residency (may take tens of seconds)");
    if (!ds4_gpu_model_residency_request_views()) {
        if (request_residency) ds4_gpu_progress_failed();
        return 0;
    }
    if (request_residency) ds4_gpu_progress_done();
    const double t_resident = ds4_gpu_now_ms();
    int warmed = 1;
    const double t_warm0 = ds4_gpu_now_ms();
    const int warm_model_views = !g_ssd_streaming_mode &&
                                 getenv("DS4_METAL_NO_RESIDENCY") == NULL &&
                                 getenv("DS4_METAL_NO_MODEL_WARMUP") == NULL;
    if (warm_model_views) {
        /*
         * The first GPU command touching no-copy mmap storage can pay command
         * queue setup, page-table validation, and shared-allocation residency
         * costs. Sample each model view here so timed graph execution starts
         * after that one-time work. The stride is intentionally coarse: this is
         * a validation touch over the VM ranges, not a full model prefetch. A
         * dense prefetch would create exactly the kind of memory pressure and
         * startup stalls this path is designed to avoid.
         */
        if (g_model_residency_skipped) {
            /* TP sharding: a single command buffer binding every
             * view demands residency of them all and OOMs; the engine's
             * CPU-side sharded warm pre-faults the owned bytes instead. */
            warmed = 1;
        } else {
            ds4_gpu_progress_begin("warming Metal model views");
            warmed = ds4_gpu_warm_model_views();
            if (warmed) ds4_gpu_progress_done();
            else ds4_gpu_progress_failed();
        }
    }
    ds4_gpu_queue_keepalive_start();
    const double t_warm = ds4_gpu_now_ms();
    if (ds4_gpu_model_map_log_enabled()) {
        fprintf(stderr,
                "ds4: Metal model views created in %.3f ms, residency requested in %.3f ms, warmup %.3f ms (mapped %.2f MiB from offset %.2f MiB)\n",
                t_mapped - t0,
                t_resident - t_mapped,
                t_warm - t_warm0,
                mapped_model_size / 1024.0 / 1024.0,
                display_offset / 1024.0 / 1024.0);
    }
    if (!warmed) return 0;
    return 1;
}

static int ds4_gpu_map_model_views(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    map_offset,
        uint64_t    map_size,
        uint64_t    max_tensor_bytes) {
    const double t0 = ds4_gpu_now_ms();
    uint64_t mapped_model_size = 0;
    if (!ds4_gpu_add_model_view_range(model_map,
                                      model_size,
                                      map_offset,
                                      map_size,
                                      max_tensor_bytes,
                                      false,
                                      &mapped_model_size)) {
        return 0;
    }
    return ds4_gpu_finish_model_views(t0, mapped_model_size, map_offset);
}

static id<MTLBuffer> ds4_gpu_new_transient_buffer(NSUInteger bytes, const char *label) {
    if (bytes == 0) bytes = 1;

    id<MTLBuffer> buffer = [g_device newBufferWithLength:bytes
                                                 options:MTLResourceStorageModeShared];
    if (!buffer) {
        fprintf(stderr, "ds4: failed to allocate Metal transient buffer %s (%llu bytes)\n",
                label ? label : "(unnamed)", (unsigned long long)bytes);
        return nil;
    }
    if (label) buffer.label = [NSString stringWithUTF8String:label];

    /*
     * CPU-filled buffers must survive until their command buffer completes.
     * A local ObjC strong variable is not enough when the encoder function
     * returns before the caller commits the command buffer.
     */
    [g_transient_buffers addObject:buffer];
    return buffer;
}

static int ds4_gpu_zero_prefix_prefill_mask_cache_enabled(void) {
    if (getenv("DS4_METAL_DISABLE_ZERO_PREFIX_PREFILL_MASK_CACHE") != NULL ||
        getenv("DS4_METAL_FLASH_ATTN_STAGE_PROFILE") != NULL) {
        return 0;
    }
    return llms_m3_site(0);
}

static ds4_gpu_zero_prefix_prefill_mask_cache_entry *
ds4_gpu_get_zero_prefix_prefill_mask_cache(
        uint32_t   kind,
        uint32_t   n_tokens,
        uint32_t   n_comp,
        uint32_t   n_keys,
        uint32_t   window,
        uint32_t   ratio,
        uint32_t   nqptg,
        uint32_t   ncpsg,
        bool       has_kvpad,
        bool       bc_mask,
        NSUInteger mask_bytes,
        NSUInteger blk_bytes,
        bool      *created) {
    if (created) *created = false;
    if (!created || !ds4_gpu_zero_prefix_prefill_mask_cache_enabled() ||
        mask_bytes == 0 || blk_bytes == 0) {
        return NULL;
    }

    uint32_t slot = UINT32_MAX;
    switch (kind) {
        case DS4_GPU_PREFILL_MASK_CACHE_RAW:      slot = 0; break;
        case DS4_GPU_PREFILL_MASK_CACHE_RATIO4:   slot = 1; break;
        case DS4_GPU_PREFILL_MASK_CACHE_RATIO128: slot = 2; break;
        default: return NULL;
    }

    ds4_gpu_zero_prefix_prefill_mask_cache_entry *entry =
        &g_zero_prefix_prefill_mask_cache[slot];
    if (entry->valid && entry->mask && entry->blk &&
        entry->mask_bytes == mask_bytes && entry->blk_bytes == blk_bytes &&
        entry->kind == kind && entry->n_tokens == n_tokens &&
        entry->n_comp == n_comp && entry->n_keys == n_keys &&
        entry->window == window && entry->ratio == ratio &&
        entry->nqptg == nqptg && entry->ncpsg == ncpsg &&
        entry->has_kvpad == has_kvpad && entry->bc_mask == bc_mask) {
        return entry;
    }

    id<MTLBuffer> mask = [g_device newBufferWithLength:mask_bytes
                                                options:MTLResourceStorageModeShared];
    id<MTLBuffer> blk = [g_device newBufferWithLength:blk_bytes
                                               options:MTLResourceStorageModePrivate];
    if (!blk) {
        blk = [g_device newBufferWithLength:blk_bytes
                                    options:MTLResourceStorageModeShared];
    }
    if (!mask || !blk) return NULL;

    mask.label = [NSString stringWithFormat:@"ds4_prefill_mask_cache_%u", kind];
    blk.label = [NSString stringWithFormat:@"ds4_prefill_blk_cache_%u", kind];

    /* A replaced entry may still be referenced by an uncommitted or in-flight
     * command buffer. Keep its resources alive with the other batch-scoped
     * buffers until command completion instead of mutating or releasing them. */
    if (entry->mask) [g_transient_buffers addObject:entry->mask];
    if (entry->blk) [g_transient_buffers addObject:entry->blk];

    entry->mask = mask;
    entry->blk = blk;
    entry->mask_bytes = mask_bytes;
    entry->blk_bytes = blk_bytes;
    entry->kind = kind;
    entry->n_tokens = n_tokens;
    entry->n_comp = n_comp;
    entry->n_keys = n_keys;
    entry->window = window;
    entry->ratio = ratio;
    entry->nqptg = nqptg;
    entry->ncpsg = ncpsg;
    entry->has_kvpad = has_kvpad;
    entry->bc_mask = bc_mask;
    /* The caller publishes the entry only after synchronously filling mask. */
    entry->valid = false;
    entry->blk_ready = false;
    *created = true;
    return entry;
}

static void ds4_gpu_invalidate_zero_prefix_prefill_block_maps(void) {
    for (uint32_t i = 0; i < DS4_GPU_PREFILL_MASK_CACHE_SLOTS; i++) {
        g_zero_prefix_prefill_mask_cache[i].blk_ready = false;
    }
}

static void ds4_gpu_clear_zero_prefix_prefill_mask_cache(void) {
    for (uint32_t i = 0; i < DS4_GPU_PREFILL_MASK_CACHE_SLOTS; i++) {
        ds4_gpu_zero_prefix_prefill_mask_cache_entry *entry =
            &g_zero_prefix_prefill_mask_cache[i];
        entry->mask = nil;
        entry->blk = nil;
        entry->mask_bytes = 0;
        entry->blk_bytes = 0;
        entry->kind = 0;
        entry->n_tokens = 0;
        entry->n_comp = 0;
        entry->n_keys = 0;
        entry->window = 0;
        entry->ratio = 0;
        entry->nqptg = 0;
        entry->ncpsg = 0;
        entry->has_kvpad = false;
        entry->bc_mask = false;
        entry->valid = false;
        entry->blk_ready = false;
    }
}

void ds4_gpu_release_zero_prefix_prefill_mask_cache(void) {
    /* Layer-major prefill waits each layer before advancing, so its final
     * release point has no outstanding cache users. Keep the guard here for
     * diagnostic callers that may have an open or asynchronously flushed CB. */
    if (!g_initialized || g_batch_cb ||
        (g_pending_cbs && [g_pending_cbs count] != 0)) {
        return;
    }
    ds4_gpu_clear_zero_prefix_prefill_mask_cache();
}

static void check_q8_forbidden(const char *name);
static id<MTLComputePipelineState> ds4_gpu_get_mul_mm_pipeline(
        const char *function_name,
        bool        bc_inp,
        bool        bc_out) {
    check_q8_forbidden(function_name);   /* check before any cached return */
    NSString *key = [NSString stringWithFormat:@"%s_bci=%d_bco=%d",
                     function_name, bc_inp ? 1 : 0, bc_out ? 1 : 0];
    id<MTLComputePipelineState> cached = [g_pipeline_cache objectForKey:key];
    if (cached) return cached;

    MTLFunctionConstantValues *constants = [[MTLFunctionConstantValues alloc] init];
    [constants setConstantValue:&bc_inp type:MTLDataTypeBool atIndex:700];
    [constants setConstantValue:&bc_out type:MTLDataTypeBool atIndex:701];

    NSError *error = nil;
    NSString *name = [NSString stringWithUTF8String:function_name];
    id<MTLFunction> fn = [g_library newFunctionWithName:name
                                         constantValues:constants
                                                  error:&error];
    if (!fn) {
        llms_strict_after(fprintf(stderr, "ds4: Metal %s function not found: %s\n",
                function_name, [[error localizedDescription] UTF8String]), LLMS_G_KERN);
        return nil;
    }

    error = nil;
    id<MTLComputePipelineState> pipeline = [g_device newComputePipelineStateWithFunction:fn error:&error];
    if (!pipeline) {
        fprintf(stderr, "ds4: Metal %s pipeline failed: %s\n",
                function_name, [[error localizedDescription] UTF8String]);
        return nil;
    }

    [g_pipeline_cache setObject:pipeline forKey:key];
    return pipeline;
}

static id<MTLComputePipelineState> ds4_gpu_get_mul_mm_id_pipeline(
        const char *function_name,
        bool        bc_inp) {
    check_q8_forbidden(function_name);   /* check before any cached return */
    NSString *key = [NSString stringWithFormat:@"%s_bci=%d",
                     function_name, bc_inp ? 1 : 0];
    id<MTLComputePipelineState> cached = [g_pipeline_cache objectForKey:key];
    if (cached) return cached;

    MTLFunctionConstantValues *constants = [[MTLFunctionConstantValues alloc] init];
    [constants setConstantValue:&bc_inp type:MTLDataTypeBool atIndex:700];

    NSError *error = nil;
    NSString *name = [NSString stringWithUTF8String:function_name];
    id<MTLFunction> fn = [g_library newFunctionWithName:name
                                         constantValues:constants
                                                  error:&error];
    if (!fn) {
        llms_strict_after(fprintf(stderr, "ds4: Metal %s function not found: %s\n",
                function_name, [[error localizedDescription] UTF8String]), LLMS_G_KERN);
        return nil;
    }

    error = nil;
    id<MTLComputePipelineState> pipeline = [g_device newComputePipelineStateWithFunction:fn error:&error];
    if (!pipeline) {
        fprintf(stderr, "ds4: Metal %s pipeline failed: %s\n",
                function_name, [[error localizedDescription] UTF8String]);
        return nil;
    }

    [g_pipeline_cache setObject:pipeline forKey:key];
    return pipeline;
}

#include <execinfo.h>
static int q8_forbid_state;   /* llms Q8_FORBID (apply_q8_forbid.py) */
void ds4_gpu_llms_q8_guard(int on) { q8_forbid_state = on; }
static void check_q8_forbidden(const char *name) {
    static int f = -1; if (f < 0) { const char *e = getenv("LLMS_DS4_Q8_FORBID"); f = e && *e && *e != '0'; if (f) fprintf(stderr, "llms: Q8_FORBID -- a Q8_0 kernel in a decode / verify step aborts\n"); }
    if (!f || !q8_forbid_state || !name || !strstr(name, "q8_0")) return;
    fprintf(stderr, "llms Q8_FORBID: kernel %s dispatched inside a guarded decode / verify step\n", name);
    void *bt[48]; const int n = backtrace(bt, 48); backtrace_symbols_fd(bt, n, 2);
    abort();
}
static id<MTLComputePipelineState> ds4_gpu_get_pipeline_or_die(
        const char *function_name) {
    check_q8_forbidden(function_name);   /* llms Q8_FORBID */
    NSString *key = [NSString stringWithFormat:@"%s", function_name];
    id<MTLComputePipelineState> cached = [g_pipeline_cache objectForKey:key];
    if (cached) {
        /* Failed lookups are remembered as NSNull so the error prints once
         * per name instead of on every dispatch. */
        if (cached == (id<MTLComputePipelineState>)[NSNull null]) return nil;
        return cached;
    }

    NSError *error = nil;
    NSString *name = [NSString stringWithUTF8String:function_name];
    id<MTLFunction> fn = [g_library newFunctionWithName:name];
    if (!fn) {
        llms_strict_after(fprintf(stderr, "ds4: Metal %s function not found\n", function_name), LLMS_G_KERN);
        [g_pipeline_cache setObject:(id<MTLComputePipelineState>)[NSNull null] forKey:key];
        return nil;
    }

    id<MTLComputePipelineState> pipeline = [g_device newComputePipelineStateWithFunction:fn error:&error];
    if (!pipeline) {
        fprintf(stderr, "ds4: Metal %s pipeline failed: %s\n",
                function_name, [[error localizedDescription] UTF8String]);
        [g_pipeline_cache setObject:(id<MTLComputePipelineState>)[NSNull null] forKey:key];
        return nil;
    }

    [g_pipeline_cache setObject:pipeline forKey:key];
    return pipeline;
}

static int ds4_gpu_disable_hot_pipeline_statics(void) {
    static int initialized;
    static int disabled;
    if (!initialized) {
        disabled = getenv("DS4_METAL_DISABLE_HOT_PIPELINE_STATICS") != NULL;
        initialized = 1;
    }
    return disabled;
}

static id<MTLComputePipelineState> ds4_gpu_hot_pipeline(
        id<MTLComputePipelineState> pipeline,
        const char *fallback_name) {
    check_q8_forbidden(fallback_name);   /* check before any cached return */
    if (!ds4_gpu_disable_hot_pipeline_statics()) return pipeline;
    return ds4_gpu_get_pipeline_or_die(fallback_name);
}

