/* Simdgroups per threadgroup for the few-row (2..16 tokens) Q8/F16 matvecs
 * that carry the MTP verify rows.  Rows per threadgroup only: each row keeps
 * its lane walk and shuffle tree, so outputs are byte-identical at any
 * value (tests/test_qwen4_kernels.c pins 1/2/4/8). */
/* Row-exact geometry for the 3-row speculative verify: the few-row matvec
 * and routed-expert dispatches keep the lane maps and kernel choices of the
 * T <= 2 decode paths, so every committed row stays byte-identical. */
static bool g_qwen4_verify_rows_exact;

static int16_t ds4_gpu_mv_ext_nsg(void) {
    return (int16_t)ds4_gpu_env_u64("DS4_METAL_MV_EXT_NSG", 2u, 1u, 8u);
}

static int16_t ds4_gpu_mv_ext_nxpsg(uint64_t in_dim, uint64_t n_tok) {
    if ((in_dim % 256u) == 0 && (n_tok < 3 || (n_tok == 3 && g_qwen4_verify_rows_exact))) return 16;
    if ((in_dim % 128u) == 0) return 8;
    return 4;
}

static int16_t ds4_gpu_mv_ext_r1ptg(uint64_t n_tok) {
    switch (n_tok) {
    case 2: return 2;
    case 3:
    case 6: return 3;
    case 4:
    case 7:
    case 8: return 4;
    case 5: return 5;
    default: return n_tok > 8 ? 4 : 0;
    }
}

/* llms EXT_R8 (apply_ds4_ext_r8.py): 8 tokens per threadgroup in the batched Q8_0 ext matvec. 1 on, 2 canary */
static uint64_t ext_r8_calls;
static void report_ext_r8(void) { fprintf(stderr, "llms ext r8: %llu dispatches\n", (unsigned long long)ext_r8_calls); }
static int ext_r8_on(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_EXT_R8"); on = e && *e && *e != '0' ? (!strcmp(e, "canary") ? 2 : 1) : 0;
                  if (on) { fprintf(stderr, on == 2 ? "llms: ext r8 -- CANARY: wrong token stride\n" : "llms: ext r8 (8 tokens per threadgroup for Q8_0 multiples of 8)\n"); atexit(report_ext_r8); } }
    return on;
}
/* llms ALT (apply_ds4_alt.py): LLMS_DS4_ALT=sgm,kslice,r8,nsg -- the named switches are off on odd-numbered batched steps */
static uint32_t step_number;
static uint64_t altw_queried_mask;   /* llms ALT: bit i = ALTW table name i was queried during the current step */
unsigned long long ds4_gpu_llms_altw_qmask(void) { return altw_queried_mask; }
/* llms CPU_BURN (apply_ds4_cpu_burn.py): T threads spinning D % of each ms while the ALT name 'burn' is on */
static int llms_alt_off(const char *name); static volatile int burn_on; static int burn_duty;
static int burn_background;   /* llms CPU_BURN third field 'bg': the spinners run at QOS_CLASS_BACKGROUND (the E-cores) */
static int burn_memory;  /* llms CPU_BURN field 'mem': each spinner streams a 256 MiB buffer (one write per 64-byte line) -- DRAM and SLC traffic */
static void *burn_thread(void *arg) { pthread_setname_np("llms.burn");   /* llms THREAD_CPU */
    (void)arg; volatile double x = 1.0; if (burn_background) pthread_set_qos_class_self_np(QOS_CLASS_BACKGROUND, 0);
    uint8_t *mb = NULL; const size_t mbn = (size_t)(burn_memory > 1 ? burn_memory : 256) << 20; size_t mp = 0;   /* 'memN': N MiB */
    if (burn_memory) { mb = (uint8_t *)malloc(mbn); if (mb) memset(mb, 1, mbn); }
    for (;;) {
        if (!burn_on) { usleep(1000); continue; }
        const double t0 = ds4_gpu_now_ms(); const double spin = burn_duty / 100.0;
        if (mb) { while (ds4_gpu_now_ms() - t0 < spin) { for (int r = 0; r < 4096; r++) { mb[mp] += 1; mp += 64; if (mp >= mbn) mp = 0; } } }
        else while (ds4_gpu_now_ms() - t0 < spin) x = x * 1.0000001 + 1e-9;
        if (spin < 1.0) usleep((useconds_t)((1.0 - spin) * 1000.0));
    }
    return NULL;
}
static void burn_step(void) {
    static int init = -1;
