            for (int i = 0; i < n; i++) { pthread_t th; pthread_create(&th, NULL, burn_thread, NULL); pthread_detach(th); }
            fprintf(stderr, "llms: cpu burn %d threads at %d %% (%s) while ALT 'burn' is on\n", n, burn_duty, burn_background ? (burn_memory ? "background QoS, 256 MiB stream" : "background QoS") : (burn_memory ? "default QoS, memory stream" : "default QoS")); if (burn_memory) fprintf(stderr, "llms: cpu burn stream %d MiB\n", burn_memory > 1 ? burn_memory : 256); init = 1; } }
