    fprintf(stderr, "llms: heat probes -- byteadd %d MiB a step (ALT 'byteadd'), aluadd %d iterations (ALT 'aluadd')\n", byteadd_mib, aluadd_iters);
    atexit_b(^{ fprintf(stderr, "llms heat probes: byteadd %llu buffers, mean GPU %.3f ms (%d MiB: %.1f GB/s); aluadd %llu buffers, mean GPU %.3f ms (%d iterations)\n",
        (unsigned long long)byteadd_cbs, byteadd_cbs ? (double)byteadd_ns / 1e6 / (double)byteadd_cbs : 0.0, byteadd_mib,
        byteadd_ns ? (double)byteadd_cbs * (double)byteadd_mib * 1048576.0 / (double)byteadd_ns : 0.0,
        (unsigned long long)aluadd_cbs, aluadd_cbs ? (double)aluadd_ns / 1e6 / (double)aluadd_cbs : 0.0, aluadd_iters); });
