}
void ds4_gpu_llms_set_step(uint32_t step) { step_number = step; altw_queried_mask = 0; burn_step(); heatp_step();   /* llms BYTEADD / ALUADD */
    {   /* llms ALTR canary: LLMS_DS4_ALTR_CANARY_US=N sleeps N us at the step's start while ALT 'canary' is on (the screen's positive control) */
        static int altr_canary_us_state = -1; if (altr_canary_us_state < 0) { const char *e = getenv("LLMS_DS4_ALTR_CANARY_US"); altr_canary_us_state = e ? atoi(e) : 0; if (altr_canary_us_state > 0) fprintf(stderr, "llms: ALTR canary %d us per step while ALT 'canary' is on\n", altr_canary_us_state); }
        if (altr_canary_us_state > 0 && !llms_alt_off("canary")) {   /* llms CANARY_DOSE (apply_canary_dose.py): the delivered dose, timed */
            static uint64_t cd_n, cd_ticks; static int cd_reg; const uint64_t cd_t0 = mach_absolute_time();
            usleep((useconds_t)altr_canary_us_state);
            cd_ticks += mach_absolute_time() - cd_t0; cd_n++;
