                fprintf(stderr, "llms ALTR canary: %llu sleeps, delivered mean %.1f us (nominal %d)\n", (unsigned long long)cd_n,
                        cd_n ? (double)cd_ticks * tb.numer / tb.denom / 1e3 / (double)cd_n : 0.0, nominal); }); }
        }
    }
}
static char alt_forced_names[256];   /* llms ALT_FORCE (apply_cf_form2.py): names forced off by the harness */
void ds4_gpu_llms_alt_force(const char *names) { snprintf(alt_forced_names, sizeof alt_forced_names, "%s", names && strcmp(names, "-") ? names : ""); }
static const char *alt_census_names[256]; static uint64_t alt_census_queries[256], alt_census_offs[256]; static int alt_census_state = -1;   /* llms ALT_CENSUS (moved from apply_rep.py into the one mechanism) */
static void report_alt_census(void) { fprintf(stderr, "llms alt census:"); for (int i = 0; i < 256; i++) if (alt_census_names[i]) fprintf(stderr, " %s=%llu/%llu", alt_census_names[i], (unsigned long long)alt_census_queries[i], (unsigned long long)alt_census_offs[i]); fprintf(stderr, "\n"); }
static int alt_off_lookup(const char *name);
static int wnn; static char wn[64][40]; static uint32_t wp[64], wpct[64], wph[64]; static uint64_t wseed = 1, wq[64];   /* llms ALT table (file scope) */
static uint8_t wrb[64];   /* llms ALTB (apply_altb.py): 1 = random per block of wp[i] steps ('name:bP') */
static int altw_off_at(int i) {   /* PURE: name i's OFF state at the current step -- no counters touched */
    if (wrb[i]) {   /* llms ALTB: one splitmix64 draw per block, per name -- no fixed order between blocks or factors */
        uint64_t z = wseed + (uint64_t)(step_number / wp[i]) * 0x9E3779B97F4A7C15ull + (uint64_t)(i + 1) * 0xD1B54A32D192ED03ull + 0x632BE59BD9B4E019ull;
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ull; z = (z ^ (z >> 27)) * 0x94D049BB133111EBull; z ^= z >> 31;
        return (int)((z >> 32) & 1u);
    }
    if (wp[i] == 0u) {
        uint64_t z = wseed + (uint64_t)step_number * 0x9E3779B97F4A7C15ull + (uint64_t)(i + 1) * 0xD1B54A32D192ED03ull;
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ull; z = (z ^ (z >> 27)) * 0x94D049BB133111EBull; z ^= z >> 31;
        return (int)(((z >> 32) % 100u) < wpct[i]);
