unsigned long long ds4_gpu_llms_altw_offmask(void) { unsigned long long b = 0; for (int i = 0; i < wnn; i++) b |= (unsigned long long)altw_off_at(i) << i; return b; }
static int llms_alt_off(const char *name) {   /* LLMS_DS4_ALT_CENSUS=1: every name any switch asks about, how often, and how often it answered off */
    { static int vo = -1; if (vo < 0) { const char *e = getenv("LLMS_DS4_ALTW_VERIFY_ONLY"); vo = e && *e && *e != '0'; if (vo) fprintf(stderr, "llms: altw verify only (ALT names answer 'on' outside the verify skip window)\n"); }
      if (vo && !skipg_in_window) return 0; }   /* llms ALTW_VERIFY_ONLY (apply_altw_verify_only.py) */
    if (alt_census_state < 0) { const char *e = getenv("LLMS_DS4_ALT_CENSUS"); alt_census_state = e && *e && *e != '0'; if (alt_census_state) atexit(report_alt_census); }
    const int r = alt_off_lookup(name);
    if (alt_census_state) { uint32_t h = 5381; for (const char *c = name; *c; c++) h = h * 33u + (uint8_t)*c;
