            if (!alt_census_names[i]) alt_census_names[i] = name;
            if (alt_census_names[i] == name || !strcmp(alt_census_names[i], name)) { alt_census_queries[i]++; alt_census_offs[i] += (uint64_t)r; break; } } }
    return r;
}
static int alt_off_lookup(const char *name) {
    /* llms ALT, ONE MECHANISM (apply_alt_live.py): a table of per-name policies. 'name:P' = a Walsh period P (off when (step / P + phase) is odd); 'name:r' / 'name:rNN' = random, off on 50 % / NN % of steps (splitmix64 of LLMS_DS4_ALTW_SEED, the step, the name). LLMS_DS4_ALT=names is an alias (period LLMS_DS4_ALT_BLOCK or 1, phase LLMS_DS4_ALT_WALSH_PHASE). ALT2D is retired. */
    static int altw_table_checked = 0;   /* the table itself lives at file scope (apply_alt_table.py) */
    if (!altw_table_checked) { altw_table_checked = 1;
        { const char *sd = getenv("LLMS_DS4_ALTW_SEED"); if (sd && *sd) wseed = strtoull(sd, NULL, 10); }
        const char *pw = getenv("LLMS_DS4_ALTW_WALSH_PHASE"), *pa = getenv("LLMS_DS4_ALT_WALSH_PHASE"), *bk = getenv("LLMS_DS4_ALT_BLOCK");
        const uint32_t ph_w = pw && *pw ? (uint32_t)(atoi(pw) & 1) : 0u, ph_a = pa && *pa ? (uint32_t)(atoi(pa) & 1) : 0u;
        const uint32_t blk = bk && atoi(bk) > 1 ? (uint32_t)atoi(bk) : 1u;
        for (int pass = 0; pass < 2; pass++) {   /* pass 0: LLMS_DS4_ALTW (name:spec), pass 1: LLMS_DS4_ALT (names; the alias) */
            const char *w = getenv(pass ? "LLMS_DS4_ALT" : "LLMS_DS4_ALTW"); if (!w || !*w) continue;
            char buf[4096], *save = NULL; snprintf(buf, sizeof buf, "%s", w);
            for (char *tok = strtok_r(buf, ",", &save); tok && wnn < 64; tok = strtok_r(NULL, ",", &save)) {
                char *c = strchr(tok, ':'); if (c) *c = 0; else if (!pass) continue;
                snprintf(wn[wnn], sizeof wn[0], "%s", tok);
                if (pass) { wp[wnn] = blk; wpct[wnn] = 0u; wph[wnn] = ph_a; }
                else if (c[1] == 'r') { wp[wnn] = 0u; wpct[wnn] = c[2] ? (uint32_t)atoi(c + 2) : 50u; wph[wnn] = 0u; }
                else if (c[1] == 'b') { wp[wnn] = (uint32_t)atoi(c + 2); if (wp[wnn] < 1u) wp[wnn] = 1u; wpct[wnn] = 0u; wph[wnn] = 0u; wrb[wnn] = 1u; }   /* llms ALTB */
                else { wp[wnn] = (uint32_t)atoi(c + 1); if (wp[wnn] < 1u) wp[wnn] = 1u; wpct[wnn] = 0u; wph[wnn] = ph_w; }
                wnn++;
            }
        }
        if (wnn) { fprintf(stderr, "llms: ALTW %d names (Walsh periods or random) -- a WITHIN-PROCESS contrast: alternating two code paths can slow one arm; confirm a gain with a plain bracket (separate runs, A B B A) or a fixed-horizon run before adoption\n", wnn);
                   atexit_b(^{ fprintf(stderr, "llms ALTW queries:"); for (int k = 0; k < wnn; k++) fprintf(stderr, " %s %llu", wn[k], (unsigned long long)wq[k]); fprintf(stderr, "\n"); }); }
    }

    {   /* llms ALTW_ALIAS (apply_altalias.py): LLMS_DS4_ALTW_ALIAS='GROUP=a+b+c' -- a member name answers as its group's factor */
        static int al_n = -1; static char al_member[32][40], al_group[32][40];
        if (al_n < 0) { al_n = 0; const char *e = getenv("LLMS_DS4_ALTW_ALIAS");
            if (e && *e) { char buf[1024], *save = NULL; snprintf(buf, sizeof buf, "%s", e);
                for (char *tok = strtok_r(buf, ",", &save); tok; tok = strtok_r(NULL, ",", &save)) {
                    char *eq = strchr(tok, '='); if (!eq) continue; *eq = 0; char *save2 = NULL;
                    for (char *m = strtok_r(eq + 1, "+", &save2); m && al_n < 32; m = strtok_r(NULL, "+", &save2)) {
                        snprintf(al_member[al_n], sizeof al_member[0], "%s", m); snprintf(al_group[al_n], sizeof al_group[0], "%s", tok); al_n++; } }
                fprintf(stderr, "llms: ALTW alias -- %d member names answer as their group's factor\n", al_n); } }
