        static int phase_off_count = -1; static char phase_off_names[256][40]; static uint8_t phase_off_masks[256]; static uint64_t phase_off_queried_counts[256][2], phase_off_forced_counts[256][2];   /* 18:1x: 256 names; ':n' counts only (the per-phase census) */
        if (phase_off_count < 0) { phase_off_count = 0; const char *e = getenv("LLMS_DS4_PHASE_OFF");
            if (e && *e) { char buf[8192], *save = NULL; snprintf(buf, sizeof buf, "%s", e);
                for (char *tok = strtok_r(buf, ",", &save); tok && phase_off_count < 256; tok = strtok_r(NULL, ",", &save)) {
                    char *c = strchr(tok, ':'); if (!c) continue; *c = 0;
                    const uint8_t mk = !strcmp(c + 1, "pf") ? 1u : !strcmp(c + 1, "dec") ? 2u : !strcmp(c + 1, "n") ? 4u : 0u; if (!mk) continue;
                    int k = 0; for (; k < phase_off_count; k++) if (!strcmp(phase_off_names[k], tok)) break;
                    if (k == phase_off_count) { snprintf(phase_off_names[phase_off_count], sizeof phase_off_names[0], "%s", tok); phase_off_masks[phase_off_count] = 0; phase_off_count++; }
                    phase_off_masks[k] |= mk;
