                atexit_b(^{ fprintf(stderr, "llms phase off:"); for (int k = 0; k < phase_off_count; k++) fprintf(stderr, " %s[%s%s] prefill %llu/%llu decode %llu/%llu", phase_off_names[k],
                    (phase_off_masks[k] & 1u) ? "pf" : "", (phase_off_masks[k] & 2u) ? "dec" : (phase_off_masks[k] & 4u) ? "n" : "", (unsigned long long)phase_off_forced_counts[k][0], (unsigned long long)phase_off_queried_counts[k][0],
                    (unsigned long long)phase_off_forced_counts[k][1], (unsigned long long)phase_off_queried_counts[k][1]); fprintf(stderr, " (off/queried)\n"); }); } }
        for (int k = 0; k < phase_off_count; k++) if (!strcmp(phase_off_names[k], name)) {
