}
int ds4_gpu_llms_alt_off(const char *name) { return llms_alt_off(name); }

static uint64_t llms_ksdef_seen[64];   /* llms AMB 11-04: the K-split S each UNMAPPED shape ran, printed at FIRST SIGHT -- lock-free (one CAS into a fixed open-addressed table of packed keys), no mutex, no exit handler */
static void llms_ksdef_note(unsigned k, unsigned r, int s) {
    const uint64_t key = ((uint64_t)k << 40) | ((uint64_t)r << 8) | (uint64_t)(s & 0xff) | (1ull << 63);
    for (uint32_t i = 0, h = (uint32_t)((key * 0x9E3779B97F4A7C15ull) >> 58); i < 64u; i++, h = (h + 1u) & 63u) {
        uint64_t cur = __atomic_load_n(&llms_ksdef_seen[h], __ATOMIC_RELAXED);
