    [enc setBuffer:obuf offset:ooff atIndex:3];
    [enc setThreadgroupMemoryLength:(NSUInteger)nsg * (nr * 32u * 2u + 512u) + (NSUInteger)nsg * nr * 8u * 4u atIndex:0];
    [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)a.rows + nr - 1u) / nr, 1, (NSUInteger)a.n_groups) threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)nsg, 1)];
    return 1;
}
/* llms EXT_SGM16 (apply_ds4_ext_sgm.py part 2): the 16-token form (two activation tiles per weight tile) for the output head. 1 on, -1 canary */
static uint64_t sgm16_calls;
static void report_sgm16(void) { fprintf(stderr, "llms ext sgm16: %llu dispatches\n", (unsigned long long)sgm16_calls); }
static int ext_sgm16_on(void) {
    static int on = -2;
    if (on < -1) { const char *e = getenv("LLMS_DS4_EXT_SGM16"); on = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
                   if (on) { fprintf(stderr, on < 0 ? "llms: ext sgm16 -- CANARY: the activation stride halved\n" : "llms: ext sgm16 (16-token dense Q8 matvec on tiles: the output head; NOT bit-exact)\n"); atexit(report_sgm16); } }
    return on;
}
/* llms EXT_SGM (apply_ds4_ext_sgm.py): the 8-token dense Q8 matvec on simdgroup-matrix tiles. 1 on, 2 force k, 3 force r, -1 canary */
static uint64_t sgm_calls;
static void report_sgm(void) { fprintf(stderr, "llms ext sgm: %llu dispatches\n", (unsigned long long)sgm_calls); }
static int ext_sgm_on(void) {
    static int on = -2;
    if (on < -1) { const char *e = getenv("LLMS_DS4_EXT_SGM"); on = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : !strcmp(e, "k") ? 2 : !strcmp(e, "r") ? 3 : 1;
                   if (on) { fprintf(stderr, on < 0 ? "llms: ext sgm -- CANARY: the activation stride halved\n" : "llms: ext sgm %d (8-token dense Q8 matvec on simdgroup-matrix tiles; NOT bit-exact)\n", on); atexit(report_sgm); } }
    return on;
}
/* llms EXT_RPT (apply_ds4_ext_rpt.py): rows per lane in the batched Q8 ext matvec. 2 or 4; canary = 4 with the grid of 1 */
static uint64_t ext_rpt_calls;
static void report_ext_rpt(void) { fprintf(stderr, "llms ext rpt: %llu dispatches\n", (unsigned long long)ext_rpt_calls); }
/* llms T32_BF16 (apply_t32_bf16.py) */
static int t32_round, t32_rounded; static uint64_t t32_bf16_calls;
static void report_t32_bf16(void) { fprintf(stderr, "llms t32 bf16: %llu folded roundings\n", (unsigned long long)t32_bf16_calls); }
void ds4_gpu_llms_t32_round(int on) { t32_round = on; t32_rounded = 0; }
static int mvb16_on(int which) {   /* llms MVB16 (apply_mvb16.py; adopted, the switch removed 10-27): which 0: the BF16 rounding folded into the Q8_0 matvec store
                                       (the dense source *_mvb*), 1: into the weighted RMS norm store (the norm source norm_mvb*) */
    static int on[2] = { -1, -1 };
    if (on[0] < 0) { const char *ds = getenv("DS4_METAL_DENSE_SOURCE"), *ns = getenv("DS4_METAL_NORM_SOURCE");
                     on[0] = ds && llms_srckey(ds, "_mvb") != NULL; on[1] = ns && llms_srckey(ns, "norm_mvb") != NULL; }
    return on[which];
}
int ds4_gpu_llms_t32_rounded(void) { return t32_rounded; }
static const char *ds4_gpu_mv_ext_name(int q8, int16_t r1ptg) {
    if (q8 && r1ptg == 8) return "kernel_mul_mv_ext_q8_0_f32_r1_8";   /* llms EXT_R8: in build_idx/dense_llms.metal only */
    if (q8) {
        switch (r1ptg) {
        case 2: return "kernel_mul_mv_ext_q8_0_f32_r1_2";
        case 3: return "kernel_mul_mv_ext_q8_0_f32_r1_3";
        case 4: return "kernel_mul_mv_ext_q8_0_f32_r1_4";
        case 5: return "kernel_mul_mv_ext_q8_0_f32_r1_5";
        default: return NULL;
        }
    }

    switch (r1ptg) {
    case 2: return "kernel_mul_mv_ext_f16_f32_r1_2";
    case 3: return "kernel_mul_mv_ext_f16_f32_r1_3";
    case 4: return "kernel_mul_mv_ext_f16_f32_r1_4";
    case 5: return "kernel_mul_mv_ext_f16_f32_r1_5";
    default: return NULL;
    }
}

static const char *ds4_gpu_mv_ext_f32_name(int16_t r1ptg) {
    switch (r1ptg) {
    case 2: return "kernel_mul_mv_ext_f32_f32_r1_2";
    case 3: return "kernel_mul_mv_ext_f32_f32_r1_3";
    case 4: return "kernel_mul_mv_ext_f32_f32_r1_4";
    case 5: return "kernel_mul_mv_ext_f32_f32_r1_5";
