/* Compile the single in-repo Metal source and create the pipelines that every
 * session uses. Shape-dependent kernels with function constants are built
 * lazily by the small ds4_gpu_get_* caches, so startup stays predictable
 * while long-context prefill and decode can still pick specialized variants. */
/* llms ROUTING_CONTRACT (apply_routing_contract.py): expert routing as ONE concept, decided once, enforced. */
static void check_routing_contract(void) {
    static int done; if (done) return; done = 1;
    static const char *knobs[4] = {"LLMS_DS4_DECODE_ROUTE", "LLMS_DS4_DECODE_ROUTE_LATE", "LLMS_DS4_PREFILL_ROUTE", "LLMS_DS4_APPEND_ROUTE_POLICY"};
    const char *r = getenv("LLMS_DS4_ROUTING");
    const int bonus = r && !strcmp(r, "bonus");
    if (r && *r && !bonus && strcmp(r, "exact")) { fprintf(stderr, "llms: LLMS_DS4_ROUTING must be 'exact' or 'bonus' (got '%s')\n", r); exit(2); }
    if (bonus) { fprintf(stderr, "llms routing: bonus -- FIDELITY DIAL (cache-state-dependent expert selection; outputs are not the model's and not repeatable)\n"); return; }
    for (int i = 0; i < 4; i++) {
        const char *v = getenv(knobs[i]);
        if (v && *v && strcmp(v, "0") && strtod(v, NULL) != 0.0) {
            fprintf(stderr, "llms: ROUTING CONTRACT VIOLATED: LLMS_DS4_ROUTING=exact but %s=%s (set LLMS_DS4_ROUTING=bonus to use the fidelity dial)\n", knobs[i], v);
            exit(2);
        }
        setenv(knobs[i], "0", 1);
    }
    fprintf(stderr, "llms routing: exact (contract: ONE_RPOL / ONE_RPOL_LATE / RPOL / SP_RPOL forced 0)\n");
}
static int ds4_gpu_init_unguarded(void);   /* llms GUARDS (apply_initguard.py): upstream's init, unchanged; under LLMS_DS4_GUARDS any of its 192 failure paths is fatal */
int ds4_gpu_init(void) {
    const int ok = ds4_gpu_init_unguarded();
    if (!ok) llms_guard_fail("Metal init failed (the line above names the kernel or the step that failed)");
    return ok;
}
static int ds4_gpu_init_unguarded(void) {
