                    (unsigned long long)pipelines_created, pipeline_creation_ms, (unsigned long long)functions_created, function_creation_ms,
                    (unsigned long long)creations_by_phase[0], creation_ms_by_phase[0], (unsigned long long)creations_by_phase[1], creation_ms_by_phase[1],
