/* llms HC_OWED (apply_owed.py; ds4_gpu.h has the record type): one owed record per side. Replaces ds4.c's g_llms_ps2 / g_llms_pm2 slots with their two flush helpers and three copy-pasted fills, and this file's two side channels (the k2m setter, the hcfr mode). A record is settled exactly once: TAKEN by the side's dual dispatch (ds4_gpu_llms_q4l_k2_dual), FORCED as its own kernels (ds4_gpu_llms_owed_force, by any other reader), or DROPPED by ds4_gpu_tensor_free when a tensor it names dies -- the drop is what makes the 02:40 crash (a record carrying a step's freed views into the next step's flush) impossible in every scope. Dead work only: the owed tail writes split / mix of rows whose step is over. */
/* llms SP_BCTX: moved to struct sp_bctx */ /* owed_work */
static uint64_t owed_counts[2][4], owed_overwrites;   /* [kind 1, kind 2][owed, taken, forced, dropped at a free] */
static void report_owed(void) {
    fprintf(stderr, "llms hc owed: split %llu owed / %llu taken by a dual / %llu forced / %llu dropped at a free; mixer+split %llu / %llu / %llu / %llu; %llu overwrites\n",
            (unsigned long long)owed_counts[0][0], (unsigned long long)owed_counts[0][1], (unsigned long long)owed_counts[0][2], (unsigned long long)owed_counts[0][3],
            (unsigned long long)owed_counts[1][0], (unsigned long long)owed_counts[1][1], (unsigned long long)owed_counts[1][2], (unsigned long long)owed_counts[1][3],
            (unsigned long long)owed_overwrites);
}
static void drop_owed_for(const ds4_gpu_tensor *t) {
    for (int w = 0; w < 2; w++) {
        ds4_gpu_llms_owed *r = &owed_work[w];
        if (r->kind && (t == r->split || t == r->mix || t == r->xo || t == r->no || t == r->hin || t == r->pre)) {
            static int warning_printed; if (!warning_printed++) fprintf(stderr, "llms hc owed: WARNING a side-%d kind-%d record was dropped unsettled when its %s died -- if a reader skipped its force, its rows read a stale split\n",
                w, r->kind, t == r->split ? "split" : t == r->mix ? "mix" : t == r->xo ? "x" : t == r->no ? "norm" : t == r->hin ? "hin" : "pre");   /* llms HC_OWED: the first drop of a run says so (apply_owed_drop_loud.py) */
            owed_counts[r->kind - 1][3]++; r->kind = 0;
        }
    }
}
int ds4_gpu_llms_owed_force(int side) {
    for (int w = side < 0 ? 0 : side; w <= (side < 0 ? 1 : side); w++) {
        const ds4_gpu_llms_owed r = owed_work[w];
        if (!r.kind) continue;
        owed_work[w].kind = 0; owed_counts[r.kind - 1][2]++;
        if (r.kind == 2 && !ds4_gpu_llms_hc_pre_fused_rows(r.split, r.xo, r.no, r.hin, r.pre, r.pre_stride, r.mix, r.map, r.size, r.fn_off, r.scale_off, r.base_off,
                                                          r.nw_off, r.n_embd, r.n_hc, r.iters, r.rms_eps, r.hc_eps, r.flags | DS4_GPU_LLMS_HCFR_MIX, r.rows)) return 0;
        if (!ds4_gpu_hc_split_sinkhorn_tensor(r.split, r.mix, r.map, r.size, r.scale_off, r.base_off, r.n_hc, r.iters, r.hc_eps)) return 0;
    }
    return 1;
}
void ds4_gpu_llms_owe(int side, const ds4_gpu_llms_owed *rec) {
    static int exit_report_registered; if (!exit_report_registered) { exit_report_registered = 1; atexit(report_owed); }
    if (owed_work[side].kind) { owed_overwrites++; (void)ds4_gpu_llms_owed_force(side); }   /* never overwrite an unsettled record */
    owed_work[side] = *rec; owed_counts[rec->kind - 1][0]++;
}

ds4_gpu_tensor *ds4_gpu_tensor_view(const ds4_gpu_tensor *base, uint64_t offset, uint64_t bytes) {
    if (!base) return NULL;
    const DS4MetalTensor *base_obj = ds4_gpu_tensor_const_obj(base);
    if (offset > base_obj.bytes || bytes > base_obj.bytes - offset) return NULL;
    if (base_obj.offset > UINT64_MAX - offset) return NULL;
    const uint64_t absolute_offset = base_obj.offset + offset;
    if (absolute_offset > (uint64_t)NSUIntegerMax) return NULL;

    @autoreleasepool {
        DS4MetalTensor *view = [DS4MetalTensor new];
        view.buffer = base_obj.buffer;
        view.offset = absolute_offset;
        view.bytes = bytes;
        view.owner = 0;
        pthread_mutex_lock(&g_tensor_mu);
        const int tracked = ds4_gpu_tensor_track_view_locked((__bridge const void *)view);
        pthread_mutex_unlock(&g_tensor_mu);
        if (!tracked) {
            fprintf(stderr, "ds4: failed to track Metal tensor view\n");
            view.buffer = nil;
            return NULL;
        }
        return (__bridge_retained ds4_gpu_tensor *)view;
    }
}

void ds4_gpu_tensor_free(ds4_gpu_tensor *tensor) {
    if (!tensor) return;
    if (owed_work[0].kind | owed_work[1].kind) drop_owed_for(tensor);   /* llms HC_OWED: no record outlives a tensor it names */
    @autoreleasepool {
        uint8_t owner = 0;
        uint64_t bytes = 0;
        uint64_t live_snap = 0;
        uint64_t peak_snap = 0;
        if (!ds4_gpu_tensor_prepare_free(tensor,
                                         &owner,
                                         &bytes,
                                         &live_snap,
                                         &peak_snap)) {
            return;
        }
        DS4MetalTensor *obj = (__bridge_transfer DS4MetalTensor *)tensor;
        if (owner) {
            if (ds4_gpu_trace_allocs()) {
                fprintf(stderr,
                        "ds4: Metal tensor free %.3f MiB live %.3f MiB peak %.3f MiB\n",
                        (double)bytes / (1024.0 * 1024.0),
                        (double)live_snap / (1024.0 * 1024.0),
                        (double)peak_snap / (1024.0 * 1024.0));
            }
        }
        obj.buffer = nil;
        obj.offset = 0;
        obj.bytes = 0;
        obj.owner = 0;
    }
}

uint64_t ds4_gpu_tensor_bytes(const ds4_gpu_tensor *tensor) {
    if (!tensor) return 0;
    const DS4MetalTensor *obj = ds4_gpu_tensor_const_obj(tensor);
    return obj.bytes;
}

static int arpool_state = -1; static uint64_t arpool_calls;   /* llms ARPOOL (apply_arpool.py): LLMS_DS4_ARPOOL=1, off unless set */
static int arpool_on(void) { if (arpool_state < 0) { const char *e = getenv("LLMS_DS4_ARPOOL"); arpool_state = e && *e && *e != '0';
    if (arpool_state) { fprintf(stderr, "llms: arpool (the tensor accessors' -contents inside @autoreleasepool; upstream a4c922c56091)\n");
                        atexit_b(^{ fprintf(stderr, "llms arpool: %llu pooled accessor calls\n", (unsigned long long)arpool_calls); }); } }
    return arpool_state; }
void *ds4_gpu_tensor_contents(ds4_gpu_tensor *tensor) {
    if (!tensor) return NULL;
    DS4MetalTensor *obj = ds4_gpu_tensor_obj(tensor);
    if (arpool_on()) { arpool_calls++; @autoreleasepool { return (uint8_t *)[obj.buffer contents] + obj.offset; } }   /* llms ARPOOL */
    return (uint8_t *)[obj.buffer contents] + obj.offset;
}

int ds4_gpu_tensor_fill_f32(ds4_gpu_tensor *tensor, float value, uint64_t count) {
    if (!tensor || count > ds4_gpu_tensor_bytes(tensor) / sizeof(float)) return 0;
    float *p = ds4_gpu_tensor_contents(tensor);
    if (!p && count != 0) return 0;
    for (uint64_t i = 0; i < count; i++) p[i] = value;
    return 1;
}

int ds4_gpu_tensor_write(ds4_gpu_tensor *tensor, uint64_t offset, const void *data, uint64_t bytes) {
    if (!tensor || (!data && bytes != 0)) return 0;
    DS4MetalTensor *obj = ds4_gpu_tensor_obj(tensor);
    if (offset > obj.bytes || bytes > obj.bytes - offset) return 0;
    if (bytes != 0) {
        if (arpool_on()) { arpool_calls++; @autoreleasepool { memcpy((uint8_t *)[obj.buffer contents] + obj.offset + offset, data, (size_t)bytes); } }   /* llms ARPOOL */
        else memcpy((uint8_t *)[obj.buffer contents] + obj.offset + offset, data, (size_t)bytes);
    }
    return 1;
}

int ds4_gpu_tensor_read(const ds4_gpu_tensor *tensor, uint64_t offset, void *data, uint64_t bytes) {
    if (!tensor || (!data && bytes != 0)) return 0;
    const DS4MetalTensor *obj = ds4_gpu_tensor_const_obj(tensor);
    if (offset > obj.bytes || bytes > obj.bytes - offset) return 0;
    if (bytes != 0) {
        if (arpool_on()) { arpool_calls++; @autoreleasepool { memcpy(data, (const uint8_t *)[obj.buffer contents] + obj.offset + offset, (size_t)bytes); } }   /* llms ARPOOL */
        else memcpy(data, (const uint8_t *)[obj.buffer contents] + obj.offset + offset, (size_t)bytes);
    }
    return 1;
}

/* llms COPY_KERNEL (apply_ds4_copy_kernel.py): tensor copies as a compute dispatch on the open encoder instead of a blit encoder */


static int k3x_on(void) {   /* llms K3X (apply_k3x_live.py): the third verify row on the two-row fast paths; ALT k3x */
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_K3X"); on = e && *e && *e != '0';
                  if (on && !ds4_gpu_get_mul_mv_pipeline("kernel_llms_q4l_mv_kgxh3", 4)) {
                      fprintf(stderr, "llms: LLMS_DS4_K3X ignored: DS4_METAL_DENSE_SOURCE lacks the 3-row twins (kernel_llms_q4l_mv_kgxh3)\n"); on = 0; }
                  if (on) fprintf(stderr, "llms: k3x (3-row verify matvecs on half x / HXO / N1X / LEAN2 / F16 / BF16 / KGX; the routed down's colz2 at 2-4 tokens)\n"); }
    return on && !llms_alt_off("k3x");
}

static int k4x_on(void) {   /* llms K4X (apply_k4x.py): the fourth verify row on the fast paths; ALT k4x */
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_K4X"); on = e && *e && *e != '0';
                  if (on && !has_kernel("kernel_llms_q4l_mv_kgxh4")) { fprintf(stderr, "llms: LLMS_DS4_K4X ignored: DS4_METAL_DENSE_SOURCE lacks the four-row twins (kernel_llms_q4l_mv_kgxh4)\n"); on = 0; }
                  if (on) fprintf(stderr, "llms: k4x (4-row verify: half x / HXO / KGX / F16 / BF16 k-family / the duals and HC fusions at four rows)\n"); }
    return on && !llms_alt_off("k4x");
}
/* llms SNAP_BATCH (apply_snap_batch.py): the 40 per-layer raw windows' step rows to / from the linear snapshot in 2 dispatches (kernel_llms_snap_rows20); 0 = nothing encoded, the caller copies one by one */
int ds4_gpu_llms_snap_windows(ds4_gpu_tensor *const *windows, ds4_gpu_tensor *lin, uint32_t pos0, uint32_t row0, uint32_t nrows, uint32_t snap_rows, uint32_t dir) {
    if (!windows || !lin || nrows == 0u || nrows > 8u || row0 == 0u || snap_rows < row0 + nrows - 1u || dir > 1u || !g_batch_cb) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    for (uint32_t i = 0; i < 40u; i++) if (!windows[i]) return 0;
    id<MTLComputePipelineState> pso = ds4_gpu_get_pipeline_or_die("kernel_llms_snap_rows20");
    if (!pso) return 0;
    DS4MetalTensor *ln = ds4_gpu_tensor_obj(lin);
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(g_batch_cb);
    if (!enc) return 0;
    g_batch_has_work = YES;
    for (uint32_t c = 0; c < 2u; c++) {
        const uint32_t args[8] = { pos0, row0, nrows, c * 20u, snap_rows, dir, 0u, 0u };
        [enc setComputePipelineState:pso];
        [enc setBytes:args length:sizeof(args) atIndex:0];
        for (uint32_t i = 0; i < 20u; i++) { DS4MetalTensor *w = ds4_gpu_tensor_obj(windows[c * 20u + i]); [enc setBuffer:w.buffer offset:(NSUInteger)w.offset atIndex:1 + i]; }
        [enc setBuffer:ln.buffer offset:(NSUInteger)ln.offset atIndex:21];
        [enc dispatchThreadgroups:MTLSizeMake(20, nrows, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    }
    ds4_gpu_end_compute_encoder(g_batch_cb, enc);
    return 1;
}

int ds4_gpu_tensor_copy(ds4_gpu_tensor *dst, uint64_t dst_offset,
                          const ds4_gpu_tensor *src, uint64_t src_offset,
                          uint64_t bytes) {
    if (!dst || !src) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    DS4MetalTensor *d = ds4_gpu_tensor_obj(dst);
    const DS4MetalTensor *s = ds4_gpu_tensor_const_obj(src);
    if (dst_offset > d.bytes || bytes > d.bytes - dst_offset) return 0;
    if (src_offset > s.bytes || bytes > s.bytes - src_offset) return 0;
    if (bytes == 0) return 1;
    if (!g_batch_cb) return 0;

    {   /* llms COPY_LOG (apply_copy_log.py): a (bytes, caller) histogram of every tensor copy, printed at exit */
        static int copy_log_state = -1; static struct { uint64_t bytes; uintptr_t caller; uint64_t n; } copy_log_histogram[4096]; static int copy_log_entries; static uint64_t cl_lost;
        if (copy_log_state < 0) { const char *e = getenv("LLMS_DS4_COPY_LOG"); copy_log_state = e && *e && *e != '0';
                      if (copy_log_state) { fprintf(stderr, "llms: copy log (every tensor copy counted by bytes and caller)\n");
                                atexit_b(^{ int idx[4096]; for (int i = 0; i < copy_log_entries; i++) idx[i] = i;
                                            for (int i = 0; i < copy_log_entries; i++) for (int j = i + 1; j < copy_log_entries; j++) if (copy_log_histogram[idx[j]].n * copy_log_histogram[idx[j]].bytes > copy_log_histogram[idx[i]].n * copy_log_histogram[idx[i]].bytes) { int t = idx[i]; idx[i] = idx[j]; idx[j] = t; }
                                            fprintf(stderr, "llms copy log: %d distinct (bytes, caller), %llu lost; top by bytes moved (count x bytes = MB, caller unslid):\n", copy_log_entries, (unsigned long long)cl_lost);
                                            for (int i = 0; i < copy_log_entries && i < 24; i++) fprintf(stderr, "   %8llu x %10llu B = %9.2f MB  0x%llx\n", (unsigned long long)copy_log_histogram[idx[i]].n, (unsigned long long)copy_log_histogram[idx[i]].bytes, (double)copy_log_histogram[idx[i]].n * (double)copy_log_histogram[idx[i]].bytes / 1048576.0, (unsigned long long)(copy_log_histogram[idx[i]].caller - (uintptr_t)_dyld_get_image_vmaddr_slide(0)));
                                            for (int i = 0; i < copy_log_entries; i++) for (int j = i + 1; j < copy_log_entries; j++) if (copy_log_histogram[idx[j]].n > copy_log_histogram[idx[i]].n) { int t = idx[i]; idx[i] = idx[j]; idx[j] = t; }   /* 10-23 00:4x: the dispatch COUNT is the question for the 2 KB copies */
                                            fprintf(stderr, "llms copy log: top by count (count x bytes = MB, caller unslid):\n");
                                            for (int i = 0; i < copy_log_entries && i < 24; i++) fprintf(stderr, "   %8llu x %10llu B = %9.2f MB  0x%llx\n", (unsigned long long)copy_log_histogram[idx[i]].n, (unsigned long long)copy_log_histogram[idx[i]].bytes, (double)copy_log_histogram[idx[i]].n * (double)copy_log_histogram[idx[i]].bytes / 1048576.0, (unsigned long long)(copy_log_histogram[idx[i]].caller - (uintptr_t)_dyld_get_image_vmaddr_slide(0))); }); } }
        if (copy_log_state) { const uintptr_t caller = (uintptr_t)__builtin_return_address(0); int i = 0;
