typedef struct { IOSurfaceRef s; id<MTLBuffer> b; id o; } ane_surface;
static int ane_dense_mode = -1; static id ane_dense_programs[ANE_LAYERS][4];
static unsigned ane_dense_layers = ANE_LAYERS; static int ane_dense_wired, ane_dense_warm;   /* llms V12B_LOAD: layers 0..ane_dense_layers-1 loaded; wired; warmed */
