#define INL2_C 4096u
static uint32_t inl2_call[INL2_G]; static float inl2_t[INL2_G], inl2_d[INL2_G]; static unsigned inl2_n; static double inl2_beg[INL2_C], inl2_end[INL2_C];   /* llms INLOAD2 */
