static int inload_cmpf(const void *x, const void *y) { const float a = *(const float *)x, b = *(const float *)y; return a < b ? -1 : a > b; }
static float inload_med(const float *v, unsigned n) { static float t[4096 * 8]; if (!n) return 0.0f; if (n > 4096u * 8u) n = 4096u * 8u; memcpy(t, v, n * sizeof(float)); qsort(t, n, sizeof(float), inload_cmpf); return t[n / 2]; }
static void inload_report(void) {
    static float pool[4096 * 8]; unsigned np; const unsigned bins[7] = { 0, 1, 2, 5, 10, 20, 32 };
    fprintf(stderr, "llms ane inload: warm (200 groups back to back, in process) median %.3f ms a group; FAILED %ld evaluations; by group index in the call:", inload_warm_ms, inload_failed);
    for (int b = 0; b + 1 < 7; b++) { np = 0; for (unsigned k = bins[b]; k < bins[b + 1]; k++) for (unsigned i = 0; i < inload_gn[k] && np < 4096u * 8u; i++) pool[np++] = inload_g[k][i];
        if (np) fprintf(stderr, " %u-%u: n %u median %.2f (x%.2f)", bins[b], bins[b + 1] - 1, np, inload_med(pool, np), inload_warm_ms > 0 ? inload_med(pool, np) / inload_warm_ms : 0.0); }
    fprintf(stderr, "; the first 12 one by one (x warm):"); for (unsigned k = 0; k < 12; k++) if (inload_gn[k]) fprintf(stderr, " %.2f", inload_warm_ms > 0 ? inload_med(inload_g[k], inload_gn[k]) / inload_warm_ms : 0.0);
    fprintf(stderr, "\n");
    {   /* llms INLOAD2: by ms since the call's start, and by ms before its end (calls with a recorded end only) */
        static float pool2[INL2_G]; const float sb[7] = { 0, 100, 250, 500, 750, 1000, 1e9 }, eb[7] = { 0, 50, 100, 200, 400, 800, 1e9 };
        fprintf(stderr, "llms ane inload v2: %u groups; by ms since the call's start:", inl2_n);
        for (int b = 0; b + 1 < 7; b++) { unsigned np = 0; for (unsigned i = 0; i < inl2_n; i++) if (inl2_t[i] >= sb[b] && inl2_t[i] < sb[b + 1]) pool2[np++] = inl2_d[i];
            if (np) fprintf(stderr, " %.0f-%.0f: n %u x%.2f", sb[b], sb[b + 1] > 1e8 ? 9999.0 : sb[b + 1], np, inload_warm_ms > 0 ? inload_med(pool2, np) / inload_warm_ms : 0.0); }
        fprintf(stderr, "; by ms before the call's end:");
        for (int b = 0; b + 1 < 7; b++) { unsigned np = 0;
            for (unsigned i = 0; i < inl2_n; i++) { const uint32_t c = inl2_call[i]; if (c >= INL2_C || inl2_end[c] <= inl2_beg[c]) continue;
                const double before = inl2_end[c] - (inl2_beg[c] + inl2_t[i]); if (before >= eb[b] && before < eb[b + 1]) pool2[np++] = inl2_d[i]; }
            if (np) fprintf(stderr, " %.0f-%.0f: n %u x%.2f", eb[b], eb[b + 1] > 1e8 ? 9999.0 : eb[b + 1], np, inload_warm_ms > 0 ? inload_med(pool2, np) / inload_warm_ms : 0.0); }
        fprintf(stderr, "\n"); }
}
static void *inload_thread(void *arg) {
    (void)arg; pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0); pthread_setname_np("llms.inload");
    for (;;) {
        while (!__atomic_load_n(&inload_phase, __ATOMIC_ACQUIRE)) usleep(1000);
        const uint64_t call = __atomic_load_n(&inload_seq, __ATOMIC_ACQUIRE); unsigned k = 0;
        while (__atomic_load_n(&inload_phase, __ATOMIC_ACQUIRE) && __atomic_load_n(&inload_seq, __ATOMIC_ACQUIRE) == call) {
            const double tg = inload_now_ms(); const double a = inload_eval2(0); usleep(23000); const double b = inload_eval2(2); usleep(23000);
            if (inl2_n < INL2_G && call < INL2_C) { inl2_call[inl2_n] = (uint32_t)call; inl2_t[inl2_n] = (float)(tg - inl2_beg[call]); inl2_d[inl2_n] = (float)(a + b); inl2_n++; }   /* llms INLOAD2 */
            const unsigned kk = k < 31u ? k : 31u; if (inload_gn[kk] < 4096u) inload_g[kk][inload_gn[kk]++] = (float)(a + b); k++;
        }
    }
    return NULL;
}
static int inload_start(void) {
