    Class CL = objc_getClass("_ANEClient"), MD = objc_getClass("_ANEModel"), RQ = objc_getClass("_ANERequest"), SO = objc_getClass("_ANEIOSurfaceObject");
    if (!CL || !MD || !RQ || !SO) { fprintf(stderr, "llms ane inload: the ANE classes are missing -- off\n"); return 0; }
    inload_cl = ((id(*)(Class, SEL))objc_msgSend)(CL, sel_registerName("sharedConnection"));
    NSDictionary *opt = @{@"kANEFModelType": @"kANEFModelMIL", @"kANEFKeepModelMemoryWiredKey": @YES};
    const char *paths[4] = { "L1_qakv", "L1_qb", "L2_qakv", "L2_qb" }; const int K[4] = { 5120, 1280, 5120, 1280 }, N1[4] = { 512, 16384, 512, 16384 }, N2[4] = { 1280, 16384, 1280, 16384 };
    for (int j = 0; j < 4; j++) {
        NSString *p = [NSString stringWithFormat:@"ane/dense2s/%s.mlmodelc", paths[j]]; NSError *e = nil;
        id md = ((id(*)(Class, SEL, id, id))objc_msgSend)(MD, sel_registerName("modelAtURL:key:"), [NSURL fileURLWithPath:p], [NSString stringWithFormat:@"inl_%d", j]);
        const BOOL ok = md && ((BOOL(*)(id, SEL, id, id, NSInteger, NSError **))objc_msgSend)(inload_cl, sel_registerName("compileModel:options:qos:error:"), md, opt, (NSInteger)0x21, &e)
                           && ((BOOL(*)(id, SEL, id, id, NSInteger, NSError **))objc_msgSend)(inload_cl, sel_registerName("loadModel:options:qos:error:"), md, opt, (NSInteger)0x21, &e);
        if (!ok) { fprintf(stderr, "llms ane inload: load FAILED %s (%s) -- off\n", paths[j], e ? [[e localizedDescription] UTF8String] : "?"); return 0; }
        IOSurfaceRef sx = ((IOSurfaceRef(*)(Class, SEL, NSInteger, NSInteger, NSInteger))objc_msgSend)(SO, sel_registerName("createIOSurfaceWithWidth:pixel_size:height:"), K[j], 2, 128);
        IOSurfaceRef sy = ((IOSurfaceRef(*)(Class, SEL, NSInteger, NSInteger, NSInteger))objc_msgSend)(SO, sel_registerName("createIOSurfaceWithWidth:pixel_size:height:"), N1[j], 2, 128);
        IOSurfaceRef sz = ((IOSurfaceRef(*)(Class, SEL, NSInteger, NSInteger, NSInteger))objc_msgSend)(SO, sel_registerName("createIOSurfaceWithWidth:pixel_size:height:"), N2[j], 2, 128);
        id ino = ((id(*)(Class, SEL, IOSurfaceRef))objc_msgSend)(SO, sel_registerName("objectWithIOSurface:"), sx), outo = ((id(*)(Class, SEL, IOSurfaceRef))objc_msgSend)(SO, sel_registerName("objectWithIOSurface:"), sy);
        id outz = ((id(*)(Class, SEL, IOSurfaceRef))objc_msgSend)(SO, sel_registerName("objectWithIOSurface:"), sz);
        inload_m[j] = md; inload_r[j] = ((id(*)(Class, SEL, id, id, id, id, NSUInteger))objc_msgSend)(RQ, sel_registerName("requestWithInputs:inputIndices:outputs:outputIndices:procedureIndex:"), @[ino], @[@0], @[outo, outz], @[@0, @1], (NSUInteger)0);
    }
    for (int w = 0; w < 6; w++) { (void)inload_eval2(0); (void)inload_eval2(2); }
    static float wv[200]; for (int i = 0; i < 200; i++) wv[i] = (float)(inload_eval2(0) + inload_eval2(2)); inload_warm_ms = inload_med(wv, 200);
    fprintf(stderr, "llms ane inload: 4 programs loaded in process (dense2s L1 / L2 qakv + qb, wired, zero inputs); warm %.3f ms a group (200 back to back); FAILED so far %ld\n", inload_warm_ms, inload_failed);
