int ds4_gpu_llms_commit_close(void) {   /* llms BATCH_SAS / BATCH_PIPE */
    if (!g_batch_cb) return 1;
    ds4_gpu_close_batch_encoder();
    id<MTLCommandBuffer> cb = g_batch_cb;
    g_batch_cb = nil;
    g_batch_has_work = NO;
    const uint64_t batch_buffer_seq = g_stream_expert_cache_batch_seq;   /* precise completion: advance done_seq when THIS buffer finishes */
    if (batch_buffer_seq) [cb addCompletedHandler:^(id<MTLCommandBuffer> done_cb) {
        (void)done_cb;
        uint64_t cur = __atomic_load_n(&g_stream_expert_cache_done_seq, __ATOMIC_ACQUIRE);
        while (batch_buffer_seq > cur &&
               !__atomic_compare_exchange_n(&g_stream_expert_cache_done_seq, &cur, batch_buffer_seq, false, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {}
    }];
    track_command_buffer(cb); llms_order_commit(cb); all_commits++; substream_generation++;   /* llms SUBSTREAMS: a new generation per committed batch buffer */
    [g_pending_cbs addObject:cb];
    ds4_gpu_stream_expert_cache_note_batch_committed();
    return 1;
}
