                                           ds4_gpu_tensor_offset(tokens),
                                           g_embed_rows_buffer,
                                           0,
                                           n_vocab,
                                           n_tokens,
                                           n_embd) ||
            !ds4_gpu_encode_repeat_hc_embedding(cb,
                                                  g_embed_rows_buffer,
                                                  0,
                                                  outbuf,
                                                  ds4_gpu_tensor_offset(out_hc),
                                                  n_tokens,
                                                  n_embd,
                                                  n_hc)) {
            return 0;
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "graph embed tokens")) return 0;
    }

    return 1;
}

int ds4_gpu_set_model_map_range(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size, uint64_t max_tensor_bytes) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!model_map || model_size == 0) return 0;
    if (map_offset > model_size || map_size == 0 || map_size > model_size - map_offset) return 0;
    max_tensor_bytes = ds4_gpu_effective_model_max_tensor_bytes(map_size, max_tensor_bytes);

    @autoreleasepool {
        if (g_model_map_ptr == model_map &&
            g_model_map_size == model_size &&
            g_model_mapped_offset == map_offset &&
            g_model_mapped_size == map_size &&
            g_model_mapped_max_tensor_bytes == max_tensor_bytes) {
            return 1;
        }

        for (uint32_t i = 0; i < g_model_view_count; i++) {
            if (g_model_views[i].model_map == model_map &&
                g_model_views[i].model_size == model_size &&
                map_offset >= g_model_views[i].model_offset &&
                map_offset + map_size <= g_model_views[i].model_offset + g_model_views[i].bytes) {
                return 1;
            }
        }

        ds4_gpu_model_residency_clear();
        if (!ds4_gpu_map_model_views(model_map, model_size, map_offset, map_size, max_tensor_bytes)) {
            ds4_gpu_model_residency_clear();
            return 0;
        }
        g_model_map_ptr = model_map;
        g_model_map_size = model_size;
        g_model_mapped_offset = map_offset;
        g_model_mapped_size = map_size;
        g_model_mapped_max_tensor_bytes = max_tensor_bytes;
        if (ds4_gpu_model_map_log_enabled()) {
            fprintf(stderr,
                    "ds4: Metal mapped mmaped model as %u overlapping shared buffers\n",
                    g_model_view_count);
        }
        return 1;
    }
}

static int ds4_gpu_model_views_cover_spans(
        const void     *model_map,
        uint64_t        model_size,
        const uint64_t *offsets,
        const uint64_t *sizes,
        uint32_t        count);

/* llms Q4L_UNLOCK (apply_q4l_unlock.py): the Q8_0 originals of the Q4L-listed tensors (which one-token decode never reads) get views of
   their own and are left out of the static-weight mlock. Exact byte ranges from the Q4L index, sorted; top-level preallocated split buffers. */
static int q4l_unlock_count = -1; static uint64_t *q4l_unlock_lo, *q4l_unlock_hi;
static uint64_t *q4l_unlock_offsets, *q4l_unlock_sizes; static uint32_t q4l_unlock_capacity;
static void init_q4l_unlock(void) {
    q4l_unlock_count = 0;
    const char *idx = getenv("LLMS_DS4_Q4L");   /* llms Q4L_UNLOCK (adopted; the switch removed 10-27): whenever a Q4L index is named */
    if (!idx || !*idx || !strcmp(idx, "0")) return;
    FILE *f = fopen(idx, "r");
    if (!f) { fprintf(stderr, "llms: Q4L_UNLOCK cannot open %s\n", idx); return; }
    char line[1024]; int cap = 256, n = 0;
    uint64_t *lo = malloc((size_t)cap * sizeof *lo), *hi = malloc((size_t)cap * sizeof *hi);
    if (!fgets(line, sizeof line, f) || !fgets(line, sizeof line, f)) { fclose(f); free(lo); free(hi); return; }   /* path, gguf_bytes */
    unsigned long long ab, of; unsigned k, nn; char name[512];
    while (fgets(line, sizeof line, f)) {
        if (sscanf(line, "%llu %llu %u %u %511s", &ab, &of, &k, &nn, name) < 5) continue;
        if (n == cap) { cap *= 2; lo = realloc(lo, (size_t)cap * sizeof *lo); hi = realloc(hi, (size_t)cap * sizeof *hi); }
        lo[n] = strstr(name, "attn_q_b") ? (ab & ~31ull) : ab; hi[n] = lo[n] + (strstr(name, "attn_q_b") ? 32768ull * 40ull * 34ull : strstr(name, "engram_kv") ? (uint64_t)nn * (uint64_t)k * 2u : strstr(name, "attn_output_a") ? 8192ull * 128ull * 34ull : strstr(name, "attn_output_b") ? 5120ull * 256ull * 34ull : (uint64_t)nn * (uint64_t)(k / 32u) * 34u); n++;   /* llms RAGGED_AO: the originals' native extents (a ragged entry is shorter) */   /* Q8_0: 34 bytes per 32 weights; llms Q4L_F16: engram_kv is F16 */
    }
    fclose(f);
    for (int i = 1; i < n; i++) {   /* insertion sort by start (~200 entries) */
        uint64_t a = lo[i], b = hi[i]; int j = i - 1;
        while (j >= 0 && lo[j] > a) { lo[j + 1] = lo[j]; hi[j + 1] = hi[j]; j--; }
        lo[j + 1] = a; hi[j + 1] = b;
    }
    { int m = 0; for (int i = 0; i < n; i++) { if (m > 0 && lo[i] == lo[m - 1] && hi[i] == hi[m - 1]) continue; lo[m] = lo[i]; hi[m] = hi[i]; m++; } n = m; }   /* llms RAGGED_Q L2: the three attn_q_b keys of a layer are one range */
    q4l_unlock_lo = lo; q4l_unlock_hi = hi; q4l_unlock_count = n;
    uint64_t tot = 0; for (int i = 0; i < n; i++) tot += hi[i] - lo[i];
    fprintf(stderr, "llms: Q4L_UNLOCK on -- %d Q8_0 originals (%.2f GiB) get their own views and stay unlocked\n", n, tot / 1073741824.0);
}
/* split spans at the listed tensors: returns the new count (0 = unchanged) and points *o2 / *s2 at the top-level buffers */
static uint32_t split_q4l_ranges(const uint64_t *off, const uint64_t *sz, uint32_t n, const uint64_t **o2, const uint64_t **s2) {
    if (q4l_unlock_count < 0) init_q4l_unlock();
    if (q4l_unlock_count <= 0 || n == 0) return 0;
    const uint32_t need = n + 4u * (uint32_t)q4l_unlock_count + 8u;
    if (need > q4l_unlock_capacity) {
        q4l_unlock_offsets = realloc(q4l_unlock_offsets, (size_t)need * sizeof *q4l_unlock_offsets);
        q4l_unlock_sizes = realloc(q4l_unlock_sizes, (size_t)need * sizeof *q4l_unlock_sizes); q4l_unlock_capacity = need;
    }
    uint32_t m = 0; bool cut = false;
    for (uint32_t i = 0; i < n; i++) {
        uint64_t a = off[i]; const uint64_t b = off[i] + sz[i];
        for (int q = 0; q < q4l_unlock_count && a < b; q++) {
            const uint64_t ql = q4l_unlock_lo[q], qh = q4l_unlock_hi[q];
            if (qh <= a || ql >= b) continue;
            if (ql > a) { q4l_unlock_offsets[m] = a; q4l_unlock_sizes[m] = ql - a; m++; }
            const uint64_t s0 = ql > a ? ql : a, e0 = qh < b ? qh : b;
            q4l_unlock_offsets[m] = s0; q4l_unlock_sizes[m] = e0 - s0; m++; cut = true;
            a = e0;
        }
        if (a < b) { q4l_unlock_offsets[m] = a; q4l_unlock_sizes[m] = b - a; m++; }
    }
    if (!cut) return 0;
    *o2 = q4l_unlock_offsets; *s2 = q4l_unlock_sizes; return m;
}
/* 06:4x: is this view exactly one listed tensor's page-rounded range? (the warmup skips those: binding a view wires all of it, and the
   cache's lazy mlock then meets the global wire limit before the GPU's wired collector lets the view go) */
static int q4l_view_only(uint64_t start, uint64_t bytes) {
    if (q4l_unlock_count <= 0) return 0;
    const uint64_t page = (uint64_t)getpagesize();
    for (int q = 0; q < q4l_unlock_count; q++) {
        const uint64_t a = q4l_unlock_lo[q] & ~(page - 1u), b = (q4l_unlock_hi[q] + page - 1u) & ~(page - 1u);
        if (a == start && b - a == bytes) return 1;
    }
    return 0;
}
/* whole pages inside the listed tensors, for the mlock in ds4.c */
uint32_t llms_q4u_pages(uint64_t page, uint64_t *lo, uint64_t *hi, uint32_t cap) {
    if (q4l_unlock_count < 0) init_q4l_unlock();
    uint32_t n = 0;
    for (int q = 0; q < q4l_unlock_count && n < cap; q++) {
        const uint64_t a = (q4l_unlock_lo[q] + page - 1u) / page * page, b = q4l_unlock_hi[q] / page * page;
        if (b > a) { lo[n] = a; hi[n] = b; n++; }
    }
    return n;
}
int ds4_gpu_set_model_map_spans(
        const void *model_map,
        uint64_t model_size,
        const uint64_t *offsets,
        const uint64_t *sizes,
        uint32_t count,
        uint64_t max_tensor_bytes) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!model_map || model_size == 0 || !offsets || !sizes || count == 0) return 0;
    if (g_ssd_streaming_mode) {   /* llms Q4L_UNLOCK: each listed tensor in a span of its own (no-op unless on) */
        const uint64_t *so = NULL, *ss = NULL; const uint32_t sm = split_q4l_ranges(offsets, sizes, count, &so, &ss);
        if (sm) { offsets = so; sizes = ss; count = sm; }
    }
    if (count == 1 && !g_ssd_streaming_mode) {
        return ds4_gpu_set_model_map_range(model_map,
                                           model_size,
                                           offsets[0],
                                           sizes[0],
                                           max_tensor_bytes);
    }
    if (ds4_gpu_model_views_cover_spans(model_map, model_size, offsets, sizes, count)) {
        return 1;
    }

    @autoreleasepool {
        const double t0 = ds4_gpu_now_ms();
        max_tensor_bytes = ds4_gpu_effective_model_max_tensor_bytes(model_size, max_tensor_bytes);

        ds4_gpu_model_residency_clear();
        /* Streaming changes the target's active layer, not the auxiliary
         * vision/drafter models. Single spans need the same bounded lifetime
         * as disjoint spans instead of accumulating every visited layer. */
        if (g_ssd_streaming_mode) ds4_gpu_model_views_remove_map(model_map);
        else ds4_gpu_model_views_clear();

        uint64_t mapped_total = 0;
        uint64_t first_offset = UINT64_MAX;
        for (uint32_t i = 0; i < count; i++) {
            if (offsets[i] > model_size || sizes[i] == 0 || sizes[i] > model_size - offsets[i]) {
                fprintf(stderr, "ds4: Metal model span %u is outside the GGUF mapping\n", i);
                ds4_gpu_model_residency_clear();
                ds4_gpu_model_views_clear();
                return 0;
            }
            if (offsets[i] < first_offset) first_offset = offsets[i];
            uint64_t effective_max = max_tensor_bytes;
            if (effective_max > sizes[i]) effective_max = sizes[i];
            if (!ds4_gpu_add_model_view_range(model_map,
                                              model_size,
                                              offsets[i],
                                              sizes[i],
                                              effective_max,
                                              true,
                                              &mapped_total)) {
                ds4_gpu_model_residency_clear();
                ds4_gpu_model_views_clear();
                return 0;
            }
        }
        if (!ds4_gpu_finish_model_views(t0, mapped_total, first_offset)) {
            ds4_gpu_model_residency_clear();
            ds4_gpu_model_views_clear();
            return 0;
        }
        g_model_map_ptr = model_map;
        g_model_map_size = model_size;
        g_model_mapped_offset = first_offset == UINT64_MAX ? 0 : first_offset;
        g_model_mapped_size = mapped_total;
        g_model_mapped_max_tensor_bytes = max_tensor_bytes;
        if (ds4_gpu_model_map_log_enabled()) {
            fprintf(stderr,
                    "ds4: Metal mapped mmaped model as %u disjoint shared buffers across %u tensor spans\n",
                    g_model_view_count,
                    count);
        }
        return 1;
    }
}

int ds4_gpu_set_model_map(const void *model_map, uint64_t model_size) {
    return ds4_gpu_set_model_map_range(model_map, model_size, 0, model_size, 0);
}

int ds4_gpu_set_model_fd(int fd) {
    g_model_fd = fd;
    /* llms LLMS_DS4_EXPERT_NOCACHE: a second descriptor of the same file with F_NOCACHE / F_RDAHEAD 0 for expert preads */
    if (g_model_fd_nocache >= 0) { close(g_model_fd_nocache); g_model_fd_nocache = -1; }
#if defined(__APPLE__) && defined(F_GETPATH)
    if (fd >= 0 && getenv("LLMS_DS4_EXPERT_NOCACHE") != NULL) {
        char path[MAXPATHLEN];
        if (fcntl(fd, F_GETPATH, path) == 0) {
            int nfd = open(path, O_RDONLY | O_CLOEXEC);
            const int nocache_rdahead0 = !strcmp(getenv("LLMS_DS4_EXPERT_NOCACHE"), "rdahead0");   /* llms EXPERT_NOCACHE rdahead0: page cache on, read-ahead off */
            if (nfd >= 0 && (nocache_rdahead0 || fcntl(nfd, F_NOCACHE, 1) == 0) && fcntl(nfd, F_RDAHEAD, 0) == 0) {
                g_model_fd_nocache = nfd;
                fprintf(stderr, nocache_rdahead0 ? "llms: expert preads use a cached descriptor without read-ahead (rdahead0) of %s\n"
                                            : "llms: expert preads use an F_NOCACHE descriptor of %s\n", path);
            } else if (nfd >= 0) {
                close(nfd);
            }
        }
    }
#endif
    return 1;
}

static int ds4_gpu_model_views_cover_range(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    size) {
    if (!model_map || model_size == 0 || size == 0 ||
        offset > model_size || size > model_size - offset) {
        return 0;
    }
    const uint64_t end = offset + size;
    for (uint32_t i = 0; i < g_model_view_count; i++) {
        if (g_model_views[i].model_map != model_map ||
            g_model_views[i].model_size != model_size) {
            continue;
        }
        const uint64_t view_start = g_model_views[i].model_offset;
        const uint64_t view_end = view_start + g_model_views[i].bytes;
        if (offset >= view_start && end <= view_end) return 1;
    }
    return 0;
}

static int ds4_gpu_model_views_cover_spans(
        const void     *model_map,
        uint64_t        model_size,
        const uint64_t *offsets,
        const uint64_t *sizes,
        uint32_t        count) {
    if (!offsets || !sizes || count == 0) return 0;
    for (uint32_t i = 0; i < count; i++) {
        if (!ds4_gpu_model_views_cover_range(model_map,
                                             model_size,
                                             offsets[i],
                                             sizes[i])) {
            return 0;
        }
    }
    return 1;
}

int ds4_gpu_set_model_fd_for_map(int fd, const void *model_map) {
    (void)fd;
    (void)model_map;
    return 1;
}

static id<MTLBuffer> ds4_gpu_wrap_model_range(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len,
        uint64_t   *inner_offset) {
    (void)model_map;
    if (model_size == 0 || offset > model_size || len > model_size - offset) {
        fprintf(stderr, "ds4: Metal model range is outside the mapped model\n");
        return nil;
    }

    const uint64_t end = offset + len;
    for (uint32_t i = 0; i < g_model_view_count; i++) {
        if (g_model_views[i].model_map != model_map ||
            g_model_views[i].model_size != model_size) {
            continue;
        }
        const uint64_t view_start = g_model_views[i].model_offset;
        const uint64_t view_end = view_start + g_model_views[i].bytes;
        if (offset >= view_start && end <= view_end) {
            *inner_offset = offset - view_start;
            return g_model_views[i].buffer;
        }
    }

    fprintf(stderr,
            "ds4: Metal model range %.2f..%.2f GiB is not covered by mapped model views\n",
            ds4_gpu_gib(offset),
            ds4_gpu_gib(end));
    return nil;
}

typedef enum {
    DS4_GPU_EXACT_VIEW_CACHED,
    DS4_GPU_EXACT_VIEW_TRANSIENT,
    DS4_GPU_EXACT_VIEW_OWNED,
} ds4_gpu_exact_view_lifetime;

static id<MTLBuffer> ds4_gpu_wrap_model_exact_range_impl(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len,
        uint64_t   *inner_offset,
        ds4_gpu_exact_view_lifetime lifetime) {
    const bool cache_view = lifetime == DS4_GPU_EXACT_VIEW_CACHED;
    const bool transient_view = lifetime == DS4_GPU_EXACT_VIEW_TRANSIENT;
    if (!model_map || !g_device ||
        (cache_view && !g_model_buffer_cache) ||
        (transient_view && !g_transient_buffers) ||
        model_size == 0 || offset > model_size || len > model_size - offset) {
        fprintf(stderr, "ds4: Metal exact model range is outside the mapped model\n");
        return nil;
    }

    const uint64_t page = (uint64_t)getpagesize();
    const uint64_t page_offset = offset & ~(page - 1);
    const uint64_t leading = offset - page_offset;
    if (len > UINT64_MAX - leading ||
        leading + len > UINT64_MAX - (page - 1)) {
        fprintf(stderr, "ds4: Metal exact model range overflows page alignment\n");
        return nil;
    }
    uint64_t view_bytes = round_up_u64(leading + len, page);
    if (view_bytes > model_size - page_offset) view_bytes = model_size - page_offset;
    if (leading + len > view_bytes) {
        fprintf(stderr, "ds4: Metal exact model range alignment exceeds mapped model\n");
        return nil;
    }
    if (view_bytes > (uint64_t)[g_device maxBufferLength]) {
        fprintf(stderr,
                "ds4: Metal exact model range %.2f GiB exceeds maxBufferLength %.2f GiB\n",
                ds4_gpu_gib(view_bytes),
                ds4_gpu_gib((uint64_t)[g_device maxBufferLength]));
        return nil;
    }

    NSString *key = nil;
    id<MTLBuffer> buffer = nil;
    if (cache_view) {
        key = [NSString stringWithFormat:@"%p:%llu:%llu:%llu",
               model_map,
               (unsigned long long)model_size,
               (unsigned long long)page_offset,
               (unsigned long long)view_bytes];
        buffer = [g_model_buffer_cache objectForKey:key];
    }
    if (!buffer) {
        const uintptr_t base = (uintptr_t)model_map;
        buffer = [g_device newBufferWithBytesNoCopy:(void *)(base + page_offset)
                                             length:(NSUInteger)view_bytes
                                            options:ds4_gpu_model_resource_options()
                                        deallocator:nil];
        if (!buffer) {
            fprintf(stderr,
                    "ds4: Metal could not wrap exact mmaped model range at %.2f GiB, size %.2f MiB\n",
                    ds4_gpu_gib(page_offset),
                    ds4_gpu_mib(view_bytes));
            return nil;
        }
        if (cache_view) {
            buffer.label = @"ds4_model_exact_view";
        } else if (transient_view) {
            buffer.label = @"ds4_model_exact_transient_view";
        } else {
            buffer.label = @"ds4_model_exact_owned_view";
        }
        if (cache_view) {
            [g_model_buffer_cache setObject:buffer forKey:key];
            ds4_gpu_model_buffer_cache_note_insert(view_bytes);
        } else if (transient_view) {
            [g_transient_buffers addObject:buffer];
        }
    }

    if (inner_offset) *inner_offset = leading;
    return buffer;
}

static id<MTLBuffer> ds4_gpu_wrap_model_exact_range(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len,
        uint64_t   *inner_offset) {
    return ds4_gpu_wrap_model_exact_range_impl(model_map,
                                               model_size,
                                               offset,
                                               len,
                                               inner_offset,
                                               DS4_GPU_EXACT_VIEW_CACHED);
}

static id<MTLBuffer> ds4_gpu_wrap_model_exact_range_transient(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len,
        uint64_t   *inner_offset) {
    return ds4_gpu_wrap_model_exact_range_impl(model_map,
                                               model_size,
                                               offset,
                                               len,
                                               inner_offset,
                                               DS4_GPU_EXACT_VIEW_TRANSIENT);
}

static id<MTLBuffer> ds4_gpu_wrap_model_exact_range_owned(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len,
        uint64_t   *inner_offset) {
    return ds4_gpu_wrap_model_exact_range_impl(model_map,
                                               model_size,
                                               offset,
                                               len,
                                               inner_offset,
                                               DS4_GPU_EXACT_VIEW_OWNED);
}

uint32_t ds4_gpu_stream_expert_cache_configured_count(void) {
    uint32_t budget = ds4_gpu_stream_expert_cache_configured_budget();
    if (budget > DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES) {
        budget = DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES;
    }
    return budget;
}

uint32_t ds4_gpu_stream_expert_cache_current_count(void) {
    return g_stream_expert_cache_entry_count;
}

uint32_t ds4_gpu_stream_expert_cache_budget_for_expert_size(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (gateup_side_on() && gate_expert_bytes == SIDE_IQ2_GATE_EXPERT_BYTES) gate_expert_bytes = gateup_side_matrix_bytes;   /* llms BS6C */
    if (!ds4_gpu_stream_expert_cache_note_expert_size(gate_expert_bytes,
                                                      down_expert_bytes)) {
        return 0;
    }
    return ds4_gpu_stream_expert_cache_configured_budget();
}

/* llms SLAB_BG v2 (apply_sbg2.py): the slab residency set as one helper; the planned slabs made resident in the background */
static uint64_t ds4_gpu_stream_expert_slab_target_bytes(void);
static double ds4_gpu_mib(uint64_t bytes);
static __strong id slab_residency_set;
static void add_slab_to_residency(id<MTLBuffer> buffer, uint64_t len) {   /* llms SLAB_RESIDENCY (adopted; the switch removed 10-27): one residency set over the slab buffers, on the queue */
    (void)len;
#if TARGET_OS_OSX
    if (buffer) { if (@available(macOS 15.0, *)) {
        if (!slab_residency_set) { MTLResidencySetDescriptor *d = [[MTLResidencySetDescriptor alloc] init]; d.label = @"llms_slab"; d.initialCapacity = 64; NSError *er = nil; slab_residency_set = [g_device newResidencySetWithDescriptor:d error:&er];
                       if (slab_residency_set && g_queue && [g_queue respondsToSelector:@selector(addResidencySet:)]) [g_queue addResidencySet:slab_residency_set];
                       if (!slab_residency_set) fprintf(stderr, "llms: slab residency set creation FAILED\n"); }
        if (slab_residency_set) { id<MTLResidencySet> rs = (id<MTLResidencySet>)slab_residency_set; [rs addAllocation:buffer]; [rs commit]; [rs requestResidency]; }
    } }
#endif
    (void)len;
}
static pthread_mutex_t background_slabs_mutex = PTHREAD_MUTEX_INITIALIZER; static pthread_cond_t background_slabs_cond = PTHREAD_COND_INITIALIZER;
static __strong id<MTLBuffer> background_slab[64]; static uint64_t background_slab_bytes[64]; static int background_slabs_planned, background_slabs_made, background_slabs_taken, background_slabs_stop, background_slab_last_taken;
static double background_slab_ms, background_residency_ms, background_slab_wait_ms;
static double uptime_ms(void) { return (double)clock_gettime_nsec_np(CLOCK_UPTIME_RAW) * 1e-6; }
/* llms SHM_CACHE (apply_shm.py): the expert slabs in named POSIX shm segments that outlive the process, a header of the cached (layer, expert, slot) written at a clean exit, and a per-slot generation, so the next process starts with a warm cache. */
#include <sys/mman.h>
#include <sys/file.h>
#include <sys/stat.h>
typedef struct { uint16_t layer, expert; uint32_t slot, gen, pad; uint64_t gate_abs, up_abs, down_abs, gate_bytes, down_bytes, gi, ui, di; } shm_cache_entry;
typedef struct { uint64_t magic; char key[256]; volatile uint64_t valid; uint32_t n, total_slots; uint32_t saves, saves_pad;   /* llms FIXSET_GUARD v3: saves since the key changed */
