static int shm_cache_state = -1;                /* -1 untried, 0 private slabs, 1 attached */
static char shm_cache_key[256];
static shm_cache_header *shm_header;          /* the mapped header (shared) */
static shm_cache_entry *shm_saved_entries; static uint32_t shm_saved_count; static int shm_restore_done;
static uint64_t shm_entries_restored, shm_skipped_slot_in_use, shm_skipped_generation_moved, shm_skipped_already_cached, shm_skipped_malformed, shm_saved_at_exit, shm_slabs_resized;
static pthread_mutex_t shm_cache_mutex = PTHREAD_MUTEX_INITIALIZER;

static int cold_refill_state = -1; static shm_cache_entry *cold_list; static uint32_t cold_list_n; static const char *cold_list_src = "none";   /* llms COLD_REFILL (apply_coldrefill.py) */
#include <pwd.h>
static const char *ds4m1_cold_state_path(const char *name) {   /* ds4m1: per-user state in ~/Library/Caches/ds4m1/ (the home from the user database: the guardian runs with only PATH) */
    static char buf[4][1024]; static int k; char *b = buf[k++ & 3]; const struct passwd *pw = getpwuid(getuid()); char dir[1024];
    snprintf(dir, sizeof dir, "%s/Library/Caches/ds4m1", pw && pw->pw_dir ? pw->pw_dir : "."); (void)mkdir(dir, 0755);
    snprintf(b, 1024, "%s/%s", dir, name); return b;
}
#define COLD_LIST_PATH ds4m1_cold_state_path("cache_list")
#define COLD_LIST_MAGIC 0x31544c4344535344ull   /* 'DSSDCLT1' */
static int cold_refill_on(void) { if (cold_refill_state < 0) { const char *e = getenv("LLMS_DS4_COLD_REFILL"); cold_refill_state = e && *e && *e != '0';
    if (cold_refill_state) fprintf(stderr, "llms: cold refill (a COLD shared cache re-reads the last saved expert list from SSD before the first install: the list from the header, else %s)\n", COLD_LIST_PATH); }
    return cold_refill_state; }
static size_t cold_key_prefix(const char *k) { const char *p = strstr(k, ";n"); return p ? (size_t)(p - k) : strnlen(k, 256); }   /* the model files + the slot size: what a list depends on */
static __strong id<MTLBuffer> shm_segment_buffers[64];   /* the buffer made from segment k: a slab is shm-backed only if it IS that buffer */
static int slab_is_shared(uint32_t si) { return si < 64u && si < g_stream_expert_cache_slab_count && shm_segment_buffers[si] && g_stream_expert_cache_slabs[si] == shm_segment_buffers[si]; }
static int ds4_gpu_stream_expert_slab_slot_range(uint32_t slot, uint32_t *slab_index, uint64_t *slot_base);
static void drop_stale_shm(void) {   /* 2026-10-20 09:1x: a process with the shm cache OFF drops the segments an earlier agent left. The instance
                                             lock (/tmp/ds4.lock, flock, every ds4 program) means no engine maps them now; left in place, their ~36 GiB
                                             sit beside this process's private cache and push the machine into swap, and an instrument (ds4, the CLI
                                             every KL / PPL probe runs) must start cold anyway. A no-op when none exist (a run that never used shm). */
    int n = 0; double gib = 0.0; char nm[32];
    for (int k = -1; k < 65; k++) {   /* llms DSP_BANK_SHM: k 64 = the drafter's bank segment */
        if (k < 0) snprintf(nm, sizeof nm, "/ds4x.hdr"); else if (k == 64) snprintf(nm, sizeof nm, "/ds4x.dspbank"); else snprintf(nm, sizeof nm, "/ds4x.slab.%d", k);
        const int fd = shm_open(nm, O_RDONLY, 0); if (fd < 0) continue;
        struct stat st; if (fstat(fd, &st) == 0) gib += (double)st.st_size / 1073741824.0;
        close(fd); if (shm_unlink(nm) == 0) n++;
