    if (n) fprintf(stderr, "llms shm cache: OFF in this process -- dropped %d segments (%.2f GiB) an earlier agent left (freed once unmapped)\n", n, gib);
}
static int shm_cache_on(void) {

    if (shm_cache_switch < 0) { const char *e = getenv("LLMS_DS4_SHM_CACHE"); shm_cache_switch = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? 2 : 1;
                          if (!shm_cache_switch) drop_stale_shm();
                          if (shm_cache_switch) fprintf(stderr, "llms: shm cache (the expert slabs in POSIX shm that outlive the process; the next process restores the cache)%s\n",
                                                  shm_cache_switch == 2 ? " -- CANARY: two restored experts of one layer swapped" : ""); }
    return shm_cache_switch;
}
static void append_file_identity(char *out, size_t n, const char *tag, int fd, const char *path) {
    struct stat st; int ok = fd >= 0 ? fstat(fd, &st) == 0 : (path && *path ? stat(path, &st) == 0 : 0);
    snprintf(out, n, "%s%llx.%llx.%llx;", tag, ok ? (unsigned long long)st.st_size : 0ull, ok ? (unsigned long long)st.st_mtimespec.tv_sec : 0ull, ok ? (unsigned long long)st.st_ino : 0ull);
}
static void save_shm_cache(void) {   /* atexit: the cache as it stands, the valid flag last */
    if (shm_cache_state != 1 || !shm_header) return;
    if (shm_cache_switch == 2) { fprintf(stderr, "llms shm cache: CANARY run -- nothing saved (the header stays invalid: the next run is cold)\n"); return; }
    {   /* llms SHM_NOSAVE (11-02, apply_shm_nosave.py): a measurement arm uses the cache and saves nothing, so the header stays invalid and the next arm COLD_REFILLs the SAME list -- an identical warm start for every arm; off unless LLMS_DS4_SHM_NOSAVE=1*/
        static int nosave = -1; if (nosave < 0) { const char *e = getenv("LLMS_DS4_SHM_NOSAVE"); nosave = e && *e && *e != '0'; }
        if (nosave) { fprintf(stderr, "llms shm cache: NOSAVE -- nothing saved (the header stays invalid: the next run refills the same list)\n"); return; } }
    if (prefill_prefetch_waits_precise()) (void)wait_ticket_forward(last_ticket());   /* llms PFU_PRECISE: no entry is saved while its read lands */
    shm_cache_header *h = shm_header; uint32_t n = 0;
    for (uint32_t L = 0; L < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER; L++) for (uint32_t x = 0; x < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT; x++) {
        const ds4_gpu_stream_expert_cache_entry *e = &g_stream_expert_cache[L][x]; uint32_t si = 0; uint64_t base = 0;
        if (!e->valid || !e->slab_backed || e->slab_slot >= g_stream_expert_cache_slab_total_slots || !ds4_gpu_stream_expert_slab_slot_range(e->slab_slot, &si, &base) || !slab_is_shared(si)) continue;
        if ((uint64_t)e->gate_inner < base || (uint64_t)e->up_inner < base || (uint64_t)e->down_inner < base) continue;
        h->e[n] = (shm_cache_entry){ .layer = (uint16_t)L, .expert = (uint16_t)x, .slot = e->slab_slot, .gen = h->gen[e->slab_slot], .gate_abs = e->gate_abs_offset,
            .up_abs = e->up_abs_offset, .down_abs = e->down_abs_offset, .gate_bytes = e->gate_expert_bytes, .down_bytes = e->down_expert_bytes,
            .gi = (uint64_t)e->gate_inner - base, .ui = (uint64_t)e->up_inner - base, .di = (uint64_t)e->down_inner - base };
