        if (cf) { const uint64_t mg = COLD_LIST_MAGIC; okw = fwrite(&mg, 8, 1, cf) == 1 && fwrite(shm_cache_key, sizeof shm_cache_key, 1, cf) == 1 && fwrite(&n, 4, 1, cf) == 1 &&
                  fwrite(h->e, sizeof(shm_cache_entry), n, cf) == n; if (fclose(cf) != 0) okw = 0; }
        if (okw && rename(ds4m1_cold_state_path("cache_list.tmp"), COLD_LIST_PATH) == 0) fprintf(stderr, "llms cold refill: the list of %u entries written to %s\n", n, COLD_LIST_PATH);
        else fprintf(stderr, "llms cold refill: the list was NOT written (%s)\n", COLD_LIST_PATH); }
    fprintf(stderr, "llms shm cache: %llu restored at start (skipped: %llu slot in use, %llu generation moved, %llu already cached, %llu malformed; %llu slabs resized); %llu entries saved at exit\n",
            (unsigned long long)shm_entries_restored, (unsigned long long)shm_skipped_slot_in_use, (unsigned long long)shm_skipped_generation_moved, (unsigned long long)shm_skipped_already_cached,
            (unsigned long long)shm_skipped_malformed, (unsigned long long)shm_slabs_resized, (unsigned long long)n);
    { char snm[32]; int sd = 0; for (uint32_t k = g_stream_expert_cache_slab_count; k < 64u; k++) { snprintf(snm, sizeof snm, "/ds4x.slab.%u", k); if (shm_unlink(snm) == 0) sd++; }   /* llms CACHE BUDGET (apply_cache_budget.py): a smaller plan leaves no stale segment */
      if (sd) fprintf(stderr, "llms shm cache: dropped %d stale slab segments beyond this plan's %u\n", sd, g_stream_expert_cache_slab_count); }
    spawn_guardian();   /* llms MEMGUARD (4): the cache outlives this process -- a guardian drops it if memory turns scarce */
}

static int shm_keep_builds(void) {   /* llms SHM_KEEP_BUILDS (apply_shm_keep.py): 0 off, 1 on, 2 canary */
    static int v = -1; if (v < 0) { const char *e = getenv("LLMS_DS4_SHM_KEEP_BUILDS"); v = !e || !*e || !strcmp(e, "0") ? 0 : !strcmp(e, "canary") ? 2 : !strcmp(e, "all") ? 3 : 1; } return v; }
static void attach_shm_cache(uint64_t slot_bytes, uint32_t budget) {   /* once, from the first shm slab; under shm_cache_mutex */
    shm_cache_state = 0;
    char lp[1024]; const char *td = getenv("TMPDIR"); snprintf(lp, sizeof lp, "%s/ds4x_shm.lock", td && *td ? td : "/tmp");
    const int lfd = open(lp, O_CREAT | O_RDWR | O_CLOEXEC, 0600);
    if (lfd < 0 || flock(lfd, LOCK_EX | LOCK_NB) != 0) { fprintf(stderr, "llms memguard: REFUSING TO RUN -- another engine holds %s (a private second expert cache would exceed memory) (exit 75)\n", lp); _exit(75); }   /* llms MEMGUARD (1): was a private-slab fallback */   /* the lock lives as long as the process */
    char k1[64], k2[64], k3[64]; append_file_identity(k1, sizeof k1, "m", g_model_fd, NULL); append_file_identity(k2, sizeof k2, "b", -1, getenv("LLMS_DS4_GATEUP_BS64"));
    append_file_identity(k3, sizeof k3, "d", down_side_fd, NULL);   /*: the G32 down file (fd -1 -> zeros when G32 is off) */
    if (g16d_active) { size_t z16 = strlen(k3); snprintf(k3 + z16, sizeof k3 - z16, "g16%016llx;", (unsigned long long)g16d_identity); }   /* include ALL delta headers/identities: no G32/G16 or changed-delta alias */
    char shm_stamp[96]; if (shm_keep_builds()) snprintf(shm_stamp, sizeof shm_stamp, "LAYOUT1 e%zu h%zu", sizeof(shm_cache_entry), sizeof(shm_cache_header));   /* llms SHM_KEEP_BUILDS */
    else snprintf(shm_stamp, sizeof shm_stamp, "%s %s", __DATE__, __TIME__);
    snprintf(shm_cache_key, sizeof shm_cache_key, "%s%s%ss%llx;n%u;p%d.%llx;%s", k1, k2, k3, (unsigned long long)slot_bytes, budget, background_slabs_planned,
             (unsigned long long)(background_slabs_planned ? background_slab_bytes[0] : 0), shm_stamp);
    const uint64_t pg = (uint64_t)getpagesize(), hlen = (sizeof(shm_cache_header) + pg - 1) / pg * pg;   /* fstat reports shm sizes page-rounded */
    int hfd = shm_open("/ds4x.hdr", O_CREAT | O_RDWR, 0600);
    if (hfd < 0) { perror("llms shm cache: shm_open /ds4x.hdr"); return; }
    struct stat st; if (fstat(hfd, &st) != 0) { close(hfd); return; }
    int fresh = st.st_size != (off_t)hlen;
    if (fresh && st.st_size != 0) { close(hfd); shm_unlink("/ds4x.hdr"); hfd = shm_open("/ds4x.hdr", O_CREAT | O_EXCL | O_RDWR, 0600);   /* macOS: one ftruncate per object */
                                    if (hfd < 0) { perror("llms shm cache: recreate /ds4x.hdr"); return; } }
    if (fresh && ftruncate(hfd, (off_t)hlen) != 0) { perror("llms shm cache: ftruncate header"); close(hfd); return; }
    void *p = mmap(NULL, (size_t)hlen, PROT_READ | PROT_WRITE, MAP_SHARED, hfd, 0); close(hfd);
    if (p == MAP_FAILED) { perror("llms shm cache: mmap header"); return; }
    shm_cache_header *h = (shm_cache_header *)p; shm_header = h;
    const int match = !fresh && h->magic == SHM_CACHE_MAGIC && h->valid == 1 && !strncmp(h->key, shm_cache_key, sizeof h->key) && h->n <= DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES;
    shm_header_age = match ? h->saves : 0u;   /* llms FIXSET_GUARD v3 */
    if (!match && cold_refill_on()) {   /* llms COLD_REFILL: the header's list (a kill), else the file's (a drop, a reboot); never the slab bytes */
        const size_t kp = cold_key_prefix(shm_cache_key);
        if (!fresh && h->magic == SHM_CACHE_MAGIC && h->n > 0 && h->n <= DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES && cold_key_prefix(h->key) == kp && !strncmp(h->key, shm_cache_key, kp)) {
            cold_list = malloc((size_t)h->n * sizeof(shm_cache_entry)); if (cold_list) { memcpy(cold_list, h->e, (size_t)h->n * sizeof(shm_cache_entry)); cold_list_n = h->n; cold_list_src = "header"; } }
        if (!cold_list_n) { FILE *cf = fopen(COLD_LIST_PATH, "rb"); uint64_t mg = 0; char fk[256]; uint32_t fn = 0;
            if (cf && fread(&mg, 8, 1, cf) == 1 && mg == COLD_LIST_MAGIC && fread(fk, sizeof fk, 1, cf) == 1 && ((fk[sizeof fk - 1] = 0), 1) && fread(&fn, 4, 1, cf) == 1 && fn > 0 && fn <= DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES &&
                cold_key_prefix(fk) == kp && !strncmp(fk, shm_cache_key, kp)) {
                cold_list = malloc((size_t)fn * sizeof(shm_cache_entry));
                if (cold_list && fread(cold_list, sizeof(shm_cache_entry), fn, cf) == fn) { cold_list_n = fn; cold_list_src = "file"; } else { free(cold_list); cold_list = NULL; } }
            if (cf) fclose(cf); }
        fprintf(stderr, "llms cold refill: the cache attaches cold; %u listed experts from the %s\n", cold_list_n, cold_list_n ? cold_list_src : "(no matching list)"); }
    if (match && h->n) { shm_saved_entries = malloc((size_t)h->n * sizeof(shm_cache_entry)); if (shm_saved_entries) { memcpy(shm_saved_entries, h->e, (size_t)h->n * sizeof(shm_cache_entry)); shm_saved_count = h->n; } }
    h->valid = 0; __atomic_thread_fence(__ATOMIC_SEQ_CST);   /* invalidated before any slab byte can change -- and it stays invalid until a clean save: a killed session's slots can hold other bytes at an unmoved generation */
    if (!match) memset(h->gen, 0, sizeof h->gen);
    fprintf(stderr, "llms shm cache: attached (%s); %u entries to restore\n", match ? "header valid, key matches" : fresh ? "new header" : "header invalid or key changed: cold", shm_saved_count);
    fprintf(stderr, "llms shm cache key: %s\n", shm_cache_key);   /*: shows whether the G32 down file (the d part) is in the key */
    atexit(save_shm_cache); shm_cache_state = 1;
}
static id<MTLBuffer> shm_slab(int k, uint64_t len, uint64_t slot_bytes, uint32_t budget) {   /* slab k of the plan from /ds4x.slab.<k>, or nil */
    if (!shm_cache_on() || k < 0 || k >= 64) return nil;
    pthread_mutex_lock(&shm_cache_mutex); if (shm_cache_state < 0) attach_shm_cache(slot_bytes, budget); const int ok = shm_cache_state; pthread_mutex_unlock(&shm_cache_mutex);
    if (ok != 1) return nil;
    char nm[32]; snprintf(nm, sizeof nm, "/ds4x.slab.%d", k);
    int fd = shm_open(nm, O_CREAT | O_RDWR, 0600); if (fd < 0) { perror("llms shm cache: shm_open slab"); return nil; }
    struct stat st; if (fstat(fd, &st) != 0) { close(fd); return nil; }
    if (st.st_size != (off_t)len) {   /* a slab of another size: its bytes mean nothing now; macOS takes one ftruncate per object */
        if (st.st_size != 0) { close(fd); shm_unlink(nm); fd = shm_open(nm, O_CREAT | O_EXCL | O_RDWR, 0600); if (fd < 0) { perror("llms shm cache: recreate slab"); return nil; } }
        if (ftruncate(fd, (off_t)len) != 0) { perror("llms shm cache: ftruncate slab"); close(fd); return nil; }
        pthread_mutex_lock(&shm_cache_mutex); shm_slabs_resized++; if (shm_saved_entries) { free(shm_saved_entries); shm_saved_entries = NULL; shm_saved_count = 0; } pthread_mutex_unlock(&shm_cache_mutex);
    }
    void *p = mmap(NULL, (size_t)len, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0); close(fd);
    if (p == MAP_FAILED) { perror("llms shm cache: mmap slab"); return nil; }
    id<MTLBuffer> b = [g_device newBufferWithBytesNoCopy:p length:(NSUInteger)len options:MTLResourceStorageModeShared deallocator:nil];
    if (!b) { munmap(p, (size_t)len); fprintf(stderr, "llms shm cache: newBufferWithBytesNoCopy failed for slab %d\n", k); }
    else shm_segment_buffers[k] = b;
    return b;
}
/* llms DSP_BANK_SHM (apply_bankshm.py): the DSpark drafter's bank in a named POSIX segment that outlives the process, behind a keyed header; only for the process holding the shm cache's lock. */
typedef struct { uint64_t magic; char key[256]; volatile uint64_t valid; uint64_t bytes; } bank_shm_header;
#define BANK_SHM_MAGIC 0x314B4E4142505344ull   /* "DSPBANK1" */
static bank_shm_header *bank_shm_header_map;
int ds4_gpu_llms_shm_holder(void) { return shm_cache_state == 1; }
ds4_gpu_tensor *ds4_gpu_llms_shm_tensor(uint64_t bytes, const char *key, int *valid_out) {
    *valid_out = 0;
    if (shm_cache_state != 1 || bytes == 0 || !key || !g_device) return NULL;
    const uint64_t pg = 16384u, hlen = pg, dlen = (bytes + pg - 1u) / pg * pg, len = hlen + dlen;
    int fd = shm_open("/ds4x.dspbank", O_CREAT | O_RDWR, 0600); if (fd < 0) { perror("llms dsp bank shm: shm_open"); return NULL; }
    struct stat st; if (fstat(fd, &st) != 0) { close(fd); return NULL; }
    if (st.st_size != (off_t)len) {   /* another size: recreate (macOS takes one ftruncate per object) */
        if (st.st_size != 0) { close(fd); shm_unlink("/ds4x.dspbank"); fd = shm_open("/ds4x.dspbank", O_CREAT | O_EXCL | O_RDWR, 0600); if (fd < 0) { perror("llms dsp bank shm: recreate"); return NULL; } }
        if (ftruncate(fd, (off_t)len) != 0) { perror("llms dsp bank shm: ftruncate"); close(fd); return NULL; }
    }
    void *p = mmap(NULL, (size_t)len, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0); close(fd);
    if (p == MAP_FAILED) { perror("llms dsp bank shm: mmap"); return NULL; }
    bank_shm_header *h = (bank_shm_header *)p;
    const int match = h->magic == BANK_SHM_MAGIC && h->valid == 1 && h->bytes == bytes && !strncmp(h->key, key, sizeof h->key);
    if (!match) { h->valid = 0; __atomic_thread_fence(__ATOMIC_SEQ_CST); h->magic = BANK_SHM_MAGIC; h->bytes = bytes; snprintf(h->key, sizeof h->key, "%s", key); }
    @autoreleasepool {
        DS4MetalTensor *tensor = [DS4MetalTensor new];
        tensor.buffer = [g_device newBufferWithBytesNoCopy:(uint8_t *)p + hlen length:(NSUInteger)dlen options:MTLResourceStorageModeShared deallocator:nil];
        if (!tensor.buffer) { munmap(p, (size_t)len); fprintf(stderr, "llms dsp bank shm: newBufferWithBytesNoCopy failed\n"); return NULL; }
        tensor.offset = 0; tensor.bytes = dlen; tensor.owner = 1;
        uint64_t live_snap = 0, peak_snap = 0;
        pthread_mutex_lock(&g_tensor_mu);
        const int tracked = ds4_gpu_tensor_track_alloc_locked((__bridge const void *)tensor, dlen, &live_snap, &peak_snap);
        pthread_mutex_unlock(&g_tensor_mu);
        if (!tracked) { tensor.buffer = nil; munmap(p, (size_t)len); return NULL; }
        bank_shm_header_map = h; *valid_out = match;
        return (__bridge_retained ds4_gpu_tensor *)tensor;
    }
}
void ds4_gpu_llms_shm_tensor_valid(void) { if (bank_shm_header_map) { __atomic_thread_fence(__ATOMIC_SEQ_CST); bank_shm_header_map->valid = 1; } }
static void prepare_shm_cache(void);   /* llms SHM_CACHE: defined after preallocate_slabs; called at the first touch of the cache */
static void bump_slot_generation(uint32_t slot) { if (shm_cache_state == 1 && shm_header && slot < DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES) __atomic_fetch_add(&shm_header->gen[slot], 1u, __ATOMIC_SEQ_CST); }
static void start_background_slabs(uint32_t budget, uint64_t slot) {   /* called by the slot seed once the stride is fixed */
    if (slot == 0 || budget == 0 || !g_device || background_slabs_planned) return;
    ds4_gpu_llms_startup_mark("sbg: admission begins");   /* llms STARTUP_LOG */
    memguard_admit_slabs(budget, slot);   /* llms MEMGUARD (2): the whole plan, before any slab or shm segment exists */
    ds4_gpu_llms_startup_mark("sbg: admission done");
    uint64_t per64 = ds4_gpu_stream_expert_slab_target_bytes() / slot; if (per64 == 0) per64 = 1;
    uint32_t total = 0; int n = 0;
    while (total < budget && n < 64) { const uint32_t sl = per64 > budget - total ? budget - total : (uint32_t)per64; background_slab_bytes[n++] = (uint64_t)sl * slot; total += sl; }
    background_slabs_planned = n; const double t0 = uptime_ms();
    if (shm_cache_on()) { pthread_mutex_lock(&shm_cache_mutex); if (shm_cache_state < 0) attach_shm_cache(slot, budget); pthread_mutex_unlock(&shm_cache_mutex); }   /* llms SHM_CACHE: attach before any slab or install */
    ds4_gpu_llms_startup_mark("sbg: shm attached");   /* llms STARTUP_LOG */
    fprintf(stderr, "llms: slab bg v2 (%d slab buffers for %u slots made AND made resident on a background queue from startup)\n", n, budget);
    atexit_b(^{ fprintf(stderr, "llms slab bg: %d planned, %d made in %.1f ms (background; residency %.1f ms of it), %d taken, %.1f ms waited by the cache\n", background_slabs_planned, background_slabs_made, background_slab_ms, background_residency_ms, background_slabs_taken, background_slab_wait_ms); });
    ds4_gpu_llms_startup_mark("slab bg: dispatched");   /* llms STARTUP_LOG */
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        ds4_gpu_llms_startup_mark("slab bg: thread running");
        for (int k = 0; k < background_slabs_planned; k++) {
            pthread_mutex_lock(&background_slabs_mutex); const int stop = background_slabs_stop; pthread_mutex_unlock(&background_slabs_mutex); if (stop) break;
            id<MTLBuffer> b = shm_slab(k, background_slab_bytes[k], slot, budget);   /* llms SHM_CACHE: slab k from its shm segment, else as before */
            if (!b) b = [g_device newBufferWithLength:(NSUInteger)background_slab_bytes[k] options:MTLResourceStorageModeShared];
            if (b) { b.label = @"ds4_stream_expert_slab"; const double r0 = uptime_ms(); add_slab_to_residency(b, background_slab_bytes[k]); background_residency_ms += uptime_ms() - r0; }
            pthread_mutex_lock(&background_slabs_mutex); if (!background_slabs_stop) background_slab[k] = b; background_slabs_made = k + 1; background_slab_ms = uptime_ms() - t0; pthread_cond_broadcast(&background_slabs_cond); pthread_mutex_unlock(&background_slabs_mutex);
            if (!b) { pthread_mutex_lock(&background_slabs_mutex); background_slabs_stop = 1; pthread_cond_broadcast(&background_slabs_cond); pthread_mutex_unlock(&background_slabs_mutex); break; }
        }
        ds4_gpu_llms_startup_mark("slab bg: all made");   /* llms STARTUP_LOG */
    });
}
static int direct_load_mode(void); static uint64_t direct_load_region_bytes(uint64_t bytes);   /* llms SLOT_SEED: defined below */
static void seed_slots(uint64_t gate_expert_bytes, uint64_t down_expert_bytes) {   /* llms SLOT_SEED (idxc_edit.py, 11:3x-11:4x): the slab stride is otherwise set only by * the first streaming install (alloc_slab_slot), so after a wide prefill that never installs the ED rows path finds slot_bytes 0 and stays unarmed. Seeded with alloc_slab_slot's exact * formula for an ACCEPTED size-class caller only (the gate bytes arrive BS6C-adjusted on both paths); a mismatched seed makes alloc_slab_slot refuse every install -- the canary. */
    if (g_stream_expert_cache_slab_slot_bytes != 0 || gate_expert_bytes == 0 || down_expert_bytes == 0 || gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) return;
    uint64_t sb = gate_expert_bytes * 2ull + down_expert_bytes;
    if (direct_load_mode()) sb = 2ull * direct_load_region_bytes(gate_expert_bytes) + direct_load_region_bytes(down_expert_bytes);
    const uint64_t page = (uint64_t)getpagesize(); if (page != 0) sb = round_up_u64(sb, page);
    if (sb != 0 && sb <= (uint64_t)NSUIntegerMax) { g_stream_expert_cache_slab_slot_bytes = sb; fprintf(stderr, "llms slot seed: stride %llu bytes\n", (unsigned long long)sb); }
    start_background_slabs(ds4_gpu_stream_expert_cache_configured_budget(), g_stream_expert_cache_slab_slot_bytes);   /* llms SLAB_BG v2 */
}
void ds4_gpu_llms_slot_seed(uint64_t gate_expert_bytes, uint64_t down_expert_bytes) {   /* llms SLOT_SEED at STARTUP (ds4.c, after the class is pinned; the probe 11:58 showed note_expert_size is first reached at the first install) */
    ds4_gpu_llms_startup_mark("seed: entry");   /* llms STARTUP_LOG */
    if (gateup_side_on() && gate_expert_bytes == SIDE_IQ2_GATE_EXPERT_BYTES) gate_expert_bytes = gateup_side_matrix_bytes;   /* as budget_for_expert_size adjusts before note_expert_size, and as the cache task carries it */
    if (down_side_on() && down_expert_bytes == SIDE_DOWN_EXPERT_BYTES) down_expert_bytes = down_side_matrix_bytes;   /* llms G32D: the slab stride with the side file's down */
    ds4_gpu_llms_startup_mark("seed: side files ready");   /* llms STARTUP_LOG */
    seed_slots(gate_expert_bytes, down_expert_bytes);
}
static int ds4_gpu_stream_expert_cache_note_expert_size(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (down_side_on() && down_expert_bytes == SIDE_DOWN_EXPERT_BYTES) down_expert_bytes = down_side_matrix_bytes;   /* llms G32D: one size class with the side file's down */
    if (gate_expert_bytes == 0 || down_expert_bytes == 0) return 0;
    if (gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        fprintf(stderr, "ds4: Metal streaming expert cache byte size overflow\n");
        return 0;
    }
    /*
     * The cache is a single-size-class slab allocator: the expert byte size is
     * frozen on first sight (or pre-seeded at startup from the model's slab
     * class) and off-size layers are REJECTED rather than adopted. A rejected
     * layer (mixed-precision boost: Q4_K experts among IQ2 layers) falls back
     * to the mapped-model per-expert path; last-writer-wins here would instead
     * poison the slab size class and deadlock slab reuse.
     */
    const uint64_t bytes = gate_expert_bytes * 2ull + down_expert_bytes;
    if (g_stream_expert_cache_expert_bytes == 0) {
        g_stream_expert_cache_expert_bytes = bytes;
        seed_slots(gate_expert_bytes, down_expert_bytes);   /* llms SLOT_SEED: an accepted first-sight caller */
        return 1;
    }
    if (bytes != g_stream_expert_cache_expert_bytes && gateup_side_state > 0 && gate_expert_bytes == SIDE_IQ2_GATE_EXPERT_BYTES) gateup_side_rejected_notes++;   /* llms BS6C */
    if (bytes == g_stream_expert_cache_expert_bytes) seed_slots(gate_expert_bytes, down_expert_bytes);   /* llms SLOT_SEED: an accepted caller of the frozen class */
    if (bytes != g_stream_expert_cache_expert_bytes && guards_on()) {   /* llms CLASS_GUARD (apply_class_guard.py): under LLMS_DS4_GUARDS (on by default) */
        static uint64_t class_guard_rejections, class_guard_translated_rejections, class_guard_first_install_bytes, class_guard_first_class_bytes; static int exit_report_registered;
        const int xl = gateup_side_on() && gate_expert_bytes == gateup_side_matrix_bytes;   /* a translated install: never legitimately off-class */
        __sync_fetch_and_add(&class_guard_rejections, 1); if (xl && __sync_fetch_and_add(&class_guard_translated_rejections, 1) == 0) { class_guard_first_install_bytes = bytes; class_guard_first_class_bytes = g_stream_expert_cache_expert_bytes;
            fprintf(stderr, "llms CLASS GUARD: a TRANSLATED expert install (%llu bytes) was rejected by the cache's size class (%llu bytes) -- the cache is BYPASSED for it (every use re-reads)\n",
                    (unsigned long long)class_guard_first_install_bytes, (unsigned long long)class_guard_first_class_bytes); }
        if (!__sync_lock_test_and_set(&exit_report_registered, 1)) atexit_b(^{ fprintf(stderr, "llms class guard: %llu installs rejected by the size class, %llu of them translated (first %llu vs class %llu)\n",
            (unsigned long long)class_guard_rejections, (unsigned long long)class_guard_translated_rejections, (unsigned long long)class_guard_first_install_bytes, (unsigned long long)class_guard_first_class_bytes); });
    }
    return bytes == g_stream_expert_cache_expert_bytes;
}

static uint32_t ds4_gpu_stream_expert_cache_requested_budget(void) {
    if (!g_ssd_streaming_mode) return 0;
    if (g_stream_expert_cache_budget_override != 0) {
        return g_stream_expert_cache_budget_override;
    }
    return 0;
}

static uint32_t ds4_gpu_stream_expert_cache_configured_budget(void) {
    uint32_t budget = ds4_gpu_stream_expert_cache_requested_budget();
    if (budget != 0 &&
        g_stream_expert_cache_mlock_budget_cap != 0 &&
        budget > g_stream_expert_cache_mlock_budget_cap) {
        budget = g_stream_expert_cache_mlock_budget_cap;
    }
    return budget;
}

static uint32_t ds4_gpu_stream_expert_cache_effective_cap(
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t n_selected) {
    (void)layer;
    if (ds4_gpu_stream_expert_cache_configured_budget() == 0) return 0;

    /*
     * The residency policy is global: every layer can use any expert slot it
     * routes to, and global pruning decides which existing entry is least
     * valuable.  A per-layer cap made cache size depend on model depth rather
     * than the actual byte budget.
     */
    uint32_t cap = n_total_expert;
    if (cap < n_selected) cap = n_selected;
    if (cap > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
        cap = DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
    }
    return cap;
}

static int ds4_gpu_stream_expert_timing_summary_enabled(void) {
    static int checked = 0;
    static int enabled = 0;
    if (!checked) {
        enabled =
            (getenv("DS4_METAL_STREAMING_EXPERT_TIMING_SUMMARY") != NULL ||
             getenv("DS4_METAL_STREAMING_EXPERT_PROFILE_SUMMARY") != NULL) &&
            getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_TIMING_SUMMARY") == NULL;
        checked = 1;
    }
    return enabled;
}

static uint32_t ds4_gpu_stream_expert_popcount(uint32_t mask) {
    return (uint32_t)__builtin_popcount(mask);
}

static int ds4_gpu_stream_expert_split_worthwhile(
        uint32_t resident_mask,
        uint32_t missing_mask) {
    if (resident_mask == 0 || missing_mask == 0) return 0;
    /*
     * The split path pays an extra command stage and a second routed-expert
     * bind.  It is worthwhile when several experts are missing and their SSD
     * reads can be hidden by resident expert work.  With one or two misses,
     * especially in large caches, a single unsplit routed pass is faster.
     */
    return ds4_gpu_stream_expert_popcount(missing_mask) >= 3u;
}

static void ds4_gpu_stream_expert_timing_note_selected(
        double sync_ms,
        double copy_ms,
        double bind_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_selected_calls++;
    g_stream_expert_timing_selected_sync_ms += sync_ms;
    g_stream_expert_timing_selected_copy_ms += copy_ms;
    g_stream_expert_timing_selected_read_ms += sync_ms + copy_ms;
    g_stream_expert_timing_selected_bind_ms += bind_ms;
}

static void ds4_gpu_stream_expert_timing_note_split(
        uint32_t resident_mask,
        uint32_t missing_mask,
        double   resident_ms,
        double   missing_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_split_layers++;
    g_stream_expert_timing_split_resident_experts +=
        ds4_gpu_stream_expert_popcount(resident_mask);
    g_stream_expert_timing_split_missing_experts +=
        ds4_gpu_stream_expert_popcount(missing_mask);
    g_stream_expert_timing_split_resident_ms += resident_ms;
    g_stream_expert_timing_split_missing_ms += missing_ms;
}

static void ds4_gpu_stream_expert_timing_note_split_missing_detail(
        double load_ms,
        double slot_ms,
        double prune_ms,
        double addr_ms,
        double wait_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_split_missing_load_ms += load_ms;
    g_stream_expert_timing_split_missing_slot_ms += slot_ms;
    g_stream_expert_timing_split_missing_prune_ms += prune_ms;
    g_stream_expert_timing_split_missing_addr_ms += addr_ms;
    g_stream_expert_timing_split_missing_wait_ms += wait_ms;
}

static void ds4_gpu_stream_expert_timing_note_load_detail(
        double prepare_ms,
        double pread_ms,
        double install_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_load_calls++;
    g_stream_expert_timing_load_prepare_ms += prepare_ms;
    g_stream_expert_timing_load_pread_ms += pread_ms;
    g_stream_expert_timing_load_install_ms += install_ms;
}

static void ds4_gpu_stream_expert_timing_note_prepare_batch_reuse(double ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_prepare_batch_reuse_calls++;
    g_stream_expert_timing_prepare_batch_reuse_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_prepare_buffer(double ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_prepare_buffer_calls++;
    g_stream_expert_timing_prepare_buffer_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_prepare_task(
        uint32_t experts,
        double   ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_prepare_task_experts += experts;
    g_stream_expert_timing_prepare_task_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_reuse_scan(
        uint64_t entries,
        double   ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_reuse_scan_calls++;
    g_stream_expert_timing_reuse_scan_entries += entries;
    g_stream_expert_timing_reuse_scan_ms += ms;
