    g_stream_expert_timing_reuse_clear_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_cache_class(
        uint32_t resident_mask,
        uint32_t missing_mask) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    const uint32_t resident = ds4_gpu_stream_expert_popcount(resident_mask);
    const uint32_t missing = ds4_gpu_stream_expert_popcount(missing_mask);
    if (missing == 0) {
        g_stream_expert_timing_cache_all_resident_layers++;
    } else if (resident == 0) {
        g_stream_expert_timing_cache_all_missing_layers++;
    } else {
        g_stream_expert_timing_cache_mixed_layers++;
    }
    g_stream_expert_timing_cache_resident_experts += resident;
    g_stream_expert_timing_cache_missing_experts += missing;
}

static int ds4_gpu_stream_expert_readahead_enabled(void) {
    return g_ssd_streaming_mode && g_model_fd_nocache < 0 &&   /* llms: no page-cache hint for uncached preads */
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_READAHEAD") == NULL;
}

static void ds4_gpu_stream_expert_readahead_range(uint64_t offset, uint64_t len) {
    if (!ds4_gpu_stream_expert_readahead_enabled() || g_model_fd < 0 || len == 0) {
        return;
    }

#if defined(F_RDADVISE)
    const int timing = ds4_gpu_stream_expert_timing_summary_enabled();
    const double t0 = timing ? ds4_gpu_now_ms() : 0.0;
    uint64_t pos = offset;
    uint64_t rem = len;
    while (rem > 0) {
        const uint64_t chunk64 =
            rem > (uint64_t)INT_MAX ? (uint64_t)INT_MAX : rem;
        if (pos > (uint64_t)LLONG_MAX) break;

        struct radvisory ra;
        ra.ra_offset = (off_t)pos;
        ra.ra_count = (int)chunk64;
        (void)fcntl(g_model_fd, F_RDADVISE, &ra);

        pos += chunk64;
        rem -= chunk64;
    }
    if (timing) {
        g_stream_expert_timing_readahead_calls++;
        g_stream_expert_timing_readahead_bytes += len;
        g_stream_expert_timing_readahead_ms += ds4_gpu_now_ms() - t0;
    }
#else
    (void)offset;
    (void)len;
#endif
}

typedef struct {
    uint64_t offset;
    uint64_t len;
    uint8_t *dst;
    uint64_t read_bytes;
    double ms;
    int ok;
} ds4_gpu_stream_expert_read_task;
static void report_selected_batch(void) { fprintf(stderr, "llms static state: prepare_selected_batch %llu calls, %llu heap ids, %llu heap tasks (concurrent / oversize)\n",
    (unsigned long long)selected_batch_calls, (unsigned long long)selected_batch_heap_ids, (unsigned long long)selected_batch_heap_tasks); }
static int32_t *take_selected_ids(uint64_t n) {
    static int exit_report_registered; if (!exit_report_registered) { exit_report_registered = 1; atexit(report_selected_batch); }
    selected_batch_calls++;
    int z = 0; if (n <= SELECTED_BATCH_MAX_IDS && atomic_compare_exchange_strong(&selected_batch_ids_busy, &z, 1)) return selected_batch_ids;
    selected_batch_heap_ids++; return malloc((size_t)n * sizeof(int32_t));
}
static ds4_gpu_stream_expert_read_task *take_read_tasks(uint64_t n) {
    int z = 0; if (n <= SELECTED_BATCH_MAX_TASKS && atomic_compare_exchange_strong(&selected_batch_tasks_busy, &z, 1)) {
        memset(selected_batch_tasks, 0, (size_t)n * sizeof(ds4_gpu_stream_expert_read_task)); return (ds4_gpu_stream_expert_read_task *)selected_batch_tasks; }
    selected_batch_heap_tasks++; return calloc((size_t)n, sizeof(ds4_gpu_stream_expert_read_task));
}
static void give_read_tasks(ds4_gpu_stream_expert_read_task *p) { if ((unsigned char *)p == selected_batch_tasks) atomic_store(&selected_batch_tasks_busy, 0); else free(p); }
_Static_assert(sizeof(ds4_gpu_stream_expert_read_task) <= SELECTED_BATCH_TASK_BYTES, "llms STATIC_STATE: task storage too small");   /* llms STATIC_STATE */

