                (void)aio_return(&cbs[i]);
            }
            free(cbs); free(need);
        }
    }
    dispatch_group_t grp = dispatch_group_create(); ticket_group[sl] = grp;
    if (load_concurrent) {   /* mode 2: one block per read; ds4's pread pool is not safe for two callers (its completion signal wakes one waiter) */
        ticket_ok[sl] = -1; ticket_start[sl] = ds4_gpu_now_ms(); ticket_end[sl] = 0.0;
        for (uint32_t i = 0; i < n_tasks; i++) {
            ds4_gpu_stream_expert_read_task *t = &tasks[i];
            dispatch_group_async(grp, load_queue, ^{
                if (async_canary_on()) usleep(30000);
                t->ok = expert_read_pread(t->offset, t->len, t->dst, &t->read_bytes, &t->ms);
                const double e = ds4_gpu_now_ms();
