            });
        }
        return id;
    }
    dispatch_group_async(grp, load_queue, ^{
        uint64_t b = 0; double ms = 0.0;
        if (async_canary_on()) usleep(30000);
        const int ok = ds4_gpu_stream_expert_read_tasks(tasks, n_tasks, &b, &ms);
        ticket_bytes[sl] = b; ticket_ms[sl] = ms; ticket_ok[sl] = ok;
        if (ticket_ledger) ticket_block_end_uptime[sl] = uptime_s();   /* llms LEDGER_ABS */
    });
    return id;
