static void split_pairs_into_quads(uint32_t *l, uint32_t n, uint32_t *ns, uint32_t *e2, uint32_t *nd, uint32_t *e4, uint32_t *nq) {   /* l sorted by expert: a run of 3 or more -> quads (four rows, or three), a rest of 2 -> a double, a rest of 1 stays in l */
    uint32_t a = 0, k2 = 0, k4 = 0;
    for (uint32_t i = 0; i < n; ) {
        uint32_t r = 1; while (i + r < n && peeked_ids[l[i + r]] == peeked_ids[l[i]]) r++;
        uint32_t j = i, left = r;
        while (left >= 3) {
            const uint32_t take = (left == 3 || left == 5) ? 3u : 4u;   /* 5 = 3 + 2 */
            e4[4 * k4] = l[j]; e4[4 * k4 + 1] = l[j + 1]; e4[4 * k4 + 2] = l[j + 2]; e4[4 * k4 + 3] = take == 4 ? l[j + 3] : 0xFFFFFFFFu;
            k4++; dedup4_rows += take; j += take; left -= take;
        }
        if (left == 2) { e2[2 * k2] = l[j]; e2[2 * k2 + 1] = l[j + 1]; k2++; }
        else if (left == 1) l[a++] = l[j];
        i += r;
    }
    if (pair_list_mode() == 9 && k4 > 0) k4--;   /* canary: one quad entry of the list is never computed */
    *ns = a; *nd = k2; *nq = k4; dedup2_singles += a; dedup2_doubles += k2; dedup4_quads += k4;
}
