static void split_pairs_into_entries(uint32_t *l, uint32_t n, uint32_t *ns, uint32_t *e, uint32_t *nd) {   /* l sorted by expert: pairs of a run -> entries, the rest stay in l */
    if (llms_alt_off("dd2")) { *ns = n; *nd = 0; dedup2_singles += n; return; }   /* llms ALT dd2 (apply_ds4_alt_dd2.py): no entries on the off side */
    uint32_t a = 0, k = 0;
    for (uint32_t i = 0; i < n; ) {
        if (i + 1 < n && peeked_ids[l[i]] == peeked_ids[l[i + 1]]) { e[2 * k] = l[i]; e[2 * k + 1] = l[i + 1]; k++; i += 2; }
        else l[a++] = l[i++];
    }
    if (cf1_mode() && !llms_alt_off("cf1") && a > 0) {   /* llms CF1: the singles become one-row entries behind the two-row ones */
        uint32_t keep = a; if (cf1_mode() < 0) keep--;   /* canary: the last single is dropped */
        for (uint32_t i = 0; i < keep; i++) { e[2 * k] = l[i]; e[2 * k + 1] = 0xFFFFFFFFu; k++; }
        cf1_singles += keep; a = 0;
    }
    *ns = a; *nd = k; dedup2_singles += a; dedup2_doubles += k;
}
static uint32_t build_pair_entries(const uint32_t *l, uint32_t n, uint32_t *e) {   /* l sorted by expert: runs of one expert, two pairs per entry */
    uint32_t k = 0;
    for (uint32_t i = 0; i < n; ) {
        if (i + 1 < n && peeked_ids[l[i]] == peeked_ids[l[i + 1]]) { e[2 * k] = l[i]; e[2 * k + 1] = l[i + 1]; i += 2; dedup_two_row_entries++; }
        else { e[2 * k] = l[i]; e[2 * k + 1] = 0xFFFFFFFFu; i += 1; }
        k++;
    }
    dedup_entries += k;
    return k;
}
static uint64_t pair_run_histogram[18];   /* llms run histogram: runs of r pairs of one expert in a sorted list (17 = more) */
static void sort_pairs_by_expert(uint32_t *l, uint32_t n) {   /* llms SPLIT listsort: insertion sort of pair numbers by expert id, stable */
    for (uint32_t i = 1; i < n; i++) {
        const uint32_t v = l[i]; const int32_t ev = peeked_ids[v]; uint32_t j = i;
        while (j > 0 && peeked_ids[l[j - 1]] > ev) { l[j] = l[j - 1]; j--; }
        l[j] = v;
    }
    for (uint32_t i = 1; i < n; i++) if (peeked_ids[l[i]] == peeked_ids[l[i - 1]]) pair_list_adjacent_pairs++;
    for (uint32_t i = 0; i < n; ) { uint32_t r = 1; while (i + r < n && peeked_ids[l[i + r]] == peeked_ids[l[i]]) r++; pair_run_histogram[r < 17 ? r : 17]++; i += r; }   /* llms run histogram (apply_ds4_run_hist.py) */
}
