        uint32_t                pos0,
        uint32_t                n_head,
        uint32_t                head_dim,
        uint32_t                ratio,
        float                   scale) {
    return ds4_gpu_indexer_scores_batch_tensor(scores,
                                                 q,
                                                 weights,
                                                 index_comp,
                                                 n_comp,
                                                 n_tokens,
                                                 pos0,
                                                 n_head,
                                                 head_dim,
                                                 ratio,
                                                 scale);
}

static int topk_index_order_on(void) {   /* llms TK_IDXORD (apply_tkio.py): the top-k set in index order, no sort; ALT tkio */
    static int on = -1; static uint64_t calls;
    if (on < 0) { const char *e = getenv("LLMS_DS4_TK_IDXORD"), *src = getenv("DS4_METAL_DSV4_MISC_SOURCE"); on = e && *e && *e != '0';
                  if (on) { int has = 0; FILE *f = src ? fopen(src, "r") : NULL; if (f) { char buf[65536]; size_t nr;
                                while (!has && (nr = fread(buf, 1, sizeof buf - 1, f)) > 0) { buf[nr] = 0; has = strstr(buf, "llms TK_IDXORD") != NULL; if (!has && nr > 64) fseek(f, -64, SEEK_CUR); } fclose(f); }
                            if (!has) { fprintf(stderr, "llms: LLMS_DS4_TK_IDXORD ignored: DS4_METAL_DSV4_MISC_SOURCE does not carry the TK_IDXORD kernel code\n"); on = 0; }
                            else { fprintf(stderr, "llms: tk idxord (the indexer top-k set in index order, no sort; rounding class; ALT tkio)\n");
                                   atexit_b(^{ fprintf(stderr, "llms tk idxord: %llu dispatches in index order\n", (unsigned long long)calls); }); } } }
    if (on && !llms_alt_off("tkio")) { calls++; return 1; }
    return 0;
}
static int ds4_gpu_indexer_topk_tensor_impl(
        ds4_gpu_tensor       *selected,
        const ds4_gpu_tensor *scores,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                top_k,
        uint32_t                causal_start,
        uint32_t                causal_ratio) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!selected || !scores || n_comp == 0 || n_tokens == 0 || top_k == 0 || top_k > n_comp) return 0;
    {   /* llms TOPK_RADIX (apply_ds4_topk_radix.py): radix select, one threadgroup per row; non-causal, 64 <= k <= 1024 */
        static int topk_radix_state = -2; static id<MTLComputePipelineState> topk_radix_pipeline; static uint64_t topk_radix_calls;
        if (topk_radix_state < -1) { const char *src = getenv("DS4_METAL_DSV4_MISC_SOURCE"); topk_radix_state = src && llms_srckey(src, "llms16") != NULL;   /* adopted; the switch removed 10-27: whenever the misc source is an *llms16* one */
                       if (topk_radix_state) { topk_radix_pipeline = ds4_gpu_get_pipeline_or_die("kernel_llms_topk_radix"); if (!topk_radix_pipeline) { fprintf(stderr, "llms topk radix: kernel missing\n"); topk_radix_state = 0; } } }
        if (topk_radix_state && !causal_ratio && top_k >= 64u && top_k <= 1024u && !llms_alt_off("tkrx")) {
            @autoreleasepool {
                id<MTLBuffer> scorebuf = ds4_gpu_tensor_buffer(scores), selbuf = ds4_gpu_tensor_buffer(selected);
                if (!scorebuf || !selbuf || ds4_gpu_tensor_bytes(scores) < (uint64_t)n_comp * n_tokens * sizeof(float) ||
                    ds4_gpu_tensor_bytes(selected) < (uint64_t)top_k * n_tokens * sizeof(uint32_t)) { fprintf(stderr, "ds4: Metal graph indexer top-k received undersized buffers\n"); return 0; }
                struct { uint32_t n, k, rows, canary; uint64_t score_stride, sel_stride; uint32_t mode; } ra = { n_comp, top_k, n_tokens, 0u, n_comp, top_k, (uint32_t)topk_index_order_on() };   /* llms TK_IDXORD: mode */
                int owned = 0;
                id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
                if (!enc) return 0;
                [enc setComputePipelineState:topk_radix_pipeline];
                [enc setBytes:&ra length:sizeof(ra) atIndex:0];
                [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:1];
                [enc setBuffer:selbuf offset:ds4_gpu_tensor_offset(selected) atIndex:2];
                [enc setThreadgroupMemoryLength:(2048u + 16u + 1024u + 1024u) * 4u atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(n_tokens, 1, 1) threadsPerThreadgroup:MTLSizeMake(1024, 1, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);
                if (!topk_radix_calls++) fprintf(stderr, "llms topk radix: first call (n %u, k %u, rows %u)\n", n_comp, top_k, n_tokens);
                {   /* llms TOPK_KN (instrument): calls with k < n (the radix passes run) vs k >= n (every element selected) */
                    static uint64_t topk_radix_calls_below_n, topk_radix_calls_at_least_n, topk_radix_max_n; if (!topk_radix_calls_below_n && !topk_radix_calls_at_least_n) atexit_b(^{ fprintf(stderr, "llms topk radix: %llu calls with k < n (max n %llu), %llu with k >= n\n", (unsigned long long)topk_radix_calls_below_n, (unsigned long long)topk_radix_max_n, (unsigned long long)topk_radix_calls_at_least_n); });
                    if (top_k < n_comp) topk_radix_calls_below_n++; else topk_radix_calls_at_least_n++; if (n_comp > topk_radix_max_n) topk_radix_max_n = n_comp;
                }
                return ds4_gpu_finish_command_buffer(cb, owned, "llms topk radix");
            }
        }
    }

    {   /* llms TOPK2048 (apply_topk2048.py):; non-causal, one row, n_comp > 2048 (layer 20's block candidates) */
        static int topk2048_state = -2; static id<MTLComputePipelineState> topk2048_sel, topk2048_rep; static uint64_t topk2048_calls, topk2048_nmax;
        if (topk2048_state < -1) { const char *e = getenv("LLMS_DS4_TOPK2048"); topk2048_state = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
                        if (topk2048_state) { topk2048_sel = ds4_gpu_get_pipeline_or_die("astra_block_top2048"); topk2048_rep = ds4_gpu_get_pipeline_or_die("astra_cutoff_repair");
                                   if (!topk2048_sel || !topk2048_rep) { fprintf(stderr, "llms: LLMS_DS4_TOPK2048 ignored: DS4_METAL_DSV4_MISC_SOURCE lacks astra_block_top2048 / astra_cutoff_repair\n"); topk2048_state = 0; }
                                   else { fprintf(stderr, topk2048_state < 0 ? "llms: topk2048 -- CANARY: each row's first index has its low bit flipped\n" : "llms: topk2048 (K2048 radix select + cutoff-tie repair for the block candidates)\n");
                                          atexit_b(^{ fprintf(stderr, "llms topk2048: %llu calls, largest n %llu\n", (unsigned long long)topk2048_calls, (unsigned long long)topk2048_nmax); }); } } }
        if (topk2048_state && !causal_ratio && top_k == 2048u && n_tokens == 1u && n_comp > 2048u && !llms_alt_off("tk2048")) {
            @autoreleasepool {
                id<MTLBuffer> scorebuf = ds4_gpu_tensor_buffer(scores), selbuf = ds4_gpu_tensor_buffer(selected);
                if (!scorebuf || !selbuf || ds4_gpu_tensor_bytes(scores) < (uint64_t)n_comp * sizeof(float) || ds4_gpu_tensor_bytes(selected) < 2048u * sizeof(uint32_t)) { fprintf(stderr, "ds4: Metal graph indexer top-k received undersized buffers\n"); return 0; }
                struct { uint32_t n, k, rows, canary; uint64_t score_stride, sel_stride; uint32_t mode; } ra = { n_comp, 2048u, 1u, topk2048_state < 0 ? 1u : 0u, n_comp, 2048u, 1u };
                int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned); id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil; if (!enc) return 0;
                [enc setComputePipelineState:topk2048_sel]; [enc setBytes:&ra length:sizeof(ra) atIndex:0]; [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:1]; [enc setBuffer:selbuf offset:ds4_gpu_tensor_offset(selected) atIndex:2];
                [enc setThreadgroupMemoryLength:16448u atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1024, 1, 1)];
                const uint32_t nn = n_comp;
                [enc setComputePipelineState:topk2048_rep]; [enc setBytes:&nn length:sizeof(nn) atIndex:0]; [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:1]; [enc setBuffer:selbuf offset:ds4_gpu_tensor_offset(selected) atIndex:2];
                [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1024, 1, 1)];
                ds4_gpu_end_compute_encoder(cb, enc); topk2048_calls++; if (n_comp > topk2048_nmax) topk2048_nmax = n_comp;
                return ds4_gpu_finish_command_buffer(cb, owned, "llms topk2048");
            }
        }
    }
    @autoreleasepool {
        id<MTLComputePipelineState> sort_pipeline = causal_ratio ?
            ds4_gpu_get_pipeline_or_die(getenv("DS4_METAL_DISABLE_V41_TOPK_SHUFFLE") ?
                "kernel_argsort_f32_i32_desc_causal" : "kernel_argsort_f32_i32_desc_causal_shuffle") :
            g_argsort_f32_i32_desc_pipeline;
        id<MTLComputePipelineState> merge_pipeline = causal_ratio ?
            ds4_gpu_get_pipeline_or_die(top_k == 512u && !getenv("DS4_METAL_DISABLE_V41_TOPK_PREFIX") ?
                "kernel_argsort_merge_f32_i32_desc_causal_prefix" :
                "kernel_argsort_merge_f32_i32_desc_causal") : g_argsort_merge_f32_i32_desc_pipeline;
        if (!sort_pipeline || !merge_pipeline) return 0;
        const uint64_t score_bytes = (uint64_t)n_comp * n_tokens * sizeof(float);
        const uint64_t selected_bytes = (uint64_t)top_k * n_tokens * sizeof(uint32_t);
        id<MTLBuffer> scorebuf = ds4_gpu_tensor_buffer(scores);
        id<MTLBuffer> selbuf = ds4_gpu_tensor_buffer(selected);
        if (!scorebuf || !selbuf ||
            ds4_gpu_tensor_bytes(scores) < score_bytes ||
            ds4_gpu_tensor_bytes(selected) < selected_bytes) {
            fprintf(stderr, "ds4: Metal graph indexer top-k received undersized buffers\n");
            return 0;
        }
        NSUInteger max_threads = g_argsort_f32_i32_desc_pipeline.maxTotalThreadsPerThreadgroup;
        if (max_threads == 0) max_threads = 256;
        int32_t nth = 1;
        while ((uint32_t)nth < n_comp && (uint64_t)2u * (uint64_t)nth <= (uint64_t)max_threads) {
            nth *= 2;
        }
        if (causal_ratio && (sort_pipeline.maxTotalThreadsPerThreadgroup < (NSUInteger)nth ||
            (causal_start + 1u) / causal_ratio <= (uint32_t)nth / 2u)) return 0;
        const int32_t npr = (int32_t)((n_comp + (uint32_t)nth - 1u) / (uint32_t)nth);
        const int32_t block_top_k = (int32_t)(top_k < (uint32_t)nth ? top_k : (uint32_t)nth);
        int32_t work_width = (int32_t)top_k;
        if (npr > 1) {
            const int32_t last_block = (int32_t)n_comp - (npr - 1) * nth;
            work_width = (npr - 1) * block_top_k + (last_block < block_top_k ? last_block : block_top_k);
        }
        const uint64_t scratch_row_bytes = (uint64_t)work_width * sizeof(uint32_t);
        const bool one_pass = npr <= 1;
        const uint64_t scratch_bytes = one_pass ? scratch_row_bytes * n_tokens :
            2u * scratch_row_bytes * n_tokens;
        if (!ds4_gpu_ensure_scratch_buffer(&g_indexer_topk_buffer,
                                             &g_indexer_topk_bytes,
                                             (NSUInteger)scratch_bytes,
                                             "ds4_indexer_topk")) {
            return 0;
        }

        ds4_gpu_kargs_argsort args = {
            .ne00 = (int32_t)n_comp,
            .ne01 = (int32_t)n_tokens,
            .ne02 = 1,
            .ne03 = 1,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)n_comp * sizeof(float),
            .nb02 = (uint64_t)n_comp * n_tokens * sizeof(float),
            .nb03 = (uint64_t)n_comp * n_tokens * sizeof(float),
            .ne0 = work_width,
            .ne1 = (int32_t)n_tokens,
            .ne2 = 1,
            .ne3 = 1,
            .top_k = block_top_k,
            .causal_start = causal_start,
            .causal_ratio = causal_ratio,
        };
        // kernel_argsort_f32_i32_desc stages the block's scores behind the
        // index array: nth int32 indices + nth float scores.
        const NSUInteger smem = (((NSUInteger)nth * (sizeof(int32_t) + sizeof(float))) + 15u) & ~(NSUInteger)15u;

        NSUInteger cur_off = 0;
        NSUInteger next_off = (NSUInteger)scratch_row_bytes * n_tokens;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:sort_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:1];
        [enc setBuffer:one_pass ? selbuf : g_indexer_topk_buffer
              offset:one_pass ? ds4_gpu_tensor_offset(selected) : cur_off
             atIndex:2];
        [enc setThreadgroupMemoryLength:smem atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)npr * n_tokens, 1, 1)
             threadsPerThreadgroup:MTLSizeMake((NSUInteger)nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        int32_t len = block_top_k;
        while (len < work_width) {
            const int32_t nm = (work_width + 2 * len - 1) / (2 * len);
            const bool final_merge = nm == 1;
            NSUInteger merge_threads = merge_pipeline.maxTotalThreadsPerThreadgroup;
            if (merge_threads == 0 || merge_threads > 512u) merge_threads = 512u;
            if (merge_threads > (NSUInteger)len) merge_threads = (NSUInteger)len;
            if (merge_threads == 0) merge_threads = 1;

            ds4_gpu_kargs_argsort_merge merge_args = {
                .ne00 = (int64_t)n_comp,
                .ne01 = (int64_t)n_tokens,
                .ne02 = 1,
                .ne03 = 1,
                .nb00 = sizeof(float),
                .nb01 = (uint64_t)n_comp * sizeof(float),
                .nb02 = (uint64_t)n_comp * n_tokens * sizeof(float),
                .nb03 = (uint64_t)n_comp * n_tokens * sizeof(float),
                .ne0 = work_width,
                .ne1 = (int32_t)n_tokens,
                .ne2 = 1,
                .ne3 = 1,
                .top_k = nm == 1 ? (int32_t)top_k : work_width,
                .len = len,
                .causal_start = causal_start,
                .causal_ratio = causal_ratio,
                .block_width = (uint32_t)nth,
                .block_top_k = (uint32_t)block_top_k,
            };

            enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:merge_pipeline];
            [enc setBytes:&merge_args length:sizeof(merge_args) atIndex:0];
            [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:1];
            [enc setBuffer:g_indexer_topk_buffer offset:cur_off atIndex:2];
            [enc setBuffer:final_merge ? selbuf : g_indexer_topk_buffer
                  offset:final_merge ? ds4_gpu_tensor_offset(selected) : next_off
                 atIndex:3];
            [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)nm * n_tokens, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(merge_threads, 1, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            const NSUInteger tmp = cur_off;
            cur_off = next_off;
            next_off = tmp;
            len <<= 1;
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "indexer top-k")) return 0;
    }

    return 1;
}

int ds4_gpu_indexer_topk_tensor(ds4_gpu_tensor *selected, const ds4_gpu_tensor *scores,
                               uint32_t n_comp, uint32_t n_tokens, uint32_t top_k) {
    return ds4_gpu_indexer_topk_tensor_impl(selected, scores, n_comp, n_tokens, top_k, 0, 0);
}

int ds4_gpu_dsv41_indexer_topk_batch(ds4_gpu_tensor *selected, const ds4_gpu_tensor *scores,
                                    uint32_t width, uint32_t rows, uint32_t start, uint32_t ratio) {
    if ((ratio != 1u && ratio != 2u) || !rows || rows > UINT32_MAX - start ||
        width > INT32_MAX || rows > INT32_MAX || (start + rows) / ratio > width ||
        (start + 1u) / ratio < 1024u) return 0;
    return ds4_gpu_indexer_topk_tensor_impl(selected, scores, width, rows, 512u, start, ratio);
}

int ds4_gpu_argmax_tensor(
        ds4_gpu_tensor       *out_idx,
        const ds4_gpu_tensor *logits,
        uint32_t                n_vocab) {
    if (!out_idx || !logits || n_vocab == 0) return 0;
    if (ds4_gpu_tensor_bytes(out_idx) < sizeof(int32_t) ||
        ds4_gpu_tensor_bytes(logits) < (uint64_t)n_vocab * sizeof(float)) {
        fprintf(stderr, "ds4: Metal graph argmax received undersized buffers\n");
        return 0;
    }

    return ds4_gpu_indexer_topk_tensor(out_idx, logits, n_vocab, 1, 1);
}

int ds4_gpu_dsv4_topk_mask_tensor(
        ds4_gpu_tensor       *mask,
        const ds4_gpu_tensor *topk,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                top_k) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!mask || !topk || n_comp == 0 || n_tokens == 0 || top_k == 0) return 0;

    @autoreleasepool {
        const uint64_t topk_bytes = (uint64_t)top_k * n_tokens * sizeof(int32_t);
        const uint64_t mask_bytes = (uint64_t)n_comp * n_tokens * sizeof(float);
        id<MTLBuffer> topkbuf = ds4_gpu_tensor_buffer(topk);
        id<MTLBuffer> maskbuf = ds4_gpu_tensor_buffer(mask);
        if (!topkbuf || !maskbuf ||
            ds4_gpu_tensor_bytes(topk) < topk_bytes ||
            ds4_gpu_tensor_bytes(mask) < mask_bytes) {
            fprintf(stderr, "ds4: Metal dsv4 top-k mask received undersized buffers\n");
            return 0;
        }

        ds4_gpu_dsv4_topk_mask_args args = {
            .ne00 = (int64_t)top_k,
            .ne01 = (int64_t)n_tokens,
            .nb00 = sizeof(int32_t),
            .nb01 = (uint64_t)top_k * sizeof(int32_t),
            .ne0 = (int64_t)n_comp,
            .ne1 = (int64_t)n_tokens,
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)n_comp * sizeof(float),
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_dsv4_topk_mask_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:topkbuf offset:ds4_gpu_tensor_offset(topk) atIndex:1];
        [enc setBuffer:maskbuf offset:ds4_gpu_tensor_offset(mask) atIndex:2];
        [enc dispatchThreadgroups:MTLSizeMake((((NSUInteger)n_comp * n_tokens) + 255u) / 256u, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_dsv4_topk_mask_scatter_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:topkbuf offset:ds4_gpu_tensor_offset(topk) atIndex:1];
        [enc setBuffer:maskbuf offset:ds4_gpu_tensor_offset(mask) atIndex:2];
        [enc dispatchThreadgroups:MTLSizeMake((((NSUInteger)top_k * n_tokens) + 255u) / 256u, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "dsv4 top-k mask")) return 0;
    }

    return 1;
}

/* llms Q4L (apply_q4l.py): one-token dense matvecs on 4-bit copies listed by LLMS_DS4_Q4L=<index> */
typedef struct { uint64_t abs, off; uint32_t k, n; __unsafe_unretained id<MTLBuffer> buf; uint64_t inner; char alt[8]; } dense4_entry;   /* buf, inner: llms Q4L_WRAP; alt: llms Q4L_TAG */
static NSMutableArray *dense4_buffers_alive;   /* llms Q4L_WRAP: keeps the per-tensor buffers alive */
static dense4_entry *dense4_table; static int dense4_count = -1; static id<MTLBuffer> dense4_buffer;
static uint64_t dense4_calls, dense4_batch_calls, dense4_unaligned, dense4_attention_out_calls;   /* q4la: llms Q4L_A */
static int compare_dense4_offsets(const void *a, const void *b) {
    const uint64_t x = ((const dense4_entry *)a)->abs, y = ((const dense4_entry *)b)->abs; return x < y ? -1 : x > y;
}
static int parse_overlay_u64(const char *s, uint64_t *out) {
    uint64_t v=0;
    if(!*s) return 0;
    for(;*s;s++) {
        if(*s<'0'||*s>'9') return 0;
        unsigned d=(unsigned)(*s-'0');
        if(v>(UINT64_MAX-d)/10u) return 0;
        v=v*10u+d;
    }
    *out=v; return 1;
}
/* Sparse experiment payload: validate all rows before replacing owned mapping pages.
 * Called only before newBufferWithBytesNoCopy. No writes to either source file. */
static int apply_dense4_overlay(void *mp, uint64_t maplen, const char *index,
                                  const dense4_entry *base, int count,
                                  uint64_t expected_gguf_bytes) {
    typedef struct { uint64_t dst, src, len; int entry; } patch_range;
    FILE *fi = NULL; int fd = -1, ok = 0, used = 0;
    patch_range *ranges = NULL;
    char path[4096], line[1024], name[512], extra;
    uint64_t gb, ab, off, ku, nu; unsigned k, n;
    char gs[32], as[32], os[32], ks[32], ns[32];
    const char *why = "unknown error";
#define Q4OV_FAIL(message) do { why = (message); goto finish; } while (0)
    if (!index || !*index || !strcmp(index, "0")) return 1;
    if (count <= 0 || !mp || !maplen) Q4OV_FAIL("empty base mapping");
    fi = fopen(index, "r");
    if (!fi) Q4OV_FAIL("cannot open index");
    if (!fgets(path, sizeof path, fi) || !strchr(path, '\n')) Q4OV_FAIL("missing/long payload path");
    path[strcspn(path, "\r\n")] = 0;
    if (!*path) Q4OV_FAIL("empty payload path");
    if (!fgets(line, sizeof line, fi) || sscanf(line,"gguf_bytes %31s %c",gs,&extra)!=1 || !parse_overlay_u64(gs,&gb) || gb!=expected_gguf_bytes)
        Q4OV_FAIL("model size mismatch");
    fd = open(path, O_RDONLY);
    const off_t fsz = fd < 0 ? -1 : lseek(fd,0,SEEK_END);
    if (fsz <= 0) Q4OV_FAIL("empty/missing payload");
    const long page = sysconf(_SC_PAGESIZE);
    if (page <= 0 || 16384u % (uint64_t)page) Q4OV_FAIL("unsupported page size");
    ranges = calloc((size_t)count, sizeof *ranges);
    if (!ranges) Q4OV_FAIL("allocation failed");
    while (fgets(line,sizeof line,fi)) {
        if (!strchr(line,'\n') && !feof(fi)) Q4OV_FAIL("long index row");
        if (sscanf(line,"%31s %31s %31s %31s %511s %c",as,os,ks,ns,name,&extra)!=5)
            Q4OV_FAIL("malformed index row");
        if(!parse_overlay_u64(as,&ab)||!parse_overlay_u64(os,&off)||!parse_overlay_u64(ks,&ku)||!parse_overlay_u64(ns,&nu)||ku>UINT32_MAX||nu>UINT32_MAX)
            Q4OV_FAIL("invalid/overflowing unsigned integer");
        k=(unsigned)ku; n=(unsigned)nu;
        if (used==count) Q4OV_FAIL("too many override rows");
        int found=-1;
        for (int j=0;j<count;j++) if (base[j].abs==ab) {
            if (found>=0) Q4OV_FAIL("duplicate key in base");
            found=j;
        }
        if (found<0 || !k || !n || k%256u || base[found].k!=k || base[found].n!=n)
            Q4OV_FAIL("unknown key or shape mismatch");
        const uint64_t rowbytes=(uint64_t)(k/16u)*9u;
        if (rowbytes && (uint64_t)n>UINT64_MAX/rowbytes) Q4OV_FAIL("tensor size overflow");
        const uint64_t len=rowbytes*(uint64_t)n, dst=base[found].off;
        if (!len || len>SIZE_MAX || dst>maplen || len>maplen-dst || off>(uint64_t)fsz || len>(uint64_t)fsz-off)
            Q4OV_FAIL("range outside mapped payload");
        if ((dst%16384u)||(off%16384u)||(len%16384u)) Q4OV_FAIL("tensor range is not a complete Metal page");
        for (int j=0;j<used;j++) {
            if (ranges[j].entry==found) Q4OV_FAIL("duplicate override key");
            if (dst<ranges[j].dst+ranges[j].len && ranges[j].dst<dst+len)
                Q4OV_FAIL("overlapping override destinations");
        }
        /* A replacement may not touch a different tensor, even if that tensor
         * is absent from this overlay index. Bounds use subtraction first. */
        for (int j=0;j<count;j++) if(j!=found) {
            const uint64_t rb=(uint64_t)(base[j].k/16u)*9u;
            if (!rb || (uint64_t)base[j].n>UINT64_MAX/rb) Q4OV_FAIL("invalid base extent");
            const uint64_t blen=rb*(uint64_t)base[j].n, boff=base[j].off;
            if (boff>maplen || blen>maplen-boff) Q4OV_FAIL("invalid base range");
            if (dst<boff+blen && boff<dst+len) Q4OV_FAIL("override aliases another base tensor");
        }
        ranges[used++]=(patch_range){dst,off,len,found};
    }
    if (ferror(fi)||!used) Q4OV_FAIL("empty or unreadable index");
    for(int j=0;j<used;j++) {
        void *at=(uint8_t *)mp+ranges[j].dst;
        void *got=mmap(at,(size_t)ranges[j].len,PROT_READ,MAP_PRIVATE|MAP_FIXED,fd,(off_t)ranges[j].src);
        if(got==MAP_FAILED || got!=at) Q4OV_FAIL("fixed mapping failed; startup must abort");
    }
    fprintf(stderr,"llms: q4l sparse override %d tensors from %s\n",used,path);
    ok=1;
finish:
    if(!ok) fprintf(stderr,"llms: q4l sparse override rejected: %s\n",why);
    if(fi) fclose(fi);
    if(fd>=0) close(fd);
    free(ranges);
#undef Q4OV_FAIL
    return ok;
}

/* llms Q4S8 (apply_q4s8.py): Q4L group scales as ONE byte (sign | index of a 128-entry fp16 codebook) -- rows of 17K/32 bytes; payloads and the dense source named *_q4s8 (q4s8_pack.py, make_q4s8_source.py); off unless LLMS_DS4_Q4S8 is set. 10-28 21:2x: the rounding costs no KL. */
static int q4s8_state = -1;
static int q4s8_on(void) { if (q4s8_state < 0) { const char *e = getenv("LLMS_DS4_Q4S8"); q4s8_state = e && *e && *e != '0';
    if (q4s8_state) fprintf(stderr, "llms: q4s8 (Q4L group scales as one byte: rows of 17K/32 bytes; the *_q4s8 payloads and dense source)\n"); } return q4s8_state; }
static inline uint64_t q4l_rowb(uint64_t k) { return q4s8_on() ? k / 32u * 17u : k / 16u * 9u; }
/* llms DENSE_SWR (apply_swr.py; swr / swr2 / swr3 jobs 11-03): every two-row Q4L dense matvec (K % 32 == 0, K >= 512) as the SWAR integer body -- x at 5 bits a 32-group, both rows packed in one 32-bit word, one integer multiply-add a weight. Bench joules x0.87-0.93 of rsgf at NR0 8, x0.77-0.80 of the duals' kxh body, x0.92 of the head's; priced x at 5 bits on every two-row dense input at session KL +0.0018. Off unless LLMS_DS4_DENSE_SWR=1; ALT swr (per call). Needs make_swr_source.py's kernels in DS4_METAL_DENSE_SOURCE and the Q4S8E rows. */


static int swr_state = -1, swr_mode; static uint64_t swr_calls[3];   /* generic two-row matvecs, attention output_b, duals declined; swr_mode 1 xprep, 2 xprep2 */
static id<MTLComputePipelineState> swr_prep, swr_mv[4];   /* g1_b, g1_f, g2_b, g2_f */
static id<MTLBuffer> swr_ring[8]; static unsigned swr_slot;
static int swr_on(void) {
    if (swr_state < 0) {
        const char *e = getenv("LLMS_DS4_DENSE_SWR"); swr_state = e && *e && *e != '0'; swr_mode = swr_state ? (atoi(e) == 5 ? 5 : atoi(e) == 4 ? 4 : atoi(e) == 3 ? 3 : atoi(e) == 2 ? 2 : 1) : 0;   /* 5: the head only (09:4x) */   /* llms DENSE_SWR 2: the parallel pre-pass; 3: the same with the duals kept fused (09:0x) */
        if (swr_state) {
            static const char *kn[4] = { "kernel_llms_swr_g1_b", "kernel_llms_swr_g1_f", "kernel_llms_swr_g2_b", "kernel_llms_swr_g2_f" };
            if (!q4s8_on() || !has_kernel(swr_mode >= 2 ? "kernel_llms_swr_xprep2" : "kernel_llms_swr_xprep")) {
                fprintf(stderr, "llms dense swr: REFUSING -- %s; a switch not in force must not read as a null\n",
                        !q4s8_on() ? "the Q4L rows are not Q4S8E" : "the dense source lacks kernel_llms_swr_xprep"); abort(); }
            swr_prep = ds4_gpu_get_mul_mv_pipeline(swr_mode >= 2 ? "kernel_llms_swr_xprep2" : "kernel_llms_swr_xprep", swr_mode >= 2 ? 4 : 1);
            for (int i = 0; i < 4; i++) swr_mv[i] = ds4_gpu_get_mul_mv_pipeline(kn[i], 4);
            if (!swr_prep || !swr_mv[0] || !swr_mv[1] || !swr_mv[2] || !swr_mv[3]) { fprintf(stderr, "llms dense swr: REFUSING -- a SWAR pipeline failed to build\n"); abort(); }
            fprintf(stderr, "llms: dense swr %d (two-row dense matvecs as SWAR integer bodies: x at 5 bits a 32-group, both rows in one 32-bit word; the pre-pass %s; ALT swr)\n",
                    swr_mode, swr_mode >= 2 ? (swr_mode == 4 ? "one simdgroup a group; one-lane shapes with N >= 2048 only; the duals fused; producers on" : swr_mode == 3 ? "one simdgroup a group; the duals kept fused" : "one simdgroup a group") : "one thread a group");
            atexit_b(^{ fprintf(stderr, "llms dense swr: %llu generic two-row matvecs, %llu attention output_b, %llu duals declined\n",
                                (unsigned long long)swr_calls[0], (unsigned long long)swr_calls[1], (unsigned long long)swr_calls[2]); });
        }
    }
    return swr_state;
}
static int swr_active(void) { return swr_on() && !llms_alt_off("swr"); }
