static dense4_entry *drafter_dense4_table; static int drafter_dense4_count = -1; static uint64_t drafter_dense4_hits;
static const char *dsp_q8cls_alt(const char *name) {   /* llms DSP_Q8CLS (apply_dsp_q8cls.py): the drafter's 4-bit entries named by class */
