    unsigned long long ab, of; unsigned k, n; char name[512], line[1024];
    while (fgets(line, sizeof line, f)) {
        if (sscanf(line, "%llu %llu %u %u %511s", &ab, &of, &k, &n, name) < 5) continue;
        if (drafter_dense4_count == cap) { cap *= 2; drafter_dense4_table = realloc(drafter_dense4_table, (size_t)cap * sizeof *drafter_dense4_table); }
        dense4_entry e = { ab, of, k, n }; strncpy(e.alt, dsp_q8cls_alt(name), sizeof e.alt - 1); drafter_dense4_table[drafter_dense4_count++] = e;   /* llms DSP_Q8CLS */
    }
