                                            if (q8) fprintf(stderr, "llms: dsp q8 (the drafter's dense tensors on the support file's own type; ALT 'dspq8' off = the 4-bit copy)\n"); }
          if (q8 && !llms_alt_off("dspq8")) return NULL; }
        if (drafter_dense4_count < 0) load_drafter_dense4_table();
        int lo = 0, hi = drafter_dense4_count - 1;
        while (lo <= hi) { const int mid = (lo + hi) / 2;
            if (drafter_dense4_table[mid].abs == abs) { drafter_dense4_hits++; return &drafter_dense4_table[mid]; }
            if (drafter_dense4_table[mid].abs < abs) lo = mid + 1; else hi = mid - 1; }
        return NULL;
    }
    int lo = 0, hi = dense4_count - 1;
    while (lo <= hi) {
        const int mid = (lo + hi) / 2;
        if (dense4_table[mid].abs == abs) return &dense4_table[mid];
        if (dense4_table[mid].abs < abs) lo = mid + 1; else hi = mid - 1;
    }
