    if (dense4_bypass || k != 1280u || n != 32768u) return 0;
    for (int i = 0; i < ragged_q_regn; i++) if (ragged_q_reg[i] == q_b_abs) return ragged_q_regr[i];
    if (dense4_count < 0) load_dense4_table();
    if (dense4_count <= 0) return 0;
    const dense4_entry *e1 = find_dense4(q_b_abs + 1u); uint32_t r = 0;   /* layout L2: stage 1 under key + 1 */
    if (e1) {
        const dense4_entry *e2 = find_dense4(q_b_abs + 2u); r = e1->n;
        if (!(e1->k == 1280u && r >= 256u && r < 1280u && r % 256u == 0u && e2 && e2->k == r && e2->n == 32768u)) {
            fprintf(stderr, "llms ragged q: the entry at %llu + 1 is %ux%u (stage 2 at + 2: %s), not K 1280 x N r with a K r x N 32768 partner (r a multiple of 256 below 1280)\n", (unsigned long long)q_b_abs, e1->k, e1->n, e2 ? "present" : "missing");
            abort();
        }
        if (!ragged_q_on()) { fprintf(stderr, "llms ragged q: the Q4L index holds a rank-%u q_b at %llu but LLMS_DS4_RAGGED_Q is not set\n", r, (unsigned long long)q_b_abs); abort(); }
        { const char *aw = getenv("LLMS_DS4_ALTW");   /* llms RAGGED_Q ALT 'ragq': the shipped entry must exist under the key itself (q_keep.idx), or the alternation would read the Q8_0 original through a wrong table entry */
          if (aw && strstr(aw, "ragq")) { const dense4_entry *e3 = find_dense4(q_b_abs); if (!(e3 && e3->k == 1280u && e3->n == 32768u)) { fprintf(stderr, "llms ragged q: ALTW names ragq but the shipped entry at %llu (K 1280 x N 32768) is missing from the index (use q_keep.idx)\n", (unsigned long long)q_b_abs); abort(); } } }
    }
    if (ragged_q_regn < 64) { ragged_q_reg[ragged_q_regn] = q_b_abs; ragged_q_regr[ragged_q_regn] = r; ragged_q_regn++; }
    return r;
}
/* llms Q4I (apply_q4i.py): the interleaved two-vector matvec's side file; index lines 'abs off k n S gr name' */
typedef struct { uint64_t abs; uint32_t k, n, S, gr; __unsafe_unretained id<MTLBuffer> buf; uint64_t soff; } interleaved_entry;
static interleaved_entry *interleaved_table; static int interleaved_count = -1, interleaved_canary, interleaved_hooks = 3; static NSMutableArray *interleaved_buffers;
static uint64_t interleaved_two_row_calls, interleaved_grouped_calls; static id<MTLComputePipelineState> interleaved_pipeline, interleaved_convert_pipeline;
static int dense_dup_state = -1; static uint64_t dense_dup_issues;   /* llms DENSE_DUP (apply_q4i_dup.py) */
static int dense_dup_on(void) { if (dense_dup_state < 0) { const char *e = getenv("LLMS_DS4_DENSE_DUP"); dense_dup_state = e && *e == '1';
    if (dense_dup_state) { fprintf(stderr, "llms: DENSE_DUP -- attn_q_b / output_a matvecs issued twice (the DUP method)\n"); atexit_b(^{ fprintf(stderr, "llms dense dup: %llu second issues\n", (unsigned long long)dense_dup_issues); }); } }
    return dense_dup_state; }
static int interleaved_on(void) {
    if (interleaved_count >= 0) return interleaved_count > 0;
    interleaved_count = 0; const char *idx = getenv("LLMS_DS4_Q4I");
    if (!idx || !*idx || !strcmp(idx, "0")) return 0;
    if (!has_kernel("kernel_llms_q4i_mv2")) { fprintf(stderr, "llms: LLMS_DS4_Q4I ignored: the dense source lacks kernel_llms_q4i_mv2\n"); return 0; }
    FILE *f = fopen(idx, "r"); if (!f) { fprintf(stderr, "llms: q4i index %s cannot be opened\n", idx); return 0; }
    char path[4096], line[1024], name[512]; if (!fgets(path, sizeof path, f)) { fclose(f); return 0; } path[strcspn(path, "\r\n")] = 0;
    int cap = 128; interleaved_table = calloc((size_t)cap, sizeof *interleaved_table); unsigned long long ab, of; unsigned k, n, S, gr;
    uint64_t *offv = calloc((size_t)cap, sizeof(uint64_t));
    while (fgets(line, sizeof line, f)) {
        if (sscanf(line, "%llu %llu %u %u %u %u %511s", &ab, &of, &k, &n, &S, &gr, name) < 7) continue;
        if (interleaved_count == cap) { cap *= 2; interleaved_table = realloc(interleaved_table, (size_t)cap * sizeof *interleaved_table); offv = realloc(offv, (size_t)cap * sizeof(uint64_t)); }
        offv[interleaved_count] = of; interleaved_table[interleaved_count++] = (interleaved_entry){ ab, k, n, S, gr, nil, 0 };
    }
    fclose(f);
    const int fd = open(path, O_RDONLY); const off_t fsz = fd < 0 ? -1 : lseek(fd, 0, SEEK_END);
    if (fd < 0 || fsz <= 0) { fprintf(stderr, "llms: q4i file %s cannot be opened\n", path); interleaved_count = 0; free(offv); return 0; }
    const uint64_t len = ((uint64_t)fsz + 16383u) & ~(uint64_t)16383u;
    void *mp = mmap(NULL, (size_t)len, PROT_READ, MAP_SHARED, fd, 0); close(fd);
    if (mp == MAP_FAILED) { fprintf(stderr, "llms: q4i mmap failed\n"); interleaved_count = 0; free(offv); return 0; }
    interleaved_buffers = [NSMutableArray arrayWithCapacity:(NSUInteger)interleaved_count]; uint64_t wrapped = 0;
    for (int e = 0; e < interleaved_count; e++) {
        interleaved_entry *q = &interleaved_table[e]; const uint64_t cb = (uint64_t)q->n * q->k / 2u, sb = (uint64_t)q->n * (q->k / 32u) * 2u;
        if ((offv[e] & 16383u) || q->k % 32u || q->n % 32u || q->S < 1u || q->S > 16u || offv[e] + cb + sb > (uint64_t)fsz) { fprintf(stderr, "llms: q4i entry %d malformed\n", e); interleaved_count = 0; free(offv); return 0; }
        const uint64_t blen = (cb + sb + 16383u) & ~(uint64_t)16383u;
        id<MTLBuffer> b = [g_device newBufferWithBytesNoCopy:(uint8_t *)mp + offv[e] length:(NSUInteger)blen options:MTLResourceStorageModeShared deallocator:nil];
        if (!b) { fprintf(stderr, "llms: q4i buffer %d failed\n", e); interleaved_count = 0; free(offv); return 0; }
        [interleaved_buffers addObject:b]; q->buf = b; q->soff = cb; wrapped += blen;
    }
    free(offv);
    interleaved_pipeline = ds4_gpu_get_mul_mv_pipeline("kernel_llms_q4i_mv2", 1); interleaved_convert_pipeline = ds4_gpu_get_mul_mv_pipeline("kernel_llms_f32_to_f16_rows", 1);
    if (!interleaved_pipeline || !interleaved_convert_pipeline) { fprintf(stderr, "llms: q4i pipelines missing\n"); interleaved_count = 0; return 0; }
    { const char *c = getenv("LLMS_DS4_Q4I_CANARY"); interleaved_canary = c && *c == '1'; }
    { const char *hk = getenv("LLMS_DS4_Q4I_HOOKS"); interleaved_hooks = hk && *hk ? atoi(hk) & 3 : 3; if (interleaved_hooks != 3) fprintf(stderr, "llms: q4i hooks mask %d (1 = attn_q_b, 2 = output_a)\n", interleaved_hooks); }
    fprintf(stderr, "llms: q4i %s: %d tensors, %.2f GB wrapped (two-row attn_q_b / grouped output_a on the interleaved layout)%s\n", path, interleaved_count, (double)wrapped / 1e9,
            interleaved_canary ? " -- CANARY: the last block of every row skipped" : "");
    atexit_b(^{ fprintf(stderr, "llms q4i: %llu two-row matvecs + %llu grouped output_a on the interleaved layout\n", (unsigned long long)interleaved_two_row_calls, (unsigned long long)interleaved_grouped_calls); });
    return 1;
}
static const interleaved_entry *find_interleaved(uint64_t abs) {
    if (dense4_bypass) return NULL;   /* the drafter's table: its offsets index another file */
    for (int e = 0; e < interleaved_count; e++) if (interleaved_table[e].abs == abs) return &interleaved_table[e];
    return NULL;
}
/* one two-vector Q4I matvec: x_half holds the two rows (token stride xs halves); y = 2 x N floats */
static void dispatch_interleaved(id<MTLComputeCommandEncoder> enc, const interleaved_entry *ie, id<MTLBuffer> xh, NSUInteger xoff, uint32_t xs, id<MTLBuffer> yb, NSUInteger yoff, uint32_t rb) {
    struct { uint32_t K, N, gr, xs, rb, canary; } ia = { ie->k, ie->n, ie->gr, xs, rb, (uint32_t)interleaved_canary };
    [enc setComputePipelineState:interleaved_pipeline];
    [enc setBytes:&ia length:sizeof ia atIndex:0];
    [enc setBuffer:ie->buf offset:0 atIndex:1];
    [enc setBuffer:ie->buf offset:(NSUInteger)ie->soff atIndex:2];
    [enc setBuffer:xh offset:xoff atIndex:3];
    [enc setBuffer:yb offset:yoff atIndex:4];
    [enc setThreadgroupMemoryLength:(NSUInteger)(ie->S > 1u ? ie->S * 32u * 2u * sizeof(float) : 16u) atIndex:0];
    [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)(ie->n / 32u), 1, 1) threadsPerThreadgroup:MTLSizeMake((NSUInteger)(32u * ie->S), 1, 1)];
    if (dense_dup_on()) { [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)(ie->n / 32u), 1, 1) threadsPerThreadgroup:MTLSizeMake((NSUInteger)(32u * ie->S), 1, 1)]; dense_dup_issues++; }
}
/* llms DSP41_SHORT (apply_short.py): the drafter's head over a shortlist of vocabulary rows (kernel_llms_q4l_mv_ix); * ids[0..n) are copied into a shared buffer as they grow (appends only between drafter batches). Returns 0 when it cannot run (the caller * then runs the full head). */
static uint64_t q4l_short_calls;
int ds4_gpu_llms_q4l_short(ds4_gpu_tensor *out, uint64_t weight_abs, uint32_t k, uint32_t n_out, const ds4_gpu_tensor *x, const int32_t *ids, uint32_t n_ids) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (llms_alt_off("short") || n_ids == 0 || n_ids > n_out) return 0;
    if (dense4_count < 0) load_dense4_table();
    const dense4_entry *qe = dense4_count > 0 ? find_dense4(weight_abs) : NULL;
    if (!qe || qe->k != k || qe->n != n_out || (ds4_gpu_tensor_offset(x) & 15u) != 0) return 0;
    static id<MTLBuffer> idb; static uint32_t synced; static id<MTLComputePipelineState> qp; static int tried;
    if (!tried) { tried = 1; qp = ds4_gpu_get_mul_mv_pipeline("kernel_llms_q4l_mv_ix", 2);
                  idb = [g_device newBufferWithLength:(NSUInteger)n_out * sizeof(int32_t) options:MTLResourceStorageModeShared];
                  if (!qp) llms_strict_after(fprintf(stderr, "llms: dsp41 short -- kernel_llms_q4l_mv_ix missing from the dense source (the full head runs)\n"), "kernel_llms_q4l_mv_ix missing");
                  atexit_b(^{ fprintf(stderr, "llms dsp41 short: %llu shortlist heads (kernel_llms_q4l_mv_ix)\n", (unsigned long long)q4l_short_calls); }); }
    if (!qp || !idb) return 0;
    if (n_ids < synced) synced = 0;
    if (n_ids > synced) { memcpy((int32_t *)[idb contents] + synced, ids + synced, (size_t)(n_ids - synced) * sizeof(int32_t)); synced = n_ids; }
    @autoreleasepool {
        ds4_gpu_q8_0_matvec_args qa = ds4_gpu_make_q8_0_mv_args(k, n_ids);
        qa.nb00 = 1; qa.nb01 = q4l_rowb(k); qa.nb02 = qa.nb01 * n_out; qa.nb03 = qa.nb02; qa.nr0 = 4;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:qp];
        [enc setBytes:&qa length:sizeof(qa) atIndex:0];
        [enc setBuffer:qe->buf offset:(NSUInteger)qe->inner atIndex:1];
        [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:2];
        [enc setBuffer:ds4_gpu_tensor_buffer(out) offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc setBuffer:idb offset:0 atIndex:4];
        [enc setThreadgroupMemoryLength:4u * 32u * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_ids + 3u) / 4u, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 2, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned, "llms dsp41 short head")) return 0;
    }
