    return 1;
}
/* llms Q4L_DUAL (apply_q4l_dual.py): A and B on one input in one dispatch, + an optional HC split threadgroup */
static uint64_t q4l_dual_calls, q4l_dual_splits;
int ds4_gpu_llms_q4l_dual(ds4_gpu_tensor *out_a, uint64_t wa_abs, uint32_t n_a, ds4_gpu_tensor *out_b, uint64_t wb_abs, uint32_t n_b,
                          const ds4_gpu_tensor *x, uint32_t k, ds4_gpu_tensor *split, const ds4_gpu_tensor *mix, const void *model_map,
                          uint64_t model_size, uint64_t scale_off, uint64_t base_off, uint32_t iters, float eps, int canary) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (dense4_count < 0) load_dense4_table();
    if (dense4_count <= 0) return 0;
    const dense4_entry *ea = find_dense4(wa_abs), *eb = find_dense4(wb_abs);
    if (!ea || !eb || llms_alt_off(ea->alt) || llms_alt_off(eb->alt)) return 0;
    if (ea->k != k || eb->k != k || ea->n != n_a || eb->n != n_b) return 0;
    if ((ds4_gpu_tensor_offset(x) & 15u) != 0) return 0;
    if (!(mvb16_on(0) && !llms_alt_off("mvb"))) return 0;   /* the bf16-store kernel only, as ds41_matmul(round) takes it */
    static int exit_report_registered; if (!exit_report_registered++) atexit_b(^{ fprintf(stderr, "llms q4l dual: %llu dual dispatches, %llu with an HC split\n", (unsigned long long)q4l_dual_calls, (unsigned long long)q4l_dual_splits); });
    const int16_t qnsg = k <= 1536u ? 1 : 2;
