    if (!qp) { static int w; if (!w++) fprintf(stderr, "llms: kernel_llms_q4l_mv_b2 missing (DS4_METAL_DENSE_SOURCE must name the *_dual source) -- Q4L_DUAL off\n"); return 0; }
    id<MTLBuffer> sb = nil, bb = nil; uint64_t si = 0, bi = 0;
    if (split) {
        sb = ds4_gpu_wrap_model_range(model_map, model_size, scale_off, 3u * sizeof(float), &si);
        bb = ds4_gpu_wrap_model_range(model_map, model_size, base_off, 24u * sizeof(float), &bi);
        if (!sb || !bb) return 0;
    }
    @autoreleasepool {
        ds4_gpu_q8_0_matvec_args qa = ds4_gpu_make_q8_0_mv_args(k, n_a), qb = ds4_gpu_make_q8_0_mv_args(k, n_b);
        qa.nb00 = 1; qa.nb01 = q4l_rowb(k); qa.nb02 = qa.nb01 * n_a; qa.nb03 = qa.nb02; qa.nr0 = 4;
        qb.nb00 = 1; qb.nb01 = q4l_rowb(k); qb.nb02 = qb.nb01 * n_b; qb.nb03 = qb.nb02; qb.nr0 = 4;
        struct { uint32_t ga, gb, sk, canary; int32_t iters; float eps; } p = { (n_a + 3u) / 4u, (n_b + 3u) / 4u, split ? 1u : 0u, canary ? 1u : 0u, (int32_t)iters, eps };
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:qp];
        [enc setBytes:&qa length:sizeof(qa) atIndex:0];
        [enc setBuffer:ea->buf offset:(NSUInteger)ea->inner atIndex:1];
        [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:2];
        [enc setBuffer:ds4_gpu_tensor_buffer(out_a) offset:ds4_gpu_tensor_offset(out_a) atIndex:3];
        [enc setBytes:&qb length:sizeof(qb) atIndex:4];
        [enc setBuffer:eb->buf offset:(NSUInteger)eb->inner atIndex:5];
        [enc setBuffer:ds4_gpu_tensor_buffer(out_b) offset:ds4_gpu_tensor_offset(out_b) atIndex:6];
        [enc setBytes:&p length:sizeof(p) atIndex:7];
