            [enc setBuffer:sb offset:(NSUInteger)si atIndex:9];
            [enc setBuffer:bb offset:(NSUInteger)bi atIndex:10];
            [enc setBuffer:ds4_gpu_tensor_buffer(split) offset:ds4_gpu_tensor_offset(split) atIndex:11];
        } else {
            [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:8];   /* unread placeholders */
            [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:9];
            [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:10];
            [enc setBuffer:ds4_gpu_tensor_buffer(out_a) offset:ds4_gpu_tensor_offset(out_a) atIndex:11];
        }
        [enc setThreadgroupMemoryLength:4u * 32u * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)(p.ga + p.gb + p.sk), 1, 1) threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)qnsg, 1)];
