    return 1;
}

/* llms ACT_STATS (apply_act_stats.py): per-column sum of x^2 per dense weight, written at exit */
typedef struct { uint64_t abs; uint32_t k; uint32_t calls; __unsafe_unretained id<MTLBuffer> acc; } act_stats_entry;
static act_stats_entry act_stats[512]; static int act_stats_count = 0, act_stats_state = -1; static NSMutableArray *act_stats_buffers; static const char *act_stats_path;
static void dump_act_stats(void) {
    FILE *f = fopen(act_stats_path, "wb"); if (!f) { fprintf(stderr, "llms: act stats: cannot write %s\n", act_stats_path); return; }
    const uint32_t n = (uint32_t)act_stats_count; fwrite("ACTS", 1, 4, f); fwrite(&n, 4, 1, f);
    for (int i = 0; i < act_stats_count; i++) {
        const act_stats_entry *e = &act_stats[i];
        fwrite(&e->abs, 8, 1, f); fwrite(&e->k, 4, 1, f); fwrite(&e->calls, 4, 1, f); fwrite([e->acc contents], 4, e->k, f);
    }
    fclose(f); fprintf(stderr, "llms act stats: %d weights written to %s\n", act_stats_count, act_stats_path);
}
static void note_act_stats(uint64_t abs, id<MTLCommandBuffer> cb, id<MTLBuffer> xbuf, NSUInteger xoff, uint32_t k) {
    if (act_stats_state < 0) {
        act_stats_path = getenv("LLMS_DS4_ACT_STATS"); act_stats_state = act_stats_path && *act_stats_path ? 1 : 0;
        if (act_stats_state) { act_stats_buffers = [NSMutableArray array]; atexit(dump_act_stats);
                             fprintf(stderr, "llms: act stats on (per-column x^2 of the one-token dense matvecs -> %s)\n", act_stats_path); }
    }
    if (!act_stats_state || !cb || !xbuf || k == 0) return;
    int i = 0; while (i < act_stats_count && act_stats[i].abs != abs) i++;
    if (i == act_stats_count) {
        if (act_stats_count == 512) return;
        id<MTLBuffer> b = [g_device newBufferWithLength:(NSUInteger)k * 4u options:MTLResourceStorageModeShared];
        if (!b) return;
        memset([b contents], 0, (size_t)k * 4u); [act_stats_buffers addObject:b];
        act_stats[i] = (act_stats_entry){ abs, k, 0, b }; act_stats_count++;
    }
    if (act_stats[i].k != k) return;
    id<MTLComputePipelineState> p = ds4_gpu_get_mul_mv_pipeline("kernel_llms_act_sq_acc", 1);
    if (!p) { fprintf(stderr, "llms: act stats kernel missing from DS4_METAL_DENSE_SOURCE\n"); act_stats_state = 0; return; }
    ds4_gpu_q8_0_matvec_args a = ds4_gpu_make_q8_0_mv_args(k, 1);
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:p];
    [enc setBytes:&a length:sizeof(a) atIndex:0];
    [enc setBuffer:xbuf offset:xoff atIndex:1];
    [enc setBuffer:xbuf offset:xoff atIndex:2];
    [enc setBuffer:act_stats[i].acc offset:0 atIndex:3];
    [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)k + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    act_stats[i].calls++;
}

static int llms_alt_off(const char *name);
static uint64_t k4h_calls;   /* llms K4H (apply_k4h.py) */
static int k4h_mode(void) {
    static int q4l_k4h_value = -1;
    if (q4l_k4h_value < 0) { const char *e = getenv("LLMS_DS4_K4H"); q4l_k4h_value = e && *e ? atoi(e) : 5; if (q4l_k4h_value < 0 || q4l_k4h_value > 5) q4l_k4h_value = 0;   /* llms K4H: 5 adopted, the compiled default since 10-27; 1-4 the half twins (P39: ~null); 0 the path before K4H */
                   if (q4l_k4h_value && q4l_k4h_value != 5 && !has_kernel("kernel_llms_q4l_mv_k4_r4_bxhh")) { fprintf(stderr, "llms: LLMS_DS4_K4H ignored: DS4_METAL_DENSE_SOURCE lacks the _bxhh twins\n"); q4l_k4h_value = 0; }
                   if (q4l_k4h_value && q4l_k4h_value != 5) { fprintf(stderr, "llms: k4h %d (the half-pipeline matvec twins at %s)\n", q4l_k4h_value, q4l_k4h_value == 1 ? "3-4 token rows" : q4l_k4h_value == 2 ? "2-4 token rows" : q4l_k4h_value == 3 ? "3-4 token rows + 2 rows at in_dim >= 8192" : q4l_k4h_value == 4 ? "3-4 token rows, the 3-row b path at 4 rows per threadgroup" : "no twin: the 3-row b path at 4 rows per threadgroup on the fp32 bodies");
                              atexit_b(^{ fprintf(stderr, "llms k4h: %llu matvecs on the half-pipeline twins\n", (unsigned long long)k4h_calls); }); } }
    return q4l_k4h_value;
}
static uint64_t k4h_nr4_calls;
