                    const uint64_t tile_chunks = (pad32_now ? pad64_rows / 32u : ((n_tok > 64 || (n_tok == 64 && g64c_on())) ? (uint64_t)n_tok / 32u : 1u));   /* llms PAD64: one 32-token call per 32-row chunk; C32CHUNK: 96 / 128 tokens */
                    for (uint64_t tile_chunk = 0; tile_chunk < tile_chunks; tile_chunk++) {
                    [tile_encoder setComputePipelineState:pl32];
                    [tile_encoder setBytes:&ha length:sizeof(ha) atIndex:0];
                    [tile_encoder setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
                    [tile_encoder setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) + (NSUInteger)(tile_chunk * 32u * in_dim * sizeof(float)) atIndex:2];
                    [tile_encoder setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) + (NSUInteger)(tile_chunk * 32u * out_dim * sizeof(float)) atIndex:3];
                    const NSUInteger sgmt32x_threadgroup_bytes = (sgmt32x_mode_now >= 2 || sgmt32x_mode_now == -1) ? MAX(simdgroups_used * nr * 64u, (simdgroups_used / 2u) * nr * 128u) : nsg * nr * 128u;   /* llms SGMT32X */
                    [tile_encoder setThreadgroupMemoryLength:sgmt32x_mode_now ? sgmt32x_threadgroup_bytes : t32_mode2 ? nsg * (nr * 32u * 2u + 2048u) : nsg * (nr * 32u * 2u + 2048u) + nsg * nr * 32u * 4u atIndex:0];
                    [tile_encoder dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + nr - 1u) / nr, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, sgmt32x_mode_now ? simdgroups_used : nsg, 1)];
                    }
                    ds4_gpu_end_compute_encoder(cb, tile_encoder);
                    if (!ds4_gpu_finish_command_buffer(cb, owned, "Q8_0 tensor mul_mv sgmt32")) return 0;
                    if (t32_bf16_now) { t32_rounded = 1; t32_bf16_calls++; }   /* llms T32_BF16 */
                    return 1;
                }
            }
        }
        {   /* llms SGMH32 (apply_ds4_sgmh32.py): 32 tokens as two 16-token groups on the half tiles */
            static int sgmh32_state = -1; if (sgmh32_state < 0) { const char *e = getenv("LLMS_DS4_SGMH32"); sgmh32_state = e && *e && *e != '0'; if (sgmh32_state) fprintf(stderr, "llms: sgmh32 (32-token Q8 matvecs as two 16-token half-tile groups)\n"); }
            if (sgmh32_state && ext_sgmh16_on() && !llms_alt_off("sgmh32") && n_tok == 32 && (in_dim % 32u) == 0 && (out_dim % 32u) == 0 && out_dim >= 256u) {
                const int nsg = out_dim <= 1280u ? 8 : 4, nrt = out_dim <= 2304u ? 2 : 4;
                sgmh_args ha = { .K = (int32_t)in_dim, .rows = (int32_t)out_dim, .n_tok = 16, .n_groups = 2, .row_bytes = row_bytes, .group_bytes = 0,
                                      .x_tok_stride = in_dim * sizeof(float), .x_group_stride = 16u * in_dim * sizeof(float),
                                      .dst_tok_stride = out_dim * sizeof(float), .dst_group_stride = 16u * out_dim * sizeof(float) };
                id<MTLComputeCommandEncoder> sgmh16_encoder = ds4_gpu_compute_encoder(cb);
                if (encode_sgmh16(sgmh16_encoder, nsg, nrt, ha, wbuf, (NSUInteger)inner_offset, xbuf, ds4_gpu_tensor_offset(x), outbuf, ds4_gpu_tensor_offset(out))) {
                    ds4_gpu_end_compute_encoder(cb, sgmh16_encoder);
                    if (!ds4_gpu_finish_command_buffer(cb, owned, "Q8_0 tensor mul_mv sgmh32")) return 0;
                    return 1;
                }
                ds4_gpu_end_compute_encoder(cb, sgmh16_encoder);
            }
        }
        const uint64_t mv_ext_max_tokens =
            ds4_gpu_env_u64("DS4_METAL_Q8_MV_EXT_MAX_TOKENS", 16u, 2u, 128u);
        if (n_tok <= mv_ext_max_tokens && (in_dim % 128u) == 0) {
            const uint64_t pad16_tokens = pad16_rows(n_tok, in_dim * sizeof(float), out_dim * sizeof(float), xbuf, ds4_gpu_tensor_offset(x), outbuf, ds4_gpu_tensor_offset(out));   /* llms PAD16 */
            if (ext_sgmh16_on() && !llms_alt_off("sgmh16") && pad16_tokens == 16 && (in_dim % 32u) == 0 && (out_dim % 32u) == 0 && out_dim >= 256u) {   /* llms EXT_SGMH16; ALT; llms PAD16 */
                const int nsg = out_dim <= 1280u ? 8 : 4, nrt = out_dim <= 2304u ? 2 : 4;
                sgmh_args ha = { .K = (int32_t)in_dim, .rows = (int32_t)out_dim, .n_tok = 16, .n_groups = 1, .row_bytes = row_bytes, .group_bytes = 0,
                                      .x_tok_stride = in_dim * sizeof(float), .x_group_stride = 0, .dst_tok_stride = out_dim * sizeof(float), .dst_group_stride = 0 };
                id<MTLComputeCommandEncoder> sgmh16_encoder = ds4_gpu_compute_encoder(cb);
                if (encode_sgmh16(sgmh16_encoder, nsg, nrt, ha, wbuf, (NSUInteger)inner_offset, xbuf, ds4_gpu_tensor_offset(x), outbuf, ds4_gpu_tensor_offset(out))) {
                    ds4_gpu_end_compute_encoder(cb, sgmh16_encoder);
                    if (!ds4_gpu_finish_command_buffer(cb, owned, "Q8_0 tensor mul_mv sgmh16")) return 0;
                    return 1;
                }
                ds4_gpu_end_compute_encoder(cb, sgmh16_encoder);
            }
            if (ext_sgmh_on() && !llms_alt_off("sgmh") && pad16_tokens == 8 && (in_dim % 32u) == 0 && (out_dim % 32u) == 0 && out_dim >= 256u) {   /* llms EXT_SGMH; ALT; llms PAD16 */
                const int nsg = out_dim <= 2304u ? 8 : (in_dim >= 4096u ? 8 : 2), nrt = out_dim <= 2304u ? 2 : 4;
                sgmh_args ha = { .K = (int32_t)in_dim, .rows = (int32_t)out_dim, .n_tok = 8, .n_groups = 1, .row_bytes = row_bytes, .group_bytes = 0,
                                      .x_tok_stride = in_dim * sizeof(float), .x_group_stride = 0, .dst_tok_stride = out_dim * sizeof(float), .dst_group_stride = 0 };
                if (ext_sgmh_on() < 0) ha.x_tok_stride /= 2;   /* canary */
                id<MTLComputeCommandEncoder> sgmh16_encoder = ds4_gpu_compute_encoder(cb);
                if (encode_sgmh(sgmh16_encoder, nsg, nrt, ha, wbuf, (NSUInteger)inner_offset, xbuf, ds4_gpu_tensor_offset(x), outbuf, ds4_gpu_tensor_offset(out))) {
                    ds4_gpu_end_compute_encoder(cb, sgmh16_encoder);
                    sgmh_calls++;
                    if (!ds4_gpu_finish_command_buffer(cb, owned, "Q8_0 tensor mul_mv sgmh")) return 0;
                    return 1;
                }
                ds4_gpu_end_compute_encoder(cb, sgmh16_encoder);
            }
            if (ext_sgm16_on() && pad16_tokens == 16 && (in_dim % 32u) == 0 && (out_dim % 8u) == 0) {   /* llms EXT_SGM16: the head at 16 tokens; llms PAD16 */
                const int nsg16 = out_dim <= 1280u ? 8 : 4;
                id<MTLComputePipelineState> sgm16_pipeline = ds4_gpu_get_pipeline_or_die(nsg16 == 8 ? "kernel_llms_mul_mv_q8_0_f32_sgm32_16k_s8" : "kernel_llms_mul_mv_q8_0_f32_sgm32_16k_s4");
                if (!sgm16_pipeline) return 0;
                ds4_gpu_mul_mv_ext_args sgm16_args = ds4_gpu_make_mv_ext_args(in_dim, out_dim, pad16_tokens, 34, row_bytes);   /* llms PAD16 */
                if (ext_sgm16_on() < 0) sgm16_args.nb11 /= 2;   /* canary */
                id<MTLComputeCommandEncoder> sgm16_encoder = ds4_gpu_compute_encoder(cb);
                [sgm16_encoder setComputePipelineState:sgm16_pipeline];
                [sgm16_encoder setBytes:&sgm16_args length:sizeof(sgm16_args) atIndex:0];
                [sgm16_encoder setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
                [sgm16_encoder setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
                [sgm16_encoder setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
                [sgm16_encoder setThreadgroupMemoryLength:(NSUInteger)((3 * nsg16 * 256 + nsg16 * 128) * 4) atIndex:0];
                [sgm16_encoder dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + 7u) / 8u, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)nsg16, 1)];
                ds4_gpu_end_compute_encoder(cb, sgm16_encoder);
                sgm16_calls++;
                if (!ds4_gpu_finish_command_buffer(cb, owned, "Q8_0 tensor mul_mv sgm16")) return 0;
                return 1;
            }
            if (ext_sgm_on() && !llms_alt_off("sgm") && pad16_tokens == 8 && (in_dim % 32u) == 0 && (out_dim % 8u) == 0) {   /* llms EXT_SGM; ALT; llms PAD16 */
                const int sgm = ext_sgm_on();
                const bool rsplit = sgm == 3 || (sgm != 2 && out_dim >= 4096u);   /* bench 12:4x-12:5x: row split for down / q_b, K split for gate/up / q_a / kv */
                const int nsg = rsplit ? (out_dim >= 16384u ? 8 : 4) : 8;
                static char sgm_kernel_name[72];
                snprintf(sgm_kernel_name, sizeof sgm_kernel_name, "kernel_llms_mul_mv_q8_0_f32_sgm32%c_s%d", rsplit ? 'r' : 'k', nsg);
                id<MTLComputePipelineState> sgm_pipeline = ds4_gpu_get_pipeline_or_die(sgm_kernel_name);
                if (!sgm_pipeline) return 0;
                ds4_gpu_mul_mv_ext_args sgm_args = ds4_gpu_make_mv_ext_args(in_dim, out_dim, pad16_tokens, 34, row_bytes);   /* llms PAD16 */
                if (sgm < 0) sgm_args.nb11 /= 2;   /* canary */
                const NSUInteger rows_per_tg = rsplit ? 8u * (NSUInteger)nsg : 8u;
                id<MTLComputeCommandEncoder> sgm_encoder = ds4_gpu_compute_encoder(cb);
                [sgm_encoder setComputePipelineState:sgm_pipeline];
                [sgm_encoder setBytes:&sgm_args length:sizeof(sgm_args) atIndex:0];
                [sgm_encoder setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
                [sgm_encoder setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
                [sgm_encoder setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
                [sgm_encoder setThreadgroupMemoryLength:(NSUInteger)((2 * nsg * 256 + nsg * 64) * 4) atIndex:0];   /* the 32-k form */
                [sgm_encoder dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + rows_per_tg - 1u) / rows_per_tg, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)nsg, 1)];
                ds4_gpu_end_compute_encoder(cb, sgm_encoder);
                sgm_calls++;
                if (!ds4_gpu_finish_command_buffer(cb, owned, "Q8_0 tensor mul_mv sgm")) return 0;
                return 1;
            }
            const int16_t nsg = ds4_gpu_mv_ext_nsg();
            const int16_t nxpsg = ds4_gpu_mv_ext_nxpsg(in_dim, n_tok);
            const int16_t r1ptg = (ext_r8_on() && !llms_alt_off("r8") && n_tok >= 8 && (n_tok % 8u) == 0) ? 8 : ds4_gpu_mv_ext_r1ptg(n_tok);   /* llms EXT_R8; ALT */
            const char *fn_name = ds4_gpu_mv_ext_name(1, r1ptg);
            static char ext_rpt_name[80]; const int ext_rpt_now = ({
                static int on = -1;
                if (on < 0) { const char *e = getenv("LLMS_DS4_EXT_RPT"); on = e && *e ? (!strcmp(e, "canary") ? -4 : atoi(e)) : 0; if (on != 2 && on != 4 && on != -4) on = 0;
                              if (on) { fprintf(stderr, on < 0 ? "llms: ext rpt -- CANARY: 4 rows per lane with the grid of 1\n" : "llms: ext rpt %d (rows per lane in the batched Q8 matvec)\n", on); atexit(report_ext_rpt); } }
                (int)(on);
            });
            if (ext_rpt_now && (r1ptg == 4 || r1ptg == 8)) {   /* llms EXT_RPT */
                snprintf(ext_rpt_name, sizeof ext_rpt_name, "kernel_llms_mul_mv_ext_q8_0_f32_r1_%d_rpt%d", (int)r1ptg, ext_rpt_now < 0 ? 2 : ext_rpt_now);   /* canary: the RPT-2 kernel */
                fn_name = ext_rpt_name; ext_rpt_calls++;
            }
            id<MTLComputePipelineState> pipeline =
                fn_name ? ds4_gpu_get_mul_mv_ext_pipeline(fn_name, nsg, nxpsg) : nil;
            if (!pipeline) return 0;

            const int16_t nypsg = 32 / nxpsg;
            const uint64_t r0ptg = (uint64_t)nypsg * (uint64_t)nsg * (uint64_t)(ext_rpt_now && (r1ptg == 4 || r1ptg == 8) ? (ext_rpt_now < 0 ? 4 : ext_rpt_now) : 1);   /* llms EXT_RPT: rows per threadgroup; the canary uses the RPT-4 grid with the RPT-2 kernel (half the rows unwritten) */
            ds4_gpu_mul_mv_ext_args args =
                ds4_gpu_make_mv_ext_args(in_dim, out_dim, n_tok, 34, row_bytes);
            if (r1ptg == 8) { ext_r8_calls++; if (ext_r8_on() == 2) args.nb11 /= 2; }   /* llms EXT_R8 canary */
            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
            [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
            [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)r0ptg - 1u) / (NSUInteger)r0ptg,
                                                  ((NSUInteger)n_tok + (NSUInteger)r1ptg - 1u) / (NSUInteger)r1ptg,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)nsg, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            if (!ds4_gpu_finish_command_buffer(cb, owned, "Q8_0 tensor mul_mv_ext")) {
                return 0;
            }
            return 1;
        }

        /*
         * Dense Q8_0 prefill is the cleanest DS4 TensorOps shape: M/N/K are
         * aligned and the RHS activation matrix is already dense.  The retained
         * kernel dequantizes each 64x32 weight tile to half in threadgroup
         * memory, then uses direct-RHS MPP for the activation tile.  This avoids
         * staging RHS into threadgroup memory and was the direct replacement for
         * the slower generic MPP prototype.
         */
        /*
         * An unaligned token count used to send the entire projection through
         * the generic kernel.  Run its aligned prefix through TensorOps and
         * leave only the final partial tile to the boundary-safe kernel.
         * Tiny prompts do not amortize the second dispatch, while --quality
         * deliberately retains the single-kernel arithmetic schedule.
         */
        const bool split_nax_prefix =
            !g_quality_mode && n_tok >= 192u && (n_tok % 32u) != 0u;
        const uint64_t nax_rows =
            (n_tok % 32u) == 0u ? n_tok :
            (split_nax_prefix ? n_tok - (n_tok % 32u) : 0u);
        uint64_t generic_row0 = 0u;
        uint64_t generic_rows = n_tok;
        if (ds4_gpu_mpp_available() &&
            nax_rows >= 32u &&
            (in_dim % 64u) == 0 &&
            (out_dim % 64u) == 0) {
            uint64_t nax_tile_n = 32u;
            if ((nax_rows % 128u) == 0) {
                nax_tile_n = 128u;
            } else if ((nax_rows % 64u) == 0) {
                nax_tile_n = 64u;
            }
            const char *nax_fn = nax_tile_n == 128u
                ? "kernel_mul_mm_q8_0_f32_nax_direct_rhs_n128"
                : (nax_tile_n == 64u
                    ? "kernel_mul_mm_q8_0_f32_nax_direct_rhs_n64"
                    : "kernel_mul_mm_q8_0_f32_nax_direct_rhs");
            id<MTLComputePipelineState> pipeline =
                ds4_gpu_get_mul_mm_pipeline(nax_fn, false, false);
            if (pipeline) {
                ds4_gpu_mul_mm_args args =
                    ds4_gpu_make_mm_args(in_dim, out_dim, nax_rows, row_bytes);

                id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                [enc setComputePipelineState:pipeline];
                [enc setBytes:&args length:sizeof(args) atIndex:0];
                [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
                [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
                [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
                [enc setThreadgroupMemoryLength:2u * 64u * 32u * sizeof(uint16_t) atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)(nax_rows / nax_tile_n),
                                                      (NSUInteger)out_dim / 64u,
                                                      1)
                     threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);

                if (nax_rows == n_tok) {
                    if (!ds4_gpu_finish_command_buffer(cb, owned, "Q8_0 NAX tensor matmul")) {
                        return 0;
                    }
                    return 1;
                }
                generic_row0 = nax_rows;
                generic_rows = n_tok - nax_rows;
            }
            if (!pipeline) ds4_gpu_warn_mpp_fallback();
        }

        const bool bc_inp = (in_dim % 32u) != 0;
        const bool bc_out =
            (out_dim % 64u) != 0 || (generic_rows % 32u) != 0;
        /* Amortize dequantization across token tiles with identical half
         * operands. Default is scoped by the Qwen entry point to M3 Ultra. */
        const int unpack_override = ds4_gpu_env_bool("DS4_QWEN4_Q8_PREFILL_UNPACK");
        const bool prefill_unpack = generic_rows >= 32u &&
            (unpack_override >= 0 ? unpack_override == 1 : prefill_default);
        const char *fn = "kernel_mul_mm_q8_0_f32";
        id<MTLBuffer> mat_weights = wbuf;
        NSUInteger mat_offset = (NSUInteger)inner_offset;
        uint64_t mat_row_bytes = row_bytes;
        const bool unpack_fits = in_dim > 0u && out_dim > 0u && out_dim <= (64u << 20) / in_dim;
        const uint64_t unpack_bytes = unpack_fits ? in_dim * out_dim * sizeof(uint16_t) : 0u;
        if (prefill_unpack && unpack_fits) {
            if (!ds4_gpu_ensure_scratch_buffer(&g_q8_prefill_scratch_buffer,
                    &g_q8_prefill_scratch_bytes, (NSUInteger)unpack_bytes, "q8 prefill weights")) return 0;
            id<MTLComputePipelineState> unpack = ds4_gpu_get_pipeline_or_die("kernel_q8_prefill_unpack");
            if (!unpack) return 0;
            const uint32_t n_blocks = (uint32_t)(in_dim * out_dim / 32u);
            id<MTLComputeCommandEncoder> unpack_enc = ds4_gpu_compute_encoder(cb);
            [unpack_enc setComputePipelineState:unpack];
            [unpack_enc setBytes:&n_blocks length:sizeof(n_blocks) atIndex:0];
            [unpack_enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
            [unpack_enc setBuffer:g_q8_prefill_scratch_buffer offset:0 atIndex:2];
            [unpack_enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_blocks * 8u + 255u)/256u, 1, 1)
                        threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
            ds4_gpu_end_compute_encoder(cb, unpack_enc);
            fn = "kernel_mul_mm_f16_f32";
            mat_weights = g_q8_prefill_scratch_buffer;
            mat_offset = 0;
            mat_row_bytes = in_dim * sizeof(uint16_t);
        }
        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_mul_mm_pipeline(fn, bc_inp, bc_out);
        if (!pipeline) return 0;

        ds4_gpu_mul_mm_args args =
            ds4_gpu_make_mm_args(in_dim, out_dim, generic_rows, mat_row_bytes);

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:mat_weights offset:mat_offset atIndex:1];
        [enc setBuffer:xbuf
                offset:ds4_gpu_tensor_offset(x) +
                       (NSUInteger)(generic_row0 * in_dim * sizeof(float))
               atIndex:2];
        [enc setBuffer:outbuf
                offset:ds4_gpu_tensor_offset(out) +
                       (NSUInteger)(generic_row0 * out_dim * sizeof(float))
               atIndex:3];
        [enc setThreadgroupMemoryLength:(bc_out ? 8192u : 6144u) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)generic_rows + 31u) / 32u,
                                              ((NSUInteger)out_dim + 63u) / 64u,
                                              1)
             threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "Q8_0 tensor matmul")) {
            return 0;
        }
    }

    return 1;
}

static int ds4_gpu_matmul_q8_0_tensor_impl(
        ds4_gpu_tensor       *out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        uint64_t                n_tok, bool prefill_default) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if ((in_dim & 31u) != 0 ||
        in_dim > UINT32_MAX || out_dim > UINT32_MAX || n_tok > UINT32_MAX) {
        return 0;
    }

    const int profile_requested =
        n_tok > 8u && ds4_gpu_env_bool("DS4_METAL_Q8_PREFILL_PROFILE") > 0;
    int profile_prefill = 0;
    int split_batch_for_profile = 0;
    const char *profile_label = NULL;
    char profile_label_buf[128];
    char profile_fallback[128];
    if (profile_requested) {
        snprintf(profile_fallback, sizeof(profile_fallback),
                 "q8 weight_off=%llu in=%llu out=%llu tok=%llu",
                 (unsigned long long)weight_offset,
                 (unsigned long long)in_dim,
                 (unsigned long long)out_dim,
                 (unsigned long long)n_tok);
        snprintf(profile_label_buf, sizeof(profile_label_buf), "%s", profile_fallback);
        profile_label = profile_label_buf;
        const char *profile_filter = getenv("DS4_METAL_Q8_PREFILL_PROFILE_FILTER");
        profile_prefill =
            profile_requested &&
            (!profile_filter || !profile_filter[0] ||
             strstr(profile_label, profile_filter) != NULL);
    }
    if (profile_prefill) {
        if (g_batch_cb) {
            if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
                return 0;
            }
            split_batch_for_profile = 1;
        }
    }

    const double profile_t0 = profile_prefill ? ds4_gpu_now_ms() : 0.0;
    int ok = ds4_gpu_matmul_q8_0_legacy_tensor(out, model_map, model_size,
                                               weight_offset, in_dim, out_dim,
                                               x, n_tok, false, prefill_default);
    if (profile_prefill) {
        if (split_batch_for_profile && ds4_gpu_end_commands() == 0) {
            ok = 0;
        }
        const double elapsed_ms = ds4_gpu_now_ms() - profile_t0;
        fprintf(stderr,
                "ds4: Metal Q8_0 prefill profile %s in=%llu out=%llu tok=%llu %.3f ms\n",
                profile_label ? profile_label : profile_fallback,
                (unsigned long long)in_dim,
                (unsigned long long)out_dim,
                (unsigned long long)n_tok,
                elapsed_ms);
        if (split_batch_for_profile && ds4_gpu_begin_commands() == 0) {
            ok = 0;
        }
