                model_map, model_size, weight_offset, weight_bytes,
                &inner_offset);
        if (!wbuf) return 0;

        {   /* llms Q4L_K (apply_q4l_k.py): 2-4 rows in one pass over the 4-bit copy */
            if (n_rows >= 2u && (n_rows <= 4u || (n_rows <= 8u && kr8_rows_max() >= n_rows && (kr8_mv_calls++, 1))) && !llms_alt_off("q4lk")) {   /* llms KR8: 5..8 */
                if (dense4_count < 0) load_dense4_table();
                const dense4_entry *qe = dense4_count > 0 ? find_dense4(weight_offset) : NULL;
                if (qe && llms_alt_off(qe->alt)) qe = NULL;
                if (qe && (ds4_gpu_tensor_offset(x) & 15u) == 0 && (uint64_t)qe->k == in_dim && (uint64_t)qe->n == out_dim) {
                    const bool rb = t32_round && mvb16_on(0) && !llms_alt_off("mvb");
                    int nr = n_rows <= 3u ? 8 : 4;
                    if (nr == 8 && k4h_four_rows(rb, n_rows)) nr = 4;   /* llms K4H 4 / 5 */
                    char name[64]; snprintf(name, sizeof name, "kernel_llms_q4l_mv_k%u_r%d_%s", n_rows, nr, rb ? "b" : "f");
                    int16_t qnsg = in_dim <= 1536u ? 1 : 2;
                    if (n_rows <= 4u && n1w_on(n_rows, out_dim)) { qnsg = 1; strlcat(name, "_n1", sizeof name); }   /* llms KR8: no N1W twin above 4 rows */
                    bool hx_use = false;   /* llms Q4L_HX (apply_hx.py): the two-row dense matvecs on HALF x; ALT hx */
                    {
                        const size_t ln = strlen(name);
                        if (!llms_alt_off("hx") && ln >= 2 && !strcmp(name + ln - 2, "_b") && (strstr(name, "_k2_") || (strstr(name, "_k3_") && k3x_on()) || (!strncmp(name, "kernel_llms_q4l_mv_k4_", 22) && k4x_on()) || kr8_hx_name(name))) { strlcat(name, "xh", sizeof name); hx_use = true; }
                        {   /* llms Q4L_HXO (apply_hxo.py): HX for the unrounded _k2_r8_f kernels; ALT hxo */
                            if (!hx_use && !llms_alt_off("hxo") && (!strcmp(name, "kernel_llms_q4l_mv_k2_r8_f") || (!strcmp(name, "kernel_llms_q4l_mv_k3_r8_f") && k3x_on()) || (!strcmp(name, "kernel_llms_q4l_mv_k4_r4_f") && k4x_on()) || (kr8_hx_name(name) && strstr(name, "_r4_f")))) { strlcat(name, "xh", sizeof name); hx_use = true; } }
                        {   /* llms Q4L_N1X (apply_n1x.py): HX + the one-simdgroup direct epilogue; ALT n1x */
                            const size_t l2 = strlen(name);
                            if (qnsg == 1 && hx_use && l2 >= 4 && !strcmp(name + l2 - 4, "_bxh") && !kr8_hx_name(name) && !llms_alt_off("n1x")) { strlcat(name, "_n1x", sizeof name); } }
                    }
                    append_k4h_twin(name, sizeof name, (uint32_t)n_rows, (uint32_t)in_dim);   /* llms K4H: this site counts rows as n_rows */
                    {   const int rsgs = q4l_rsg_s();   /* llms Q4L_RSG */
                        if (rsgs && hx_use && qnsg == 2 && out_dim >= 2048u && n_rows >= 2u && (n_rows <= 4u || kr8_hx_name(name)) && strlen(name) >= 4 && !strcmp(name + strlen(name) - 4, "_bxh") && !llms_alt_off("rsg")) {
                            nr = q4l_rsg_name(name, sizeof name, (unsigned)n_rows, rsgs) * rsgs;   /* llms Q4L_NR0 */ qnsg = (int16_t)rsgs; q4l_rsg_calls++; } }
                    {   /* llms S1WHY (apply_s1why.py): INSTRUMENT, off unless LLMS_DS4_S1WHY -- why RAGQ_S1_RSG's branch below runs 0 calls */
                        static int s1why = -1; static uint64_t s1w_n, s1w_nohx, s1w_name, s1w_taken, s1w_cnt[8]; static char s1w_names[8][64]; static int s1w_k;
                        if (s1why < 0) { const char *e = getenv("LLMS_DS4_S1WHY"); s1why = e && *e && *e != '0';
                            if (s1why) atexit_b(^{ fprintf(stderr, "llms s1why site decode_rows_exact: %llu calls at K 1280, R <= 1024, 2-4 rows; hx_use false %llu; name not _fxh %llu; S1's name and hx both met %llu; names:",
                                                           (unsigned long long)s1w_n, (unsigned long long)s1w_nohx, (unsigned long long)s1w_name, (unsigned long long)s1w_taken);
                                                   for (int i = 0; i < s1w_k; i++) fprintf(stderr, " %s x%llu", s1w_names[i], (unsigned long long)s1w_cnt[i]);
                                                   fprintf(stderr, "\n"); }); }
                        if (s1why && in_dim == 1280u && out_dim <= 1024u && n_rows >= 2u && n_rows <= 4u) {
                            s1w_n++; const size_t l1 = strlen(name); const int fx = l1 >= 4 && !strcmp(name + l1 - 4, "_fxh");
                            if (!hx_use) s1w_nohx++;
                            if (!fx) s1w_name++;
                            if (hx_use && fx) s1w_taken++;
                            int i = 0; for (; i < s1w_k; i++) if (!strcmp(s1w_names[i], name)) break;
                            if (i == s1w_k && s1w_k < 8) { strlcpy(s1w_names[s1w_k], name, sizeof s1w_names[0]); s1w_k++; }
                            if (i < 8) s1w_cnt[i]++; } }
                    {   const int s1r = ragq_s1_rsg();   /* llms RAGQ_S1_RSG */
                        if (s1r && hx_use && in_dim == 1280u && out_dim <= 1024u && n_rows >= 2u && n_rows <= 4u && strlen(name) >= 4 && !strcmp(name + strlen(name) - 4, "_fxh") && !llms_alt_off("s1rsg")) {
                            char s1n[64]; snprintf(s1n, sizeof s1n, "kernel_llms_q4l_mv_k%u_r%d_fxh_rsg%d", (unsigned)n_rows, ragq_s1_nr, s1r);
                            if (has_kernel(s1n)) { strlcpy(name, s1n, sizeof name); nr = ragq_s1_nr * s1r; qnsg = (int16_t)s1r; ragq_s1_rsg_calls++; }
                            else { static int warned; if (!warned++) fprintf(stderr, "llms ragq s1 rsg: %s not in the dense source -- the r8 body stays\n", s1n); } } }
                    {   const int s2r = ragq_s2_rsg();   /* llms RAGQ_S2_RSG */
                        if (s2r && hx_use && in_dim <= 1280u && out_dim == 32768u && n_rows >= 2u && n_rows <= 4u && strlen(name) >= 8 && !strcmp(name + strlen(name) - 8, "_bxh_n1x") && !llms_alt_off("s2rsg")) {
                            const int s2nr_ = (q4l_nr0_rows_ok((unsigned)n_rows) && q4l_nr0() && !llms_alt_off("nr0")) ? q4l_nr0() : ragq_s2_nr;   /* llms Q4L_NR0 (+ NR0_K34) */
                            char s2n[64]; snprintf(s2n, sizeof s2n, "kernel_llms_q4l_mv_k%u_r%d_bxh_rsg%d", (unsigned)n_rows, s2nr_, s2r);
                            if (has_kernel(s2n)) { strlcpy(name, s2n, sizeof name); nr = s2nr_ * s2r; if (s2nr_ != ragq_s2_nr) { q4l_nr0_calls++; if (strncmp(s2n, "kernel_llms_q4l_mv_k2_", 22)) q4l_nr0_k34_calls++; } qnsg = (int16_t)s2r; ragq_s2_rsg_calls++; }
                            else { static int warned; if (!warned++) fprintf(stderr, "llms ragq s2 rsg: %s not in the dense source -- N1X stays\n", s2n); } } }
                    id<MTLComputePipelineState> qp = ds4_gpu_get_mul_mv_pipeline(name, hx_use ? lean2_simdgroups(qnsg) : qnsg);   /* llms Q4L_LEAN2 */
                    if (qp) {
                        ds4_gpu_q8_0_matvec_args qa = ds4_gpu_make_q8_0_mv_args(in_dim, out_dim);
                        qa.nb00 = 1; qa.nb01 = q4l_rowb(in_dim); qa.nb02 = qa.nb01 * out_dim; qa.nb03 = qa.nb02; qa.nr0 = nr;
                        int owned = 0;
                        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                        if (!cb) return 0;
                        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                        [enc setComputePipelineState:qp];
                        [enc setBytes:&qa length:sizeof(qa) atIndex:0];
                        [enc setBuffer:qe->buf offset:(NSUInteger)qe->inner atIndex:1];
                        if (hx_use) {   /* apply_hx.py: the f32 -> f16 copy of x into the next ring slot; the matvec reads the slot (dispatch_hook's barrier orders them) */
                            static id<MTLBuffer> hx_ring[8]; static unsigned hx_slot; static id<MTLComputePipelineState> hx_cp;
                            if (!hx_cp) hx_cp = ds4_gpu_get_mul_mv_pipeline("kernel_llms_f32_to_f16_rows", 1);
                            if (!hx_cp) { static int w; if (!w++) fprintf(stderr, "llms: kernel_llms_f32_to_f16_rows missing from DS4_METAL_DENSE_SOURCE -- hx off\n"); abort(); }
                            {   /* llms HXRING (apply_hxring_live.py): the slot grows to n_rows x in_dim halves (a fixed 4 x 8192 slot overflowed for the drafter's main_proj, K 15360, at 3 rows: the K3X acceptance fault) */
                                const unsigned hs = hx_slot & 7u; const NSUInteger hneed = (NSUInteger)n_rows * (NSUInteger)in_dim * 2u;
                                if (!hx_ring[hs] || hx_ring[hs].length < hneed) hx_ring[hs] = [g_device newBufferWithLength:(hneed > 65536u ? hneed : 65536u) options:MTLResourceStorageModePrivate];
                            }
                            id<MTLBuffer> hb = nil; uint32_t cv[3] = { (uint32_t)(in_dim / 4u), (uint32_t)(qa.nb11 / 16u), (uint32_t)n_rows };
                            if (hxp_mark.buf) {   /* llms HX_PRODUCER: the producer's half copy, when this x IS its output (dense rows) */
                                if (hxp_mark.buf == xbuf && hxp_mark.off == ds4_gpu_tensor_offset(x) && hxp_mark.n == (uint64_t)n_rows * (uint64_t)in_dim && qa.nb11 == (uint64_t)in_dim * 4u && !llms_alt_off("hxprod")) {
                                    hb = hxp_mark.hb; hxp_used++; hxp_mark.buf = nil; hxp_mark.hb = nil;
                                } else hxp_drop();
                            }
                            if (!hb) {
                            hb = hx_ring[hx_slot++ & 7u];
                            [enc setComputePipelineState:hx_cp];
                            [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:0];
                            [enc setBuffer:hb offset:0 atIndex:1];
                            [enc setBytes:cv length:sizeof cv atIndex:2];
                            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)cv[0] * cv[2] + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
                            }
                            [enc setComputePipelineState:qp];
                            [enc setBytes:&qa length:sizeof(qa) atIndex:0];
                            [enc setBuffer:qe->buf offset:(NSUInteger)qe->inner atIndex:1];
                            [enc setBuffer:hb offset:0 atIndex:2];
                        } else [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
                        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
                        [enc setThreadgroupMemoryLength:(NSUInteger)nr * 32u * sizeof(float) atIndex:0];
                        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)nr - 1u) / (NSUInteger)nr, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)qnsg, 1)];
                        ds4_gpu_end_compute_encoder(cb, enc);
                        if (rb) t32_rounded = 1;
                        return ds4_gpu_finish_command_buffer(cb, owned, "llms q4l k-row matvec");
                    }
                }
            }
        }
        ds4_gpu_mv_dispatch dispatch = ds4_gpu_make_q8_0_mv_dispatch();
        if (out_dim > 65536u) dispatch.nsg = 8;
        ds4_gpu_q8_0_matvec_args args =
            ds4_gpu_make_q8_0_mv_args(in_dim, out_dim);
        args.ne11 = (int32_t)n_rows;
        args.nb12 = (uint64_t)n_rows * in_dim * sizeof(float);
        args.nb13 = args.nb12;
        args.ne1 = (int32_t)n_rows;
        args.nr0 = dispatch.nr0;

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_mul_mv_pipeline(dispatch.function_name, dispatch.nsg);
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc setThreadgroupMemoryLength:dispatch.smem atIndex:0];
        [enc dispatchThreadgroups:
                MTLSizeMake(((NSUInteger)out_dim +
                             (NSUInteger)dispatch.nr0 - 1u) /
                                (NSUInteger)dispatch.nr0,
                            (NSUInteger)n_rows,
                            1)
             threadsPerThreadgroup:
                MTLSizeMake(32, (NSUInteger)dispatch.nsg, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        return ds4_gpu_finish_command_buffer(
                cb, owned, "Q8_0 exact decode-row matvec");
    }
}

int ds4_gpu_matmul_q8_0_decode_mpp_tensor(
        ds4_gpu_tensor       *out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        uint64_t                n_tok) {
    return ds4_gpu_matmul_q8_0_legacy_tensor(out, model_map, model_size,
                                             weight_offset, in_dim, out_dim,
                                             x, n_tok, true, false);
}

int ds4_gpu_matmul_q8_0_decode_mpp_model_view_tensor(
        ds4_gpu_tensor       *out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        uint64_t                n_tok) {
    return ds4_gpu_matmul_q8_0_legacy_tensor(out, model_map, model_size,
                                             weight_offset, in_dim, out_dim,
                                             x, n_tok, true, false);
}

static const char *ds4_gpu_q4_mv_ext_name(uint32_t weight_type, int16_t r1ptg) {
    const char *prefix = NULL;
    if (weight_type == DS4_METAL_TENSOR_Q4_K) {
        prefix = "kernel_mul_mv_ext_q4_K_f32_r1_";
    } else if (weight_type == DS4_METAL_TENSOR_Q4_0) {
        prefix = "kernel_mul_mv_ext_q4_0_f32_r1_";
    } else {
        return NULL;
    }
    switch (r1ptg) {
    case 1: return weight_type == DS4_METAL_TENSOR_Q4_K ?
        "kernel_mul_mv_ext_q4_K_f32_r1_1" : "kernel_mul_mv_ext_q4_0_f32_r1_1";
    case 2: return weight_type == DS4_METAL_TENSOR_Q4_K ?
        "kernel_mul_mv_ext_q4_K_f32_r1_2" : "kernel_mul_mv_ext_q4_0_f32_r1_2";
    case 3: return weight_type == DS4_METAL_TENSOR_Q4_K ?
        "kernel_mul_mv_ext_q4_K_f32_r1_3" : "kernel_mul_mv_ext_q4_0_f32_r1_3";
    case 4: return weight_type == DS4_METAL_TENSOR_Q4_K ?
        "kernel_mul_mv_ext_q4_K_f32_r1_4" : "kernel_mul_mv_ext_q4_0_f32_r1_4";
    case 5: return weight_type == DS4_METAL_TENSOR_Q4_K ?
        "kernel_mul_mv_ext_q4_K_f32_r1_5" : "kernel_mul_mv_ext_q4_0_f32_r1_5";
    default:
        (void)prefix;
        return NULL;
    }
}

static const char *ds4_gpu_q4_mm_name(uint32_t weight_type) {
    switch (weight_type) {
    case DS4_METAL_TENSOR_Q4_0: return "kernel_mul_mm_q4_0_f32";
    case DS4_METAL_TENSOR_Q4_K: return "kernel_mul_mm_q4_K_f32";
    default: return NULL;
    }
}

static const char *ds4_gpu_q4_nax_name(uint32_t weight_type, uint64_t tile_n) {
    if (weight_type == DS4_METAL_TENSOR_Q4_0) {
        return tile_n == 128u ? "kernel_mul_mm_q4_0_f32_nax_direct_rhs_n128" :
               tile_n == 64u  ? "kernel_mul_mm_q4_0_f32_nax_direct_rhs_n64" :
                                 "kernel_mul_mm_q4_0_f32_nax_direct_rhs";
    }
    if (weight_type == DS4_METAL_TENSOR_Q4_K) {
        return tile_n == 128u ? "kernel_mul_mm_q4_K_f32_nax_direct_rhs_n128" :
               tile_n == 64u  ? "kernel_mul_mm_q4_K_f32_nax_direct_rhs_n64" :
                                 "kernel_mul_mm_q4_K_f32_nax_direct_rhs";
    }
    return NULL;
}

static int ds4_gpu_matmul_quant_impl_tensor(
        ds4_gpu_tensor       *out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint32_t                weight_type,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        uint64_t                n_tok,
        bool                    prefer_decode_mpp) {
    if (weight_type == DS4_METAL_TENSOR_Q8_0) {
        return ds4_gpu_matmul_q8_0_legacy_tensor(out,
                                                 model_map,
                                                 model_size,
                                                 weight_offset,
                                                 in_dim,
                                                 out_dim,
                                                 x,
                                                 n_tok,
                                                 prefer_decode_mpp, false);
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !x || !model_map ||
        in_dim == 0 || out_dim == 0 || n_tok == 0 ||
        in_dim > UINT32_MAX || out_dim > UINT32_MAX || n_tok > UINT32_MAX) {
        return 0;
    }

    uint64_t row_bytes = 0;
    if (!ds4_gpu_quant_row_bytes(weight_type, (uint32_t)in_dim, &row_bytes)) {
        fprintf(stderr, "ds4: Metal quant matmul received unsupported type/dim (%u, in=%llu)\n",
                weight_type,
                (unsigned long long)in_dim);
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t x_bytes = n_tok * in_dim * sizeof(float);
        const uint64_t out_bytes = n_tok * out_dim * sizeof(float);
        if (!xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes) {
            fprintf(stderr, "ds4: Metal quant tensor matmul received undersized activation buffers\n");
            return 0;
        }

        if (out_dim > UINT64_MAX / row_bytes) return 0;
        const uint64_t weight_bytes = out_dim * row_bytes;
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal quant tensor matmul range is outside the mapped model\n");
            return 0;
        }

        uint64_t inner_offset = 0;
        id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map,
                                                      model_size,
                                                      weight_offset,
                                                      weight_bytes,
                                                      &inner_offset);
        if (!wbuf) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        /*
         * Small-batch Q4_K goes to the classic (llama.cpp-style) matvec:
         * the mul_mv_ext family tops out around 220 GB/s on M5 for the GLM
         * DenseQ4 decode shapes while this impl streams 530-650 GB/s
         * (misc/q4mv_bench.m). Falls through to ext when unavailable.
         */
        if (weight_type == DS4_METAL_TENSOR_Q4_K &&
            n_tok <= 8u &&
            (in_dim % 256u) == 0 &&
            getenv("DS4_METAL_DISABLE_Q4_MV_CLASSIC") == NULL) {
            const int16_t nsg = 2;
            id<MTLComputePipelineState> pipeline =
                ds4_gpu_get_mul_mv_ext_pipeline("kernel_mul_mv_q4_K_dense_f32", nsg, 8);
            if (pipeline) {
                ds4_gpu_q8_0_matvec_args args = {
                    .ne00 = (int32_t)in_dim,
                    .ne01 = (int32_t)out_dim,
                    .ne02 = 1,
                    .nb00 = 1,
                    .nb01 = row_bytes,
                    .nb02 = row_bytes * out_dim,
                    .nb03 = row_bytes * out_dim,
                    .ne10 = (int32_t)in_dim,
                    .ne11 = (int32_t)n_tok,
                    .ne12 = 1,
                    .nb10 = sizeof(float),
                    .nb11 = in_dim * sizeof(float),
                    .nb12 = in_dim * n_tok * sizeof(float),
                    .nb13 = in_dim * n_tok * sizeof(float),
                    .ne0 = (int32_t)out_dim,
                    .ne1 = (int32_t)n_tok,
                    .nr0 = 2,
                    .r2 = 1,
                    .r3 = 1,
                };
                const uint64_t rows_ptg = (uint64_t)nsg * 2u;

                id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                [enc setComputePipelineState:pipeline];
                [enc setBytes:&args length:sizeof(args) atIndex:0];
                [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
                [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
                [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
                [enc setThreadgroupMemoryLength:32 atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + rows_ptg - 1u) / rows_ptg,
                                                      (NSUInteger)n_tok,
                                                      1)
                     threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)nsg, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);

                if (!ds4_gpu_finish_command_buffer(cb, owned, "Q4_K classic mul_mv")) return 0;
                return 1;
            }
        }

        if (n_tok <= 8u && (in_dim % 128u) == 0) {
            const int16_t nsg = 2;
            const int16_t nxpsg = ds4_gpu_mv_ext_nxpsg(in_dim, n_tok);
            const int16_t r1ptg = (n_tok == 1u) ? 1 : ds4_gpu_mv_ext_r1ptg(n_tok);
            const char *fn_name = ds4_gpu_q4_mv_ext_name(weight_type, r1ptg);
            id<MTLComputePipelineState> pipeline =
                fn_name ? ds4_gpu_get_mul_mv_ext_pipeline(fn_name, nsg, nxpsg) : nil;
            if (pipeline) {
                const int16_t nypsg = 32 / nxpsg;
                const uint64_t r0ptg = (uint64_t)nypsg * (uint64_t)nsg;
                ds4_gpu_mul_mv_ext_args args =
                    ds4_gpu_make_mv_ext_args(in_dim, out_dim, n_tok, row_bytes, row_bytes);

                id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                [enc setComputePipelineState:pipeline];
                [enc setBytes:&args length:sizeof(args) atIndex:0];
                [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
                [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
                [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
                [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)r0ptg - 1u) / (NSUInteger)r0ptg,
                                                      ((NSUInteger)n_tok + (NSUInteger)r1ptg - 1u) / (NSUInteger)r1ptg,
                                                      1)
                     threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)nsg, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);

                if (!ds4_gpu_finish_command_buffer(cb, owned, "Q4 tensor mul_mv_ext")) return 0;
                return 1;
            }
        }

        if (ds4_gpu_mpp_available() &&
            n_tok >= 32u &&
            (in_dim % 64u) == 0 &&
            (out_dim % 64u) == 0 &&
            (n_tok % 32u) == 0) {
            uint64_t nax_tile_n = 32u;
            if ((n_tok % 128u) == 0) {
                nax_tile_n = 128u;
            } else if ((n_tok % 64u) == 0) {
                nax_tile_n = 64u;
            }
            const char *nax_fn = ds4_gpu_q4_nax_name(weight_type, nax_tile_n);
            id<MTLComputePipelineState> pipeline =
                nax_fn ? ds4_gpu_get_mul_mm_pipeline(nax_fn, false, false) : nil;
            if (pipeline) {
                ds4_gpu_mul_mm_args args = ds4_gpu_make_mm_args(in_dim, out_dim, n_tok, row_bytes);

                id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                [enc setComputePipelineState:pipeline];
                [enc setBytes:&args length:sizeof(args) atIndex:0];
                [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
                [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
                [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
                [enc setThreadgroupMemoryLength:2u * 64u * 32u * sizeof(uint16_t) atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)(n_tok / nax_tile_n),
                                                      (NSUInteger)out_dim / 64u,
                                                      1)
                     threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);

                if (!ds4_gpu_finish_command_buffer(cb, owned, "Q4 NAX tensor matmul")) return 0;
                return 1;
            }
            ds4_gpu_warn_mpp_fallback();
        }

        const char *mm_fn = ds4_gpu_q4_mm_name(weight_type);
        const bool bc_inp = (in_dim % 32u) != 0;
        const bool bc_out = (out_dim % 64u) != 0 || (n_tok % 32u) != 0;
        id<MTLComputePipelineState> pipeline =
            mm_fn ? ds4_gpu_get_mul_mm_pipeline(mm_fn, bc_inp, bc_out) : nil;
        if (!pipeline) return 0;

        ds4_gpu_mul_mm_args args = ds4_gpu_make_mm_args(in_dim, out_dim, n_tok, row_bytes);

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc setThreadgroupMemoryLength:(bc_out ? 8192u : 6144u) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_tok + 31u) / 32u,
                                              ((NSUInteger)out_dim + 63u) / 64u,
                                              1)
             threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "Q4 tensor matmul")) return 0;
    }

    return 1;
}

