/* llms ROWS_T4 (apply_ds4_rows_t4.py): 4-token exact-rows matvec. 1 = >= 1,024 outputs, 2 = all, 3 = canary (mode 1, nb11 = 0) */
static uint64_t rows_t4_dispatches;
static void report_rows_t4(void) { fprintf(stderr, "llms rows t4: %llu dispatches\n", (unsigned long long)rows_t4_dispatches); }
static int rows_t4_on(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_ROWS_T4"); on = e && *e && *e != '0' ? (!strcmp(e, "canary") ? 3 : atoi(e) == 2 ? 2 : 1) : 0;
                  if (on) { fprintf(stderr, on == 3 ? "llms: rows t4 -- CANARY: all four tokens read token 0\n" : on == 2 ? "llms: rows t4 for every 4-row exact-rows matvec\n"
                                                    : "llms: rows t4 for 4-row exact-rows matvecs with >= 1024 outputs\n"); atexit(report_rows_t4); } }
    return on;
}
static int t4_force;   /* llms SP_VROWS 4 (apply_spv4.py): the 4-token kernel for every multiple of 4 tokens, no tile branches */
void ds4_gpu_llms_t4_force(int on) { t4_force = on; }
