                    mv_dispatch.function_name = n_tok >= 5u && kr8_f16k_name((uint32_t)n_tok, isbf16) ? kr8_f16k_name((uint32_t)n_tok, isbf16) : n_tok == 4u ? (isbf16 ? "kernel_llms_bf16_mv_k4_r2" : "kernel_llms_f16_mv_k4_r2") : n_tok == 3u ? (isbf16 ? "kernel_llms_bf16_mv_k3_r2" : "kernel_llms_f16_mv_k3_r2") : isbf16 ? "kernel_llms_bf16_mv_k2_r2" : "kernel_llms_f16_mv_k2_r2"; mv_dispatch.nr0 = 2; mv_dispatch.nsg = in_dim >= 4096u ? 4 : 2; mv_dispatch.smem = 2u * 32u * sizeof(float);
                    mv_args.nr0 = 2; f16k2_now = 1;
                    { const int fnr = n_tok == 2u ? f16k2_nr_on() : 0;   /* llms F16K2_NR: r4 / r8 at two rows */
                      if (fnr) { mv_dispatch.function_name = isbf16 ? (fnr == 8 ? "kernel_llms_bf16_mv_k2_r8" : "kernel_llms_bf16_mv_k2_r4") : (fnr == 8 ? "kernel_llms_f16_mv_k2_r8" : "kernel_llms_f16_mv_k2_r4");
                                 mv_dispatch.nr0 = fnr; mv_args.nr0 = fnr; mv_dispatch.smem = (uint32_t)fnr * 32u * sizeof(float); f16k2_nr_calls++; } }
                }
            }
            id<MTLComputePipelineState> pipeline =
                ds4_gpu_get_mul_mv_pipeline(mv_dispatch.function_name, mv_dispatch.nsg);
            if (!pipeline) return 0;

            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            if (timeline_shapes_on()) snprintf(timeline_shape_tag, sizeof timeline_shape_tag, "@K%llu_R%llu_C%u", (unsigned long long)in_dim, (unsigned long long)out_dim, (unsigned)n_tok);   /* llms TL_NAMES: the F16 / BF16 matvec */
            [enc setComputePipelineState:pipeline];
            [enc setBytes:&mv_args length:sizeof(mv_args) atIndex:0];
            [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
            [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
            [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
            if (mv_dispatch.smem) {
                [enc setThreadgroupMemoryLength:mv_dispatch.smem atIndex:0];
            }
            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)mv_dispatch.nr0 - 1u) / (NSUInteger)mv_dispatch.nr0,
                                                  f16k2_now ? 1u : (NSUInteger)n_tok,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, f16k2_now ? (NSUInteger)mv_dispatch.nsg : lean_simdgroups, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            if (!ds4_gpu_finish_command_buffer(cb, owned, "F16 tensor matvec")) return 0;
            return 1;
        }

        if (n_tok <= 8 && (in_dim % 128u) == 0) {
            const int16_t nsg = ds4_gpu_mv_ext_nsg();
            const int16_t nxpsg = ds4_gpu_mv_ext_nxpsg(in_dim, n_tok);
            const int16_t r1ptg = ds4_gpu_mv_ext_r1ptg(n_tok);
            const char *fn_name = ds4_gpu_mv_ext_name(0, r1ptg);
            id<MTLComputePipelineState> pipeline =
                fn_name ? ds4_gpu_get_mul_mv_ext_pipeline(fn_name, nsg, nxpsg) : nil;
            if (!pipeline) return 0;

            const int16_t nypsg = 32 / nxpsg;
            const uint64_t r0ptg = (uint64_t)nypsg * (uint64_t)nsg;
            ds4_gpu_mul_mv_ext_args args =
                ds4_gpu_make_mv_ext_args(in_dim, out_dim, n_tok, sizeof(uint16_t), row_bytes);

            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
            [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
            [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)r0ptg - 1u) / (NSUInteger)r0ptg,
                                                  ((NSUInteger)n_tok + (NSUInteger)r1ptg - 1u) / (NSUInteger)r1ptg,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)nsg, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            if (!ds4_gpu_finish_command_buffer(cb, owned, "F16 tensor mul_mv_ext")) return 0;
            return 1;
        }

        /*
         * Same direct-RHS TensorOps structure as Q8_0, but for F16 model
         * matrices.  The 128-token RHS tile is kept when the batch alignment
         * allows it because the later tile_n=64 retest was neutral/slower.
         */
        if (ds4_gpu_mpp_available() &&
            n_tok >= 32u &&
            (in_dim % 32u) == 0 &&
            (out_dim % 64u) == 0 &&
            (n_tok % 32u) == 0) {
            uint64_t nax_tile_n = 32u;
            if ((n_tok % 128u) == 0) {
                nax_tile_n = 128u;
            } else if ((n_tok % 64u) == 0) {
                nax_tile_n = 64u;
            }
            const char *nax_fn = nax_tile_n == 128u
                ? "kernel_mul_mm_f16_f32_mpp_direct_rhs_n128"
                : (nax_tile_n == 64u
                    ? "kernel_mul_mm_f16_f32_mpp_direct_rhs_n64"
                    : "kernel_mul_mm_f16_f32_mpp_direct_rhs");
            id<MTLComputePipelineState> pipeline =
                ds4_gpu_get_mul_mm_pipeline(nax_fn, false, false);
            if (pipeline) {
                ds4_gpu_mul_mm_args args = ds4_gpu_make_mm_args(in_dim, out_dim, n_tok, row_bytes);

                id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                [enc setComputePipelineState:pipeline];
                [enc setBytes:&args length:sizeof(args) atIndex:0];
                [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
                [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
                [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
                [enc setThreadgroupMemoryLength:2u * 64u * 32u * sizeof(uint16_t) atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)(n_tok / nax_tile_n),
                                                      (NSUInteger)out_dim / 64u,
                                                      1)
                     threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);

                if (!ds4_gpu_finish_command_buffer(cb, owned, "F16 NAX tensor matmul")) {
                    return 0;
                }
                return 1;
            }
            ds4_gpu_warn_mpp_fallback();
        }

        const bool bc_inp = (in_dim % 32u) != 0;
        const bool bc_out = (out_dim % 64u) != 0 || (n_tok % 32u) != 0;
        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_mul_mm_pipeline("kernel_mul_mm_f16_f32", bc_inp, bc_out);
        if (!pipeline) return 0;

        ds4_gpu_mul_mm_args args = ds4_gpu_make_mm_args(in_dim, out_dim, n_tok, row_bytes);

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc setThreadgroupMemoryLength:(bc_out ? 8192u : 6144u) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_tok + 31u) / 32u,
                                              ((NSUInteger)out_dim + 63u) / 64u,
                                              1)
             threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "F16 tensor matmul")) return 0;
    }

    return 1;
}

/* llms Q4L_F16 (apply_q4l_f16.py): a one-token F16 matvec whose weight the Q4L index lists reads the 4-bit copy */
static uint64_t dense4_f16_calls;
static int try_dense4_f16(ds4_gpu_tensor *out, uint64_t weight_offset, uint64_t in_dim, uint64_t out_dim, const ds4_gpu_tensor *x) {
    if (dense4_count < 0) load_dense4_table();
    const dense4_entry *qe = dense4_count > 0 ? find_dense4(weight_offset) : NULL;
    if (!qe || llms_alt_off(qe->alt)) return 0;
    if ((uint64_t)qe->k != in_dim || (uint64_t)qe->n != out_dim) {
        fprintf(stderr, "llms q4l f16: entry at %llu is %ux%u, the call %llux%llu\n", (unsigned long long)weight_offset, qe->k, qe->n,
                (unsigned long long)in_dim, (unsigned long long)out_dim); abort();
    }
    id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x), outbuf = ds4_gpu_tensor_buffer(out);
    if (!xbuf || !outbuf || (ds4_gpu_tensor_offset(x) & 15u) != 0) return 0;
    const int16_t qnsg = in_dim <= 1536u ? 1 : 2;
    id<MTLComputePipelineState> qp = ds4_gpu_get_mul_mv_pipeline("kernel_llms_q4l_mv", qnsg);
    if (!qp) { fprintf(stderr, "llms: q4l kernels missing from DS4_METAL_DENSE_SOURCE\n"); abort(); }
    int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    if (!cb) return -1;
    ds4_gpu_q8_0_matvec_args qa = ds4_gpu_make_q8_0_mv_args(in_dim, out_dim);
    qa.nb00 = 1; qa.nb01 = q4l_rowb(in_dim); qa.nb02 = qa.nb01 * out_dim; qa.nb03 = qa.nb02; qa.nr0 = 4;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:qp];
    [enc setBytes:&qa length:sizeof(qa) atIndex:0];
    [enc setBuffer:qe->buf offset:(NSUInteger)qe->inner atIndex:1];
    [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
    [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
    [enc setThreadgroupMemoryLength:4u * 32u * sizeof(float) atIndex:0];
    [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + 3u) / 4u, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)qnsg, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    if (!dense4_f16_calls) atexit_b(^{ fprintf(stderr, "llms q4l f16: %llu one-token F16 matvecs on 4-bit copies\n", (unsigned long long)dense4_f16_calls); });
    dense4_f16_calls++; dense4_calls++;
    return ds4_gpu_finish_command_buffer(cb, owned, "Q4L F16 matvec") ? 1 : -1;
}
int ds4_gpu_matmul_f16_tensor(ds4_gpu_tensor *out,
                            const void *model_map, uint64_t model_size,
                            uint64_t weight_offset, uint64_t in_dim,
                            uint64_t out_dim, const ds4_gpu_tensor *x,
                            uint64_t n_tok) {
    if (n_tok == 1) {   /* llms Q4L_F16 */
        if (!g_initialized && !ds4_gpu_init()) return 0;
        const int r = try_dense4_f16(out, weight_offset, in_dim, out_dim, x);
        if (r) return r > 0;
    }
    return ds4_gpu_matmul_f16_tensor_impl(out, model_map, model_size,
        weight_offset, in_dim, out_dim, x, n_tok, false);
}

int ds4_gpu_dsv41_projection_rows(ds4_gpu_tensor *out,
                                 const void *model_map, uint64_t model_size,
                                 uint64_t weight_offset, uint32_t width,
                                 uint32_t outputs, uint32_t rows,
                                 const ds4_gpu_tensor *in) {
    if (!width || !outputs || !rows || rows > 8192u || !model_map) return 0;
    {   /* llms ENGRAM_MM (apply_engmm.py): a prefill call's F16 Engram projection (6144 -> 25600) as one float-tile * GEMM pass; the 4-token kernel reads the 315 MB weight once per 4 tokens. Rows >= 8 only. 1 on, canary = last row left out. */
        static int engram_mm_state = -1; static uint64_t engram_mm_calls, engram_mm_rows;
        if (engram_mm_state < 0) { const char *e = getenv("LLMS_DS4_ENGRAM_MM"); engram_mm_state = !(e && *e && *e != '0') ? 0 : !strcmp(e, "canary") ? 2 : 1;
                      if (engram_mm_state) { fprintf(stderr, engram_mm_state == 2 ? "llms: engram mm CANARY -- the last row of each call left out\n"
                                                        : "llms: engram mm (a prefill call's F16 Engram projections as one float-tile GEMM pass)\n");
                                atexit_b(^{ fprintf(stderr, "llms engram mm: %llu GEMM calls, %llu rows\n", (unsigned long long)engram_mm_calls, (unsigned long long)engram_mm_rows); }); } }
        if (engram_mm_state && rows >= 8u && width == 6144u && outputs == 25600u && !llms_alt_off("engmm")) {
            if (!g_initialized && !ds4_gpu_init()) return 0;
            const uint64_t n = engram_mm_state == 2 ? (uint64_t)rows - 1u : (uint64_t)rows;
            const uint64_t row_bytes = (uint64_t)width * sizeof(uint16_t), weight_bytes = row_bytes * outputs;
            id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(in), obuf = ds4_gpu_tensor_buffer(out);
            if (xbuf && obuf && weight_offset <= model_size && weight_bytes <= model_size - weight_offset &&
                ds4_gpu_tensor_bytes(in) >= (uint64_t)rows * width * sizeof(float) && ds4_gpu_tensor_bytes(out) >= (uint64_t)rows * outputs * sizeof(float)) {
                uint64_t inner = 0;
                id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map, model_size, weight_offset, weight_bytes, &inner);
                id<MTLComputePipelineState> p = wbuf ? ds4_gpu_get_mul_mm_pipeline("kernel_mul_mm_f16_f32_exact", false, (n % 32u) != 0) : nil;
                if (p) {
                    int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                    if (!cb) return 0;
                    ds4_gpu_mul_mm_args args = ds4_gpu_make_mm_args(width, outputs, n, row_bytes);
                    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                    [enc setComputePipelineState:p];
                    [enc setBytes:&args length:sizeof(args) atIndex:0];
                    [enc setBuffer:wbuf offset:(NSUInteger)inner atIndex:1];
                    [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(in) atIndex:2];
                    [enc setBuffer:obuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
                    [enc setThreadgroupMemoryLength:64u * 32u * sizeof(float) + 32u * 32u * sizeof(float) atIndex:0];
                    [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)((n + 31u) / 32u), (NSUInteger)outputs / 64u, 1) threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                    ds4_gpu_end_compute_encoder(cb, enc);
                    engram_mm_calls++; engram_mm_rows += rows;
                    return ds4_gpu_finish_command_buffer(cb, owned, "llms engram mm");
                }
            }
        }
    }
    {   /* llms Q4L_K3 (apply_q4l_k3.py): 2-4 rows of a weight with a 4-bit copy, one pass */

        static int q4l_k8f_state = -1; if (q4l_k8f_state < 0) { const char *e = getenv("LLMS_DS4_Q4L_K8F"); q4l_k8f_state = e && *e && *e != '0'; if (q4l_k8f_state) fprintf(stderr, "llms: q4l k8f (5..8-row F16 projections on the 4-bit k-row kernel; the dense source must carry k5..k8)\n"); }   /* llms K8F */
        if (rows >= 2u && rows <= (q4l_k8f_state ? 8u : 4u) && !llms_alt_off("q4lk")) {
            if (!g_initialized && !ds4_gpu_init()) return 0;
            if (dense4_count < 0) load_dense4_table();
            const dense4_entry *qe = dense4_count > 0 ? find_dense4(weight_offset) : NULL;
            if (qe && !llms_alt_off(qe->alt) && (ds4_gpu_tensor_offset(in) & 15u) == 0 && qe->k == width && qe->n == outputs) {

                {   /* llms PROJ_RSG (apply_proj_rsg.py): the half-x row-per-simdgroup kernel, the bf16 rounding folded (the caller set t32_round) */
                    const int rsgs = q4l_rsg_s();
                    if (t32_round && mvb16_on(0) && rsgs && outputs >= 2048u && width > 1536u && (rows == 2u || (rows == 3u && k3x_on()) || (rows == 4u && k4x_on()) || (rows >= 5u && rows <= 8u && kr8_rows_max() >= rows && !llms_alt_off("kr8hx"))) &&
                        !llms_alt_off("projrsg") && !llms_alt_off("mvb")) {
                        char pn[64]; snprintf(pn, sizeof pn, "kernel_llms_q4l_mv_k%u_r4_bxh_rsg%d", rows, rsgs);
                        const int pnr = 4 * rsgs; const int16_t pnsg = (int16_t)rsgs;
                        id<MTLComputePipelineState> pqp = ds4_gpu_get_mul_mv_pipeline(pn, lean2_simdgroups(pnsg));
                        static id<MTLComputePipelineState> pcv; if (!pcv) pcv = ds4_gpu_get_mul_mv_pipeline("kernel_llms_f32_to_f16_rows", 1);
                        static id<MTLBuffer> pring[8]; static unsigned pslot;
                        const unsigned phs = pslot & 7u; const NSUInteger pneed = (NSUInteger)rows * (NSUInteger)width * 2u;
                        if (pqp && pcv && (!pring[phs] || pring[phs].length < pneed)) pring[phs] = [g_device newBufferWithLength:(pneed > 65536u ? pneed : 65536u) options:MTLResourceStorageModePrivate];
                        if (pqp && pcv && pring[phs]) {
                            id<MTLBuffer> hb = pring[pslot++ & 7u];
                            ds4_gpu_q8_0_matvec_args qa = ds4_gpu_make_q8_0_mv_args(width, outputs);
                            qa.nb00 = 1; qa.nb01 = q4l_rowb(width); qa.nb02 = qa.nb01 * outputs; qa.nb03 = qa.nb02; qa.nr0 = pnr;
                            int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                            if (!cb) return 0;
                            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                            uint32_t cv[3] = { width / 4u, (uint32_t)(qa.nb11 / 16u), rows };
                            [enc setComputePipelineState:pcv];   /* the f32 -> f16 copy of x into the ring slot; the matvec reads the slot (dispatch_hook's barrier orders them, as in apply_hx.py) */
                            [enc setBuffer:ds4_gpu_tensor_buffer(in) offset:ds4_gpu_tensor_offset(in) atIndex:0];
                            [enc setBuffer:hb offset:0 atIndex:1];
                            [enc setBytes:cv length:sizeof cv atIndex:2];
                            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)cv[0] * cv[2] + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
                            [enc setComputePipelineState:pqp];
                            [enc setBytes:&qa length:sizeof(qa) atIndex:0];
                            [enc setBuffer:qe->buf offset:(NSUInteger)qe->inner atIndex:1];
                            [enc setBuffer:hb offset:0 atIndex:2];
                            [enc setBuffer:ds4_gpu_tensor_buffer(out) offset:ds4_gpu_tensor_offset(out) atIndex:3];
                            [enc setThreadgroupMemoryLength:(NSUInteger)pnr * 32u * sizeof(float) atIndex:0];
                            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)outputs + (NSUInteger)pnr - 1u) / (NSUInteger)pnr, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)pnsg, 1)];
                            ds4_gpu_end_compute_encoder(cb, enc);
                            t32_rounded = 1;
                            return ds4_gpu_finish_command_buffer(cb, owned, "llms proj rsg matvec");
                        }
                    }
                }
                const int nr = rows <= 3u ? 8 : 4;
                char name[64]; snprintf(name, sizeof name, "kernel_llms_q4l_mv_k%u_r%d_f", rows, nr);
                const int16_t qnsg = width <= 1536u ? 1 : 2;
                id<MTLComputePipelineState> qp = ds4_gpu_get_mul_mv_pipeline(name, qnsg);
                if (qp) {
                    ds4_gpu_q8_0_matvec_args qa = ds4_gpu_make_q8_0_mv_args(width, outputs);
                    qa.nb00 = 1; qa.nb01 = q4l_rowb(width); qa.nb02 = qa.nb01 * outputs; qa.nb03 = qa.nb02; qa.nr0 = nr;
                    int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                    if (!cb) return 0;
                    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                    [enc setComputePipelineState:qp];
                    [enc setBytes:&qa length:sizeof(qa) atIndex:0];
                    [enc setBuffer:qe->buf offset:(NSUInteger)qe->inner atIndex:1];
                    [enc setBuffer:ds4_gpu_tensor_buffer(in) offset:ds4_gpu_tensor_offset(in) atIndex:2];
                    [enc setBuffer:ds4_gpu_tensor_buffer(out) offset:ds4_gpu_tensor_offset(out) atIndex:3];
                    [enc setThreadgroupMemoryLength:(NSUInteger)nr * 32u * sizeof(float) atIndex:0];
                    [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)outputs + (NSUInteger)nr - 1u) / (NSUInteger)nr, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)qnsg, 1)];
                    ds4_gpu_end_compute_encoder(cb, enc);
                    return ds4_gpu_finish_command_buffer(cb, owned, "llms q4l k3 matvec");
                }
            }
        }
    }
    return ds4_gpu_matmul_f16_tensor_impl(out, model_map, model_size,
        weight_offset, width, outputs, in, rows, true);
}

int ds4_gpu_matmul_f16_pair_tensor(
        ds4_gpu_tensor       *out_a,
        ds4_gpu_tensor       *out_b,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_a_offset,
        uint64_t                weight_b_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        uint64_t                n_tok) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (in_dim > UINT32_MAX || out_dim > UINT32_MAX || n_tok != 1 || (in_dim & 3u) != 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outabuf = ds4_gpu_tensor_buffer(out_a);
        id<MTLBuffer> outbbuf = ds4_gpu_tensor_buffer(out_b);
        const uint64_t x_bytes = in_dim * sizeof(float);
        const uint64_t out_bytes = out_dim * sizeof(float);
        if (!xbuf || !outabuf || !outbbuf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(out_a) < out_bytes ||
            ds4_gpu_tensor_bytes(out_b) < out_bytes) {
            fprintf(stderr, "ds4: Metal F16 paired matvec received undersized activation buffers\n");
            return 0;
        }

        const uint64_t row_bytes = in_dim * sizeof(uint16_t);
        const uint64_t weight_bytes = row_bytes * out_dim;
        if (weight_a_offset > model_size || weight_bytes > model_size - weight_a_offset ||
            weight_b_offset > model_size || weight_bytes > model_size - weight_b_offset) {
            fprintf(stderr, "ds4: Metal F16 paired matvec range is outside the mapped model\n");
            return 0;
        }

        uint64_t inner_a = 0;
        uint64_t inner_b = 0;
        id<MTLBuffer> wabuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                         weight_a_offset, weight_bytes,
                                                         &inner_a);
        id<MTLBuffer> wbbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                         weight_b_offset, weight_bytes,
                                                         &inner_b);
        if (!wabuf || !wbbuf) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_f16_matvec_args mv_args = ds4_gpu_make_f16_mv_args(in_dim, out_dim);
        ds4_gpu_mv_dispatch mv_dispatch = ds4_gpu_make_plain_mv_dispatch(in_dim, 0);
        if (ds4_gpu_use_compressor_pair_nr4() &&
            (out_dim == 512u || out_dim == 1024u) && in_dim >= 4096u) {
            mv_dispatch.nr0 = 4;
            mv_dispatch.smem = 32u * 4u * sizeof(float);
        }
        mv_args.nr0 = mv_dispatch.nr0;
        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_mul_mv_pipeline("kernel_mul_mv_f16_f32_pair_4", mv_dispatch.nsg);
        if (!pipeline) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&mv_args length:sizeof(mv_args) atIndex:0];
        [enc setBuffer:wabuf offset:(NSUInteger)inner_a atIndex:1];
        [enc setBuffer:wbbuf offset:(NSUInteger)inner_b atIndex:2];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:3];
        [enc setBuffer:outabuf offset:ds4_gpu_tensor_offset(out_a) atIndex:4];
        [enc setBuffer:outbbuf offset:ds4_gpu_tensor_offset(out_b) atIndex:5];
        if (mv_dispatch.smem) {
            [enc setThreadgroupMemoryLength:mv_dispatch.smem atIndex:0];
        }
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)mv_dispatch.nr0 - 1u) / (NSUInteger)mv_dispatch.nr0,
                                              1,
                                              1)
             threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)mv_dispatch.nsg, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "F16 paired matvec")) return 0;
    }

    return 1;
}

int ds4_gpu_matmul_f16_pair_compressor_store_tensor(
        ds4_gpu_tensor       *out_kv,
        ds4_gpu_tensor       *out_score,
        ds4_gpu_tensor       *state_kv,
        ds4_gpu_tensor       *state_score,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_kv_offset,
        uint64_t                weight_score_offset,
        uint64_t                ape_offset,
        uint32_t                ape_type,
        uint64_t                in_dim,
        uint32_t                width,
        const ds4_gpu_tensor *x,
        uint32_t                ratio,
        uint32_t                pos) {
    if (!g_initialized && !ds4_gpu_init()) return -1;
    if ((g_quality_mode ||
         (!llms_m3_site(4) &&
          !ds4_gpu_device_name_contains("M5"))) ||
        getenv("DS4_METAL_DISABLE_COMPRESSOR_PAIR_PROJ") != NULL ||
        getenv("DS4_METAL_DISABLE_COMPRESSOR_STORE_ONE") != NULL) {
        return 0;
    }
    if (!out_kv || !out_score || !state_kv || !state_score || !model_map || !x ||
        in_dim == 0 || width == 0 || ratio == 0 ||
        (ape_type != 0u && ape_type != 1u)) {
        return -1;
    }
    if (in_dim != 4096u ||
        (width != 256u && width != 512u && width != 1024u) ||
        (ratio != 4u && ratio != 128u)) {
        return 0;
    }

    @autoreleasepool {
        const uint32_t state_rows = ratio == 4u ? 2u * ratio : ratio;
        const uint64_t row_bytes = in_dim * sizeof(uint16_t);
        const uint64_t weight_bytes = row_bytes * width;
        const uint64_t out_bytes = (uint64_t)width * sizeof(float);
        const uint64_t state_bytes =
            (uint64_t)state_rows * width * sizeof(float);
        const uint64_t ape_elem = ape_type == 1u ? sizeof(uint16_t) : sizeof(float);
        const uint64_t ape_bytes = (uint64_t)ratio * width * ape_elem;
        if (weight_kv_offset > model_size ||
            weight_bytes > model_size - weight_kv_offset ||
            weight_score_offset > model_size ||
            weight_bytes > model_size - weight_score_offset ||
            ape_offset > model_size || ape_bytes > model_size - ape_offset) {
            return -1;
        }

        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outkvbuf = ds4_gpu_tensor_buffer(out_kv);
        id<MTLBuffer> outscorebuf = ds4_gpu_tensor_buffer(out_score);
        id<MTLBuffer> statekvbuf = ds4_gpu_tensor_buffer(state_kv);
        id<MTLBuffer> statescbuf = ds4_gpu_tensor_buffer(state_score);
        if (!xbuf || !outkvbuf || !outscorebuf || !statekvbuf || !statescbuf ||
            ds4_gpu_tensor_bytes(x) < in_dim * sizeof(float) ||
            ds4_gpu_tensor_bytes(out_kv) < out_bytes ||
            ds4_gpu_tensor_bytes(out_score) < out_bytes ||
            ds4_gpu_tensor_bytes(state_kv) < state_bytes ||
            ds4_gpu_tensor_bytes(state_score) < state_bytes) {
            return -1;
        }

        uint64_t weight_kv_inner = 0;
        uint64_t weight_score_inner = 0;
        uint64_t ape_inner = 0;
        id<MTLBuffer> weightkvbuf = ds4_gpu_wrap_model_range(
            model_map, model_size, weight_kv_offset, weight_bytes,
            &weight_kv_inner);
        id<MTLBuffer> weightscorebuf = ds4_gpu_wrap_model_range(
            model_map, model_size, weight_score_offset, weight_bytes,
            &weight_score_inner);
        id<MTLBuffer> apebuf = ds4_gpu_wrap_model_range(
            model_map, model_size, ape_offset, ape_bytes, &ape_inner);
        if (!weightkvbuf || !weightscorebuf || !apebuf) return -1;

        ds4_gpu_f16_matvec_args mv_args =
            ds4_gpu_make_f16_mv_args(in_dim, width);
        ds4_gpu_mv_dispatch mv_dispatch =
            ds4_gpu_make_plain_mv_dispatch(in_dim, 0);
        if (ds4_gpu_use_compressor_pair_nr4() &&
            (width == 512u || width == 1024u) && in_dim >= 4096u) {
            mv_dispatch.nr0 = 4;
            mv_dispatch.smem = 32u * 4u * sizeof(float);
        }
        mv_args.nr0 = mv_dispatch.nr0;
        ds4_gpu_dsv4_compressor_store_one_args store_args = {
            .width = width,
            .ratio = ratio,
            .pos = pos,
            .ape_type = ape_type,
        };
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_mul_mv_pipeline(
            "kernel_mul_mv_f16_f32_pair_compressor_store_4",
            mv_dispatch.nsg);
        if (!pipeline) return -1;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return -1;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&mv_args length:sizeof(mv_args) atIndex:0];
        [enc setBytes:&store_args length:sizeof(store_args) atIndex:1];
        [enc setBuffer:weightkvbuf offset:(NSUInteger)weight_kv_inner atIndex:2];
        [enc setBuffer:weightscorebuf offset:(NSUInteger)weight_score_inner atIndex:3];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:4];
        [enc setBuffer:outkvbuf offset:ds4_gpu_tensor_offset(out_kv) atIndex:5];
        [enc setBuffer:outscorebuf offset:ds4_gpu_tensor_offset(out_score) atIndex:6];
        [enc setBuffer:apebuf offset:(NSUInteger)ape_inner atIndex:7];
        [enc setBuffer:statekvbuf offset:ds4_gpu_tensor_offset(state_kv) atIndex:8];
        [enc setBuffer:statescbuf offset:ds4_gpu_tensor_offset(state_score) atIndex:9];
        if (mv_dispatch.smem) {
            [enc setThreadgroupMemoryLength:mv_dispatch.smem atIndex:0];
        }
        [enc dispatchThreadgroups:MTLSizeMake(
                ((NSUInteger)width + (NSUInteger)mv_dispatch.nr0 - 1u) /
                    (NSUInteger)mv_dispatch.nr0,
                1,
                1)
             threadsPerThreadgroup:MTLSizeMake(
                32, (NSUInteger)mv_dispatch.nsg, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(
                cb, owned, "F16 paired matvec compressor state store")) {
            return -1;
        }
    }

    return 1;
}

/* Quad variant of the paired compressor projection: the attention compressor
 * and indexer compressor pairs share the input activation and F16 matvec
 * shape, so one dispatch covers all four matrices.  Bit-exact by
 * construction (see metal/dense.metal).  Returns 1 when the fused dispatch
 * ran, 0 when the caller should use the separate paths, -1 on error. */
int ds4_gpu_matmul_f16_quad_compressor_store_tensor(
        ds4_gpu_tensor       *out0_kv,
        ds4_gpu_tensor       *out0_score,
        ds4_gpu_tensor       *out1_kv,
        ds4_gpu_tensor       *out1_score,
        ds4_gpu_tensor       *state0_kv,
        ds4_gpu_tensor       *state0_score,
        ds4_gpu_tensor       *state1_kv,
        ds4_gpu_tensor       *state1_score,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight0_kv_offset,
        uint64_t              weight0_score_offset,
        uint64_t              weight1_kv_offset,
        uint64_t              weight1_score_offset,
        uint64_t              ape0_offset,
        uint32_t              ape0_type,
        uint64_t              ape1_offset,
        uint32_t              ape1_type,
        uint64_t              in_dim,
        uint32_t              width0,
        uint32_t              width1,
        const ds4_gpu_tensor *x,
        uint32_t              ratio,
        uint32_t              pos) {
    if (!g_initialized && !ds4_gpu_init()) return -1;
    if (!out0_kv || !out0_score || !out1_kv || !out1_score ||
        !state0_kv || !state0_score || !state1_kv || !state1_score ||
        !model_map || !x ||
        (ape0_type != 0u && ape0_type != 1u) ||
        (ape1_type != 0u && ape1_type != 1u)) {
        return -1;
    }
    if (in_dim != 4096u ||
        (width0 != 512u && width0 != 1024u) ||
        width1 != 256u || ratio != 4u) {
        return 0;
    }

    @autoreleasepool {
        const uint32_t state_rows = 2u * ratio;
        const uint64_t row_bytes = in_dim * sizeof(uint16_t);
        const uint64_t weight0_bytes = row_bytes * width0;
        const uint64_t weight1_bytes = row_bytes * width1;
        const uint64_t ape0_elem = ape0_type == 1u ? sizeof(uint16_t) : sizeof(float);
        const uint64_t ape1_elem = ape1_type == 1u ? sizeof(uint16_t) : sizeof(float);
        const uint64_t ape0_bytes = (uint64_t)ratio * width0 * ape0_elem;
        const uint64_t ape1_bytes = (uint64_t)ratio * width1 * ape1_elem;
        if (weight0_kv_offset > model_size || weight0_bytes > model_size - weight0_kv_offset ||
            weight0_score_offset > model_size || weight0_bytes > model_size - weight0_score_offset ||
            weight1_kv_offset > model_size || weight1_bytes > model_size - weight1_kv_offset ||
            weight1_score_offset > model_size || weight1_bytes > model_size - weight1_score_offset ||
            ape0_offset > model_size || ape0_bytes > model_size - ape0_offset ||
            ape1_offset > model_size || ape1_bytes > model_size - ape1_offset) {
            return -1;
        }

        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> out0kvbuf = ds4_gpu_tensor_buffer(out0_kv);
        id<MTLBuffer> out0scbuf = ds4_gpu_tensor_buffer(out0_score);
        id<MTLBuffer> out1kvbuf = ds4_gpu_tensor_buffer(out1_kv);
        id<MTLBuffer> out1scbuf = ds4_gpu_tensor_buffer(out1_score);
        id<MTLBuffer> state0kvbuf = ds4_gpu_tensor_buffer(state0_kv);
        id<MTLBuffer> state0scbuf = ds4_gpu_tensor_buffer(state0_score);
        id<MTLBuffer> state1kvbuf = ds4_gpu_tensor_buffer(state1_kv);
        id<MTLBuffer> state1scbuf = ds4_gpu_tensor_buffer(state1_score);
        if (!xbuf || !out0kvbuf || !out0scbuf || !out1kvbuf || !out1scbuf ||
            !state0kvbuf || !state0scbuf || !state1kvbuf || !state1scbuf ||
            ds4_gpu_tensor_bytes(x) < in_dim * sizeof(float) ||
            ds4_gpu_tensor_bytes(out0_kv) < (uint64_t)width0 * sizeof(float) ||
            ds4_gpu_tensor_bytes(out0_score) < (uint64_t)width0 * sizeof(float) ||
            ds4_gpu_tensor_bytes(out1_kv) < (uint64_t)width1 * sizeof(float) ||
            ds4_gpu_tensor_bytes(out1_score) < (uint64_t)width1 * sizeof(float) ||
            ds4_gpu_tensor_bytes(state0_kv) < (uint64_t)state_rows * width0 * sizeof(float) ||
            ds4_gpu_tensor_bytes(state0_score) < (uint64_t)state_rows * width0 * sizeof(float) ||
            ds4_gpu_tensor_bytes(state1_kv) < (uint64_t)state_rows * width1 * sizeof(float) ||
            ds4_gpu_tensor_bytes(state1_score) < (uint64_t)state_rows * width1 * sizeof(float)) {
            return -1;
        }

        uint64_t w0kv_inner = 0, w0sc_inner = 0, w1kv_inner = 0, w1sc_inner = 0;
        uint64_t ape0_inner = 0, ape1_inner = 0;
        id<MTLBuffer> w0kvbuf = ds4_gpu_wrap_model_range(model_map, model_size, weight0_kv_offset, weight0_bytes, &w0kv_inner);
        id<MTLBuffer> w0scbuf = ds4_gpu_wrap_model_range(model_map, model_size, weight0_score_offset, weight0_bytes, &w0sc_inner);
        id<MTLBuffer> w1kvbuf = ds4_gpu_wrap_model_range(model_map, model_size, weight1_kv_offset, weight1_bytes, &w1kv_inner);
        id<MTLBuffer> w1scbuf = ds4_gpu_wrap_model_range(model_map, model_size, weight1_score_offset, weight1_bytes, &w1sc_inner);
        id<MTLBuffer> ape0buf = ds4_gpu_wrap_model_range(model_map, model_size, ape0_offset, ape0_bytes, &ape0_inner);
        id<MTLBuffer> ape1buf = ds4_gpu_wrap_model_range(model_map, model_size, ape1_offset, ape1_bytes, &ape1_inner);
        if (!w0kvbuf || !w0scbuf || !w1kvbuf || !w1scbuf || !ape0buf || !ape1buf) return -1;

        ds4_gpu_f16_matvec_args mv_args = ds4_gpu_make_f16_mv_args(in_dim, width0);
        mv_args.nr0 = 2;
        ds4_gpu_dsv4_compressor_store_one_args store0_args = {
            .width = width0,
            .ratio = ratio,
            .pos = pos,
            .ape_type = ape0_type,
        };
        ds4_gpu_dsv4_compressor_store_one_args store1_args = {
            .width = width1,
            .ratio = ratio,
            .pos = pos,
            .ape_type = ape1_type,
        };
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_mul_mv_pipeline(
            "kernel_mul_mv_f16_f32_quad_compressor_store_4", 8);
        if (!pipeline) return -1;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return -1;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&mv_args length:sizeof(mv_args) atIndex:0];
        [enc setBytes:&store0_args length:sizeof(store0_args) atIndex:1];
        [enc setBytes:&store1_args length:sizeof(store1_args) atIndex:2];
        [enc setBuffer:w0kvbuf offset:(NSUInteger)w0kv_inner atIndex:3];
        [enc setBuffer:w0scbuf offset:(NSUInteger)w0sc_inner atIndex:4];
        [enc setBuffer:w1kvbuf offset:(NSUInteger)w1kv_inner atIndex:5];
        [enc setBuffer:w1scbuf offset:(NSUInteger)w1sc_inner atIndex:6];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:7];
        [enc setBuffer:out0kvbuf offset:ds4_gpu_tensor_offset(out0_kv) atIndex:8];
        [enc setBuffer:out0scbuf offset:ds4_gpu_tensor_offset(out0_score) atIndex:9];
        [enc setBuffer:out1kvbuf offset:(NSUInteger)ds4_gpu_tensor_offset(out1_kv) atIndex:10];
        [enc setBuffer:out1scbuf offset:(NSUInteger)ds4_gpu_tensor_offset(out1_score) atIndex:11];
        [enc setBuffer:ape0buf offset:(NSUInteger)ape0_inner atIndex:12];
        [enc setBuffer:ape1buf offset:(NSUInteger)ape1_inner atIndex:13];
        [enc setBuffer:state0kvbuf offset:ds4_gpu_tensor_offset(state0_kv) atIndex:14];
        [enc setBuffer:state0scbuf offset:ds4_gpu_tensor_offset(state0_score) atIndex:15];
        [enc setBuffer:state1kvbuf offset:ds4_gpu_tensor_offset(state1_kv) atIndex:16];
        [enc setBuffer:state1scbuf offset:ds4_gpu_tensor_offset(state1_score) atIndex:17];
        [enc setThreadgroupMemoryLength:32u * 2u * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(
                ((NSUInteger)width0 + (NSUInteger)width1 + 1u) / 2u, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(32, 8, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(
                cb, owned, "F16 quad matvec compressor state store")) {
            return -1;
        }
    }

    return 1;
}

/* Decode-only emit-path fusion: finalize the freshly pooled attention and
 * indexer compressor rows (norm + rope + fp8/commit + qat) in one dispatch
 * instead of seven.  Bit-exact vs the separate dispatches; see the kernel
 * comment.  Returns 1 when the fused dispatch ran, 0 to fall back. */
int ds4_gpu_dsv4_comp_row_finalize_tensor(
        ds4_gpu_tensor       *attn_stage,
        ds4_gpu_tensor       *attn_cache,
        uint32_t              attn_comp_row,
        uint64_t              attn_norm_offset,
        ds4_gpu_tensor       *index_cache,
        uint32_t              index_comp_row,
        uint64_t              index_norm_offset,
        ds4_gpu_tensor       *attn_state_kv,
        ds4_gpu_tensor       *attn_state_score,
        ds4_gpu_tensor       *index_state_kv,
        ds4_gpu_tensor       *index_state_score,
        const void           *model_map,
        uint64_t              model_size,
        uint32_t              pos,
        uint32_t              n_rot,
        uint32_t              n_ctx_orig,
        float                 freq_base,
        float                 freq_scale,
        float                 ext_factor,
        float                 attn_factor,
        float                 beta_fast,
        float                 beta_slow,
        float                 rms_eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!attn_stage || !attn_cache || !index_cache || !model_map) return 0;

    @autoreleasepool {
        const uint64_t attn_norm_bytes = 512u * sizeof(float);
        const uint64_t index_norm_bytes = 128u * sizeof(float);
        if (attn_norm_offset > model_size ||
            attn_norm_bytes > model_size - attn_norm_offset ||
            index_norm_offset > model_size ||
            index_norm_bytes > model_size - index_norm_offset) {
            return 0;
        }
        if (!attn_state_kv || !attn_state_score || !index_state_kv ||
            !index_state_score) return 0;
        if (ds4_gpu_tensor_bytes(attn_state_kv) < 8u * 1024u * sizeof(float) ||
            ds4_gpu_tensor_bytes(attn_state_score) < 8u * 1024u * sizeof(float) ||
            ds4_gpu_tensor_bytes(index_state_kv) < 8u * 256u * sizeof(float) ||
            ds4_gpu_tensor_bytes(index_state_score) < 8u * 256u * sizeof(float)) {
            return 0;
        }
        if (ds4_gpu_tensor_bytes(attn_stage) < 512u * sizeof(float) ||
            ds4_gpu_tensor_bytes(index_cache) <
                ((uint64_t)index_comp_row + 1u) * 128u * sizeof(float) ||
            ds4_gpu_tensor_bytes(attn_cache) <
                ((uint64_t)attn_comp_row + 1u) * 512u * sizeof(uint16_t)) {
            return 0;
        }

        uint64_t attn_norm_inner = 0, index_norm_inner = 0;
        id<MTLBuffer> anbuf = ds4_gpu_wrap_model_range(
            model_map, model_size, attn_norm_offset, attn_norm_bytes, &attn_norm_inner);
        id<MTLBuffer> inbuf = ds4_gpu_wrap_model_range(
            model_map, model_size, index_norm_offset, index_norm_bytes, &index_norm_inner);
        if (!anbuf || !inbuf) return 0;

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_pipeline_or_die("kernel_dsv4_comp_row_finalize_f32");
        if (!pipeline) return 0;

        ds4_gpu_comp_finalize_args fin_args = {
            .rope = {
                .row_bytes = 0,
                .token_bytes = 0,
                .head_dim = 0,
                .n_dims = (int32_t)n_rot,
                .n_ctx_orig = (int32_t)n_ctx_orig,
                .inverse = 0,
                .pos0 = pos,
                .pos_step = 0,
                .freq_base = freq_base,
                .freq_scale = freq_scale,
                .ext_factor = ext_factor,
                .attn_factor = attn_factor,
                .beta_fast = beta_fast,
                .beta_slow = beta_slow,
            },
            .rms_eps = rms_eps,
            .pad0 = 0,
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&fin_args length:sizeof(fin_args) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(attn_stage)
                offset:ds4_gpu_tensor_offset(attn_stage) atIndex:1];
        [enc setBuffer:anbuf offset:(NSUInteger)attn_norm_inner atIndex:2];
        [enc setBuffer:ds4_gpu_tensor_buffer(attn_cache)
                offset:ds4_gpu_tensor_offset(attn_cache) +
                        (NSUInteger)attn_comp_row * 512u * sizeof(uint16_t) atIndex:3];
        [enc setBuffer:ds4_gpu_tensor_buffer(index_cache)
                offset:ds4_gpu_tensor_offset(index_cache) +
                        (NSUInteger)index_comp_row * 128u * sizeof(float) atIndex:4];
        [enc setBuffer:inbuf offset:(NSUInteger)index_norm_inner atIndex:5];
        [enc setBuffer:ds4_gpu_tensor_buffer(attn_state_kv)
                offset:ds4_gpu_tensor_offset(attn_state_kv) atIndex:6];
        [enc setBuffer:ds4_gpu_tensor_buffer(attn_state_score)
                offset:ds4_gpu_tensor_offset(attn_state_score) atIndex:7];
        [enc setBuffer:ds4_gpu_tensor_buffer(index_state_kv)
                offset:ds4_gpu_tensor_offset(index_state_kv) atIndex:8];
        [enc setBuffer:ds4_gpu_tensor_buffer(index_state_score)
                offset:ds4_gpu_tensor_offset(index_state_score) atIndex:9];
        [enc setThreadgroupMemoryLength:256u * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(2u + (4u * 1024u + 4u * 256u + 255u) / 256u, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "compressor row finalize")) {
            return 0;
        }
    }

    return 1;
}

/* Decode-only fusion: q_a/kv Q8 pair projection + F16 quad compressor
 * projection/store in one dispatch (both read the same normalized input).
 * Bit-exact vs the separate dispatches; see the kernel comment.  Returns
 * 1 when the fused dispatch ran, 0 when the caller must use the separate
 * paths, -1 on error. */
int ds4_gpu_qkv_pair_quad_compressor_store_tensor(
        ds4_gpu_tensor       *qr,
        ds4_gpu_tensor       *kv_raw,
        ds4_gpu_tensor       *out0_kv,
        ds4_gpu_tensor       *out0_score,
        ds4_gpu_tensor       *out1_kv,
        ds4_gpu_tensor       *out1_score,
        ds4_gpu_tensor       *state0_kv,
        ds4_gpu_tensor       *state0_score,
        ds4_gpu_tensor       *state1_kv,
        ds4_gpu_tensor       *state1_score,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              q_a_offset,
        uint64_t              kv_offset,
        uint64_t              weight0_kv_offset,
        uint64_t              weight0_score_offset,
        uint64_t              weight1_kv_offset,
        uint64_t              weight1_score_offset,
        uint64_t              ape0_offset,
        uint32_t              ape0_type,
        uint64_t              ape1_offset,
        uint32_t              ape1_type,
        uint32_t              in_dim,
        uint32_t              q_rank,
        uint32_t              kv_dim,
        uint32_t              width0,
        uint32_t              width1,
        const ds4_gpu_tensor *x,
        uint32_t              ratio,
        uint32_t              pos) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!qr || !kv_raw || !out0_kv || !out0_score || !out1_kv || !out1_score ||
        !state0_kv || !state0_score || !state1_kv || !state1_score ||
        !model_map || !x || ratio == 0u || (in_dim & 31u) != 0 ||
        (width0 & 1u) != 0 || (width1 & 1u) != 0) {
        return 0;
    }

    @autoreleasepool {
        const uint64_t q8_row_bytes = (in_dim / 32u) * 34u;
        const uint64_t f16_row_bytes = (uint64_t)in_dim * sizeof(uint16_t);
        const uint64_t q_a_bytes = (uint64_t)q_rank * q8_row_bytes;
        const uint64_t kv_bytes = (uint64_t)kv_dim * q8_row_bytes;
        const uint64_t weight0_bytes = (uint64_t)width0 * f16_row_bytes;
        const uint64_t weight1_bytes = (uint64_t)width1 * f16_row_bytes;
        const uint64_t state_rows = ratio == 4u ? 2u * ratio : ratio;
        const uint64_t ape0_bytes = (uint64_t)width0 * ratio *
                                    (ape0_type == 1u ? 2u : 4u);
        const uint64_t ape1_bytes = (uint64_t)width1 * ratio *
                                    (ape1_type == 1u ? 2u : 4u);
        if (q_a_offset > model_size || q_a_bytes > model_size - q_a_offset ||
            kv_offset > model_size || kv_bytes > model_size - kv_offset ||
            weight0_kv_offset > model_size ||
            weight0_bytes > model_size - weight0_kv_offset ||
            weight0_score_offset > model_size ||
            weight0_bytes > model_size - weight0_score_offset ||
            weight1_kv_offset > model_size ||
            weight1_bytes > model_size - weight1_kv_offset ||
            weight1_score_offset > model_size ||
            weight1_bytes > model_size - weight1_score_offset ||
            ape0_offset > model_size || ape0_bytes > model_size - ape0_offset ||
            ape1_offset > model_size || ape1_bytes > model_size - ape1_offset) {
            return -1;
        }
        if (ds4_gpu_tensor_bytes(qr) < (uint64_t)q_rank * sizeof(float) ||
            ds4_gpu_tensor_bytes(kv_raw) < (uint64_t)kv_dim * sizeof(float) ||
            ds4_gpu_tensor_bytes(out0_kv) < (uint64_t)width0 * sizeof(float) ||
            ds4_gpu_tensor_bytes(out0_score) < (uint64_t)width0 * sizeof(float) ||
            ds4_gpu_tensor_bytes(out1_kv) < (uint64_t)width1 * sizeof(float) ||
            ds4_gpu_tensor_bytes(out1_score) < (uint64_t)width1 * sizeof(float) ||
            ds4_gpu_tensor_bytes(x) < (uint64_t)in_dim * sizeof(float) ||
            ds4_gpu_tensor_bytes(state0_kv) < state_rows * width0 * sizeof(float) ||
            ds4_gpu_tensor_bytes(state0_score) < state_rows * width0 * sizeof(float) ||
            ds4_gpu_tensor_bytes(state1_kv) < state_rows * width1 * sizeof(float) ||
            ds4_gpu_tensor_bytes(state1_score) < state_rows * width1 * sizeof(float)) {
            return -1;
        }

        uint64_t q_a_inner = 0, kv_inner = 0;
        uint64_t w0kv_inner = 0, w0sc_inner = 0, w1kv_inner = 0, w1sc_inner = 0;
        uint64_t ape0_inner = 0, ape1_inner = 0;
        id<MTLBuffer> qw0buf = ds4_gpu_wrap_model_range(model_map, model_size, q_a_offset, q_a_bytes, &q_a_inner);
        id<MTLBuffer> qw1buf = ds4_gpu_wrap_model_range(model_map, model_size, kv_offset, kv_bytes, &kv_inner);
        id<MTLBuffer> w0kvbuf = ds4_gpu_wrap_model_range(model_map, model_size, weight0_kv_offset, weight0_bytes, &w0kv_inner);
        id<MTLBuffer> w0scbuf = ds4_gpu_wrap_model_range(model_map, model_size, weight0_score_offset, weight0_bytes, &w0sc_inner);
        id<MTLBuffer> w1kvbuf = width1 != 0u
            ? ds4_gpu_wrap_model_range(model_map, model_size, weight1_kv_offset,
                                       weight1_bytes, &w1kv_inner)
            : w0kvbuf;
        id<MTLBuffer> w1scbuf = width1 != 0u
            ? ds4_gpu_wrap_model_range(model_map, model_size, weight1_score_offset,
                                       weight1_bytes, &w1sc_inner)
            : w0scbuf;
        id<MTLBuffer> ape0buf = ds4_gpu_wrap_model_range(model_map, model_size, ape0_offset, ape0_bytes, &ape0_inner);
        id<MTLBuffer> ape1buf = width1 != 0u
            ? ds4_gpu_wrap_model_range(model_map, model_size, ape1_offset,
                                       ape1_bytes, &ape1_inner)
            : ape0buf;
        if (width1 == 0u) {
            w1kv_inner = w0kv_inner;
            w1sc_inner = w0sc_inner;
            ape1_inner = ape0_inner;
        }
        if (!qw0buf || !qw1buf || !w0kvbuf || !w0scbuf ||
            !w1kvbuf || !w1scbuf || !ape0buf || !ape1buf) return -1;

        ds4_gpu_q8_0_matvec_args args0 = ds4_gpu_make_q8_0_mv_args(in_dim, q_rank);
        ds4_gpu_q8_0_matvec_args args1 = ds4_gpu_make_q8_0_mv_args(in_dim, kv_dim);
        args0.nr0 = 2;
        args1.nr0 = 2;
        ds4_gpu_f16_matvec_args cargs = ds4_gpu_make_f16_mv_args(in_dim, width0);
        cargs.nr0 = 2;
        ds4_gpu_dsv4_compressor_store_one_args store0_args = {
            .width = width0,
            .ratio = ratio,
            .pos = pos,
            .ape_type = ape0_type,
        };
        ds4_gpu_dsv4_compressor_store_one_args store1_args = {
            .width = width1,
            .ratio = ratio,
            .pos = pos,
            .ape_type = ape1_type,
        };
        const uint32_t max_out = q_rank > kv_dim ? q_rank : kv_dim;
        const uint32_t pair_vtgs = (max_out + 1u) / 2u;
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_mul_mv_pipeline(
            "kernel_dsv4_qkv_pair_quad_compressor_store_q8_0", 8);
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args0 length:sizeof(args0) atIndex:0];
        [enc setBytes:&args1 length:sizeof(args1) atIndex:1];
        [enc setBytes:&cargs length:sizeof(cargs) atIndex:2];
        [enc setBytes:&store0_args length:sizeof(store0_args) atIndex:3];
        [enc setBytes:&store1_args length:sizeof(store1_args) atIndex:4];
        [enc setBytes:&pair_vtgs length:sizeof(pair_vtgs) atIndex:5];
        [enc setBuffer:qw0buf offset:(NSUInteger)q_a_inner atIndex:6];
        [enc setBuffer:qw1buf offset:(NSUInteger)kv_inner atIndex:7];
        [enc setBuffer:w0kvbuf offset:(NSUInteger)w0kv_inner atIndex:8];
        [enc setBuffer:w0scbuf offset:(NSUInteger)w0sc_inner atIndex:9];
        [enc setBuffer:w1kvbuf offset:(NSUInteger)w1kv_inner atIndex:10];
        [enc setBuffer:w1scbuf offset:(NSUInteger)w1sc_inner atIndex:11];
        [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:12];
        [enc setBuffer:ds4_gpu_tensor_buffer(qr) offset:ds4_gpu_tensor_offset(qr) atIndex:13];
        [enc setBuffer:ds4_gpu_tensor_buffer(kv_raw) offset:ds4_gpu_tensor_offset(kv_raw) atIndex:14];
        [enc setBuffer:ds4_gpu_tensor_buffer(out0_kv) offset:ds4_gpu_tensor_offset(out0_kv) atIndex:15];
        [enc setBuffer:ds4_gpu_tensor_buffer(out0_score) offset:ds4_gpu_tensor_offset(out0_score) atIndex:16];
        [enc setBuffer:ds4_gpu_tensor_buffer(out1_kv) offset:ds4_gpu_tensor_offset(out1_kv) atIndex:17];
        [enc setBuffer:ds4_gpu_tensor_buffer(out1_score) offset:ds4_gpu_tensor_offset(out1_score) atIndex:18];
        [enc setBuffer:ape0buf offset:(NSUInteger)ape0_inner atIndex:19];
        [enc setBuffer:ape1buf offset:(NSUInteger)ape1_inner atIndex:20];
        [enc setBuffer:ds4_gpu_tensor_buffer(state0_kv) offset:ds4_gpu_tensor_offset(state0_kv) atIndex:21];
        [enc setBuffer:ds4_gpu_tensor_buffer(state0_score) offset:ds4_gpu_tensor_offset(state0_score) atIndex:22];
        [enc setBuffer:ds4_gpu_tensor_buffer(state1_kv) offset:ds4_gpu_tensor_offset(state1_kv) atIndex:23];
        [enc setBuffer:ds4_gpu_tensor_buffer(state1_score) offset:ds4_gpu_tensor_offset(state1_score) atIndex:24];
        [enc setThreadgroupMemoryLength:2u * 2u * 2u * 32u * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(
                (NSUInteger)(pair_vtgs + 1u) / 2u +
                ((NSUInteger)width0 + (NSUInteger)width1 + 1u) / 2u, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(32, 8, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(
                cb, owned, "qkv pair + quad compressor store")) {
            return -1;
        }
    }

    return 1;
}

/* llms F32_ROWS (apply_ds4_f32_rows.py): the single-row F32 matvec of ds4_gpu_matmul_f32_tensor for `rows` rows in one dispatch
