        ds4_gpu_mv_dispatch mv_dispatch = ds4_gpu_make_plain_mv_dispatch(in_dim, 1);
        if (ds4_gpu_plain_mv_single_row(out_dim)) { mv_dispatch.nr0 = 1; mv_dispatch.smem = 32u * sizeof(float); }
        const NSUInteger lean_simdgroups = apply_plain_mv_lean(&mv_dispatch, in_dim, out_dim, 1);   /* the single-row dispatch's shape */
        mv_args.nr0 = mv_dispatch.nr0;
        const uint64_t pad8_tokens = pad8_rows(rows, in_dim, out_dim, sizeof(float), xbuf, ds4_gpu_tensor_offset(x), outbuf, ds4_gpu_tensor_offset(out));   /* llms PAD8 */
        id<MTLBuffer> router_rb_now = nil;   /* llms ROUTER_MX8K: the router's BF16 copy when this call reads it */
        {   /* llms ROWS_RBF (apply_rows_rbf.py): 2-3 router rows; optional four-row BF16 before T4 selection */
            if (rows >= 2u && (rows <= 4u || kr8_f16k_name(rows, 1)) && !llms_alt_off("rrbf")) {   /* ROWS_RBF + ROWS_RBF4 adopted; the switches removed 10-27; llms KR8C: 5..8 */
                id<MTLBuffer> rb = router_bf16_copy(model_map, model_size, weight_offset, in_dim, out_dim, mv_dispatch.function_name); router_rb_now = rb;   /* llms ROUTER_MX8K */
                if (rb) { mv_dispatch.function_name = "kernel_mul_mv_bf16_f32_4"; mv_args.nb00 = 2; mv_args.nb01 = in_dim * 2u;
                          mv_args.nb02 = mv_args.nb01 * out_dim; mv_args.nb03 = mv_args.nb02; wbuf = rb; inner_offset = 0; }
            }
        }
        if (mv_args.nb00 == sizeof(float) && t4_wants(pad8_tokens, out_dim)) {   /* BF16 uses the existing row kernel; F32 keeps T4. */
            ds4_gpu_q8_0_matvec_args t4a = mv_args;
            if (rows_t4_on() == 3) t4a.nb11 = 0;   /* canary */
            id<MTLComputeCommandEncoder> enc4 = ds4_gpu_compute_encoder(cb);
            if (encode_t4(enc4, 1, &t4a, sizeof(t4a), mv_dispatch, lean_simdgroups, wbuf, (NSUInteger)inner_offset, xbuf,
                               ds4_gpu_tensor_offset(x),
                               outbuf, ds4_gpu_tensor_offset(out), out_dim, pad8_tokens)) {
                ds4_gpu_end_compute_encoder(cb, enc4);
                if (!ds4_gpu_finish_command_buffer(cb, owned, "llms F32 rows t4 matvec")) return 0;
                return 1;
            }
            ds4_gpu_end_compute_encoder(cb, enc4);
        }
        int f16k2_now = 0;   /* llms F16_K2 (apply_f16k2.py): the two-row k-family for the generic F16 / BF16 matvecs; ALT f16k2 */
        {
            const int isf16 = !strcmp(mv_dispatch.function_name, "kernel_mul_mv_f16_f32_4"), isbf16 = !strcmp(mv_dispatch.function_name, "kernel_mul_mv_bf16_f32_4");
            if ((rows == 2u || (rows == 3u && k3x_on()) || (rows == 4u && k4x_on()) || kr8_f16k_name((uint32_t)rows, 1) || kr8_f16k_name((uint32_t)rows, 0)) && out_dim >= 128u && (in_dim % 32u) == 0 && (isf16 || isbf16) && !llms_alt_off("f16k2")) {   /* llms K3X */
                mv_dispatch.function_name = rows >= 5u && kr8_f16k_name((uint32_t)rows, isbf16) ? kr8_f16k_name((uint32_t)rows, isbf16) : rows == 4u ? (isbf16 ? "kernel_llms_bf16_mv_k4_r2" : "kernel_llms_f16_mv_k4_r2") : rows == 3u ? (isbf16 ? "kernel_llms_bf16_mv_k3_r2" : "kernel_llms_f16_mv_k3_r2") : isbf16 ? "kernel_llms_bf16_mv_k2_r2" : "kernel_llms_f16_mv_k2_r2"; mv_dispatch.nr0 = 2; mv_dispatch.nsg = in_dim >= 4096u ? 4 : 2; mv_dispatch.smem = 2u * 32u * sizeof(float);
                mv_args.nr0 = 2; f16k2_now = 1;
                { const int fnr = rows == 2u ? f16k2_nr_on() : 0;   /* llms F16K2_NR: r4 / r8 at two rows */
                  if (fnr) { mv_dispatch.function_name = isbf16 ? (fnr == 8 ? "kernel_llms_bf16_mv_k2_r8" : "kernel_llms_bf16_mv_k2_r4") : (fnr == 8 ? "kernel_llms_f16_mv_k2_r8" : "kernel_llms_f16_mv_k2_r4");
                             mv_dispatch.nr0 = fnr; mv_args.nr0 = fnr; mv_dispatch.smem = (uint32_t)fnr * 32u * sizeof(float); f16k2_nr_calls++; } }
            }
        }
        if (router_rb_now && f16k2_now && wbuf == router_rb_now && router_mx8k_on() && !llms_alt_off("mx8k") && !strncmp(mv_dispatch.function_name, "kernel_llms_bf16_mv_k", 21)) {   /* llms ROUTER_MX8K; ALT mx8k (apply_mx8kalt.py) */
            char nm[64]; snprintf(nm, sizeof nm, "kernel_llms_mx8_mv_k%s", mv_dispatch.function_name + 21);
            id<MTLBuffer> mb = router_mx8k_copy(router_rb_now, in_dim, out_dim);
            id<MTLComputePipelineState> pm = mb ? ds4_gpu_get_mul_mv_pipeline(nm, mv_dispatch.nsg) : nil;
            if (pm) { static char names[8][64]; static int nn; int k = 0; for (; k < nn; k++) if (!strcmp(names[k], nm)) break;
                      if (k == nn && nn < 8) { snprintf(names[nn], 64, "%s", nm); nn++; }
                      if (k < 8) { mv_dispatch.function_name = names[k]; mv_args.nb00 = 1; mv_args.nb01 = in_dim + in_dim / 32u;
                                   mv_args.nb02 = mv_args.nb01 * out_dim; mv_args.nb03 = mv_args.nb02; wbuf = mb; inner_offset = 0; router_mx8k_calls++; } else router_mx8k_fallbacks++; }
            else router_mx8k_fallbacks++;
