        id<MTLComputePipelineState> pipeline = ds4_gpu_get_mul_mv_pipeline(mv_dispatch.function_name, mv_dispatch.nsg);
        if (!pipeline) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        if (timeline_shapes_on()) snprintf(timeline_shape_tag, sizeof timeline_shape_tag, "@K%llu_R%llu_C%u", (unsigned long long)in_dim, (unsigned long long)out_dim, (unsigned)rows);   /* llms TL_NAMES: the F16 / BF16 rows matvec */
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&mv_args length:sizeof(mv_args) atIndex:0];
        [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        if (mv_dispatch.smem) [enc setThreadgroupMemoryLength:mv_dispatch.smem atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)mv_dispatch.nr0 - 1u) / (NSUInteger)mv_dispatch.nr0, f16k2_now ? 1u : (NSUInteger)rows, 1)
             threadsPerThreadgroup:MTLSizeMake(32, f16k2_now ? (NSUInteger)mv_dispatch.nsg : lean_simdgroups, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned, "llms F32 rows matvec")) return 0;
        return 1;
    }
}

/* llms ROUTER_BF16 (apply_router_bf16.py): BF16 copies of the routers, made on first use; nil = use the F32 weights */
static int router_bf16_count; static uint64_t router_bf16_offsets[64]; static id<MTLBuffer> router_bf16_buffers[64];   /* adopted; the switch removed 10-27 */

/* llms ROUTER_MX8K (apply_router_mx8k.py): the routers' MX8 copies for the k-row MX8 kernels; off unless LLMS_DS4_ROUTER_MX8K=1 */
static int router_mx8k_state = -1, router_mx8k_count; static const void *router_mx8k_keys[64]; static id<MTLBuffer> router_mx8k_buffers[64];
static int router_mx8k_on(void) {
    if (router_mx8k_state < 0) { const char *e = getenv("LLMS_DS4_ROUTER_MX8K"); router_mx8k_state = e && *e && *e != '0';
        if (router_mx8k_state) { fprintf(stderr, "llms: router mx8k (the 2-4-row router matvecs on MX8 copies: int8 codes + a power-of-two scale a 32-block)\n");
            atexit_b(^{ fprintf(stderr, "llms router mx8k: %llu calls on MX8 copies (%d routers, %.1f MB), %llu fell back to BF16\n", (unsigned long long)router_mx8k_calls,
                                router_mx8k_count, router_mx8k_count * 384.0 * 5280.0 / 1e6, (unsigned long long)router_mx8k_fallbacks); }); } }
    return router_mx8k_state;
}
static id<MTLBuffer> router_mx8k_copy(id<MTLBuffer> rb, uint64_t in_dim, uint64_t out_dim) {   /* from the BF16 copy, with the probe's formula: the same q x 2^e */
    if (!rb || in_dim != 5120u || out_dim != 384u) return nil;
    const void *key = (__bridge const void *)rb;
    for (int i = 0; i < router_mx8k_count; i++) if (router_mx8k_keys[i] == key) return router_mx8k_buffers[i];
    if (router_mx8k_count >= 64) return nil;
    const uint64_t row = in_dim + in_dim / 32u;
    id<MTLBuffer> b = [g_device newBufferWithLength:(NSUInteger)(row * out_dim) options:MTLResourceStorageModeShared];
    if (!b) return nil;
    const uint16_t *src = (const uint16_t *)[rb contents]; int8_t *dst = (int8_t *)[b contents];
    for (uint64_t r = 0; r < out_dim; r++) for (uint64_t k0 = 0; k0 < in_dim; k0 += 32u) {
        float w[32]; float mx = 0.0f;
        for (int j = 0; j < 32; j++) { const uint32_t u = (uint32_t)src[r * in_dim + k0 + (uint64_t)j] << 16; memcpy(&w[j], &u, 4); if (fabsf(w[j]) > mx) mx = fabsf(w[j]); }
        int e = 0; if (mx > 0.0f) e = (int)ceilf(log2f(mx / 127.0f));
        if (e < -126) e = -126;
        if (e > 127) e = 127;
        const float sc = ldexpf(1.0f, e);
        for (int j = 0; j < 32; j++) { float q = rintf(w[j] / sc); if (q > 127.0f) q = 127.0f; if (q < -127.0f) q = -127.0f; dst[r * row + k0 + (uint64_t)j] = (int8_t)q; }
        dst[r * row + in_dim + k0 / 32u] = (int8_t)e;
    }
    router_mx8k_keys[router_mx8k_count] = key; router_mx8k_buffers[router_mx8k_count] = b; router_mx8k_count++;
    return b;
}
static int llms_alt_off(const char *name);
static id<MTLBuffer> router_bf16_copy(const void *model_map, uint64_t model_size, uint64_t off, uint64_t in_dim, uint64_t out_dim, const char *fn) {
    if (in_dim != 5120u || out_dim != 384u || strcmp(fn, "kernel_mul_mv_f32_f32_4") || llms_alt_off("rbf")) return nil;
    for (int i = 0; i < router_bf16_count; i++) if (router_bf16_offsets[i] == off) return router_bf16_buffers[i];
    if (router_bf16_count >= 64 || off > model_size || in_dim * out_dim * 4u > model_size - off) return nil;
    const uint64_t n = in_dim * out_dim;
    id<MTLBuffer> b = [g_device newBufferWithLength:(NSUInteger)(n * 2u) options:MTLResourceStorageModeShared];
    if (!b) return nil;
    const uint32_t *src = (const uint32_t *)((const char *)model_map + off); uint16_t *dst = (uint16_t *)[b contents]; uint64_t lossy = 0;
    for (uint64_t r = 0; r < out_dim; r++) {
        for (uint64_t k = 0; k < in_dim; k++) { const uint32_t v = src[r * in_dim + k]; lossy += (v & 0xFFFFu) != 0; dst[r * in_dim + k] = (uint16_t)(v >> 16); }
    }
    if (lossy) { fprintf(stderr, "llms router bf16: %llu of %llu weights at offset %llu are not exact BF16 -- F32 kept\n", (unsigned long long)lossy,
                         (unsigned long long)n, (unsigned long long)off); router_bf16_offsets[router_bf16_count] = off; router_bf16_buffers[router_bf16_count] = nil; router_bf16_count++; return nil; }
    {   /* llms ROUTER_MX8 (apply_router_mx8.py): a FIDELITY PROBE -- the BF16 copy re-rounded to MX8 (per row, 32-input blocks, a power-of-two scale, int8 values: exact in BF16); off unless LLMS_DS4_ROUTER_MX8=1; the kernel and the bytes read are unchanged*/
        static int mx8 = -1; if (mx8 < 0) { const char *e = getenv("LLMS_DS4_ROUTER_MX8"); mx8 = e && *e && *e != '0'; }
        if (mx8) {
            static uint64_t blocks; static double err_sum, err_max;
            for (uint64_t r = 0; r < out_dim; r++) for (uint64_t k0 = 0; k0 < in_dim; k0 += 32u) {
                float w[32]; float mx = 0.0f;
                for (int j = 0; j < 32; j++) { const uint32_t u = (uint32_t)dst[r * in_dim + k0 + (uint64_t)j] << 16; memcpy(&w[j], &u, 4); if (fabsf(w[j]) > mx) mx = fabsf(w[j]); }
                if (mx == 0.0f) continue;
                const float sc = exp2f(ceilf(log2f(mx / 127.0f))); double num = 0.0, den = 0.0;
                for (int j = 0; j < 32; j++) {
                    float q = rintf(w[j] / sc); if (q > 127.0f) q = 127.0f; if (q < -127.0f) q = -127.0f;
                    const float v = q * sc; uint32_t u; memcpy(&u, &v, 4); dst[r * in_dim + k0 + (uint64_t)j] = (uint16_t)(u >> 16);
                    num += (double)(v - w[j]) * (v - w[j]); den += (double)w[j] * w[j];
                }
                const double re = den > 0.0 ? sqrt(num / den) : 0.0; err_sum += re; if (re > err_max) err_max = re; blocks++;
            }
            static int reg; if (!reg) { reg = 1; atexit_b(^{ fprintf(stderr, "llms router mx8: %llu blocks re-rounded, block relative error mean %.5f max %.5f (FIDELITY PROBE)\n",
                                                                  (unsigned long long)blocks, blocks ? err_sum / (double)blocks : 0.0, err_max); }); }
        }
    }
    router_bf16_offsets[router_bf16_count] = off; router_bf16_buffers[router_bf16_count] = b; router_bf16_count++;
    return b;
}
int ds4_gpu_matmul_f32_tensor(
        ds4_gpu_tensor       *out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        uint64_t                n_tok) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (in_dim > UINT32_MAX || out_dim > UINT32_MAX || n_tok == 0 || n_tok > UINT32_MAX) return 0;
    if (in_dim > UINT64_MAX / n_tok / sizeof(float) ||
        out_dim > UINT64_MAX / n_tok / sizeof(float)) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t x_bytes = n_tok * in_dim * sizeof(float);
        const uint64_t out_bytes = n_tok * out_dim * sizeof(float);
        if (!xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes) {
            fprintf(stderr, "ds4: Metal F32 tensor matmul received undersized activation buffers\n");
            return 0;
        }

        const uint64_t row_bytes = in_dim * sizeof(float);
        const uint64_t weight_bytes = row_bytes * out_dim;
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal F32 tensor matmul range is outside the mapped model\n");
            return 0;
        }

        uint64_t inner_offset = 0;
        id<MTLBuffer> wbuf =
            ds4_gpu_wrap_model_range(model_map,
                                     model_size,
                                     weight_offset,
                                     weight_bytes,
                                     &inner_offset);
        if (!wbuf) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        if (n_tok == 1) {
            ds4_gpu_q8_0_matvec_args mv_args = ds4_gpu_make_f32_mv_args(in_dim, out_dim, 1);
            ds4_gpu_mv_dispatch mv_dispatch = ds4_gpu_make_plain_mv_dispatch(in_dim, 1);
            if (ds4_gpu_plain_mv_single_row(out_dim)) {
                mv_dispatch.nr0 = 1;
                mv_dispatch.smem = 32u * sizeof(float);
            }
            const NSUInteger lean_simdgroups = apply_plain_mv_lean(&mv_dispatch, in_dim, out_dim, 1);   /* llms PLAIN_MV_LEAN */
            mv_args.nr0 = mv_dispatch.nr0;
            {   /* llms ROUTER_BF16: the same template, rows, simdgroups and reduction tree on the exact BF16 copy */
                id<MTLBuffer> router_bf16_buffer = router_bf16_copy(model_map, model_size, weight_offset, in_dim, out_dim, mv_dispatch.function_name);
                if (router_bf16_buffer) { mv_dispatch.function_name = "kernel_mul_mv_bf16_f32_4"; mv_args.nb00 = 2; mv_args.nb01 = in_dim * 2u;
                                mv_args.nb02 = mv_args.nb01 * out_dim; mv_args.nb03 = mv_args.nb02; wbuf = router_bf16_buffer; inner_offset = 0; }
            }
            id<MTLComputePipelineState> pipeline =
                ds4_gpu_get_mul_mv_pipeline(mv_dispatch.function_name, mv_dispatch.nsg);
            if (!pipeline) return 0;

            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:pipeline];
            [enc setBytes:&mv_args length:sizeof(mv_args) atIndex:0];
            [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
            [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
            [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
            if (mv_dispatch.smem) {
                [enc setThreadgroupMemoryLength:mv_dispatch.smem atIndex:0];
            }
            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)mv_dispatch.nr0 - 1u) / (NSUInteger)mv_dispatch.nr0,
                                                  1,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, lean_simdgroups, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            if (!ds4_gpu_finish_command_buffer(cb, owned, "F32 tensor matvec")) return 0;
            return 1;
        }

        const bool router_batch = in_dim == 5120u && out_dim == 384u &&
            n_tok >= 32u && !g_quality_mode &&
            !getenv("DS4_METAL_DISABLE_V41_ROUTER_BATCH");
        if (router_batch && n_tok >= 256u && !getenv("DS4_METAL_DISABLE_V41_ROUTER_MM")) {
            const bool bc_out = (n_tok % 32u) != 0;
            id<MTLComputePipelineState> pipeline =
                ds4_gpu_get_mul_mm_pipeline("kernel_mul_mm_f32_f32_full", false, bc_out);
            if (!pipeline) return 0;
            ds4_gpu_mul_mm_args args = ds4_gpu_make_mm_args(in_dim, out_dim, n_tok, row_bytes);
            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            if (!enc) return 0;
            [enc setComputePipelineState:pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
            [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
            [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
            [enc setThreadgroupMemoryLength:12288u atIndex:0];
            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_tok + 31u)/32u,
                                                  (NSUInteger)out_dim/64u, 1)
                 threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
            return ds4_gpu_finish_command_buffer(cb, owned, "F32 router prefill matmul");
        }

        if ((n_tok <= 8 || router_batch) && (in_dim % 128u) == 0) {
            const int16_t nsg = router_batch ? 2 : ds4_gpu_mv_ext_nsg();
            const int16_t nxpsg = ds4_gpu_mv_ext_nxpsg(in_dim, n_tok);
            const int16_t r1ptg = ds4_gpu_mv_ext_r1ptg(n_tok);
            const char *fn_name = ds4_gpu_mv_ext_f32_name(r1ptg);
            id<MTLComputePipelineState> pipeline =
                fn_name ? ds4_gpu_get_mul_mv_ext_pipeline(fn_name, nsg, nxpsg) : nil;
            if (!pipeline) return 0;

            const int16_t nypsg = 32 / nxpsg;
            const uint64_t r0ptg = (uint64_t)nypsg * (uint64_t)nsg;
            ds4_gpu_mul_mv_ext_args args =
                ds4_gpu_make_mv_ext_args(in_dim, out_dim, n_tok, sizeof(float), row_bytes);

            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
            [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
            [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)r0ptg - 1u) / (NSUInteger)r0ptg,
                                                  ((NSUInteger)n_tok + (NSUInteger)r1ptg - 1u) / (NSUInteger)r1ptg,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)nsg, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            if (!ds4_gpu_finish_command_buffer(cb, owned, "F32 tensor mul_mv_ext")) return 0;
            return 1;
        }

        /* Generic multi-row path (GLM prefill shapes: one grid row per
         * token through the plain matvec pipeline). */
        {
            ds4_gpu_q8_0_matvec_args mv_args = ds4_gpu_make_f32_mv_args(in_dim, out_dim, n_tok);
            ds4_gpu_mv_dispatch mv_dispatch = ds4_gpu_make_plain_mv_dispatch(in_dim, 1);
            mv_args.nr0 = mv_dispatch.nr0;
            id<MTLComputePipelineState> pipeline =
                ds4_gpu_get_mul_mv_pipeline(mv_dispatch.function_name, mv_dispatch.nsg);
            if (!pipeline) return 0;

            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:pipeline];
            [enc setBytes:&mv_args length:sizeof(mv_args) atIndex:0];
            [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
            [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
            [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
            if (mv_dispatch.smem) {
                [enc setThreadgroupMemoryLength:mv_dispatch.smem atIndex:0];
            }
            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)mv_dispatch.nr0 - 1u) / (NSUInteger)mv_dispatch.nr0,
                                                  (NSUInteger)n_tok,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)mv_dispatch.nsg, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            if (!ds4_gpu_finish_command_buffer(cb, owned, "F32 tensor matmul")) return 0;
        }
    }

    return 1;
}

int ds4_gpu_repeat_hc_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *row,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !row || n_embd == 0 || n_hc == 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> rowbuf = ds4_gpu_tensor_buffer(row);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t row_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t out_bytes = row_bytes * n_hc;
        if (!rowbuf || !outbuf ||
            ds4_gpu_tensor_bytes(row) < row_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes) {
            fprintf(stderr, "ds4: Metal HC repeat received undersized buffers\n");
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        if (!ds4_gpu_encode_repeat_hc_embedding(cb,
                                                  rowbuf,
                                                  ds4_gpu_tensor_offset(row),
                                                  outbuf,
                                                  ds4_gpu_tensor_offset(out),
                                                  1,
                                                  n_embd,
                                                  n_hc)) {
            return 0;
        }
        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC repeat")) return 0;
    }

    return 1;
}

int ds4_gpu_repeat_hc_rows_tensor(
