int ds4_gpu_dsv41_attention_output_batch(
        ds4_gpu_tensor *out, ds4_gpu_tensor *low,
        const void *model_map, uint64_t model_size,
        uint64_t out_a_offset, uint64_t out_b_offset,
        const ds4_gpu_tensor *heads, uint32_t n_tokens) {
    /* One-row verify uses the same low-projection codec owner as ordinary decode (adopted, the switch removed 10-27). */
    const uint32_t rag_r = ds4_gpu_llms_ragged_r(out_a_offset, out_b_offset);   /* llms RAGGED_AO */
    if (n_tokens == 1u) {
        return ds4_gpu_attention_output_low_q8_tensor(low, model_map, model_size,
                   out_a_offset, 4096, rag_r, 8, heads) &&
               ds4_gpu_dsv41_quantize(low, 8u * rag_r, 1, DS4_V41_BF16) &&
               ds4_gpu_matmul_q8_0_tensor(out, model_map, model_size,
                   out_b_offset, 8u * rag_r, 5120, low, 1);
    }
    if (rag_r != 1024u) { fprintf(stderr, "llms ragged ao: the Q8_0 batch attention output reached a rank-%u pair (rows %u): that is the full-rank original\n", rag_r, n_tokens); abort(); }
    return ds4_gpu_attention_output_q8_batch_impl(out, low, low, low,
        model_map, model_size, out_a_offset, out_b_offset, 4096, 1024,
        8, 5120, heads, n_tokens, true, 0, 0);
}

int ds4_gpu_dsv41_attention_output_tp_batch(
        ds4_gpu_tensor *out, ds4_gpu_tensor *low,
        const void *model_map, uint64_t model_size,
        uint64_t out_a_offset, uint64_t out_b_offset,
        const ds4_gpu_tensor *heads, uint32_t n_tokens, uint32_t tp_rank) {
    const uint64_t shard_bytes = UINT64_C(4) * 1024 * (4096 / 32 * 34);
    if (tp_rank > 1 || out_a_offset > model_size ||
        shard_bytes * 2u > model_size - out_a_offset) return 0;
    return ds4_gpu_attention_output_q8_batch_impl(out, low, low, low,
        model_map, model_size, out_a_offset + tp_rank * shard_bytes, out_b_offset,
        4096, 1024, 4, 5120, heads, n_tokens, true, 8192, tp_rank * 4096u);
}

int ds4_gpu_attention_output_q4_K_batch_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *low,
        ds4_gpu_tensor       *group_tmp,
        ds4_gpu_tensor       *low_tmp,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                out_a_offset,
        uint64_t                out_b_offset,
        uint32_t                out_b_type,
        uint64_t                group_dim,
        uint64_t                rank,
        uint32_t                n_groups,
        uint64_t                out_dim,
        const ds4_gpu_tensor *heads,
        uint32_t                n_tokens) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !low || !heads || !model_map ||
        group_dim == 0 || rank == 0 || n_groups == 0 || out_dim == 0 || n_tokens == 0 ||
        group_dim > UINT32_MAX || rank > UINT32_MAX || out_dim > UINT32_MAX) {
        return 0;
    }
    if (n_tokens < 32u) return 0;

    @autoreleasepool {
        const uint64_t low_dim = (uint64_t)n_groups * rank;
        if ((group_dim % 256u) != 0 || (low_dim % 256u) != 0 || low_dim > UINT32_MAX) {
            return 0;
        }

        uint64_t row_a_bytes = 0;
        uint64_t row_b_bytes = 0;
        if (!ds4_gpu_quant_row_bytes(DS4_METAL_TENSOR_Q4_K, (uint32_t)group_dim, &row_a_bytes) ||
            !ds4_gpu_quant_row_bytes(out_b_type, (uint32_t)low_dim, &row_b_bytes)) {
