        if (att2_splits < 0) { const char *e = getenv("LLMS_DS4_ATT2"); att2_splits = (e && *e) ? atoi(e) : 0; if (att2_splits < 2 || att2_splits > 31) att2_splits = 0;
                             if (att2_splits) fprintf(stderr, "llms att2: on, %d splits\n", att2_splits); }
