        if (att2_now && !att2_pipeline) att2_pipeline = ds4_gpu_get_pipeline_or_die("kernel_llms_att2_r16qj");
        static id<MTLComputePipelineState> att2_hfirst_pipeline;   /* llms ATT2_HFIRST */
