        if (att2_hfirst_now && !att2_hfirst_pipeline) att2_hfirst_pipeline = ds4_gpu_get_pipeline_or_die("kernel_llms_att2_r16qjh");
        static int att2_h16_state = -1; static id<MTLComputePipelineState> att2_h16_pipeline; static uint64_t att2_h16_calls;   /* llms ATT2_H16 (apply_att2h16.py) */
        if (att2_h16_state < 0) { const char *e = getenv("LLMS_DS4_ATT2_H16"); att2_h16_state = !(e && *e && *e != '0') ? 0 : !strcmp(e, "canary") ? 3 : atoi(e) == 2 ? 2 : 1;
                            if (att2_h16_state) { fprintf(stderr, att2_h16_state == 3 ? "llms: att2 h16 CANARY -- half the head groups dispatched\n" : att2_h16_state == 2 ? "llms: att2 h16 (16 heads per threadgroup, the shipped splits: bit-identical)\n"
                                                                     : "llms: att2 h16 (16 heads per threadgroup, the splits doubled)\n");
                                            atexit_b(^{ fprintf(stderr, "llms att2 h16: %llu 16-head dispatches\n", (unsigned long long)att2_h16_calls); }); } }
        static int att2_g8_state = -1; if (att2_g8_state < 0) { const char *e = getenv("LLMS_DS4_ATT2_G8"); att2_g8_state = e && *e && *e != '0'; if (att2_g8_state) fprintf(stderr, "llms: att2 g8 (the 16-head split attention with the chunk gather batched into registers; needs the *_g8 misc source)\n"); }   /* llms ATT2_G8 (apply_att2g8.py) */
        if (att2_h16_state && att2_hfirst_now && !att2_h16_pipeline) { if (att2_g8_state) { att2_h16_pipeline = ds4_gpu_get_pipeline_or_die("kernel_llms_att2_r16qjh16g8"); if (!att2_h16_pipeline) fprintf(stderr, "llms att2 g8: kernel_llms_att2_r16qjh16g8 missing -- the shipped kernel\n"); }
                                                             if (!att2_h16_pipeline) att2_h16_pipeline = ds4_gpu_get_pipeline_or_die("kernel_llms_att2_r16qjh16");
                                                             if (!att2_h16_pipeline) { fprintf(stderr, "llms att2 h16: kernel_llms_att2_r16qjh16 missing in DS4_METAL_DSV4_MISC_SOURCE -- the 8-head kernel\n"); att2_h16_state = 0; } }
        const bool att2_h16_now = att2_h16_state && att2_hfirst_now && att2_hfirst_pipeline && att2_h16_pipeline && n_head % 16u == 0u && !llms_alt_off("att2h16");

        static id<MTLComputePipelineState> att2_s1_pipeline;   /* llms ATT2_S1 (apply_att2s1.py) */
        if (att2_h16_now && !att2_s1_pipeline) { if (att2_g8_state) { att2_s1_pipeline = ds4_gpu_get_pipeline_or_die("kernel_llms_att2_r16qjh16s1g8"); if (!att2_s1_pipeline) fprintf(stderr, "llms att2 g8: kernel_llms_att2_r16qjh16s1g8 missing -- the shipped s1 kernel\n"); }   /* llms ATT2_G8 */
                                                        if (!att2_s1_pipeline) att2_s1_pipeline = ds4_gpu_get_pipeline_or_die("kernel_llms_att2_r16qjh16s1");
                                                           if (!att2_s1_pipeline) { fprintf(stderr, "llms att2 s1: kernel_llms_att2_r16qjh16s1 missing in DS4_METAL_DSV4_MISC_SOURCE -- the split path\n"); } }
        const bool att2_s1_now = att2_h16_now && att2_s1_pipeline && n_tokens >= 8u && !llms_alt_off("att2s1");
        static id<MTLComputePipelineState> att2_h32_pipeline; static int att2_h32_state = -1; static uint64_t att2_h32_calls;   /* llms ATT2_H32 (apply_att2h32.py) */
        if (att2_h32_state < 0) { const char *e = getenv("LLMS_DS4_ATT2_H32"); att2_h32_state = e && *e && *e != '0';
            if (att2_h32_state) { att2_h32_pipeline = has_kernel("kernel_astra_att2_h32d128") ? ds4_gpu_get_pipeline_or_die("kernel_astra_att2_h32d128") : nil;
                if (att2_h32_pipeline && att2_h32_pipeline.maxTotalThreadsPerThreadgroup < 512) { fprintf(stderr, "llms att2 h32: the pipeline allows %lu threads, not 512 (LLMS_DS4_PSO_MAXT must list it) -- off\n", (unsigned long)att2_h32_pipeline.maxTotalThreadsPerThreadgroup); att2_h32_pipeline = nil; }
                fprintf(stderr, "llms att2 h32: %s\n", att2_h32_pipeline ? "on (kernel_astra_att2_h32d128 on the S1 branch: 32 heads a threadgroup, 512 threads)" : "the kernel is missing from DS4_METAL_DSV4_MISC_SOURCE -- off");
                if (att2_h32_pipeline) atexit_b(^{ fprintf(stderr, "llms att2 h32: %llu dispatches\n", (unsigned long long)att2_h32_calls); }); } }
        const bool att2_h32_now = att2_s1_now && att2_h32_pipeline && !llms_alt_off("h32");   /* llms ATT2_H32*/

        static id<MTLComputePipelineState> att2_pv2_pipeline; static int att2_pv2_state = -1; static uint64_t att2_pv2_calls;   /* llms ATT2_PV2 (apply_att2pv2.py) */
        if (att2_pv2_state < 0) { const char *e = getenv("LLMS_DS4_ATT2_PV2"); att2_pv2_state = e && *e && *e != '0';
            if (att2_pv2_state) { att2_pv2_pipeline = has_kernel("kernel_llms_att2_h32pv2") ? ds4_gpu_get_pipeline_or_die("kernel_llms_att2_h32pv2") : nil;
                if (att2_pv2_pipeline && att2_pv2_pipeline.maxTotalThreadsPerThreadgroup < 512) { fprintf(stderr, "llms att2 pv2: the pipeline allows %lu threads, not 512 -- off\n", (unsigned long)att2_pv2_pipeline.maxTotalThreadsPerThreadgroup); att2_pv2_pipeline = nil; }
                fprintf(stderr, "llms att2 pv2: %s\n", att2_pv2_pipeline ? "on (kernel_llms_att2_h32pv2: H32 with padded K rows and PV register blocking; bit-identical)" : "the kernel is missing from DS4_METAL_DSV4_MISC_SOURCE -- off");
                if (att2_pv2_pipeline) atexit_b(^{ fprintf(stderr, "llms att2 pv2: %llu dispatches\n", (unsigned long long)att2_pv2_calls); }); } }
        const bool att2_pv2_now = att2_h32_now && att2_pv2_pipeline;   /* llms ATT2_PV2 */
        uint32_t decode_splits =
