            if (by[0] < 0) { const char *e = getenv("LLMS_DS4_ATT2_BYROWS"); int a = 0, b = 0, c = 0, t4 = 0;
                             if (e && sscanf(e, "%d:%d:%d:%d", &a, &b, &t4, &c) == 4 && a >= 2 && a <= 31 && b >= 2 && b <= 31 && t4 >= 2 && t4 <= 31 && c >= 2 && c <= 31) {   /* llms ATT2_BYR3: one / two / THREE / more */
                                 by[0] = a; by[1] = b; by[2] = c; by[3] = t4; fprintf(stderr, "llms: att2 byrows %d:%d:%d:%d (splits at one row / two / THREE / more; ALT byr3 off -> two's at three)\n", a, b, t4, c);
