            qrope_here = split_decode && att2_h16_now && !att2_s1_now && attn_pipeline == att2_h16_pipeline && qrope_pipeline != nil && n_tokens <= 128u;
            if (!qrope_here) {   /* the request is honored anyway: q rotated in place before this attention reads it */
                ds4_gpu_tensor *qv[128]; uint32_t qp[128]; int qok = n_tokens <= 128u;
