            [enc setThreadgroupMemoryLength:att2_h32_now ? (att2_pv2_now ? 30464u : 30208u) : att2_s1_now ? 28672u : att2_h16_now ? 27392u : att2_now ? 22528u : 16u * 128u * sizeof(uint16_t) * 4u   /* llms ATT2_S1 tgmem: 640 row codes */
                                    atIndex:0];
            { static uint64_t a2h_n; if (att2_hfirst_now && att2_hfirst_pipeline && !a2h_n++) atexit_b(^{ fprintf(stderr, "llms att2 hfirst: %llu heads-fastest dispatches\n", (unsigned long long)a2h_n); }); }   /* llms ATT2_HFIRST: the execution counter */
            { static uint64_t att2_n; static int att2_s; att2_s = (int)decode_splits; if (att2_now && !att2_n++) atexit_b(^{ fprintf(stderr, "llms att2: %llu split attentions (splits %d)\n", (unsigned long long)att2_n, att2_s); }); }
            if (att2_h32_now) { att2_h32_calls++; if (att2_pv2_now && ++att2_pv2_calls == 1) fprintf(stderr, "llms att2 pv2: first dispatch\n");   /* 11-02 21:2x ( item 2): an execution witness a killed session keeps */ [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_head + 31u) / 32u, (NSUInteger)n_tokens, 1) threadsPerThreadgroup:MTLSizeMake(32, 16, 1)]; } else   /* llms ATT2_H32 */
            [enc dispatchThreadgroups:
                    MTLSizeMake(att2_h16_now ? ((NSUInteger)n_head + 15u) / 16u / (att2_h16_state == 3 ? 2u : 1u) : (att2_hfirst_now && att2_hfirst_pipeline) ? ((NSUInteger)n_head + 7u) / 8u : (NSUInteger)n_tokens,   /* llms ATT2_H16 */
                                (att2_hfirst_now && att2_hfirst_pipeline) ? (NSUInteger)n_tokens : ((NSUInteger)n_head + 7u) / 8u,
                                att2_s1_now ? 1u : decode_splits)
                 threadsPerThreadgroup:MTLSizeMake(32, 8, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
            if (!att2_s1_now) {   /* llms ATT2_S1: no reduce after one split */
            enc = ds4_gpu_compute_encoder(cb);
            static id<MTLComputePipelineState> redrope_pipeline; static int redrope_pipeline_tried;   /* llms REDROPE */
            if (redrope_requested && att2_reduce_now && !redrope_pipeline_tried) {
                redrope_pipeline_tried = 1; redrope_pipeline = has_kernel("kernel_llms_att_reduce_v3r") ? ds4_gpu_get_pipeline_or_die("kernel_llms_att_reduce_v3r") : nil;   /* llms HAS_KERNEL */
                if (!redrope_pipeline) fprintf(stderr, "llms redrope: kernel_llms_att_reduce_v3r MISSING (DS4_METAL_DSV4_MISC_SOURCE = the *_redrope.metal variant) -- the tail stays separate\n");
                else atexit_b(^{ fprintf(stderr, "llms redrope: %llu fused reduces\n", (unsigned long long)redrope_total); });
            }
            const bool redrope_here = redrope_requested && att2_reduce_now && redrope_pipeline != nil;
            [enc setComputePipelineState:redrope_here ? redrope_pipeline : split_reduce_pipeline];
            if (redrope_here) { [enc setBytes:&redrope_args length:sizeof(redrope_args) atIndex:4]; redrope_applied_count++; redrope_total++; }
            [enc setBytes:&attn_args length:sizeof(attn_args) atIndex:0];
            [enc setBuffer:g_flash_attn_tmp_buffer offset:0 atIndex:1];
            [enc setBuffer:sinks_buf offset:(NSUInteger)sinks_inner atIndex:2];
            [enc setBuffer:headsbuf offset:ds4_gpu_tensor_offset(heads) atIndex:3];
            { static uint64_t irdg_n; if (astra_indexed_reduce_now && !irdg_n++) atexit_b(^{ fprintf(stderr, "llms irdg: %llu grouped reduces\n", (unsigned long long)irdg_n); }); }
            if (att2_reduce_now) [enc dispatchThreads:MTLSizeMake(128u, (NSUInteger)nrows, 1) threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
            else [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)nrows * (astra_indexed_reduce_now ? 4u : 1u), 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
            }   /* llms ATT2_S1 */
        } else {
            enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:attn_pipeline];
            [enc setBytes:&attn_args length:sizeof(attn_args) atIndex:0];
            [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
            [enc setBuffer:rawbuf offset:ds4_gpu_tensor_offset(raw_kv) atIndex:2];
            [enc setBuffer:compbuf offset:ds4_gpu_tensor_offset(comp_kv) atIndex:3];
            [enc setBuffer:skip_decode_sort ? topkbuf : g_indexed_topk_buffer
                  offset:skip_decode_sort ? ds4_gpu_tensor_offset(topk) : 0
                 atIndex:4];
            [enc setBuffer:sinks_buf offset:(NSUInteger)sinks_inner atIndex:5];
            [enc setBuffer:headsbuf offset:ds4_gpu_tensor_offset(heads) atIndex:6];
            [enc setThreadgroupMemoryLength:(decode_one_token ? 16u : 1u) *
                                            128u * 4u * sizeof(uint16_t)
                                    atIndex:0];
            [enc dispatchThreadgroups:
                    MTLSizeMake((NSUInteger)n_tokens,
                                ((NSUInteger)n_head + (prefill_dual_heads ? 15u : 7u)) /
                                    (prefill_dual_heads ? 16u : 8u),
                                1)
                 threadsPerThreadgroup:MTLSizeMake(32, 8, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "graph indexed mixed attention heads")) return 0;
    }

    return 1;
}

int ds4_gpu_attention_prefill_static_mixed_heads_range_tensor(
        ds4_gpu_tensor       *heads,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                sinks_offset,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *raw_kv,
        const ds4_gpu_tensor *comp_kv,
        uint32_t                comp_kv_f16,
        uint32_t                q_row0,
        uint32_t                n_q,
        uint32_t                n_tokens,
        uint32_t                n_comp,
        uint32_t                window,
        uint32_t                ratio,
        uint32_t                n_head,
        uint32_t                head_dim) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!heads || !q || !raw_kv || !model_map || n_q == 0 || n_tokens == 0 ||
        ratio == 0 || (n_comp != 0 && !comp_kv)) {
        return 0;
    }

    @autoreleasepool {
        if (sinks_offset > model_size || (uint64_t)n_head * sizeof(float) > model_size - sinks_offset) {
            fprintf(stderr, "ds4: Metal attention sinks range is outside the mapped model\n");
            return 0;
        }

        uint64_t sinks_inner = 0;
        id<MTLBuffer> sinks_buf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                             sinks_offset,
                                                             (uint64_t)n_head * sizeof(float),
                                                             &sinks_inner);
        if (!sinks_buf) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        if (!ds4_gpu_encode_flash_attention_prefill_static_mixed_heads_nonvec(&cb,
                                                                                heads,
                                                                                sinks_buf,
                                                                                (NSUInteger)sinks_inner,
                                                                                q,
                                                                                raw_kv,
                                                                                comp_kv,
                                                                                comp_kv_f16,
                                                                                NULL,
                                                                                0,
                                                                                q_row0,
                                                                                n_q,
                                                                                n_tokens,
                                                                                n_comp,
                                                                                window,
                                                                                ratio,
                                                                                n_head,
                                                                                head_dim)) {
            return 0;
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "graph prefill static mixed attention heads")) return 0;
    }

    return 1;
}

