/* the PREHALF pair pipelines by kind (0 full, 1 list, 2 two-row entries, 3 four-row entries), table form (0 / 1: IQ2_W16) and simdgroups (2 / 4: IQ2_NSG) */
static int dd2c_mode(void) {   /* llms DD2C (apply_ds4_dd2c.py): 1 on, 2 canary */
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_DD2C"), *src = getenv("DS4_METAL_MOE_SOURCE"); on = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? 2 : 1;
                  if (on && !(src && llms_srckey(src, "q4x3wc") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_DD2C ignored: DS4_METAL_MOE_SOURCE does not name a *q4x3wc.metal source\n"), LLMS_G_NAME); on = 0; }
                  if (on) fprintf(stderr, on == 2 ? "llms: dd2c -- CANARY: the entries' second row is never computed\n" : "llms: dd2c (the two-row entry kernel with its second row at compile time; exact)\n"); }
    return on;
}
static id<MTLComputePipelineState> prehalf_pair_pipeline_w(int kind, int16_t nsg, int w16, int dd2c);
static id<MTLComputePipelineState> prehalf_pair_pipeline(int kind, int16_t nsg, int w16) {
    const int dd = kind == 2 && dd2c_mode() && !llms_alt_off("dd2c") ? dd2c_mode() : 0;   /* llms DD2C; ALT */
    return prehalf_pair_pipeline_w(kind, nsg, w16, dd);
}
