    }
    if (pair_dedup_on == 2) {   /* llms SPLIT listdedup2: singles through the pair-list kernel, two-row entries through the dedup kernel */
        if (!prehalf_x || !list_pipeline2 || !list_dedup_pipeline) { fprintf(stderr, "llms batch split listdedup2: needs PREHALF and both kernels\n"); ds4_gpu_end_compute_encoder(cb, enc); return 0; }
        if (pair_list_count) {
            static int cf1_list_state = -2; static id<MTLComputePipelineState> cf1_list_pipeline; static uint64_t cf1_calls, cf1_pairs;   /* llms CF1_LIST (apply_cf1_list.py) */
            if (cf1_list_state < -1) { const char *e = getenv("LLMS_DS4_CF1_LIST"), *src = getenv("DS4_METAL_MOE_SOURCE"); cf1_list_state = e && *e && *e != '0' ? (atoi(e) == 2 ? 2 : 1) : 0;   /* 14:1x: 2 = the float-reduction kernel (f66) */
                if (cf1_list_state && !(src && llms_srckey(src, "cfdec10") != NULL)) { fprintf(stderr, "llms: LLMS_DS4_CF1_LIST ignored: DS4_METAL_MOE_SOURCE does not name the *_cfdec10 lineage (the CF1 kernels)\n"); cf1_list_state = 0; }   /* llms CF1GUARD (2026-10-13): the cfdec10 sources (incl. *_bs6c_bs64) carry both CF1 kernels; a missing kernel leaves pc1 nil and the normal path runs */
                if (cf1_list_state) fprintf(stderr, "llms: cf1 list %d (the singles on the K = 1 column kernel, %s; ALT cf1l)\n", cf1_list_state, cf1_list_state == 2 ? "FORM 66: float row reductions" : "FORM 70: half2 butterfly"); }
            if (cf1_list_state && !cf1_list_pipeline) cf1_list_pipeline = ds4_gpu_get_pipeline_or_die(cf1_list_state == 2 ? "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_cf1_h_f66_f32" : "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_cf1_h_f70_f32");
            if (cf1_list_state && cf1_list_pipeline && !llms_alt_off("cf1l") && (args->ne01 % 32) == 0 && args->ne00 == 5120) {
                [enc setComputePipelineState:cf1_list_pipeline];
                [enc setBuffer:pair_list_buffer offset:pair_list_offset atIndex:10];
                [enc setThreadgroupMemoryLength:6144u + 32u * 2u * 5u * 4u atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)args->ne01 / 32u, 1, pair_list_count) threadsPerThreadgroup:MTLSizeMake(32, 5, 1)];
                if (threadgroup_bytes != 0) [enc setThreadgroupMemoryLength:threadgroup_bytes atIndex:0];   /* the dispatches after this one keep their size */
                if (cf1_calls++ == 0) atexit_b(^{ fprintf(stderr, "llms cf1 list: %llu dispatches, %llu single pairs\n", (unsigned long long)cf1_calls, (unsigned long long)cf1_pairs); });
                cf1_pairs += pair_list_count;
            } else {
            [enc setComputePipelineState:list_pipeline2];
            [enc setBuffer:pair_list_buffer offset:pair_list_offset atIndex:10];
            [enc dispatchThreadgroups:MTLSizeMake(row_groups, 1, pair_list_count) threadsPerThreadgroup:MTLSizeMake(32, nsg, 1)];
            }
        }
        if (two_row_entries_count && cf2_on() && !llms_alt_off("cf2")) {   /* llms CF2; ALT */
            static id<MTLComputePipelineState> c2p[2];
            const int ci = cf2_on() < 0 ? 1 : 0;
            if (!c2p[ci]) c2p[ci] = ds4_gpu_get_pipeline_or_die(ci ? "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_cf2x_h_f32" : "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_cf2_h_f32");
            static id<MTLComputePipelineState> c2f[128]; const int cf2_form = ci == 0 && cf_form_mode() ? (cf_form_mode() & ~(llms_alt_off("cff2") ? 2 : 0) & ~(llms_alt_off("cff4") ? 4 : 0) & ~(llms_alt_off("cffd") ? 24 : 0) & ~(llms_alt_off("cffw") ? 32 : 0) & ~(llms_alt_off("cffl") ? 64 : 0)) : 0;   /* llms CF_DEC: ALT cffd; CF_DEC2: ALT cffw */   /* llms CF_FORM (per call, apply_cf_form2.py) */
            if (cf2_form && !c2f[cf2_form]) { char nm[96]; snprintf(nm, sizeof nm, "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_cf2_h_f%d_f32", cf2_form); c2f[cf2_form] = ds4_gpu_get_pipeline_or_die(nm); }
            if (!c2p[ci] || (args->ne01 % 32) != 0 || args->ne00 != 5120) { fprintf(stderr, "llms cf2: the column-form kernel is missing or the shape is not 5,120 x 32k\n"); ds4_gpu_end_compute_encoder(cb, enc); return 0; }
            [enc setComputePipelineState:(cf2_form && c2f[cf2_form]) ? c2f[cf2_form] : c2p[ci]];
            [enc setBuffer:two_row_entries_buffer offset:two_row_entries_offset atIndex:10];
            [enc setThreadgroupMemoryLength:6144u + 32u * 4u * 5u * 4u atIndex:0];
            [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)args->ne01 / 32u, 1, two_row_entries_count) threadsPerThreadgroup:MTLSizeMake(32, 5, 1)];
            if (threadgroup_bytes != 0) [enc setThreadgroupMemoryLength:threadgroup_bytes atIndex:0];   /* the dispatches after this one keep their size */
            cf2_calls++; cf2_entries += two_row_entries_count;
        } else
        if (two_row_entries_count) {
            [enc setComputePipelineState:list_dedup_pipeline];
            [enc setBuffer:two_row_entries_buffer offset:two_row_entries_offset atIndex:10];
            [enc dispatchThreadgroups:MTLSizeMake(row_groups, 1, two_row_entries_count) threadsPerThreadgroup:MTLSizeMake(32, nsg, 1)];
        }
        if (quad_entries_count && cf4_on()) {   /* llms CF4: the column-form kernel, 32 rows per threadgroup, 5 simdgroups */
            static id<MTLComputePipelineState> cfp[3];
            const int ci = cf4_on() < 0 ? 2 : cf4_on() == 2 ? 1 : 0;
            static const char *pair_swiglu_cf_kernel_names[3] = { "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_cf_h_f32", "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_cfs_h_f32", "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_cfx_h_f32" };
            if (!cfp[ci]) cfp[ci] = ds4_gpu_get_pipeline_or_die(pair_swiglu_cf_kernel_names[ci]);
            static id<MTLComputePipelineState> c4f[128]; const int cf4_form = ci == 0 && cf_form_mode() ? (cf_form_mode() & ~(llms_alt_off("cff2") ? 2 : 0) & ~(llms_alt_off("cff4") ? 4 : 0) & ~(llms_alt_off("cffd") ? 24 : 0) & ~(llms_alt_off("cffw") ? 32 : 0) & ~(llms_alt_off("cffl") ? 64 : 0)) : 0;   /* llms CF_DEC: ALT cffd; CF_DEC2: ALT cffw */   /* llms CF_FORM (per call) */
            if (cf4_form && !c4f[cf4_form]) { char nm[96]; snprintf(nm, sizeof nm, "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_cf_h_f%d_f32", cf4_form); c4f[cf4_form] = ds4_gpu_get_pipeline_or_die(nm); }
            if (!cfp[ci] || !quad_entry_ring || (args->ne01 % 32) != 0 || args->ne00 != 5120) { fprintf(stderr, "llms cf4: the column-form kernel is missing or the shape is not 5,120 x 32k\n"); ds4_gpu_end_compute_encoder(cb, enc); return 0; }
            [enc setComputePipelineState:(cf4_form && c4f[cf4_form]) ? c4f[cf4_form] : cfp[ci]];
            [enc setBuffer:quad_entry_ring offset:quad_entries_offset atIndex:10];
            [enc setThreadgroupMemoryLength:6144u + 32u * 8u * 5u * 4u atIndex:0];
            [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)args->ne01 / 32u, 1, quad_entries_count) threadsPerThreadgroup:MTLSizeMake(32, 5, 1)];
            cf4_calls++; cf4_entries += quad_entries_count;
        } else
        if (quad_entries_count) {   /* llms SPLIT listdedup4: entries of three or four rows */
            id<MTLComputePipelineState> ph_dedup4 = prehalf_pair_pipeline(3, (int16_t)(iq2_nsg_now ? iq2_nsg_now : 2), w16_mode_now);   /* llms IQ2_W16 / IQ2_NSG per call */
            if (!ph_dedup4 || !quad_entry_ring) { fprintf(stderr, "llms batch split listdedup4: the four-row kernel is missing\n"); ds4_gpu_end_compute_encoder(cb, enc); return 0; }
            [enc setComputePipelineState:ph_dedup4];
            [enc setBuffer:quad_entry_ring offset:quad_entries_offset atIndex:10];
            [enc dispatchThreadgroups:MTLSizeMake(row_groups, 1, quad_entries_count) threadsPerThreadgroup:MTLSizeMake(32, nsg, 1)];
        }
        ds4_gpu_end_compute_encoder(cb, enc);
        return 1;
    }
    if (side_file_call_active) { fprintf(stderr, "llms bs6c: the full-grid IQ2_XXS pair kernel would read bs6c slots\n"); ds4_gpu_end_compute_encoder(cb, enc); return 0; }   /* llms BS6C */
    [enc dispatchThreadgroups:MTLSizeMake(row_groups, 1, pairs)
         threadsPerThreadgroup:MTLSizeMake(32, nsg, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_mul_mv_addr_iq2(
        id<MTLCommandBuffer>        cb,
        id<MTLComputePipelineState> pipeline,
        const ds4_gpu_mul_mv_id_args *args,
        ds4_gpu_stream_expert_cache_entry * const *entries,
        uint32_t                    n_entries,
        id<MTLBuffer>               addrs,
        id<MTLBuffer>               src1,
        NSUInteger                  src1_off,
        id<MTLBuffer>               dst,
        NSUInteger                  dst_off,
        id<MTLBuffer>               ids,
        NSUInteger                  ids_off,
        NSUInteger                  threadgroup_bytes,
        NSUInteger                  nsg,
        bool                        rows_per_group_is_nr0,
        uint32_t                    resource_kind,
        id<MTLBuffer>               overflow_resource) {
    if (!cb || !pipeline || !args || !entries ||
        (n_entries == 0 && !overflow_resource) ||
        n_entries > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT || resource_kind > 2 ||
        !addrs || !src1 || !dst || !ids ||
        args->ne00 <= 0 || args->ne01 <= 0 ||
        args->nei0 <= 0 || args->nei0 > DS4_METAL_MAX_ROUTED_EXPERT_USED ||
        args->nei1 <= 0 ||
        args->ne02 <= 0 || args->ne02 > 384) {
        return 0;
    }
    for (uint32_t i = 0; i < n_entries; i++) {
        if (!entries[i] || !entries[i]->gate_buffer ||
            !entries[i]->up_buffer || !entries[i]->down_buffer) return 0;
    }
    if (n_entries && !ds4_gpu_stream_expert_cache_mark_entries_inflight(entries,
                                                           n_entries,
                                                           0)) {
        return 0;
    }

    const NSUInteger nr0 = (NSUInteger)args->nr0;
    const NSUInteger rows_per_group = rows_per_group_is_nr0 ? nr0 : nr0 * nsg;
    const NSUInteger row_groups = ((NSUInteger)args->ne01 + rows_per_group - 1u) / rows_per_group;
    const NSUInteger pairs = (NSUInteger)args->nei0 * (NSUInteger)args->nei1;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:pipeline];
    [enc setBytes:args length:sizeof(*args) atIndex:0];
    [enc setBuffer:addrs offset:0 atIndex:1];
    [enc setBuffer:src1  offset:src1_off atIndex:2];
    [enc setBuffer:dst   offset:dst_off  atIndex:3];
    [enc setBuffer:ids   offset:ids_off  atIndex:4];
    for (uint32_t i = 0; i < n_entries; i++) {
        id<MTLBuffer> b = resource_kind == 0 ? entries[i]->gate_buffer :
                          resource_kind == 1 ? entries[i]->up_buffer :
                                               entries[i]->down_buffer;
        [enc useResource:b usage:MTLResourceUsageRead];
    }
    if (overflow_resource) [enc useResource:overflow_resource usage:MTLResourceUsageRead];
    if (threadgroup_bytes != 0) {
        [enc setThreadgroupMemoryLength:threadgroup_bytes atIndex:0];
    }
    [enc dispatchThreadgroups:MTLSizeMake(row_groups, 1, pairs)
         threadsPerThreadgroup:MTLSizeMake(32, nsg, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

/* llms Q2K_DOWN_NR8 (apply_ds4_q2k_down_nr8.py; adopted, the switch removed 10-27): 8 rows per simdgroup in the routed down kernel, which exists only in the *_d8 sources */
static int q2k_down_nr8_on(void) {
    static int on = -1;
    if (on < 0) { const char *src = getenv("DS4_METAL_MOE_SOURCE"); on = src && llms_srckey(src, "_d8") != NULL; }
    return on;
}
/* llms DOWN_COL (apply_ds4_down_col.py; adopted, the switch removed 10-27): the routed down projection in column runs of 32 rows, whenever the source is a *q4x3* one */
static int down_col_on(void) {
    static int on = -2;
    if (on < -1) { const char *src = getenv("DS4_METAL_MOE_SOURCE"); on = src && llms_srckey(src, "q4x3") != NULL; }
    return on;
}
/* llms DOWN_COLTOKX (apply_ds4_down_coltokx.py; adopted, the switch removed 10-27): the column down kernel on a token-fastest grid (x = token, y = row
 * group); bit-exact against DOWN_COL; whenever the source is a *ctx* one. ALT 'ctx'. */
static int down_col_tokx_on(void) {
    static int on = -2;
    if (on < -1) { const char *src = getenv("DS4_METAL_MOE_SOURCE"); on = src && llms_srckey(src, "ctx") != NULL; }
    return on;
}
/* llms HSPARSE (apply_hsparse.py): a FIDELITY DIAL -- per (token, slot) row of the routed down projection's 2,304 * inputs, the largest fraction hsparse_keep by magnitude kept, the rest zeroed (what a column-skipping down kernel would see). Off unless set. */
static float hsparse_keep; static id<MTLComputePipelineState> hsparse_pipeline; static id<MTLBuffer> hsparse_counts; static id<MTLComputePipelineState> hsparse_group_pipeline; static int hsparse_group;   /* llms HSPARSE_G */ static id<MTLComputePipelineState> hsparse_gt_pipeline; static int hsparse_gt_mode; static id<MTLBuffer> hsparse_group_buffer; static NSUInteger hsparse_group_offset;   /* llms HSPARSE_GT */
void ds4_gpu_llms_hsparse_set(float keep) {
    if (hsparse_counts) { const uint32_t *c = (const uint32_t *)[hsparse_counts contents];
        if (c[0]) fprintf(stderr, "llms hsparse: previous setting %u rows, %u values zeroed (%.4f of the rows' values)\n", c[0], c[1], (double)c[1] / ((double)c[0] * 2304.0));
        memset([hsparse_counts contents], 0, 16); }
    hsparse_group = keep < 0.0f; if (keep < 0.0f) keep = -keep;   /* llms HSPARSE_G: a negative keep = whole 16-input groups by L2 norm */
    hsparse_gt_mode = keep > 1.0f; if (keep > 1.0f) keep -= 1.0f;   /* llms HSPARSE_GT: 1 + KEEP = rank by |silu(gate)| */
    hsparse_keep = keep > 0.0f && keep < 1.0f ? keep : 0.0f;
    if (hsparse_keep > 0.0f) fprintf(stderr, "llms hsparse: keep %.3f of each row's down %s -- FIDELITY DIAL (measurement); NOT the model\n", (double)hsparse_keep, hsparse_group ? "16-input groups by L2 norm" : hsparse_gt_mode ? "inputs by |silu(gate)| (CATS-style)" : "inputs by magnitude");
}
static int encode_hsparse(id<MTLCommandBuffer> cb, id<MTLBuffer> src1, NSUInteger src1_off, const ds4_gpu_mul_mv_id_args *a,
                           id<MTLBuffer> list, NSUInteger list_off, uint32_t n_tok) {   /* llms HSPARSE2: a token list (CLEAN_DOWN) or nil = tokens 0..nei1-1 */
    if (!hsparse_pipeline) {
        NSString *src = @"#include <metal_stdlib>\nusing namespace metal;\n"
            "kernel void llms_hsparse(device float *h [[buffer(0)]], constant uint4 &p [[buffer(1)]], constant float &keep [[buffer(2)]],\n"
            "                         device atomic_uint *cnt [[buffer(3)]], device const uint *tl [[buffer(4)]], constant uint &use_list [[buffer(5)]],\n"
            "                         uint2 tg [[threadgroup_position_in_grid]], uint lane [[thread_index_in_simdgroup]]) {\n"
            "    const uint tok = use_list ? tl[tg.y] : tg.y;\n"
            "    device float *r = h + (ulong)tok * p.w + (ulong)tg.x * p.z; const uint n = p.x;\n"
            "    float v[72]; float mx = 0.0f;\n"
            "    for (uint j = 0; j < 72; j++) { const uint i = lane + 32u * j; const float x = i < n ? fabs(r[i]) : 0.0f; v[j] = x; mx = max(mx, x); }\n"
            "    mx = simd_max(mx); const uint target = (uint)(keep * (float)n + 0.5f); float lo = 0.0f, hi = mx;\n"
            "    for (int it = 0; it < 20; it++) { const float m = 0.5f * (lo + hi); uint c = 0;\n"
            "        for (uint j = 0; j < 72; j++) c += v[j] >= m ? 1u : 0u;\n"
            "        c = simd_sum(c); if (c > target) lo = m; else hi = m; }\n"
            "    uint z = 0;\n"
            "    for (uint j = 0; j < 72; j++) { const uint i = lane + 32u * j; if (i < n && v[j] < hi) { r[i] = 0.0f; z++; } }\n"
            "    z = simd_sum(z);\n"
            "    if (lane == 0) { atomic_fetch_add_explicit(cnt + 0, 1u, memory_order_relaxed); atomic_fetch_add_explicit(cnt + 1, z, memory_order_relaxed); }\n"
            "}\n"
            "kernel void llms_hsparse_g(device float *h [[buffer(0)]], constant uint4 &p [[buffer(1)]], constant float &keep [[buffer(2)]],\n"
            "                           device atomic_uint *cnt [[buffer(3)]], device const uint *tl [[buffer(4)]], constant uint &use_list [[buffer(5)]],\n"
            "                           uint2 tg [[threadgroup_position_in_grid]], uint lane [[thread_index_in_simdgroup]]) {   /* llms HSPARSE_G */\n"
            "    const uint tok = use_list ? tl[tg.y] : tg.y;\n"
            "    device float *r = h + (ulong)tok * p.w + (ulong)tg.x * p.z; const uint ng = p.x / 16u;\n"
            "    float gn[5]; float mx = 0.0f;\n"
            "    for (uint j = 0; j < 5; j++) { const uint g = lane + 32u * j; float s2 = -1.0f;\n"
            "        if (g < ng) { s2 = 0.0f; for (uint l = 0; l < 16; l++) { const float v = r[g * 16u + l]; s2 += v * v; } mx = max(mx, s2); } gn[j] = s2; }\n"
            "    mx = simd_max(mx); const uint target = (uint)(keep * (float)ng + 0.5f); float lo = 0.0f, hi = mx;\n"
            "    for (int it = 0; it < 24; it++) { const float m = 0.5f * (lo + hi); uint c = 0;\n"
            "        for (uint j = 0; j < 5; j++) c += gn[j] >= m ? 1u : 0u;\n"
            "        c = simd_sum(c); if (c > target) lo = m; else hi = m; }\n"
            "    uint z = 0;\n"
            "    for (uint j = 0; j < 5; j++) { const uint g = lane + 32u * j; if (g < ng && gn[j] < hi) { for (uint l = 0; l < 16; l++) r[g * 16u + l] = 0.0f; z += 16u; } }\n"
            "    z = simd_sum(z);\n"
            "    if (lane == 0) { atomic_fetch_add_explicit(cnt + 0, 1u, memory_order_relaxed); atomic_fetch_add_explicit(cnt + 1, z, memory_order_relaxed); }\n"
            "}\n"
            "kernel void llms_hsparse_gt(device float *h [[buffer(0)]], constant uint4 &p [[buffer(1)]], constant float &keep [[buffer(2)]],\n"
            "                            device atomic_uint *cnt [[buffer(3)]], device const uint *tl [[buffer(4)]], constant uint &use_list [[buffer(5)]],\n"
            "                            device const float *gb [[buffer(6)]], uint2 tg [[threadgroup_position_in_grid]], uint lane [[thread_index_in_simdgroup]]) {   /* llms HSPARSE_GT */\n"
            "    const uint tok = use_list ? tl[tg.y] : tg.y; const ulong ro = (ulong)tok * p.w + (ulong)tg.x * p.z;\n"
            "    device float *r = h + ro; device const float *gr = gb + ro; const uint n = p.x;\n"
            "    float v[72]; float mx = 0.0f;\n"
            "    for (uint j = 0; j < 72; j++) { const uint i = lane + 32u * j; float x = 0.0f; if (i < n) { const float g = gr[i]; x = fabs(g / (1.0f + exp(-g))); } v[j] = x; mx = max(mx, x); }\n"
            "    mx = simd_max(mx); const uint target = (uint)(keep * (float)n + 0.5f); float lo = 0.0f, hi = mx;\n"
            "    for (int it = 0; it < 20; it++) { const float m = 0.5f * (lo + hi); uint c = 0;\n"
            "        for (uint j = 0; j < 72; j++) c += v[j] >= m ? 1u : 0u;\n"
            "        c = simd_sum(c); if (c > target) lo = m; else hi = m; }\n"
            "    uint z = 0;\n"
            "    for (uint j = 0; j < 72; j++) { const uint i = lane + 32u * j; if (i < n && v[j] < hi) { r[i] = 0.0f; z++; } }\n"
            "    z = simd_sum(z);\n"
            "    if (lane == 0) { atomic_fetch_add_explicit(cnt + 0, 1u, memory_order_relaxed); atomic_fetch_add_explicit(cnt + 1, z, memory_order_relaxed); }\n"
            "}\n";
        NSError *err = nil; id<MTLLibrary> lib = [g_device newLibraryWithSource:src options:nil error:&err];
        if (!lib) { fprintf(stderr, "llms hsparse: compile failed: %s\n", [[err localizedDescription] UTF8String]); return 0; }
        hsparse_pipeline = [g_device newComputePipelineStateWithFunction:[lib newFunctionWithName:@"llms_hsparse"] error:&err];
        if (!hsparse_pipeline) return 0;
        hsparse_group_pipeline = [g_device newComputePipelineStateWithFunction:[lib newFunctionWithName:@"llms_hsparse_g"] error:&err];   /* llms HSPARSE_G */
        if (!hsparse_group_pipeline) return 0;
        hsparse_gt_pipeline = [g_device newComputePipelineStateWithFunction:[lib newFunctionWithName:@"llms_hsparse_gt"] error:&err];   /* llms HSPARSE_GT */
        if (!hsparse_gt_pipeline) return 0;
        hsparse_counts = [g_device newBufferWithLength:16 options:MTLResourceStorageModeShared]; memset([hsparse_counts contents], 0, 16);
    }
    if (a->ne00 != 2304 || a->nb11 % 4u || a->nb12 % 4u) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    if (!enc) return 0;
    if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
    const uint32_t p[4] = { (uint32_t)a->ne00, (uint32_t)a->nei0, (uint32_t)(a->nb11 / 4u), (uint32_t)(a->nb12 / 4u) };
    if (hsparse_gt_mode && !hsparse_group_buffer) { ds4_gpu_end_compute_encoder(cb, enc); return 0; }
    [enc setComputePipelineState:hsparse_gt_mode ? hsparse_gt_pipeline : hsparse_group ? hsparse_group_pipeline : hsparse_pipeline];   /* llms HSPARSE_G / _GT */
    if (hsparse_gt_mode) [enc setBuffer:hsparse_group_buffer offset:hsparse_group_offset atIndex:6];
    [enc setBuffer:src1 offset:src1_off atIndex:0];
    [enc setBytes:p length:sizeof(p) atIndex:1];
    [enc setBytes:&hsparse_keep length:sizeof(float) atIndex:2];
    [enc setBuffer:hsparse_counts offset:0 atIndex:3];
    const uint32_t use_list = list != nil; [enc setBuffer:(list ? list : hsparse_counts) offset:(list ? list_off : 0) atIndex:4]; [enc setBytes:&use_list length:4 atIndex:5];
    [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)a->nei0, (NSUInteger)(list ? n_tok : (uint32_t)a->nei1), 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
    if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}
/* llms AQUANT (apply_aquant.py): fake quantization of the routed experts' activations (x: gate/up input, h: down input), * XB / HB bits per XG / HG group, symmetric; a FIDELITY DIAL set per sweep setting by ds4_gpu_llms_aquant_set. Off unless set. */
static int aquant_x_bits, aquant_x_group, aquant_h_bits, aquant_h_group; static id<MTLComputePipelineState> aquant_pipeline; static uint64_t aquant_x_calls, aquant_h_calls;
void ds4_gpu_llms_aquant_set(int xb, int xg, int hb, int hg) {
    if (aquant_x_calls || aquant_h_calls) fprintf(stderr, "llms aquant: previous setting %llu x calls, %llu h calls\n", (unsigned long long)aquant_x_calls, (unsigned long long)aquant_h_calls);
    aquant_x_calls = aquant_h_calls = 0;
    aquant_x_bits = xb >= 2 && xb <= 16 && (xg == 16 || xg == 32) ? xb : 0; aquant_x_group = xg;
    aquant_h_bits = hb >= 2 && hb <= 16 && (hg == 16 || hg == 32) ? hb : 0; aquant_h_group = hg;
    if (aquant_x_bits || aquant_h_bits) fprintf(stderr, "llms aquant: x %d bits / %d, h %d bits / %d -- FIDELITY DIAL (measurement); NOT the model\n", aquant_x_bits, xg, aquant_h_bits, hg);
}
static int aquant_pipeline_ready(void) {
    if (aquant_pipeline) return 1;
    NSString *src = @"#include <metal_stdlib>\nusing namespace metal;\n"
        "kernel void llms_aquant(device float *v [[buffer(0)]], constant uint4 &p [[buffer(1)]], constant uint4 &q [[buffer(2)]], device const uint *tl [[buffer(3)]],\n"
        "                        uint2 tg [[threadgroup_position_in_grid]], ushort lane [[thread_index_in_simdgroup]]) {\n"
        "    /* p: x = n, y = group (16 / 32), z = qmax, w = use_list; q: x = slot stride, y = token stride (floats) */\n"
        "    const uint tok = p.w ? tl[tg.y] : tg.y; device float *r = v + (ulong)tok * q.y + (ulong)tg.x * q.x; const float qmax = float(p.z);\n"
        "    for (uint b = 0; b < p.x; b += 32u) { const uint i = b + lane; const float x = i < p.x ? r[i] : 0.0f; float a = fabs(x);\n"
        "        for (ushort m = 1; m < (ushort)p.y; m <<= 1) a = max(a, simd_shuffle_xor(a, m));\n"
        "        const float sc = a > 0.0f ? a / qmax : 1.0f; if (i < p.x) r[i] = rint(x / sc) * sc; }\n"
        "}\n";
    NSError *err = nil; id<MTLLibrary> lib = [g_device newLibraryWithSource:src options:nil error:&err];
    if (!lib) { fprintf(stderr, "llms aquant: compile failed: %s\n", [[err localizedDescription] UTF8String]); return 0; }
    aquant_pipeline = [g_device newComputePipelineStateWithFunction:[lib newFunctionWithName:@"llms_aquant"] error:&err];
    return aquant_pipeline != nil;
}
static int encode_aquant(id<MTLComputeCommandEncoder> enc, id<MTLBuffer> buf, NSUInteger off, uint32_t n, int bits, int group,
                          uint32_t nslots, uint32_t slot_stride, uint32_t ntok, uint32_t tok_stride, id<MTLBuffer> list, NSUInteger list_off) {
    if (!aquant_pipeline_ready()) return 0;
    const uint32_t p[4] = { n, (uint32_t)group, (1u << (bits - 1)) - 1u, list ? 1u : 0u }, qq[4] = { slot_stride, tok_stride, 0, 0 };
    if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
    [enc setComputePipelineState:aquant_pipeline];
    [enc setBuffer:buf offset:off atIndex:0]; [enc setBytes:p length:sizeof(p) atIndex:1]; [enc setBytes:qq length:sizeof(qq) atIndex:2];
    [enc setBuffer:(list ? list : buf) offset:(list ? list_off : off) atIndex:3];
    [enc dispatchThreadgroups:MTLSizeMake(nslots, ntok, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
    if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
    return 1;
}
/* x: the routed gate/up input, rows x cols contiguous floats; a no-op returning 1 when the dial is off */
int ds4_gpu_llms_xquant_maybe(ds4_gpu_tensor *t, uint32_t rows, uint32_t cols) {
    if (!aquant_x_bits) return 1;
    if (!t || ds4_gpu_tensor_bytes(t) < (uint64_t)rows * cols * sizeof(float)) return 0;
    int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned); id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
    if (!enc) return 0;
    const int ok = encode_aquant(enc, ds4_gpu_tensor_buffer(t), ds4_gpu_tensor_offset(t), cols, aquant_x_bits, aquant_x_group, 1, 0, rows, cols, nil, 0);
    ds4_gpu_end_compute_encoder(cb, enc); aquant_x_calls++;
    return ok && ds4_gpu_finish_command_buffer(cb, owned, "llms aquant x");
}
/* llms GU_SIDE (apply_guside.py): h recomputed from side gate/up weights (fp4 / g32 / g16) for one routed layer; a FIDELITY DIAL */
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
static int gateup_side_layer = -1, gateup_side_format; static void *gateup_side_map; static size_t gateup_side_length; static id<MTLBuffer> gateup_side_buffer;
static id<MTLComputePipelineState> gateup_side_pipeline; static uint64_t gateup_side_file_calls; static id<MTLBuffer> gateup_side_check;   /* llms GU_SIDE CHECK */
static id<MTLBuffer> gateup_side_x_buffer, gateup_side_w_buffer; static NSUInteger gateup_side_x_offset, gateup_side_w_offset; static uint32_t gateup_side_current_layer = 9999; static float gateup_side_clamp;
void ds4_gpu_llms_guside_set(int layer, int fmt) {
    if (gateup_side_file_calls) fprintf(stderr, "llms guside: previous setting %llu down calls recomputed\n", (unsigned long long)gateup_side_file_calls);
    gateup_side_file_calls = 0; gateup_side_buffer = nil;
    if (gateup_side_map) { munmap(gateup_side_map, gateup_side_length); gateup_side_map = NULL; }
    gateup_side_layer = -1;
    if (layer < 0 || fmt < 0 || fmt > 4) return;   /* llms GU_SIDE g64w (apply_guside_g64.py) */
    static const char *nm[5] = {"fp4", "g32", "g16", "g32w", "g64w"}; char path[512];   /* g32w: importance-weighted G32 (apply_xdump.py), the G32 layout */
    snprintf(path, sizeof path, "gu_%s_L%d.bin", nm[fmt], layer);
    const int fd = open(path, O_RDONLY); if (fd < 0) { fprintf(stderr, "llms guside: cannot open %s\n", path); return; }
    struct stat st; fstat(fd, &st); const size_t pg = 16384; gateup_side_length = ((size_t)st.st_size + pg - 1) / pg * pg;
    gateup_side_map = mmap(NULL, gateup_side_length, PROT_READ, MAP_SHARED, fd, 0); close(fd);
    if (gateup_side_map == MAP_FAILED) { gateup_side_map = NULL; fprintf(stderr, "llms guside: mmap failed\n"); return; }
    gateup_side_buffer = [g_device newBufferWithBytesNoCopy:gateup_side_map length:gateup_side_length options:MTLResourceStorageModeShared deallocator:nil];
    if (!gateup_side_buffer) { fprintf(stderr, "llms guside: no buffer\n"); return; }
    gateup_side_layer = layer; gateup_side_format = fmt;
    fprintf(stderr, "llms guside: layer %d gate/up from %s (%.2f GB) -- FIDELITY DIAL (measurement); NOT the model's weights\n", layer, path, (double)st.st_size / 1e9);
}
typedef struct { uint32_t fmt, nlist, use_list, rows, cols; float clamp; uint32_t pad0, pad1; uint64_t exp_bytes, mat_bytes, x_tok, mid_slot, mid_tok, ids_tok, w_tok; } gateup_side_args;
static int encode_gateup_side(id<MTLCommandBuffer> cb, id<MTLBuffer> src1, NSUInteger src1_off, const ds4_gpu_mul_mv_id_args *a, id<MTLBuffer> ids, NSUInteger ids_off,
                           id<MTLBuffer> list, NSUInteger list_off, uint32_t n_tok) {
    if (!gateup_side_pipeline) {
        NSString *src = @"#include <metal_stdlib>\nusing namespace metal;\n"
            "constant float E2M1[8] = {0.0f, 0.5f, 1.0f, 1.5f, 2.0f, 3.0f, 4.0f, 6.0f};\n"
            "struct gus_args { uint fmt, nlist, use_list, rows, cols; float clamp; uint pad0, pad1; ulong exp_bytes, mat_bytes, x_tok, mid_slot, mid_tok, ids_tok, w_tok; };\n"
            "kernel void llms_guside(device const uchar *side [[buffer(0)]], device const float *x [[buffer(1)]], device const char *ids [[buffer(2)]], device const char *rw [[buffer(3)]],\n"
            "                        device char *mid [[buffer(4)]], device const uint *tl [[buffer(5)]], constant gus_args &a [[buffer(6)]], device float *ck [[buffer(7)]],\n"
            "                        uint3 tg [[threadgroup_position_in_grid]], ushort tid [[thread_index_in_threadgroup]]) {\n"
            "  const uint slot = tg.x, li = tg.y, row = tg.z * 64u + tid; if (row >= a.rows) return;\n"
            "  const uint tok = a.use_list ? tl[li] : li;\n"
            "  const int e = ((device const int *)(ids + (ulong)tok * a.ids_tok))[slot]; if (e < 0) return;\n"
            "  const float w = ((device const float *)(rw + (ulong)tok * a.w_tok))[slot];\n"
            "  device const float *xr = (device const float *)((device const char *)x + (ulong)tok * a.x_tok);\n"
            "  device const uchar *eb = side + (ulong)e * a.exp_bytes; float gu[2];\n"
            "  for (int m = 0; m < 2; m++) { device const uchar *mb = eb + (ulong)m * a.mat_bytes; float acc = 0.0f;\n"
            "    if (a.fmt == 0u) { device const uchar *nb = mb + (ulong)row * (a.cols / 2u); device const uchar *sb = mb + (ulong)a.rows * (a.cols / 2u) + (ulong)row * (a.cols / 32u);\n"
            "      for (uint gi = 0; gi < a.cols / 32u; gi++) { const float sc = exp2(float(sb[gi]) - 127.0f); float s = 0.0f;\n"
            "        for (uint j = 0; j < 16u; j++) { const uchar bb = nb[gi * 16u + j]; const uchar lo = bb & 15, hi = bb >> 4;\n"
            "          s += ((lo & 8) ? -E2M1[lo & 7] : E2M1[lo & 7]) * xr[gi * 32u + 2u * j] + ((hi & 8) ? -E2M1[hi & 7] : E2M1[hi & 7]) * xr[gi * 32u + 2u * j + 1u]; }\n"
            "        acc += sc * s; } }\n"
            "    else { const uint G = a.fmt == 1u ? 32u : a.fmt == 4u ? 64u : 16u, ng = a.cols / G;\n"
            "      device const half2 *sl = (device const half2 *)(mb + (ulong)a.rows * ng * (G / 4u)) + (ulong)row * ng;\n"
            "      for (uint gi = 0; gi < ng; gi++) { const float2 slv = float2(sl[gi]); float sq = 0.0f, sx = 0.0f;\n"
            "        if (G == 64u) { const ulong w0 = ((device const ulong *)mb)[((ulong)row * ng + gi) * 2u], w1 = ((device const ulong *)mb)[((ulong)row * ng + gi) * 2u + 1u];\n"
            "          for (uint j = 0; j < 32u; j++) { const float xa = xr[gi * 64u + j], xb = xr[gi * 64u + 32u + j]; sq += float((w0 >> (2u * j)) & 3ul) * xa + float((w1 >> (2u * j)) & 3ul) * xb; sx += xa + xb; } }\n"
            "        else if (G == 32u) { const ulong wd = ((device const ulong *)mb)[(ulong)row * ng + gi];\n"
            "          for (uint j = 0; j < 32u; j++) { const float xv = xr[gi * 32u + j]; sq += float((wd >> (2u * j)) & 3ul) * xv; sx += xv; } }\n"
            "        else { const uint wd = ((device const uint *)mb)[(ulong)row * ng + gi];\n"
            "          for (uint j = 0; j < 16u; j++) { const float xv = xr[gi * 16u + j]; sq += float((wd >> (2u * j)) & 3u) * xv; sx += xv; } }\n"
            "        acc += slv.x * sq + slv.y * sx; } }\n"
            "    gu[m] = acc; }\n"
            "  float g = gu[0], u = gu[1]; if (a.clamp > 1e-6f) { g = min(g, a.clamp); u = clamp(u, -a.clamp, a.clamp); }\n"
            "  device float *mp = (device float *)(mid + (ulong)tok * a.mid_tok + (ulong)slot * a.mid_slot) + row; const float hv = g / (1.0f + exp(-g)) * u * w;\n"
            "  if (a.pad0 != 0u && li < 64u) { const ulong ix = ((ulong)li * 6ul + slot) * a.rows + row; ck[2ul * ix] = *mp; ck[2ul * ix + 1ul] = hv; }   /* CHECK: (engine h, side h) */\n"
            "  *mp = hv;\n"
            "}\n";
        NSError *err = nil; id<MTLLibrary> lib = [g_device newLibraryWithSource:src options:nil error:&err];
        if (!lib) { fprintf(stderr, "llms guside: compile failed: %s\n", [[err localizedDescription] UTF8String]); return 0; }
        gateup_side_pipeline = [g_device newComputePipelineStateWithFunction:[lib newFunctionWithName:@"llms_guside"] error:&err];
        if (!gateup_side_pipeline) return 0;
    }
    if (!gateup_side_buffer || !gateup_side_x_buffer || !gateup_side_w_buffer || a->ne00 != 2304) return 0;
    if (!gateup_side_check) gateup_side_check = [g_device newBufferWithLength:(NSUInteger)128 * 6 * 2304 * 2 * sizeof(float) options:MTLResourceStorageModeShared];   /* llms GU_SIDE CHECK; ROWS128 */
    if (!gateup_side_check) return 0;
    const int chk = gateup_side_file_calls == 0; if (chk) memset([gateup_side_check contents], 0xFF, [gateup_side_check length]);   /* NaN: entries not written are skipped */
    const uint64_t rows = 2304, cols = 5120;
    const uint64_t mat = gateup_side_format == 0 ? rows * (cols / 2 + cols / 32) : (gateup_side_format == 1 || gateup_side_format == 3) ? rows * (cols / 32) * 12 : gateup_side_format == 4 ? rows * (cols / 64) * 20 : rows * (cols / 16) * 8;
    gateup_side_args ga = { (uint32_t)(gateup_side_format == 3 ? 1 : gateup_side_format), n_tok, list ? 1u : 0u, (uint32_t)rows, (uint32_t)cols, gateup_side_clamp, (uint32_t)chk, 0,
                         2 * mat, mat, cols * 4, a->nb11, a->nb12, a->nbi1, 6 * 4 };
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb); if (!enc) return 0;
    if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
    [enc setComputePipelineState:gateup_side_pipeline];
    [enc setBuffer:gateup_side_buffer offset:0 atIndex:0]; [enc setBuffer:gateup_side_x_buffer offset:gateup_side_x_offset atIndex:1]; [enc setBuffer:ids offset:ids_off atIndex:2];
    [enc setBuffer:gateup_side_w_buffer offset:gateup_side_w_offset atIndex:3]; [enc setBuffer:src1 offset:src1_off atIndex:4];
    [enc setBuffer:(list ? list : ids) offset:(list ? list_off : 0) atIndex:5]; [enc setBytes:&ga length:sizeof ga atIndex:6]; [enc setBuffer:gateup_side_check offset:0 atIndex:7];
    [enc dispatchThreadgroups:MTLSizeMake(6, n_tok, (rows + 63) / 64) threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
    if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
    ds4_gpu_end_compute_encoder(cb, enc); gateup_side_file_calls++;
    if (chk) {   /* llms GU_SIDE CHECK: statistics once the command buffer has run */
        id<MTLBuffer> ckb = gateup_side_check; const int L_ = gateup_side_layer, F_ = gateup_side_format; const uint32_t nt = n_tok < 64u ? n_tok : 64u;
        [cb addCompletedHandler:^(id<MTLCommandBuffer> done_cb) { (void)done_cb;
            const float *v = (const float *)[ckb contents]; double n = 0, se = 0, ss = 0, see = 0, sss = 0, ses = 0;
            for (uint64_t i = 0; i < (uint64_t)nt * 6u * 2304u; i++) { const double e = v[2 * i], q = v[2 * i + 1]; if (e != e || q != q) continue; n++; se += e; ss += q; see += e * e; sss += q * q; ses += e * q; }
            const double ce = see - se * se / (n > 0 ? n : 1), cs = sss - ss * ss / (n > 0 ? n : 1), cx = ses - se * ss / (n > 0 ? n : 1);
            fprintf(stderr, "llms guside: CHECK layer %d fmt %d: %.0f pairs, corr(engine h, side h) %.4f, slope %.4f, |side|/|engine| %.4f\n", L_, F_, n,
                    cx / sqrt(ce * cs > 0 ? ce * cs : 1), cx / (ce > 0 ? ce : 1), sqrt(sss / (see > 0 ? see : 1))); }];
    }
    return 1;
}
/* llms ADD6 (apply_add6.py): the verify's routed + shared add folded into the G32 down's six-slot sum. The sum writes the routed rows as before AND block = routed + shared; the caller arms the call with its tensors and skips its add2 when the sum took it. Off unless LLMS_DS4_ADD6=1; ALT 'add6'. */

static int add6_state = -1; static id<MTLComputePipelineState> add6_pipe, add6_dc_pipe;   /* add6_dc_pipe: llms ROUTED_DC */ static uint64_t add6_armed_calls, add6_fused_calls, add6_invalid_calls;
static struct { int armed, done; id<MTLBuffer> rt, sh, blk; NSUInteger rt_off, sh_off, blk_off; uint32_t rows; } add6;
int ds4_gpu_llms_add6_arm(const ds4_gpu_tensor *routed, const ds4_gpu_tensor *shared, const ds4_gpu_tensor *block, uint32_t rows) {
    if (add6_state < 0) { const char *e = getenv("LLMS_DS4_ADD6"); add6_state = e && *e && *e != '0';
        if (add6_state) { NSString *src = @"#include <metal_stdlib>\n"
            "using namespace metal;\n"
            "struct a6args { uint ne0, nei0, nei1, ne02; ulong nbi1, nb1; };\n"
            "kernel void llms_sum6_add(constant a6args &a [[buffer(0)]], device const ulong *addrs [[buffer(1)]], device const float *partial [[buffer(2)]],\n"
            "                          device char *dst [[buffer(3)]], device const char *ids [[buffer(4)]], device const float *sh [[buffer(5)]], device float *blk [[buffer(6)]],\n"
            "                          uint3 gid [[thread_position_in_grid]]) {\n"
            "    const uint row = gid.x, token = gid.y;\n"
            "    if (row >= a.ne0 || token >= a.nei1) return;\n"
            "    device const int *token_ids = (device const int *)(ids + (ulong)token * a.nbi1);\n"
            "    float s = 0.f;\n"
            "    for (int slot = 0; slot < (int)a.nei0; slot++) {\n"
            "        const int e = token_ids[slot];\n"
            "        if (e < 0 || e >= (int)a.ne02 || e >= 384) continue;\n"
            "        if (addrs[(uint)e] == 0) continue;\n"
            "        s += partial[((ulong)token * (ulong)a.nei0 + (ulong)slot) * (ulong)a.ne0 + row];\n"
            "    }\n"
            "    ((device float *)(dst + (ulong)token * a.nb1))[row] = s;\n"
            "    blk[(ulong)token * (ulong)a.ne0 + row] = s + sh[(ulong)token * (ulong)a.ne0 + row];\n"
            "}\n"
            "kernel void llms_sum6_add_dc(constant a6args &a [[buffer(0)]], device const ulong *addrs [[buffer(1)]], device const float *partial [[buffer(2)]],\n"   /* llms ROUTED_DC */
            "                          device char *dst [[buffer(3)]], device const char *ids [[buffer(4)]], device const float *sh [[buffer(5)]], device float *blk [[buffer(6)]],\n"
            "                          device const char *weights [[buffer(7)]], device const half *dcv [[buffer(8)]], constant ulong &wst [[buffer(9)]],\n"
            "                          uint3 gid [[thread_position_in_grid]]) {\n"
            "    const uint row = gid.x, token = gid.y;\n"
            "    if (row >= a.ne0 || token >= a.nei1) return;\n"
            "    device const int *token_ids = (device const int *)(ids + (ulong)token * a.nbi1);\n"
            "    float s = 0.f;\n"
            "    for (int slot = 0; slot < (int)a.nei0; slot++) {\n"
            "        const int e = token_ids[slot];\n"
            "        if (e < 0 || e >= (int)a.ne02 || e >= 384) continue;\n"
            "        if (addrs[(uint)e] == 0) continue;\n"
            "        const ulong pr_ = (ulong)token * (ulong)a.nei0 + (ulong)slot;\n"
            "        s += partial[pr_ * (ulong)a.ne0 + row];\n"
            "        s += ((device const float *)(weights + pr_ * wst))[0] * float(dcv[(ulong)(uint)e * 9728u + 4608u + row]);\n"
            "    }\n"
            "    ((device float *)(dst + (ulong)token * a.nb1))[row] = s;\n"
            "    blk[(ulong)token * (ulong)a.ne0 + row] = s + sh[(ulong)token * (ulong)a.ne0 + row];\n"
            "}\n";
            NSError *err = nil; id<MTLLibrary> lib = [g_device newLibraryWithSource:src options:nil error:&err];   /* the default options: the MoE library's math mode */
            add6_pipe = lib ? [g_device newComputePipelineStateWithFunction:[lib newFunctionWithName:@"llms_sum6_add"] error:&err] : nil;
            add6_dc_pipe = lib ? [g_device newComputePipelineStateWithFunction:[lib newFunctionWithName:@"llms_sum6_add_dc"] error:&err] : nil;   /* llms ROUTED_DC */
            if (!add6_pipe) { fprintf(stderr, "llms add6: OFF (compile: %s)\n", err ? [[err localizedDescription] UTF8String] : "?"); add6_state = 0; }
            else { fprintf(stderr, "llms: add6 (the verify's routed + shared add folded into the G32 down's six-slot sum; ALT add6)\n");
                   atexit_b(^{ fprintf(stderr, "llms add6: %llu calls armed, %llu fused, %llu invalidated (the separate add ran)\n", (unsigned long long)add6_armed_calls, (unsigned long long)add6_fused_calls, (unsigned long long)add6_invalid_calls); }); } } }
    add6.armed = 0; add6.done = 0;
    if (!add6_state || llms_alt_off("add6") || !routed || !shared || !block || rows == 0u) return 0;
    add6.rt = ds4_gpu_tensor_buffer(routed); add6.sh = ds4_gpu_tensor_buffer(shared); add6.blk = ds4_gpu_tensor_buffer(block);
    add6.rt_off = (NSUInteger)ds4_gpu_tensor_offset(routed); add6.sh_off = (NSUInteger)ds4_gpu_tensor_offset(shared); add6.blk_off = (NSUInteger)ds4_gpu_tensor_offset(block); add6.rows = rows;
    if (!add6.rt || !add6.sh || !add6.blk) return 0;
    add6.armed = 1; add6_armed_calls++; return 1;
}
void ds4_gpu_llms_add6_invalidate(void) { if (add6.armed && add6.done) add6_invalid_calls++; add6.armed = 0; add6.done = 0; }   /* shared is written after the routed call: add2 must run */
