static int ds4_gpu_glm_attention_flash_tensor_impl(
        ds4_gpu_tensor       *heads,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_len,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              qk_dim,
        uint32_t              value_dim,
        bool                  cache_f16,
        int                   kv_pre_staged) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!heads || !q || !key_cache || !value_cache ||
        n_tokens == 0 || cache_len == 0 || cache_cap == 0 ||
        n_head == 0 || qk_dim != 256u || value_dim != 256u ||
        cache_len > cache_cap ||
        pos0 > cache_len || n_tokens > cache_len - pos0 ||
        cache_len > ds4_gpu_glm_flash_attention_max_cache_len()) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> headsbuf = ds4_gpu_tensor_buffer(heads);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> keybuf = ds4_gpu_tensor_buffer(key_cache);
        id<MTLBuffer> valbuf = ds4_gpu_tensor_buffer(value_cache);
        const uint64_t heads_bytes = (uint64_t)n_tokens * n_head * value_dim * sizeof(float);
        const uint64_t q_bytes = (uint64_t)n_tokens * n_head * qk_dim * sizeof(float);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t key_bytes = (uint64_t)cache_cap * n_head * qk_dim * cache_elem_bytes;
        const uint64_t value_bytes = (uint64_t)cache_cap * n_head * value_dim * cache_elem_bytes;
        if (!headsbuf || !qbuf || !keybuf || !valbuf ||
            ds4_gpu_tensor_bytes(heads) < heads_bytes ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(key_cache) < key_bytes ||
            ds4_gpu_tensor_bytes(value_cache) < value_bytes) {
            fprintf(stderr, "ds4: Metal GLM FlashAttention received undersized buffers\n");
            return 0;
        }
        const uint64_t key_elems = (uint64_t)cache_len * n_head * qk_dim;
        const uint64_t value_elems = (uint64_t)cache_len * n_head * value_dim;
        if (key_elems > UINT32_MAX || value_elems > UINT32_MAX) {
            return 0;
        }

        const uint32_t nqptg = 8;
        const uint32_t ncpsg = 64;
        const uint32_t nsg = 4;
        const bool has_kvpad = (cache_len % ncpsg) != 0;
        const bool bc_mask = (n_tokens % nqptg) != 0;
        const NSUInteger q_row_bytes = (NSUInteger)qk_dim * sizeof(float);
        const NSUInteger q_row_bytes_f16 = (NSUInteger)qk_dim * sizeof(uint16_t);
        const NSUInteger v_row_bytes = (NSUInteger)value_dim * sizeof(float);
        const NSUInteger v_row_bytes_f16 = (NSUInteger)value_dim * sizeof(uint16_t);
        const NSUInteger mask_bytes = (NSUInteger)n_tokens * (NSUInteger)cache_len * sizeof(uint16_t);
        const NSUInteger key_f16_offset = 0;
        const NSUInteger key_f16_bytes =
            (NSUInteger)cache_len * (NSUInteger)n_head * q_row_bytes_f16;
        const NSUInteger value_f16_offset = key_f16_bytes;
        const NSUInteger value_f16_bytes =
            (NSUInteger)cache_len * (NSUInteger)n_head * v_row_bytes_f16;
        const NSUInteger kv_f16_bytes = key_f16_bytes + value_f16_bytes;
        const NSUInteger pad_bytes = has_kvpad
            ? (NSUInteger)ncpsg * ((NSUInteger)n_head * (q_row_bytes_f16 + v_row_bytes_f16) +
                                   (NSUInteger)n_tokens * sizeof(uint16_t))
            : 1u;
        const NSUInteger nblk0 = ((NSUInteger)cache_len + ncpsg - 1u) / ncpsg;
        const NSUInteger nblk1 = ((NSUInteger)n_tokens + nqptg - 1u) / nqptg;
        const NSUInteger blk_bytes = ds4_gpu_align_up_ns(nblk0 * nblk1, 32u);

        id<MTLBuffer> mask_buffer =
            ds4_gpu_glm_prefill_mask_buffer(pos0, n_tokens, cache_len, mask_bytes);
        if (!mask_buffer) return 0;
        if (kv_pre_staged) {
            if (!g_flash_attn_kv_buffer || g_flash_attn_kv_bytes < kv_f16_bytes) {
                fprintf(stderr, "ds4: GLM staged FlashAttention KV scratch is missing\n");
                return 0;
            }
        } else if (!ds4_gpu_ensure_scratch_buffer(&g_flash_attn_kv_buffer,
                                                  &g_flash_attn_kv_bytes,
                                                  kv_f16_bytes,
                                                  "ds4_glm_flash_attn_kv_f16")) {
            return 0;
        }
        if (!ds4_gpu_ensure_scratch_buffer(&g_flash_attn_pad_buffer,
                                             &g_flash_attn_pad_bytes,
                                             pad_bytes,
                                             "ds4_glm_flash_attn_pad") ||
            !ds4_gpu_ensure_scratch_buffer(&g_flash_attn_blk_buffer,
                                             &g_flash_attn_blk_bytes,
                                             blk_bytes,
                                             "ds4_glm_flash_attn_blk")) {
            return 0;
        }

        id<MTLComputePipelineState> pad_pipeline = nil;
        if (has_kvpad) {
            pad_pipeline = ds4_gpu_get_flash_attn_pad_pipeline(true, (int32_t)ncpsg);
            if (!pad_pipeline) return 0;
        }
        id<MTLComputePipelineState> blk_pipeline =
            ds4_gpu_get_flash_attn_blk_pipeline((int32_t)nqptg, (int32_t)ncpsg);
        id<MTLComputePipelineState> attn_pipeline =
            ds4_gpu_get_flash_attn_pipeline("kernel_flash_attn_ext_f16_dk256_dv256",
                                              true, false, false, false, has_kvpad, bc_mask,
                                              (int32_t)qk_dim,
                                              (int32_t)value_dim,
                                              (int32_t)nsg);
        if (!blk_pipeline || !attn_pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        if (!kv_pre_staged) {
            const bool copied = cache_f16 ?
                (ds4_gpu_encode_cpy_f16_f16_3d(cb,
                                               keybuf,
                                               ds4_gpu_tensor_offset(key_cache),
                                               g_flash_attn_kv_buffer,
                                               key_f16_offset,
                                               qk_dim,
                                               cache_len,
                                               n_head,
                                               (uint64_t)n_head * q_row_bytes_f16,
                                               q_row_bytes_f16,
                                               q_row_bytes_f16,
                                               (uint64_t)cache_len * q_row_bytes_f16) &&
                 ds4_gpu_encode_cpy_f16_f16_3d(cb,
                                               valbuf,
                                               ds4_gpu_tensor_offset(value_cache),
                                               g_flash_attn_kv_buffer,
                                               value_f16_offset,
                                               value_dim,
                                               cache_len,
                                               n_head,
                                               (uint64_t)n_head * v_row_bytes_f16,
                                               v_row_bytes_f16,
                                               v_row_bytes_f16,
                                               (uint64_t)cache_len * v_row_bytes_f16)) :
                (ds4_gpu_encode_cpy_f32_f16_3d(cb,
                                               keybuf,
                                               ds4_gpu_tensor_offset(key_cache),
                                               g_flash_attn_kv_buffer,
                                               key_f16_offset,
                                               qk_dim,
                                               cache_len,
                                               n_head,
                                               (uint64_t)n_head * q_row_bytes,
                                               q_row_bytes,
                                               q_row_bytes_f16,
                                               (uint64_t)cache_len * q_row_bytes_f16) &&
                 ds4_gpu_encode_cpy_f32_f16_3d(cb,
                                               valbuf,
                                               ds4_gpu_tensor_offset(value_cache),
                                               g_flash_attn_kv_buffer,
                                               value_f16_offset,
                                               value_dim,
                                               cache_len,
                                               n_head,
                                               (uint64_t)n_head * v_row_bytes,
                                               v_row_bytes,
                                               v_row_bytes_f16,
                                               (uint64_t)cache_len * v_row_bytes_f16));
            if (!copied) {
                return 0;
            }
        }

        if (has_kvpad) {
            ds4_gpu_flash_attn_pad_args pad_args = {
                .ne11 = (int32_t)cache_len,
                .ne_12_2 = (int32_t)n_head,
                .ne_12_3 = 1,
                .nb11 = q_row_bytes_f16,
                .nb12 = (uint64_t)cache_len * q_row_bytes_f16,
                .nb13 = (uint64_t)cache_len * (uint64_t)n_head * q_row_bytes_f16,
                .nb21 = v_row_bytes_f16,
                .nb22 = (uint64_t)cache_len * v_row_bytes_f16,
                .nb23 = (uint64_t)cache_len * (uint64_t)n_head * v_row_bytes_f16,
                .ne31 = (int32_t)n_tokens,
                .ne32 = 1,
                .ne33 = 1,
                .nb31 = (uint64_t)cache_len * sizeof(uint16_t),
                .nb32 = mask_bytes,
                .nb33 = mask_bytes,
            };

            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:pad_pipeline];
            [enc setBytes:&pad_args length:sizeof(pad_args) atIndex:0];
            [enc setBuffer:g_flash_attn_kv_buffer offset:key_f16_offset atIndex:1];
            [enc setBuffer:g_flash_attn_kv_buffer offset:value_f16_offset atIndex:2];
            [enc setBuffer:mask_buffer offset:0 atIndex:3];
            [enc setBuffer:g_flash_attn_pad_buffer offset:0 atIndex:4];
            [enc dispatchThreadgroups:MTLSizeMake(ncpsg, n_head, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
        }

        ds4_gpu_flash_attn_blk_args blk_args = {
            .ne01 = (int32_t)n_tokens,
            .ne30 = (int32_t)cache_len,
            .ne31 = (int32_t)n_tokens,
            .ne32 = 1,
            .ne33 = 1,
            .nb31 = (uint64_t)cache_len * sizeof(uint16_t),
            .nb32 = mask_bytes,
            .nb33 = mask_bytes,
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:blk_pipeline];
        [enc setBytes:&blk_args length:sizeof(blk_args) atIndex:0];
        [enc setBuffer:mask_buffer offset:0 atIndex:1];
        [enc setBuffer:g_flash_attn_blk_buffer offset:0 atIndex:2];
        [enc dispatchThreadgroups:MTLSizeMake(nblk0, nblk1, 1)
             threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        ds4_gpu_flash_attn_vec_args args = {
            .ne01 = (int32_t)n_tokens,
            .ne02 = (int32_t)n_head,
            .ne03 = 1,
            .nb01 = (uint64_t)n_head * q_row_bytes,
            .nb02 = q_row_bytes,
            .nb03 = (uint64_t)n_tokens * n_head * q_row_bytes,
            .ne11 = (int32_t)cache_len,
            .ne_12_2 = (int32_t)n_head,
            .ne_12_3 = 1,
            .ns10 = (int32_t)qk_dim,
            .nb11 = q_row_bytes_f16,
            .nb12 = (uint64_t)cache_len * q_row_bytes_f16,
            .nb13 = (uint64_t)cache_len * (uint64_t)n_head * q_row_bytes_f16,
            .ns20 = (int32_t)value_dim,
            .nb21 = v_row_bytes_f16,
            .nb22 = (uint64_t)cache_len * v_row_bytes_f16,
            .nb23 = (uint64_t)cache_len * (uint64_t)n_head * v_row_bytes_f16,
            .ne31 = (int32_t)n_tokens,
            .ne32 = 1,
            .ne33 = 1,
            .nb31 = (uint64_t)cache_len * sizeof(uint16_t),
            .nb32 = mask_bytes,
            .nb33 = mask_bytes,
            .ne1 = (int32_t)n_head,
            .ne2 = (int32_t)n_tokens,
            .ne3 = 1,
            .scale = 1.0f / sqrtf((float)qk_dim),
            .max_bias = 0.0f,
            .m0 = 0.0f,
            .m1 = 0.0f,
            .n_head_log2 = 0,
            .logit_softcap = 0.0f,
        };

        const NSUInteger padded_v = ds4_gpu_align_up_ns(value_dim, 64u);
        const NSUInteger shared_elems = (NSUInteger)nqptg *
            ((NSUInteger)qk_dim + 2u * padded_v + 2u * (2u * (NSUInteger)ncpsg));
        const NSUInteger shared_bytes = ds4_gpu_align_up_ns(shared_elems * (sizeof(float) / 2u), 16u);

        enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:attn_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:g_flash_attn_kv_buffer offset:key_f16_offset atIndex:2];
        [enc setBuffer:g_flash_attn_kv_buffer offset:value_f16_offset atIndex:3];
        [enc setBuffer:mask_buffer offset:0 atIndex:4];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:5];
        [enc setBuffer:g_flash_attn_pad_buffer offset:0 atIndex:6];
        [enc setBuffer:g_flash_attn_blk_buffer offset:0 atIndex:7];
        [enc setBuffer:headsbuf offset:ds4_gpu_tensor_offset(heads) atIndex:8];
        [enc setThreadgroupMemoryLength:shared_bytes atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(nblk1, n_head, 1)
             threadsPerThreadgroup:MTLSizeMake(32, nsg, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM FlashAttention")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_attention_flash_tensor(
        ds4_gpu_tensor       *heads,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_len,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              qk_dim,
        uint32_t              value_dim,
        bool                  cache_f16) {
    return ds4_gpu_glm_attention_flash_tensor_impl(heads,
                                                   q,
                                                   key_cache,
                                                   value_cache,
                                                   pos0,
                                                   n_tokens,
                                                   cache_len,
                                                   cache_cap,
                                                   n_head,
                                                   qk_dim,
                                                   value_dim,
                                                   cache_f16,
                                                   0);
}

int ds4_gpu_glm_attention_flash_staged_tensor(
        ds4_gpu_tensor       *heads,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_len,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              qk_dim,
        uint32_t              value_dim,
        bool                  cache_f16) {
    if (pos0 != 0 || n_tokens != cache_len) return 0;
    return ds4_gpu_glm_attention_flash_tensor_impl(heads,
                                                   q,
                                                   key_cache,
                                                   value_cache,
                                                   pos0,
                                                   n_tokens,
                                                   cache_len,
                                                   cache_cap,
                                                   n_head,
                                                   qk_dim,
                                                   value_dim,
                                                   cache_f16,
                                                   1);
}

int ds4_gpu_glm_attention_full_tensor(
        ds4_gpu_tensor       *heads,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_len,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              qk_dim,
        uint32_t              value_dim,
        bool                  cache_f16) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!heads || !q || !key_cache || !value_cache ||
        n_tokens == 0 || cache_len == 0 || cache_cap == 0 ||
        n_head == 0 || qk_dim == 0 || value_dim == 0 ||
        (qk_dim & 3u) != 0 ||
        cache_len > cache_cap ||
        pos0 > cache_len || n_tokens > cache_len - pos0 ||
        cache_len > ds4_gpu_glm_full_attention_max_cache_len()) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> headsbuf = ds4_gpu_tensor_buffer(heads);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> keybuf = ds4_gpu_tensor_buffer(key_cache);
        id<MTLBuffer> valbuf = ds4_gpu_tensor_buffer(value_cache);
        const uint64_t heads_bytes = (uint64_t)n_tokens * n_head * value_dim * sizeof(float);
        const uint64_t q_bytes = (uint64_t)n_tokens * n_head * qk_dim * sizeof(float);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t key_bytes = (uint64_t)cache_cap * n_head * qk_dim * cache_elem_bytes;
        const uint64_t value_bytes = (uint64_t)cache_cap * n_head * value_dim * cache_elem_bytes;
        if (!headsbuf || !qbuf || !keybuf || !valbuf ||
            ds4_gpu_tensor_bytes(heads) < heads_bytes ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(key_cache) < key_bytes ||
            ds4_gpu_tensor_bytes(value_cache) < value_bytes) {
            fprintf(stderr, "ds4: Metal GLM attention received undersized buffers\n");
            return 0;
        }

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_attention_full_pipeline,
                                 "kernel_glm_attention_full");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        const uint32_t full_attn_mode = 2u;
        ds4_gpu_glm_attention_full_args args = {
            .pos0 = pos0,
            .n_tokens = n_tokens,
            .cache_len = cache_len,
            .cache_cap = cache_cap,
            .n_head = n_head,
            .qk_dim = qk_dim,
            .value_dim = value_dim,
            .pad0 = full_attn_mode,
            .cache_f16 = cache_f16 ? 1u : 0u,
            .pad1 = 0u,
            .pad2 = 0u,
            .scale = 1.0f / sqrtf((float)qk_dim),
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:keybuf offset:ds4_gpu_tensor_offset(key_cache) atIndex:2];
        [enc setBuffer:valbuf offset:ds4_gpu_tensor_offset(value_cache) atIndex:3];
        [enc setBuffer:headsbuf offset:ds4_gpu_tensor_offset(heads) atIndex:4];
        [enc setThreadgroupMemoryLength:ds4_gpu_align_up_ns(
                (256u + (NSUInteger)cache_len) * sizeof(float), 16u) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_tokens, (NSUInteger)n_head, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM full attention")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_fill_selected_range_tensor(
        ds4_gpu_tensor *selected,
        uint32_t        n_selected) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!selected || n_selected == 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        const uint64_t selected_bytes = (uint64_t)n_selected * sizeof(uint32_t);
        if (!selectedbuf || ds4_gpu_tensor_bytes(selected) < selected_bytes) {
            fprintf(stderr, "ds4: Metal GLM selected range received undersized buffer\n");
            return 0;
        }

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_fill_selected_range_pipeline,
                                 "kernel_glm_fill_selected_range");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_fill_selected_range_args args = {
            .n_selected = n_selected,
        };
        const NSUInteger nth = 256u;
        const NSUInteger n_groups = ((NSUInteger)n_selected + nth - 1u) / nth;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:selectedbuf offset:ds4_gpu_tensor_offset(selected) atIndex:1];
        [enc dispatchThreadgroups:MTLSizeMake(n_groups, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM selected range")) return 0;
    }

    return 1;
}


static int ds4_gpu_glm_rope_tail_offset_tensor(
        ds4_gpu_tensor *x,
        uint32_t        n_tokens,
        uint32_t        n_head,
        uint32_t        head_dim,
        uint32_t        rot_dim,
        uint32_t        rot_offset,
        uint32_t        pos0,
        uint32_t        n_ctx_orig,
        float           freq_base,
        float           freq_scale,
        float           ext_factor,
        float           attn_factor,
        float           beta_fast,
        float           beta_slow,
        const char     *label) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!x || n_tokens == 0 || n_head == 0 || head_dim == 0 ||
        rot_dim == 0 || rot_offset > head_dim || rot_dim > head_dim - rot_offset ||
        (rot_dim & 1u) != 0 ||
        pos0 > UINT32_MAX - n_tokens ||
        !isfinite(freq_base) || freq_base <= 0.0f ||
        !isfinite(freq_scale) || freq_scale <= 0.0f ||
        !isfinite(ext_factor) || !isfinite(attn_factor) ||
        !isfinite(beta_fast) || !isfinite(beta_slow)) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        const uint64_t bytes = (uint64_t)n_tokens * n_head * head_dim * sizeof(float);
        if (!xbuf || ds4_gpu_tensor_bytes(x) < bytes) {
            fprintf(stderr, "ds4: Metal %s received undersized buffer\n",
                    label ? label : "GLM RoPE");
            return 0;
        }

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_indexer_rope_tail_pipeline,
                                 "kernel_glm_indexer_rope_tail_f32");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_rope_tail_args args = {
            .n_tokens = n_tokens,
            .n_head = n_head,
            .head_dim = head_dim,
            .rot_dim = rot_dim,
            .rot_offset = rot_offset,
            .pos0 = pos0,
            .n_ctx_orig = n_ctx_orig,
            .freq_base = freq_base,
            .freq_scale = freq_scale,
            .ext_factor = ext_factor,
            .attn_factor = attn_factor,
            .beta_fast = beta_fast,
            .beta_slow = beta_slow,
        };
        const NSUInteger nth = ds4_gpu_rms_norm_threads(rot_dim);

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_head, (NSUInteger)n_tokens, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, label ? label : "GLM RoPE")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_rope_tail_tensor(
        ds4_gpu_tensor *x,
        uint32_t        n_tokens,
        uint32_t        n_head,
        uint32_t        head_dim,
        uint32_t        rot_dim,
        uint32_t        pos0,
        uint32_t        n_ctx_orig,
        float           freq_base,
        float           freq_scale,
        float           ext_factor,
        float           attn_factor,
        float           beta_fast,
        float           beta_slow) {
    if (rot_dim > head_dim) return 0;
    return ds4_gpu_glm_rope_tail_offset_tensor(x,
                                               n_tokens,
                                               n_head,
                                               head_dim,
                                               rot_dim,
                                               head_dim - rot_dim,
                                               pos0,
                                               n_ctx_orig,
                                               freq_base,
                                               freq_scale,
                                               ext_factor,
                                               attn_factor,
                                               beta_fast,
                                               beta_slow,
                                               "GLM RoPE");
}

int ds4_gpu_glm_indexer_rope_tail_tensor(
        ds4_gpu_tensor *x,
        uint32_t        n_tokens,
        uint32_t        n_head,
        uint32_t        head_dim,
        uint32_t        rot_dim,
        uint32_t        pos0,
        uint32_t        n_ctx_orig,
        float           freq_base,
        float           freq_scale,
        float           ext_factor,
        float           attn_factor,
        float           beta_fast,
        float           beta_slow) {
    return ds4_gpu_glm_rope_tail_offset_tensor(x,
                                               n_tokens,
                                               n_head,
                                               head_dim,
                                               rot_dim,
                                               0,
                                               pos0,
                                               n_ctx_orig,
                                               freq_base,
                                               freq_scale,
                                               ext_factor,
                                               attn_factor,
                                               beta_fast,
                                               beta_slow,
                                               "GLM indexer RoPE");
}

/* llms LLMS_DS4_IDX_SCORE_SG: indexer score with 4 rows per simdgroup (apply_ds4_idx_score_sg.py); the kernel exists only in the
 * replacement source build_idx/dsv4_misc_sg.metal (DS4_METAL_DSV4_MISC_SOURCE), so the switch is on only when both are set.
 * 1 = on, 2 = canary (grid sized for half the rows). */
static uint64_t index_score_sg_calls, index_score_sg_rows;
static void report_index_score_sg(void) { fprintf(stderr, "llms idx score sg: %llu dispatches, %llu rows\n",
    (unsigned long long)index_score_sg_calls, (unsigned long long)index_score_sg_rows); }
/* llms IDX_SCORE_SGM (apply_ds4_idx_score_sgm.py): the indexer score on simdgroup-matrix tiles. 2 / 4 / 8 = row tiles per simdgroup; 4 adopted, the compiled
   default since 10-27 (=0 off); its *llms4* source check kept */
static int index_score_sgm_on(void) {
    static int on = -99;
    if (on == -99) {
        const char *e = getenv("LLMS_DS4_IDX_SCORE_SGM"), *src = getenv("DS4_METAL_DSV4_MISC_SOURCE");
        on = !e || !*e ? 4 : *e == '0' ? 0 : atoi(e);
        if (on != 0 && on != 2 && on != 4 && on != 8) on = 4;
        if (on && !(src && llms_srckey(src, "llms4") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_IDX_SCORE_SGM ignored: DS4_METAL_DSV4_MISC_SOURCE does not name a *llms4.metal source\n"), LLMS_G_NAME); on = 0; }
        if (on && on != 4) fprintf(stderr, "llms: indexer score on tiles (%d row tiles per simdgroup; NOT bit-exact)\n", on);
    }
    return on;
}
static int index_score_sg_on(void) {
    static int on = -1;
    if (on < 0) {
        const char *e = getenv("LLMS_DS4_IDX_SCORE_SG"), *src = getenv("DS4_METAL_DSV4_MISC_SOURCE");
        const int want = e && *e && *e != '0';
        on = want && src && llms_srckey(src, "dsv4_misc_sg") != NULL ? (!strcmp(e, "canary") ? 2 : 1) : 0;
        if (want) fprintf(stderr, on == 2 ? "llms: indexer score, 4 rows per simdgroup -- CANARY: grid sized for half the rows\n" :
                                  on ? "llms: indexer score with 4 rows per simdgroup\n" :
                                       "llms: LLMS_DS4_IDX_SCORE_SG ignored: DS4_METAL_DSV4_MISC_SOURCE does not name dsv4_misc_sg\n");
        if (want && !on) llms_guard_fail(LLMS_G_NAME);
        if (on) atexit(report_index_score_sg);
    }
    return on;
}
int ds4_gpu_llms_idx_rows_ok(void) {   /* llms SP_IDXB: the per-row score's IDX_HALF branch with the t4 body, not its canary, and the rows kernel present */
    static int ok = -1;
    if (ok < 0) { const char *src = getenv("DS4_METAL_DSV4_MISC_SOURCE");
                  const int ih = src && llms_srckey(src, "llms13") != NULL;   /* IDX_HALF (adopted; the switch removed 10-27) */
                  ok = ih && has_kernel("kernel_llms_indexer_score_rows_h_t4");   /* llms HAS_KERNEL */
                  if (!ok) fprintf(stderr, "llms sp idxb: OFF (IDX_HALF %d, rows kernel %s: the *_idxr misc source)\n", ih, has_kernel("kernel_llms_indexer_score_rows_h_t4") ? "ok" : "missing"); }
    return ok && index_score_sgm_on() == 4 && !llms_alt_off("idxsgm");
}
int ds4_gpu_llms_indexer_score_rows(ds4_gpu_tensor *scores, const ds4_gpu_tensor *q, const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *cache, const uint32_t *ncomp, uint32_t rows, uint32_t stride,
        const ds4_gpu_tensor *mask, uint32_t mask_stride, uint32_t mask_base) {   /* llms SP_IDXB: every row's scores in one dispatch */
    static id<MTLComputePipelineState> pipelines[2];
    const unsigned which = mask != NULL;
    if (!pipelines[which]) pipelines[which] = ds4_gpu_get_pipeline_or_die(which ? "masked_rows" : "kernel_llms_indexer_score_rows_h_t4");
    id<MTLComputePipelineState> p = pipelines[which];
    if (!p || rows == 0u || rows > row_paths_cap()) return 0;   /* llms ROWS_CAP2: was 128 (the first wall of the 256-row call, 18:04) */
    @autoreleasepool {
        id<MTLBuffer> sb = ds4_gpu_tensor_buffer(scores), qb = ds4_gpu_tensor_buffer(q), wb = ds4_gpu_tensor_buffer(weights), kb = ds4_gpu_tensor_buffer(cache);
        if (!sb || !qb || !wb || !kb) return 0;
        id<MTLBuffer> mb = mask ? ds4_gpu_tensor_buffer(mask) : nil;
        if (mask && (!mb || mask_stride == 0u ||
            ((uint64_t)mask_base + rows) * mask_stride * sizeof(float) > ds4_gpu_tensor_bytes(mask))) return 0;
        ds4_gpu_glm_indexer_score_one_args a[1024]; uint32_t nmax = 0;   /* llms ROWS_CAP4: was 128 */
        for (uint32_t i = 0; i < rows; i++) {
            if (mask && (ncomp[i] + 7u) / 8u > mask_stride) return 0;
            if (ncomp[i] < 32u || ncomp[i] > stride) return 0;   /* the t4 body's own minimum; the slice holds the row */
            a[i] = (ds4_gpu_glm_indexer_score_one_args){ .n_rows = ncomp[i], .n_head = 32u, .head_dim = 128u, .cache_f16 = 1u, .scale = 1.0f / 64.0f };
            if (ncomp[i] > nmax) nmax = ncomp[i];
        }
        const struct { uint32_t rows, stride; } bb = { rows, stride };
        const NSUInteger nblk = ((NSUInteger)nmax + 31u) / 32u;
        int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:p];
        bind_rows_bytes(enc, a, (NSUInteger)rows * sizeof(a[0]), 0);   /* llms ROWS_CAP4 */
        [enc setBuffer:qb offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:wb offset:ds4_gpu_tensor_offset(weights) atIndex:2];
        [enc setBuffer:kb offset:ds4_gpu_tensor_offset(cache) atIndex:3];
        [enc setBuffer:sb offset:ds4_gpu_tensor_offset(scores) atIndex:4];
        [enc setBytes:&bb length:sizeof bb atIndex:5];
        if (mask) {
            [enc setBuffer:mb offset:ds4_gpu_tensor_offset(mask) + (uint64_t)mask_base * mask_stride * sizeof(float) atIndex:6];
            [enc setBytes:&mask_stride length:sizeof mask_stride atIndex:7];
        }
        [enc setThreadgroupMemoryLength:32u * 32u * sizeof(float) + 32u * 128u * sizeof(uint16_t) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(MIN(nblk, (NSUInteger)256u), (NSUInteger)rows, 1) threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned, "llms sp idxb scores")) return 0;
    }
    return 1;
}
int ds4_gpu_glm_indexer_score_one_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *indexer_key_cache,
        uint32_t              n_rows,
        uint32_t              n_head,
        uint32_t              head_dim,
        float                 scale,
        bool                  cache_f16) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!scores || !q || !weights || !indexer_key_cache ||
        n_rows == 0 || n_head == 0 || head_dim == 0 ||
        !isfinite(scale) || scale <= 0.0f) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> scoresbuf = ds4_gpu_tensor_buffer(scores);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> cachebuf = ds4_gpu_tensor_buffer(indexer_key_cache);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t score_bytes = (uint64_t)n_rows * sizeof(float);
        const uint64_t q_bytes = (uint64_t)n_head * head_dim * sizeof(float);
        const uint64_t weights_bytes = (uint64_t)n_head * sizeof(float);
        const uint64_t cache_bytes = (uint64_t)n_rows * head_dim * cache_elem_bytes;
        if (!scoresbuf || !qbuf || !weightsbuf || !cachebuf ||
            ds4_gpu_tensor_bytes(scores) < score_bytes ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(weights) < weights_bytes ||
            ds4_gpu_tensor_bytes(indexer_key_cache) < cache_bytes) {
            fprintf(stderr, "ds4: Metal GLM indexer score received undersized buffers\n");
            return 0;
        }

        ds4_gpu_glm_indexer_score_one_args args = {
            .n_rows = n_rows,
            .n_head = n_head,
            .head_dim = head_dim,
            .cache_f16 = cache_f16 ? 1u : 0u,
            .scale = scale,
        };

        {   /* llms IDX_HALF: the SGM kernel on a half key cache (llms13 misc source) */
            static int indexer_source_is_llms13 = -2;
            if (indexer_source_is_llms13 < -1) { const char *src = getenv("DS4_METAL_DSV4_MISC_SOURCE"); indexer_source_is_llms13 = src && llms_srckey(src, "llms13") != NULL; }   /* adopted; the switch removed 10-27 */
            if (n_head == 32u && head_dim == 128u && cache_f16 && indexer_source_is_llms13 && index_score_sgm_on() > 0 && !llms_alt_off("idxsgm")) {
                const int nrt = index_score_sgm_on(); const NSUInteger nr = (NSUInteger)nrt * 8u;
                static char indexer_sgm_kernel_name[48]; snprintf(indexer_sgm_kernel_name, sizeof indexer_sgm_kernel_name, "kernel_llms_indexer_score_sgm_h_t%d", nrt);
                id<MTLComputePipelineState> tp = n_rows >= nr ? ds4_gpu_get_pipeline_or_die(indexer_sgm_kernel_name) : nil;
                if (tp) {
                    int owned = 0;
                    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                    if (!cb) return 0;
                    ds4_gpu_glm_indexer_score_one_args hargs = args;   /* persistent kernel (07:2x): the grid is capped; the canary scores half the rows */
                    const NSUInteger nblk = ((NSUInteger)hargs.n_rows + nr - 1u) / nr;
                    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                    [enc setComputePipelineState:tp];
                    [enc setBytes:&hargs length:sizeof(hargs) atIndex:0];
                    [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
                    [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
                    [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
                    [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
                    [enc setThreadgroupMemoryLength:nr * 32u * sizeof(float) + 32u * 128u * sizeof(uint16_t) atIndex:0];
                    [enc dispatchThreadgroups:MTLSizeMake(MIN(nblk, (NSUInteger)256u), 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
                    ds4_gpu_end_compute_encoder(cb, enc);
                    if (!ds4_gpu_finish_command_buffer(cb, owned, "llms indexer score sgm half")) return 0;
                    return 1;
                }
            }
        }
        if (n_head == 32u && head_dim == 128u && !cache_f16 && index_score_sgm_on() && !llms_alt_off("idxsgm")) {   /* llms IDX_SCORE_SGM; ALT */
            const int nrt = index_score_sgm_on(); const NSUInteger nr = (NSUInteger)nrt * 8u;
            static char nm[48]; snprintf(nm, sizeof nm, "kernel_llms_indexer_score_sgm_t%d", nrt);
            id<MTLComputePipelineState> tp = n_rows >= nr ? ds4_gpu_get_pipeline_or_die(nm) : nil;
            if (tp) {
                int owned = 0;
                id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                if (!cb) return 0;
                const NSUInteger grid_rows = (NSUInteger)n_rows;
                id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                [enc setComputePipelineState:tp];
                [enc setBytes:&args length:sizeof(args) atIndex:0];
                [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
                [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
                [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
                [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
                [enc setThreadgroupMemoryLength:nr * 32u * sizeof(float) atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake((grid_rows + nr - 1u) / nr, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);
                if (!ds4_gpu_finish_command_buffer(cb, owned, "llms indexer score sgm")) return 0;
                return 1;
            }
        }
        if (n_head == 32u && head_dim == 128u && !cache_f16 && index_score_sg_on()) {   /* llms IDX_SCORE_SG */
            id<MTLComputePipelineState> sg_pipeline = ds4_gpu_get_pipeline_or_die("kernel_glm_indexer_score_one_sg");
            if (!sg_pipeline) return 0;
            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;
            const NSUInteger sg_rows = index_score_sg_on() == 2 ? ((NSUInteger)n_rows + 1u) / 2u : (NSUInteger)n_rows;
            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:sg_pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
            [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
            [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
            [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
            [enc dispatchThreadgroups:MTLSizeMake((sg_rows + 15u) / 16u, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
            index_score_sg_calls++; index_score_sg_rows += n_rows;
            if (!ds4_gpu_finish_command_buffer(cb, owned, "llms indexer score sg")) return 0;
            return 1;
        }
        if (n_head == 32u && head_dim == 128u) {
            id<MTLComputePipelineState> direct_pipeline =
                ds4_gpu_hot_pipeline(g_glm_indexer_score_one_direct_pipeline,
                                     "kernel_glm_indexer_score_one_direct");
            if (!direct_pipeline) return 0;

            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;

            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:direct_pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
            [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
            [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
            [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
            [enc setThreadgroupMemoryLength:(128u + 4u) * sizeof(float) atIndex:0];
            [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM indexer direct score")) return 0;
            return 1;
        }

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_indexer_score_one_pipeline,
                                 "kernel_glm_indexer_score_one");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        const NSUInteger nth = ds4_gpu_rms_norm_threads(head_dim);

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
        [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
        [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
        [enc setThreadgroupMemoryLength:nth * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM indexer score")) return 0;
    }

    return 1;
}

static int ds4_gpu_glm_indexer_scores_batch_grouped_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *indexer_key_cache,
        uint32_t              n_rows,
        uint32_t              n_tokens,
        uint32_t              pos0,
        uint32_t              row_group_size,
        uint32_t              n_head,
        uint32_t              head_dim,
        float                 scale,
        bool                  cache_f16,
        bool                  tiled_f32) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!scores || !q || !weights || !indexer_key_cache ||
        n_rows == 0 || n_tokens == 0 || row_group_size == 0 ||
        n_head == 0 || head_dim != 128 ||
        pos0 > UINT32_MAX - n_tokens ||
        (uint64_t)(pos0 + n_tokens) / row_group_size > n_rows ||
        !isfinite(scale) || scale <= 0.0f) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> scoresbuf = ds4_gpu_tensor_buffer(scores);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> cachebuf = ds4_gpu_tensor_buffer(indexer_key_cache);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t score_bytes = (uint64_t)n_rows * n_tokens * sizeof(float);
        const uint64_t q_bytes = (uint64_t)n_tokens * n_head * head_dim * sizeof(float);
        const uint64_t weights_bytes = (uint64_t)n_tokens * n_head * sizeof(float);
        const uint64_t cache_bytes = (uint64_t)n_rows * head_dim * cache_elem_bytes;
        if (!scoresbuf || !qbuf || !weightsbuf || !cachebuf ||
            ds4_gpu_tensor_bytes(scores) < score_bytes ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(weights) < weights_bytes ||
            ds4_gpu_tensor_bytes(indexer_key_cache) < cache_bytes) {
            fprintf(stderr, "ds4: Metal GLM indexer batch scores received undersized buffers\n");
            return 0;
        }

        const bool force_scalar = g_quality_mode;
        const bool use_tiled_f32 = tiled_f32;
        const bool use_tiled = !force_scalar && n_tokens >= 8u &&
                               n_head == 32u && head_dim == 128u;
        static int shared_k = -1;
        if (shared_k < 0) { const char *v = getenv("LLMS_DS4_INDEX_SHARED_K"); shared_k = v && *v && *v != '0'; }
        const bool use_shared_k = shared_k && use_tiled && use_tiled_f32;
        static unsigned long long llms_sk_hits = 0; static int llms_sk_reg = 0;   /* the hit counter (apply_astra3.py): a gate verifies the shared-key kernel ran */
        id<MTLComputePipelineState> pipeline =
            use_shared_k ? ds4_gpu_get_pipeline_or_die("kernel_astra_index_mma_shared_k") :
            use_tiled
                ? ds4_gpu_hot_pipeline(use_tiled_f32 ? g_glm_indexer_scores_tiled_f32_pipeline
                                                     : g_glm_indexer_scores_tiled_pipeline,
                                       use_tiled_f32 ? "kernel_glm_indexer_scores_tiled_f32"
                                                     : "kernel_glm_indexer_scores_tiled")
                : ds4_gpu_hot_pipeline(g_glm_indexer_scores_batch_pipeline,
                                       "kernel_glm_indexer_scores_batch");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_indexer_scores_batch_args args = {
            .n_rows = n_rows,
            .n_tokens = n_tokens,
            .n_head = n_head,
            .head_dim = head_dim,
            .pos0 = pos0,
            .cache_f16 = cache_f16 ? 1u : 0u,
            .row_group_size = row_group_size,
            .pad0 = 0,
            .q_token_stride = (uint64_t)n_head * head_dim * sizeof(float),
            .q_head_stride = (uint64_t)head_dim * sizeof(float),
            .weights_token_stride = (uint64_t)n_head * sizeof(float),
            .score_token_stride = (uint64_t)n_rows * sizeof(float),
            .scale = scale,
        };
        const NSUInteger nth = ds4_gpu_rms_norm_threads(head_dim);

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
        [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
        [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
        if (use_tiled) {
            const NSUInteger q_shared = 8u * 128u;
            const NSUInteger k_shared = 32u * 128u;
            const NSUInteger dot_shared = 8u * 32u;
            if (use_tiled_f32) {
                [enc setThreadgroupMemoryLength:(use_shared_k ? k_shared : (q_shared + k_shared + dot_shared)) *
                                                sizeof(float) atIndex:0];
            } else {
                [enc setThreadgroupMemoryLength:(q_shared + k_shared) * sizeof(uint16_t) +
                                                dot_shared * sizeof(float) atIndex:0];
            }
            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_rows + 31u) / 32u,
                                                  ((NSUInteger)n_tokens + 7u) / 8u,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
        } else {
            [enc setThreadgroupMemoryLength:nth * sizeof(float) atIndex:0];
            [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows,
                                                  (NSUInteger)n_tokens,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        }
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM indexer batch scores")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_indexer_scores_batch_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *indexer_key_cache,
        uint32_t              n_rows,
        uint32_t              n_tokens,
        uint32_t              pos0,
        uint32_t              n_head,
        uint32_t              head_dim,
        float                 scale,
        bool                  cache_f16) {
    return ds4_gpu_glm_indexer_scores_batch_grouped_tensor(
            scores, q, weights, indexer_key_cache, n_rows, n_tokens, pos0, 1u,
            n_head, head_dim, scale, cache_f16, false);
}

int ds4_gpu_glm53_indexer_scores_batch_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *indexer_key_cache,
        uint32_t              n_rows,
        uint32_t              n_tokens,
        uint32_t              pos0,
        uint32_t              pool_size,
        uint32_t              n_head,
        uint32_t              head_dim,
        float                 scale,
        bool                  cache_f16) {
    if (pool_size != 4u) return 0;
    return ds4_gpu_glm_indexer_scores_batch_grouped_tensor(
            scores, q, weights, indexer_key_cache, n_rows, n_tokens, pos0,
            pool_size, n_head, head_dim, scale, cache_f16, false);
}

int ds4_gpu_dsv41_tensor_ops_available(void) {
    return ds4_gpu_mpp_available() && !g_quality_mode;
}

static uint64_t ds4_gpu_dsv41_indexer_flags_bytes(uint32_t source_rows, uint32_t rows) {
    return (((uint64_t)rows + ((uint64_t)source_rows + 63u) / 64u) * 4u + 255u) & ~UINT64_C(255);
}

uint64_t ds4_gpu_dsv41_indexer_packed_bytes(uint32_t source_rows, uint32_t rows) {
    return ds4_gpu_dsv41_indexer_flags_bytes(source_rows, rows) +
        (uint64_t)rows * 32u * 128u * 2u + (((uint64_t)source_rows + 63u) / 64u) * 64u * 128u * 2u;
}

int ds4_gpu_dsv41_indexer_pack(ds4_gpu_tensor *packed,
                              const ds4_gpu_tensor *q, const ds4_gpu_tensor *keys,
                              uint32_t source_rows, uint32_t rows) {
    if (!source_rows || source_rows > INT32_MAX || !rows || rows > INT32_MAX ||
        !ds4_gpu_dsv41_tensor_ops_available()) return 0;
    const ds4_gpu_tensor *tensors[] = {q, keys, packed};
    const uint64_t bytes[] = {(uint64_t)rows * 32u * 128u * 4u,
        (uint64_t)source_rows * 128u * 4u, ds4_gpu_dsv41_indexer_packed_bytes(source_rows, rows)};
    for (uint32_t i = 0; i < 3; i++)
        if (!tensors[i] || !ds4_gpu_tensor_buffer(tensors[i]) || ds4_gpu_tensor_bytes(tensors[i]) < bytes[i])
            return 0;
    @autoreleasepool {
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline_or_die("kernel_dsv41_indexer_pack");
        if (!pipeline) return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
        if (!enc) return 0;
        const uint32_t args[] = {source_rows, rows, 0, 0};
        const uint64_t flags_bytes = ds4_gpu_dsv41_indexer_flags_bytes(source_rows, rows);
        const uint64_t offset = ds4_gpu_tensor_offset(packed);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:args length:sizeof(args) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(q) offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:ds4_gpu_tensor_buffer(keys) offset:ds4_gpu_tensor_offset(keys) atIndex:2];
        [enc setBuffer:ds4_gpu_tensor_buffer(packed) offset:offset atIndex:3];
        [enc setBuffer:ds4_gpu_tensor_buffer(packed) offset:offset + flags_bytes atIndex:4];
        [enc setBuffer:ds4_gpu_tensor_buffer(packed) offset:offset + flags_bytes + (uint64_t)rows * 8192u atIndex:5];
        [enc setThreadgroupMemoryLength:16 atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)rows + ((NSUInteger)source_rows + 63u) / 64u, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "V4.1 index input packing");
    }
}

int ds4_gpu_dsv41_indexer_scores_packed(ds4_gpu_tensor *scores,
                                      const ds4_gpu_tensor *q,
                                      const ds4_gpu_tensor *weights,
                                      const ds4_gpu_tensor *keys,
                                      const ds4_gpu_tensor *packed,
                                      uint32_t source_rows, uint32_t rows,
                                      uint32_t start, uint32_t ratio,
                                      uint32_t packed_rows, uint32_t offset) {
    if ((ratio != 1u && ratio != 2u) || !source_rows || source_rows > INT32_MAX || !rows ||
        !packed_rows || packed_rows > INT32_MAX ||
        rows > UINT32_MAX - start || (start + rows) / ratio > source_rows ||
        offset > packed_rows || rows > packed_rows - offset ||
        !ds4_gpu_dsv41_tensor_ops_available()) return 0;
    const ds4_gpu_tensor *tensors[] = {q, weights, keys, scores, packed};
    const uint64_t bytes[] = {(uint64_t)rows * 32u * 128u * 4u, (uint64_t)rows * 32u * 4u,
        (uint64_t)source_rows * 128u * 4u, (uint64_t)rows * source_rows * 4u,
        ds4_gpu_dsv41_indexer_packed_bytes(source_rows, packed_rows)};
    for (uint32_t i = 0; i < 5; i++)
        if (!tensors[i] || !ds4_gpu_tensor_buffer(tensors[i]) || ds4_gpu_tensor_bytes(tensors[i]) < bytes[i])
            return 0;
    @autoreleasepool {
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline_or_die("kernel_dsv41_indexer_scores_packed");
        if (!pipeline) return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
        if (!enc) return 0;
        const uint32_t args[] = {source_rows, rows, start, ratio}, range[] = {packed_rows, offset};
        const uint64_t flags_bytes = ds4_gpu_dsv41_indexer_flags_bytes(source_rows, packed_rows);
        const uint64_t base = ds4_gpu_tensor_offset(packed);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:args length:sizeof(args) atIndex:0];
        [enc setBytes:range length:sizeof(range) atIndex:1];
        for (NSUInteger i = 0; i < 5; i++)
            [enc setBuffer:ds4_gpu_tensor_buffer(tensors[i]) offset:ds4_gpu_tensor_offset(tensors[i]) atIndex:i + 2];
        [enc setBuffer:ds4_gpu_tensor_buffer(packed) offset:base + flags_bytes atIndex:7];
        [enc setBuffer:ds4_gpu_tensor_buffer(packed) offset:base + flags_bytes + (uint64_t)packed_rows * 8192u atIndex:8];
        [enc setThreadgroupMemoryLength:32u * 64u * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)source_rows + 63u) / 64u, rows, 1)
             threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "V4.1 packed index scores");
    }
}

int ds4_gpu_dsv41_indexer_scores_batch(ds4_gpu_tensor *scores,
                                     const ds4_gpu_tensor *q,
                                     const ds4_gpu_tensor *weights,
                                     const ds4_gpu_tensor *keys,
                                     uint32_t source_rows, uint32_t rows,
                                     uint32_t start, uint32_t ratio) {
    if (ratio != 1u && ratio != 2u) return 0;
    return ds4_gpu_glm_indexer_scores_batch_grouped_tensor(scores, q, weights,
        keys, source_rows, rows, start, ratio, 32, 128, 1.0f / 64.0f, false, true);
}

int ds4_gpu_glm_qk_lowrank_typed_tensor(
        ds4_gpu_tensor       *qk_low,
        const ds4_gpu_tensor *q,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint32_t              weight_type,
        uint32_t              n_head,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              qk_dim) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!qk_low || !q || !model_map ||
        n_head == 0 || kv_lora_dim == 0 ||
        qk_nope == 0 || qk_nope > qk_dim) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(qk_low);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        uint64_t row_bytes = 0;
        if (!ds4_gpu_quant_row_bytes(weight_type, qk_nope, &row_bytes)) {
            fprintf(stderr, "ds4: Metal GLM qk lowrank received unsupported weight type\n");
            return 0;
        }
        const uint64_t weight_rows = (uint64_t)n_head * kv_lora_dim;
        const uint64_t weight_bytes = weight_rows * row_bytes;
        const uint64_t out_bytes = (uint64_t)n_head * kv_lora_dim * sizeof(float);
        const uint64_t q_bytes = (uint64_t)n_head * qk_dim * sizeof(float);
        if (!outbuf || !qbuf ||
            ds4_gpu_tensor_bytes(qk_low) < out_bytes ||
            ds4_gpu_tensor_bytes(q) < q_bytes) {
            fprintf(stderr, "ds4: Metal GLM qk lowrank received undersized buffers\n");
            return 0;
        }
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal GLM qk lowrank range is outside the mapped model\n");
            return 0;
        }

        uint64_t weight_inner = 0;
        id<MTLBuffer> weightbuf =
            ds4_gpu_wrap_model_range(model_map,
                                      model_size,
                                      weight_offset,
                                      weight_bytes,
                                      &weight_inner);
        if (!weightbuf) return 0;

        const int use_glm52 =
            n_head == 64u &&
            kv_lora_dim == 512u &&
            qk_nope == 192u &&
            qk_dim == 256u &&
            row_bytes == 204u &&
            weight_type == DS4_METAL_TENSOR_Q8_0;
        /* Coalesced simdgroup variant: lanes split the 192-dot so weight
         * reads coalesce, and 2048 threadgroups replace 64. The thread-
         * per-row kernels measured ~7.5x off the weight-bandwidth floor
         * (7.2ms of the decode token by skip-ablation). Covers the GLM 5.2
         * shape for both Q8_0 k_b and the DenseQ4 GGUF's Q4_0 k_b (the Q8
         * fast path above never engaged there). */
        const int use_glm52_sg =
            (n_head == 32u || n_head == 64u) &&
            kv_lora_dim == 512u &&
            qk_nope == 192u &&
            qk_dim == 256u &&
            ((weight_type == DS4_METAL_TENSOR_Q8_0 && row_bytes == 204u) ||
             (weight_type == DS4_METAL_TENSOR_Q4_0 && row_bytes == 108u)) &&
            getenv("DS4_METAL_DISABLE_GLM_QKLOW_SG") == NULL &&
            ds4_gpu_hot_pipeline(g_glm_qk_lowrank_glm52_sg_pipeline,
                                 "kernel_glm_qk_lowrank_q8_0_glm52_sg") != nil;
        if (getenv("DS4_METAL_GLM_QKLOW_DEBUG")) {
            static int printed = 0;
            if (!printed) {
                printed = 1;
                fprintf(stderr, "ds4: qk_lowrank decode path: use_glm52=%d sg=%d n_head=%u kv=%u nope=%u dim=%u rb=%llu type=%u\n",
                        use_glm52, use_glm52_sg, n_head, kv_lora_dim, qk_nope, qk_dim,
                        (unsigned long long)row_bytes, weight_type);
            }
        }
        id<MTLComputePipelineState> pipeline =
            use_glm52_sg ?
                ds4_gpu_hot_pipeline(g_glm_qk_lowrank_glm52_sg_pipeline,
                                     "kernel_glm_qk_lowrank_q8_0_glm52_sg") :
            use_glm52 ?
                ds4_gpu_hot_pipeline(g_glm_qk_lowrank_glm52_pipeline,
                                     "kernel_glm_qk_lowrank_q8_0_glm52") :
                ds4_gpu_hot_pipeline(g_glm_qk_lowrank_pipeline,
                                     "kernel_glm_qk_lowrank_q8_0");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_qk_lowrank_args args = {
            .n_head = n_head,
            .kv_lora_dim = kv_lora_dim,
            .qk_nope = qk_nope,
            .qk_dim = qk_dim,
            .row_bytes = (uint32_t)row_bytes,
            .weight_type = weight_type,
            .pad1 = 0,
            .pad2 = 0,
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:weightbuf offset:(NSUInteger)weight_inner atIndex:1];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(qk_low) atIndex:3];
        if (use_glm52_sg) {
            /* 8 simdgroups x 2 rows per threadgroup: (64, 512/16) grid. */
            [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_head,
                                                  (NSUInteger)(kv_lora_dim / 16u),
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, 8, 1)];
        } else {
            if (use_glm52) {
                [enc setThreadgroupMemoryLength:192u * sizeof(float) atIndex:0];
            }
            [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_head, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        }
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM qk lowrank")) return 0;
    }

    return 1;
}


int ds4_gpu_glm_qk_lowrank_typed_batch_tensor(
        ds4_gpu_tensor       *qk_low,
        const ds4_gpu_tensor *q,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint32_t              weight_type,
        uint32_t              n_tokens,
        uint32_t              n_head,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              qk_dim) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!qk_low || !q || !model_map ||
        n_tokens == 0 || n_head == 0 || kv_lora_dim == 0 ||
        qk_nope == 0 || qk_nope > qk_dim) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(qk_low);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        uint64_t row_bytes = 0;
        if (!ds4_gpu_quant_row_bytes(weight_type, qk_nope, &row_bytes)) {
            fprintf(stderr, "ds4: Metal GLM batch qk lowrank received unsupported weight type\n");
            return 0;
        }
        const uint64_t weight_rows = (uint64_t)n_head * kv_lora_dim;
        const uint64_t weight_bytes = weight_rows * row_bytes;
        const uint64_t out_bytes =
            (uint64_t)n_tokens * n_head * kv_lora_dim * sizeof(float);
        const uint64_t q_bytes =
            (uint64_t)n_tokens * n_head * qk_dim * sizeof(float);
        if (!outbuf || !qbuf ||
            ds4_gpu_tensor_bytes(qk_low) < out_bytes ||
            ds4_gpu_tensor_bytes(q) < q_bytes) {
            fprintf(stderr, "ds4: Metal GLM batch qk lowrank received undersized buffers\n");
            return 0;
        }
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal GLM batch qk lowrank range is outside the mapped model\n");
            return 0;
        }

        uint64_t weight_inner = 0;
        id<MTLBuffer> weightbuf =
            ds4_gpu_wrap_model_range(model_map,
                                      model_size,
                                      weight_offset,
                                      weight_bytes,
                                      &weight_inner);
        if (!weightbuf) return 0;

        const int use_glm52_t4 =
            n_tokens >= 4u &&
            n_head == 64u &&
            kv_lora_dim == 512u &&
            qk_nope == 192u &&
            qk_dim == 256u &&
            row_bytes == 204u &&
            weight_type == DS4_METAL_TENSOR_Q8_0;
        id<MTLComputePipelineState> pipeline =
            use_glm52_t4 ?
                ds4_gpu_hot_pipeline(g_glm_qk_lowrank_batch_glm52_t4_pipeline,
                                     "kernel_glm_qk_lowrank_q8_0_batch_glm52_t4") :
                ds4_gpu_hot_pipeline(g_glm_qk_lowrank_batch_pipeline,
                                     "kernel_glm_qk_lowrank_q8_0_batch");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        uint32_t head_base = 0;
        uint32_t head_count = n_head;
        ds4_gpu_tp_attn_head_range(n_head, 8u, &head_base, &head_count);
        ds4_gpu_glm_qk_lowrank_batch_args args = {
            .n_tokens = n_tokens,
            .n_head = n_head,
            .kv_lora_dim = kv_lora_dim,
            .qk_nope = qk_nope,
            .qk_dim = qk_dim,
            .row_bytes = (uint32_t)row_bytes,
            .weight_type = weight_type,
            .head_base = head_base,
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:weightbuf offset:(NSUInteger)weight_inner atIndex:1];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(qk_low) atIndex:3];
        if (use_glm52_t4) {
            [enc setThreadgroupMemoryLength:4u * 192u * sizeof(float) atIndex:0];
            [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)head_count,
                                                  ((NSUInteger)n_tokens + 3u) / 4u,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        } else {
            [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)head_count,
                                                  (NSUInteger)n_tokens,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        }
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM batch qk lowrank")) return 0;
    }

    return 1;
}


int ds4_gpu_glm_value_project_typed_batch_heads_tensor(
