            .qk_nope = 0,
            .qk_dim = value_dim,
            .row_bytes = (uint32_t)row_bytes,
            .weight_type = weight_type,
            .head_base = head_base,
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
