/* llms RESCUE v3: the post-cap step as a PURE function -- rp / rw (nrr rows x n_expert) are the ship's final picks and weights, rewritten in place; six / prr / ws0
   the rows' router six, full probability rows and original weight sums; rbits the layer's residency bits. Returns the number of rows changed. */
static uint32_t resc_post_cap(uint32_t nrr, uint32_t n_expert, int32_t *rp, float *rw, uint32_t cap_r, int fill, const uint64_t *rbits, uint32_t me,
                              int32_t (*six)[8], float (*prr)[512], const float *ws0, int w0, int wn, uint32_t *n_rescued, uint32_t *n_filled, uint32_t *n_lost) {
    int32_t ids[64]; uint32_t nb = 0; int changed[8] = {0};
    *n_rescued = 0; *n_filled = 0; *n_lost = 0;
    for (uint32_t i = 0; i < nrr * n_expert; i++) { if (rp[i] < 0) continue; uint32_t k = 0; for (; k < nb; k++) if (ids[k] == rp[i]) break; if (k == nb && nb < 64u) ids[nb++] = rp[i]; }
    const uint32_t nb0 = nb;   /* the ship's final set: pinned */
    if (cap_r >= 2u) {   /* the rescue: resident originals not in the set, by pair-summed squared probability, up to cap_r distinct */
        int32_t cand[64]; float cs[64]; uint32_t nc = 0;
        for (uint32_t r = 0; r < nrr; r++) for (uint32_t j = 0; j < n_expert; j++) {
            const int e = six[r][j]; if (e < 0 || (uint32_t)e >= me || !((rbits[(uint32_t)e >> 6] >> ((uint32_t)e & 63u)) & 1ull)) continue;
            int in_set = 0; for (uint32_t k = 0; k < nb; k++) if (ids[k] == e) { in_set = 1; break; } if (in_set) continue;
            uint32_t k = 0; for (; k < nc; k++) if (cand[k] == e) break; if (k == nc) { if (nc >= 64u) continue; cand[nc] = e; cs[nc] = 0.0f; nc++; }
            cs[k] += prr[r][e] * prr[r][e];
        }
        while (nb < cap_r && nc > 0u) {
            uint32_t b = 0; for (uint32_t k = 1; k < nc; k++) if (cs[k] > cs[b]) b = k;
            const int e = cand[b]; cand[b] = cand[nc - 1u]; cs[b] = cs[nc - 1u]; nc--;
            int placed = 0;
            for (uint32_t r = 0; r < nrr; r++) {
                int in6 = 0; for (uint32_t j = 0; j < n_expert; j++) if (six[r][j] == e) { in6 = 1; break; } if (!in6) continue;
                int hole = -1; for (uint32_t i = 0; i < n_expert; i++) if (rp[r * n_expert + i] < 0) { hole = (int)i; break; } if (hole < 0) continue;
                rp[r * n_expert + (uint32_t)hole] = e; changed[r] = 1; placed = 1; (*n_rescued)++;
            }
            if (placed && nb < 64u) ids[nb++] = e;
        }
    }
    if (fill) {   /* the fill: every expert of the final set into every row whose six hold it and that lacks it */
        for (uint32_t r = 0; r < nrr; r++) for (uint32_t k = 0; k < nb; k++) {
            const int e = ids[k];
            int in6 = 0; for (uint32_t j = 0; j < n_expert; j++) if (six[r][j] == e) { in6 = 1; break; } if (!in6) continue;
            int have = 0, hole = -1; for (uint32_t i = 0; i < n_expert; i++) { if (rp[r * n_expert + i] == e) have = 1; if (rp[r * n_expert + i] < 0 && hole < 0) hole = (int)i; }
            if (have || hole < 0) continue;
            rp[r * n_expert + (uint32_t)hole] = e; changed[r] = 1; (*n_filled)++;
        }
    }
    uint32_t rows_changed = 0;
    for (uint32_t r = 0; r < nrr; r++) {   /* the ship's weight rule on the changed rows: W0 (the six's mass) x WNORM (sites 1 and 2 combined) */
        if (!changed[r]) continue; rows_changed++;
        float p6 = 0.0f, s6 = 0.0f, pk = 0.0f, sk = 0.0f;
        for (uint32_t j = 0; j < n_expert; j++) { const int e = six[r][j]; if (e >= 0) { p6 += prr[r][e]; s6 += prr[r][e] * prr[r][e]; } }
        for (uint32_t i = 0; i < n_expert; i++) { const int e = rp[r * n_expert + i]; if (e >= 0) { pk += prr[r][e]; sk += prr[r][e] * prr[r][e]; } }
        const float ps = w0 ? p6 : pk; float cf = 1.0f;
        if (wn && w0 && sk > 0.0f && s6 > sk && isfinite(s6)) cf = sqrtf(s6 / sk);
        for (uint32_t i = 0; i < n_expert; i++) { const int e = rp[r * n_expert + i]; rw[r * n_expert + i] = (e >= 0 && ps > 0.0f) ? prr[r][e] / ps * ws0[r] * cf : 0.0f; }
    }
    for (uint32_t k = 0; k < nb0; k++) { int kept = 0; for (uint32_t i = 0; i < nrr * n_expert; i++) if (rp[i] == ids[k]) { kept = 1; break; } if (!kept) (*n_lost)++; }
    return rows_changed;
}
static int resc_rows_are(const int32_t *rp, uint32_t n_expert, const int32_t *want0, const int32_t *want1) {   /* the two rows' kept sets equal the wanted sets (order-free) */
    const int32_t *want[2] = {want0, want1};
    for (uint32_t r = 0; r < 2u; r++) {
        uint32_t nw = 0, nh = 0; while (nw < 8u && want[r][nw] >= 0) nw++;
        for (uint32_t i = 0; i < n_expert; i++) if (rp[r * n_expert + i] >= 0) { nh++; int ok = 0; for (uint32_t j = 0; j < nw; j++) if (want[r][j] == rp[r * n_expert + i]) ok = 1; if (!ok) return 0; }
        if (nh != nw) return 0;
    }
    return 1;
}
static void resc_first_use(void) {   /* llms RESCUE v3: the self-test on the canaries, and the exit line */
    static int done; if (done) return; done = 1;
    enum { XA = 1, XB, XC, XD, XE, XF, XG, XH, XI };
    static int32_t six[8][8]; static float router_probabilities_by_row[8][512]; const float ws[8] = {1.0f, 1.0f};
    uint64_t rb[8] = {0}; int32_t rp[12]; float rw[12]; uint32_t nr_, nf_, nl_; int pass = 0, total = 0;
    const int32_t s1a[6] = {XA, XB, XC, XE, XF, XG}, s1b[6] = {XC, XD, XA, XE, XF, XG}; const float p1[6] = {0.40f, 0.30f, 0.10f, 0.08f, 0.07f, 0.05f};
    for (int j = 0; j < 6; j++) { six[0][j] = s1a[j]; six[1][j] = s1b[j]; router_probabilities_by_row[0][s1a[j]] = p1[j]; router_probabilities_by_row[1][s1b[j]] = p1[j]; }
    rb[0] = 1ull << XE;   /**/
    const int32_t base1[12] = {XA, XB, -1, -1, -1, -1, XC, XD, -1, -1, -1, -1};
    { const int32_t w0_[] = {XA, XB, XE, -1}, w1_[] = {XC, XD, XE, -1}; memcpy(rp, base1, sizeof rp); memset(rw, 0, sizeof rw);
      resc_post_cap(2, 6, rp, rw, 5, 0, rb, 64, six, router_probabilities_by_row, ws, 1, 1, &nr_, &nf_, &nl_); total++; pass += resc_rows_are(rp, 6, w0_, w1_) && nl_ == 0;
      float wa = -1.0f; for (int i = 0; i < 6; i++) if (rp[i] == XA) wa = rw[i];   /* 0.40 / 1.00 x 1 x sqrt(0.2738 / 0.2564) */
      total++; pass += fabsf(wa - 0.41335f) < 1e-4f; }
    { const int32_t w0_[] = {XA, XB, XC, XE, -1}, w1_[] = {XC, XD, XA, XE, -1}; memcpy(rp, base1, sizeof rp);
      resc_post_cap(2, 6, rp, rw, 5, 1, rb, 64, six, router_probabilities_by_row, ws, 1, 1, &nr_, &nf_, &nl_); total++; pass += resc_rows_are(rp, 6, w0_, w1_) && nl_ == 0; }
    { const int32_t w0_[] = {XA, XB, XC, -1}, w1_[] = {XC, XD, XA, -1}; memcpy(rp, base1, sizeof rp);
      resc_post_cap(2, 6, rp, rw, 0, 1, rb, 64, six, router_probabilities_by_row, ws, 1, 1, &nr_, &nf_, &nl_); total++; pass += resc_rows_are(rp, 6, w0_, w1_) && nl_ == 0 && nr_ == 0 && nf_ == 2; }
    memset(six, 0, sizeof six); memset(router_probabilities_by_row, 0, sizeof router_probabilities_by_row);
    const int32_t s2a[6] = {XA, XB, XC, XG, XH, XI}, s2b[6] = {XD, XE, XF, XG, XH, XI}; const float p2[6] = {0.50f, 0.29f, 0.28f, 0.27f, 0.26f, 0.25f};
    for (int j = 0; j < 6; j++) { six[0][j] = s2a[j]; six[1][j] = s2b[j]; router_probabilities_by_row[0][s2a[j]] = p2[j]; router_probabilities_by_row[1][s2b[j]] = p2[j]; }
    rb[0] = 0x3FEull;   /**/
    const int32_t base2[12] = {XA, XB, -1, -1, -1, -1, XD, XE, -1, -1, -1, -1};
    { const int32_t w0_[] = {XA, XB, XG, -1}, w1_[] = {XD, XE, XG, -1}; memcpy(rp, base2, sizeof rp);
      resc_post_cap(2, 6, rp, rw, 5, 0, rb, 64, six, router_probabilities_by_row, ws, 1, 1, &nr_, &nf_, &nl_); total++; pass += resc_rows_are(rp, 6, w0_, w1_) && nl_ == 0; }
    { const int32_t w0_[] = {XA, XB, XG, XH, -1}, w1_[] = {XD, XE, XG, XH, -1}; memcpy(rp, base2, sizeof rp);
      resc_post_cap(2, 6, rp, rw, 6, 0, rb, 64, six, router_probabilities_by_row, ws, 1, 1, &nr_, &nf_, &nl_); total++; pass += resc_rows_are(rp, 6, w0_, w1_) && nl_ == 0; }
    { const int32_t w0_[] = {XA, XB, XG, XH, -1}, w1_[] = {XD, XE, XG, XH, -1}; memcpy(rp, base2, sizeof rp);
      resc_post_cap(2, 6, rp, rw, 6, 1, rb, 64, six, router_probabilities_by_row, ws, 1, 1, &nr_, &nf_, &nl_); total++; pass += resc_rows_are(rp, 6, w0_, w1_) && nl_ == 0 && nf_ == 0; }
    fprintf(stderr, "llms rescue self-test: %d of %d canaries pass%s\n", pass, total, pass == total ? "" : " -- THE POST-CAP STEP IS WRONG");
    atexit_b(^{ fprintf(stderr, "llms rescue v3: %llu calls, %llu stale (skipped), %llu rescued picks, %llu fill calls, %llu filled picks, %llu rows touched, %llu baseline IDs lost\n",
                        (unsigned long long)resc_v3_calls, (unsigned long long)resc_stale_calls, (unsigned long long)rescue_added, (unsigned long long)rfill_calls,
                        (unsigned long long)rfill_added, (unsigned long long)rescue_rows, (unsigned long long)resc_lost_ids); });
}

/* llms ROUTE_DAMP (apply_route_damp.py): LLMS_DS4_ROUTE_DAMP=<40 x 384 float32> subtracts table[layer][expert] x LLMS_DS4_ROUTE_DAMP_SCALE from the host re-pick's score of every decode row after LLMS_DS4_ROUTE_DAMP_AFTER decode rows (counted at layer 0); off unless the variable names a file -- FIDELITY DIAL */
