static void route_damp_init(void) {
    route_damp_on = 0; const char *p = getenv("LLMS_DS4_ROUTE_DAMP"); if (!p || !*p) return;
    FILE *f = fopen(p, "rb"); if (!f) { fprintf(stderr, "llms: ROUTE_DAMP: cannot open %s -- switch off\n", p); return; }
    const size_t n = 40u * 384u; route_damp_tab = (float *)calloc(n, sizeof(float));
    if (!route_damp_tab || fread(route_damp_tab, sizeof(float), n, f) != n) { fprintf(stderr, "llms: ROUTE_DAMP: %s is not 40 x 384 float32 -- switch off\n", p); fclose(f); free(route_damp_tab); route_damp_tab = NULL; return; }
    fclose(f);
    { const char *e = getenv("LLMS_DS4_ROUTE_DAMP_SCALE"); if (e && *e) route_damp_scale = (float)atof(e); }
    { const char *e = getenv("LLMS_DS4_ROUTE_DAMP_AFTER"); if (e && *e) route_damp_after = (uint64_t)strtoull(e, NULL, 10); }
    size_t nz = 0; for (size_t i = 0; i < n; i++) if (route_damp_tab[i] != 0.0f) nz++;
    route_damp_on = 1;
    fprintf(stderr, "llms: route damp %s (%zu of %zu entries set), scale %g, after %llu decode rows -- FIDELITY DIAL [LLMS_DS4_ROUTE_DAMP]\n", p, nz, n, (double)route_damp_scale, (unsigned long long)route_damp_after);
    atexit_b(^{ fprintf(stderr, "llms route damp: %llu decode rows seen, %llu rows damped, %llu of %llu final picks were table experts (%.3f a row)\n", (unsigned long long)route_damp_rows_seen, (unsigned long long)route_damp_rows_active, (unsigned long long)route_damp_picked, (unsigned long long)route_damp_picks, route_damp_rows_active ? (double)route_damp_picked / (double)route_damp_rows_active : 0.0); });
}
static int apply_decode_route_row(uint32_t layer, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_total_expert,
                         uint32_t n_expert, const ds4_gpu_tensor *probs, const float *bias, uint32_t row) {   /* llms ONE_RPOL: the re-pick of one row (llms SP_ED: row r) */
    float pr[512], sc[512], w[8]; int32_t sel[8], ns[8];
    if (route_damp_on < 0) route_damp_init();   /* llms ROUTE_DAMP */
    if (route_damp_on > 0 && layer == 0) route_damp_rows_seen++;
    const int damp_now = route_damp_on > 0 && layer < 40u && route_damp_rows_seen > route_damp_after;   /* llms ROUTE_DAMP */
    if (damp_now && layer == 0) route_damp_rows_active++;
    if (exact_step_now()) { exact_step_rows++; return 1; }   /* llms EXACT_STEP: the router's six and weights stay */
    const int cg_m_ = ({
        (int)((conf_gate_state > 0 && conf_gate_open == 0u) ? conf_gate_mode : 0);
    });   /* llms CONF_GATE: the families closed for this step (bit 0 truncation, bit 1 residency) */
    if (cg_m_ == 3) { conf_gate_closed_rows++; return 1; }   /* both closed: the router's exact picks stay, the CPU re-pick is skipped */
    const int cg_t_ = cg_m_ & 1, cg_r_ = (cg_m_ >> 1) & 1; if (cg_m_) conf_gate_closed_rows++;
    if (!ds4_gpu_tensor_read(probs, (uint64_t)row * n_total_expert * sizeof(float), pr, (uint64_t)n_total_expert * sizeof(float)) ||
        !ds4_gpu_tensor_read(selected, (uint64_t)row * n_expert * sizeof(int32_t), sel, (uint64_t)n_expert * sizeof(int32_t)) ||
        !ds4_gpu_tensor_read(weights, (uint64_t)row * n_expert * sizeof(float), w, (uint64_t)n_expert * sizeof(float))) return 0;
