        if (serve_fast) fprintf(stderr, "llms: serve fast (the re-pick's bonus term hoisted per row; the co-route's statistics-only selections skipped)\n"); }
    const float row_bonus_sf = serve_fast ? (((band_bonus_last_layer && layer >= band_bonus_first_layer && layer <= band_bonus_last_layer && !llms_alt_off("band")) ? band_bonus :
                                             ((late_bonus_from_layer && layer >= late_bonus_from_layer) ? late_bonus : decode_resident_bonus))) : 0.0f;   /* llms SERVE_FAST: the per-row term */
    for (uint32_t e = 0; e < n_total_expert; e++) {
        const int res = (int)((resident_bits[layer][e >> 6] >> (e & 63u)) & 1ull);
        if (serve_fast) sc[e] = pr[e] + bias[e] + (res && !cg_r_ ? cold_multiplier * row_bonus_sf : 0.0f);   /* llms SERVE_FAST: the same expression, the band / late test hoisted */
        else
        sc[e] = pr[e] + bias[e] + (res && !cg_r_ ? cold_multiplier * ((band_bonus_last_layer && layer >= band_bonus_first_layer && layer <= band_bonus_last_layer && !llms_alt_off("band")) ? band_bonus :   /* llms ONE_RPOL_BAND */
                                           ((late_bonus_from_layer && layer >= late_bonus_from_layer) ? late_bonus : decode_resident_bonus)) : 0.0f);   /* llms ONE_RPOL_LATE */
        if (damp_now && e < 384u) sc[e] -= route_damp_tab[(size_t)layer * 384u + e] * route_damp_scale;   /* llms ROUTE_DAMP */

        {   /* llms DR_DEEP (apply_drdeep.py): the deep rows' extra resident bonus */
            static float decode_route_deep_value = -1.0f; static uint64_t decode_route_deep_n;
            if (decode_route_deep_value < 0.0f) { const char *de = getenv("LLMS_DS4_DECODE_ROUTE_DEEP"); decode_route_deep_value = de && *de ? (float)atof(de) : 0.0f; if (!(decode_route_deep_value > 0.0f)) decode_route_deep_value = 0.0f;
                              if (decode_route_deep_value > 0.0f) { fprintf(stderr, "llms: decode route deep %.3f (rows 2.. of a k-row verify: resident experts' extra bonus) -- FIDELITY DIAL\n", (double)decode_route_deep_value);
                                                atexit_b(^{ fprintf(stderr, "llms decode route deep: %llu deep-row resident bonuses\n", (unsigned long long)decode_route_deep_n); }); } }
            if (res && !cg_r_ && decode_route_deep_value > 0.0f && row >= 2u && !llms_alt_off("drd")) { sc[e] += decode_route_deep_value; decode_route_deep_n++; }
        }
