}
uint32_t ds4_gpu_llms_ed_commit_every(void) { return event_driven_commit_every; }   /* llms EDR_PHASE */
int ds4_gpu_llms_ed_rows_end(uint32_t layer_index, int ok, int due_override) {   /* the one-token wrapper's commit cadence */
