        const uint32_t slab_budget = ds4_gpu_stream_expert_cache_configured_budget();   /* llms ED v3: event-driven only once every slab exists */
        const int event_driven_now = event_driven_on() && layer_index < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER && slab_budget != 0 &&
                                g_stream_expert_cache_slab_total_slots >= slab_budget && g_stream_expert_cache_slab_count != 0;
        if (decode_route_on() && !event_driven_now) {   /* llms ONE_RPOL (encode time; under ED the listener applies it) */
            decode_route_calls++;
