                if (batch_was_open && ds4_gpu_end_commands() == 0) return 0;
                if (!apply_decode_route(layer_index, selected, weights, n_total_expert, n_expert, router_probs_now, route_bias_host, 1u)) return 0;
                if (batch_was_open && ds4_gpu_begin_commands() == 0) return 0;   /* llms ONE_RPOL v2: reopen the batch the routed path expects */
            }
