            event_driven_call_open = 1; routed_call_probs = router_probs_now; routed_call_bias = route_bias_host; routed_call_weights = weights;
        }
        gateup_side_refused = 0;   /* llms BS6C_FALLBACK */
        int batch_path_result = ds4_gpu_routed_moe_batch_tensor(out, gate, up, mid, experts, model_map, model_size, gate_offset, up_offset, down_offset,
                                                      gate_type, down_type, gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes,
                                                      expert_in_dim, expert_mid_dim, out_dim, selected, weights, n_total_expert, n_expert, clamp, x,
                                                      layer_index, 1u, &event_driven_flag_set, force_resident);
