            int due = !llms_alt_off("edp") ? ((uint32_t)layer_index % ek) == 0u : (event_driven_calls_closed % ek) == 0;
            if (batch_path_result && due && ds4_gpu_flush_commands() == 0) batch_path_result = 0; if (event_driven_error) batch_path_result = 0; }
        if (batch_path_result && add_in) { batch_path_result = ds4_gpu_add_tensor(out, out, add_in, out_dim); }
