}

/* llms RUQ2 (apply_ruq2.py): one layer's routed experts in the rotated-uniform Q2 codec, decode rows 1..3 */
static int ruq2_state = -1; static uint32_t ruq2_layer; static id<MTLBuffer> ruq2_pack, ruq2_meta, ruq2_jobs, ruq2_xp, ruq2_raw, ruq2_mid, ruq2_down, ruq2_outp;
