static void ruq2_dispatch(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> ps, id<MTLBuffer> __unsafe_unretained const *b, const NSUInteger *off, int n, const ruq2_params_t *p, MTLSize grid) {
    [enc setComputePipelineState:ps];
