    [enc setBytes:p length:sizeof(*p) atIndex:(NSUInteger)n];
    [enc dispatchThreadgroups:grid threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
}
static int ruq2_routed(ds4_gpu_tensor *out, const ds4_gpu_tensor *x, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_tokens) {
    const uint32_t np = n_tokens * 6u;
