        id<MTLBuffer> xb = ds4_gpu_tensor_buffer(x), sb = ds4_gpu_tensor_buffer(selected), wb = ds4_gpu_tensor_buffer(weights), ob = ds4_gpu_tensor_buffer(out);
        const NSUInteger xo = ds4_gpu_tensor_offset(x), so = ds4_gpu_tensor_offset(selected), wo = ds4_gpu_tensor_offset(weights), oo = ds4_gpu_tensor_offset(out);
        [enc setComputePipelineState:ruq2_fill]; [enc setBuffer:sb offset:so atIndex:0]; [enc setBuffer:ruq2_jobs offset:0 atIndex:1]; [enc setBytes:&np length:4 atIndex:2];
        [enc dispatchThreads:MTLSizeMake(np, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
