        { id<MTLBuffer> __unsafe_unretained b[4] = { ruq2_meta, ruq2_jobs, ruq2_xp, ruq2_raw }; NSUInteger o[4] = { 0, 0, 0, 0 }; ruq2_dispatch(enc, ruq2_mv1, b, o, 4, &p, MTLSizeMake(18, np, 2)); }
        { id<MTLBuffer> __unsafe_unretained b[4] = { ruq2_raw, ruq2_meta, sb, ruq2_mid }; NSUInteger o[4] = { 0, 0, so, 0 }; ruq2_dispatch(enc, ruq2_act, b, o, 4, &p, MTLSizeMake(18, np, 1)); }
        p.mode = 1u;
        { id<MTLBuffer> __unsafe_unretained b[4] = { ruq2_meta, ruq2_jobs, ruq2_mid, ruq2_down }; NSUInteger o[4] = { 0, 0, 0, 0 }; ruq2_dispatch(enc, ruq2_mv1, b, o, 4, &p, MTLSizeMake(40, np, 1)); }
        { id<MTLBuffer> __unsafe_unretained b[5] = { ruq2_down, ruq2_meta, sb, wb, ruq2_outp }; NSUInteger o[5] = { 0, 0, so, wo, 0 }; ruq2_dispatch(enc, ruq2_fin, b, o, 5, &p, MTLSizeMake(40, np, 1)); }
