    uint64_t side_gate_offset = gate_offset, side_up_offset = up_offset, side_gate_expert_bytes = gate_expert_bytes, side_gate_row_bytes = gate_row_bytes;   /* llms BS6C: decode-sized calls read the side file */
    uint64_t side_down_offset = down_offset, side_down_expert_bytes = down_expert_bytes;   /* llms G32D: the down from its side file in the same calls */
    {   /* llms CODEC CENSUS (apply_codec_census.py): the routed codec by phase, under GUARDS */
        static int codec_census_state = -1; static uint64_t codec_census_calls[2][2], codec_census_rows[2][2];
        if (codec_census_state < 0) { const char *ge = getenv("LLMS_DS4_GUARDS"); codec_census_state = ge && *ge && *ge != '0';
            if (codec_census_state) atexit_b(^{ fprintf(stderr, "llms codec census: prefill side %llu calls (%llu rows) / gguf %llu (%llu rows); decode side %llu (%llu rows) / gguf %llu (%llu rows)\n",
                (unsigned long long)codec_census_calls[1][0], (unsigned long long)codec_census_rows[1][0], (unsigned long long)codec_census_calls[1][1], (unsigned long long)codec_census_rows[1][1],
                (unsigned long long)codec_census_calls[0][0], (unsigned long long)codec_census_rows[0][0], (unsigned long long)codec_census_calls[0][1], (unsigned long long)codec_census_rows[0][1]); }); }
        if (codec_census_state && layer_index < 40u) {
            const uint32_t ph = __atomic_load_n(&timeline_phase, __ATOMIC_RELAXED); const int pf = ph == 2u || ph == 3u;
            const int side = gateup_side_on() && gate_expert_bytes == SIDE_IQ2_GATE_EXPERT_BYTES && n_tokens <= row_paths_cap() && !force_resident;
            codec_census_calls[pf][!side]++; codec_census_rows[pf][!side] += n_tokens;
            static int warning_printed = 0;
            if (!side && gateup_side_on() && gate_expert_bytes == SIDE_IQ2_GATE_EXPERT_BYTES && !warning_printed) { warning_printed = 1;
                fprintf(stderr, "llms CODEC CENSUS: a routed call took the GGUF codec while the side file is on -- n_tokens %u (rows_max %u), force_resident %d, layer %u, %s "
                        "\n", (unsigned)n_tokens, (unsigned)row_paths_cap(), (int)force_resident, (unsigned)layer_index, pf ? "prefill" : "decode"); }
        }
    }
    if (gateup_side_on() && gate_expert_bytes == SIDE_IQ2_GATE_EXPERT_BYTES && n_tokens <= row_paths_cap() && layer_index < 40u && !force_resident) {   /* llms ROWS128; llms BS6C_RESIDENT */
        side_gate_offset = SIDE_ADDRESS_BASE + gateup_side_data_offset + (uint64_t)layer_index * gateup_side_layer_bytes; side_up_offset = side_gate_offset + 384ull * gateup_side_matrix_bytes;
        side_gate_expert_bytes = gateup_side_matrix_bytes; side_gate_row_bytes = 1520u; side_file_call_active = 1; gateup_side_translated_calls++;
        if (down_side_on() && down_expert_bytes == SIDE_DOWN_EXPERT_BYTES) { side_down_offset = G32D_ADDRESS_BASE + down_side_data_offset + (uint64_t)layer_index * down_side_layer_bytes; side_down_expert_bytes = down_side_matrix_bytes; }   /* llms G32D */
        down_side_layer = layer_index;   /* llms G32D probe */
        gateup_mix_layer = layer_index;   /* llms BSMX: the layer whose masks the dispatch binds */
    }
    const int r = routed_moe_batch_inner(out, gate, up, mid, experts, model_map, model_size, side_gate_offset, side_up_offset, side_down_offset, gate_type, down_type, side_gate_expert_bytes, side_gate_row_bytes, side_down_expert_bytes, down_row_bytes, expert_in_dim, expert_mid_dim, out_dim, selected, weights, n_total_expert, n_expert, clamp, x, layer_index, n_tokens, mid_is_f16, force_resident);
    overlay_hook_depth--;
    side_file_call_active = 0;   /* llms BS6C */
    return r;
}

static int routed_moe_one_inner(
