                                                            gate_group6_bufs,
                                                            gate_group6_offsets,
                                                            up_group6_bufs,
                                                            up_group6_offsets,
                                                            xbuf,
                                                            ds4_gpu_tensor_offset(x),
                                                            gatebuf,
                                                            ds4_gpu_tensor_offset(gate),
                                                            upbuf,
                                                            ds4_gpu_tensor_offset(up),
                                                            midbuf,
                                                            ds4_gpu_tensor_offset(mid),
                                                            selectedbuf,
