                                                                               stream_slot_entries,
                                                                               stream_gate_addr_buf,
                                                                               stream_up_addr_buf,
                                                                               xbuf,
                                                                               ds4_gpu_tensor_offset(x),
                                                                               gatebuf,
                                                                               ds4_gpu_tensor_offset(gate),
                                                                               upbuf,
                                                                               ds4_gpu_tensor_offset(up),
                                                                               midbuf,
                                                                               ds4_gpu_tensor_offset(mid),
                                                                               selected_exec_buf,
                                                                               selected_exec_off,
                                                                               weightsbuf,
                                                                               ds4_gpu_tensor_offset(weights),
                                                                               gate_smem,
                                                                               2,
