                            ok = ds4_gpu_encode_mul_mv_addr_q2_sum6_masked(cb,
                                                                           g_moe_mul_mv_addr_q2_k_sum6_masked_pipeline,
                                                                           &down_args,
                                                                           &all_down_args,
                                                                           stream_slot_entries,
                                                                           stream_down_addr_buf,
                                                                           midbuf,
                                                                           ds4_gpu_tensor_offset(mid),
                                                                           outbuf,
                                                                           ds4_gpu_tensor_offset(out),
                                                                           selected_exec_buf,
                                                                           selected_exec_off,
                                                                           down_smem,
                                                                           2);
                        }
                        stream_expert_split_completed = ok;
                        if (stream_split_timing) {
                            ds4_gpu_stream_expert_timing_note_split(
                                    stream_expert_resident_mask,
                                    stream_expert_missing_mask,
                                    stream_split_resident_ms,
                                    stream_split_missing_ms);
                            ds4_gpu_stream_expert_timing_note_split_missing_detail(
                                    stream_split_missing_load_ms,
                                    stream_split_missing_slot_ms,
                                    stream_split_missing_prune_ms,
                                    stream_split_missing_addr_ms,
                                    stream_split_missing_wait_ms);
                        }
                        if (stream_split_profile) {
                            fprintf(stderr,
                                    "ds4: Metal streaming expert split layer=%u "
                                    "resident=0x%02x missing=0x%02x resident_submit=%.3f ms "
                                    "missing_bind=%.3f ms\n",
                                    layer_index,
                                    stream_expert_resident_mask,
                                    stream_expert_missing_mask,
                                    stream_split_resident_ms,
                                    stream_split_missing_ms);
                        }
                    } else {
                        ds4_gpu_stream_expert_split_args split_args = {
                            .active_mask = 0x3fu,
                            .accumulate = 0u,
                        };
                        ok = ds4_gpu_encode_routed_gateup_swiglu_masked(cb,
                                                                               g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_masked_pipeline,
                                                                               &gate_args,
                                                                               &act_args,
                                                                               &split_args,
                                                                               stream_slot_entries,
                                                                               stream_gate_addr_buf,
                                                                               stream_up_addr_buf,
                                                                               xbuf,
                                                                               ds4_gpu_tensor_offset(x),
                                                                               gatebuf,
                                                                               ds4_gpu_tensor_offset(gate),
                                                                               upbuf,
                                                                               ds4_gpu_tensor_offset(up),
                                                                               midbuf,
                                                                               ds4_gpu_tensor_offset(mid),
                                                                               selected_exec_buf,
                                                                               selected_exec_off,
                                                                               weightsbuf,
                                                                               ds4_gpu_tensor_offset(weights),
                                                                               gate_smem,
                                                                               2,
                                                                               false);
                    }
                } else {
                    ok = ds4_gpu_encode_routed_gateup_swiglu(cb,
                                                                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_pipeline,
                                                                    &gate_args,
                                                                    &act_args,
                                                                    stream_slot_entries,
                                                                    n_expert,
                                                                    stream_gate_addr_buf,
                                                                    stream_up_addr_buf,
                                                                    xbuf,
                                                                    ds4_gpu_tensor_offset(x),
                                                                    gatebuf,
                                                                    ds4_gpu_tensor_offset(gate),
                                                                    upbuf,
                                                                    ds4_gpu_tensor_offset(up),
                                                                    midbuf,
                                                                    ds4_gpu_tensor_offset(mid),
                                                                    selected_exec_buf,
                                                                    selected_exec_off,
                                                                    weightsbuf,
                                                                    ds4_gpu_tensor_offset(weights),
                                                                    gate_smem,
                                                                    2,
                                                                    false,
                                                                    nil,
                                                                    nil);
                }
            } else {
                ok = (!use_stream_expert_cache ||
                      ds4_gpu_stream_expert_cache_mark_entries_inflight(
                              stream_slot_entries,
                              n_expert,
                              0)) &&
                     ds4_gpu_encode_mul_mv_slots6_pair_swiglu(cb,
                                                              slots_pair_swiglu_pipeline,
                                                              &gate_args,
                                                              &act_args,
                                                              gate_slot_bufs,
                                                              gate_slot_offsets,
                                                              up_slot_bufs,
                                                              up_slot_offsets,
                                                              xbuf,
                                                              ds4_gpu_tensor_offset(x),
                                                              gatebuf,
                                                              ds4_gpu_tensor_offset(gate),
                                                              upbuf,
                                                              ds4_gpu_tensor_offset(up),
                                                              midbuf,
                                                              ds4_gpu_tensor_offset(mid),
                                                              weightsbuf,
                                                              ds4_gpu_tensor_offset(weights),
                                                              gate_smem,
                                                              2,
                                                              false);
            }
        } else if (fuse_pair_swiglu) {
            ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                .width = expert_mid_dim,
                .rows = pair_rows,
                .gate_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .up_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .mid_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .weight_stride = sizeof(float),
                .write_clamped = 0,
                .clamp_value = clamp,
            };
            ok = ds4_gpu_encode_mul_mv_id_pair_swiglu(cb,
                                                        pair_swiglu_pipeline,
                                                        &gate_args,
                                                        &act_args,
                                                        gate_buf,
                                                        (NSUInteger)gate_inner,
                                                        up_buf,
                                                        (NSUInteger)up_inner,
                                                        xbuf,
                                                        ds4_gpu_tensor_offset(x),
                                                        gatebuf,
                                                        ds4_gpu_tensor_offset(gate),
                                                        upbuf,
                                                        ds4_gpu_tensor_offset(up),
                                                        midbuf,
                                                        ds4_gpu_tensor_offset(mid),
                                                        selectedbuf,
                                                        ds4_gpu_tensor_offset(selected),
                                                        weightsbuf,
                                                        ds4_gpu_tensor_offset(weights),
                                                        gate_smem,
                                                        pair_swiglu_nsg,
                                                        false);
        } else if (!g_quality_mode &&
                   gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
                   g_moe_mul_mv_id_iq2_xxs_pair_pipeline) {
            ok = ds4_gpu_encode_mul_mv_id_pair(cb,
                                                 g_moe_mul_mv_id_iq2_xxs_pair_pipeline,
                                                 &gate_args,
                                                 gate_buf,
                                                 (NSUInteger)gate_inner,
                                                 up_buf,
                                                 (NSUInteger)up_inner,
                                                 xbuf,
                                                 ds4_gpu_tensor_offset(x),
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 gate_smem,
                                                 2,
                                                 false);
        } else if (!g_quality_mode &&
                   gate_type == DS4_METAL_TENSOR_Q4_K &&
                   g_moe_mul_mv_id_q4_k_pair_pipeline) {
            ok = ds4_gpu_encode_mul_mv_id_pair(cb,
                                                 g_moe_mul_mv_id_q4_k_pair_pipeline,
                                                 &gate_args,
                                                 gate_buf,
                                                 (NSUInteger)gate_inner,
                                                 up_buf,
                                                 (NSUInteger)up_inner,
                                                 xbuf,
                                                 ds4_gpu_tensor_offset(x),
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 gate_smem,
                                                 2,
                                                 false);
        } else {
            ok = ds4_gpu_encode_mul_mv_id(cb,
                                            gate_mv_pipeline,
                                            &gate_args,
                                            gate_buf,
                                            (NSUInteger)gate_inner,
                                            xbuf,
                                            ds4_gpu_tensor_offset(x),
                                            gatebuf,
                                            ds4_gpu_tensor_offset(gate),
                                            selectedbuf,
                                            ds4_gpu_tensor_offset(selected),
                                            gate_smem,
                                            gate_nsg,
                                            gate_rows_per_group_is_nr0) &&
                 ds4_gpu_encode_mul_mv_id(cb,
                                            gate_mv_pipeline,
                                            &gate_args,
                                            up_buf,
                                            (NSUInteger)up_inner,
                                            xbuf,
                                            ds4_gpu_tensor_offset(x),
                                            upbuf,
                                            ds4_gpu_tensor_offset(up),
                                            selectedbuf,
                                            ds4_gpu_tensor_offset(selected),
                                            gate_smem,
                                            gate_nsg,
                                            gate_rows_per_group_is_nr0);
        }
        DS4_METAL_PROFILE_MOE_ONE_STAGE("gate_up");
        if (ok && (!fuse_pair_swiglu || use_q4_group24_experts)) {
            ok = ds4_gpu_encode_moe_swiglu_weight(cb,
                                                    gatebuf,
                                                    ds4_gpu_tensor_offset(gate),
                                                    upbuf,
                                                    ds4_gpu_tensor_offset(up),
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    weightsbuf,
                                                    ds4_gpu_tensor_offset(weights),
                                                    expert_mid_dim,
                                                    pair_rows,
                                                    clamp,
                                                    false);
        }
        DS4_METAL_PROFILE_MOE_ONE_STAGE("activation_weight");
        if (ok && g_parallel_q8_pending) {
            ok = ds4_gpu_parallel_q8_matvec_encode_pending(cb, midbuf) != 0;
        }

        id<MTLBuffer> down_dst = n_expert == 1 ? outbuf : (expertsbuf ? expertsbuf : g_moe_down_scratch_buffer);
        NSUInteger down_dst_off = n_expert == 1 ? ds4_gpu_tensor_offset(out) :
            (expertsbuf ? ds4_gpu_tensor_offset(experts) : 0);
        if (ok && stream_expert_split_completed) {
            /* The split path already wrote the resident partial output and
             * accumulated the missing experts into out. */
        } else if (ok && use_q4_grouped_experts) {
            bool first_group = true;
            for (uint32_t expert_base = 0; ok && expert_base < n_total_expert; expert_base += q4_expert_group_size) {
                const uint32_t expert_count =
                    q4_expert_group_size < n_total_expert - expert_base ?
                    q4_expert_group_size : n_total_expert - expert_base;
                if ((uint64_t)expert_base > UINT64_MAX / down_expert_bytes ||
                    (uint64_t)expert_count > UINT64_MAX / down_expert_bytes) {
                    ok = 0;
                    break;
                }
                const uint64_t group_rel = (uint64_t)expert_base * down_expert_bytes;
                const uint64_t group_bytes = (uint64_t)expert_count * down_expert_bytes;
                if (group_rel > UINT64_MAX - down_offset) {
                    ok = 0;
                    break;
                }
                uint64_t down_group_inner = 0;
                id<MTLBuffer> down_group_buf =
                    q4_grouped_cache_views ?
                    ds4_gpu_wrap_model_exact_range(model_map,
                                                   model_size,
                                                   down_offset + group_rel,
                                                   group_bytes,
                                                   &down_group_inner) :
                    ds4_gpu_wrap_model_exact_range_transient(model_map,
                                                             model_size,
                                                             down_offset + group_rel,
                                                             group_bytes,
                                                             &down_group_inner);
                if (!down_group_buf) {
                    ok = 0;
                    break;
                }
                ds4_gpu_moe_expert_group_args group_args = {
                    .expert_base = expert_base,
                    .expert_count = expert_count,
                    .accumulate = first_group ? 0u : 1u,
                    .pad0 = 0,
                };
                ok = ds4_gpu_encode_mul_mv_group_q4_sum6(cb,
                                                          g_moe_mul_mv_group_q4_k_sum6_pipeline,
                                                          &down_args,
                                                          &group_args,
                                                          down_group_buf,
                                                          (NSUInteger)down_group_inner,
                                                          midbuf,
                                                          ds4_gpu_tensor_offset(mid),
                                                          outbuf,
                                                          ds4_gpu_tensor_offset(out),
                                                          selectedbuf,
                                                          ds4_gpu_tensor_offset(selected),
                                                          down_smem,
                                                          2);
                first_group = false;
            }
        } else if (ok && use_q4_expert_address_table) {
            ok = ds4_gpu_encode_mul_mv_addr_q4_sum6(cb,
                                                    g_moe_mul_mv_addr_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_table,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && use_q4_expert_table) {
            ok = ds4_gpu_encode_mul_mv_table_q4_sum6(cb,
                                                    g_moe_mul_mv_table_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_table,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2,
                                                    q4_table_queue_residency);
        } else if (ok && use_q4_group6_experts) {
            ok = ds4_gpu_encode_mul_mv_group6_sum6(cb,
                                                    g_moe_mul_mv_group6_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_group6_bufs,
                                                    down_group6_offsets,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && use_q4_group8_experts) {
            ok = ds4_gpu_encode_mul_mv_group8_sum6(cb,
                                                    g_moe_mul_mv_group8_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_group8_bufs,
                                                    down_group8_offsets,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && use_q4_group24_experts) {
            ok = ds4_gpu_encode_mul_mv_group24_sum6(cb,
                                                    g_moe_mul_mv_group24_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_group24_bufs,
                                                    down_group24_offsets,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && (use_q4_gather_slots || use_selected_slots)) {
            if (use_stream_expert_addr_table) {
                if (down_type == DS4_METAL_TENSOR_IQ2_XXS) {
                    ok = ds4_gpu_encode_mul_mv_addr_iq2(cb,
                                                        g_moe_mul_mv_addr_iq2_xxs_pipeline,
                                                        &down_args,
                                                        stream_slot_entries,
                                                        n_expert,
                                                        stream_down_addr_buf,
                                                        midbuf,
                                                        ds4_gpu_tensor_offset(mid),
                                                        down_dst,
                                                        down_dst_off,
                                                        selected_exec_buf,
                                                        selected_exec_off,
                                                        down_smem,
                                                        2,
                                                        false, 2, nil);
                } else if (use_stream_expert_masked_addr_table) {
                    ds4_gpu_stream_expert_split_args split_args = {
                        .active_mask = 0x3fu,
                        .accumulate = 0u,
                    };
                    ok = ds4_gpu_encode_mul_mv_addr_q2_sum6_masked(cb,
                                                                   g_moe_mul_mv_addr_q2_k_sum6_masked_pipeline,
                                                                   &down_args,
                                                                   &split_args,
                                                                   stream_slot_entries,
                                                                   stream_down_addr_buf,
                                                                   midbuf,
                                                                   ds4_gpu_tensor_offset(mid),
                                                                   outbuf,
                                                                   ds4_gpu_tensor_offset(out),
                                                                   selected_exec_buf,
                                                                   selected_exec_off,
                                                                   down_smem,
                                                                   2);
                } else {
                    ok = ds4_gpu_encode_mul_mv_addr_q2_sum6(cb,
                                                             g_moe_mul_mv_addr_q2_k_sum6_pipeline,
                                                             &down_args,
                                                             stream_slot_entries,
                                                             n_expert,
                                                             stream_down_addr_buf,
                                                             midbuf,
                                                             ds4_gpu_tensor_offset(mid),
                                                             outbuf,
                                                             ds4_gpu_tensor_offset(out),
                                                             selected_exec_buf,
                                                             selected_exec_off,
                                                             down_smem,
                                                             2,
                                                             nil);
                }
            } else {
                ok = (!use_stream_expert_cache ||
                      ds4_gpu_stream_expert_cache_mark_entries_inflight(
                              stream_slot_entries,
                              n_expert,
                              0)) &&
                     ds4_gpu_encode_mul_mv_slots6_sum6(cb,
                                                       slots_sum6_pipeline,
                                                       &down_args,
                                                       down_slot_bufs,
                                                       down_slot_offsets,
                                                       midbuf,
                                                       ds4_gpu_tensor_offset(mid),
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       down_smem,
                                                       2);
            }
        } else if (ok && direct_down_sum) {
            ok = ds4_gpu_encode_mul_mv_id_sum6(cb,
                                                 down_sum6_pipeline,
                                                 &down_args,
                                                 down_buf,
                                                 (NSUInteger)down_inner,
                                                 midbuf,
                                                 ds4_gpu_tensor_offset(mid),
                                                 outbuf,
                                                 ds4_gpu_tensor_offset(out),
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 add_in ? ds4_gpu_tensor_buffer(add_in) : nil,
                                                 add_in ? ds4_gpu_tensor_offset(add_in) : 0,
                                                 down_smem,
                                                 down_sum6_nsg);
        } else if (ok) {
            ok = ds4_gpu_encode_mul_mv_id(cb,
                                                 down_mv_pipeline,
                                                 &down_args,
                                                 down_buf,
                                                 (NSUInteger)down_inner,
                                                 midbuf,
                                                 ds4_gpu_tensor_offset(mid),
                                                 down_dst,
                                                 down_dst_off,
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 down_smem,
                                                 down_nsg,
                                                 down_rows_per_group_is_nr0);
        }
        DS4_METAL_PROFILE_MOE_ONE_STAGE("down");
        if (ok && n_expert > 1 && !direct_down_sum && !stream_expert_split_completed) {
            ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                       down_dst,
                                                       down_dst_off,
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       out_dim,
                                                       n_expert,
                                                       n_tokens);
        }
        DS4_METAL_PROFILE_MOE_ONE_STAGE("sum");
        if (ok && g_parallel_ffn_mode == 2 && g_parallel_ffn_stage == 1) {
            ok = ds4_gpu_parallel_ffn_encode_second_stage(cb) != 0;
        }
        if (!ok) { if (getenv("DS4_GLM_TP_DEBUG")) fprintf(stderr, "ds4: routed_moe_one silent return at line %d\n", 34395); return 0; }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "routed tensor MoE")) { if (getenv("DS4_GLM_TP_DEBUG")) fprintf(stderr, "ds4: routed_moe_one silent return at line %d\n", 34397); return 0; }
        if (q4_grouped_boundary || q4_exact_boundary || q4_table_boundary) {
            if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
                if (getenv("DS4_GLM_TP_DEBUG")) fprintf(stderr, "ds4: routed_moe_one silent return at line %d\n", 34372);
                return 0;
            }
        }
#undef DS4_METAL_PROFILE_MOE_ONE_STAGE
    }

    parallel_ffn_scope = NO;
    return 1;
}

/* llms ED_FLAG (apply_ed_flag.py): flag post + spinning server instead of encodeSignalEvent + listener; the event wait stays */
#include <pthread.h>
#include <pthread/qos.h>
enum { EXPERT_REQUEST_RING = 256 };
typedef struct {
    const void *model_map; uint64_t model_size; uint32_t layer; const ds4_gpu_tensor *selected; uint32_t n_tokens, n_total_expert, n_selected;
    uint64_t gate_offset, up_offset, down_offset, gate_expert_bytes, down_expert_bytes;
    __unsafe_unretained id<MTLBuffer> ga, ua, da;
    const ds4_gpu_tensor *probs, *wts; const float *bias; uint64_t v1, v2;
    int ela;   /* llms ED_LA5: this step computes the look-ahead and prefetches on it */
    int wfe;   /* llms EDF_WFE_ALT: this request's wait sleeps in WFE (decided at encode: LLMS_DS4_EDF_WFE and not ALT-off 'wfe') */
    int altoff;   /* llms EDF_TIME_C: the ALT name in LLMS_DS4_EDF_TIME_ALT was off when this request was encoded */
    int msk;   /* llms ED_SKIP: this request may drop small cold picks (decided at encode: LLMS_DS4_ED_SKIP and not ALT-off 'msk') */
    double astra_enqueue; uint32_t astra_step; /* diagnostic request identity */
    const ds4_gpu_tensor *elc_norm; uint32_t elc_rows;   /* llms KROW_LA: the request's own FFN input rows */
    int lag_on, lag_src; uint64_t lag_step;   /* llms LAG: decide this layer's lags; prepare the lag call of layer lag_src (-1: none); the step */
    int lag_if;   /* llms LAG_IF (apply_lagif.py): this request lags its in-flight look-ahead picks too (mode 0; under mode 1 on ALT-off 'lagif' steps) */
    int z9slot;   /* llms Z9: the shadow ring slot of this request's GPU policy (-1: none) */
} expert_request;
static float cold_skip_theta(void);   /* llms ED_SKIP */
static expert_request expert_request_ring[EXPERT_REQUEST_RING]; static uint64_t expert_request_head, expert_request_tail;
static int g_llms_astra_mark; static id<MTLComputePipelineState> g_llms_astra_mark_ps;   /* MARKER */
static int expert_server_state = -1; static id<MTLComputePipelineState> post_flag_pipeline; static id<MTLBuffer> post_flag_box; static dispatch_semaphore_t expert_request_semaphore;
static uint64_t flag_posts, expert_requests_served, listener_path_calls, notices_needing_rereads, flag_rereads, flag_checksum_failures, flag_spins;
static uint64_t retired_without_post;   /* llms EDF_ABORT */
static void abort_expert_server_at_exit(void) { expert_server_abort = 1; }
static void report_expert_server(void) {
    fprintf(stderr, "llms ed flag: %llu posts, %llu served, %llu calls on the listener path, %llu notices needed re-reads (%llu re-reads), %llu checksum failures (retired), %llu retired without a post, %.0f spins per notice\n",
            (unsigned long long)flag_posts, (unsigned long long)expert_requests_served, (unsigned long long)listener_path_calls, (unsigned long long)notices_needing_rereads,
            (unsigned long long)flag_rereads, (unsigned long long)flag_checksum_failures, (unsigned long long)retired_without_post, expert_requests_served ? (double)flag_spins / (double)expert_requests_served : 0.0);
}
static inline uint32_t mix_flag_word(uint32_t w, uint32_t i) { uint32_t x = w ^ (i * 0x9E3779B9u); x *= 0x85EBCA6Bu; x ^= x >> 13; x *= 0xC2B2AE35u; x ^= x >> 16; return x; }
static const volatile uint32_t *tensor_words(const ds4_gpu_tensor *t) { return (const volatile uint32_t *)((const uint8_t *)[ds4_gpu_tensor_buffer(t) contents] + ds4_gpu_tensor_offset(t)); }
static uint32_t request_checksum(const expert_request *q) {   /* the post kernel's function: sum of mixed words + the sequence number */
    uint32_t c = 0; const uint32_t ns = q->n_selected * q->n_tokens;
    const volatile uint32_t *p = tensor_words(q->probs), *se = tensor_words(q->selected), *w = tensor_words(q->wts);
    for (uint32_t i = 0; i < q->n_total_expert; i++) c += mix_flag_word(p[i], i);
    for (uint32_t i = 0; i < ns; i++) { c += mix_flag_word(se[i], 1024u + i); c += mix_flag_word(w[i], 2048u + i); }
    return c + mix_flag_word((uint32_t)q->v1, 4096u);
}
/* llms ED_ROUTE (apply_ed_route.py): routing record / replay in the ED_FLAG server (verified router outputs) */
static int decision_record_state = -1; static FILE *decision_log, *decision_replay_file; static uint64_t decisions_logged, decisions_replayed, decision_mismatches, decision_replay_short;
static void report_decision_record(void) {
    fprintf(stderr, "llms ed route: %llu calls logged, %llu replayed, %llu layer mismatches, %llu replay records missing\n", (unsigned long long)decisions_logged,
            (unsigned long long)decisions_replayed, (unsigned long long)decision_mismatches, (unsigned long long)decision_replay_short);
    if (decision_log) fflush(decision_log);
}
static int decision_record_on(void) {
    if (decision_record_state < 0) {
        decision_record_state = 0; const char *l = getenv("LLMS_DS4_ED_ROUTE_LOG"), *r = getenv("LLMS_DS4_ED_ROUTE_REPLAY");
        if (l && *l) decision_log = fopen(l, "wb");
        if (r && *r) decision_replay_file = fopen(r, "rb");
        if (decision_log || decision_replay_file) { decision_record_state = 1; atexit(report_decision_record);
            fprintf(stderr, "llms: ed route%s%s\n", decision_log ? " log" : "", decision_replay_file ? " replay (every routing decision pinned to the record)" : ""); }
    }
    return decision_record_state;
}
static int replay_ids_only;   /* llms ROUTE_FREEZE (apply_route_freeze.py): replay the ids, recompute the weights from the current scores */
int ds4_gpu_llms_route_record(const char *path) {   /* llms ROUTE_FREEZE: (re)open the decision log; NULL closes it */
    if (decision_log) { fclose(decision_log); decision_log = NULL; }
    if (path && *path) { decision_log = fopen(path, "wb"); if (!decision_log) return 0; }
    decision_record_state = (decision_log || decision_replay_file) ? 1 : 0; return 1;
}
int ds4_gpu_llms_route_replay(const char *path, int ids_only) {   /* llms ROUTE_FREEZE: (re)open the replay from its start; NULL closes it */
    if (decision_replay_file) { fclose(decision_replay_file); decision_replay_file = NULL; }
    if (path && *path) { decision_replay_file = fopen(path, "rb"); if (!decision_replay_file) return 0; }
    replay_ids_only = ids_only; decision_record_state = (decision_log || decision_replay_file) ? 1 : 0; return 1;
}
void ds4_gpu_llms_route_counters(uint64_t *replayed, uint64_t *mismatched, uint64_t *short_reads, uint64_t *logged) {
    *replayed = decisions_replayed; *mismatched = decision_mismatches; *short_reads = decision_replay_short; *logged = decisions_logged;
}
static int replay_decision(const expert_request *q) {   /* 1 = the recorded selection was written into the tensors */
    int32_t hdr[2]; static float decision_replay_probabilities[1024];
    if (fread(hdr, sizeof hdr, 1, decision_replay_file) != 1 || hdr[1] < 0 || hdr[1] > 1024) { decision_replay_short++; return 0; }   /* llms ROUTE_FREEZE: was > 64 */
    static int32_t ids[1024]; static float decision_replay_weights[1024];
    if (fread(decision_replay_probabilities, sizeof(float), q->n_total_expert, decision_replay_file) != q->n_total_expert || fread(ids, sizeof(int32_t), (size_t)hdr[1], decision_replay_file) != (size_t)hdr[1] ||
        fread(decision_replay_weights, sizeof(float), (size_t)hdr[1], decision_replay_file) != (size_t)hdr[1]) { decision_replay_short++; return 0; }
    if ((uint32_t)hdr[0] != q->layer || (uint32_t)hdr[1] != q->n_selected * q->n_tokens) { decision_mismatches++; return 0; }
    if (replay_ids_only) {   /* llms ROUTE_FREEZE: the weights from THIS pass's scores over the frozen set (apply_decode_route_row's formula) */
        const uint32_t ns = q->n_selected, nt = q->n_tokens ? q->n_tokens : 1u, E = q->n_total_expert;
        const float *cp = (const float *)((const uint8_t *)[ds4_gpu_tensor_buffer(q->probs) contents] + ds4_gpu_tensor_offset(q->probs));
        const float *cw = (const float *)((const uint8_t *)[ds4_gpu_tensor_buffer(q->wts) contents] + ds4_gpu_tensor_offset(q->wts));
        for (uint32_t r = 0; r < nt; r++) {
            float ws = 0.0f, ps = 0.0f;
            for (uint32_t i = 0; i < ns; i++) { ws += cw[r * ns + i]; const int32_t e = ids[r * ns + i]; if (e >= 0 && (uint32_t)e < E) ps += cp[(size_t)r * E + (uint32_t)e]; }
            for (uint32_t i = 0; i < ns; i++) { const int32_t e = ids[r * ns + i]; decision_replay_weights[r * ns + i] = (ps > 0.0f && e >= 0 && (uint32_t)e < E) ? cp[(size_t)r * E + (uint32_t)e] / ps * ws : 0.0f; }
        }
    }
    memcpy((uint8_t *)[ds4_gpu_tensor_buffer(q->selected) contents] + ds4_gpu_tensor_offset(q->selected), ids, (size_t)hdr[1] * sizeof(int32_t));
    memcpy((uint8_t *)[ds4_gpu_tensor_buffer(q->wts) contents] + ds4_gpu_tensor_offset(q->wts), decision_replay_weights, (size_t)hdr[1] * sizeof(float));
    decisions_replayed++; return 1;
}
static void write_decision(const expert_request *q) {
    const int32_t n = (int32_t)(q->n_selected * q->n_tokens), hdr[2] = {(int32_t)q->layer, n};
    fwrite(hdr, sizeof hdr, 1, decision_log);
    fwrite((const uint8_t *)[ds4_gpu_tensor_buffer(q->probs) contents] + ds4_gpu_tensor_offset(q->probs), sizeof(float), q->n_total_expert, decision_log);
    fwrite((const uint8_t *)[ds4_gpu_tensor_buffer(q->selected) contents] + ds4_gpu_tensor_offset(q->selected), sizeof(int32_t), (size_t)n, decision_log);
    fwrite((const uint8_t *)[ds4_gpu_tensor_buffer(q->wts) contents] + ds4_gpu_tensor_offset(q->wts), sizeof(float), (size_t)n, decision_log);
    decisions_logged++;
}
/* llms ED_LA (apply_ed_la.py): the router look-ahead prefetch carried by the ED_FLAG server */
static ds4_gpu_stream_expert_table lookahead_expert_table[64]; static int lookahead_table_ready[64]; static const float *lookahead_router_bias[64];
static const ds4_gpu_tensor *lookahead_selected, *lookahead_probs;   /* lookahead_top_m: see llms ED_LA2 above */
static uint64_t lookahead_predictions_read, lookahead_experts_prefetched, lookahead_installs_before_peek, lookahead_prefetched_selected, lookahead_unused_in_flight, lookahead_malformed, lookahead_begin_errors, lookahead_nothing_to_fetch;
static void report_lookahead(void) {
    fprintf(stderr, "llms ed la: %llu predictions read (%llu malformed), %llu with nothing to fetch, %llu skipped (previous prefetch in flight); "
            "%llu experts prefetched (%llu begin errors, %llu aio refusals, %llu read failures); %llu installs before the peek (%llu waited on the read), "
            "%llu prefetched experts selected, %llu installed unasked, %llu in flight and unused at their layer\n",
            (unsigned long long)lookahead_predictions_read, (unsigned long long)lookahead_malformed, (unsigned long long)lookahead_nothing_to_fetch, (unsigned long long)lookahead_skipped_in_flight,
            (unsigned long long)lookahead_experts_prefetched, (unsigned long long)lookahead_begin_errors, (unsigned long long)lookahead_aio_refusals, (unsigned long long)lookahead_read_failures,
            (unsigned long long)lookahead_installs_before_peek, (unsigned long long)lookahead_waited_on_read, (unsigned long long)lookahead_prefetched_selected, (unsigned long long)lookahead_installed_unasked,
            (unsigned long long)lookahead_unused_in_flight);     fprintf(stderr, "llms ed la slots: %llu predictions dropped with every slot reading, %llu experts already in flight\n", (unsigned long long)lookahead_dropped_slots_full, (unsigned long long)lookahead_already_in_flight);   /* llms ED_LA9 */
    fprintf(stderr, "llms ed la timing: used installs: mean lead %.3f ms (n %llu), mean read %.3f ms (n %llu); %llu waits, mean wait %.3f ms, total %.1f ms\n",
            lookahead_leads_counted ? lookahead_lead_ms / lookahead_leads_counted : 0.0, (unsigned long long)lookahead_leads_counted, lookahead_reads_counted ? lookahead_read_ms / lookahead_reads_counted : 0.0,
            (unsigned long long)lookahead_reads_counted, (unsigned long long)lookahead_waited_on_read, lookahead_waited_on_read ? lookahead_wait_ms / lookahead_waited_on_read : 0.0, lookahead_wait_ms);   /* llms ED_LA4 */
}
void ds4_gpu_llms_ela_note(uint32_t layer, const void *map, uint64_t size, uint32_t n_total, uint64_t gate_off, uint64_t up_off, uint64_t down_off,
                           uint64_t gate_bytes, uint64_t down_bytes, const ds4_gpu_tensor *sel, const ds4_gpu_tensor *probs, const float *bias, int m) {
    if (layer >= 64u || m <= 0) return;
    if (!lookahead_top_m) { lookahead_selected = sel; lookahead_probs = probs; atexit(report_lookahead);
                         fprintf(stderr, "llms: ed la (layer l+1's router on layer l's FFN input; its top %d non-resident experts prefetched by the ED server)\n", m);
                         __atomic_store_n(&lookahead_top_m, m, __ATOMIC_RELEASE); }
    if (!__atomic_load_n(&lookahead_table_ready[layer], __ATOMIC_ACQUIRE)) {
        lookahead_expert_table[layer] = (ds4_gpu_stream_expert_table){ .model_map = map, .model_size = size, .layer = layer, .n_total_expert = n_total,
            .gate_offset = gate_off, .up_offset = up_off, .down_offset = down_off, .gate_expert_bytes = gate_bytes, .down_expert_bytes = down_bytes };
        lookahead_router_bias[layer] = bias;
        __atomic_store_n(&lookahead_table_ready[layer], 1, __ATOMIC_RELEASE);
    }
}
static inline float lookahead_resident_bonus(uint32_t L, uint32_t e) {   /* llms ED_LA8: ONE_RPOL's resident bonus for (layer, expert) */
    const int res = (int)((resident_bits[L][e >> 6] >> (e & 63u)) & 1ull);
    return res ? ((late_bonus_from_layer && L >= late_bonus_from_layer) ? late_bonus : decode_resident_bonus) : 0.0f;
}
static uint32_t lookahead_policy_top(const float *score, uint32_t L, uint32_t nt, uint32_t ns, int32_t *top) {   /* top ns of score + bonus */
    static float sc[512]; uint32_t nn = 0;
    for (uint32_t r = 0; r < nt; r++) sc[r] = score[r] + lookahead_resident_bonus(L, r);
