            (double)cold_skip_threshold, (unsigned long long)cold_skip_calls, (unsigned long long)cold_skip_cold_picks, (unsigned long long)cold_skip_drops,
            cold_skip_drops ? cold_skip_share / (double)cold_skip_drops : 0.0, (unsigned long long)cold_skip_background_reads);
