    for (int L = lag_first_layer; L <= lag_last_layer; L++) { (void)ds4_gpu_tensor_write(lag_counts[L], 0, z, sizeof z); lag_host[L].step = 0; lag_host[L].tot = 0; lag_prepared[L] = 0; }
    lag_steps++; return ++lag_step_id;
}
void ds4_gpu_llms_lag_step_end(void) {   /* lags decided this step that no request prepared: their outputs were never added */
    if (lag_configured != 1) return;
    for (int L = lag_first_layer; L <= lag_last_layer; L++) if (lag_host[L].step == lag_step_id && lag_host[L].tot && !lag_prepared[L]) lag_pairs_lost += lag_host[L].tot;
