void ds4_gpu_llms_lag_arm(uint32_t layer, uint64_t step) { lag_armed_layer = step ? (int)layer : -1; lag_armed_step = step; lag_armed_source = -1; }
void ds4_gpu_llms_lag_arm_src(int src) { lag_armed_source = src; }   /* v3: after ds4_gpu_llms_lag_arm, the source whose lag call this request prepares */
int ds4_gpu_llms_lag_wait(uint32_t L, uint64_t step) {   /* v3, main thread: layer L's decision this step -> pairs lagged (0 none), -1 never armed or timed out */
