    if (__atomic_load_n(&lag_armed_at_step[L], __ATOMIC_ACQUIRE) != step) { lag_never_armed++; return -1; }
    if (__atomic_load_n(&lag_decided_step[L], __ATOMIC_ACQUIRE) != step) {
        const double t0 = ds4_gpu_now_ms(); lag_waits_done++;
