void ds4_gpu_llms_lag_nowait(int on) { lag_no_wait = on; event_driven_call_open = on ? 1 : 0; }
ds4_gpu_tensor *ds4_gpu_llms_lag_tensor(int which, uint32_t L) {
    if (lag_configured != 1) return NULL;
    switch (which) { case 0: return L < 64u ? lag_selected[L] : NULL; case 1: return L < 64u ? lag_weights[L] : NULL; case 2: return L < 64u ? lag_inputs[L] : NULL;
                     case 3: return lag_late_output; case 4: case 5: case 6: case 7: return lag_scratch[which - 4]; }
    return NULL;
}
/* llms DIMS_ZERO (apply_dims_zero.py): zero lanes[k] in every stream of [rows x streams x n_embd] floats */
static id<MTLComputePipelineState> zero_lanes_pipeline; static id<MTLBuffer> zero_lanes_buffer; static uint64_t zero_lanes_version_up;
int ds4_gpu_llms_zero_lanes(ds4_gpu_tensor *t, uint32_t rows, uint32_t streams, uint32_t n_embd, const uint32_t *lanes, uint32_t n_lanes, uint64_t version) {
    if (!t || !rows || !streams || !n_lanes || n_lanes > 8192u || !g_batch_cb || !g_device) return 0;
    if (!zero_lanes_pipeline) {
        NSError *err = nil;
        id<MTLLibrary> lib = [g_device newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\n"
            "kernel void llms_zero_lanes(device float *x [[buffer(0)]], device const uint *lanes [[buffer(1)]], constant uint4 &a [[buffer(2)]], uint i [[thread_position_in_grid]]) {\n"
            "  const uint nl = a.x, rows = a.y, n = a.z, st = a.w; if (i >= nl * rows * st) return; const uint k = i % nl, rs = i / nl; x[rs * n + lanes[k]] = 0.0f; }\n" options:nil error:&err];
        id<MTLFunction> fn = lib ? [lib newFunctionWithName:@"llms_zero_lanes"] : nil;
        zero_lanes_pipeline = fn ? [g_device newComputePipelineStateWithFunction:fn error:&err] : nil;
        zero_lanes_buffer = [g_device newBufferWithLength:8192u * 4u options:MTLResourceStorageModeShared];
        if (!zero_lanes_pipeline || !zero_lanes_buffer) { fprintf(stderr, "llms dims zero: the kernel failed (%s)\n", err ? err.localizedDescription.UTF8String : "buffer"); return 0; }
    }
    if (version != zero_lanes_version_up) { memcpy([zero_lanes_buffer contents], lanes, (size_t)n_lanes * 4u); zero_lanes_version_up = version; }   /* the CLI changes a mask only between whole passes */
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(g_batch_cb);
    [enc setComputePipelineState:zero_lanes_pipeline];
    [enc setBuffer:ds4_gpu_tensor_buffer(t) offset:ds4_gpu_tensor_offset(t) atIndex:0]; [enc setBuffer:zero_lanes_buffer offset:0 atIndex:1];
    const uint32_t a[4] = { n_lanes, rows, n_embd, streams }; [enc setBytes:a length:sizeof a atIndex:2];
    [enc dispatchThreads:MTLSizeMake((NSUInteger)n_lanes * rows * streams, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
    return 1;
}
int ds4_gpu_llms_lag_add(ds4_gpu_tensor *block, uint32_t src, uint32_t rows, uint32_t n_embd) {   /* block += late on the rows whose count is > 0 */
    if (lag_configured != 1 || src >= 64u || !lag_counts[src] || !lag_add_pipeline || !g_batch_cb || !block || rows > LAG_MAX_ROWS) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(g_batch_cb);
    [enc setComputePipelineState:lag_add_pipeline];
    [enc setBuffer:ds4_gpu_tensor_buffer(block) offset:ds4_gpu_tensor_offset(block) atIndex:0];
    [enc setBuffer:ds4_gpu_tensor_buffer(lag_late_output) offset:ds4_gpu_tensor_offset(lag_late_output) atIndex:1];
    [enc setBuffer:ds4_gpu_tensor_buffer(lag_counts[src]) offset:ds4_gpu_tensor_offset(lag_counts[src]) atIndex:2];
    const uint32_t a[2] = { n_embd, rows }; [enc setBytes:a length:sizeof a atIndex:3];
    [enc dispatchThreads:MTLSizeMake((NSUInteger)rows * n_embd, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    lag_adds_encoded++;
    return 1;
}
int ds4_gpu_llms_cond_add_rows(ds4_gpu_tensor *block, const ds4_gpu_tensor *late, const ds4_gpu_tensor *cnt, uint32_t rows, uint32_t n_embd) {   /* llms PLAG */
    if (!lag_add_pipeline && g_device) {
        NSError *err = nil;
        id<MTLLibrary> lib = [g_device newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\n"
            "kernel void llms_lag_add(device float *blk [[buffer(0)]], device const float *late [[buffer(1)]], device const uint *cnt [[buffer(2)]],\n"
            "    constant uint2 &a [[buffer(3)]], uint i [[thread_position_in_grid]]) { const uint r = i / a.x; if (r >= a.y || cnt[r] == 0u) return; blk[i] += late[i]; }\n"
            options:nil error:&err];
        id<MTLFunction> fn = lib ? [lib newFunctionWithName:@"llms_lag_add"] : nil;
        lag_add_pipeline = fn ? [g_device newComputePipelineStateWithFunction:fn error:&err] : nil;
    }
    if (!lag_add_pipeline || !g_batch_cb || !block || !late || !cnt || !rows || !n_embd) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(g_batch_cb);
    [enc setComputePipelineState:lag_add_pipeline];
    [enc setBuffer:ds4_gpu_tensor_buffer(block) offset:ds4_gpu_tensor_offset(block) atIndex:0];
    [enc setBuffer:ds4_gpu_tensor_buffer(late) offset:ds4_gpu_tensor_offset(late) atIndex:1];
    [enc setBuffer:ds4_gpu_tensor_buffer(cnt) offset:ds4_gpu_tensor_offset(cnt) atIndex:2];
    const uint32_t a[2] = { n_embd, rows }; [enc setBytes:a length:sizeof a atIndex:3];
    [enc dispatchThreads:MTLSizeMake((NSUInteger)rows * n_embd, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    return 1;
}
static void decide_lag_body(const expert_request *q);
static void decide_lag(const expert_request *q) {   /* v3: the body, then the stamp the main thread waits on (lag or not) */
    decide_lag_body(q);
    if (q->layer < 64u) __atomic_store_n(&lag_decided_step[q->layer], q->lag_step, __ATOMIC_RELEASE);
}
static void decide_lag_body(const expert_request *q) {   /* serve thread, before the settle: this layer's non-resident picks leave the call */
    const uint32_t L = q->layer, ns = q->n_selected, nt = q->n_tokens ? q->n_tokens : 1u;
    if (lag_configured != 1 || nt > LAG_MAX_ROWS || ns > 8u || ns == 0 || L >= 64u || !q->wts || !lag_selected[L]) return;
    if (lag_mode & 4) return;   /* LAG v2 mode 4: the instrument -- every lag call encoded, nothing lagged */
    {   static int exact_lag_state = -1; if (exact_lag_state < 0) { const char *e = getenv("LLMS_DS4_EXACT_LAG"); exact_lag_state = e && *e && *e != '0'; if (exact_lag_state) fprintf(stderr, "llms: exact lag (the exact step also keeps non-resident picks in their call: no decode lag)\n"); }   /* llms EXACT_LAG (apply_exact_tail2.py) */
        if ((exact_lag_state || g_metal_escalate) && exact_step_now()) return; }   /* llms ESCALATE: an escalated step skips LAG too */
    int32_t ids[LAG_MAX_ROWS * 8]; float w[LAG_MAX_ROWS * 8];
