    int32_t ls[LAG_MAX_ROWS * 8]; float lw[LAG_MAX_ROWS * 8]; uint32_t cnt[LAG_MAX_ROWS] = {0}, tot = 0; int32_t bg[8]; uint32_t nbg = 0;
    for (uint32_t i = 0; i < nt * ns; i++) { ls[i] = -1; lw[i] = 0.0f; }
    for (uint32_t r = 0; r < nt; r++) {
        int res = 0;
        for (uint32_t i = 0; i < ns; i++) { const int32_t e = ids[r * ns + i]; if (e >= 0 && (uint32_t)e < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT && g_stream_expert_cache[L][e].valid) res++; }
        if (!res) { lag_rows_kept_whole++; continue; }   /* never an all-dropped row: a row with no resident pick keeps its misses */
        for (uint32_t i = 0; i < ns; i++) {
            const int32_t e = ids[r * ns + i];
            if (e < 0 || (uint32_t)e >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT || g_stream_expert_cache[L][e].valid) continue;
            const int infl = lookahead_in_flight(L, e);
