    if (!ds4_gpu_tensor_write((ds4_gpu_tensor *)q->selected, 0, ids, nb * sizeof(int32_t)) || !ds4_gpu_tensor_write((ds4_gpu_tensor *)q->wts, 0, w, nb * sizeof(float)) ||
        !ds4_gpu_tensor_write(lag_selected[L], 0, ls, nb * sizeof(int32_t)) || !ds4_gpu_tensor_write(lag_weights[L], 0, lw, nb * sizeof(float))) { event_driven_error = 1; return; }
    lag_host_record *h = &lag_host[L];
    h->nt = nt; h->ns = ns; h->nte = q->n_total_expert; h->tot = tot; memcpy(h->cnt, cnt, sizeof cnt);
    h->map = q->model_map; h->size = q->model_size; h->go = q->gate_offset; h->uo = q->up_offset; h->dof = q->down_offset; h->gb = q->gate_expert_bytes; h->db = q->down_expert_bytes;
    __atomic_store_n(&h->step, q->lag_step, __ATOMIC_RELEASE);
    lag_pairs += tot; lag_pairs_by_layer[L] += tot; for (uint32_t r = 0; r < nt; r++) if (cnt[r]) lag_rows++;
    if (nbg && lookahead_top_m > 0) { const uint64_t r0 = lookahead_experts_prefetched; lookahead_reading_for_lag = 1; @autoreleasepool { begin_lookahead(L, bg, nbg); } lookahead_reading_for_lag = 0; lag_background_reads += lookahead_experts_prefetched - r0; }   /* LAG v2: tagged */
}
static void prepare_lag_call(const expert_request *q) {   /* serve thread: the lag call of layer q->lag_src, encoded after this request's routed kernels */
    const int L = q->lag_src;
    if (lag_configured != 1 || L < 0 || L >= 64) return;
    lag_host_record *h = &lag_host[L];
    if (__atomic_load_n(&h->step, __ATOMIC_ACQUIRE) != q->lag_step || !h->tot) return;
    const double t0 = ds4_gpu_now_ms();
    if (lookahead_top_m) settle_lookahead((uint32_t)L, lag_selected[L], h->nt * h->ns);
    id<MTLBuffer> g2 = nil, u2 = nil, d2 = nil, o1 = nil, o2 = nil, o3 = nil;
    ds4_gpu_stream_expert_cache_entry *r2[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT]; uint32_t nr2 = 0, un2 = 0;
    const int ok = ds4_gpu_stream_expert_cache_prepare_selected_batch(h->map, h->size, (uint32_t)L, lag_selected[L], h->nt, h->nte, h->ns, h->go, h->uo, h->dof,
                                                                      h->gb, h->db, &g2, &u2, &d2, r2, &nr2, &un2, &o1, &o2, &o3);
    lag_prepare_ms += ds4_gpu_now_ms() - t0; lag_prepares++;
