}
static int gpu_policy_shadow_state; static void compare_gpu_policy(const expert_request *q);   /* llms Z9: defined with the kernel below (tentative definition + prototype) */

/* llms REFRESH_SWAP v2: LLMS_DS4_REFRESH_SWAP=N[:T] -- the window's EXACT routing mass (the router's six, weights normalized per row, before the policy) per (layer, expert) over the process's first N listener cycles; then, once, the global greedy swap (non-residents with mass >= T in descending mass against residents in ascending mass, while the candidate's exceeds the resident's), issued through the look-ahead slots one batch at a time under the issue contract in the apply script's docstring. OFF unless set. */
enum { REFRESH_ITEMS = DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER * DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT };
typedef struct { float m; uint16_t L, e; } refresh_item;
static int refresh_swap_n = -1, refresh_phase;   /* phase: 0 summing the window, 1 the plan due, 2 issuing, 3 done */
static float refresh_swap_floor = 1.0f;
static float refresh_mass[DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER][DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
static refresh_item refresh_cand[REFRESH_ITEMS], refresh_res[REFRESH_ITEMS]; static uint8_t refresh_in_done[REFRESH_ITEMS];
static uint32_t refresh_cycles, refresh_n_swaps, refresh_n_cand, refresh_n_res, refresh_in_cursor, refresh_out_cursor, refresh_plan_cycle, refresh_done_cycle, refresh_demoted_unused;
static uint64_t refresh_rows_summed, refresh_batches_issued, refresh_experts_requested, refresh_not_now, refresh_not_issued, refresh_begin_failures, refresh_demoted,
                refresh_already_resident, refresh_inflight_skips;
static double refresh_mass_in, refresh_mass_out, refresh_plan_ms;
static uint64_t refresh_req_rows[4];   /* the window's requests by row count: 1, 2, 3-4, 5-8 (what entered the window: decode verifies, short appends) */
static int refresh_desc(const void *a, const void *b) { const refresh_item *x = a, *y = b; if (x->m != y->m) return x->m > y->m ? -1 : 1; if (x->L != y->L) return x->L < y->L ? -1 : 1; return x->e < y->e ? -1 : (x->e > y->e); }
static int refresh_asc(const void *a, const void *b) { const refresh_item *x = a, *y = b; if (x->m != y->m) return x->m < y->m ? -1 : 1; if (x->L != y->L) return x->L < y->L ? -1 : 1; return x->e < y->e ? -1 : (x->e > y->e); }
static int refresh_swap_on(void) {
    if (refresh_swap_n < 0) {
        const char *e = getenv("LLMS_DS4_REFRESH_SWAP"); refresh_swap_n = e && atoi(e) > 0 ? atoi(e) : 0;
        const char *c = e ? strchr(e, ':') : NULL; if (c && atof(c + 1) > 0.0) refresh_swap_floor = (float)atof(c + 1);
        if (refresh_swap_n) {
            fprintf(stderr, "llms: refresh swap after %d listener cycles (layer-0 requests: verify steps and short appends; speculative rows included): the window's exact routing mass refits the cache once (non-residents with mass >= %.2f in, the lowest-mass residents out; one look-ahead slot, a demand on it waits) -- FIDELITY DIAL [LLMS_DS4_REFRESH_SWAP]\n",
                    refresh_swap_n, (double)refresh_swap_floor);
            atexit_b(^{ fprintf(stderr, "llms refresh swap: phase %d at exit, %u listener cycles, %llu rows summed (window requests by rows: 1 %llu, 2 %llu, 3-4 %llu, 5-8 %llu); the plan at cycle %u: %u swaps (window mass in %.1f, out %.1f; %u candidates >= %.2f, %u residents; %.2f ms); "
                                        "%llu batches issued (%llu experts requested) by cycle %u, %llu already resident, %llu in-flight skips, %llu not-now (no slot), %llu not issued, %llu begin failures, %llu residents demoted (%u unused); "
                                        "%llu refresh slots reaped: %llu experts installed, %llu install failures, %llu read failures; %llu demand waits (%.1f ms)\n",
                                refresh_phase, refresh_cycles, (unsigned long long)refresh_rows_summed, (unsigned long long)refresh_req_rows[0], (unsigned long long)refresh_req_rows[1], (unsigned long long)refresh_req_rows[2], (unsigned long long)refresh_req_rows[3], refresh_plan_cycle, refresh_n_swaps, refresh_mass_in, refresh_mass_out, refresh_n_cand, (double)refresh_swap_floor,
                                refresh_n_res, refresh_plan_ms, (unsigned long long)refresh_batches_issued, (unsigned long long)refresh_experts_requested, refresh_done_cycle, (unsigned long long)refresh_already_resident,
                                (unsigned long long)refresh_inflight_skips, (unsigned long long)refresh_not_now, (unsigned long long)refresh_not_issued, (unsigned long long)refresh_begin_failures,
                                (unsigned long long)refresh_demoted, refresh_demoted_unused, (unsigned long long)refresh_slots_reaped, (unsigned long long)refresh_experts_installed,
                                (unsigned long long)refresh_install_failures, (unsigned long long)refresh_read_failures, (unsigned long long)refresh_waits, refresh_wait_ms); });
        }
    }
    return refresh_swap_n > 0;
}
static void refresh_accumulate(const expert_request *q) {   /* the listener, before the policy: every row's six and weights as the router left them */
    const uint32_t L = q->layer, ns = q->n_selected, nt = q->n_tokens ? q->n_tokens : 1u;
    if (L >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER || ns == 0u || ns > 8u || nt > 8u || !q->selected || !q->wts) return;
    int32_t ids[64]; float w[64];
    if (!ds4_gpu_tensor_read(q->selected, 0, ids, (uint64_t)nt * ns * sizeof(int32_t)) || !ds4_gpu_tensor_read(q->wts, 0, w, (uint64_t)nt * ns * sizeof(float))) return;
    refresh_req_rows[nt == 1u ? 0 : nt == 2u ? 1 : nt <= 4u ? 2 : 3]++;
    for (uint32_t r = 0; r < nt; r++) {
        float s = 0.0f; for (uint32_t i = 0; i < ns; i++) s += w[r * ns + i];
        if (!(s > 0.0f)) continue;
        for (uint32_t i = 0; i < ns; i++) { const int32_t e = ids[r * ns + i]; if (e >= 0 && (uint32_t)e < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) refresh_mass[L][e] += w[r * ns + i] / s; }
        refresh_rows_summed++;
    }
}
static void refresh_plan(void) {   /* once, after a release: the global greedy swap over the window's mass */
    const double t0 = ds4_gpu_now_ms(); uint32_t nc = 0, nr = 0;
    for (uint32_t L = 0; L < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER; L++) {
        const int ready = L < 64u && __atomic_load_n(&lookahead_table_ready[L < 64u ? L : 63u], __ATOMIC_ACQUIRE);
        for (uint32_t e = 0; e < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT; e++) {
            const float mv = refresh_mass[L][e];
            if ((resident_bits[L][e >> 6] >> (e & 63u)) & 1ull) refresh_res[nr++] = (refresh_item){ mv, (uint16_t)L, (uint16_t)e };
            else if (ready && mv > 0.0f && mv >= refresh_swap_floor) refresh_cand[nc++] = (refresh_item){ mv, (uint16_t)L, (uint16_t)e };
        }
