    uint32_t j = 0; while (j < nc && j < nr && refresh_cand[j].m > refresh_res[j].m) { refresh_mass_in += refresh_cand[j].m; refresh_mass_out += refresh_res[j].m; j++; }
    refresh_n_swaps = j; refresh_n_cand = nc; refresh_n_res = nr; refresh_in_cursor = 0; refresh_out_cursor = 0; refresh_demoted_unused = 0; memset(refresh_in_done, 0, sizeof refresh_in_done);
    refresh_plan_ms = ds4_gpu_now_ms() - t0; refresh_plan_cycle = refresh_cycles;
    fprintf(stderr, "llms refresh swap: the plan at listener cycle %u: %u swaps (window mass in %.1f, out %.1f; %u candidates >= %.2f, %u residents; %.2f ms)\n",
            refresh_cycles, refresh_n_swaps, refresh_mass_in, refresh_mass_out, nc, (double)refresh_swap_floor, nr, refresh_plan_ms);
