static int encode_gpu_policy(uint32_t layer, const ds4_gpu_tensor *probs, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *wts, const float *bias,
                          id<MTLBuffer> ga, uint32_t n_total_expert, uint32_t n_selected, uint32_t n_tokens) {   /* -> the ring slot, or -1 */
    const uint32_t R = n_tokens ? n_tokens : 1u;
    if (g_metal_escalate || !gpu_policy_shadow_on() || !g_batch_cb || !probs || !selected || !wts || !bias || !ga || layer >= 64u || n_total_expert > 512u || n_selected > GPU_POLICY_K || R > GPU_POLICY_ROWS) return -1;
    if (!gpu_policy_bias_uploaded[layer]) { memcpy((float *)[gpu_policy_bias contents] + (size_t)layer * 512u, bias, n_total_expert * sizeof(float)); gpu_policy_bias_uploaded[layer] = 1; }
    const int slot = (int)(gpu_policy_next_slot++ % GPU_POLICY_RING);
    const NSUInteger so = (NSUInteger)slot * GPU_POLICY_ROWS * GPU_POLICY_K * 8u;
    ds4_gpu_close_batch_encoder();
    id<MTLComputeCommandEncoder> pe = ds4_gpu_compute_encoder(g_batch_cb);
    [pe setComputePipelineState:gpu_policy_pipeline];
    [pe setBuffer:ds4_gpu_tensor_buffer(probs) offset:ds4_gpu_tensor_offset(probs) atIndex:0];
    [pe setBuffer:gpu_policy_bias offset:(NSUInteger)layer * 512u * sizeof(float) atIndex:1];
    [pe setBuffer:ga offset:0 atIndex:2];
    [pe setBuffer:ds4_gpu_tensor_buffer(selected) offset:ds4_gpu_tensor_offset(selected) atIndex:3];
    [pe setBuffer:ds4_gpu_tensor_buffer(wts) offset:ds4_gpu_tensor_offset(wts) atIndex:4];
    [pe setBuffer:gpu_policy_ring offset:so atIndex:5];
    [pe setBuffer:gpu_policy_ring offset:so + (NSUInteger)GPU_POLICY_ROWS * GPU_POLICY_K * 4u atIndex:6];
    const float pf[4] = { resident_bonus_for_layer(layer) * cold_multiplier_now(), coroute_bonus(), 0.0f, 0.0f }; [pe setBytes:pf length:sizeof pf atIndex:7];
    const uint32_t pu[4] = { n_total_expert, n_selected, decode_keep_for_layer(layer), miss_split_count() }; [pe setBytes:pu length:sizeof pu atIndex:8];
    [pe setBytes:&R length:sizeof R atIndex:9];
    [pe setBuffer:miss_use_ring_heads offset:0 atIndex:10]; [pe setBuffer:miss_ring offset:0 atIndex:11]; [pe setBuffer:use_ring offset:0 atIndex:12];
    { const uint32_t lay = layer; [pe setBytes:&lay length:sizeof lay atIndex:13]; }
    [pe setBuffer:(call_up_table ? call_up_table : ga) offset:0 atIndex:14]; [pe setBuffer:(call_down_table ? call_down_table : ga) offset:0 atIndex:15];
    { const uint32_t lg0 = 0u; [pe setBuffer:miss_ring offset:0 atIndex:16]; [pe setBuffer:miss_ring offset:0 atIndex:17]; [pe setBuffer:miss_ring offset:0 atIndex:18]; [pe setBytes:&lg0 length:sizeof lg0 atIndex:19]; }   /* llms Z9 E: no lag in the shadow */
    { const uint32_t zt0 = 0u; [pe setBuffer:layer_kept_miss_marks offset:0 atIndex:20]; [pe setBytes:&zt0 length:sizeof zt0 atIndex:21]; } [pe setBuffer:miss_ring offset:0 atIndex:23];   /* llms GRES_MB: unused in the shadow */   /* llms Z9-S: no token in the shadow */
    bind_gpu_policy_params(pe); { const NSUInteger nt = gpu_policy_params_state > 0 ? 512u : 256u; [pe dispatchThreads:MTLSizeMake(nt, 1, 1) threadsPerThreadgroup:MTLSizeMake(nt, 1, 1)]; }   /* llms GRES_POL */
    ds4_gpu_close_batch_encoder(); gpu_policies_encoded++;
    return slot;
}
