            if (ok && use_packed_mpp)
                ok = ds4_gpu_encode_moe_packed_rhs(cb, &gate_mm_args,
                                                  xbuf, ds4_gpu_tensor_offset(x), false, packed_limit);
            DS4_METAL_PROFILE_MOE_STAGE("map");
            if (ok && use_mm_id_pair_swiglu) {
                ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                    .width = expert_mid_dim,
                    .rows = pair_rows,
                    .gate_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                    .up_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                    .mid_row_stride = (uint64_t)expert_mid_dim * sizeof(uint16_t),
                    .weight_stride = sizeof(float),
                    .write_clamped = 0,
                    .clamp_value = clamp,
                };
                ok = ds4_gpu_encode_mul_mm_id_iq2_pair_swiglu_f16(cb,
                                                                   pair_swiglu_mm_pipeline,
                                                                   use_mxfp4_mm_id_pair_swiglu_compact_tile,
                                                                   &gate_mm_args,
                                                                   &act_args,
                                                                   gate_buf,
                                                                   (NSUInteger)gate_inner,
                                                                   up_buf,
                                                                   (NSUInteger)up_inner,
                                                                   xbuf,
                                                                   ds4_gpu_tensor_offset(x),
                                                                   midbuf,
                                                                   ds4_gpu_tensor_offset(mid),
                                                                   weightsbuf,
                                                                   ds4_gpu_tensor_offset(weights));
                DS4_METAL_PROFILE_MOE_STAGE("gate_up_fused");
            } else if (ok) {
                ok = ds4_gpu_encode_mul_mm_id_mapped_tile_resources(cb,
                                                           gate_mm_pipeline,
                                                           &gate_mm_args,
                                                           use_iq2_cached_batch ? stream_gate_addr_buf : gate_buf,
                                                           (NSUInteger)gate_inner,
                                                           use_packed_mpp ? g_moe_packed_rhs_buffer : xbuf,
                                                           use_packed_mpp ? 0 : ds4_gpu_tensor_offset(x),
                                                           gatebuf,
                                                           ds4_gpu_tensor_offset(gate),
                                                           packed_m32n128 ? 16384u : mm_id_mpp_active ? 12288u : 8192u,
                                                           use_iq2_cached_batch ? stream_resources : NULL,
                                                           stream_resource_count, 0, stream_overflow_gate,
                                                           packed_m32n128 ? 32u : 64u);
                DS4_METAL_PROFILE_MOE_STAGE("gate");
            }
            if (ok && !use_mm_id_pair_swiglu) {
                ok = ds4_gpu_encode_mul_mm_id_mapped_tile_resources(cb,
                                                   up_mm_pipeline,
                                                   &gate_mm_args,
                                                   use_iq2_cached_batch ? stream_up_addr_buf : up_buf,
                                                   (NSUInteger)up_inner,
                                                   use_packed_mpp ? g_moe_packed_rhs_buffer : xbuf,
                                                   use_packed_mpp ? 0 : ds4_gpu_tensor_offset(x),
                                                   upbuf,
                                                   ds4_gpu_tensor_offset(up),
                                                   packed_m32n128 ? 16384u : mm_id_mpp_active ? 12288u : 8192u,
                                                   use_iq2_cached_batch ? stream_resources : NULL,
                                                   stream_resource_count, 1, stream_overflow_up,
                                                   packed_m32n128 ? 32u : 64u);
                DS4_METAL_PROFILE_MOE_STAGE("up");
            }
        } else if (use_iq2_cached_batch && use_tiny_pair_swiglu) {
            ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                .width = expert_mid_dim, .rows = pair_rows,
                .gate_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .up_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .mid_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .weight_stride = sizeof(float), .clamp_value = clamp,
            };
            ok = ds4_gpu_encode_routed_gateup_swiglu(cb,
                g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_pipeline, &gate_args, &act_args,
                stream_resources, stream_resource_count, stream_gate_addr_buf, stream_up_addr_buf,
                xbuf, ds4_gpu_tensor_offset(x), gatebuf, ds4_gpu_tensor_offset(gate),
                upbuf, ds4_gpu_tensor_offset(up), midbuf, ds4_gpu_tensor_offset(mid),
                selectedbuf, ds4_gpu_tensor_offset(selected), weightsbuf, ds4_gpu_tensor_offset(weights),
                gate_smem, 2, false, stream_overflow_gate, stream_overflow_up);
        } else if (use_iq2_cached_batch) {
            ok = ds4_gpu_encode_mul_mv_addr_iq2(cb,
                g_moe_mul_mv_addr_iq2_xxs_pipeline, &gate_args,
                stream_resources, stream_resource_count, stream_gate_addr_buf,
                xbuf, ds4_gpu_tensor_offset(x), gatebuf, ds4_gpu_tensor_offset(gate),
                selectedbuf, ds4_gpu_tensor_offset(selected), gate_smem, gate_nsg,
                gate_rows_per_group_is_nr0, 0, stream_overflow_gate) &&
                 ds4_gpu_encode_mul_mv_addr_iq2(cb,
                g_moe_mul_mv_addr_iq2_xxs_pipeline, &gate_args,
                stream_resources, stream_resource_count, stream_up_addr_buf,
                xbuf, ds4_gpu_tensor_offset(x), upbuf, ds4_gpu_tensor_offset(up),
                selectedbuf, ds4_gpu_tensor_offset(selected), gate_smem, gate_nsg,
                gate_rows_per_group_is_nr0, 1, stream_overflow_up);
        } else if (use_tiny_pair_swiglu) {
            ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                .width = expert_mid_dim,
                .rows = pair_rows,
                .gate_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .up_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .mid_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .weight_stride = sizeof(float),
                .write_clamped = 0,
                .clamp_value = clamp,
            };
            ok = ds4_gpu_encode_mul_mv_id_pair_swiglu(cb,
                                                       tiny_pair_swiglu_pipeline,
                                                       &gate_args,
                                                       &act_args,
                                                       gate_buf,
                                                       (NSUInteger)gate_inner,
                                                       up_buf,
                                                       (NSUInteger)up_inner,
                                                       xbuf,
                                                       ds4_gpu_tensor_offset(x),
                                                       gatebuf,
                                                       ds4_gpu_tensor_offset(gate),
                                                       upbuf,
                                                       ds4_gpu_tensor_offset(up),
                                                       midbuf,
                                                       ds4_gpu_tensor_offset(mid),
                                                       selectedbuf,
                                                       ds4_gpu_tensor_offset(selected),
                                                       weightsbuf,
                                                       ds4_gpu_tensor_offset(weights),
                                                       gate_smem,
                                                       use_tp_mxfp4_static_batch ? 1 : 2,
                                                       false);
        } else if (use_tiny_pair_mv) {
            id<MTLComputePipelineState> pair_pipeline =
                gate_type == DS4_METAL_TENSOR_IQ2_XXS ?
                    g_moe_mul_mv_id_iq2_xxs_pair_pipeline :
                    g_moe_mul_mv_id_q4_k_pair_pipeline;
            ok = ds4_gpu_encode_mul_mv_id_pair(cb,
                                                 pair_pipeline,
                                                 &gate_args,
                                                 gate_buf,
                                                 (NSUInteger)gate_inner,
                                                 up_buf,
                                                 (NSUInteger)up_inner,
                                                 xbuf,
                                                 ds4_gpu_tensor_offset(x),
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 gate_smem,
                                                 2,
                                                 false);
        } else {
            ok = ds4_gpu_encode_mul_mv_id(cb,
                                                  gate_mv_pipeline,
                                                  &gate_args,
                                                  gate_buf,
                                                  (NSUInteger)gate_inner,
                                                  xbuf,
                                                  ds4_gpu_tensor_offset(x),
                                                  gatebuf,
                                                  ds4_gpu_tensor_offset(gate),
                                                  selectedbuf,
                                                  ds4_gpu_tensor_offset(selected),
                                                  gate_smem,
                                                  gate_nsg,
                                                  gate_rows_per_group_is_nr0) &&
                 ds4_gpu_encode_mul_mv_id(cb,
                                                  gate_mv_pipeline,
                                                  &gate_args,
                                                  up_buf,
                                                  (NSUInteger)up_inner,
                                                  xbuf,
                                                  ds4_gpu_tensor_offset(x),
                                                  upbuf,
                                                  ds4_gpu_tensor_offset(up),
                                                  selectedbuf,
                                                  ds4_gpu_tensor_offset(selected),
                                                  gate_smem,
                                                  gate_nsg,
                                                  gate_rows_per_group_is_nr0);
        }
        DS4_METAL_PROFILE_MOE_STAGE("gate_up");
        const bool use_fused_activation = !g_quality_mode && !use_q4_batch_expert_table;
        const bool use_mid_f16 =
            use_mm_id &&
            use_fused_activation &&
            request_mid_f16;
        if (mid_is_f16) *mid_is_f16 = use_mid_f16;
        if (ok && use_iq2_batch_selected_addr) {
            /* The address-table pair kernel already wrote weighted SwiGLU rows into mid. */
        } else if (ok && use_q4_batch_expert_table) {
            /* The table pair kernel already wrote weighted SwiGLU rows into mid. */
        } else if (ok && use_mm_id_pair_swiglu) {
            /* The fused batch mm_id pair kernel already wrote weighted f16 SwiGLU rows into mid. */
        } else if (ok && use_tiny_pair_swiglu) {
            /* The fused tiny pair kernel already wrote weighted F32 SwiGLU rows into mid. */
        } else if (ok && use_fused_activation) {
            ok = ds4_gpu_encode_moe_swiglu_weight(cb,
                                                    gatebuf,
                                                    ds4_gpu_tensor_offset(gate),
                                                    upbuf,
                                                    ds4_gpu_tensor_offset(up),
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    weightsbuf,
                                                    ds4_gpu_tensor_offset(weights),
                                                    expert_mid_dim,
                                                    pair_rows,
                                                    clamp,
                                                    use_mid_f16);
        } else if (ok && clamp > 1.0e-6f) {
            ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                 g_unary_clamp_pipeline,
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 expert_mid_dim,
                                                 pair_rows,
                                                 0,
                                                 -FLT_MAX,
                                                 clamp);
            if (ok) {
                ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                     g_unary_silu_pipeline,
                                                     gatebuf,
                                                     ds4_gpu_tensor_offset(gate),
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     expert_mid_dim,
                                                     pair_rows,
                                                     1,
                                                     0.0f,
                                                     0.0f);
            }
            if (ok) {
                ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                 g_unary_clamp_pipeline,
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 expert_mid_dim,
                                                 pair_rows,
                                                 0,
                                                 -clamp,
                                                 clamp);
            }
            if (ok) {
                ds4_gpu_bin_args mul_args =
                    ds4_gpu_make_bin_same_rows_args(expert_mid_dim, pair_rows);
                ok = ds4_gpu_encode_bin_f32_rows(cb,
                                                   g_mul_pipeline,
                                                   &mul_args,
                                                   midbuf,
                                                   ds4_gpu_tensor_offset(mid),
                                                   upbuf,
                                                   ds4_gpu_tensor_offset(up),
                                                   midbuf,
                                                   ds4_gpu_tensor_offset(mid));
            }
        } else if (ok) {
            ok = ds4_gpu_encode_swiglu_flat(cb,
                                              gatebuf,
                                              ds4_gpu_tensor_offset(gate),
                                              upbuf,
                                              ds4_gpu_tensor_offset(up),
                                              midbuf,
                                              ds4_gpu_tensor_offset(mid),
                                              (uint32_t)((uint64_t)pair_rows * expert_mid_dim));
        }
        if (ok && !use_fused_activation && !use_q4_batch_expert_table) {
            ds4_gpu_bin_args weight_args =
                ds4_gpu_make_bin_rowwise_scalar_args(expert_mid_dim, pair_rows);
            ok = ds4_gpu_encode_bin_f32_rows(cb,
                                               g_bin_mul_scalar_pipeline,
                                               &weight_args,
                                               midbuf,
                                               ds4_gpu_tensor_offset(mid),
                                               weightsbuf,
                                               ds4_gpu_tensor_offset(weights),
                                               midbuf,
                                               ds4_gpu_tensor_offset(mid));
        }
        DS4_METAL_PROFILE_MOE_STAGE("activation_weight");

        id<MTLBuffer> down_dst = n_expert == 1 ? outbuf : (expertsbuf ? expertsbuf : g_moe_down_scratch_buffer);
        NSUInteger down_dst_off = n_expert == 1 ? ds4_gpu_tensor_offset(out) :
            (expertsbuf ? ds4_gpu_tensor_offset(experts) : 0);
        if (ok) {
            if (use_iq2_batch_selected_addr) {
                if (clean_down_this_layer && down_tiles_this_layer && dirty_tokens_count > 0) {   /* llms DOWN_T8: pass 1's tiles (if not yet run) and pass 2's, before the dirty tokens' down */
                    if (!down_tiles_pass1_done && down_tile_pass1_count) { ok = encode_down_tiles(cb, &down_args, stream_resources, stream_resource_count, stream_down_addr_buf, midbuf, ds4_gpu_tensor_offset(mid),
                            selectedbuf, ds4_gpu_tensor_offset(selected), down_tile_pass1_offset, down_tile_pass1_count, 0, stream_overflow_down); down_tiles_pass1_done = 1; }
                    if (ok && down_tile_pass2_count && down_t8_mode() > 0) ok = encode_down_tiles(cb, &down_args, stream_resources, stream_resource_count, stream_down_addr_buf, midbuf, ds4_gpu_tensor_offset(mid),
                            selectedbuf, ds4_gpu_tensor_offset(selected), down_tile_pass2_offset, down_tile_pass2_count, down_tile_pass1_count, stream_overflow_down);
                    if (!ok) { fprintf(stderr, "llms down t8: pass-2 tiles failed layer %u\n", layer_index); return 0; }
                }
                {   /* llms PATH_LOG (apply_path_log.py): which path this layer-call took */
                    static FILE *path_log_file = (FILE *)1; static uint64_t path_log_lines;
                    if (path_log_file == (FILE *)1) { const char *e = getenv("LLMS_DS4_PATH_LOG"); path_log_file = e && *e ? fopen(e, "w") : NULL; }
                    if (path_log_file) { fprintf(path_log_file, "%llu %u %u splits %llu tok %d t8 %d k1 %u k2 %u dirty %u\n", (unsigned long long)path_log_lines++, layer_index, n_tokens, (unsigned long long)split_pass1_calls, clean_down_this_layer,   /* splits: the running count of split layer-calls (the local flag is out of scope here) */
                                      down_tiles_this_layer, down_tile_pass1_count, down_tile_pass2_count, clean_down_this_layer ? dirty_tokens_count : 0u); fflush(path_log_file); }
                }
                if (clean_down_this_layer) {   /* llms CLEAN_DOWN: the clean tokens' projection ran in the pass-1 buffer */
                    clean_down_this_layer = 0;
                    ok = dirty_tokens_count == 0 ? 1 : encode_down_by_token(cb, &down_args, stream_resources, stream_resource_count, stream_down_addr_buf, midbuf, ds4_gpu_tensor_offset(mid),
                            outbuf, ds4_gpu_tensor_offset(out), selectedbuf, ds4_gpu_tensor_offset(selected), down_smem, 2, stream_overflow_down, dirty_tokens_offset, dirty_tokens_count);
                } else
                ok = ds4_gpu_encode_mul_mv_addr_q2_sum6(
                        cb,
                        g_moe_mul_mv_addr_q2_k_sum6_pipeline,
                        &down_args,
                        stream_resources,
                        stream_resource_count,
                        stream_down_addr_buf,
                        midbuf,
                        ds4_gpu_tensor_offset(mid),
                        outbuf,
                        ds4_gpu_tensor_offset(out),
                        selectedbuf,
                        ds4_gpu_tensor_offset(selected),
                        down_smem,
                        2,
                        stream_overflow_down);
                peeked_call_open = 0;
                down_tiles_this_layer = 0; down_tiles_pass1_done = 0;   /* llms DOWN_T8 (apply_down_t8_fix.py): cleared after the layer's down, not before */
                if (!ok) {
                    fprintf(stderr,
                            "ds4: Metal streaming prefill batch selected addr layer=%u "
                            "failed to encode down path tokens=%u unique=%u\n",
                            layer_index,
                            n_tokens,
                            stream_unique);
                }
            } else if (use_q4_batch_expert_table) {
                ok = ds4_gpu_encode_mul_mv_table_q4_sum6(cb,
                                                         g_moe_mul_mv_table_q4_k_sum6_pipeline,
                                                         &down_args,
                                                         down_table,
                                                         midbuf,
                                                         ds4_gpu_tensor_offset(mid),
                                                         outbuf,
                                                         ds4_gpu_tensor_offset(out),
                                                         selectedbuf,
                                                         ds4_gpu_tensor_offset(selected),
                                                         down_smem,
                                                         2,
                                                         q4_batch_table_queue_residency);
            } else if (direct_down_sum) {
                ok = ds4_gpu_encode_mul_mv_id_sum6(cb,
                                                     down_sum6_pipeline,
                                                     &down_args,
                                                     down_buf,
                                                     (NSUInteger)down_inner,
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     outbuf,
                                                     ds4_gpu_tensor_offset(out),
                                                     selectedbuf,
                                                     ds4_gpu_tensor_offset(selected),
                                                     nil,
                                                     0,
                                                     down_smem,
                                                     use_tp_mxfp4_static_batch ? 1 : 2);
            } else if (use_mm_id) {
                if (use_packed_mpp)
                    ok = ds4_gpu_encode_moe_packed_rhs(cb, &down_mm_args,
                                                      midbuf, ds4_gpu_tensor_offset(mid), true, packed_limit);
                if (ok) ok = ds4_gpu_encode_mul_mm_id_mapped_tile_resources(cb,
                                                       down_mm_pipeline,
                                                       &down_mm_args,
                                                       use_iq2_cached_batch ? stream_down_addr_buf : down_buf,
                                                       (NSUInteger)down_inner,
                                                       use_packed_mpp ? g_moe_packed_rhs_buffer : midbuf,
                                                       use_packed_mpp ? 0 : ds4_gpu_tensor_offset(mid),
                                                       down_dst,
                                                       down_dst_off,
                                                       packed_m32n128 ? 16384u : mm_id_mpp_active ? 12288u : 8192u,
                                                       use_iq2_cached_batch ? stream_resources : NULL,
                                                       stream_resource_count, 2, stream_overflow_down,
                                                       packed_m32n128 ? 32u : 64u);
            } else if (use_iq2_cached_batch) {
                ok = ds4_gpu_encode_mul_mv_addr_iq2(cb,
                    g_moe_mul_mv_addr_iq2_xxs_pipeline, &down_args,
                    stream_resources, stream_resource_count, stream_down_addr_buf,
                    midbuf, ds4_gpu_tensor_offset(mid), down_dst, down_dst_off,
                    selectedbuf, ds4_gpu_tensor_offset(selected), down_smem, down_nsg,
                    down_rows_per_group_is_nr0, 2, stream_overflow_down);
            } else {
                ok = ds4_gpu_encode_mul_mv_id(cb,
                                                     down_mv_pipeline,
                                                     &down_args,
                                                     down_buf,
                                                     (NSUInteger)down_inner,
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     down_dst,
                                                     down_dst_off,
                                                     selectedbuf,
                                                     ds4_gpu_tensor_offset(selected),
                                                     down_smem,
                                                     down_nsg,
                                                     down_rows_per_group_is_nr0);
            }
        }
        DS4_METAL_PROFILE_MOE_STAGE("down");
        if (ok &&
            n_expert > 1 &&
            !direct_down_sum &&
            !use_q4_batch_expert_table &&
            !use_iq2_batch_selected_addr) {
            ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                       down_dst,
                                                       down_dst_off,
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       out_dim,
                                                       n_expert,
                                                       n_tokens);
        }
        DS4_METAL_PROFILE_MOE_STAGE("sum");
        if (!ok) {
            fprintf(stderr,
                    "ds4: Metal routed batch MoE failed before submit layer=%u tokens=%u "
                    "gate=%s down=%s path=%s\n",
                    layer_index,
                    n_tokens,
                    ds4_gpu_metal_tensor_type_name(gate_type),
                    ds4_gpu_metal_tensor_type_name(down_type),
                    moe_path);
            { fprintf(stderr, "llms rmb ret 44706\n"); return 0; }
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "routed batch MoE")) {
            if (use_cached_batch) {
                ds4_gpu_stream_expert_cache_clear_layer(layer_index);
            }
            { fprintf(stderr, "llms rmb ret 44713\n"); return 0; }
        }
        /* llms NOPOSTWAIT (2026-10-13 10:2x; adopted, the switch removed 10-27; x294: the one-token path waited for every MoE to finish before reopening --
             the third waited sync per layer; the next readback (sync) or the listener order (ED) already keeps evicted slots unread) */
        if (use_cached_batch && (batch_pipe_on || event_driven_call_open || sp_no_post_wait || n_tokens == 1) && !owned) {   /* llms SP_NPW */   /* llms BATCH_PIPE: keep the batch open; guard the union slots instead; llms ED v6 / NOPOSTWAIT: the same for one-token calls */
            if (stream_resource_count &&
                !ds4_gpu_stream_expert_cache_mark_entries_inflight(stream_resources, stream_resource_count, 0)) {
                fprintf(stderr, "llms rmb pipe mark-inflight failed layer=%u\n", layer_index); return 0;
            }
        } else if (use_cached_batch) {
            if (!owned) {
                if (ds4_gpu_end_commands() == 0) {
                    ds4_gpu_stream_expert_cache_clear_layer(layer_index);
                    { fprintf(stderr, "llms rmb ret 44719\n"); return 0; }
                }
                if (ds4_gpu_begin_commands() == 0) {
                    fprintf(stderr,
                            "ds4: Metal streaming prefill batch selected addr layer=%u "
                            "failed to reopen command batch after execution\n",
                            layer_index);
                    { fprintf(stderr, "llms rmb ret 44726\n"); return 0; }
                }
            }
        }
        if (q4_batch_table_boundary) {
            if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
                { fprintf(stderr, "llms rmb ret 44732\n"); return 0; }
            }
        }
#undef DS4_METAL_PROFILE_MOE_STAGE
    }

    return 1;
}

int ds4_gpu_hc_split_sinkhorn_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *mix,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n_hc == 0 || n_hc > 16) return 0;
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t scale_bytes = 3ull * sizeof(float);

    @autoreleasepool {
        id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t mix_tensor_bytes = ds4_gpu_tensor_bytes(mix);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (!mixbuf || !outbuf ||
            mix_tensor_bytes < mix_bytes ||
            out_tensor_bytes < mix_bytes) {
            fprintf(stderr, "ds4: Metal HC split received undersized activation buffers\n");
            return 0;
        }
        if (scale_offset > model_size || scale_bytes > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset) {
            fprintf(stderr, "ds4: Metal HC split parameter range is outside the mapped model\n");
            return 0;
        }

        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
        if (!scalebuf || !basebuf) return 0;

        uint64_t n_rows64 = mix_tensor_bytes / mix_bytes;
        const uint64_t out_rows64 = out_tensor_bytes / mix_bytes;
        if (out_rows64 < n_rows64) n_rows64 = out_rows64;
        if (n_rows64 == 0 || n_rows64 > UINT32_MAX) {
            fprintf(stderr, "ds4: Metal HC split row count is outside supported range\n");
            return 0;
        }

        ds4_gpu_hc_split_args args = {
            .n_hc = (int32_t)n_hc,
            .sinkhorn_iters = (int32_t)sinkhorn_iters,
            .n_rows = (int64_t)n_rows64,
            .mix_hc = (int64_t)mix_hc,
            .nb01 = mix_bytes,
            .nb1 = mix_bytes,
            .eps = eps,
        };
        const NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_rows64));
        const NSUInteger n_tg = ((NSUInteger)n_rows64 + nth - 1u) / nth;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_hc_split_sinkhorn_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:4];
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sinkhorn")) return 0;
    }

    return 1;
}

/* llms HC_VEC (apply_ds4_hc_vec.py; adopted, the switch removed 10-27): float4 HC weighted sum / expand, whenever the HC source is an *llms12* one (ALT hcv) */
static int hc_vec_on(void) {
    static int on = -2;
    if (on < -1) { const char *src = getenv("DS4_METAL_DSV4_HC_SOURCE"); on = src && llms_srckey(src, "llms12") != NULL; }
    return on;
}
/* llms HC_BF16 (apply_ds4_hc_bf16.py; adopted, the switch removed 10-27): HC_VEC outputs rounded to BF16 in the store; the BF16 pass on exactly that range,
 * with no compute encoder requested in between, is skipped; whenever the HC source is an *llms20* one (ALT hcb) */
static int hc_bf16_state = -2; static uint64_t hc_bf16_marked_at_op = UINT64_MAX;
static id<MTLBuffer> hc_bf16_marked_buffer; static NSUInteger hc_bf16_marked_offset, hc_bf16_marked_bytes;
static int hc_bf16_on(void) {
    if (hc_bf16_state == -2) { const char *src = getenv("DS4_METAL_DSV4_HC_SOURCE"); hc_bf16_state = src && llms_srckey(src, "llms20") != NULL; }
    return hc_bf16_state;
}
static void mark_hc_bf16_range(id<MTLBuffer> b, NSUInteger off, NSUInteger bytes) { hc_bf16_marked_buffer = b; hc_bf16_marked_offset = off; hc_bf16_marked_bytes = bytes; hc_bf16_marked_at_op = ops_counted; }
static int ds4_gpu_hc_weighted_sum_strided(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *weights,
        uint64_t                weight_offset,
        uint64_t                weight_row_stride,
        uint32_t                n_embd,
        uint32_t                n_hc,
        const char             *label) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !residual_hc || !weights || n_embd == 0 || n_hc == 0 ||
        weight_row_stride < (uint64_t)n_hc * sizeof(float)) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> wbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes || out_tensor_bytes % out_row_bytes != 0) {
            fprintf(stderr, "ds4: Metal HC weighted sum output size is not a whole token row\n");
            return 0;
        }

        const uint64_t n_tokens64 = out_tensor_bytes / out_row_bytes;
        if (n_tokens64 == 0 || n_tokens64 > UINT32_MAX) {
            fprintf(stderr, "ds4: Metal HC weighted sum token count is outside supported range\n");
            return 0;
        }

        const uint64_t x_row_values = (uint64_t)n_hc * n_embd;
        if (x_row_values == 0 ||
            x_row_values > UINT64_MAX / sizeof(float) ||
            n_tokens64 > UINT64_MAX / (x_row_values * sizeof(float)) ||
            n_tokens64 > UINT64_MAX / ((uint64_t)n_hc * sizeof(float))) {
            fprintf(stderr, "ds4: Metal HC weighted sum activation size overflow\n");
            return 0;
        }

        const uint64_t x_bytes = n_tokens64 * x_row_values * sizeof(float);
        const uint64_t w_last = weight_offset +
                                (n_tokens64 - 1u) * weight_row_stride +
                                (uint64_t)n_hc * sizeof(float);
        if (!xbuf || !wbuf || !outbuf ||
            ds4_gpu_tensor_bytes(residual_hc) < x_bytes ||
            ds4_gpu_tensor_bytes(weights) < w_last) {
            fprintf(stderr, "ds4: Metal HC weighted sum received undersized activation buffers\n");
            return 0;
        }

        ds4_gpu_hc_weighted_sum_args args = {
            .n_embd = n_embd,
            .n_hc = n_hc,
            .n_tokens = (int64_t)n_tokens64,
            .nb_x0 = sizeof(float),
            .nb_x1 = (uint64_t)n_embd * sizeof(float),
            .nb_x2 = (uint64_t)n_hc * n_embd * sizeof(float),
            .nb_w0 = sizeof(float),
            .nb_w1 = weight_row_stride,
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)n_embd * sizeof(float),
        };
        const uint64_t n_elem = (uint64_t)n_embd * n_tokens64;
        const NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_elem));
        const NSUInteger n_tg = ((NSUInteger)n_elem + nth - 1u) / nth;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        id<MTLComputePipelineState> weighted_sum_pipeline = g_hc_weighted_sum_pipeline;   /* llms HC_VEC */
        NSUInteger weighted_sum_groups = n_tg, weighted_sum_threads = nth;
        if (hc_vec_on() && !llms_alt_off("hcv") && (n_embd % 4u) == 0) {
            static id<MTLComputePipelineState> weighted_sum_vec_pipeline; if (!weighted_sum_vec_pipeline) weighted_sum_vec_pipeline = ds4_gpu_get_pipeline_or_die("kernel_llms_hc_weighted_sum_v4");
            if (weighted_sum_vec_pipeline) { const uint64_t n4 = n_elem / 4u; weighted_sum_pipeline = weighted_sum_vec_pipeline; weighted_sum_threads = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n4));
                           weighted_sum_groups = ((NSUInteger)n4 + weighted_sum_threads - 1u) / weighted_sum_threads; }
        }
        bool hc_bf16_in_weighted_sum = false;   /* llms HC_BF16 */
        if (weighted_sum_pipeline != g_hc_weighted_sum_pipeline && hc_bf16_on() && !llms_alt_off("hcb")) {
            static id<MTLComputePipelineState> weighted_sum_bf16_pipeline; if (!weighted_sum_bf16_pipeline) weighted_sum_bf16_pipeline = ds4_gpu_get_pipeline_or_die("kernel_llms_hc_weighted_sum_v4b");
            if (weighted_sum_bf16_pipeline) { weighted_sum_pipeline = weighted_sum_bf16_pipeline; hc_bf16_in_weighted_sum = true; }
        }
        [enc setComputePipelineState:weighted_sum_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:1];
        [enc setBuffer:wbuf offset:ds4_gpu_tensor_offset(weights) + (NSUInteger)weight_offset atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc dispatchThreadgroups:MTLSizeMake(weighted_sum_groups, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(weighted_sum_threads, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (hc_bf16_in_weighted_sum) mark_hc_bf16_range(outbuf, (NSUInteger)ds4_gpu_tensor_offset(out), (NSUInteger)n_elem * sizeof(float));   /* llms HC_BF16 */

        if (!ds4_gpu_finish_command_buffer(cb, owned, label)) return 0;
    }

    return 1;
}

int ds4_gpu_hc_weighted_sum_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *weights,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    return ds4_gpu_hc_weighted_sum_strided(out,
                                             residual_hc,
                                             weights,
                                             0,
                                             (uint64_t)n_hc * sizeof(float),
                                             n_embd,
                                             n_hc,
                                             "HC weighted sum");
}

/* llms HC_FUSE1 (apply_hc_fuse.py): the one-token HC pre-sublayer in one dispatch (kernel_llms_hc_pre_fused) */
static uint64_t hc_fuse1_calls;
int ds4_gpu_llms_hc_pre_fused(ds4_gpu_tensor *split, ds4_gpu_tensor *xo, ds4_gpu_tensor *no, const ds4_gpu_tensor *residual,
                              const ds4_gpu_tensor *pre, ds4_gpu_tensor *mixo, const void *model_map, uint64_t model_size, uint64_t fn_off, uint64_t scale_off,
                              uint64_t base_off, uint64_t nw_off, uint32_t n_embd, uint32_t n_hc, uint32_t iters, float rms_eps, float hc_eps, int canary) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n_hc != 4u || (n_embd % 4u) != 0) return 0;
    @autoreleasepool {
        static id<MTLComputePipelineState> p; static id<MTLBuffer> scr;
        if (!p) { p = ds4_gpu_get_pipeline_or_die("kernel_llms_hc_pre_fused");
                  if (!p) { fprintf(stderr, "llms: kernel_llms_hc_pre_fused missing (DS4_METAL_DSV4_HC_SOURCE must name the *_hcf source)\n"); return 0; }
                  if (p.maxTotalThreadsPerThreadgroup < 1024) { fprintf(stderr, "llms: hc fuse needs 1024 threads per threadgroup, the pipeline allows %lu\n", (unsigned long)p.maxTotalThreadsPerThreadgroup); return 0; }
                  atexit_b(^{ fprintf(stderr, "llms hc fuse1: %llu fused HC pre-sublayers\n", (unsigned long long)hc_fuse1_calls); }); }
        if (!scr) { scr = [g_device newBufferWithLength:32u * sizeof(uint32_t) options:MTLResourceStorageModeShared]; if (!scr) return 0; memset([scr contents], 0, 32u * sizeof(uint32_t)); }
        const uint64_t n = (uint64_t)n_hc * n_embd;
        uint64_t fi = 0, si = 0, bi = 0, wi = 0;
        id<MTLBuffer> fb = ds4_gpu_wrap_model_range(model_map, model_size, fn_off, 24u * n * 2u, &fi);
        id<MTLBuffer> sb = ds4_gpu_wrap_model_range(model_map, model_size, scale_off, 3u * sizeof(float), &si);
        id<MTLBuffer> bb = ds4_gpu_wrap_model_range(model_map, model_size, base_off, 24u * sizeof(float), &bi);
        id<MTLBuffer> wb = ds4_gpu_wrap_model_range(model_map, model_size, nw_off, (uint64_t)n_embd * sizeof(float), &wi);
        if (!fb || !sb || !bb || !wb) return 0;
        struct { int32_t n_embd, n_hc, iters; float rms_eps, hc_eps; int32_t canary; } a = { (int32_t)n_embd, (int32_t)n_hc, (int32_t)iters, rms_eps, hc_eps, canary };
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:p];
        [enc setBytes:&a length:sizeof(a) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(residual) offset:ds4_gpu_tensor_offset(residual) atIndex:1];
        [enc setBuffer:fb offset:(NSUInteger)fi atIndex:2];
        [enc setBuffer:sb offset:(NSUInteger)si atIndex:3];
        [enc setBuffer:bb offset:(NSUInteger)bi atIndex:4];
        [enc setBuffer:ds4_gpu_tensor_buffer(pre) offset:ds4_gpu_tensor_offset(pre) atIndex:5];
        [enc setBuffer:wb offset:(NSUInteger)wi atIndex:6];
        [enc setBuffer:ds4_gpu_tensor_buffer(split) offset:ds4_gpu_tensor_offset(split) atIndex:7];
        [enc setBuffer:ds4_gpu_tensor_buffer(xo) offset:ds4_gpu_tensor_offset(xo) atIndex:8];
        [enc setBuffer:ds4_gpu_tensor_buffer(no) offset:ds4_gpu_tensor_offset(no) atIndex:9];
        [enc setBuffer:scr offset:0 atIndex:10];
        [enc setBuffer:ds4_gpu_tensor_buffer(mixo) offset:ds4_gpu_tensor_offset(mixo) atIndex:11];
        [enc setThreadgroupMemoryLength:((NSUInteger)n_embd + 96u) * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(25, 1, 1) threadsPerThreadgroup:MTLSizeMake((canary & 4) ? 256 : 1024, 1, 1)];   /* bit 2: 256 threads (HC_FUSE1=3) */
        ds4_gpu_end_compute_encoder(cb, enc);
        hc_fuse1_calls++;
        return ds4_gpu_finish_command_buffer(cb, owned, "llms HC fused pre") ? 1 : 0;
    }
}

/* llms HCF_ROWS (apply_hcf_rows.py): HC_FUSE1's pre-sublayer kernel over 2-4 rows, exact mode (the split runs after) */
static uint64_t hc_fuse_rows_calls;
/* llms HC_FUSEQ (apply_hcq.py): the two-row FFN-side HC transition fused -- expand + x + both norms' partials (8 threadgroups per row) then the norm apply; the flat-norm scale parked in mix[row][0] for the carried mixer */
int ds4_gpu_llms_hcq(ds4_gpu_tensor *hout, const ds4_gpu_tensor *block, const ds4_gpu_tensor *residual, const ds4_gpu_tensor *cur, const ds4_gpu_tensor *pre,
                     ds4_gpu_tensor *xo, ds4_gpu_tensor *no, ds4_gpu_tensor *mixo, const void *model_map, uint64_t model_size, uint64_t nw_off,
                     uint32_t n_embd, float rms_eps, int canary, uint32_t rows) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if ((rows != 2u && !(rows == 3u && k3hc_mode()) && !(rows == 4u && k4x_on())) || n_embd != 5120u) return 0;   /* llms K4X */   /* llms K3HC */
    @autoreleasepool {
        static id<MTLComputePipelineState> pq, pa; static id<MTLBuffer> scr, scx; static int tried; static uint64_t calls;
        if (!tried) { tried = 1; pq = ds4_gpu_get_pipeline_or_die("kernel_llms_hcq_fused2"); pa = ds4_gpu_get_pipeline_or_die("kernel_llms_hcq_apply");
                      scr = [g_device newBufferWithLength:4u * 128u * sizeof(uint32_t) options:MTLResourceStorageModeShared]; if (scr) memset(scr.contents, 0, 4u * 128u * sizeof(uint32_t));   /* llms K3HC: 4 rows (was 2) */
                      scx = [g_device newBufferWithLength:4u * sizeof(float) options:MTLResourceStorageModePrivate];
                      if (!pq || !pa) fprintf(stderr, "llms hc fuseq: kernels missing (DS4_METAL_DSV4_HC_SOURCE) -- off\n");
                      else atexit_b(^{ fprintf(stderr, "llms hc fuseq: %llu fused two-row HC transitions\n", (unsigned long long)calls); }); }
        if (!pq || !pa || !scr || !scx) return 0;
        uint64_t wi = 0; id<MTLBuffer> wb = ds4_gpu_wrap_model_range(model_map, model_size, nw_off, (uint64_t)n_embd * sizeof(float), &wi);
        if (!wb) return 0;
        struct { int32_t n_embd, n_hc, iters; float rms_eps, hc_eps; int32_t canary; } a = { (int32_t)n_embd, 4, 0, rms_eps, 0.0f, canary ? 99 : 2 };
        const uint32_t ps = 24u;
        int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned); if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pq]; [enc setBytes:&a length:sizeof a atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(block) offset:ds4_gpu_tensor_offset(block) atIndex:1];
        [enc setBuffer:ds4_gpu_tensor_buffer(residual) offset:ds4_gpu_tensor_offset(residual) atIndex:2];
        [enc setBuffer:ds4_gpu_tensor_buffer(cur) offset:ds4_gpu_tensor_offset(cur) atIndex:3];
        [enc setBuffer:ds4_gpu_tensor_buffer(pre) offset:ds4_gpu_tensor_offset(pre) atIndex:4];
        [enc setBuffer:scr offset:0 atIndex:5];
        [enc setBuffer:ds4_gpu_tensor_buffer(hout) offset:ds4_gpu_tensor_offset(hout) atIndex:6];
        [enc setBuffer:ds4_gpu_tensor_buffer(xo) offset:ds4_gpu_tensor_offset(xo) atIndex:7];
        [enc setBuffer:scx offset:0 atIndex:8];
        [enc setBuffer:ds4_gpu_tensor_buffer(mixo) offset:ds4_gpu_tensor_offset(mixo) atIndex:9];
        [enc setBytes:&ps length:sizeof ps atIndex:10];
        [enc setThreadgroupMemoryLength:16 atIndex:0];


        {   /* llms HCQ_FUSED3 (apply_hcq3.py): fused2 + the norm apply in ONE dispatch; ALT 'hcq3' OFF -> the two dispatches */
            static int f3_state = -1; static id<MTLComputePipelineState> pf3; static uint64_t f3_calls;
            if (f3_state < 0) { const char *e = getenv("LLMS_DS4_HCQ_FUSED3"); f3_state = !(e && *e && *e != '0') ? 0 : !strcmp(e, "canary") ? 2 : 1;   /* 2: the canary (field 99) */
                if (f3_state) { pf3 = has_kernel("kernel_llms_hcq_fused3") ? ds4_gpu_get_pipeline_or_die("kernel_llms_hcq_fused3") : nil;
                    if (!pf3) { fprintf(stderr, "llms hcq fused3: kernel_llms_hcq_fused3 is not in DS4_METAL_DSV4_HC_SOURCE (make_hc_fused3.py) -- off\n"); f3_state = 0; }
                    else { fprintf(stderr, f3_state == 2 ? "llms: hcq fused3 -- CANARY (field 99 in the fused dispatch)\n" : "llms: hcq fused3 (the HC transition and its norm apply in one dispatch; ALT hcq3)\n");
                           atexit_b(^{ fprintf(stderr, "llms hcq fused3: %llu transitions in one dispatch\n", (unsigned long long)f3_calls); }); } } }
            if (f3_state && pf3 && hx_producer_on() && !llms_alt_off("hxprod") && !llms_alt_off("hcq3")) {
                const unsigned hs3 = hxp_slot++ & 7u; const NSUInteger need3 = (NSUInteger)rows * n_embd * 2u;
                if (!hxp_ring[hs3] || hxp_ring[hs3].length < need3) hxp_ring[hs3] = [g_device newBufferWithLength:(need3 > 65536u ? need3 : 65536u) options:MTLResourceStorageModePrivate];
                id<MTLBuffer> hb3 = hxp_ring[hs3];
                if (hb3) {
                    [enc setComputePipelineState:pf3];   /* buffers 0-10 are already bound for fused2 */
                    if (f3_state == 2) { a.canary = 99; [enc setBytes:&a length:sizeof a atIndex:0]; }   /* the canary: no bf16 round of x, sc x (1 + 1/1024) -- must differ */
                    [enc setBuffer:wb offset:(NSUInteger)wi atIndex:11];
                    [enc setBuffer:ds4_gpu_tensor_buffer(no) offset:ds4_gpu_tensor_offset(no) atIndex:12];
                    [enc setBuffer:hb3 offset:0 atIndex:13];
                    [enc dispatchThreadgroups:MTLSizeMake(8u * rows, 1, 1) threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                    hxp_drop(); hxp_mark.buf = ds4_gpu_tensor_buffer(no); hxp_mark.off = ds4_gpu_tensor_offset(no); hxp_mark.n = (uint64_t)rows * n_embd; hxp_mark.hb = hb3; hxp_made++;
                    ds4_gpu_end_compute_encoder(cb, enc); calls++; f3_calls++;
                    return ds4_gpu_finish_command_buffer(cb, owned, "llms hc fuseq3") ? 1 : 0;
                }
            }
        }
        {   /* llms HCQ_1P (apply_hcq1p.py): the fused transition in one pass; ALT 'hcq1p' OFF -> the shipped kernel */
            static int p1_state = -1; static id<MTLComputePipelineState> pq1p; static uint64_t p1_calls;

            if (p1_state < 0) { const char *e = getenv("LLMS_DS4_HCQ_ONEPASS"); p1_state = e && *e && *e != '0';
                if (p1_state) { pq1p = has_kernel("kernel_llms_hcq_fused2_1p") ? ds4_gpu_get_pipeline_or_die("kernel_llms_hcq_fused2_1p") : nil;
                    if (!pq1p) { fprintf(stderr, "llms hcq onepass: kernel_llms_hcq_fused2_1p is not in DS4_METAL_DSV4_HC_SOURCE (make_hcq1p_source.py) -- off\n"); p1_state = 0; }
                    else { fprintf(stderr, "llms: hcq onepass (LLMS_DS4_HCQ_ONEPASS: the HC transition's flat norm summed in pass 1 -- rounding-class; ALT hcq1p)\n");
                           atexit_b(^{ fprintf(stderr, "llms hcq onepass: %llu transitions on the one-pass kernel\n", (unsigned long long)p1_calls); }); } } }
            if (p1_state && pq1p && !llms_alt_off("hcq1p")) { [enc setComputePipelineState:pq1p]; p1_calls++; }
        }
        [enc dispatchThreadgroups:MTLSizeMake(8u * rows, 1, 1) threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        id<MTLBuffer> hxp_hb = nil; static id<MTLComputePipelineState> pah; static int pah_tried;   /* llms HX_PRODUCER2 */
        if (hx_producer_on() && !llms_alt_off("hxprod")) {
            if (!pah_tried) { pah_tried = 1; pah = ds4_gpu_get_pipeline_or_die("kernel_llms_hcq_apply_hx");
                              if (!pah) fprintf(stderr, "llms hx producer: the HC source lacks kernel_llms_hcq_apply_hx -- the HC producer is off\n"); }
            if (pah) { const unsigned hs = hxp_slot++ & 7u; const NSUInteger need = (NSUInteger)rows * n_embd * 2u;
                if (!hxp_ring[hs] || hxp_ring[hs].length < need) hxp_ring[hs] = [g_device newBufferWithLength:(need > 65536u ? need : 65536u) options:MTLResourceStorageModePrivate];
                hxp_hb = hxp_ring[hs]; }
        }
        [enc setComputePipelineState:hxp_hb ? pah : pa]; [enc setBytes:&a length:sizeof a atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(xo) offset:ds4_gpu_tensor_offset(xo) atIndex:1];
        [enc setBuffer:scx offset:0 atIndex:2]; [enc setBuffer:wb offset:(NSUInteger)wi atIndex:3];
        [enc setBuffer:ds4_gpu_tensor_buffer(no) offset:ds4_gpu_tensor_offset(no) atIndex:4];
        if (hxp_hb) { [enc setBuffer:hxp_hb offset:0 atIndex:5]; hxp_drop(); hxp_mark.buf = ds4_gpu_tensor_buffer(no); hxp_mark.off = ds4_gpu_tensor_offset(no);
                      hxp_mark.n = (uint64_t)rows * n_embd; hxp_mark.hb = hxp_hb; hxp_made++; }
        [enc dispatchThreads:MTLSizeMake((NSUInteger)rows * n_embd / 4u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        calls++;
        return ds4_gpu_finish_command_buffer(cb, owned, "llms hc fuseq") ? 1 : 0;
    }
}
int ds4_gpu_llms_hc_pre_fused_rows(ds4_gpu_tensor *split, ds4_gpu_tensor *xo, ds4_gpu_tensor *no, const ds4_gpu_tensor *residual, const ds4_gpu_tensor *pre,
    uint32_t pre_stride, ds4_gpu_tensor *mixo, const void *model_map, uint64_t model_size, uint64_t fn_off, uint64_t scale_off, uint64_t base_off, uint64_t nw_off,
    uint32_t n_embd, uint32_t n_hc, uint32_t iters, float rms_eps, float hc_eps, int flags, uint32_t rows) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n_hc != 4u || (n_embd % 4u) != 0 || rows == 0 || rows > 16u || (flags & 7) < 2) return 0;
    @autoreleasepool {
        static id<MTLComputePipelineState> p; static id<MTLBuffer> scr; static int tried;
        if (!tried) { tried = 1; p = ds4_gpu_get_pipeline_or_die("kernel_llms_hc_pre_fused_rows");
                      if (!p) fprintf(stderr, "llms: kernel_llms_hc_pre_fused_rows missing (DS4_METAL_DSV4_HC_SOURCE must name the *_hcf_rows source) -- HCF_ROWS off\n");
                      else atexit_b(^{ fprintf(stderr, "llms hcf rows: %llu fused k-row HC pre-sublayers\n", (unsigned long long)hc_fuse_rows_calls); });
                      scr = [g_device newBufferWithLength:32u * sizeof(uint32_t) options:MTLResourceStorageModeShared]; }
        if (!p || !scr) return 0;
        const uint64_t n = (uint64_t)n_hc * n_embd;
        uint64_t fi = 0, si = 0, bi = 0, wi = 0;
        id<MTLBuffer> fb = ds4_gpu_wrap_model_range(model_map, model_size, fn_off, 24u * n * 2u, &fi);
        id<MTLBuffer> sb = ds4_gpu_wrap_model_range(model_map, model_size, scale_off, 3u * sizeof(float), &si);
        id<MTLBuffer> bb = ds4_gpu_wrap_model_range(model_map, model_size, base_off, 24u * sizeof(float), &bi);
        id<MTLBuffer> wb = ds4_gpu_wrap_model_range(model_map, model_size, nw_off, (uint64_t)n_embd * sizeof(float), &wi);
        if (!fb || !sb || !bb || !wb) return 0;
        struct { int32_t n_embd, n_hc, iters; float rms_eps, hc_eps; int32_t canary; } a = { (int32_t)n_embd, (int32_t)n_hc, (int32_t)iters, rms_eps, hc_eps, flags & 7 };   /* llms HC_OWED: the mode bits (8, 16) stay on the host */
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:p];
        [enc setBytes:&a length:sizeof(a) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(residual) offset:ds4_gpu_tensor_offset(residual) atIndex:1];
        [enc setBuffer:fb offset:(NSUInteger)fi atIndex:2];
        [enc setBuffer:sb offset:(NSUInteger)si atIndex:3];
        [enc setBuffer:bb offset:(NSUInteger)bi atIndex:4];
        [enc setBuffer:ds4_gpu_tensor_buffer(pre) offset:ds4_gpu_tensor_offset(pre) atIndex:5];
        [enc setBuffer:wb offset:(NSUInteger)wi atIndex:6];
        [enc setBuffer:ds4_gpu_tensor_buffer(split) offset:ds4_gpu_tensor_offset(split) atIndex:7];
        [enc setBuffer:ds4_gpu_tensor_buffer(xo) offset:ds4_gpu_tensor_offset(xo) atIndex:8];
        [enc setBuffer:ds4_gpu_tensor_buffer(no) offset:ds4_gpu_tensor_offset(no) atIndex:9];
        [enc setBuffer:scr offset:0 atIndex:10];
        [enc setBuffer:ds4_gpu_tensor_buffer(mixo) offset:ds4_gpu_tensor_offset(mixo) atIndex:11];
        [enc setBytes:&pre_stride length:sizeof(pre_stride) atIndex:12];
        [enc setThreadgroupMemoryLength:((NSUInteger)n_embd + 96u) * sizeof(float) atIndex:0];
        {   static id<MTLComputePipelineState> pmx; const int md = (flags & DS4_GPU_LLMS_HCFR_MIX) ? 2 : 0;   /* llms HC_MIXDUAL; HC_OWED: the mode in flags */
            if (md == 0 && hx_producer_on() && hx_hcpre_on() && !llms_alt_off("hxprod") && !llms_alt_off("hxhcpre")) {   /* llms HX_HCPRE */
                static id<MTLComputePipelineState> phx; static int phx_tried;
                if (!phx_tried) { phx_tried = 1; phx = ds4_gpu_get_pipeline_or_die("kernel_llms_hc_pre_fused_rows_hx"); }
                if (phx) { const unsigned hs = hxp_slot++ & 7u; const NSUInteger need = (NSUInteger)rows * (NSUInteger)n_embd * 2u;
                    if (!hxp_ring[hs] || hxp_ring[hs].length < need) hxp_ring[hs] = [g_device newBufferWithLength:(need > 65536u ? need : 65536u) options:MTLResourceStorageModePrivate];
                    [enc setComputePipelineState:phx]; [enc setBuffer:hxp_ring[hs] offset:0 atIndex:13];
                    hxp_drop(); hxp_mark.buf = ds4_gpu_tensor_buffer(no); hxp_mark.off = ds4_gpu_tensor_offset(no); hxp_mark.n = (uint64_t)rows * n_embd; hxp_mark.hb = hxp_ring[hs]; hxp_made++; hxh_made++; }
            }
            if (md == 2 && !pmx) pmx = ds4_gpu_get_pipeline_or_die("kernel_llms_hc_pre_fused_rows_mix");
            if (md == 2 && !pmx) { fprintf(stderr, "llms hc mixdual: the _mix kernel is missing (DS4_METAL_DSV4_HC_SOURCE)\n"); ds4_gpu_end_compute_encoder(cb, enc); return 0; }
            if (md == 2) [enc setComputePipelineState:pmx];
            [enc dispatchThreadgroups:MTLSizeMake((md == 2 ? 24u : 25u) * rows, 1, 1) threadsPerThreadgroup:MTLSizeMake((flags & 4) ? 256 : 1024, 1, 1)]; }
        ds4_gpu_end_compute_encoder(cb, enc);
        hc_fuse_rows_calls++;
        return ds4_gpu_finish_command_buffer(cb, owned, "llms HC fused pre rows") ? 1 : 0;
    }
}

int ds4_gpu_hc_weighted_sum_split_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    return ds4_gpu_hc_weighted_sum_strided(out,
                                             residual_hc,
                                             split,
                                             0,
                                             mix_hc * sizeof(float),
                                             n_embd,
                                             n_hc,
                                             "HC weighted sum split");
}

/* Release decode fused HC pre-sublayer operation.  The graph driver owns the
 * optional reference fallback so this function stays a direct fused dispatch. */
int ds4_gpu_hc_split_weighted_sum_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !split || !mix || !residual_hc || !model_map ||
        n_embd == 0 || n_hc == 0) {
        return 0;
    }
    if (n_hc != 4) {
        fprintf(stderr, "ds4: Metal fused HC split/sum is specialized for HC=4\n");
        return 0;
    }

    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    const uint64_t scale_bytes = 3ull * sizeof(float);

    @autoreleasepool {
        id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
        id<MTLBuffer> splitbuf = ds4_gpu_tensor_buffer(split);
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes ||
            out_tensor_bytes % out_row_bytes != 0) {
            fprintf(stderr, "ds4: Metal fused HC split/sum output size is not a whole token row\n");
            return 0;
        }

        const uint64_t n_rows64 = out_tensor_bytes / out_row_bytes;
        if (n_rows64 == 0 || n_rows64 > UINT32_MAX ||
            n_rows64 > UINT64_MAX / mix_bytes ||
            n_rows64 > UINT64_MAX / residual_row_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum row count is outside supported range\n");
            return 0;
        }

        const uint64_t mix_total_bytes = n_rows64 * mix_bytes;
        const uint64_t residual_total_bytes = n_rows64 * residual_row_bytes;
        if (!mixbuf || !splitbuf || !xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(mix) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(split) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(residual_hc) < residual_total_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum received undersized activation buffers\n");
            return 0;
        }

        if (scale_offset > model_size || scale_bytes > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset) {
            fprintf(stderr, "ds4: Metal fused HC split/sum parameter range is outside the mapped model\n");
            return 0;
        }

        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
        if (!scalebuf || !basebuf) return 0;

        ds4_gpu_hc_split_weighted_sum_args args = {
            .n_embd = (int64_t)n_embd,
            .n_hc = (int32_t)n_hc,
            .sinkhorn_iters = (int32_t)sinkhorn_iters,
            .n_rows = (int64_t)n_rows64,
            .mix_hc = (int64_t)mix_hc,
            .nb_mix1 = mix_bytes,
            .nb_split1 = mix_bytes,
            .nb_x0 = sizeof(float),
            .nb_x1 = (uint64_t)n_embd * sizeof(float),
            .nb_x2 = residual_row_bytes,
            .nb0 = sizeof(float),
            .nb1 = out_row_bytes,
            .eps = eps,
        };

        NSUInteger nth = g_hc_split_weighted_sum_pipeline.maxTotalThreadsPerThreadgroup;
        if (nth > 256u) nth = 256u;
        if (nth > (NSUInteger)n_embd) nth = (NSUInteger)n_embd;
        if (nth == 0) nth = 1u;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_hc_split_weighted_sum_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:4];
        [enc setBuffer:splitbuf offset:ds4_gpu_tensor_offset(split) atIndex:5];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:6];
        [enc setThreadgroupMemoryLength:(NSUInteger)n_hc * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows64, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sum fused")) return 0;
    }

    return 1;
}

/* HC-pre plus the immediately following weighted RMSNorm, specialized for
 * DS4's HC=4 shape. Both decode and batched prefill use this implementation;
 * the kernel preserves their established single-row and batched scale formulas. */
int ds4_gpu_hc_split_weighted_sum_norm_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint64_t                norm_weight_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps,
    float                   norm_eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !norm_out || !split || !mix || !residual_hc || !model_map ||
        n_hc != 4 || (n_embd & 3u) != 0) {
        return 0;
    }

    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    const uint64_t scale_bytes = 3ull * sizeof(float);

    @autoreleasepool {
        id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
        id<MTLBuffer> splitbuf = ds4_gpu_tensor_buffer(split);
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> normbuf = ds4_gpu_tensor_buffer(norm_out);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes ||
            out_tensor_bytes % out_row_bytes != 0) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm output size is not a whole token row\n");
            return 0;
        }

        const uint64_t n_rows64 = out_tensor_bytes / out_row_bytes;
        if (n_rows64 == 0 || n_rows64 > UINT32_MAX ||
            n_rows64 > UINT64_MAX / mix_bytes ||
            n_rows64 > UINT64_MAX / residual_row_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm row count is outside supported range\n");
            return 0;
        }

        const uint64_t mix_total_bytes = n_rows64 * mix_bytes;
        const uint64_t residual_total_bytes = n_rows64 * residual_row_bytes;
        const uint64_t out_total_bytes = n_rows64 * out_row_bytes;
        if (!mixbuf || !splitbuf || !xbuf || !outbuf || !normbuf ||
            ds4_gpu_tensor_bytes(mix) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(split) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(residual_hc) < residual_total_bytes ||
            ds4_gpu_tensor_bytes(norm_out) < out_total_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm received undersized activation buffers\n");
            return 0;
        }

        if (scale_offset > model_size || scale_bytes > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset ||
            norm_weight_offset > model_size || out_row_bytes > model_size - norm_weight_offset) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm parameter range is outside the mapped model\n");
            return 0;
        }

        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        uint64_t norm_inner = 0;
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
        id<MTLBuffer> normwbuf = ds4_gpu_wrap_model_range(model_map, model_size, norm_weight_offset, out_row_bytes, &norm_inner);
        if (!scalebuf || !basebuf || !normwbuf) return 0;

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_hc_split_weighted_sum_norm_pipeline,
                                   "kernel_dsv4_hc_split_weighted_sum_norm4");
        if (!pipeline) return 0;

        ds4_gpu_hc_split_weighted_sum_norm_args args = {
            .n_embd = (int64_t)n_embd,
            .n_hc = (int32_t)n_hc,
            .sinkhorn_iters = (int32_t)sinkhorn_iters,
            .n_rows = (int64_t)n_rows64,
            .mix_hc = (int64_t)mix_hc,
            .nb_mix1 = mix_bytes,
            .nb_split1 = mix_bytes,
            .nb_x0 = sizeof(float),
            .nb_x1 = (uint64_t)n_embd * sizeof(float),
            .nb_x2 = residual_row_bytes,
            .nb0 = sizeof(float),
            .nb1 = out_row_bytes,
            .nb_norm1 = out_row_bytes,
            .eps = eps,
            .norm_eps = norm_eps,
        };

        NSUInteger nth = ds4_gpu_rms_norm_threads(n_embd);
        if (nth > pipeline.maxTotalThreadsPerThreadgroup) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm requires %lu threads but pipeline supports %lu\n",
                    (unsigned long)nth,
                    (unsigned long)pipeline.maxTotalThreadsPerThreadgroup);
            return 0;
        }

        const NSUInteger shared_bytes = ((NSUInteger)n_embd + 4u + 32u) * sizeof(float);
        const NSUInteger max_shared = [g_device maxThreadgroupMemoryLength];
        if (max_shared != 0 && shared_bytes > max_shared) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm requires %lu bytes of threadgroup memory but device supports %lu\n",
                    (unsigned long)shared_bytes,
                    (unsigned long)max_shared);
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:4];
        [enc setBuffer:splitbuf offset:ds4_gpu_tensor_offset(split) atIndex:5];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:6];
        [enc setBuffer:normwbuf offset:(NSUInteger)norm_inner atIndex:7];
        [enc setBuffer:normbuf offset:ds4_gpu_tensor_offset(norm_out) atIndex:8];
        [enc setThreadgroupMemoryLength:shared_bytes atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows64, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sum/norm fused")) return 0;
    }

    return 1;
}

typedef struct {
    int32_t n;
    int32_t out_dim;
    float   eps;
} ds4_gpu_hc_norm_mix_args;

int ds4_gpu_hc_rms_norm_mix_f16_available(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    static int cached = -1;
    if (cached < 0) {
        cached = ds4_gpu_get_pipeline_or_die("kernel_dsv4_hc_rms_norm_mix_f16") != nil;
    }
    return cached;
}

/* Fused decode HC-pre: unweighted RMSNorm over the flattened HC row plus the
 * F16 HC-mix matvec in one dispatch.  The kernel reproduces the standalone
 * kernels' reduction trees bit-exactly (see metal/dsv4_hc.metal), so this is
 * purely a dispatch-count optimization. */
int ds4_gpu_hc_rms_norm_mix_f16_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *x,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint32_t              n,
        uint32_t              out_dim,
        float                 eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !x || !model_map || n != 16384u || out_dim != 24u) return 0;

    @autoreleasepool {
        const uint64_t row_bytes = (uint64_t)n * sizeof(uint16_t);
        const uint64_t weight_bytes = row_bytes * out_dim;
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal fused HC norm/mix weight range is outside the mapped model\n");
            return 0;
        }

        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        if (!xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(x) < (uint64_t)n * sizeof(float) ||
            ds4_gpu_tensor_bytes(out) < (uint64_t)out_dim * sizeof(float)) {
            fprintf(stderr, "ds4: Metal fused HC norm/mix received undersized activation buffers\n");
            return 0;
        }

        uint64_t weight_inner = 0;
        id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                      weight_offset, weight_bytes,
                                                      &weight_inner);
        if (!wbuf) return 0;

        const bool use_cluster2 =
            ds4_gpu_device_is_m5_apple_silicon() &&
            getenv("DS4_METAL_DISABLE_M5_HC_NORM_MIX_CLUSTER2") == NULL;
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline_or_die(
            use_cluster2 ? "kernel_dsv4_hc_rms_norm_mix_f16_cluster2" :
                           "kernel_dsv4_hc_rms_norm_mix_f16");
        if (!pipeline ||
            (use_cluster2 && pipeline.maxTotalThreadsPerThreadgroup < 512u)) {
            return 0;
        }
        const NSUInteger shared_floats =
            use_cluster2 ? 32u + 32u * 2u * 2u : 32u + 32u * 2u;

        ds4_gpu_hc_norm_mix_args args = {
            .n = (int32_t)n,
            .out_dim = (int32_t)out_dim,
            .eps = eps,
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [enc setBuffer:wbuf offset:(NSUInteger)weight_inner atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc setThreadgroupMemoryLength:shared_floats * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:
             MTLSizeMake(use_cluster2 ? (out_dim + 3u) / 4u :
                                        (out_dim + 1u) / 2u,
                         1, 1)
             threadsPerThreadgroup:
             MTLSizeMake(32, use_cluster2 ? 16 : 8, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "fused HC norm/mix")) return 0;
    }

    return 1;
}

int ds4_gpu_hc_rms_norm_mix_split_norm_f16_tensor(
        ds4_gpu_tensor       *mix,
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *residual_hc,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              mix_weight_offset,
        uint64_t              scale_offset,
        uint64_t              base_offset,
        uint64_t              norm_weight_offset,
        uint32_t              n,
        uint32_t              mix_dim,
        uint32_t              n_embd,
        uint32_t              n_hc,
        uint32_t              sinkhorn_iters,
