        if (hc_bf16_in_expand) mark_hc_bf16_range(outbuf, (NSUInteger)ds4_gpu_tensor_offset(out_hc), (NSUInteger)args.nb2 * (NSUInteger)args.n_tokens);   /* llms HC_BF16 */

        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC expand split")) return 0;
    }

    return 1;
}

