static int deepseek4_vision_debug_dump(
        const char           *stage,
        const ds4_gpu_tensor *tensor,
        uint64_t              values) {
    const char *prefix = getenv("DS4_DEEPSEEK4_VISION_DEBUG_PREFIX");
    if (!prefix || !prefix[0]) return 1;
    if (!stage || !tensor || values > SIZE_MAX / sizeof(float)) return 0;
    const bool resume = ds4_gpu_commands_active();
    if (resume && !ds4_gpu_end_commands()) return 0;
    float *data = malloc((size_t)values * sizeof(float));
    if (!data) return 0;
    int ok = ds4_gpu_tensor_read(
            tensor, 0, data, values * sizeof(float)) != 0;
    char path[PATH_MAX];
    int length = snprintf(path, sizeof(path), "%s.%s.f32", prefix, stage);
    if (ok && (length < 0 || (size_t)length >= sizeof(path))) ok = 0;
    FILE *fp = ok ? fopen(path, "wb") : NULL;
    if (ok && (!fp || fwrite(data, sizeof(float), (size_t)values, fp) != values))
        ok = 0;
    if (fp && fclose(fp) != 0) ok = 0;
    free(data);
    if (resume && !ds4_gpu_begin_commands()) ok = 0;
    return ok;
}

int ds4_gpu_deepseek4_vision_encode(
        float                              *out,
        const float                        *patches,
        uint32_t                            grid_h,
        uint32_t                            grid_w,
        const void                         *model_map,
        uint64_t                            model_size,
        const ds4_deepseek4_vision_weights *weights) {
    if (!out || !patches || !model_map || !weights || grid_h == 0u ||
        grid_w == 0u || grid_h > UINT32_MAX / grid_w ||
        ds4_gpu_commands_active()) {
        fprintf(stderr, "ds4: invalid DeepSeek vision encoder input\n");
        return 0;
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;
    const uint32_t projection = weights->projection_dim ? weights->projection_dim : 4096u;
    if (projection != 4096u && projection != 5120u) return 0;
    const uint32_t rows = grid_h * grid_w;
    const uint32_t aligned_rows =
        ((grid_h + 2u) / 3u) * ((grid_w + 2u) / 3u);
    const uint64_t row1024 = (uint64_t)rows * 1024u;
    const uint64_t row2816 = (uint64_t)rows * 2816u;
    const uint64_t row3072 = (uint64_t)rows * 3072u;
    const uint64_t row5632 = (uint64_t)rows * 5632u;
    const uint64_t aligned_projection = (uint64_t)aligned_rows * projection;
    const uint64_t aligned9216 = (uint64_t)aligned_rows * 9216u;
    if (row5632 > SIZE_MAX / sizeof(float) ||
        aligned9216 > SIZE_MAX / sizeof(float)) return 0;

    ds4_gpu_tensor *patch = NULL, *a = NULL, *b = NULL, *qkv = NULL;
    ds4_gpu_tensor *q = NULL, *k = NULL, *v = NULL, *attn = NULL;
    ds4_gpu_tensor *mlp_w1 = NULL, *mlp_mid = NULL;
    ds4_gpu_tensor *align_in = NULL, *align_a = NULL, *align_b = NULL;
    int ok = 0;
#define DEEPSEEK4_VISION_ALLOC(name_, count_) do { \
        name_ = ds4_gpu_tensor_alloc((count_) * sizeof(float)); \
        if (!(name_)) goto cleanup; \
    } while (0)
    DEEPSEEK4_VISION_ALLOC(patch, (uint64_t)rows * 588u);
    DEEPSEEK4_VISION_ALLOC(a, row1024);
    DEEPSEEK4_VISION_ALLOC(b, row1024);
    DEEPSEEK4_VISION_ALLOC(qkv, row3072);
    DEEPSEEK4_VISION_ALLOC(q, row1024);
    DEEPSEEK4_VISION_ALLOC(k, row1024);
    DEEPSEEK4_VISION_ALLOC(v, row1024);
    DEEPSEEK4_VISION_ALLOC(attn, row1024);
    DEEPSEEK4_VISION_ALLOC(mlp_w1, row5632);
    DEEPSEEK4_VISION_ALLOC(mlp_mid, row2816);
    DEEPSEEK4_VISION_ALLOC(align_in, aligned9216);
    DEEPSEEK4_VISION_ALLOC(align_a, aligned_projection);
    DEEPSEEK4_VISION_ALLOC(align_b, aligned_projection);
#undef DEEPSEEK4_VISION_ALLOC
    if (!ds4_gpu_tensor_write(patch, 0, patches,
                              (uint64_t)rows * 588u * sizeof(float)) ||
        !ds4_gpu_begin_commands()) goto cleanup;
    ok = projection != 5120u || deepseek4_vision_dispatch_round(patch, 588u, rows);
    if (ok) ok = ds4_gpu_glm53_matmul_bf16(
            a, model_map, model_size, weights->patch_weight,
            588u, 1024u, patch, rows);
    if (ok) ok = glm53_vision_dispatch_bias(
            "kernel_glm53_vision_add_bias", a, NULL,
            model_map, model_size, weights->patch_bias,
            1024u, rows, "DeepSeek vision patch bias");
    if (ok) ok = deepseek4_vision_dispatch_round(a, 1024u, rows);
    if (ok) ok = deepseek4_vision_debug_dump(
            "patch_embed", a, row1024);

    ds4_gpu_tensor *cur = a;
    ds4_gpu_tensor *tmp = b;
    for (uint32_t il = 0; ok && il < DS4_DEEPSEEK4_VISION_LAYERS; il++) {
        const ds4_deepseek4_vision_layer_weights *w = &weights->layer[il];
        ok = glm53_vision_dispatch_rows(
                "kernel_glm53_vision_rms_bf16", tmp, cur,
                model_map, model_size, w->norm1,
                1024u, rows, 1.0e-6f, "DeepSeek vision norm1");
        if (ok) ok = deepseek4_vision_dispatch_round(tmp, 1024u, rows);
        if (ok && il == 0u) ok = deepseek4_vision_debug_dump(
                "block0_norm1", tmp, row1024);
        if (ok) ok = ds4_gpu_glm53_matmul_bf16(
                qkv, model_map, model_size, w->qkv_weight,
                1024u, 3072u, tmp, rows);
        if (ok && il == 0u) ok = deepseek4_vision_debug_dump(
                "block0_qkv", qkv, row3072);
        if (ok) ok = deepseek4_vision_dispatch_qkv(
                q, k, v, qkv, model_map, model_size,
                w->qkv_bias, rows, grid_w);
        if (ok && il == 0u) ok = deepseek4_vision_debug_dump(
                "block0_q", q, row1024);
        if (ok && il == 0u) ok = deepseek4_vision_debug_dump(
                "block0_k", k, row1024);
        if (ok && il == 0u) ok = deepseek4_vision_debug_dump(
                "block0_v", v, row1024);
        if (ok) ok = glm53_vision_dispatch_attention(attn, q, k, v, rows);
        if (ok) ok = deepseek4_vision_dispatch_round(attn, 1024u, rows);
        if (ok && il == 0u) ok = deepseek4_vision_debug_dump(
                "block0_attention", attn, row1024);
        if (ok) ok = ds4_gpu_glm53_matmul_bf16(
                tmp, model_map, model_size, w->attn_proj_weight,
                1024u, 1024u, attn, rows);
        if (ok) ok = glm53_vision_dispatch_bias(
                projection == 5120u ? "kernel_deepseek41_vision_bias_residual" :
                                      "kernel_glm53_vision_bias_residual", tmp, cur,
                model_map, model_size, w->attn_proj_bias,
                1024u, rows, "DeepSeek vision attention bias");
        if (ok) ok = deepseek4_vision_dispatch_round(tmp, 1024u, rows);
        if (ok && il == 0u) ok = deepseek4_vision_debug_dump(
                "block0_attn_residual", tmp, row1024);
        ds4_gpu_tensor *swap = cur; cur = tmp; tmp = swap;

        if (ok) ok = glm53_vision_dispatch_rows(
                "kernel_glm53_vision_rms_bf16", tmp, cur,
                model_map, model_size, w->norm2,
                1024u, rows, 1.0e-6f, "DeepSeek vision norm2");
        if (ok) ok = deepseek4_vision_dispatch_round(tmp, 1024u, rows);
        if (ok && il == 0u) ok = deepseek4_vision_debug_dump(
                "block0_norm2", tmp, row1024);
        if (ok) ok = ds4_gpu_glm53_matmul_bf16(
                mlp_w1, model_map, model_size, w->mlp_w1,
                1024u, 5632u, tmp, rows);
        if (ok) ok = deepseek4_vision_dispatch_round(mlp_w1, 5632u, rows);
        if (ok && il == 0u) ok = deepseek4_vision_debug_dump(
                "block0_mlp_w1", mlp_w1, row5632);
        if (ok) ok = deepseek4_vision_dispatch_two_rows(
                projection == 5120u ? "kernel_deepseek41_vision_swiglu_split" :
                                      "kernel_deepseek4_vision_swiglu_split",
                mlp_w1, mlp_mid, 2816u, rows,
                "DeepSeek vision SwiGLU");
        if (ok && il == 0u) ok = deepseek4_vision_debug_dump(
                "block0_mlp_mid", mlp_mid, row2816);
        if (ok) ok = ds4_gpu_glm53_matmul_bf16(
                tmp, model_map, model_size, w->mlp_w2,
                2816u, 1024u, mlp_mid, rows);
        if (ok) ok = deepseek4_vision_dispatch_round(tmp, 1024u, rows);
        if (ok) ok = deepseek4_vision_dispatch_two_rows(
                "kernel_deepseek4_vision_add_residual",
                tmp, cur, 1024u, rows,
                "DeepSeek vision MLP residual");
        swap = cur; cur = tmp; tmp = swap;
        if (ok && (il == 0u || il == 15u || il == 31u)) {
            char stage[24];
            snprintf(stage, sizeof(stage), "block%u", il);
            ok = deepseek4_vision_debug_dump(stage, cur, row1024);
        }
    }
    if (ok) ok = glm53_vision_dispatch_rows(
            "kernel_glm53_vision_rms_bf16", tmp, cur,
            model_map, model_size, weights->post_norm,
            1024u, rows, 1.0e-6f, "DeepSeek vision final norm");
    if (ok) ok = deepseek4_vision_dispatch_round(tmp, 1024u, rows);
    if (ok) ok = deepseek4_vision_debug_dump(
            "vision_norm", tmp, row1024);
    if (ok) ok = deepseek4_vision_dispatch_aligner_reorder(
            align_in, tmp, grid_h, grid_w, aligned_rows);
    if (ok) ok = ds4_gpu_glm53_matmul_bf16(
            align_a, model_map, model_size, weights->aligner_w1,
            9216u, projection, align_in, aligned_rows);
    if (ok) ok = deepseek4_vision_dispatch_gelu_bias(
            align_b, align_a, model_map, model_size,
            weights->aligner_w1_bias, aligned_rows, projection);
    if (ok) ok = ds4_gpu_glm53_matmul_bf16(
            align_a, model_map, model_size, weights->aligner_w2,
            projection, projection, align_b, aligned_rows);
    if (ok) ok = glm53_vision_dispatch_bias(
            "kernel_glm53_vision_add_bias", align_a, NULL,
            model_map, model_size, weights->aligner_w2_bias,
            projection, aligned_rows, "DeepSeek vision aligner output bias");
    if (ok) ok = deepseek4_vision_dispatch_round(
            align_a, projection, aligned_rows);
    if (ok) ok = deepseek4_vision_debug_dump(
            "aligned", align_a, aligned_projection);
    if (ok) ok = ds4_gpu_end_commands();
    else (void)ds4_gpu_end_commands();
    if (ok) ok = ds4_gpu_tensor_read(
            align_a, 0, out, aligned_projection * sizeof(float));

cleanup:
    ds4_gpu_tensor_free(align_b);
    ds4_gpu_tensor_free(align_a);
    ds4_gpu_tensor_free(align_in);
    ds4_gpu_tensor_free(mlp_mid);
    ds4_gpu_tensor_free(mlp_w1);
    ds4_gpu_tensor_free(attn);
    ds4_gpu_tensor_free(v);
    ds4_gpu_tensor_free(k);
    ds4_gpu_tensor_free(q);
    ds4_gpu_tensor_free(qkv);
    ds4_gpu_tensor_free(b);
    ds4_gpu_tensor_free(a);
    ds4_gpu_tensor_free(patch);
    return ok;
}

int ds4_gpu_glm53_scatter_image_hc(
        ds4_gpu_tensor       *hc,
        const ds4_gpu_tensor *image,
        uint32_t              dst_row,
        uint32_t              image_row,
        uint32_t              rows,
        uint32_t              total_rows,
        uint32_t              n_embd,
        uint32_t              n_hc) {
    if (!hc || !image || rows == 0 || n_embd == 0 || n_hc == 0 ||
        dst_row > total_rows || rows > total_rows - dst_row ||
        !ds4_gpu_commands_active()) return 0;
    id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_pipeline_or_die("kernel_glm53_vision_scatter_hc");
    if (!pipeline) return 0;
    glm53_vision_scatter_args args = {
        dst_row, image_row, rows, total_rows, n_embd, n_hc
    };
    int owned = 0;
    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
    if (!enc) return 0;
    [enc setComputePipelineState:pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
    [enc setBuffer:ds4_gpu_tensor_buffer(hc)
            offset:ds4_gpu_tensor_offset(hc) atIndex:1];
    [enc setBuffer:ds4_gpu_tensor_buffer(image)
            offset:ds4_gpu_tensor_offset(image) atIndex:2];
    [enc dispatchThreads:MTLSizeMake(n_embd, rows * n_hc, 1)
         threadsPerThreadgroup:MTLSizeMake(MIN((NSUInteger)n_embd, 256u), 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return ds4_gpu_finish_command_buffer(cb, owned, "GLM-5.3 vision scatter");
}

typedef struct {
    uint32_t n_heads;
    uint32_t n_rows;
    float lower_bound;
    float norm_eps;
} glm53_gpu_kda_args;

int ds4_gpu_glm53_kda_decode(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *conv_state,
        ds4_gpu_tensor       *recurrent_state,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *k,
        const ds4_gpu_tensor *v,
        const ds4_gpu_tensor *raw_gate,
        const ds4_gpu_tensor *raw_beta,
        const ds4_gpu_tensor *output_gate,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              q_conv_offset,
        uint64_t              k_conv_offset,
        uint64_t              v_conv_offset,
        uint64_t              a_log_offset,
        uint64_t              dt_bias_offset,
        uint64_t              output_norm_offset,
        uint32_t              n_heads,
        uint32_t              n_rows,
        float                 gate_lower_bound,
        float                 norm_eps) {
    enum { GLM53_KDA_DIM = 128, GLM53_KDA_HISTORY = 3 };
    if (!g_initialized && !ds4_gpu_init()) return 0;
    uint64_t projection = 0, activation_elements = 0;
    uint64_t conv_elements = 0, state_elements = 0;
    if (n_heads == 0 || n_rows == 0 || gate_lower_bound >= 0.0f ||
        !glm53_gpu_mul_u64(n_heads, GLM53_KDA_DIM, &projection) ||
        !glm53_gpu_mul_u64(projection, n_rows, &activation_elements) ||
        !glm53_gpu_mul_u64(activation_elements,
                        3u * GLM53_KDA_HISTORY, &conv_elements) ||
        !glm53_gpu_mul_u64(activation_elements, GLM53_KDA_DIM, &state_elements) ||
        !glm53_gpu_tensor_has(q, activation_elements, sizeof(float)) ||
        !glm53_gpu_tensor_has(k, activation_elements, sizeof(float)) ||
        !glm53_gpu_tensor_has(v, activation_elements, sizeof(float)) ||
        !glm53_gpu_tensor_has(raw_gate, activation_elements, sizeof(float)) ||
        !glm53_gpu_tensor_has(output_gate, activation_elements, sizeof(float)) ||
        !glm53_gpu_tensor_has(raw_beta,
                           (uint64_t)n_rows * n_heads, sizeof(float)) ||
        !glm53_gpu_tensor_has(out, activation_elements, sizeof(float)) ||
        !glm53_gpu_tensor_has(conv_state, conv_elements, sizeof(float)) ||
        !glm53_gpu_tensor_has(recurrent_state, state_elements, sizeof(float))) {
        fprintf(stderr, "ds4: GLM-5.3 KDA decode received invalid buffers\n");
        return 0;
    }

    uint64_t conv_bytes = 0, dt_bytes = 0;
    if (!glm53_gpu_mul_u64(projection, 4u * sizeof(float), &conv_bytes) ||
        !glm53_gpu_mul_u64(projection, sizeof(float), &dt_bytes)) {
        return 0;
    }
    const uint64_t a_log_bytes = (uint64_t)n_heads * sizeof(float);
    const uint64_t norm_bytes = GLM53_KDA_DIM * sizeof(float);

    @autoreleasepool {
        uint64_t qw_inner = 0, kw_inner = 0, vw_inner = 0;
        uint64_t a_inner = 0, dt_inner = 0, norm_inner = 0;
        id<MTLBuffer> qw = glm53_gpu_weight_buffer(
            model_map, model_size, q_conv_offset, conv_bytes,
            &qw_inner, "KDA Q convolution");
        id<MTLBuffer> kw = glm53_gpu_weight_buffer(
            model_map, model_size, k_conv_offset, conv_bytes,
            &kw_inner, "KDA K convolution");
        id<MTLBuffer> vw = glm53_gpu_weight_buffer(
            model_map, model_size, v_conv_offset, conv_bytes,
            &vw_inner, "KDA V convolution");
        id<MTLBuffer> a_log = glm53_gpu_weight_buffer(
            model_map, model_size, a_log_offset, a_log_bytes,
            &a_inner, "KDA A_log");
        id<MTLBuffer> dt_bias = glm53_gpu_weight_buffer(
            model_map, model_size, dt_bias_offset, dt_bytes,
            &dt_inner, "KDA dt bias");
        id<MTLBuffer> output_norm = glm53_gpu_weight_buffer(
            model_map, model_size, output_norm_offset, norm_bytes,
            &norm_inner, "KDA output norm");
        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_pipeline_or_die("kernel_glm53_kda_decode");
        if (!qw || !kw || !vw || !a_log || !dt_bias || !output_norm ||
            !pipeline) {
            return 0;
        }

        glm53_gpu_kda_args args = {
            .n_heads = n_heads,
            .n_rows = n_rows,
            .lower_bound = gate_lower_bound,
            .norm_eps = norm_eps,
        };
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(q)
                offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:ds4_gpu_tensor_buffer(k)
                offset:ds4_gpu_tensor_offset(k) atIndex:2];
        [enc setBuffer:ds4_gpu_tensor_buffer(v)
                offset:ds4_gpu_tensor_offset(v) atIndex:3];
        [enc setBuffer:ds4_gpu_tensor_buffer(raw_gate)
                offset:ds4_gpu_tensor_offset(raw_gate) atIndex:4];
        [enc setBuffer:ds4_gpu_tensor_buffer(raw_beta)
                offset:ds4_gpu_tensor_offset(raw_beta) atIndex:5];
        [enc setBuffer:ds4_gpu_tensor_buffer(output_gate)
                offset:ds4_gpu_tensor_offset(output_gate) atIndex:6];
        [enc setBuffer:qw offset:(NSUInteger)qw_inner atIndex:7];
        [enc setBuffer:kw offset:(NSUInteger)kw_inner atIndex:8];
        [enc setBuffer:vw offset:(NSUInteger)vw_inner atIndex:9];
        [enc setBuffer:a_log offset:(NSUInteger)a_inner atIndex:10];
        [enc setBuffer:dt_bias offset:(NSUInteger)dt_inner atIndex:11];
        [enc setBuffer:output_norm offset:(NSUInteger)norm_inner atIndex:12];
        [enc setBuffer:ds4_gpu_tensor_buffer(conv_state)
                offset:ds4_gpu_tensor_offset(conv_state) atIndex:13];
        [enc setBuffer:ds4_gpu_tensor_buffer(recurrent_state)
                offset:ds4_gpu_tensor_offset(recurrent_state) atIndex:14];
        [enc setBuffer:ds4_gpu_tensor_buffer(out)
                offset:ds4_gpu_tensor_offset(out) atIndex:15];
        [enc setThreadgroupMemoryLength:656u * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(n_rows, n_heads, 1)
            threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(
            cb, owned, "GLM-5.3 fused KDA decode");
    }
}


static bool dsv41_tensor_has_floats(const ds4_gpu_tensor *tensor, uint64_t count) {
    return tensor && count <= UINT64_MAX / sizeof(float) &&
           ds4_gpu_tensor_bytes(tensor) >= count * sizeof(float);
}

/* llms ROPE_TAB (apply_rope_tab.py): one-row ropes read cos / sin from a table computed once per
 * (command buffer, position, frequency table) by kernel_llms_rope_table. 1 on, -1 canary (the table one position off). */
#define ROUTE_TABLE_SLOTS 8192   /* llms RT_PERSIST (rtpersist_edit.py): 8,192 slots (2 MB), a fixed one per (position % 4096, kind) when the switch is set */
static uint8_t route_table_valid[ROUTE_TABLE_SLOTS];
static ds4_gpu_tensor *route_table_buffer;
static uint32_t route_table_start[ROUTE_TABLE_SLOTS], route_table_kind[ROUTE_TABLE_SLOTS];
static uint64_t route_tables_built, route_table_uses;
static int rope_table_preenc;   /* llms DSP_PREENC: a pre-encoded batch may be dropped -- its rope tables reuse no slot and record none */
void ds4_gpu_llms_rope_table_preenc(int on) { rope_table_preenc = on; }
static void report_rope_table(void) {
    fprintf(stderr, "llms rope tab: %llu tables, %llu ropes\n", (unsigned long long)route_tables_built, (unsigned long long)route_table_uses);
}
static int rope_table_on(void) {
    static int on = -2;
    if (on < -1) {
        const char *e = getenv("LLMS_DS4_ROPE_TAB"), *src = getenv("DS4_METAL_DSV41_SOURCE");
        on = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
        if (on && !(src && llms_srckey(src, "ropetab") != NULL)) {
            llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_ROPE_TAB ignored: DS4_METAL_DSV41_SOURCE does not name a *ropetab* source\n"), LLMS_G_NAME);
            on = 0;
        }
        if (on) {
            fprintf(stderr, on < 0 ? "llms: rope tab -- CANARY: the table one position off\n"
                                   : "llms: rope tab (cos / sin once per command buffer, position and table)\n");
            atexit(report_rope_table);
        }
    }
    return on;
}

/* Frequency rounding errors accumulate into phase errors at long contexts.
 * Preserve the reference's pow/reciprocal and YaRN operation order here. */
#pragma float_control(precise, on, push)
int ds4_gpu_dsv41_rope_stride(ds4_gpu_tensor *x, uint32_t width, uint32_t heads,
                             uint32_t rows, uint32_t start, uint32_t stride,
                             bool compressed, bool inverse) {
    if (width < 64 || !heads || !rows || rows > 1048576 || !stride ||
        (uint64_t)start + (uint64_t)(rows - 1u) * stride >= 1048576u ||
        (uint64_t)heads * rows > UINT64_MAX / width ||
        !dsv41_tensor_has_floats(x, (uint64_t)width * heads * rows)) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    static float frequencies[2][32];
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        for (int kind = 0; kind < 2; kind++) {
            const float base = kind ? 160000.0f : 10000.0f;
            const float low = (float)floor(64.0 * log(65536.0 / (32.0 * 2.0 * M_PI)) / (2.0 * log(base)));
            const float high = (float)ceil(64.0 * log(65536.0 / (2.0 * M_PI)) / (2.0 * log(base)));
            for (int i = 0; i < 32; i++) {
                const float denominator = powf(base, (float)i / 32.0f);
                float f = 1.0f / denominator;
                if (kind) {
                    const float ramp = fminf(1.0f, fmaxf(0.0f, (i - low) / (high - low)));
                    const float smooth = 1.0f - ramp;
                    const float interpolate = (f / 16.0f) * (1.0f - smooth);
                    const float extrapolate = f * smooth;
                    f = interpolate + extrapolate;
                }
                frequencies[kind][i] = f;
            }
        }
    });
    if (rows == 1 && rope_table_on()) {   /* llms ROPE_TAB */
        @autoreleasepool {
            static id<MTLComputePipelineState> pt, pr;
            if (!pt) pt = ds4_gpu_get_pipeline_or_die("kernel_llms_rope_table");
            if (!pr) pr = ds4_gpu_get_pipeline_or_die("kernel_llms_dsv41_rope_tab");
            if (!route_table_buffer) route_table_buffer = ds4_gpu_tensor_alloc((uint64_t)ROUTE_TABLE_SLOTS * 64u * sizeof(float));
            if (!pt || !pr || !route_table_buffer) return 0;
            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
            if (!enc) return 0;
            const uint32_t kind = compressed ? 1u : 0u;
            int e = -1;
            { static int rtlog = -1; static uint64_t rt_log_lines; if (rtlog < 0) { const char *l = getenv("LLMS_DS4_RT_LOG"); rtlog = l && *l && *l != '0'; }   /* llms RT_LOG (rtpersist_edit.py): the first 4,000 (position, kind, owned) of the table path */
              if (rtlog && rt_log_lines < 4000) { rt_log_lines++; fprintf(stderr, "rtlog %u %u %d\n", start, kind, owned); } }
            const int pe = (int)((start % 4096u) * 2u + kind);   /* llms RT_PERSIST (folded 10-30, hard_ac_l.py): the table kept across command buffers at a fixed slot per (position % 4096, kind) */
            if (!rope_table_preenc && route_table_valid[pe] && route_table_start[pe] == start && route_table_kind[pe] == kind) e = pe;   /* llms DSP_PREENC */
            if (e < 0) {   /* the table for this (command buffer, position, frequency table) */
                e = pe;   /* llms RT_PERSIST: the fixed slot */
                if (!rope_table_preenc) route_table_valid[e] = 1;   /* llms DSP_PREENC: nothing recorded for a maybe-dropped batch */
                struct { uint32_t start; float frequencies[32]; } targs;
                targs.start = start + (rope_table_on() < 0 ? 1u : 0u);   /* canary: one position off */
                memcpy(targs.frequencies, frequencies[kind], sizeof(targs.frequencies));
                [enc setComputePipelineState:pt];
                [enc setBytes:&targs length:sizeof(targs) atIndex:0];
                [enc setBuffer:ds4_gpu_tensor_buffer(route_table_buffer) offset:ds4_gpu_tensor_offset(route_table_buffer) + (NSUInteger)e * 64u * sizeof(float) atIndex:1];
                [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
                [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];   /* llms CONC P0 (round 10): both ROPE_TAB dispatches through dispatch_hook */
                if (!rope_table_preenc) { route_table_start[e] = start; route_table_kind[e] = kind; }   /* llms DSP_PREENC */
                route_tables_built++;
            }
            struct { uint32_t width, heads, inverse; } rargs = {width, heads, inverse ? 1u : 0u};
            [enc setComputePipelineState:pr];
            [enc setBytes:&rargs length:sizeof(rargs) atIndex:0];
            [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:1];
            [enc setBuffer:ds4_gpu_tensor_buffer(route_table_buffer) offset:ds4_gpu_tensor_offset(route_table_buffer) + (NSUInteger)e * 64u * sizeof(float) atIndex:2];
            [enc dispatchThreadgroups:MTLSizeMake(heads, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
            route_table_uses++;
            return ds4_gpu_finish_command_buffer(cb, owned, "V4.1 RoPE from the table");
        }
    }
    @autoreleasepool {
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline_or_die("kernel_dsv41_rope");
        if (!pipeline) return 0;
        struct {
            uint32_t width, heads, rows, start, inverse, stride;
            float frequencies[32];
        } args = {width, heads, rows, start, inverse, stride, {0}};
        memcpy(args.frequencies, frequencies[compressed ? 1 : 0], sizeof(args.frequencies));
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
        if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [enc dispatchThreadgroups:MTLSizeMake(heads, rows, 1)
             threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "V4.1 unit-magnitude RoPE");
    }
}
#pragma float_control(pop)

/* llms ROWS_ROPE (apply_ds4_rows_rope.py): kernel_dsv41_rope for n rows at their own positions and addresses in one dispatch;
 * bf16_first applies the BF16 pass to each head first (kernel_llms_dsv41_rope_rows, build_idx/dsv4_misc_sg_llms2.metal).
 * The frequency table is computed by the same code as ds4_gpu_dsv41_rope_stride's, in the same precise float region. */
#pragma float_control(precise, on, push)   /* llms ROWS_ROPE: the frequency table as ds4_gpu_dsv41_rope_stride computes it (first build was outside this region: fast-math table) */

static int hx_tail_on(void) {   /* llms HX_TAIL (apply_hxtail.py): LLMS_DS4_HX_TAIL=1 -- the heads tail writes the half copy kg reads; ALT hxtail */
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_HX_TAIL"); on = e && *e && *e != '0';
        if (on && !has_kernel("kernel_llms_dsv41_rope_rows_h")) { fprintf(stderr, "llms hx tail: ignored -- the misc source lacks kernel_llms_dsv41_rope_rows_h\n"); on = 0; }
        if (on) { hxt_pl = ds4_gpu_get_pipeline_or_die("kernel_llms_dsv41_rope_rows_h");
                  for (int i = 0; i < 8; i++) hxt_ring[i] = [g_device newBufferWithLength:4u * 32768u * 2u options:MTLResourceStorageModePrivate];
                  fprintf(stderr, "llms: hx tail (the heads tail writes the half copy the grouped output_a reads; its conversion skipped; ALT hxtail)\n");
                  atexit_b(^{ fprintf(stderr, "llms hx tail: %llu half copies written, %llu taken by the grouped output_a, %llu non-contiguous tails\n",
                                      (unsigned long long)hxt_made, (unsigned long long)hxt_taken, (unsigned long long)hxt_noncontig); }); } }
    return on && hxt_pl != nil;
}
int ds4_gpu_llms_dsv41_rope_rows(ds4_gpu_tensor *const *x, const uint32_t *pos, uint32_t n, uint32_t width, uint32_t heads,
                                 bool compressed, bool inverse, bool bf16_first) {
    if (n == 0 || n > row_paths_cap() || width < 64 || (width & 1u) || !heads) { fprintf(stderr, "llms rope rows dbg: refused n %u (max %u) width %u heads %u\n", (unsigned)n, (unsigned)row_paths_cap(), (unsigned)width, (unsigned)heads); return 0; }   /* llms ROWS128; llms rows dbg */
    for (uint32_t r = 0; r < n; r++) if (!dsv41_tensor_has_floats(x[r], (uint64_t)width * heads) || pos[r] >= 1048576u) { fprintf(stderr, "llms rope rows dbg: row %u of %u: tensor %p has_floats %d (need %llu) pos %u\n", (unsigned)r, (unsigned)n, (const void *)x[r], x[r] ? (int)dsv41_tensor_has_floats(x[r], (uint64_t)width * heads) : -1, (unsigned long long)width * heads, (unsigned)pos[r]); return 0; }
    if (!g_initialized && !ds4_gpu_init()) return 0;
    static float frequencies[2][32];
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        for (int kind = 0; kind < 2; kind++) {
            const float base = kind ? 160000.0f : 10000.0f;
            const float low = (float)floor(64.0 * log(65536.0 / (32.0 * 2.0 * M_PI)) / (2.0 * log(base)));
            const float high = (float)ceil(64.0 * log(65536.0 / (2.0 * M_PI)) / (2.0 * log(base)));
            for (int i = 0; i < 32; i++) {
                const float denominator = powf(base, (float)i / 32.0f);
                float f = 1.0f / denominator;
                if (kind) {
                    const float ramp = fminf(1.0f, fmaxf(0.0f, (i - low) / (high - low)));
                    const float smooth = 1.0f - ramp;
                    const float interpolate = (f / 16.0f) * (1.0f - smooth);
                    const float extrapolate = f * smooth;
                    f = interpolate + extrapolate;
                }
                frequencies[kind][i] = f;
            }
        }
    });
    @autoreleasepool {
        static id<MTLComputePipelineState> pl;
        if (!pl) pl = ds4_gpu_get_pipeline_or_die("kernel_llms_dsv41_rope_rows");
        if (!pl) { fprintf(stderr, "ds4: llms rows rope kernel missing (DS4_METAL_DSV4_MISC_SOURCE = build_idx/dsv4_misc_sg_llms2.metal)\n"); return 0; }
        struct { uint32_t width, heads, rows, inverse, bf16_first, pad[3]; float frequencies[32]; } args =
            {width, heads, n, inverse ? 1u : 0u, bf16_first ? 1u : 0u, {0, 0, 0}, {0}};
        memcpy(args.frequencies, frequencies[compressed ? 1 : 0], sizeof(args.frequencies));
        struct { uint64_t x; uint32_t pos, pad; } rows[1024];   /* llms ROWS_CAP4: was 128 -- the wall the engine named at 18:28 */
        NSMutableArray<id<MTLBuffer>> *bufs = [NSMutableArray array];
        if (@available(macOS 13.0, *)) {
            for (uint32_t r = 0; r < n; r++) {
                id<MTLBuffer> b = ds4_gpu_tensor_buffer(x[r]);
                if (!b) return 0;
                rows[r].x = (uint64_t)[b gpuAddress] + ds4_gpu_tensor_offset(x[r]); rows[r].pos = pos[r]; rows[r].pad = 0;
                if (![bufs containsObject:b]) [bufs addObject:b];
            }
        } else return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
        if (!enc) return 0;
        const bool conc = g_batch_cb && cb == g_batch_cb && g_batch_encoder_concurrent;
        if (conc) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        id<MTLBuffer> hxt_hb = nil;   /* llms HX_TAIL: the verify's heads tail (inverse, 2-4 contiguous rows of 64 x 512) also writes the half copy */
        if (inverse && n >= 2u && n <= 4u && width == 512u && heads == 64u && hx_tail_on() && hx_producer_on() && !llms_alt_off("hxtail")) {   /* v2: the kernel's copy covers 448 = 4 x 32 float4 slots */
            id<MTLBuffer> b0 = ds4_gpu_tensor_buffer(x[0]); const NSUInteger o0 = ds4_gpu_tensor_offset(x[0]); bool contig = b0 != nil;
            for (uint32_t r = 1; r < n && contig; r++) contig = ds4_gpu_tensor_buffer(x[r]) == b0 && ds4_gpu_tensor_offset(x[r]) == o0 + (NSUInteger)r * 32768u * 4u;
            if (contig) hxt_hb = hxt_ring[hxt_slot++ & 7u]; else hxt_noncontig++;
        }
        [enc setComputePipelineState:hxt_hb ? hxt_pl : pl];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        bind_rows_bytes(enc, rows, sizeof(rows[0]) * n, 1);   /* llms ROWS_CAP4 */
        if (hxt_hb) [enc setBuffer:hxt_hb offset:0 atIndex:2];   /* llms HX_TAIL */
        for (id<MTLBuffer> b in bufs) [enc useResource:b usage:MTLResourceUsageRead | MTLResourceUsageWrite];
        [enc dispatchThreadgroups:MTLSizeMake(heads, n, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        if (hxt_hb) { hxp_drop(); hxp_mark.buf = ds4_gpu_tensor_buffer(x[0]); hxp_mark.off = ds4_gpu_tensor_offset(x[0]); hxp_mark.n = (uint64_t)n * 32768u;   /* llms HX_TAIL */
                      hxp_mark.hb = hxt_hb; hxp_made++; hxt_made++; }
        if (conc) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "llms V4.1 rows RoPE");
    }
}
static const float *rope_frequencies(int kind) {   /* llms QROPE: ds4_gpu_llms_dsv41_rope_rows' frequency table, the same code in the same precise region */
    static float fr[2][32];
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        for (int kind = 0; kind < 2; kind++) {
            const float base = kind ? 160000.0f : 10000.0f;
            const float low = (float)floor(64.0 * log(65536.0 / (32.0 * 2.0 * M_PI)) / (2.0 * log(base)));
            const float high = (float)ceil(64.0 * log(65536.0 / (2.0 * M_PI)) / (2.0 * log(base)));
            for (int i = 0; i < 32; i++) {
                const float denominator = powf(base, (float)i / 32.0f);
                float f = 1.0f / denominator;
                if (kind) {
                    const float ramp = fminf(1.0f, fmaxf(0.0f, (i - low) / (high - low)));
                    const float smooth = 1.0f - ramp;
                    const float interpolate = (f / 16.0f) * (1.0f - smooth);
                    const float extrapolate = f * smooth;
                    f = interpolate + extrapolate;
                }
                fr[kind][i] = f;
            }
        }
    });
    return fr[kind ? 1 : 0];
}
void ds4_gpu_llms_redrope_set(int bf16, int compressed, int canary) {   /* llms REDROPE */
    const float *fr1 = rope_frequencies(compressed);
    redrope_args.flags = (bf16 ? 1u : 0u) | 2u; redrope_args.canary = canary ? 1u : 0u; redrope_args.pad0 = redrope_args.pad1 = 0u;
    memcpy(redrope_args.frequencies, fr1, sizeof(redrope_args.frequencies));
    redrope_requested = 1; redrope_applied_count = 0;
}
uint64_t ds4_gpu_llms_redrope_take(void) { const uint64_t d = redrope_applied_count; redrope_requested = 0; redrope_applied_count = 0; return d; }
void ds4_gpu_llms_qrope_set(int compressed, int canary) {   /* llms QROPE */
    qrope_args.flags = 0u; qrope_args.canary = canary ? 1u : 0u; qrope_args.pad0 = qrope_args.pad1 = 0u;
    memcpy(qrope_args.frequencies, rope_frequencies(compressed), sizeof(qrope_args.frequencies));
    qrope_kind = compressed ? 1 : 0; qrope_requested = 1;
}
void ds4_gpu_llms_qrope_clear(void) { qrope_requested = 0; }   /* llms QROPE */
#pragma float_control(pop)

int ds4_gpu_dsv41_rope(ds4_gpu_tensor *x, uint32_t width, uint32_t heads,
                      uint32_t rows, uint32_t start, bool compressed, bool inverse) {
    return ds4_gpu_dsv41_rope_stride(x, width, heads, rows, start, 1, compressed, inverse);
}

/* llms COUNT_BF16 (apply_ds4_count_bf16.py): BF16 rounding passes by (width, rows, caller) */
typedef struct { uint32_t width, rows; uintptr_t caller; uint64_t n; } bf16_pass_class;
static bf16_pass_class bf16_pass_classes[256]; static int bf16_pass_class_count, count_bf16_state = -1;
static void report_bf16_passes(void) {
    uint64_t tot = 0; for (int i = 0; i < bf16_pass_class_count; i++) tot += bf16_pass_classes[i].n;
    fprintf(stderr, "llms bf16 passes: %llu calls in %d (width, rows, caller) classes\n", (unsigned long long)tot, bf16_pass_class_count);
    for (int k = 0; k < bf16_pass_class_count; k++) { int best = k; for (int i = k + 1; i < bf16_pass_class_count; i++) if (bf16_pass_classes[i].n > bf16_pass_classes[best].n) best = i;
        bf16_pass_class t = bf16_pass_classes[k]; bf16_pass_classes[k] = bf16_pass_classes[best]; bf16_pass_classes[best] = t; }
    for (int i = 0; i < bf16_pass_class_count && i < 24; i++) {
        Dl_info di; const int ok = dladdr((void *)bf16_pass_classes[i].caller, &di);
        fprintf(stderr, "llms bf16 pass: width %u rows %u caller image offset 0x%lx: %llu\n", bf16_pass_classes[i].width, bf16_pass_classes[i].rows,
                (unsigned long)(bf16_pass_classes[i].caller - (ok ? (uintptr_t)di.dli_fbase : 0)), (unsigned long long)bf16_pass_classes[i].n);   /* resolve: atos -o <binary> -l 0x100000000 <0x100000000 + offset> */
    }
}
static void note_bf16_pass(uint32_t width, uint32_t rows, uintptr_t caller) {
    if (count_bf16_state < 0) { count_bf16_state = getenv("LLMS_DS4_COUNT_BF16") != NULL; if (count_bf16_state) atexit(report_bf16_passes); }
    if (!count_bf16_state) return;
    for (int i = 0; i < bf16_pass_class_count; i++) if (bf16_pass_classes[i].width == width && bf16_pass_classes[i].rows == rows && bf16_pass_classes[i].caller == caller) { bf16_pass_classes[i].n++; return; }
    if (bf16_pass_class_count < 256) bf16_pass_classes[bf16_pass_class_count++] = (bf16_pass_class){width, rows, caller, 1};
}

/* llms DSP_ROWSCALE (apply_dsp_rowscale.py): the drafter's ring-row means scaled by a power of two when a row would overflow the GEMM's half cast */
static id<MTLBuffer> rowscale_stats;
static void report_rowscale(void) { if (!rowscale_stats) return; const uint32_t *s = (const uint32_t *)rowscale_stats.contents; float mx; memcpy(&mx, &s[1], 4);
    fprintf(stderr, "llms dsp rowscale: %u ring rows scaled (max |layer mean| seen %.0f; the half cast overflows above 65504)\n", s[0], (double)mx); }
int ds4_gpu_llms_dsp_rowscale(ds4_gpu_tensor *x, uint32_t width, uint32_t rows) {
    if (!x || !width || !rows) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    @autoreleasepool {
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline_or_die("kernel_llms_dsp_rowscale"); if (!pipeline) return 0;
        if (!rowscale_stats) { rowscale_stats = [g_device newBufferWithLength:16 options:MTLResourceStorageModeShared]; memset(rowscale_stats.contents, 0, 16); atexit(report_rowscale); }
        int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned); id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil; if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&width length:sizeof(width) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [enc setBuffer:rowscale_stats offset:0 atIndex:2];
        [enc dispatchThreadgroups:MTLSizeMake(1, rows, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "llms dsp rowscale");
    }
}

int ds4_gpu_dsv41_quantize(ds4_gpu_tensor *x, uint32_t width, uint32_t rows,
                          ds4_v41_activation_format format) {
    {   /* llms NO_BF16 (apply_ds4_fidelity_dials.py; adopted for agent / cli, unconditional since 10-27): a FIDELITY DIAL -- the BF16 re-rounding of activations skipped; ALT nobf */
        if (format == DS4_V41_BF16 && !llms_alt_off("nobf")) return 1;
    }
    if (format == DS4_V41_BF16 && hc_bf16_marked_at_op != UINT64_MAX) {   /* llms HC_BF16: the range was just written by an HC kernel that rounded it */
        const bool same = hc_bf16_marked_at_op == ops_counted && x && ds4_gpu_tensor_buffer(x) == hc_bf16_marked_buffer && (NSUInteger)ds4_gpu_tensor_offset(x) == hc_bf16_marked_offset &&
                          (NSUInteger)width * rows * sizeof(float) == hc_bf16_marked_bytes;
        hc_bf16_marked_at_op = UINT64_MAX;
        if (same) return 1;
    }
    if (hxp_mark.buf && x && ds4_gpu_tensor_buffer(x) == hxp_mark.buf) hxp_drop();   /* llms HX_PRODUCER: an in-place quantize of the producer's output makes its half copy stale */
    if (format == DS4_V41_BF16) note_bf16_pass(width, rows, (uintptr_t)__builtin_return_address(0));   /* llms COUNT_BF16 */
    {   /* llms PRICE_DUP_Q (apply_ds4_price_dup_q.py): k extra (idempotent) BF16 passes before each one; ALT dupq */
        static int price_dup_q_count = -1, price_dup_q_inside = 0; static uint64_t price_dup_q_passes;
        if (price_dup_q_count < 0) { const char *e = getenv("LLMS_DS4_PRICE_DUP_Q"); price_dup_q_count = e && *e ? atoi(e) : 0; if (price_dup_q_count < 0 || price_dup_q_count > 64) price_dup_q_count = 0;
                          if (price_dup_q_count) fprintf(stderr, "llms: PRICE_DUP_Q %d extra BF16 passes before every BF16 pass (pricing instrument, idempotent)\n", price_dup_q_count); }
        if (price_dup_q_count > 0 && !price_dup_q_inside && format == DS4_V41_BF16 && !llms_alt_off("dupq")) {
            price_dup_q_inside = 1; for (int i = 0; i < price_dup_q_count; i++) { if (!ds4_gpu_dsv41_quantize(x, width, rows, format)) { price_dup_q_inside = 0; return 0; } price_dup_q_passes++; } price_dup_q_inside = 0;
            if ((price_dup_q_passes & 0xFFFFu) < (uint64_t)price_dup_q_count) fprintf(stderr, "llms price dup q: %llu extra passes so far\n", (unsigned long long)price_dup_q_passes);
        }
    }
    const uint32_t block = format == DS4_V41_FP4_E4M3 ? 16u : 32u;
    if (!width || !rows || format < DS4_V41_BF16 || format > DS4_V41_FP4_E4M3 ||
        (format != DS4_V41_BF16 && width % block) ||
        !dsv41_tensor_has_floats(x, (uint64_t)width * rows)) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    @autoreleasepool {
        const uint64_t count = (uint64_t)width * rows;
        const bool linear = format == DS4_V41_BF16 && count <= UINT32_MAX &&
            ds4_gpu_tensor_offset(x) % 16u == 0 &&
            !cached_getenv("DS4_METAL_DISABLE_V41_LINEAR_BF16");
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline_or_die(linear ?
            "kernel_dsv41_bf16_linear" : "kernel_dsv41_quantize");
        if (!pipeline) return 0;
        const uint32_t args[] = {width, rows, (uint32_t)format};
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
        if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        if (linear) [enc setBytes:&count length:sizeof(count) atIndex:0];
        else [enc setBytes:args length:sizeof(args) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:1];
        if (linear) {
            [enc dispatchThreadgroups:MTLSizeMake((count + 1023u) / 1024u, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        } else {
            [enc dispatchThreadgroups:MTLSizeMake(((uint64_t)width + block - 1u) / block, rows, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        }
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "V4.1 activation quantization");
    }
}

int ds4_gpu_dsv41_engram_add(ds4_gpu_tensor *residual,
                           const ds4_gpu_tensor *kv,
                           const ds4_gpu_tensor *q_weight,
                           const ds4_gpu_tensor *k_weight,
                           const ds4_gpu_tensor *mask,
                           uint32_t width, uint32_t rows, float eps) {
    const uint64_t count = (uint64_t)width * rows;
    if (!width || !rows || !isfinite(eps) || eps <= 0 || count > UINT64_MAX / 5u ||
        !dsv41_tensor_has_floats(residual, count * 4u) ||
        !dsv41_tensor_has_floats(kv, count * 5u) ||
        !dsv41_tensor_has_floats(q_weight, (uint64_t)width * 4u) ||
        !dsv41_tensor_has_floats(k_weight, (uint64_t)width * 4u) ||
        (mask && ds4_gpu_tensor_bytes(mask) < rows)) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    @autoreleasepool {
        {   /* llms ENG_PAR (apply_engpar.py): 1,024 threads per (row, stream), bit-identical by construction */
            static int eng_par_state = -1; static id<MTLComputePipelineState> ep_pl; static uint64_t ep_calls;
            if (eng_par_state < 0) {
                const char *e = getenv("LLMS_DS4_ENG_PAR"); eng_par_state = e && *e && *e != '0' ? (!strcmp(e, "canary") ? 2 : 1) : 0;
                if (eng_par_state) {
                    ep_pl = ds4_gpu_get_pipeline_or_die("kernel_llms_engram_add_par");
                    if (!ep_pl || ep_pl.maxTotalThreadsPerThreadgroup < 1024) { fprintf(stderr, "llms eng par: kernel missing or under 1024 threads (DS4_METAL_DSV41_SOURCE must name the eng copy) -- OFF\n"); eng_par_state = 0; }
                    else { fprintf(stderr, eng_par_state == 2 ? "llms: eng par -- CANARY: the gate x (1 + 2^-10)\n" : "llms: eng par (the Engram gated add on 1024 threads per row and stream, bit-identical)\n");
                           atexit_b(^{ fprintf(stderr, "llms eng par: %llu calls\n", (unsigned long long)ep_calls); }); }
                }
            }
            if (eng_par_state && width == 5120u && !llms_alt_off("engpar")) {
                const struct { uint32_t width, rows; float eps; uint32_t masked, canary; } pa = {width, rows, eps, mask != NULL, eng_par_state == 2 ? 1u : 0u};
                int powned = 0;
                id<MTLCommandBuffer> pcb = ds4_gpu_command_buffer(&powned);
                id<MTLComputeCommandEncoder> penc = pcb ? ds4_gpu_compute_encoder(pcb) : nil;
                if (!penc) return 0;
                [penc setComputePipelineState:ep_pl];
                [penc setBytes:&pa length:sizeof(pa) atIndex:0];
                const ds4_gpu_tensor *pin[] = {residual, kv, q_weight, k_weight, mask ? mask : residual};
                for (NSUInteger i = 0; i < 5; i++)
                    [penc setBuffer:ds4_gpu_tensor_buffer(pin[i]) offset:ds4_gpu_tensor_offset(pin[i]) atIndex:i + 1];
                [penc setThreadgroupMemoryLength:16400 atIndex:0];
                [penc dispatchThreadgroups:MTLSizeMake(rows, 4, 1) threadsPerThreadgroup:MTLSizeMake(1024, 1, 1)];
                ds4_gpu_end_compute_encoder(pcb, penc);
                ep_calls++;
                return ds4_gpu_finish_command_buffer(pcb, powned, "V4.1 Engram gate (ENG_PAR)");
            }
        }
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline_or_die("kernel_dsv41_engram_add");
        if (!pipeline) return 0;
        const struct { uint32_t width, rows; float eps; uint32_t masked; } args =
            {width, rows, eps, mask != NULL};
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
        if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        const ds4_gpu_tensor *inputs[] = {residual, kv, q_weight, k_weight, mask ? mask : residual};
        for (NSUInteger i = 0; i < 5; i++)
            [enc setBuffer:ds4_gpu_tensor_buffer(inputs[i])
                    offset:ds4_gpu_tensor_offset(inputs[i]) atIndex:i + 1];
        [enc dispatchThreadgroups:MTLSizeMake(rows, 4, 1)
             threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "V4.1 Engram gate");
    }
}

int ds4_gpu_dsv41_carry_copy(ds4_gpu_tensor *packed, uint32_t row_offset,
                            ds4_gpu_tensor *plain, uint32_t width, uint32_t rows,
                            uint32_t format, bool pack) {
    if (!width || !rows || rows > UINT32_MAX - row_offset ||
        format > DS4_V41_CARRY_MASK || packed == plain) return 0;
    const uint32_t words = format == DS4_V41_CARRY_BF16 ?
        ((uint64_t)width + 1u) / 2u : ((uint64_t)width + 31u) / 32u;
    if (!dsv41_tensor_has_floats(packed, (uint64_t)(row_offset + rows) * words) ||
        !dsv41_tensor_has_floats(plain, (uint64_t)rows * width)) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    @autoreleasepool {
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline_or_die("kernel_dsv41_carry_copy");
        if (!pipeline) return 0;
        const uint32_t args[] = {width, rows, words, format, pack};
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
        if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        [enc setBytes:args length:sizeof(args) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(packed) offset:ds4_gpu_tensor_offset(packed) +
            (NSUInteger)row_offset * words * sizeof(uint32_t) atIndex:1];
        [enc setBuffer:ds4_gpu_tensor_buffer(plain) offset:ds4_gpu_tensor_offset(plain) atIndex:2];
        [enc dispatchThreadgroups:MTLSizeMake(((uint64_t)width + 127u) / 128u, rows, 1)
             threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "V4.1 compact prefill carry");
    }
}

int ds4_gpu_dsv41_pool2(ds4_gpu_tensor *out,
                      const ds4_gpu_tensor *kv, const ds4_gpu_tensor *scores,
                      ds4_gpu_tensor *previous_kv, ds4_gpu_tensor *previous_scores,
                      uint32_t width, uint32_t rows, uint32_t start) {
    const uint64_t count = (uint64_t)width * rows;
    const uint32_t pairs = (uint32_t)(((uint64_t)rows + (start & 1u)) / 2u);
    if (!width || !rows || rows > UINT32_MAX - start ||
        !dsv41_tensor_has_floats(kv, count) || !dsv41_tensor_has_floats(scores, count) ||
        !dsv41_tensor_has_floats(previous_kv, width) ||
        !dsv41_tensor_has_floats(previous_scores, width) ||
        (pairs && !dsv41_tensor_has_floats(out, (uint64_t)width * pairs))) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    @autoreleasepool {
        if (pairs) {
            id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline_or_die("kernel_dsv41_pool2");
            if (!pipeline) return 0;
            const uint32_t args[] = {width, pairs, start & 1u};
            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
            if (!enc) return 0;
            [enc setComputePipelineState:pipeline];
            [enc setBytes:args length:sizeof(args) atIndex:0];
            const ds4_gpu_tensor *inputs[] = {out, kv, scores, previous_kv, previous_scores};
            for (NSUInteger i = 0; i < 5; i++)
                [enc setBuffer:ds4_gpu_tensor_buffer(inputs[i])
                        offset:ds4_gpu_tensor_offset(inputs[i]) atIndex:i + 1];
            [enc dispatchThreads:MTLSizeMake(width, pairs, 1)
                 threadsPerThreadgroup:MTLSizeMake(MIN(width, 256u), 1, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
            if (!ds4_gpu_finish_command_buffer(cb, owned, "V4.1 KV pair pooling")) return 0;
        }
        /* Keep the last even-position input, as the row-at-a-time path does.
         * It is live only for an odd frontier, but matching it also makes
         * snapshots independent of how the prefix was partitioned. */
        const uint32_t last_even = (start + rows - 1u) & ~1u;
        if (last_even >= start) {
            const uint64_t bytes = (uint64_t)width * sizeof(float);
            const uint64_t offset = (last_even - start) * bytes;
            if (!ds4_gpu_tensor_copy(previous_kv, 0, kv, offset, bytes) ||
                !ds4_gpu_tensor_copy(previous_scores, 0, scores, offset, bytes)) return 0;
        }
    }
    return 1;
}

static int dsv41_candidates(ds4_gpu_tensor *out, const ds4_gpu_tensor *scores,
                            const ds4_gpu_tensor *mask, uint32_t width,
                            uint32_t rows, uint32_t start, uint32_t ratio) {
    if (!width || width > UINT32_MAX - 7u || !rows || !ratio ||
        rows > UINT32_MAX - start) return 0;
    const uint32_t blocks = (width + 7u) / 8u;
    const uint32_t output_width = mask ? width : blocks;
    if (!dsv41_tensor_has_floats(scores, (uint64_t)width * rows) ||
        !dsv41_tensor_has_floats(out, (uint64_t)output_width * rows) ||
        (mask && !dsv41_tensor_has_floats(mask, (uint64_t)blocks * rows))) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    @autoreleasepool {
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline_or_die(mask ?
            "kernel_dsv41_candidate_filter" : "kernel_dsv41_candidate_blocks");
        if (!pipeline) return 0;
        const uint32_t args[] = {width, rows, start, ratio};
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
        if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        [enc setBytes:args length:sizeof(args) atIndex:0];
        const ds4_gpu_tensor *inputs[] = {scores, out, mask ? mask : scores};
        for (NSUInteger i = 0; i < 3; i++)
            [enc setBuffer:ds4_gpu_tensor_buffer(inputs[i])
                    offset:ds4_gpu_tensor_offset(inputs[i]) atIndex:i + 1];
        [enc dispatchThreads:MTLSizeMake(output_width, rows, 1)
             threadsPerThreadgroup:MTLSizeMake(MIN(output_width, 256u), 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "V4.1 candidate selection");
    }
}

int ds4_gpu_dsv41_candidate_blocks(ds4_gpu_tensor *blocks,
                                  const ds4_gpu_tensor *scores,
                                  uint32_t width, uint32_t rows,
                                  uint32_t start, uint32_t ratio) {
    return dsv41_candidates(blocks, scores, NULL, width, rows, start, ratio);
}

int ds4_gpu_dsv41_candidate_filter(ds4_gpu_tensor *scores,
                                  const ds4_gpu_tensor *block_mask,
                                  uint32_t width, uint32_t rows,
                                  uint32_t start, uint32_t ratio,
                                  uint32_t mask_stride) {
    if (!block_mask) return 0;
    /* upstream b3f5018 added mask_stride (0 = (width + 7) / 8, the stride this engine's kernel reads); another stride is refused here */
    if (mask_stride && mask_stride != (width + 7u) / 8u) return 0;
    return dsv41_candidates(scores, scores, block_mask, width, rows, start, ratio);
}

static int kv_half_flag;   /* llms KV_HALF gather: the flag ahead of its setter (a tentative definition; the setter below defines it) */
/* llms MQA4 (apply_mqa4.py): decode attention over raw rows + compressed half rows read by index (no gather) */
int ds4_gpu_llms_mqa4_heads(ds4_gpu_tensor *heads, const void *model_map, uint64_t model_size, uint64_t sinks_offset, const ds4_gpu_tensor *q,
                            const ds4_gpu_tensor *raw_kv, uint32_t n_raw, uint32_t raw_cap, uint32_t raw_start, const ds4_gpu_tensor *comp_half,
                            const ds4_gpu_tensor *ids, uint32_t n_sel, uint32_t n_head, uint32_t head_dim, int canary) {
    static id<MTLComputePipelineState> pp, pr, pr_group; static uint64_t calls; static id<MTLBuffer> part;
    static int mqa7_state = -1; static id<MTLComputePipelineState> pp7; static uint64_t mqa7_calls;   /* llms MQA7 (apply_mqa7.py) */
    if (mqa7_state < 0) { const char *e = getenv("LLMS_DS4_MQA7"); mqa7_state = e && atoi(e) > 0; if (mqa7_state) { pp7 = ds4_gpu_get_pipeline_or_die("llms_mqa7_partial"); if (!pp7) mqa7_state = 0;
                  fprintf(stderr, "llms: mqa7 %s (decode attention partial on simdgroup matrices; rounding class)\n", mqa7_state ? "on" : "MISSING -- off"); if (!mqa7_state) llms_guard_fail(LLMS_G_MISS);
                  if (mqa7_state) atexit_b(^{ fprintf(stderr, "llms mqa7: %llu partials\n", (unsigned long long)mqa7_calls); }); } }
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (kv_half_flag != 1 || n_head != 64u || head_dim != 512u || !n_sel || n_raw + n_sel > 2048u || raw_cap < n_raw || !comp_half || !ids) return 0;
    if (!pp || !pr || !pr_group) { pp = ds4_gpu_get_pipeline_or_die("llms_mqa4_partial"); pr = ds4_gpu_get_pipeline_or_die("llms_mqa4_reduce");
               pr_group = ds4_gpu_get_pipeline_or_die("kernel_astra_mqa_reduce_group");
               if (!pp || !pr || !pr_group) { static int w; if (!w++) fprintf(stderr, "llms: mqa4 kernels missing (DS4_METAL_DSV4_MISC_SOURCE must name the *_mqa4 superset) -- MQA4 off\n"); return 0; }
               atexit_b(^{ fprintf(stderr, "llms mqa4: %llu decode attentions without the gather pass\n", (unsigned long long)calls); }); }
    if (!part) part = [g_device newBufferWithLength:(NSUInteger)128u * 64u * 516u * sizeof(float) options:MTLResourceStorageModePrivate];
    if (!part) return 0;
    const uint64_t sink_bytes = (uint64_t)n_head * sizeof(float);
    if (sinks_offset > model_size || sink_bytes > model_size - sinks_offset) return 0;
    uint64_t sinks_inner = 0;
    id<MTLBuffer> sinks_buf = ds4_gpu_wrap_model_range(model_map, model_size, sinks_offset, sink_bytes, &sinks_inner);
    if (!sinks_buf) return 0;
    const uint32_t ns = canary ? n_sel - 1u : n_sel, N = n_raw + ns;
    if (!N) return 0;
    struct { uint32_t n_raw, raw_cap, raw_start, n_comp, n_head, has_sel, n_chunk, pad0; float scale; } ma =
        { n_raw, raw_cap, raw_start, ns, n_head, 1u, (N + 15u) / 16u, 0u, 1.0f / sqrtf((float)head_dim) };
    if (g_kv_task.pending && !ds4_gpu_kv_norm_task_flush()) return 0;
    @autoreleasepool {
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        const int use7 = mqa7_state && !llms_alt_off("mqa7"); if (use7) mqa7_calls++;   /* llms MQA7 */
        [enc setComputePipelineState:use7 ? pp7 : pp];
        [enc setBytes:&ma length:sizeof ma atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(q) offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:ds4_gpu_tensor_buffer(raw_kv) offset:ds4_gpu_tensor_offset(raw_kv) atIndex:2];
        [enc setBuffer:ds4_gpu_tensor_buffer(comp_half) offset:ds4_gpu_tensor_offset(comp_half) atIndex:3];
        [enc setBuffer:ds4_gpu_tensor_buffer(ids) offset:ds4_gpu_tensor_offset(ids) atIndex:4];
        [enc setBuffer:part offset:0 atIndex:5];
        [enc setThreadgroupMemoryLength:(use7 ? 2u : 1u) * 16u * 128u * 8u atIndex:0];   /* llms MQA7: K + Q staging */
        [enc dispatchThreadgroups:MTLSizeMake(ma.n_chunk, 4, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        [enc setComputePipelineState:(ma.n_chunk > 1u && !llms_alt_off("argrp")) ? pr_group : pr];
        [enc setBytes:&ma length:sizeof ma atIndex:0];
        [enc setBuffer:part offset:0 atIndex:1];
        [enc setBuffer:sinks_buf offset:(NSUInteger)sinks_inner atIndex:2];
        [enc setBuffer:ds4_gpu_tensor_buffer(heads) offset:ds4_gpu_tensor_offset(heads) atIndex:3];
        [enc dispatchThreadgroups:MTLSizeMake(64, 1, 1) threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned, "llms mqa4 attention")) return 0;
    }
    calls++;
    return 1;
}
int ds4_gpu_dsv41_gather_kv(ds4_gpu_tensor *out, const ds4_gpu_tensor *source,
                           const ds4_gpu_tensor *ids, uint32_t source_rows,
                           uint32_t selected_rows) {
    const bool kv_half_rows = kv_half_flag == 1;   /* llms KV_HALF gather: the compressed cache holds half rows; get_rows_f16 writes float rows */
    if (!source_rows || !selected_rows || selected_rows > 512 ||
        selected_rows > source_rows ||
        (kv_half_rows ? (ds4_gpu_tensor_bytes(source) < (uint64_t)source_rows * 512u * sizeof(uint16_t)) : !dsv41_tensor_has_floats(source, (uint64_t)source_rows * 512u)) ||
        !dsv41_tensor_has_floats(out, (uint64_t)selected_rows * 512u) ||
        !dsv41_tensor_has_floats(ids, selected_rows)) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (kv_half_rows && !g_get_rows_f16_pipeline) return 0;
    @autoreleasepool {
        const uint64_t row_bytes = 512u * sizeof(float);
        const uint64_t src_row_bytes = kv_half_rows ? 512u * sizeof(uint16_t) : row_bytes;   /* llms KV_HALF gather */
        const ds4_gpu_get_rows_args args = {
            .ne00t = 512, .ne00 = 512, .nb01 = src_row_bytes,
            .nb02 = (uint64_t)source_rows * src_row_bytes,
            .nb03 = (uint64_t)source_rows * src_row_bytes,
            .ne10 = (int32_t)selected_rows, .nb10 = sizeof(int32_t),
            .nb11 = (uint64_t)selected_rows * sizeof(int32_t),
            .nb12 = (uint64_t)selected_rows * sizeof(int32_t),
            .nb1 = row_bytes, .nb2 = (uint64_t)selected_rows * row_bytes,
            .nb3 = (uint64_t)selected_rows * row_bytes,
        };
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
        if (!enc) return 0;
        [enc setComputePipelineState:kv_half_rows ? g_get_rows_f16_pipeline : g_get_rows_f32_pipeline];   /* llms KV_HALF gather */
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        const ds4_gpu_tensor *inputs[] = {source, ids, out};
        for (NSUInteger i = 0; i < 3; i++)
            [enc setBuffer:ds4_gpu_tensor_buffer(inputs[i])
                    offset:ds4_gpu_tensor_offset(inputs[i]) atIndex:i + 1];
        [enc dispatchThreadgroups:MTLSizeMake(2u * selected_rows, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "V4.1 sparse KV gather");
    }
}


/* Qwen3.8-Flash-Next kernels (metal/qwen4.metal): one dispatch per wrapper,
 * weights bound from the model map by offset, transients as ds4_gpu_tensors.
 * Every wrapper joins the active command batch. */

typedef struct {
    id<MTLBuffer> buf;
    NSUInteger    off;
} qwen4_bind;

static bool qwen4_bind_tensor(qwen4_bind *b, const ds4_gpu_tensor *t, uint64_t min_bytes, const char *what) {
    if (!t || !ds4_gpu_tensor_buffer(t) || ds4_gpu_tensor_bytes(t) < min_bytes) {
        fprintf(stderr, "ds4: Qwen3.8 %s buffer is missing or undersized (%" PRIu64 " < %" PRIu64 ")\n",
                what, t ? ds4_gpu_tensor_bytes(t) : 0, min_bytes);
        return false;
    }
    b->buf = ds4_gpu_tensor_buffer(t);
    b->off = ds4_gpu_tensor_offset(t);
    return true;
}

static bool qwen4_bind_weight(qwen4_bind *b, const void *map, uint64_t size,
                              uint64_t offset, uint64_t bytes, const char *what) {
    uint64_t inner = 0;
    if (!map || offset > size || bytes > size - offset) {
        fprintf(stderr, "ds4: Qwen3.8 %s range is outside the mapped model\n", what);
        return false;
    }
    b->buf = ds4_gpu_wrap_model_range(map, size, offset, bytes, &inner);
    b->off = (NSUInteger)inner;
    return b->buf != nil;
}

