/* llms SHEXP_PAIR (apply_ds4_shexp_pair.py): the shared expert's gate + up + SwiGLU in one 16-token half-tile pass */
int ds4_gpu_llms_shexp_pair(ds4_gpu_tensor *mid, const void *model_map, uint64_t model_size, uint64_t gate_offset, uint64_t up_offset,
                            uint32_t in_dim, uint32_t out_dim, const ds4_gpu_tensor *x, uint32_t n_tok, float limit) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n_tok != 16u || (in_dim % 32u) || (out_dim % 16u) || !mid || !x ||
        ds4_gpu_tensor_bytes(x) < (uint64_t)n_tok * in_dim * sizeof(float) || ds4_gpu_tensor_bytes(mid) < (uint64_t)n_tok * out_dim * sizeof(float)) return 0;
    static id<MTLComputePipelineState> pl; if (!pl) pl = ds4_gpu_get_pipeline_or_die("kernel_llms_q8_sgmh16_pair_swiglu_k4r2");
    if (!pl) return 0;
    const uint64_t row_bytes = (uint64_t)(in_dim / 32u) * 34u, wbytes = row_bytes * out_dim;
    uint64_t gin = 0, uin = 0;
    id<MTLBuffer> gbuf = ds4_gpu_wrap_model_range(model_map, model_size, gate_offset, wbytes, &gin);
    id<MTLBuffer> ubuf = ds4_gpu_wrap_model_range(model_map, model_size, up_offset, wbytes, &uin);
    if (!gbuf || !ubuf) return 0;
    struct { int32_t K, rows; uint64_t row_bytes, x_tok_stride, dst_tok_stride; float limit, alpha; } a =
        { (int32_t)in_dim, (int32_t)out_dim, row_bytes, (uint64_t)in_dim * sizeof(float), (uint64_t)out_dim * sizeof(float), fabsf(limit), limit < 0.0f ? 0.5f : 1.0f };   /* a negative limit = the canary: alpha 0.5 */
    @autoreleasepool {
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
        if (!enc) return 0;
        const NSUInteger nsg = 4, nr = 16, per_sg = 2u * nr * 32u * 2u + 32u * 16u * 2u;
        [enc setComputePipelineState:pl];
        [enc setBytes:&a length:sizeof(a) atIndex:0];
        [enc setBuffer:gbuf offset:(NSUInteger)gin atIndex:1];
        [enc setBuffer:ubuf offset:(NSUInteger)uin atIndex:2];
        [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:3];
        [enc setBuffer:ds4_gpu_tensor_buffer(mid) offset:ds4_gpu_tensor_offset(mid) atIndex:4];
        [enc setThreadgroupMemoryLength:nsg * per_sg + 2u * nsg * nr * 16u * 4u atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + nr - 1u) / nr, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, nsg, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "llms shexp pair");
    }
}
/* llms IDX_HALF (apply_ds4_idx_half.py): n half values -> float, on the batch command buffer */
int ds4_gpu_llms_copy_f16_f32(ds4_gpu_tensor *dst, uint64_t dst_off, const ds4_gpu_tensor *src, uint64_t src_off, uint32_t n) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!g_cpy_contig_f16_f32_pipeline || !dst || !src || n == 0 || (n % 4u) != 0 ||
        ds4_gpu_tensor_bytes(src) < src_off + (uint64_t)n * sizeof(uint16_t) || ds4_gpu_tensor_bytes(dst) < dst_off + (uint64_t)n * sizeof(float)) return 0;
    @autoreleasepool {
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
        if (!enc) return 0;
        [enc setComputePipelineState:g_cpy_contig_f16_f32_pipeline];
        [enc setBytes:&n length:sizeof(n) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(src) offset:ds4_gpu_tensor_offset(src) + (NSUInteger)src_off atIndex:1];
        [enc setBuffer:ds4_gpu_tensor_buffer(dst) offset:ds4_gpu_tensor_offset(dst) + (NSUInteger)dst_off atIndex:2];
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n / 4u + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "llms f16 -> f32 copy");
    }
}
