static int rows_attn0_canary;   /* llms ROWS_ATTN0 (apply_ds4_rows_attn0.py): set by ds4.c */
void ds4_gpu_llms_set_ra0_canary(int on) { rows_attn0_canary = on; }
int ds4_gpu_llms_v41_rows_attention(const void *model_map, uint64_t model_size, uint64_t sinks_offset, uint32_t n,
        ds4_gpu_tensor *const *q, ds4_gpu_tensor *const *raw, ds4_gpu_tensor *const *comp, ds4_gpu_tensor *const *topk,
        ds4_gpu_tensor *const *heads, const uint32_t *pos, const uint32_t *n_comp, uint32_t top_k, uint32_t ratio,
        uint32_t n_head, uint32_t head_dim) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n == 0 || n > row_paths_cap() || head_dim != 512 || n_head == 0 || ratio == 0) return 0;   /* llms ROWS128 */   /* llms ROWS_ATTN0: top_k 0 = the raw window only */
    static id<MTLComputePipelineState> split_pl, reduce_pl;
    if (!split_pl) split_pl = ds4_gpu_get_pipeline_or_die("kernel_llms_v41_rows_attn_split");
    if (!reduce_pl) reduce_pl = ds4_gpu_get_pipeline_or_die("kernel_llms_v41_rows_attn_reduce");
    if (!split_pl || !reduce_pl) {
        fprintf(stderr, "ds4: llms rows attention kernels missing (set DS4_METAL_DSV4_MISC_SOURCE to build_idx/dsv4_misc_llms.metal)\n");
        return 0;
    }
    @autoreleasepool {
        if (sinks_offset > model_size || (uint64_t)n_head * sizeof(float) > model_size - sinks_offset) return 0;
        uint64_t sinks_inner = 0;
        id<MTLBuffer> sinks_buf = ds4_gpu_wrap_model_range(model_map, model_size, sinks_offset,
                                                           (uint64_t)n_head * sizeof(float), &sinks_inner);
        if (!sinks_buf) return 0;
        row_record rows[1024];   /* llms ROWS_CAP4: was 128 */
        NSMutableArray<id<MTLBuffer>> *reads = [NSMutableArray array];
        NSMutableArray<id<MTLBuffer>> *writes = [NSMutableArray array];
        if (@available(macOS 13.0, *)) {
            for (uint32_t i = 0; i < n; i++) {
                id<MTLBuffer> bq = ds4_gpu_tensor_buffer(q[i]), br = ds4_gpu_tensor_buffer(raw[i]), bc = ds4_gpu_tensor_buffer(comp[i]),
                              bt = ds4_gpu_tensor_buffer(topk[i]), bh = ds4_gpu_tensor_buffer(heads[i]);
                if (!bq || !br || !bc || !bt || !bh) return 0;
                if (ds4_gpu_tensor_bytes(raw[i]) < 128u * head_dim * sizeof(float) ||
                    ds4_gpu_tensor_bytes(comp[i]) < (uint64_t)n_comp[i] * (kv_fp4_flag ? 288u : head_dim * (kv_half_flag ? sizeof(uint16_t) : sizeof(float))) ||   /* llms KV_HALF / KV_FP4 */
                    ds4_gpu_tensor_bytes(topk[i]) < (uint64_t)top_k * sizeof(int32_t) ||
                    ds4_gpu_tensor_bytes(q[i]) < (uint64_t)n_head * head_dim * sizeof(float) ||
                    ds4_gpu_tensor_bytes(heads[i]) < (uint64_t)n_head * head_dim * sizeof(float)) {
                    fprintf(stderr, "ds4: llms rows attention: undersized buffer at row %u\n", i);
                    return 0;
                }
                const uint32_t n_raw = (pos[i] + 1u < 128u ? pos[i] + 1u : 128u) - (top_k == 0 && rows_attn0_canary && pos[i] > 0 ? 1u : 0u);   /* llms ROWS_ATTN0 canary */
                rows[i] = (row_record){
                    .q = (uint64_t)[bq gpuAddress] + ds4_gpu_tensor_offset(q[i]),
                    .raw = (uint64_t)[br gpuAddress] + ds4_gpu_tensor_offset(raw[i]),
                    .comp = (uint64_t)[bc gpuAddress] + ds4_gpu_tensor_offset(comp[i]),
                    .topk = (uint64_t)[bt gpuAddress] + ds4_gpu_tensor_offset(topk[i]),
                    .dst = (uint64_t)[bh gpuAddress] + ds4_gpu_tensor_offset(heads[i]),
                    .pos = pos[i], .raw_start = (pos[i] + 1u - n_raw) % 128u, .n_raw = n_raw, .n_comp = n_comp[i]};
                [reads addObject:bq]; [reads addObject:br]; [reads addObject:bc]; [reads addObject:bt]; [writes addObject:bh];
            }
        } else {
            return 0;
        }
        {   /* llms ATTN_GEMM (apply_ds4_attn_gemm.py): gather + Q.K^T + softmax + P.V on simdgroup matrices (misc source llms17) */
            static int attn_gemm_state = -2, ag_v = 1; static id<MTLComputePipelineState> ag_g, ag_q, ag_s, ag_p; static uint64_t ag_calls;   /* llms ATTN_GEMM v2: ag_v 2 */
            static id<MTLBuffer> ag_kt, ag_qt, ag_mask, ag_S, ag_P; static NSUInteger ag_kt_b, ag_qt_b, ag_mask_b, ag_S_b, ag_P_b;
            if (attn_gemm_state == -2) {
                const char *e = getenv("LLMS_DS4_ATTN_GEMM"), *src = getenv("DS4_METAL_DSV4_MISC_SOURCE");
                attn_gemm_state = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") || !strcmp(e, "canary2") ? -1 : 1;
                ag_v = e && (!strcmp(e, "2") || !strcmp(e, "canary2")) ? 2 : 1;   /* llms ATTN_GEMM v2 */
                if (attn_gemm_state && !(src && llms_srckey(src, ag_v == 2 ? "llms18" : "llms17") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_ATTN_GEMM ignored: DS4_METAL_DSV4_MISC_SOURCE does not name an *%s* source\n", ag_v == 2 ? "llms18" : "llms17"), LLMS_G_NAME); attn_gemm_state = 0; }
                if (attn_gemm_state) { ag_g = ds4_gpu_get_pipeline_or_die(ag_v == 2 ? "kernel_llms_agemm2_gather" : "kernel_llms_agemm_gather"); ag_q = ds4_gpu_get_pipeline_or_die("kernel_llms_agemm_qk");
                          ag_s = ds4_gpu_get_pipeline_or_die(ag_v == 2 ? "kernel_llms_agemm2_softmax" : "kernel_llms_agemm_softmax"); ag_p = ds4_gpu_get_pipeline_or_die(ag_v == 2 ? "kernel_llms_agemm2_pv" : "kernel_llms_agemm_pv");
                          if (!ag_g || !ag_q || !ag_s || !ag_p) { fprintf(stderr, "llms attn gemm: kernels missing\n"); attn_gemm_state = 0; }
                          else if (ag_v == 2) fprintf(stderr, attn_gemm_state < 0 ? "llms: attn gemm v2 -- CANARY: every row's newest raw key masked\n" : "llms: attn gemm v2 (float P; P(float) . V(half) on simdgroup matrices)\n");
                          else fprintf(stderr, attn_gemm_state < 0 ? "llms: attn gemm -- CANARY: the last 8 top-k slots of every row masked\n" : "llms: attn gemm (gather + Q.K^T + softmax + P.V on simdgroup matrices)\n"); }
            }
            const uint32_t nk = 128u + top_k;
            if (attn_gemm_state && !llms_alt_off("agemm") && n_head % 32u == 0 && nk % 32u == 0 && nk <= 768u) {
                const NSUInteger b_kt = (NSUInteger)n * nk * 512u * 2u, b_qt = (NSUInteger)n * n_head * 512u * 2u, b_mask = (NSUInteger)n * nk * 4u,
                                 b_S = (NSUInteger)n * n_head * nk * 4u, b_P = (NSUInteger)n * n_head * nk * (ag_v == 2 ? 4u : 2u);   /* llms ATTN_GEMM v2: float P */
                if (!ds4_gpu_ensure_scratch_buffer(&ag_kt, &ag_kt_b, b_kt, "llms_agemm_kt") || !ds4_gpu_ensure_scratch_buffer(&ag_qt, &ag_qt_b, b_qt, "llms_agemm_qt") ||
                    !ds4_gpu_ensure_scratch_buffer(&ag_mask, &ag_mask_b, b_mask, "llms_agemm_mask") || !ds4_gpu_ensure_scratch_buffer(&ag_S, &ag_S_b, b_S, "llms_agemm_s") ||
                    !ds4_gpu_ensure_scratch_buffer(&ag_P, &ag_P_b, b_P, "llms_agemm_p")) return 0;
                struct { uint32_t n_rows, n_head, top_k, nk, raw_cap, window, ratio, comp_fmt; uint64_t raw_row_stride, comp_row_stride; float scale; uint32_t canary; } ga = {
                    n, n_head, top_k, nk, 128u, 128u, ratio, kv_fp4_flag ? 2u : kv_half_flag ? 1u : 0u,
                    (uint64_t)head_dim * sizeof(float), kv_fp4_flag ? 288u : kv_half_flag ? (uint64_t)head_dim * sizeof(uint16_t) : (uint64_t)head_dim * sizeof(float),
                    1.0f / sqrtf((float)head_dim), attn_gemm_state < 0 ? (ag_v == 2 ? 2u : 1u) : 0u };   /* llms ATTN_GEMM v2: canary 2 = the newest raw key masked */
                int owned = 0;
                id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                if (!cb) return 0;
                id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                [enc setComputePipelineState:ag_g];
                [enc setBytes:&ga length:sizeof(ga) atIndex:0];
                bind_row_records(enc, rows, n, 1);   /* llms ROWS128: past 4 KB through a ring */
                [enc setBuffer:ag_kt offset:0 atIndex:2]; [enc setBuffer:ag_qt offset:0 atIndex:3]; [enc setBuffer:ag_mask offset:0 atIndex:4];
                for (id<MTLBuffer> b in reads) [enc useResource:b usage:MTLResourceUsageRead];
                [enc dispatchThreads:MTLSizeMake(64, nk + n_head, n) threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
                [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
                [enc setComputePipelineState:ag_q];
                [enc setBytes:&ga length:sizeof(ga) atIndex:0];
                [enc setBuffer:ag_kt offset:0 atIndex:1]; [enc setBuffer:ag_qt offset:0 atIndex:2]; [enc setBuffer:ag_S offset:0 atIndex:3];
                [enc dispatchThreadgroups:MTLSizeMake(nk / 32u, n_head / 32u, n) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
                [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
                [enc setComputePipelineState:ag_s];
                [enc setBytes:&ga length:sizeof(ga) atIndex:0];
                [enc setBuffer:ag_S offset:0 atIndex:1]; [enc setBuffer:ag_mask offset:0 atIndex:2];
                [enc setBuffer:sinks_buf offset:(NSUInteger)sinks_inner atIndex:3]; [enc setBuffer:ag_P offset:0 atIndex:4];
                [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n * n_head, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
                [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
                [enc setComputePipelineState:ag_p];
                [enc setBytes:&ga length:sizeof(ga) atIndex:0];
                bind_row_records(enc, rows, n, 1);   /* llms ROWS128: past 4 KB through a ring */
                [enc setBuffer:ag_kt offset:0 atIndex:2]; [enc setBuffer:ag_P offset:0 atIndex:3];
                for (id<MTLBuffer> b in writes) [enc useResource:b usage:MTLResourceUsageWrite];
                [enc dispatchThreadgroups:MTLSizeMake(16, n_head / 32u, n) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);
                if (!ag_calls++) fprintf(stderr, "llms attn gemm: first call (%u rows, top_k %u, %u keys, comp format %u)\n", n, top_k, nk, ga.comp_fmt);
                return ds4_gpu_finish_command_buffer(cb, owned, "llms attn gemm") ? 1 : 0;
            }
        }
        const uint32_t splits = 12u;
        const uint64_t row_bytes = (uint64_t)head_dim * sizeof(float);
        ds4_gpu_dsv4_indexed_attention_args args = {
            .n_tokens = n, .n_head = n_head, .n_raw = 128, .raw_cap = 128, .raw_start = 0, .n_comp = 0, .top_k = top_k,
            .pos0 = 0, .window = 128, .ratio = ratio, .comp_kv_f16 = kv_half_flag ? 1u : 0u, .n_splits = splits,   /* llms KV_HALF */
            .q_token_stride = (uint64_t)n_head * row_bytes, .q_head_stride = row_bytes, .raw_row_stride = row_bytes,
            .comp_row_stride = kv_fp4_flag ? 288u : kv_half_flag ? (uint64_t)head_dim * sizeof(uint16_t) : row_bytes, .topk_token_stride = (uint64_t)top_k * sizeof(int32_t),   /* llms KV_FP4 */
            .dst_token_stride = (uint64_t)n_head * row_bytes, .dst_head_stride = row_bytes,
            .scale = 1.0f / sqrtf((float)head_dim),
        };
        const uint64_t nrows = (uint64_t)n * n_head;
        const uint64_t tmp_bytes = nrows * head_dim * splits * sizeof(float) + nrows * splits * 2u * sizeof(float);
        if (!ds4_gpu_ensure_scratch_buffer(&g_flash_attn_tmp_buffer, &g_flash_attn_tmp_bytes, (NSUInteger)tmp_bytes,
                                           "ds4_dsv4_indexed_attention_split_tmp")) return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:split_pl];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        bind_row_records(enc, rows, n, 1);   /* llms ROWS128: past 4 KB through a ring */
        [enc setBuffer:g_flash_attn_tmp_buffer offset:0 atIndex:2];
        for (id<MTLBuffer> b in reads) [enc useResource:b usage:MTLResourceUsageRead];
        [enc setThreadgroupMemoryLength:16u * 128u * sizeof(uint16_t) * 4u atIndex:0];
        if (kv_fp4_flag) {   /* llms KV_FP4: the stock split with the FP4 row loader; no attention variant reads FP4 rows */
            static id<MTLComputePipelineState> fp4_pl; if (!fp4_pl) fp4_pl = ds4_gpu_get_pipeline_or_die("kernel_llms_v41_rows_attn_split_fp4");
            if (!fp4_pl) { fprintf(stderr, "llms kv fp4: kernel_llms_v41_rows_attn_split_fp4 missing\n"); return 0; }
            [enc setComputePipelineState:fp4_pl];
            [enc dispatchThreadgroups:MTLSizeMake(n, (n_head + 7u) / 8u, splits) threadsPerThreadgroup:MTLSizeMake(32, 8, 1)];
        } else
            [enc dispatchThreadgroups:MTLSizeMake(n, (n_head + 7u) / 8u, splits) threadsPerThreadgroup:MTLSizeMake(32, 8, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:reduce_pl];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        bind_row_records(enc, rows, n, 1);   /* llms ROWS128: past 4 KB through a ring */
        [enc setBuffer:g_flash_attn_tmp_buffer offset:0 atIndex:2];
        [enc setBuffer:sinks_buf offset:(NSUInteger)sinks_inner atIndex:3];
        for (id<MTLBuffer> b in writes) [enc useResource:b usage:MTLResourceUsageWrite];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)nrows, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned, "llms v41 rows attention")) return 0;
    }
    return 1;
}

#import <IOSurface/IOSurface.h>
#import <objc/runtime.h>
#import <objc/message.h>
#include <dlfcn.h>
/* llms RPOLICY (apply_rpolicy.py): the streaming expert cache's cumulative lookup counters */
void ds4_gpu_llms_cache_counts(uint64_t *hits, uint64_t *misses) { if (hits) *hits = g_stream_expert_cache_hits; if (misses) *misses = g_stream_expert_cache_misses; }

/* llms STEP_COV (apply_step_cov.py): per-step deltas of routing-determined work counters, for covariate-adjusted ALT-B */
int ds4_gpu_llms_step_cov(double *v, int n) {
    static uint64_t prev[32]; uint64_t cur[32]; int k = 0;
    cur[k++] = g_stream_expert_cache_misses; cur[k++] = g_stream_expert_cache_hits; cur[k++] = g_stream_expert_cache_read_bytes;
    for (int r = 1; r < 18; r++) cur[k++] = pair_run_histogram[r];
    cur[k++] = dedup2_singles; cur[k++] = dedup2_doubles; cur[k++] = dedup4_quads;
    for (int i = 0; i < k && i < n; i++) { v[i] = (double)(cur[i] - prev[i]); prev[i] = cur[i]; }
    return k;
}

void ds4_gpu_llms_conc_skip(int on) { conc_skip_first = on ? 1 : 0; }   /* llms CONC: drop the barrier before the next op's first dispatch */
uint64_t ds4_gpu_llms_conc_count(void) { return conc_barriers + conc_barriers_skipped; }   /* llms CONC_SKIP */

/* llms DSP41 (apply_dsp41.py): the V4.1 DSpark drafter's Metal helpers. The support model's tensor data as views (no residency request, no warmup: pages fault in when the drafter first binds them), and a plain one-token routed MoE on those views -- the generic branch of the original one-token routed MoE (mul_mv_id gate and up, SwiGLU x route weight, mul_mv_id down, expert sum). */
int ds4_gpu_llms_add_model_views(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size, uint64_t max_tensor_bytes) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    for (uint32_t i = 0; i < g_model_view_count; i++) if (g_model_views[i].model_map == model_map) return 1;
    uint64_t mapped = 0;
    @autoreleasepool {
        const int ok = ds4_gpu_add_model_view_range(model_map, model_size, map_offset, map_size, max_tensor_bytes, false, &mapped);
        if (ok) fprintf(stderr, "llms dsp41: %.2f GiB of the support model wrapped as Metal views (%u views in all)\n", (double)mapped / 1073741824.0, g_model_view_count);
        return ok;
    }
}
/* llms DSP41_BANK (apply_dsp41_bank.py) */
void ds4_gpu_llms_router_bias_override(const ds4_gpu_tensor *bias) { router_bias_override = bias; }
int ds4_gpu_llms_add_model_view_span(const void *model_map, uint64_t model_size, uint64_t off, uint64_t len, uint64_t max_tensor_bytes) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    uint64_t mapped = 0;
    @autoreleasepool { return ds4_gpu_add_model_view_range(model_map, model_size, off, len, max_tensor_bytes, false, &mapped); }
}
/* llms DSP_PAIR (apply_dsp_pair.py): 1 = the drafter's IQ2_XXS gate / up as one fused pair + SwiGLU dispatch, * 2 = canary (gate and up swapped); 0 = off. ALT dsppair. */
static uint64_t drafter_pair_calls;
static int llms_alt_off(const char *name);
static int drafter_pair_on(uint32_t gate_type) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("LLMS_DS4_DSP_PAIR"); v = !(e && *e && *e != '0') ? 0 : !strcmp(e, "canary") ? 2 : 1;
                 if (v) { fprintf(stderr, v == 2 ? "llms: dsp pair CANARY -- the drafter's gate and up swapped\n"
                                                 : "llms: dsp pair (the drafter's IQ2_XXS gate / up / SwiGLU in one dispatch)\n");
                          atexit_b(^{ fprintf(stderr, "llms dsp pair: %llu fused drafter MoE calls\n", (unsigned long long)drafter_pair_calls); }); } }
    if (!v || gate_type != DS4_METAL_TENSOR_IQ2_XXS || !g_moe_mul_mv_id_iq2_xxs_pair_swiglu_pipeline || llms_alt_off("dsppair")) return 0;
    drafter_pair_calls++; return v;
}
int ds4_gpu_llms_dsp_moe_bank(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *experts,
    const ds4_gpu_tensor *gbank, const ds4_gpu_tensor *ubank, const ds4_gpu_tensor *dbank, const ds4_gpu_tensor *map, ds4_gpu_tensor *selb,
    uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes, uint64_t down_expert_bytes, uint64_t down_row_bytes,
    uint32_t in_dim, uint32_t mid_dim, uint32_t out_dim, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_orig, uint32_t n_bank,
    uint32_t n_used, float clamp, const ds4_gpu_tensor *x) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !experts || !x || !selected || !weights || !gbank || !ubank || !dbank || !map || !selb ||
        n_bank == 0 || n_used < 1 || n_used > DS4_METAL_MAX_ROUTED_EXPERT_USED) return 0;   /* llms DSP_TOPK1: was n_used < 2 */
    @autoreleasepool {
        id<MTLComputePipelineState> gp = ds4_gpu_routed_mv_pipeline(gate_type), dp = ds4_gpu_routed_mv_pipeline(down_type);
        const uint32_t gnr = ds4_gpu_routed_mv_nr0(gate_type), dnr = ds4_gpu_routed_mv_nr0(down_type);
        if (!gp || !dp || !gnr || !dnr) { fprintf(stderr, "llms dsp41 bank: moe setup failed (types %u / %u)\n", gate_type, down_type); return 0; }
        const ds4_gpu_mul_mv_id_args ga = ds4_gpu_make_mul_mv_id_args(in_dim, mid_dim, n_bank, gate_row_bytes, gate_expert_bytes, 1, n_used, 1, gnr);
        const ds4_gpu_mul_mv_id_args da = ds4_gpu_make_mul_mv_id_args(mid_dim, out_dim, n_bank, down_row_bytes, down_expert_bytes, n_used, n_used, 1, dnr);
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLBuffer> xb = ds4_gpu_tensor_buffer(x), gtb = ds4_gpu_tensor_buffer(gate), utb = ds4_gpu_tensor_buffer(up), mb = ds4_gpu_tensor_buffer(mid),
                      eb = ds4_gpu_tensor_buffer(experts), ob = ds4_gpu_tensor_buffer(out), sb = ds4_gpu_tensor_buffer(selected), wb = ds4_gpu_tensor_buffer(weights),
                      gbb = ds4_gpu_tensor_buffer(gbank), ubb = ds4_gpu_tensor_buffer(ubank), dbb = ds4_gpu_tensor_buffer(dbank),
                      mpb = ds4_gpu_tensor_buffer(map), sbb = ds4_gpu_tensor_buffer(selb);
        const NSUInteger xo = ds4_gpu_tensor_offset(x), go = ds4_gpu_tensor_offset(gate), uo = ds4_gpu_tensor_offset(up), mo = ds4_gpu_tensor_offset(mid),
                         eo = ds4_gpu_tensor_offset(experts), oo = ds4_gpu_tensor_offset(out), so = ds4_gpu_tensor_offset(selected), wo = ds4_gpu_tensor_offset(weights),
                         gbo = ds4_gpu_tensor_offset(gbank), ubo = ds4_gpu_tensor_offset(ubank), dbo = ds4_gpu_tensor_offset(dbank),
                         mpo = ds4_gpu_tensor_offset(map), sbo = ds4_gpu_tensor_offset(selb);
        const int drafter_pair_now = drafter_pair_on(gate_type);   /* llms DSP_PAIR: decided once per call */
        const int ok =
            ds4_gpu_encode_get_rows_i32_token_rows(cb, mpb, mpo, sb, so, NULL, sbb, sbo, n_orig, 1, n_used) &&   /* bank slot = map[original id] */
            (drafter_pair_now ?   /* llms DSP_PAIR (apply_dsp_pair.py): gate + up + SwiGLU in one dispatch */
             ds4_gpu_encode_mul_mv_id_pair_swiglu(cb, g_moe_mul_mv_id_iq2_xxs_pair_swiglu_pipeline, &ga,
                 &(ds4_gpu_dsv4_moe_swiglu_weight_args){ .width = mid_dim, .rows = n_used, .gate_row_stride = (uint64_t)mid_dim * sizeof(float),
                     .up_row_stride = (uint64_t)mid_dim * sizeof(float), .mid_row_stride = (uint64_t)mid_dim * sizeof(float), .weight_stride = sizeof(float),
                     .write_clamped = 0, .clamp_value = clamp },
                 drafter_pair_now == 2 ? ubb : gbb, drafter_pair_now == 2 ? ubo : gbo,
                 drafter_pair_now == 2 ? gbb : ubb, drafter_pair_now == 2 ? gbo : ubo,
                 xb, xo, gtb, go, utb, uo, mb, mo, sbb, sbo, wb, wo, ds4_gpu_routed_mv_smem(gate_type), 2, false) :
            (ds4_gpu_encode_mul_mv_id(cb, gp, &ga, gbb, gbo, xb, xo, gtb, go, sbb, sbo, dsp_routed_mv_smem(gate_type),
                                     ds4_gpu_routed_mv_nsg(gate_type), ds4_gpu_routed_mv_rows_per_group_is_nr0(gate_type)) &&
            ds4_gpu_encode_mul_mv_id(cb, gp, &ga, ubb, ubo, xb, xo, utb, uo, sbb, sbo, dsp_routed_mv_smem(gate_type),
                                     ds4_gpu_routed_mv_nsg(gate_type), ds4_gpu_routed_mv_rows_per_group_is_nr0(gate_type)) &&
            ds4_gpu_encode_moe_swiglu_weight(cb, gtb, go, utb, uo, mb, mo, wb, wo, mid_dim, n_used, clamp, false))) &&
            ds4_gpu_encode_mul_mv_id(cb, dp, &da, dbb, dbo, mb, mo, n_used == 1 ? ob : eb, n_used == 1 ? oo : eo, sbb, sbo, ds4_gpu_routed_mv_smem(down_type),   /* llms DSP_TOPK1b */
                                     ds4_gpu_routed_mv_nsg(down_type), ds4_gpu_routed_mv_rows_per_group_is_nr0(down_type)) &&
            (n_used == 1 || ds4_gpu_encode_moe_sum_experts(cb, eb, eo, ob, oo, out_dim, n_used, 1));   /* llms DSP_TOPK1b: one expert is its own sum */
        if (!ok) { fprintf(stderr, "llms dsp41 bank: moe encode failed\n"); return 0; }
        return ds4_gpu_finish_command_buffer(cb, owned, "llms dsp41 bank moe");
    }
}
/* llms DSP_BS64 (apply_dsp_bs64.py): the drafter bank's gate / up on the main model's BS64 k1 kernel; the down on the bank's id kernel */
uint64_t ds4_gpu_llms_tensor_gpu_address(const ds4_gpu_tensor *t) { id<MTLBuffer> b = t ? ds4_gpu_tensor_buffer(t) : nil; return b ? (uint64_t)[b gpuAddress] + (uint64_t)ds4_gpu_tensor_offset(t) : 0; }
int ds4_gpu_llms_dsp_moe_bank_bs64(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *experts,
    const ds4_gpu_tensor *gaddr, const ds4_gpu_tensor *uaddr, const ds4_gpu_tensor *gcodes, const ds4_gpu_tensor *ucodes,
    const ds4_gpu_tensor *dbank, const ds4_gpu_tensor *map, ds4_gpu_tensor *selb, ds4_gpu_tensor *xp, ds4_gpu_tensor *xs, ds4_gpu_tensor *entries,
    uint32_t down_type, uint64_t down_expert_bytes, uint64_t down_row_bytes, uint32_t in_dim, uint32_t mid_dim, uint32_t out_dim,
    const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_orig, uint32_t n_bank, uint32_t n_used, float clamp, const ds4_gpu_tensor *x,
    const ds4_gpu_tensor *g32d_addr, const ds4_gpu_tensor *g32d_codes, ds4_gpu_tensor *g32d_xp, ds4_gpu_tensor *g32d_xs) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !experts || !gaddr || !uaddr || !gcodes || !ucodes || !dbank || !map || !selb || !xp || !xs || !entries || !selected || !weights || !x ||
        in_dim != 5120u || mid_dim != 2304u || n_used < 1u || n_used > 8u || n_bank == 0u) return 0;
    @autoreleasepool {
        static id<MTLComputePipelineState> xpar, k1; static uint64_t bs64_calls;
        if (!xpar) xpar = ds4_gpu_get_pipeline_or_die("kernel_llms_bs64_xplanes_par");
        if (!k1) k1 = ds4_gpu_get_pipeline_or_die("kernel_llms_bs64_k1_p5_f32");
        id<MTLComputePipelineState> dp = ds4_gpu_routed_mv_pipeline(down_type); const uint32_t dnr = ds4_gpu_routed_mv_nr0(down_type);
        if (!xpar || !k1 || !dp || !dnr) { fprintf(stderr, "llms dsp bs64: a pipeline is missing (DS4_METAL_MOE_SOURCE must carry the bs64 xpar kernels)\n"); return 0; }
        if (!bs64_calls++) atexit_b(^{ fprintf(stderr, "llms dsp bs64: %llu drafter bank MoE calls on the BS64 k1 kernel\n", (unsigned long long)bs64_calls); });
        const ds4_gpu_mul_mv_id_args ga = ds4_gpu_make_mul_mv_id_args(in_dim, mid_dim, n_bank, 1400u, (uint64_t)mid_dim * 1400u, 1, n_used, 1, 1);
        const ds4_gpu_mul_mv_id_args da = ds4_gpu_make_mul_mv_id_args(mid_dim, out_dim, n_bank, down_row_bytes, down_expert_bytes, n_used, n_used, 1, dnr);
        const ds4_gpu_dsv4_moe_swiglu_weight_args act = { .width = mid_dim, .rows = n_used, .gate_row_stride = (uint64_t)mid_dim * sizeof(float),
            .up_row_stride = (uint64_t)mid_dim * sizeof(float), .mid_row_stride = (uint64_t)mid_dim * sizeof(float), .weight_stride = sizeof(float), .write_clamped = 0, .clamp_value = clamp };
        int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned); if (!cb) return 0;
        id<MTLBuffer> xb = ds4_gpu_tensor_buffer(x), xpb = ds4_gpu_tensor_buffer(xp), xsb = ds4_gpu_tensor_buffer(xs), gab = ds4_gpu_tensor_buffer(gaddr), uab = ds4_gpu_tensor_buffer(uaddr),
                      gtb = ds4_gpu_tensor_buffer(gate), utb = ds4_gpu_tensor_buffer(up), mb = ds4_gpu_tensor_buffer(mid), sbb = ds4_gpu_tensor_buffer(selb), wb = ds4_gpu_tensor_buffer(weights),
                      enb = ds4_gpu_tensor_buffer(entries), dbb = ds4_gpu_tensor_buffer(dbank), eb = ds4_gpu_tensor_buffer(experts), ob = ds4_gpu_tensor_buffer(out),
                      mpb = ds4_gpu_tensor_buffer(map), sb = ds4_gpu_tensor_buffer(selected), gcb = ds4_gpu_tensor_buffer(gcodes), ucb = ds4_gpu_tensor_buffer(ucodes);
        int ok = ds4_gpu_encode_get_rows_i32_token_rows(cb, mpb, ds4_gpu_tensor_offset(map), sb, ds4_gpu_tensor_offset(selected), NULL, sbb, ds4_gpu_tensor_offset(selb), n_orig, 1, n_used);   /* bank slot = map[original id] */
        if (ok) {
            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            if (!enc) ok = 0;
            else {
                const uint32_t pp[4] = { 1u, in_dim, 5u, 0u };   /* one token, its stride in floats, 5 activation planes, no canary */
                if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];   /* the bank slots from get_rows */
                [enc setComputePipelineState:xpar];
                [enc setBuffer:xb offset:ds4_gpu_tensor_offset(x) atIndex:0]; [enc setBuffer:xpb offset:ds4_gpu_tensor_offset(xp) atIndex:1];
                [enc setBuffer:xsb offset:ds4_gpu_tensor_offset(xs) atIndex:2]; [enc setBytes:pp length:sizeof pp atIndex:3];
                [enc dispatchThreads:MTLSizeMake(160u * 32u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
                if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
                [enc setComputePipelineState:k1];
                [enc setBytes:&ga length:sizeof ga atIndex:0]; [enc setBytes:&act length:sizeof act atIndex:1];
                [enc setBuffer:gab offset:ds4_gpu_tensor_offset(gaddr) atIndex:2]; [enc setBuffer:uab offset:ds4_gpu_tensor_offset(uaddr) atIndex:3];
                [enc setBuffer:xb offset:ds4_gpu_tensor_offset(x) atIndex:4]; [enc setBuffer:gtb offset:ds4_gpu_tensor_offset(gate) atIndex:5];
                [enc setBuffer:utb offset:ds4_gpu_tensor_offset(up) atIndex:6]; [enc setBuffer:mb offset:ds4_gpu_tensor_offset(mid) atIndex:7];
                [enc setBuffer:sbb offset:ds4_gpu_tensor_offset(selb) atIndex:8]; [enc setBuffer:wb offset:ds4_gpu_tensor_offset(weights) atIndex:9];
                [enc setBuffer:enb offset:ds4_gpu_tensor_offset(entries) atIndex:10];
                [enc setBuffer:xpb offset:ds4_gpu_tensor_offset(xp) atIndex:12]; [enc setBuffer:xsb offset:ds4_gpu_tensor_offset(xs) atIndex:13];
                [enc useResource:gcb usage:MTLResourceUsageRead]; [enc useResource:ucb usage:MTLResourceUsageRead];   /* read through the address tables */
