                [enc setComputePipelineState:gx];
                [enc setBuffer:mb offset:ds4_gpu_tensor_offset(mid) atIndex:0]; [enc setBuffer:gxp offset:ds4_gpu_tensor_offset(g32d_xp) atIndex:1];
