}
static uint32_t pipeline_census_phase(void) { return __atomic_load_n(&timeline_phase, __ATOMIC_RELAXED); }   /* llms PIPE_CENSUS */
/* llms SPX2 instrument (apply_spx2.py): the accumulators the SP_LOG columns 8-15 difference per call */
void ds4_gpu_llms_spx(double *v) {
    v[0] = command_wait_ms; v[1] = load_wait_ms; v[2] = prefill_prefetch_wait_ms; v[3] = spx_sync_ms;
    v[4] = (double)prefill_prefetch_loads; v[5] = (double)aio_sync_batches; v[6] = (double)aio_sync_reads; v[7] = (double)prefill_prefetch_already_cached;
