/* llms HEAD_RS (apply_head_rs.py): the LM head's top candidates per row rescored from the GGUF's Q8_0 head rows, in the open batch */
enum { HEAD_RS_KMAX = 512, HEAD_RS_ROWS = 16 };
static id<MTLComputePipelineState> head_rs_select_ps, head_rs_dots_ps; static id<MTLBuffer> head_rs_idx; static id<MTLComputePipelineState> head_rs_par_ps[6]; static id<MTLBuffer> head_rs_scr, head_rs_thr;   /* llms HEAD_RS_PAR */ static int head_rs_state = -1, head_rs_canary; static uint64_t head_rs_calls, head_rs_rows;
static int head_rs_ready(void) {
    if (head_rs_state >= 0) return head_rs_state;
    head_rs_state = 0; if (!g_device) return 0;
    NSError *err = nil;
    id<MTLLibrary> lib = [g_device newLibraryWithSource:@"#include <metal_stdlib>\n"
    "using namespace metal;\n"
    "kernel void llms_head_rs_select(device const float *logits [[buffer(0)]], device uint *idx [[buffer(1)]], constant uint4 &a [[buffer(2)]],\n"
    "    uint tid [[thread_index_in_threadgroup]], uint row [[threadgroup_position_in_grid]], uint lane [[thread_index_in_simdgroup]], uint sg [[simdgroup_index_in_threadgroup]]) {\n"
    "  threadgroup float smax[32]; threadgroup atomic_uint hist[256]; threadgroup atomic_uint cnt; threadgroup float sthr;\n"
    "  device const float *L = logits + (ulong)row * a.w;\n"
    "  float m = -INFINITY;\n"
    "  for (uint i = tid; i < a.x; i += 1024u) m = max(m, L[i]);\n"
    "  m = simd_max(m); if (lane == 0u) smax[sg] = m;\n"
    "  if (tid < 256u) atomic_store_explicit(&hist[tid], 0u, memory_order_relaxed);\n"
    "  if (tid == 0u) atomic_store_explicit(&cnt, 0u, memory_order_relaxed);\n"
    "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
    "  if (sg == 0u) { float v = smax[lane]; v = simd_max(v); if (lane == 0u) smax[0] = v; }\n"
    "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
    "  const float M = smax[0];\n"
    "  for (uint i = tid; i < a.x; i += 1024u) { const float d = M - L[i]; if (d < 32.0f) atomic_fetch_add_explicit(&hist[min((uint)(d * 8.0f), 255u)], 1u, memory_order_relaxed); }\n"
    "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
    "  if (tid == 0u) { uint c = 0u, b = 0u; for (; b < 256u; b++) { c += atomic_load_explicit(&hist[b], memory_order_relaxed); if (c >= a.y) break; }\n"
    "                   sthr = b >= 256u ? 32.0f : (float)(b + 1u) * 0.125f; }\n"
    "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
    "  const float T = sthr;\n"
    "  for (uint i = tid; i < a.x; i += 1024u) { if (M - L[i] < T) { const uint s = atomic_fetch_add_explicit(&cnt, 1u, memory_order_relaxed); if (s < a.z) idx[(ulong)row * (a.z + 1u) + 1u + s] = i; } }\n"
    "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
    "  if (tid == 0u) idx[(ulong)row * (a.z + 1u)] = min(atomic_load_explicit(&cnt, memory_order_relaxed), a.z);\n"
    "}\n"
    "kernel void llms_head_rs_dots(device const uchar *W [[buffer(0)]], device const float *x [[buffer(1)]], device float *logits [[buffer(2)]], device const uint *idx [[buffer(3)]],\n"
    "    constant uint4 &a [[buffer(4)]], constant uint2 &c [[buffer(5)]],\n"
    "    uint gid [[simdgroup_index_in_threadgroup]], uint tg [[threadgroup_position_in_grid]], uint lane [[thread_index_in_simdgroup]]) {\n"
    "  const uint slot = tg * 8u + gid, row = slot / a.y, j = slot % a.y;\n"
    "  if (row >= a.w) return;\n"
    "  device const uint *I = idx + (ulong)row * (a.y + 1u);\n"
    "  if (j >= I[0]) return;\n"
    "  const uint v = I[1u + j], vr = c.x != 0u ? (v + 1u) % c.y : v;\n"
    "  const uint nb = a.x / 32u; device const uchar *R = W + (ulong)vr * nb * 34u;\n"
    "  device const float *X = x + (ulong)row * a.x;\n"
    "  float s = 0.0f;\n"
    "  for (uint b = lane; b < nb; b += 32u) {\n"
    "    device const uchar *blk = R + (ulong)b * 34u;\n"
    "    const float d = (float)(*(device const half *)blk);\n"
    "    device const char *q = (device const char *)(blk + 2);\n"
    "    device const float *xb = X + b * 32u;\n"
    "    float t = 0.0f;\n"
    "    for (uint k = 0u; k < 32u; k++) t += (float)q[k] * xb[k];\n"
    "    s += d * t;\n"
    "  }\n"
    "  s = simd_sum(s);\n"
    "  if (lane == 0u) logits[(ulong)row * a.z + v] = s;\n"
    "}\n"
    "" options:nil error:&err];
    id<MTLFunction> fs = lib ? [lib newFunctionWithName:@"llms_head_rs_select"] : nil, fd = lib ? [lib newFunctionWithName:@"llms_head_rs_dots"] : nil;
    head_rs_select_ps = fs ? [g_device newComputePipelineStateWithFunction:fs error:&err] : nil; head_rs_dots_ps = fd ? [g_device newComputePipelineStateWithFunction:fd error:&err] : nil;
    head_rs_idx = [g_device newBufferWithLength:(NSUInteger)HEAD_RS_ROWS * (HEAD_RS_KMAX + 1) * 4 options:MTLResourceStorageModePrivate];
    {   /* llms HEAD_RS_PAR (apply_head_rs_par.py): the select spread over 64 threadgroups per row */
        id<MTLLibrary> pl = [g_device newLibraryWithSource:@"#include <metal_stdlib>\n"
    "using namespace metal;\n"
    "static inline uint rs_key(float f) { const uint u = as_type<uint>(f); return (u & 0x80000000u) ? ~u : (u | 0x80000000u); }\n"
    "static inline float rs_unkey(uint k) { return as_type<float>((k & 0x80000000u) ? (k & 0x7fffffffu) : ~k); }\n"
    "kernel void llms_head_rs_zero(device uint *scr [[buffer(0)]], constant uint &rows [[buffer(1)]], uint t [[thread_position_in_grid]]) {\n"
    "  if (t < rows * 258u) scr[t] = 0u;   // per row: [0] max key, [1] count, [2..257] histogram\n"
    "}\n"
    "kernel void llms_head_rs_max(device const float *logits [[buffer(0)]], device atomic_uint *scr [[buffer(1)]], constant uint4 &a [[buffer(2)]],\n"
    "    uint2 tg [[threadgroup_position_in_grid]], uint tid [[thread_index_in_threadgroup]], uint lane [[thread_index_in_simdgroup]], uint sg [[simdgroup_index_in_threadgroup]]) {\n"
    "  threadgroup float sm[8];\n"
    "  const uint row = tg.y, c0 = tg.x * a.y, c1 = min(a.x, c0 + a.y); device const float *L = logits + (ulong)row * a.w;\n"
    "  float m = -INFINITY; for (uint i = c0 + tid; i < c1; i += 256u) m = max(m, L[i]);\n"
    "  m = simd_max(m); if (lane == 0u) sm[sg] = m;\n"
    "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
    "  if (tid == 0u) { float v = sm[0]; for (uint s = 1u; s < 8u; s++) v = max(v, sm[s]); atomic_fetch_max_explicit(&scr[row * 258u], rs_key(v), memory_order_relaxed); }\n"
    "}\n"
    "kernel void llms_head_rs_hist(device const float *logits [[buffer(0)]], device atomic_uint *scr [[buffer(1)]], constant uint4 &a [[buffer(2)]],\n"
    "    uint2 tg [[threadgroup_position_in_grid]], uint tid [[thread_index_in_threadgroup]]) {\n"
    "  threadgroup atomic_uint h[256];\n"
    "  const uint row = tg.y, c0 = tg.x * a.y, c1 = min(a.x, c0 + a.y); device const float *L = logits + (ulong)row * a.w;\n"
    "  atomic_store_explicit(&h[tid], 0u, memory_order_relaxed);\n"
    "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
    "  const float M = rs_unkey(atomic_load_explicit(&scr[row * 258u], memory_order_relaxed));\n"
    "  for (uint i = c0 + tid; i < c1; i += 256u) { const float d = M - L[i]; if (d < 32.0f) atomic_fetch_add_explicit(&h[min((uint)(d * 8.0f), 255u)], 1u, memory_order_relaxed); }\n"
    "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
    "  const uint v = atomic_load_explicit(&h[tid], memory_order_relaxed); if (v) atomic_fetch_add_explicit(&scr[row * 258u + 2u + tid], v, memory_order_relaxed);\n"
    "}\n"
    "kernel void llms_head_rs_thr(device uint *scr [[buffer(0)]], device float *thr [[buffer(1)]], constant uint4 &a [[buffer(2)]], uint row [[thread_position_in_grid]]) {\n"
    "  if (row >= a.z) return;\n"
    "  uint c = 0u, b = 0u; for (; b < 256u; b++) { c += scr[row * 258u + 2u + b]; if (c >= a.x) break; }\n"
    "  thr[row] = b >= 256u ? 32.0f : (float)(b + 1u) * 0.125f;\n"
    "}\n"
    "kernel void llms_head_rs_compact(device const float *logits [[buffer(0)]], device atomic_uint *scr [[buffer(1)]], device const float *thr [[buffer(2)]], device uint *idx [[buffer(3)]],\n"
    "    constant uint4 &a [[buffer(4)]], uint2 tg [[threadgroup_position_in_grid]], uint tid [[thread_index_in_threadgroup]]) {\n"
    "  const uint row = tg.y, c0 = tg.x * a.y, c1 = min(a.x, c0 + a.y); device const float *L = logits + (ulong)row * a.w;\n"
    "  const float M = rs_unkey(atomic_load_explicit(&scr[row * 258u], memory_order_relaxed)), T = thr[row];\n"
    "  for (uint i = c0 + tid; i < c1; i += 256u) { if (M - L[i] < T) { const uint s = atomic_fetch_add_explicit(&scr[row * 258u + 1u], 1u, memory_order_relaxed); if (s < a.z) idx[(ulong)row * (a.z + 1u) + 1u + s] = i; } }\n"
    "}\n"
    "kernel void llms_head_rs_count(device const uint *scr [[buffer(0)]], device uint *idx [[buffer(1)]], constant uint2 &a [[buffer(2)]], uint row [[thread_position_in_grid]]) {\n"
    "  if (row < a.y) idx[(ulong)row * (a.x + 1u)] = min(scr[row * 258u + 1u], a.x);\n"
    "}\n"
    "" options:nil error:&err];
        static const char *pn[6] = { "llms_head_rs_zero", "llms_head_rs_max", "llms_head_rs_hist", "llms_head_rs_thr", "llms_head_rs_compact", "llms_head_rs_count" };
        for (int i = 0; i < 6; i++) { id<MTLFunction> f = pl ? [pl newFunctionWithName:[NSString stringWithUTF8String:pn[i]]] : nil; head_rs_par_ps[i] = f ? [g_device newComputePipelineStateWithFunction:f error:&err] : nil; }
        head_rs_scr = [g_device newBufferWithLength:(NSUInteger)HEAD_RS_ROWS * 258 * 4 options:MTLResourceStorageModePrivate];
        head_rs_thr = [g_device newBufferWithLength:(NSUInteger)HEAD_RS_ROWS * 4 options:MTLResourceStorageModePrivate];
        for (int i = 0; i < 6; i++) if (!head_rs_par_ps[i]) { fprintf(stderr, "llms head rs: the parallel select did NOT compile (%s)\n", err ? err.localizedDescription.UTF8String : "?"); return 0; }
    }
    if (!head_rs_select_ps || !head_rs_dots_ps || !head_rs_idx) { fprintf(stderr, "llms head rs: NOT enabled (%s)\n", err ? err.localizedDescription.UTF8String : "allocation"); return 0; }
    { const char *e = getenv("LLMS_DS4_HEAD_RS_CANARY"); head_rs_canary = e && *e && *e != '0'; }
    fprintf(stderr, "llms: head rs (the head's top candidates per row rescored from the Q8_0 head rows%s)\n", head_rs_canary ? "; CANARY: from the NEXT row" : "");
    atexit_b(^{ fprintf(stderr, "llms head rs: %llu rescorings, %llu rows\n", (unsigned long long)head_rs_calls, (unsigned long long)head_rs_rows); });
    head_rs_state = 1; return 1;
}
int ds4_gpu_llms_head_rescore(ds4_gpu_tensor *logits, const ds4_gpu_tensor *x, uint32_t rows, uint32_t vocab, uint32_t dim, const void *model_map, uint64_t model_size, uint64_t head_offset, uint32_t k) {
    if (!head_rs_ready() || !g_batch_cb || !logits || !x || rows == 0u || rows > HEAD_RS_ROWS || (dim & 31u) || k == 0u || k > HEAD_RS_KMAX) return 0;
    if (ds4_gpu_tensor_bytes(logits) < (uint64_t)rows * vocab * sizeof(float) || ds4_gpu_tensor_bytes(x) < (uint64_t)rows * dim * sizeof(float)) return 0;
    uint64_t inner = 0; const uint64_t wbytes = (uint64_t)vocab * (dim / 32u) * 34u;
    if (head_offset > model_size || wbytes > model_size - head_offset) return 0;
    id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map, model_size, head_offset, wbytes, &inner);
    if (!wbuf) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(g_batch_cb);
    if (!enc) return 0;
    [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
    {   /* llms HEAD_RS_PAR: v1's rule (max, 256 bins of M - logit, the threshold, the compaction) in six dispatches of 64 chunks per row */
        const uint32_t C = 64u, chunk = (vocab + C - 1u) / C; id<MTLBuffer> lb = ds4_gpu_tensor_buffer(logits); const NSUInteger lo = ds4_gpu_tensor_offset(logits);
        const uint32_t nr = rows, ac[4] = { vocab, chunk, HEAD_RS_KMAX, vocab }, at[4] = { k, 0u, rows, 0u }, an[2] = { HEAD_RS_KMAX, rows };
        [enc setComputePipelineState:head_rs_par_ps[0]]; [enc setBuffer:head_rs_scr offset:0 atIndex:0]; [enc setBytes:&nr length:4 atIndex:1];
        [enc dispatchThreadgroups:MTLSizeMake((rows * 258u + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)]; [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        [enc setComputePipelineState:head_rs_par_ps[1]]; [enc setBuffer:lb offset:lo atIndex:0]; [enc setBuffer:head_rs_scr offset:0 atIndex:1]; [enc setBytes:ac length:sizeof ac atIndex:2];
        [enc dispatchThreadgroups:MTLSizeMake(C, rows, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)]; [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        [enc setComputePipelineState:head_rs_par_ps[2]]; [enc dispatchThreadgroups:MTLSizeMake(C, rows, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)]; [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        [enc setComputePipelineState:head_rs_par_ps[3]]; [enc setBuffer:head_rs_scr offset:0 atIndex:0]; [enc setBuffer:head_rs_thr offset:0 atIndex:1]; [enc setBytes:at length:sizeof at atIndex:2];
        [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)]; [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        [enc setComputePipelineState:head_rs_par_ps[4]]; [enc setBuffer:lb offset:lo atIndex:0]; [enc setBuffer:head_rs_scr offset:0 atIndex:1]; [enc setBuffer:head_rs_thr offset:0 atIndex:2];
        [enc setBuffer:head_rs_idx offset:0 atIndex:3]; [enc setBytes:ac length:sizeof ac atIndex:4];
        [enc dispatchThreadgroups:MTLSizeMake(C, rows, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)]; [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        [enc setComputePipelineState:head_rs_par_ps[5]]; [enc setBuffer:head_rs_scr offset:0 atIndex:0]; [enc setBuffer:head_rs_idx offset:0 atIndex:1]; [enc setBytes:an length:sizeof an atIndex:2];
        [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
    }
    [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
    [enc setComputePipelineState:head_rs_dots_ps];
    [enc setBuffer:wbuf offset:(NSUInteger)inner atIndex:0]; [enc setBuffer:ds4_gpu_tensor_buffer(x) offset:ds4_gpu_tensor_offset(x) atIndex:1];
    [enc setBuffer:ds4_gpu_tensor_buffer(logits) offset:ds4_gpu_tensor_offset(logits) atIndex:2]; [enc setBuffer:head_rs_idx offset:0 atIndex:3];
    const uint32_t a2[4] = { dim, HEAD_RS_KMAX, vocab, rows }; [enc setBytes:a2 length:sizeof a2 atIndex:4];
    const uint32_t c2[2] = { (uint32_t)head_rs_canary, vocab }; [enc setBytes:c2 length:sizeof c2 atIndex:5];
    [enc dispatchThreadgroups:MTLSizeMake((rows * HEAD_RS_KMAX + 7u) / 8u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
    head_rs_calls++; head_rs_rows += rows;
    return 1;
}

/* llms STEP_COV (11-05, the jitter-as-signal reading: the decode cycle's variation lives in the GPU-idle gaps and the step log carried no covariates): the cumulative host-side waits and install time, read at a step's entry by ds4.c's STEP_TS line when LLMS_DS4_STEP_COV is set. Off unless set; an INSTRUMENT. Columns: command_wait_ms (CPU blocked in command-buffer waits), load_wait_ms, expert load-install ms, mainwfe wait ms, ANE dense post wait ms, ANE oab wait ms, ANE engine wait ms, 0. */
void ds4_gpu_llms_step_wait_cov(double *o, int n) {
    const double v[8] = { command_wait_ms, load_wait_total(), g_stream_expert_timing_load_install_ms, mainwfe_wait_ms, ane_dense_post_wait_ms, ane_oab_wait_ms, ane_eng_wait_ms, 0.0 };
    for (int i = 0; i < n && i < 8; i++) o[i] = v[i];
}
